    REP(n)(i => res(i) = f(i + offset))
    res
  }

  def sumL(as: Array[Int]): Long = {
    var s = 0L
    REP(as.length)(i => s += as(i))
    s
  }
  def cumSum(as: Array[Int]): Array[Long] = {
    val cum = Array.ofDim[Long](as.length + 1)
    REP(as.length) { i =>
      cum(i + 1) = cum(i) + as(i)
    }
    cum
  }
}

object Workspace {
  import Main._
  import java.util.Arrays.sort

  import scala.collection.mutable
  import math.{abs, max, min}
  import mutable.ArrayBuffer
  case class Entry(v: Int, i: Int, flip: Boolean)
  def count(V: Array[Entry]): Int = {
    val ix = Array.ofDim[Int](V.length)
    REP(V.length) { i =>
      ix(i) = V(i).i
    }
    val bit = new BIT(V.length)
    var cnt = 0
    REP_r(V.length) { i =>
      cnt += bit.sum(ix(i))
      bit.add(ix(i), 1)
    }
    cnt
  }

  class BIT(n: Int, zero: Int)(f: (Int, Int) => Int) {
    def this(n: Int) = this(n, 0)(_ + _)

    private val N = {
      val a = Integer.highestOneBit(n)
      if (a == n) a else a << 1
    }
    private val bit = if (zero != 0) Array.fill[Int](N + 1)(zero) else Array.ofDim[Int](N + 1)

    /**
      * 1 index
      * addとindex違うよ
      * cumsumなんかといっしょ
      */
    def sum(i: Int): Int = {
      assert(i <= n)
      var x = i
      var s: Int = zero
      while(x > 0) {
        s = f(s, bit(x))
        x -= x & -x
      }
      s
    }

    /**
      * 0 index
      */
    def add(i: Int, a: Int): Unit = {
      assert(i < n)
      var x = i + 1
      while(x <= N) {
        bit(x) = f(bit(x), a)
        x += x & -x
      }
    }

    def sumAll: Int = sum(n)

    // A がLongとかじゃない場合はこれらを実装しないと下の奴らが使えない
    private def sub(a: Int, b: Int) = a - b
    private def lt(a: Int, b: Int) = a < b

    /**
      * [l, r)
      */
    def query(l: Int, r: Int): Int = {
      assert(r > l)
      sub(sum(r), sum(l))
    }

    def lowerBound(W: Int): Int = {
      var k = N
      var x = 0
      var w = W
      while(k > 0) {
        if (x + k <= N && lt(bit(x + k), w)) {
          w = sub(w, bit(x + k))
          x += k
        }
        k /= 2
      }
      math.min(n, x)
    }
  }
}

class Main(out: java.io.PrintWriter, sc: Main.InputReader) {
  import sc._
  import Main._
  import java.util.Arrays.sort

  import scala.collection.mutable
  import math.{abs, max, min}
  import mutable.ArrayBuffer
  import Workspace._

  // toIntとか+7とかするならvalにしろ
  final private[this] val MOD = 1000000007

  def solve(): Unit = {
    val N = ni()
    val A, B = na(N)
    val inf = 1e9.toInt
    var ans = inf
    REP(1 << N) { mask =>
      import java.util.Comparator
      val E = Array.ofDim[Entry](N)
      REP(N) { i =>
        val flip = (mask>>i&1) == 1
        val v = if (flip) B(i) else A(i)
        E(i) = Entry(v, i, flip)
      }
      sort(E, new Comparator[Entry] {
        override def compare(o1: Entry, o2: Entry): Int = Integer.compare(o1.v, o2.v)
      })
      var ok = true
      REP(N) { i =>
        ok &&= (i % 2 != E(i).i % 2) == E(i).flip
      }
      if (ok) {
        ans = min(ans, count(E))
      }
    }

    if (ans == inf) out.println(-1)
    else out.println(ans)
  }
