int N;
const int MAXN = 20;
const int big = MAXN*MAXN + 1;
int A[MAXN][2];
int dp[(1 << MAXN)][51][2];

int solve(int mask, int last, bool odd) {
	if (mask == 0) {
		return 0;
	}
	if (dp[mask][last][odd] >= 0) {
		return dp[mask][last][odd]; 
	}
	int best = big;	
	int count = 0;
	for (int i = 0; i < N; i++) {
		if (mask & (1 << i)) {
			int t = ((odd + i) % 2 ? A[i][1] : A[i][0]);
			if (t >= last) {
				int val = count + solve(mask ^ (1 << i), t, !odd);
				best = min(val, best);
			}
			count++;
		}
	}
	dp[mask][last][odd] = best;
	return best;
}

