int bubble(vector<int> &arr)
{
	int cnt = 0;

	for (int j = 0; j < arr.size(); j++)
		for (int i = 1; i < arr.size(); i++)
			if (arr[i - 1] > arr[i])
			{
				swap(arr[i - 1], arr[i]);
				cnt++;
			}

	return cnt;
}


void solve(istream &cin = std::cin, ostream &cout = std::cout)
{
	int n;

	cin >> n;

	vector<pair<int, int>> arr(n);

	for (auto &it : arr)
		cin >> it.first;
	for (auto &it : arr)
		cin >> it.second;

	for (int i = 1; i < arr.size(); i += 2)
		swap(arr[i].first, arr[i].second);

	const unsigned to = (1u << (unsigned) n);
	int ans = numeric_limits<int>::max();

	auto red = [&arr](int a, int b) {
		return tuple<int, int>{arr[a].first, a} < tuple<int, int>{arr[b].first, b};
	};
	auto blue = [&arr](int a, int b) {
		return tuple<int, int>{arr[a].second, a} < tuple<int, int>{arr[b].second, b};
	};

	for (unsigned mask = 0; mask < to; mask++)
		if (__builtin_popcount(mask) == arr.size() / 2)
		{
			vector<int> b, r;

			for (unsigned i = 0; i < n; i++)
				if (mask & (1u << i))
					b.push_back(i);
				else
					r.push_back(i);

			sort(b.begin(), b.end(), blue);
			sort(r.begin(), r.end(), red);

			bool good = true;

			for (int i = 0; good && i < b.size(); i++)
				good &= arr[r[i]].first <= arr[b[i]].second;
			for (int i = 1; good && i < r.size(); i++)
				good &= arr[b[i - 1]].second <= arr[r[i]].first;

			if (good)
			{
				vector<int> tmp;

				reverse(r.begin(), r.end());
				reverse(b.begin(), b.end());

				while (tmp.size() < arr.size())
				{
					tmp.push_back(r.back());
					r.pop_back();
					r.swap(b);
				}

				int cnt = bubble(tmp);

				ans = min(ans, cnt);
			}
		}

	if (ans == numeric_limits<int>::max())
		ans = -1;

	cout << ans << endl;
}


