const ll MAXN = 200000;
const ll INF = 1001001001;
const ll MOD = 1000000007;

ll N, ans=INF, tmp=0;
vector<ll> A, B, C, D;

void dfs(vector<ll> v, ll id, ll num) {
    if(id==N){
        ll ct = 0;
        for(int i=0;i<N;i++) {
            if(v[i]==1) ct++;
        }
        if(ct!=num) return;
        vector<pair<ll,ll>> oddv, evenv;
        vector<ll> G;
        for(int i=0;i<N;i++) {
            if(v[i]==0) evenv.push_back(make_pair(D[i],i));
            else oddv.push_back(make_pair(C[i],i));
        }
        sort(oddv.rbegin(),oddv.rend());
        sort(evenv.rbegin(),evenv.rend());
        tmp = 0;
        for(int i=0;i<N;i++) {
            if(i%2==0) {
                tmp += max(oddv.back().second-i,0LL);
                G.push_back(oddv.back().first);
                oddv.pop_back();
            }
            else {
                tmp += max(evenv.back().second-i,0LL);
                G.push_back(evenv.back().first);
                evenv.pop_back();
            }
        }
        for(int i=1;i<N;i++) {
            if(G[i]<G[i-1]) return;
        }
        ans = min(ans,tmp);
        return;
    }
    dfs(v, id+1, num);
    v[id] = 1;
    dfs(v, id+1, num);
    return;
}

