Int dfs(Int bitA, Int num){
  if(bitA == (1<<A.size())-1)return 0;
  if(used[bitA][num]++) return mem[bitA][num];

  Int res = INF;
  Int c = 0;
  Int x = __builtin_popcount(bitA)&1;
  Int rev = x;
  for(Int i=0;i<(Int)A.size();i++){
    if(bitA>>i&1) {rev = !rev; continue;}
    Int nnum = (rev + c)%2== 0? A[i].first:A[i].second;
    c++;
    //pr(c, bitA, num, nnum, A[i]);
    if(nnum < num) continue;
    Int nbitA = bitA | (1<<i);
    Int cost = dfs(nbitA, nnum) + c - 1;
    Min(res, cost);

  }

  return mem[bitA][num]= res;
}

