class SumSegTree {
private:

	int _sum(int a, int b, int k, int l, int r) {
		if (r <= a || b <= l)return 0;    // 交差しない
		if (a <= l && r <= b)return dat[k];   // a,l,r,bの順で完全に含まれる
		else {
			int s1 = _sum(a, b, 2 * k + 1, l, (l + r) / 2); // 左の子
			int s2 = _sum(a, b, 2 * k + 2, (l + r) / 2, r); // 右の子
			return s1 + s2;
		}
	}
public:
	int n, height;
	vector<int> dat;

	// 初期化（_nは最大要素数）
	SumSegTree(int _n) {
		n = 1;
		height = 1;
		while (n < _n) {
			n *= 2;
			height++;
		}
		dat = vector<int>(2 * n - 1, 0);
	}

	// 場所i(0-indexed)にxを足す
	void add(int i, int x) {
		i += n - 1; // i番目の葉ノードへ
		dat[i] += x;
		while (i > 0) { // 下から上がっていく
			i = (i - 1) / 2;
			dat[i] += x;
		}
	}

	// 区間[a,b)の総和。ノードk=[l,r)に着目している。
	int sum(int a, int b) {
		return _sum(a, b, 0, 0, n);
	}
};

ll tento(Array& a) {
	ll n = a.size();
	SumSegTree tree(60);
	ll res = 0;
	REP(i, n) {
		res += tree.sum(a[i] + 1, 51);
		tree.add(a[i], 1);
	}
	return res;
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	cout.tie(nullptr);

	ll n;
	cin >> n;
	Array a(n), b(n);
	REP(i, n) cin >> a[i];
	REP(i, n) cin >> b[i];

	Matrix dp((1LL << n) + 1, Array(60, INF));
	//dp[bit][i]：	bit->すでにそーとされたものは1(このとき左から順にソートしたものが入っている)
	//				i->ソートされた数字の中で最も大きい数字（なので次に入れる数字はこれ以上）
	//				val->その状態での現在の移動回数

	dp[0][0] = 0;//何もソートされていない状態

	REP(bit, (1LL << n)) {

		ll con = 0;//すでにソートしてある枚数
		REP(i, n) {
			if ((bit & (1LL << i)) != 0) con++;
		}

		vector<P> pos;
		ll pp = con;
		REP(i, n) {
			if ((bit & (1LL << i)) == 0) {
				pos.pb(mp(i, pp++));//もとの配列での位置＆ソートされたあとの今の位置
			}
		}

		REP(i, 51) {
			if (dp[bit][i] == INF) continue;
			for(auto p:pos) {
				//ソートされた次の一枚になるものを選別
				ll next;
				if (abs(p.first - con) % 2 == 0) {
					next = a[p.first];//差が偶数なら表
				}
				else {
					next = b[p.first];//差が奇数なら裏
				}

				if (next >= i) {
					//ソートされてある値の最大値以上であれば広義単調増加になるので遷移できる
					//遷移する際に、動かす枚数だけ、swap回数＋
					chmin(dp[bit | (1LL << p.first)][next], dp[bit][i] + abs(p.second - con));
				}
			}
		}

	}

	ll ans = INF;
	REP(i, 51) {
		chmin(ans, dp[(1LL << n) - 1][i]);//すべてソート済みの中で最も小さいもの
	}

	if (ans != INF) cout << ans << endl;
	else cout << -1 << endl;

	return 0;
}

