    cin >> n;
    vector<int> a(n),b(n),v(n);
    for(i = 0;i < n;i++) cin >> a[i];
    for(i = 0;i < n;i++) cin >> b[i];
    long long ans = -1;
    for(i = 0;i < (1<<n);i++){
        int sa = 0,sb = 0;
        for(j = 0;j < n;j++){
            if(i&(1<<j)){
                v[j] = a[j];
                sa++;
            }
            else{
                v[j] = b[j];
                sb++;
            }
        }
        if(sb%2) continue;
        sort(v.begin(),v.end());
        vector<int> used(n,-1);
        int ma = 0;
        for(j = 0;j < n;j++){
            int f = 0;
            if(i&(1<<j)){
                for(k = j%2;k < n;k+=2){
                    if(v[k] == a[j] && used[k] == -1){
                        used[k] = j;
                        f = 1;
                        break;
                    }
                }
            }
            else{
                for(k = (j+1)%2;k < n;k+=2){
                    if(v[k] == b[j] && used[k] == -1){
                        used[k] = j;
                        f = 1;
                        break;
                    }
                }
            }
            if(f == 0){
                ma = -1;
                break;
            }
        }
        if(ma == -1) continue;
        for(j = 0;j < n;j++){
            for(k = j+1;k < n;k++){
                if(used[j] > used[k]) ma++;
            }
        }
        if(ans == -1 || ma < ans){
            ans = ma;
        }
    }
