const int INF = sizeof(int) == sizeof(long long) ? 0x3f3f3f3f3f3f3f3fLL : 0x3f3f3f3f;
const int MOD =  (int)1e9 + 7;
const double EPS = 1e-9;

int N;
int X[20], Y[20];
int B[20];
vector<vector<int>> vs;

void func(int idx, int cnt)
{
	if (N - idx + cnt < N / 2)return;
	if (idx == N)
	{
		vector<int> v;
		rep(i, 0, N)
		{
			v.push_back(B[i]);
		}
		vs.push_back(v);
	}
	else
	{
		if (N - cnt - cnt > 1)
		{
			B[idx] = 1;
			func(idx + 1, cnt + 1);
		}
		B[idx] = 0;
		func(idx + 1, cnt);
	}
}

signed main()
{
	cin.tie(0);
	ios::sync_with_stdio(false);

	cin >> N;
	rep(i, 0, N)
	{
		cin >> X[i];
	}
	rep(i, 0, N)
	{
		cin >> Y[i];
	}

	func(0, 0);

	int ans = INF;
	for (auto v : vs)
	{
		vector<pii> odd, eve;
		rep(i, 0, N)
		{
			if (v[i] == 1)
			{
				if (i % 2 == 0)
				{
					odd.push_back(mp(Y[i], i));
				}
				else
				{
					odd.push_back(mp(X[i], i));
				}
			}
			else
			{
				if (i % 2 == 0)
				{
					eve.push_back(mp(X[i], i));
				}
				else
				{
					eve.push_back(mp(Y[i], i));
				}
			}
		}
		sort(all(odd));
		sort(all(eve));

		bool ok = true;
		rep(i, 0, N - 1)
		{
			if (i % 2 == 0)
			{
				if (eve[i / 2].first > odd[(i + 1) / 2].first)
				{
					ok = false;
				}
			}
			else
			{
				if (odd[i / 2].first > eve[(i + 1) / 2].first)
				{
					ok = false;
				}
			}
		}
		if (!ok)continue;
		int NP[20];
		rep(i, 0, SZ(eve))
		{
			NP[2 * i] = eve[i].second;
		}
		rep(i, 0, SZ(odd))
		{
			NP[2 * i + 1] = odd[i].second;
		}
		int res = 0;
		vector<int> tv;
		vector<int> ttv;
		rep(i, 0, N)
		{
			tv.push_back(i);
			ttv.push_back(i);
		}
		rep(i, 0, N)
		{
			while (ttv[i] != NP[i])
			{
				swap(ttv[tv[NP[i]]], ttv[tv[NP[i]] - 1]);
				tv[NP[i]]--;
				tv[NP[i] - 1]++;
				res++;
			}
		}
		chmin(ans, res);
	}

	if (ans == INF)
	{
		cout << -1 << endl;
	}
	else
	{
		cout << ans << endl;
	}

	return 0;
}

#include<iostream>
#include<algorithm>
using namespace std;
int main(){
	int N,A[18],B[18],k[18],k2[18],K[18],m[18],sum,pre,minL=10000;
	bool flag,can;
	cin>>N;
	for(int i=0;i<N;i++)cin>>A[i];
	for(int i=0;i<N;i++)cin>>B[i];
	for(int i=0;i<(1<<N);i++){
		pre=i;sum=0;
		for(int j=0;j<N;j++){
			m[j]=j;
			K[j]=pre%2;sum+=K[j];
			if(pre%2)k[j]=B[j];
			else k[j]=A[j];
			k2[j]=k[j];
			pre/=2;
		}
		if(sum%2)continue;
		sort(k2,k2+N);

		can=true;
		for(int j=0;j<N;j++){
			flag=false;
			for(int l=0;l<N;l++){
				flag |= (k[j]==k2[l] && (l-j+N*2)%2==K[j]);
			}
			can &= flag;
		}
		if(can==false)continue;
		sum=0;
		for(int j=0;j<N-1;j++){
			for(int l=0;l<N-j-1;l++){
				if(k[l]>k[l+1] || (k[l]==k[l+1]&&(m[l]-l+N*2)%2!=K[l])){
					swap(k[l],k[l+1]);
					swap(K[l],K[l+1]);
					swap(m[l],m[l+1]);
					sum++;
				}
			}
		}
		can=true;
		for(int j=0;j<N;j++){
			can &= (m[j]-j+N*2)%2==K[j];
		}
		if(!can)continue;
		minL=min(minL,sum);
	}
	if(minL==10000)cout<<-1;
	else cout<<minL;
	return 0;
}

