int dp[(1 << 18)][18];
bool possible[(1 << 18)][18];
int main(void){
    cin.tie(0);
    ios::sync_with_stdio(false);
    //cout << fixed << setprecision(20);
    int n;cin >> n;
    vector<pair<int,int> > a(n);
    for(int i = 0;i < n;i++)cin >> a[i].first;
    for(int i = 0;i < n;i++)cin >> a[i].second;


    dp[0][0] = 0;
    for(int mask = 0;mask < (1 << n);mask++){
        if(mask == 0){
            for(int i = 0;i < n;i++){
                dp[mask | (1 << i)][i] = 0;
                possible[mask | (1 << i)][i] = 1;
            }
        }else{
            for(int i = 0;i < n;i++){
                if(!(mask & (1<<i)))continue;
                for(int j = 0;j < n;j++){
                    if(mask & (1 << j))continue;
                    int sz = pop_count(mask);
                    int last,next;
                    if((i - (sz-1))%2==0){
                        last = a[i].first;
                    }else{
                        last = a[i].second;
                    }
                    if((j - sz)%2 ==0){
                        next = a[j].first;
                    }else{
                        next = a[j].second;
                    }
                    if(last > next or !possible[mask][i])continue;
                    else{
                        int cnt = 0;
                        for(int k = j+1;k < n;k++){
                            if(mask & (1 << k))cnt++;
                        }
                        possible[mask | (1 << j)][j] = 1;
                        dp[mask | (1 << j)][j] += dp[mask][i] + cnt;
                    }
                }
            }
        }
    }
    int ans = INT_MAX;
    for(int i = 0;i < n;i++){
        if(possible[(1 << n)-1][i]){
//            cout << i << ' ' << dp[(1 << n)-1][i] << '\n';
            ans = min(ans,dp[(1<<n)-1][i]);
        }
    }
    if(ans == INT_MAX)cout << -1 << '\n';
    else cout << ans << '\n';
    return 0;
}

