		oe[i]=oe[i^(i&-i)]^1;
	for(i=1;i<(1<<n);i++){
		if(i==(i&-i)){
			for(j=0;j<n;j++)
				if(i&(1<<j))f[i][j][0]=1;
			continue;
		}
		for(j=0;j<n;j++)
			if(i&(1<<j)){
				cnt=0;
				for(k=n-1;k>=0;k--)
					if(i&(1<<k)){
						if(k!=j&&a[k][oe[i]^(k&1)]>=a[j][oe[i]^(j&1)^1])
							f[i][k]|=f[i^(1<<k)][j]<<cnt;
						++cnt;
					}
