int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n;
    cin >> n;
    vector<int> a(n), b(n);
    for(int i = 0; i < n; i++) {
        cin >> a[i];
    }
    for(int i = 0; i < n; i++) {
        cin >> b[i];
    }
    dp[0][0] = 0;

    for(int bit = 0; bit < (1 << n); bit++) {
        // 今何枚並べているか
        int np = __builtin_popcount(bit);
        for(int k = 0; k <= 50; k++) {
            if(dp[bit][k] == INF) {
                continue;
            }
            int cost = 0;
            // 次に置くカードを決める
            for(int i = 0; i < n; i++) {
                // もしi番目のカードを既に使っていたらだめ
                if(bit & (1 << i)) {
                    continue;
                }
                // 位置の相対的な偶奇で表か裏かが決まる
                int next = (abs(i - np) % 2 == 0 ? a[i] : b[i]);
                // 次に置くカードによって広義単調増加になるならば更新
                if(next >= k) {
                    chmin(dp[bit | (1 << i)][next], dp[bit][k] + cost);
                }
                cost++;
            }
        }
    }
    int ans = INF;
    for(int i = 0; i <= 50; i++) {
        chmin(ans, dp[(1 << n) - 1][i]);
    }
    cout << (ans == INF ? -1 : ans) << endl;
