int main() {
    // cin.tie(0);
    // ios::sync_with_stdio(false);

    int N;
    cin >> N;
    vector<int> A(N), B(N);
    REP(i, N) { cin >> A.at(i); }
    REP(i, N) { cin >> B.at(i); }

    int ans = INF;
    int bit = 0;
    REP(bit, 1 << N) {
        vector<pair<int, int>> even, odd;
        int mask = 1;
        REP(i, N) {
            if (mask & bit) { // ビットが立てば裏
                if (i % 2 == 0) {
                    odd.push_back(make_pair(B[i], i));
                } else {
                    even.push_back(make_pair(B[i], i));
                }
            } else {
                if (i % 2 == 0) {
                    even.push_back(make_pair(A[i], i));
                } else {
                    odd.push_back(make_pair(A[i], i));
                }
            }
            mask = mask << 1;
        }

        // 遷移先が偶数になるものは (N + 1) / 2 枚、奇数は N / 2 枚
        if (!((even.size() == (N + 1) / 2) && (odd.size() == N / 2))) {
            continue;
        }

        // 偶奇で分けてソート
        sort(ALL(even));
        sort(ALL(odd));

        // 全体として広義単調増加か確認
        vector<pair<int, int>> whole;
        REP(i, N) {
            if (i % 2 == 0) {
                whole.push_back(even[i / 2]);
            } else {
                whole.push_back(odd[i / 2]);
            }
        }
        bool flag = false;
        REP(i, N - 1) {
            if (whole[i] > whole[i + 1]) {
                flag = true;
                break;
            }
        }
        if (flag) {
            continue;
        }

        // 転倒数の計算（もとの並び方に戻して計算する）
        int t = 0;
        for (int i = 0; i < N - 1; i++) {
            for (int j = 0; j < N - i - 1; j++) {
                if (whole[j].second > whole[j + 1].second) {
                    swap(whole[j], whole[j + 1]);
                    t++;
                }
            }
        }

        chmin(ans, t);
    }

    if (ans == INF) {
        cout << -1 << endl;
    } else {
        cout << ans << endl;
    }
    return 0;
}

