template<typename T=int> struct bit {//{{{
  int n;
  vector<T> dat;
  vector<T> raw;

  bit(int _n=0){ //{{{
    n = _n;
    dat = vector<T>(n);
    raw = vector<T>(n);
  } //}}}

  bit(vector<T> a){ // {{{
    n = (int)a.size();
    dat = vector<T>(n);
    raw = vector<T>(n);
    for(int i = 0; i<n; i++){
      add(i, a[i]);
      raw[i] = a[i];
    }
  } //}}}

  T sum(int i){ //{{{
    T s = 0;
    while(i >= 0){
      s += dat[i];
      i = (i & (i+1)) - 1;
    }
    return s;
  } //}}}

  T sum(int i, int j){ //{{{  [i, j]
    if(i > j) return 0;
    return sum(j) - sum(i-1);
  } //}}}

  void add(int i, T x){ //{{{
    raw[i] += x;
    while(i < n){
      dat[i] += x;
      i |= i+1;
    }
  } //}}}

  int lower_bound(T x){ // a[0]+...+a[ret] >= x{{{
    int ret = -1;
    int k = 1;
    while(2*k <= n) k <<= 1;
    for( ;k>0; k>>=1){
      if(ret+k < n && dat[ret+k] < x){
        x -= dat[ret+k];
        ret += k;
      }
    }
    return ret + 1;
  } //}}}

  friend ostream& operator<<(ostream &os, bit<T>& b){ //{{{
    os << endl << "  raw:" << b.raw << endl;
    vector<T> acum;
    rep(i, b.n){
      acum.pb(b.sum(i));
    }
    os << "  acm:" << acum << endl;
    return os;
  } //}}}
}; //}}}

