template<class V, int ME> class BIT {
public:
    V bit[1<<ME];
    V total(int e) {V s=0;e++;while(e) s+=bit[e-1],e-=e&-e; return s;}
    void update(int e, V val) {e++; while(e<=1<<ME) bit[e-1]+=val,e+=e&-e;}
};
BIT<int, 18> bi;
ll count_inversion(vector<int> &a, int s, int t){
    REP(i, 1<<18) bi.bit[i] = 0;
    ll res = 0;
    for(int i=t;i>s-1;i--){
        res+=bi.total(a[i]);
        bi.update(a[i], 1);
    }
    return res;
}

