using namespace std;

int A[20], B[20], bit[20];

void bitAdd(int n, int a){
	for(int i=n; i<20; i += i&(-i)){
		bit[i] += a;
	}
}

int bitSum(int n){
	int res=0;
	for(int i=n; i>0; i -= i&(-i)){
		res += bit[i];
	}
	return res;
}

int main() {
	int N;
	cin >> N;
	for(int i=1; i<=N; ++i) cin >> A[i];
	for(int i=1; i<=N; ++i) cin >> B[i];
	int ans=-1;
	for(int now=0; now<(1<<N); ++now){
		int cnt=0;
		for(int d=0; d<N; ++d){
			if(now&(1<<d)) ++cnt;
		}
		if(cnt==N/2){
			pair<int, int> ev[10], od[10];
			int k=0;
			for(int d=0; d<N; ++d){
				if(now&(1<<d)){
					if(d%2) od[k]=make_pair(A[d+1], d+1);
					else od[k]=make_pair(B[d+1], d+1);
					++k;
				}else{
					if(d%2) ev[d-k]=make_pair(B[d+1], d+1);
					else ev[d-k]=make_pair(A[d+1], d+1);
				}
			}
			sort(ev, ev+((N+1)/2));
			sort(od, od+(N/2));
			int sum=0, prev=0;
			bool flag=true;
			for(int i=0; i<20; ++i) bit[i]=0;
			for(int i=0; i<N; ++i){
				if(i%2==0){
					if(prev<=ev[i/2].first){
						prev=ev[i/2].first;
						bitAdd(ev[i/2].second, 1);
						sum += ev[i/2].second-bitSum(ev[i/2].second);
					}
					else flag=false;
				}else{
					if(prev<=od[i/2].first){
						prev=od[i/2].first;
						bitAdd(od[i/2].second, 1);
						sum += od[i/2].second-bitSum(od[i/2].second);
					}
					else flag=false;
				}
			}
			if(flag){
				if(ans<0) ans=sum;
				else ans=min(ans, sum);
			}
		}
	}
	cout << ans << endl;
