const int N=20,INF=1e9;
int a1[N],a2[N],n;
bool b[N];
struct node {
	int val,id;
	node(int v=0,int i=0):val(v),id(i){}
	bool operator<(const node &t) const{
		if(this->val==t.val)
			return this->id<t.id;
		return this->val<t.val;
	}
}c[N];
int solve() {
	for(int i=1;i<=n;i++)
		if(b[i])
			c[i]=node(a2[i],i);
		else
			c[i]=node(a1[i],i);
	sort(c+1,c+1+n);
	for(int i=1;i<=n;) {
		/*找下有多少个连续相等的*/
		int len=1;
		while(i+len<=n && c[i+len].val==c[i].val)
			len++;

		queue<int>q1,q2;
		for(int j=i;j<i+len;j++) {
			/*这个IF代表J的位置不对，需要修改*/
			if(abs(j-c[j].id+b[c[j].id])%2) {
				if(j&1)
					q1.push(j);
				else
					q2.push(j);
			}

		} 
		if(q1.size()!=q2.size()) return -1;
		while(!q1.empty())
			swap(c[q1.front()],c[q2.front()]),q1.pop(),q2.pop();
		i+=len;

	}

	/*求逆序对*/
	int ans=0;
	for(int i=1;i<=n;i++)
		for(int j=i+1;j<=n;j++) 
			if(c[i].id>c[j].id)
				ans++;
	return ans;
}
