int calc(const vector<int>&A, const vector<int>&B, int n, int s) {
    vector<int> C;
    vector<int> I;
    for (int i=0;i<n;++i) {
        // cout<<((s&(1<<i))>0)<<endl;
        if (s&(1<<i)) C.push_back(B[i]);
        else C.push_back(A[i]);
        I.push_back(i);
    }
    int ret = 0;
    for (int i=0;i<n;++i) {
        int mi = 100;
        int mid = -1;
        // cout<<"decide "<<i<<endl;
        for (int j=i;j<n;++j) {
            int ri = I[j];
            if (C[j]<mi) {
                mi = C[j];
                mid = -1;
                // cout<<"new max "<<mi<<endl;
            }
            if (((s&(1<<ri))>0)&&(i&1)||((s&(1<<ri))==0)&&((i&1)==0)) {
                if (C[j] == mi && mid==-1) {
                    // cout<<"new suit "<<j<<endl;
                    mid = j;
                }
            }
        }
        if (mid==-1) return n * n + 1;
        ret += mid - i;
        for (int j=mid;j>i;--j) {
            swap(C[j], C[j-1]);
            swap(I[j], I[j-1]);
        }
    }
    return ret;
}

