    for (int i = 0; i < (1 << n); i++) {
        vector <P> even, odd;
        for (int j = 0; j < n; j++) {
            // iのjビット目が立っていたら、j番目の数字はbが使われる
            if (i & (1 << j)) {
                if (j % 2 == 0) {
                    odd.push_back(P(b[j], j));
