                }
            } else {
                if (j % 2 == 0) {
                    even.push_back(P(a[j], j));
                } else {
                    odd.push_back(P(a[j], j));
                }
            }
        }

        int even_size = even.size();
        int odd_size = odd.size();
        if (even_size < odd_size || even_size > odd_size + 1) continue;

        sort(even.begin(), even.end());
        sort(odd.begin(), odd.end());

        bool check = true;
        int cur = 0;
        int count = 0;
        for (int j = 0; j < n; j++) {
            if (j % 2 == 0) {
                // check even
