                    check = false;
                    break;
                }

                cur = odd[j / 2].first;
                count += abs(odd[j / 2].second - j);
            }
        }

        if (check) {
            ans = min(ans, count);
        }
    }

    if (ans == MOD) {
        cout << -1 << '\n';
    } else {
        cout << ans / 2 << "\n";
    }
    return 0;
}

