int solve(vector<pii>& a, int mx) {
    if (a.size() == 1) {
        if (a[0].F <= mx) return 0;
        else return inf;
    }
    int n = a.size(), ans = inf;
    vector<pii> b;
    for (int i=0; i<n; i++) {
        for (int j=i+1; j<n; j++) {
            b.pb({a[j].S, a[j].F});
        }
        if (a[i].F <= mx && (n - 1 - i)%2 == 0) {
            ans = min(ans, solve(b, a[i].F) + (n - 1 - i));
        }
        if (a[i].S <= mx && (n - 1 - i)%2 == 1) {
            ans = min(ans, solve(b, a[i].S) + (n - 1 - i));
        }
        for (int j=i+1; j<n; j++) {
            b.pop_back();
        }
        b.pb(a[i]);
    }
    return ans;
}

