const int N = 18;
const int inf = 1e9 + 10;


int n;
int dp[1<<N][N]; // # of swaps if mask of cards placed, last card placed is i
int a[N], b[N];


// Build cards into prefix. The contribution total swaps will be count of inversions at time of swap.
// Use parity of distance to determine whether top/bottom of card is used.

int main() {
    ios_base::sync_with_stdio(false); cin.tie(0);  cout.tie(0);
    cin>>n;
    for (int i=0; i<n; i++) {
	cin>>a[i];
    }
    for (int i=0; i<n; i++) {
	cin>>b[i];
    }

    for (int mask=0; mask<1<<n; mask++) {
	for (int i=0; i<n; i++) {
	    dp[mask][i]=inf;    
	}
    }

    for (int i=0; i<n; i++) {
	dp[1<<i][i]=0;
    }

    for (int mask=1; mask<1<<n; mask++) {
	for (int i=0; i<n; i++) {
	    int pre = __builtin_popcount(mask);
	    // odd distance means card is flipped, even vice versa
	    int x = (i%2==(pre-1)%2 ? a[i] : b[i]);

	    for (int j=0; j<n; j++) {
		if (mask>>j&1) continue;
		int y = (j%2==pre%2 ? a[j] : b[j]);
		if (y<x) continue;

		// # of inversions with j: # of elems < y that have idx > j.
		int cost = dp[mask][i] + __builtin_popcount(mask>>j);
		relax(dp[mask|(1<<j)][j], cost);
	    }
	}
    }

    int res=inf;
    for (int i=0; i<n; i++) {
	relax(res, dp[(1<<n)-1][i]);
    }

    if (res==inf) res=-1;
    cout<<res<<endl;

    return 0;
}

