const int N = 18;
int a[N][2];
int dp[1 << N][N];
int n;

int solve(int mask, int last) {
  int len = __builtin_popcount(mask);
  if (len == n) return 0;
  int& ret = dp[mask][last];
  if (ret >= 0) return ret;
  ret = INF;
  for (int i = 0; i < n; ++i) {
    if (mask & (1 << i)) continue;
    int u = a[last][(last + len - 1) % 2];
    int v = a[i][(i + len) % 2];
    if (v < u) continue;
    int cnt = 0;
    for (int j = i + 1; j < n; ++j) {
      if (mask & (1 << j)) ++cnt;
    }
    ret = min(ret, cnt + solve(mask ^ (1 << i), i));
  }
  return ret;
}

int main() {
  scanf("%d", &n);
  for (int k = 0; k < 2; ++k) {
    for (int i = 0; i < n; ++i) {
      scanf("%d", &a[i][k]);
    }
  }
  int ret = INF;
  memset(dp, 255, sizeof(dp));
  for (int i = 0; i < n; ++i) {
    int cur = solve(1 << i, i);
    ret = min(ret, cur);
  }
  if (ret == INF) ret = -1;
  printf("%d\n", ret);
  return 0;
}

