void swapAndFilp(Card &c1, Card &c2)
{
	swap(c1.a, c1.b);
	swap(c2.a, c2.b);
	swap(c1, c2);
}

int f(int idx, vector<Card> V) // [idx ... N]을 알맞게 만드는 최소 연산 횟수
{
	if (idx == N)
	{
		V.push_back(C[idx]);
		for (int i = 1; i < N; i++)
		{
			if (V[i - 1].a > V[i].a) return 1e9;
		}
		V.pop_back();
		return 0;
	}
	int ret = 1e9;
	V.push_back(C[idx]);
	ret = min(ret, f(idx + 1, V));
	V.pop_back();

	V.push_back({ C[idx + 1].b, C[idx + 1].a });
	Card tmp = C[idx + 1];
	C[idx + 1] = { C[idx].b, C[idx].a };
	ret = min(ret, 1 + f(idx + 1, V));
	V.pop_back();
	C[idx + 1] = tmp;

	//printf("%d %d\n", idx, ret);
	return ret;
}


