// rolling hash hacking prevention + performant union by index
// https://stackoverflow.com/a/24678545
uint64_t map_integer(uint64_t value)
{
    static const uint64_t multiplier = 0x5DEECE66DL;
    static const uint64_t addend = 0xBL;
    static const uint64_t mask = (1L << 48) - 1;

    uint64_t seed = (value ^ multiplier) & mask;

    seed = (seed * multiplier + addend) & mask;
    seed = (seed * multiplier + addend) & mask;
    seed = (seed * multiplier + addend) & mask;

    return seed;
}

main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

#ifdef DUMPING_AN_UNREASONABLE_PARTNER
    freopen("no-brain-needed.inp", "r", stdin);
#endif

    int n;
    cin >> n;
    vector<int> A(n), B(n);

    for (int &x : A)
        cin >> x;
    for (int &x : B)
        cin >> x;

    int max_value = max(
        *max_element(A.begin(), A.end()),
        *max_element(B.begin(), B.end()));

    int final_result = inf;

    for (int mask = 0; mask < (1 << n); mask++)
    {
        ([&]() {
            vector<int> STATE(n);
            for (int i = 0; i < n; i++)
                if (mask & (1 << i))
                    STATE[i] = A[i];
                else
                    STATE[i] = B[i];

            vector<vector<int>> map_card_to_ranks(max_value + 1);

            {
                auto SORTED = STATE;
                sort(SORTED.begin(), SORTED.end());

                for (int i = 0; i < n; i++)
                    map_card_to_ranks[SORTED[i]].push_back(i);

                for (auto &ranks : map_card_to_ranks)
                    sort(ranks.begin(), ranks.end());
            }

            vector<int> final_indices;

            for (int i = 0; i < n; i++)
            {
                int j = *map_card_to_ranks[STATE[i]].begin();

                auto diff_parity = [](int a, int b) {
                    return (a ^ b) & 1;
                };

                auto same_parity = [](int a, int b) {
                    return (a ^ b ^ 1) & 1;
                };

                auto assign = [&map_card_to_ranks, &same_parity](int card, int index) {
                    auto &ranks = map_card_to_ranks[card];
                    auto it = lower_bound(ranks.begin(), ranks.end(), index);
                    for (; it != ranks.end(); ++it)
                    {
                        if (same_parity(*it, index))
                        {
                            int new_index = *it;
                            ranks.erase(it);
                            return new_index;
                        }
                    }
                    return -1ll;
                };

                int assigned_index = assign(STATE[i], j + (!!(mask & (1 << j)) ? diff_parity(i, j) : same_parity(i, j)));

                if (assigned_index == -1)
                    return;

                final_indices.push_back(assigned_index);
            }

            {
                int operation_count = 0;
                multiset<int> set;

                for (int index : final_indices)
                {
                    set.insert(index);
                    operation_count += distance(set.upper_bound(index), set.end());
                }

                final_result = min(final_result, operation_count);
            }
        })();
    }

    if (final_result == inf)
        cout << -1;
    else
        cout << final_result;
}

