	}
	for(i = 0; i < N; i++){
		scanf("%d", &B[i]);
	}
	int ans = inf;
	for(S = 0; S < (1 << N); S++){
		vector<pair<int, int>> V_eo(N);
		for(i = 0; i < N; i++){
			if((S | (1 << i)) == S){
				V_eo[i].first = B[i];
				V_eo[i].second = (i + 1) % 2;
			}
			else{
				V_eo[i].first = A[i];
				V_eo[i].second = i % 2;
			}
		}
		int f = 1;
		int now = inversion_number(V_eo.begin(), V_eo.end(), [](auto a, auto b){return a.first < b.first;});
		for(i = 0; i < N; i = j){
			for(j = i + 1; V_eo[j].first == V_eo[i].first; j++);
			int Ol[2] = {0, 0};
			vector<int> sub(j - i);
			for(k = i; k < j; k++){
				V_eo[k].second ^= (i % 2);
				sub[k - i] = 2 * Ol[V_eo[k].second] + V_eo[k].second;
				Ol[V_eo[k].second]++;
			}
			if(Ol[0] != (j - i + 1) / 2 || Ol[1] != (j - i) / 2){
				f = 0;
				break;
			}
			now += inversion_number(sub.begin(), sub.end(), [](auto a, auto b){return a < b;});
		}
		if(f == 1){
//			printf("now[%d] = %d\n", S, now);
			ans = min(ans, now);
		}
	}
	if(ans >= inf){
		i = 0;
		printf("%d\n", 10 / i);
		printf("-1\n");
	}
	else{
		printf("%d\n", ans);
	}
	return 0;
}

