int bnums[NBITS];
int dp[NBITS][MAX_N];

/* subroutines */

inline void setmin(int &a, int b) { if (a > b) a = b; }

inline int cs(int i, int p) {
  return ((i - p) & 1) ? bs[i] : as[i];
}

