int main() {
  int n;
  scanf("%d", &n);
  for (int i = 0; i < n; i++) scanf("%d", as + i);
  for (int i = 0; i < n; i++) scanf("%d", bs + i);

  int nbits = 1 << n;

  bnums[0] = 0;
  for (int bits = 1, msb = 1; bits < nbits; bits++) {
    if ((msb << 1) <= bits) msb <<= 1;
    bnums[bits] = bnums[bits ^ msb] + 1;
  }

  for (int bits = 0; bits < nbits; bits++)
    fill(dp[bits], dp[bits] + n, INF);
  for (int i = 0; i < n; i++) dp[1 << i][i] = 0;

  for (int bits = 0; bits < nbits; bits++) {
    int pi = bnums[bits] - 1, pj = pi + 1;
    for (int i = 0; i < n; i++)
      if (dp[bits][i] < INF) {
	int ci = cs(i, pi);
	for (int j = 0, bj = 1; j < n; j++, bj <<= 1)
	  if (! (bits & bj) && ci <= cs(j, pj))
	    setmin(dp[bits | bj][j], dp[bits][i] + bnums[bits & ~(bj - 1)]);
      }
  }

  int mind = INF;
  for (int i = 0; i < n; i++) setmin(mind, dp[nbits - 1][i]);

  printf("%d\n", (mind >= INF) ? -1 : mind);
  return 0;
}

