			if ((1 << i) & mask) {
				pick.emplace_back(v[1][i], 1);
			} else pick.emplace_back(v[0][i], 0);
		}
		t.clear();
		for (int i = 0; i < n; i++) {
			t.pb(pick[i].x);
		}
		sort(t.begin(), t.end());
		match = vector<int>(n, -1);
		used = vector<bool>(n, false);
		bool fail = false;
		int cur = 0;
		for (int i = 0; i < n; i++) {
			int closest = -1;
			for (int j = lower_bound(t.begin(), t.end(), pick[i].x) - t.begin();
				j < upper_bound(t.begin(), t.end(), pick[i].x) - t.begin(); j++) {
