lli bitCount(lli num){
    lli rtn = 0;
    while(num>0){
        rtn += num%2;
        num/=2;
    }
    return rtn;
}

 /* https://qiita.com/drken/items/1b7e6e459c24a83bb7fd */
template <class Abel> struct BIT {
    vector<Abel> dat;
    Abel UNITY_SUM = 0;                     // to be set

    /* [1, n] */
    BIT(lli n) { init(n); }
    void init(lli n) {
        dat.resize(n + 1);
        for (lli i = 0; i < (lli)dat.size(); ++i) dat[i] = UNITY_SUM;
    }

    /* a is 1-indexed */
    inline void add(lli a, Abel x) {
        for (lli i = a; i < (lli)dat.size(); i += i & -i)
            dat[i] = dat[i] + x;
    }

    /* [1, a], a is 1-indexed */
    inline Abel sum(lli a) {
        Abel res = UNITY_SUM;
        for (lli i = a; i > 0; i -= i & -i)
            res = res + dat[i];
        return res;
    }

    /* [a, b), a and b are 1-indexed */
    inline Abel sum(lli a, lli b) {
        return sum(b - 1) - sum(a - 1);
    }

    /* k-th number (k is 0-indexed) */
    lli get(long long k) {
        ++k;
        lli res = 0;
        lli N = 1; while (N < (lli)dat.size()) N *= 2;
        for (lli i = N / 2; i > 0; i /= 2) {
            if (res + i < (lli)dat.size() && dat[res + i] < k) {
                k = k - dat[res + i];
                res = res + i;
            }
        }
        return res + 1;
    }
};

void func(long long N, std::vector<long long> A, std::vector<long long> B){

    lli ans = INF;
    REP(bit,0,(1LL<<N)){
        //if(bitCount(bit)%2!=0)continue;
        vector<lli> c(N),d(N);
        vector<pair<lli,lli>> odd,even;
        REP(i,0,N){
            if(bit&(1LL<<i)){
                c[i] = B[i];
                if(i%2==0)odd.push_back({c[i],i});
                else even.push_back({c[i],i});
            }
            else {
                c[i] = A[i];
                if(i%2==0)even.push_back({c[i],i});
                else odd.push_back({c[i],i});
            }
            d[i] = c[i];
        }

        // 遷移先が偶数になるものは (N + 1) / 2 枚、奇数は N / 2 枚
        if (!((even.size() == (N + 1) / 2) && (odd.size() == N / 2))) {
            continue;
        }
        // 偶奇で分けてソート
        SORT(even);
        SORT(odd);
        // 全体として広義単調増加か確認
        vector<pair<int, int>> whole;
        REP(i,0, N) {
            if (i % 2 == 0) {
                whole.push_back(even[i / 2]);
            } else {
                whole.push_back(odd[i / 2]);
            }
        }
        bool flag = false;
        REP(i,0, N - 1) {
            if (whole[i].first > whole[i + 1].first) {
                flag = true;
                break;
            }
        }
        if (flag) {
            continue;
        }
        BIT<lli> bits(60);
        lli num = 0;
        REP(i,0,N){
            bits.add(d[i],1);
            num += i+1-bits.sum(d[i]);
        }
        chmin(ans, (lli)num);

    }

    if(ans == INF)cout<<-1<<endl;
    else cout<<ans<<endl;



}

int main(){
    // cout << fixed << setprecision(5);

    long long N;
