// 多次元 vector 生成
template <class T> vector<T> make_vec(size_t a) { return vector<T>(a); }
template <class T, class... Ts> auto make_vec(size_t a, Ts... ts) {
    return vector<decltype(make_vec<T>(ts...))>(a, make_vec<T>(ts...));
}
template <class T> bool chmax(T &a, const T &b) {
    if (a < b) {
        a = b;
        return 1;
    }
    return 0;
}
template <class T> bool chmin(T &a, const T &b) {
    if (b < a) {
        a = b;
        return 1;
    }
    return 0;
}
int main() {
    // cin.tie(0);
    // ios::sync_with_stdio(false);

    int N;
    cin >> N;
    vector<int> A(N), B(N);
    REP(i, N) { cin >> A.at(i); }
    REP(i, N) { cin >> B.at(i); }

    int ans = INF;
    int bit = 0;
    while (bit < 1 << N) {
        vector<int> use(N);
        int mask = 1;
        int sum = 0;
        REP(i, N) {
            if (mask & bit) { // ビットが立てば裏
                use[i] = B[i];
                sum++;
            } else {
                use[i] = A[i];
            }
            mask = mask << 1;
        }

        if (sum % 2 == 1) {
            bit++;
            continue;
        }

        // bubble
        vector<int> ind(N);
        REP(i, N) { ind[i] = i; }
        int t = 0;
        for (int i = 0; i < N - 1; i++) {
            for (int j = 0; j < N - i - 1; j++) {
                if (use[j] > use[j + 1]) { // 右隣が小さければ入れ替える
                    swap(use[j], use[j + 1]);
                    swap(ind[j], ind[j + 1]);
                    t++;
                }
            }
        }

        mask = 1;
        bool flag = false;
        REP(i, N) {
            if (mask & bit) { // ビットが立てば裏
                if (abs(ind[i] - i) % 2 == 0) {
                    flag = true;
                }
            } else {
                if (abs(ind[i] - i) % 2 == 1) {
                    flag = true;
                }
            }
            mask = mask << 1;
        }
        if (flag) {
            bit++;
            continue;
        }
        // cout << "bit:" << bit << " t:" << t << endl;
        chmin(ans, t);

        bit++;
    }

    if (ans == INF) {
        cout << -1 << endl;
    } else {
        cout << ans << endl;
    }
    return 0;
}

