const int N=20,INF=1e9;
int n;
int a[N],b[N];
int dp[1<<18][51];
int main(){
	n=read();
	For(i,0,n-1)
		a[i]=read();
	For(i,0,n-1)
		b[i]=read();
	For(i,0,(1<<n)-1)
		For(j,0,50)
			dp[i][j]=INF;
	dp[0][0]=0;
	For(i,0,(1<<n)-1){
