#include<bits/stdc++.h>
using namespace std;
int main(){
    int n;cin >> n;
    vector<int> a(n),b(n);
    for(int i=0;i<n;i++){
        cin >> a[i];
    }
    for(int i=0;i<n;i++){
        cin >> b[i];
    }
    vector<vector<int>> dp(1<<n,vector<int>(51,1e9));
    dp[0][0]=0;
    for(int i=0;i<(1<<n);i++){
        int t=0;
        for(int j=0;j<n;j++){
            if((i>>j)&1){
                t++;
            }
        }
        for(int j=0;j<n;j++){
            if((i>>j)&1){
                continue;
            }
            int p=0;
            for(int k=0;k<j;k++){
                if(!(i>>k)&1){
                    p++;
                }
            }
            for(int k=0;k<=50;k++){
                if(dp[i][k]==1e9){
                    continue;
                }
                if(abs(t-j)%2==0){
                    if(a[j]>=k){
                        dp[i|(1<<j)][a[j]]=min(dp[i|(1<<j)][a[j]],dp[i][k]+p);
                    }
                }
                else{
                    if(b[j]>=k){
                        dp[i|(1<<j)][b[j]]=min(dp[i|(1<<j)][b[j]],dp[i][k]+p);
                    }
                }
            }
        }
    }
    int ans=1e9;
    for(int i=0;i<=50;i++){
        ans=min(ans,dp[(1<<n)-1][i]);
    }
    if(ans==1e9){
        cout << -1 << endl;
    }
    else{
        cout << ans << endl;
    }
}

