#include<bits/stdc++.h>
#define ll long long int
#define M 1000000007
#define mod 998244353
#define mp(x,y) make_pair(x,y)
#define pb(x) push_back(x)
#define pi pair<ll,ll>
using namespace std;
const ll N=500010;

ll n;
vector<pi> ar;

ll dp[19][2][1<<19];

ll func(ll idx,int s,ll mask)
{
    if(mask==(1<<n)-1){return 0;}

    if(dp[idx][s][mask]==-1){
    ll ans=INT_MAX;
    ll count=0;
    for(ll i=0;i<n;++i){
        if((mask&(1<<i))!=0){++count;}
    }
    for(ll i=0;i<n;++i)
    {
        if((mask&(1<<i))==0)
        {
            ll cost=0;
            if(i>count){cost=i-count;}
            ll val=INT_MIN;
            if(count>0)
            {val=ar[idx].first;
            if(s){val=ar[idx].second;}
            }
            ll myval=ar[i].first;
            int ss=abs(i-count);
            if(ss%2==1){myval=ar[i].second;}
            if(val<=myval)
            {
                ans=min(ans,cost+func(i,ss%2,mask|(1<<i)));
            }
        }
    }
    dp[idx][s][mask]=ans;
    }
    return dp[idx][s][mask];
}

int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    cout.tie(NULL);

    cin>>n;
    ar.resize(n);
    for(ll i=0;i<n;++i){
        cin>>ar[i].first;
    }
    for(ll i=0;i<n;++i){
        cin>>ar[i].second;
    }

    memset(dp,-1,sizeof(dp));
    ll ans=func(n,0,0);
    if(ans==INT_MAX){ans=-1;}
    cout<<ans<<endl;

    return (0);
}

