int len,cards[MAXN][2],dp[1<<MAXN][MAXN][2];

int solve(int msk, int lst, int f){
    if(msk == (1<<len)-1) return 0;
    if(dp[msk][lst][f] != -1) return dp[msk][lst][f];
    vector<pii> v;
    int cnt = 0, res = INT_INF;
    for(int i=len-1; i>=0; i--){
        if(msk&(1<<i)) cnt++;
        else v.pb(mp(i,cnt%2));
    }
    reverse(all(v));
    for(int i=0; i<v.size(); i++){
        if(cards[v[i].first][(i%2)^v[i].second] >= cards[lst][f])
            res = min(res,solve(msk^(1<<v[i].first),v[i].first,(i%2)^v[i].second)+i);
    }
    return dp[msk][lst][f] = res;
}

