int main(){
    int n; cin >> n;
    vector<card> vc;
    rep(i, n){
        int a; cin >> a;
        vc.push_back(card{a, i, i % 2});
    }
    rep(i, n){
        int a; cin >> a;
        vc.push_back(card{a, i, (i+1) % 2});
    }
    sort(all(vc), [](card const& l, card const& r)->bool{
        if(l.val != r.val) return l.val < r.val;
        return l.oe < r.oe;
    });

    bool used[n]; int ans = 20;
    rep(i, n + 1){
        if(vc[i].oe == 1) continue;
        vector<int> prm; prm.push_back(vc[i].num);
        int count = 1;
        memset(used, false, sizeof(used)); used[vc[i].num] = true;

        for(int j = i + 1; j < 2*n; j++){
            if(count == n) break;
            if(!used[vc[j].num] && (vc[j].oe == count%2)){
                prm.push_back(vc[j].num);
                count++;
                used[vc[j].num] = true;
                if(count % 2 == 1){
                    sort(all(vc), [](card const& l, card const& r)->bool{ if(l.val != r.val) return l.val < r.val; return l.oe < r.oe; });    
                }
                else{
                    sort(all(vc), [](card const& l, card const& r)->bool{ if(l.val != r.val) return l.val < r.val; return l.oe > r.oe; });
                }
            }
        }
        if(count == n){
            ans = min(ans, min_swap(prm));
        }
    }

    if(ans == 20) ans = -1;
    cout << ans << endl;
}

