void solve() {
  int n;
  cin >> n;
  vi32 a(n), b(n);
  cin >> a >> b;
  rep(i, n) a[i]--, b[i]--;
  vector<vi32> dp(50, vi32(bit32(n), 1e9));
  dp[0][0] = 0;
  rep(s, bit32(n)) rep(i, 50) {
    if (dp[i][s] == 1e9) continue;
    int c = __builtin_popcount(s);
    rep(j, n) {
      if (s & bit32(j)) continue;
      int now = (c % 2 == j % 2) ? a[j] : b[j];
      if (i > now) continue;
      int f = j + __builtin_popcount(s & ((bit32(n) - 1) ^ (bit32(j) - 1)));
      amin(dp[now][s | bit32(j)], dp[i][s] + f - c);
    }
  }
  int ans = 1e9;
  rep(i, 50) amin(ans, dp[i][bit32(n) - 1]);
  if (ans == 1e9) ans = -1;
  cout << ans << endl;
}

