int f(vector<int> &v, int k = 0) {
    if (k == n) {
        vector<pair<int, int>> b, c;
        for (int i = 0; i < n; i++) {
            if (v[i] == 0) {
                if ((i & 1) == 0) {
                    b.push_back({a[i].first,i});
                }
                else {
                    c.push_back({a[i].first,i});
                }
            }
            else {
                if ((i & 1) == 1) {
                    b.push_back({a[i].second,i});
                }
                else {
                    c.push_back({a[i].second,i});
                }
            }
        }
        if (b.size() != (n + 1) / 2 || c.size() != n / 2) {
            return INF;
        }
        stable_sort(b.begin(), b.end(), [](pair<int, int> x, pair<int, int> y) {
            return x.first < y.first;
        });
        stable_sort(c.begin(), c.end(), [](pair<int, int> x, pair<int, int> y) {
            return x.first < y.first;
        });
        for (int i = 0; i < n / 2; i++) {
            if (b[i].first > c[i].first) {
                return INF;
            }
            else if (i + 1 < b.size() && c[i].first > b[i + 1].first) {
                return INF;
            }
        }
        vector<int> u(n);
        for (int i = 0; i < (n + 1) / 2; i++) {
            u[b[i].second] = 2 * i;
        }
        for (int i = 0; i < n / 2; i++) {
            u[c[i].second] = 2 * i + 1;
        }
        int cnt = 0;
        for (int i = 0; i < n - 1; i++) {
            for (int j = i; j < n - 1; j++) {
                if (u[i] > u[i + 1]) {
                    cnt++;
                    swap(u[i], u[i + 1]);
                }
            }
        }
        return cnt;
    }
    else {
        int res = INF;
        v[k] = 0;
        res = min(res, f(v, k + 1));
        v[k] = 1;
        res = min(res, f(v, k + 1));
        return res;
    }
}

