    int k = 9;
    int ans = -1;
    auto C = vector<int>(N);
    foreach_comb(N, k, [&](int *ind) {
        auto f = vector<int>(N,0);
        for(int i=0; i<N; i++) {
            f[ind[i]] = 1;
        }

        loop(i, N) {
            if ((f[i] - i) % 2) {
                C[i] = B[i];
            } else {
                C[i] = A[i];
            }
        }

        std::vector<size_t> indices(C.size());
        std::iota(indices.begin(), indices.end(), 0);
        std::sort(indices.begin(), indices.end(), [&C](size_t i1, size_t i2) {
            return C[i1] < C[i2];
        });

        int suc = 1;
        loop(i, N) {
            if ((f[i] - indices[i]) % 2) {
                suc = 0;
                break;
            }
        }

        if (suc) {
            int a = 0;
            loop(i, N) {
                for(int j=i+1; j<N; j++) {
                    if (indices[j] < indices[i]) {
                        a ++;
                    }
                }
            }
            if (ans < 0 || a < ans) {
                ans = a;
            }
