int main(){
	ll n; cin >> n;
	vl a(n),b(n);
	rep(i,n) cin >> a[i];
	rep(i,n) cin >> b[i];
	rep(i,n) if(i&1) swap(a[i],b[i]);
	ll ans = inf;
	rep(bit,1<<n){
		ll cnt = 0;
		rep(i,n) if(bit>>i & 1) cnt++;
		if((n+1)/2!=cnt) continue;
		vpl ev,od;
		rep(i,n){
			if(bit>>i & 1) od.emplace_back(a[i],i);
			else ev.emplace_back(b[i],i);
		}
		sort(all(od)), sort(all(ev));
		vl v;
		bool flag = true;
		rep(i,n/2){
			if(ev[i].first < od[i].first){
				flag = false;
				break;
			}
			if(n&1 || i<n/2-1){
				if(ev[i].first > od[i+1].first){
					flag = false;
					break;
				}
			}
			v.push_back(od[i].second); v.push_back(ev[i].second);
		}
		if(n&1) v.push_back(od.back().second);
		if(!flag) continue;
		cnt = 0;
		rep(i,n-1){
			REP(j,i+1,n){
				if(v[i]>v[j]) cnt++;
			}
		}
		chmin(ans,cnt);
	}
	if(ans==inf) puts("-1");
	else cout << ans << endl;
}

