// n個の中からk個選ぶ 0~n-1 bitで表現 n<=18 k<=n
vector<ll> combination(ll n,ll k){
	vector<ll> ans;
	ll x = (1LL<<k)-1;
	ll f = x<<(n-k);
	while(1){
		ans.push_back(x);
		if(x==f)return ans;
		x += x&-x;
		ll pcount = bitset<64>(x).count();
		x|=(1LL<<(k-pcount))-1;
	}
}

int main(){
	int N,n,ans=-1;
	cin >> N;
	n = N/2;
	if(N==1){
		cout << 0 << endl;
		return 0;
	}
	vector<int> A(N),B(N);
	for(int i=0;i<N;i++) cin >> A[i];
	for(int i=0;i<N;i++) cin >> B[i];
	for(int ch=0; ch<=n; ch++){
		auto chodd = combination( n,ch );
		auto cheve = combination( N-n,ch );
		for(auto odds : chodd){
			for(auto eves : cheve){
				vector<pair<int,int>> odd,eve;
				for(int i=0;i<n;i++){
					if(odds&(1<<i)){
						eve.push_back({B[2*i+1],2*i+1});
					}else{
						odd.push_back({A[2*i+1],2*i+1});
					}
				}
				for(int i=0;i<N-n;i++){
					if(eves&(1<<i)){
						odd.push_back({B[2*i],2*i});
					}else{
						eve.push_back({A[2*i],2*i});
					}
				}
				sort(odd.begin(), odd.end());
				sort(eve.begin(), eve.end());
				vector<int> to_ind,value;
				for(int i=0;i<n;i++){
					value.push_back(eve[i].first);
					to_ind.push_back(eve[i].second);
					value.push_back(odd[i].first);
					to_ind.push_back(odd[i].second);
				}
				if(N&1){
					value.push_back(eve[n].first);
					to_ind.push_back(eve[n].second);
				}
				bool none = false;
				for(int i=0;i<N-1;i++) if(value[i]>value[i+1]) none = true;
				if(none) continue;
				int cnt = 0;
				set<int> se;
				for(int i=0;i<N;i++)se.insert(i);
				for(int i=0;i<N;i++){
					auto ind = se.lower_bound(to_ind[i]);
					int indc = 0;
					auto ite = se.begin();
					while(ite!=ind){ite++;indc++;}
					cnt += indc;
					se.erase(to_ind[i]);
				}
				if(ans==-1) ans = cnt;
				ans = min(ans,cnt);
			}
		}
	}
	cout << ans << endl;
}

