int n;
int ab[18][2];

int solve(int mask) {
	vector<pair<int, bool>> q(n);
	for (int i = 0; i < n; i++) {
		bool k = mask & 1<<i;
		q[i] = {ab[i][k], k};
	}
	int cnt = 0;
	while (true) {
		bool done = true;
		for (int i = 1; i < n; i++) {
			if (q[i-1].first > q[i].first) {
				swap(q[i-1], q[i]);
				q[i-1].second = !q[i-1].second;
				q[i].second = !q[i].second;
				cnt++;
				done = false;
			}
		}
		if (done) {
			break;
		}
	}
	for (int i = 1; i < n; i++) {
		if (q[i-1].first == q[i].first && q[i-1].second && q[i].second) {
			q[i-1].second = false;
			q[i].second = false;
			cnt++;
		}
	}
	for (int i = 0; i < n; i++) {
		if (q[i].second) {
			return 1e9;
		}
	}
	return cnt;
}

int main() {
	cin >> n;
	for (int k = 0; k < 2; k++) {
		for (int i = 0; i < n; i++) {
			cin >> ab[i][k];
		}
	}

	int ans = 1e9;
	for (int mask = 0; mask < 1<<n; mask++) {
		ans = min(ans, solve(mask));
	}
	cout << (ans < 1e9 ? ans : -1) << endl;
	return 0;
}

