int main() {
	ll n;
	cin >> n;
	vll a, b;
	a = vin(n);
	b = vin(n);
	ll lim = POW(2, 18);
	using t = pair<pair<ll, ll>, ll>;
	ll res = dekai;

	rep(bit, lim) {
		bitset<18> bise = bit;
		V<t> h, g;
		rep(i, n) {
			t e;
			if(~bise[i]) {
				e = {{a[i], i}, 0};
			} else {
				e = {{b[i], i}, 1};
			}
			if((e.second + e.first.second) % 2 == 0) {
				h.push_back(e);
			} else {
				g.push_back(e);
			}
		}
		if(g.size() != n / 2) continue;
		sort(all(h));
		sort(all(g));
		vector<t> v;
		rep(i, n / 2) {
			v.push_back(h[i]);
			v.push_back(g[i]);
		}
		if(n & 1) v.push_back(h[n / 2]);
		bool f = 1;
		rep(i, n - 1) {
			if(v[i].first.first > v[i + 1].first.first) {
				f = 0;
				break;
			}
		}
		if(!f) continue;
		vll vec(n);
		rep(i, n) vec[i] = v[i].first.second;
		auto w = vec;
		ll cnt = 0;
		rep(i, n - 1) {
			rep(j, n - 1 - i) {
				if(vec[j] > vec[j + 1]) {
					cnt++;
					swap(vec[j], vec[j + 1]);
				}
			}
		}
		if(chmin(res, cnt)) {
			//cout << bits(bit, n) << " " << res << endl;
			//vout(w);
		}
	}
	if(res == dekai) res = -1;
	cout << res << endl;
}

