int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int N; cin >> N;
    vector<int> A(N),B(N);
    rep(i,N) cin >> A[i];
    rep(i,N) cin >> B[i];

    //rep(i,N) if (i%2==1) swap(A[i],B[i]);
    vector<int> C(N,1);
    rep (i,N/2) C[i] = 0;
    int ans = INF;
    do {
        int cnt = 0;
        vector<pii> P,Q;
        rep(i,N) {
            if (C[i]) {
                if (i%2==0) P.emplace_back(A[i],i);
                else P.emplace_back(B[i],i);
            } else {
                if (i%2==1) Q.emplace_back(A[i],i);
                else Q.emplace_back(B[i],i);
            }
        }
        sort(all(P)); sort(all(Q));
        bool ok = true;
        rep(i,N-1) {
            if (i%2==0) {
                if (P[i/2].first>Q[i/2].first) ok = false;
            } else {
                if (Q[i/2].first>P[i/2+1].first) ok = false;
            }
        }
        if (ok) {
            for (int i = 0; i < N; i +=2) {
                int k = i/2;
                cnt += abs(P[k].second-i);
            }
            for (int i = 1; i < N; i +=2) {
                int k = i/2;
                cnt += abs(Q[k].second-i);
            }
            chmin(ans,cnt);
        }
    } while (next_permutation(all(C)));

    if (ans == INF) cout << -1 << endl;
    else cout << ans/2 << endl;
}

