int main(){
    scan(n);
    if(n == 1){
        puts("0");
        return 0;
    }
    a.resize(n);
    b.resize(n);
    for(int i = 0; i < n; i++)
        scan(a[i]);
    for(int i = 0; i < n; i++)
        scan(b[i]);
