    for(int i = 0; i < (1<<(n-1)); i++){
        a = ina, b = inb;
        for(int j = 0; j < n; j++){
            if(i&(1<<j)){
                swap(a[j], b[j+1]);
                swap(b[j], a[j+1]);
            }
        }
