#define ALL(a)  (a).begin(),(a).end()
#define mp(a,b) make_pair((a),(b)) 

void recursive_comb(int *indexes, int s, int rest, std::function<void(int *)> f) {
  if (rest == 0) {
    f(indexes);
  } else {
    if (s < 0) return;
    recursive_comb(indexes, s - 1, rest, f);
    indexes[rest - 1] = s;
    recursive_comb(indexes, s - 1, rest - 1, f);
  }
}

// nCkの組み合わせに対して処理を実行する
void foreach_comb(int n, int k, std::function<void(int *)> f) {
  int indexes[k];
  recursive_comb(indexes, n - 1, k, f);
}



void Main(){
    int n;cin>>n;
    int ans=1679616;
    vector<int> a(n);
    For(i,0,n) cin>>a[i];
    vector<int> b(n);
    For(i,0,n) cin>>b[i];
    foreach_comb(n, n/2, [&n,&a,&b,&ans](int *indexes) {//1,3,5…番目(0-indexed)のものを列挙する
        vector<pair<int,int>> odd,even,init;
        vector<bool> used(n,false);
        For(i,0,n/2) {//1,3,5…番目
            if(indexes[i]%2==1) odd.push_back(mp(a[indexes[i]],indexes[i]));
            else odd.push_back(mp(b[indexes[i]],indexes[i]));
            used[indexes[i]]=true;
        }
        For(i,0,n){//0,2,4…番目
            if(used[i]==false){
                if(i%2==0) {
                    even.push_back(mp(a[i],i));
                    init.push_back(mp(a[i],i));
                }
                else {
                    even.push_back(mp(b[i],i));
                    init.push_back(mp(b[i],i));
                }
            }
            else{
                if(i%2==0) {
                    init.push_back(mp(b[i],i));
                }
                else {
                    init.push_back(mp(a[i],i));
                }
            }
        }
        sort(ALL(odd));
        sort(ALL(even));
        int m=0;
        bool flag=true;
        For(i,0,n/2){
            if(m>even[i].first){
                flag=false;
                break;
            }
            m=even[i].first;
            if(m>odd[i].first){
                flag=false;
                break;
            }
            m=odd[i].first;
        }
        if(n%2){
            if(m>even[even.size()-1].first){
                flag=false;
            }
        }
        if(flag){
            /*For(i,0,n) cout<<init[i].first<<" ";
            cout<<endl;*/
            int cnt=0;
            For(i,0,n){
                for(int j=n-1;j>i;j--){
                    if(init[j-1].first>init[j].first){
                        pair<int,int> t=init[j-1];
                        init[j-1]=init[j];
                        init[j]=t;
                        cnt++;
                    }
                }
            }
            int left=0,now=init[0].first;
            For(i,1,n){
                if(now==init[i].first) continue;
                else{
                    int right=i-1,cnt2=0;
                    if(left<right){
                        For(j,left,right+1){
                            if(used[init[j].second]^(j%2==0)==true) cnt2++;
                        }
                        cnt+=cnt2/(right-left);
                    }
                    left=i;
                    now=init[i].first;
                }
            }
            //cout<<cnt<<endl;
            ans=min(ans,cnt);
        }
    });
    if(ans>1600000) ans=-1;
    cout<<ans<<endl;    
}
