int dp[1<<18][18];

void solve() {
    int n; cin >> n;
    vector<int> A(n), B(n);
    rep (i, n) cin >> A[i];
    rep (i, n) cin >> B[i];

    rep (i, 1<<18) rep (j, 18) dp[i][j] = INF;
    dp[0][0] = 0;
    rep (bit, 1<<n) {
        rep (last, n) {
            bool f = __builtin_popcount(bit) % 2;
            rep (nxt, n) {
                if ((bit >> nxt) & 1) continue;
                int card = (f==nxt%2 ? A[nxt] : B[nxt]);
                int prev = 0;
                if (bit != 0) prev = (f!=last%2 ? A[last] : B[last]);
                if (prev <= card) {
                    int tugi = dp[bit][last];
                    FOR (i, nxt, n) {
                        if ((bit >> i) & 1) tugi++;
                    }
                    chmin(dp[bit | 1 << nxt][nxt], tugi);
                }
            }
        }
    }
    int ans = INF;
    rep (i, n) chmin(ans, dp[(1<<n)-1][i]);
    if (ans == INF) cout << -1 << endl;
    else cout << ans << endl;
}

