using namespace std;
typedef pair<int, int> P;
const int mod = 1000000007;
const int INF = 1e9;

int dp[1 << 18][18];

signed main(){
	cin.tie(nullptr);
	ios::sync_with_stdio(false);
	int n;
	cin >> n;
	vector<int> a(n), b(n);
	rep(i, 0, n) cin >> a[i];
	rep(i, 0, n) cin >> b[i];
	rep(i, 0, 1 << n) rep(j, 0, n) dp[i][j] = INF;
	rep(i, 0, n) dp[1 << i][i] = i;
	for(int mask = 0; mask < (1 << n); mask++){
		int c = __builtin_popcountll(mask);
		for(int i = 0; i < n; i++){
			if(dp[mask][i] == INF) continue;
			if(mask & (1 << i)){
				for(int j = 0; j < n; j++){
					if(mask & (1 << j)) continue;
					int pre = ((c - 1) % 2 == i % 2 ? a[i] : b[i]);
					int nxt = (c % 2 == j % 2 ? a[j] : b[j]);
					if(pre <= nxt){
						dp[mask | (1 << j)][j] = min(dp[mask | (1 << j)][j], dp[mask][i] + abs(c - j));
					}
				}
			}
		}
	}
	int ans = INF;
	rep(i, 0, n) ans = min(ans, dp[(1 << n) - 1][i] / 2);
	if(ans >= INF / 2) ans = -1;
	cout << ans << endl;
}

