#include <bits/stdc++.h>
using namespace std;
class rolling_hash{
public:
    constexpr static uint64_t mod = (1ULL << 61) - 1;
    constexpr static uint64_t mask31 = (1ULL << 31) - 1;
    constexpr static uint64_t mask30 = (1ULL << 30) - 1;
    static uint64_t base[2];
    std::vector<uint64_t> hash[2], bpow[2];

    uint64_t mul(uint64_t a, uint64_t b) const noexcept{
        uint64_t ah = a >> 31, al = a & mask31;
        uint64_t bh = b >> 31, bl = b & mask31;
        uint64_t mid = ah * bl + al * bh;
        uint64_t mh = mid >> 30, ml = mid & mask30;
        return 2 * ah * bh + mh + (ml << 31) + al * bl;
    }
    uint64_t rem(uint64_t x) const noexcept{
        x = (x & mod) + (x >> 61);
        return x < mod ? x : x - mod;
    }

    rolling_hash(): bpow{{1}, {1}} {
        if(base[0] == 0){
            std::mt19937_64 mt(rand());
            std::uniform_int_distribution<uint64_t> dist(3, mod-1);
            base[0] = dist(mt);
            base[1] = dist(mt);
        }
    }
    void push_back(char c){
        if(hash[0].size() == 0){
            hash[0].push_back(c);
            hash[1].push_back(c);
        }else{
            hash[0].push_back(rem(mul(hash[0].back(), base[0]) + c));
            hash[1].push_back(rem(mul(hash[1].back(), base[1]) + c));
        }
        bpow[0].push_back(rem(mul(bpow[0].back(), base[0])));
        bpow[1].push_back(rem(mul(bpow[1].back(), base[1])));
    }
    void push_back(std::string s){
        size_t n = hash[0].size() + s.size();
        hash[0].reserve(n);
        hash[1].reserve(n);
        bpow[0].reserve(n + 1);
        bpow[1].reserve(n + 1);
        for(char c: s) push_back(c);
    }
    std::pair<uint64_t, uint64_t> operator[](size_t i) const noexcept{
        return {hash[0][i], hash[1][i]};
    }
    std::pair<uint64_t, uint64_t> operator[](std::pair<size_t, size_t> r) const noexcept{
        if(r.first == 0) return operator[](r.second - 1);
        uint64_t h0 = rem(hash[0][r.second-1] + 3 * mod - mul(hash[0][r.first-1], bpow[0][r.second - r.first]));
        uint64_t h1 = rem(hash[1][r.second-1] + 3 * mod - mul(hash[1][r.first-1], bpow[1][r.second - r.first]));
        return {h0, h1};
    }
};
uint64_t rolling_hash::base[2];

int main(){
    int n;
    string s = "                                    ";
    for(int i=0;i<36;++i) s[i] = 0;
    cin >> n;
    for(int i=0;i<n;++i){ int x; cin >> x; s[i] = x; }
    for(int i=0;i<n;++i){ int x; cin >> x; s[i+18] = x; }

    unordered_set<uint64_t> checked;
    queue<pair<string, int>> q;
    q.push({s, 0});
    rolling_hash rh; rh.push_back(s);
    checked.insert(rh[35].first);
    while(!q.empty()){
        string st = q.front().first;
        int cnt = q.front().second;
        q.pop();
        bool flg = true;
        for(int i=1;i<n;++i){
            if(st[i] < st[i-1]){ flg = false; break; }
        }
        if(flg){
            cout << cnt << endl;
            return 0;
        }
        for(int i=0;i<n-1;++i){
            string t{st};
            swap(t[i], t[18+i+1]);
            swap(t[i+1], t[18+i]);

            rolling_hash th; th.push_back(t);
            auto hash = th[35].first;
            if(checked.count(hash)==0){
                checked.insert(hash);
                q.push({t, cnt+1});
            }
        }
    }
    cout << -1 << endl;
    return 0;
}

#include<iostream>
#include<algorithm>
using namespace std;
int main(){
	int N,A[18],B[18],k[18],k2[18],K[18],m[18],sum,pre,minL=10000;
	bool flag,can;
	cin>>N;
	for(int i=0;i<N;i++)cin>>A[i];
	for(int i=0;i<N;i++)cin>>B[i];
	for(int i=0;i<(1<<N);i++){
		pre=i;sum=0;
		for(int j=0;j<N;j++){
			m[j]=j;
			K[j]=pre%2;sum+=K[j];
			if(pre%2)k[j]=B[j];
			else k[j]=A[j];
			k2[j]=k[j];
			pre/=2;
		}
		if(sum%2)continue;
		sort(k2,k2+N);

		can=true;
		for(int j=0;j<N;j++){
			flag=false;
			for(int l=0;l<N;l++){
				flag |= (k[j]==k2[l] && (l-j+N*2)%2==K[j]);
			}
			can &= flag;
		}
		if(can==false)continue;
		sum=0;
		for(int j=0;j<N-1;j++){
			for(int l=0;l<N-j-1;l++){
				if(k[l]>k[l+1] || (k[l]==k[l+1]&&(m[l]-l+N*2)%2!=K[l])){
					swap(k[l],k[l+1]);
					swap(K[l],K[l+1]);
					swap(m[l],m[l+1]);
					sum++;
				}
			}
		}
		minL=min(minL,sum);
	}
	if(minL==10000)cout<<-1;
	else cout<<minL;
	return 0;
}

