#include <bits/stdc++.h>
typedef long long ll;
typedef long double ld;
using namespace std;

int kthbit(int A, int K) { return (A >> K) & 1; }

struct card{ int val; int initial; };

void sortCards(vector<card>& v){
    sort(v.begin(), v.end(), [](const card &a, const card &b){
        if(a.val != b.val) return a.val < b.val;
        else return a.initial < b.initial;
    });
}

int main(){
    int N;  cin >> N;
    vector<pair<int, int>> P(N);
    for(int i=0; i<N; i++)
        cin >> P[i].first;
    for(int i=0; i<N; i++)
        cin >> P[i].second;

    int ans = -1;
    for(int n=0; n<(1<<N); n++){
        vector<card> even, odd;
        for(int i=0; i<N; i++){
            card card;
            card.initial = i;
            bool isTable;
            if(kthbit(n, i) == 1){
                card.val = P[i].second;
                isTable = false;
            }else{
                card.val = P[i].first;
                isTable = true;
            }
            if((i%2==0 && isTable) || (i%2==1 && !isTable)) even.push_back(card);
            if((i%2==1 && isTable) || (i%2==0 && !isTable)) odd.push_back(card);
        }
        sortCards(odd);  sortCards(even);

        vector<card> result(N);
        bool ok = true;
        for(int i=0; i<even.size(); i++){
            if(2*i >= N){
                ok = false;
                break;
            }
            result[2*i] = even[i];
        }
        for(int i=0; i<odd.size(); i++){
            if(2*i + 1 >= N){
                ok = false;
                break;
            }
            result[2*i + 1] = odd[i];
        }
        for(int i=0; i<N-1; i++){
            if(result[i].val > result[i+1].val){
                ok = false;
                break;
            }
        }
        if(!ok) continue;

        vector<int> start(N);
        for(int i=0; i<N; i++){
            start[i] = result[i].initial;
        }

        int cnt = 0;
        for(int i=0; i<N-1; i++) for(int j=N-1; j>i; j--){
            if(start[j-1] > start[j]){
                swap(start[j-1], start[j]);
                cnt++;
            }
        }
        if(ans == -1) ans = cnt;
        else ans = min(ans, cnt);   
    }
    cout << ans << endl;
}

