int dp[500000][55];
int main()
{
	int n;
	cin >> n;
	int a[n], b[n];
	for (int i = 0; i < n; i++)
	{
		cin >> a[i];
	}
	for (int i = 0; i < n; i++)
	{
		cin >> b[i];
	}

	for (int bit = 0; bit < (1 << n); bit++)
	{
		for (int i = 0; i < 55; i++)
		{
			dp[bit][i] = INF;
		}
	}
	dp[0][0] = 0;

	for (int bit = 0; bit < (1 << n); bit++)
	{
		int s_size = 0;
		for (int i = 0; i < n; i++)
		{
			int mask = 1 << i;
			if (bit & mask)
			{
				s_size++;
			}
		}

		vector<pair<int, int>> ins; //first:もともと何番目か second:カードの現在地
		int now = s_size;
		for (int i = 0; i < n; i++)
		{
			int mask = 1 << i;
			if ((bit & mask) == 0)
			{
				ins.emplace_back(i, now);
				now++;
			}
		}

		for (int last = 0; last < 51; last++)
		{
			for (auto v : ins)
			{
				int i = v.first;
				int now = v.second;
				int ival;
				if (abs(i - s_size) % 2 == 0)
					ival = a[i];
				else
					ival = b[i];
				if (ival >= last)
				{
						dp[bit | (1 << i)][ival] = min(dp[bit | (1 << i)][ival], dp[bit][last] + abs(now - s_size));
				}
			}
		}
	}

	int ans = INF;
	for (int i = 0; i < 55; i++)
	{
		ans = min(ans, dp[(1 << n) - 1][i]);
	}
	if (ans == INF) cout << "-1" << endl;
	else cout << ans << endl;
	return 0;
}

