    for(int i = 1; i < n; ++i) {
      data nextd;
      if(i % 2)
        nextd = even[i / 2];
      else
        nextd = odd[i / 2];
      if(now > nextd.num) { ch = 0; }
      now = nextd.num;
      v.push_back(nextd.id);
    }
    if(!ch) continue;
    now = calc(v);
    res = min(res, now);
  }
  if(res == inf) return -1;
  return res;
}

long long calc(vector<long long> &v) {
  int x = v.size();
  if(x <= 1) return 0;
  long long res = 0;
  vector<long long> p(v.begin(), v.begin() + x / 2),
      q(v.begin() + x / 2, v.end());
  res += calc(p) + calc(q);
  int aid = 0, bid = 0, cid = 0, psize = p.size(),
      qsize = q.size();
  while(aid < x) {
    if(bid < psize && (cid == qsize || p[bid] <= q[cid]))
      v[aid++] = p[bid++];
    else {
      res += x / 2 - bid;
      v[aid++] = q[cid++];
    }
  }
  return res;
}

