typedef long long ll;

int n;
int a[20],b[20];

struct Node
{
	int face, val;
} c[20];

int d[20];

int solve(int s)
{
	int ret=0;
	for (int i=0;i<n;i++)
	{
		if ((1<<i)&s) // B-side
		{
			c[i+1].face = 1;
			c[i+1].val = b[i+1];
			d[i+1] = b[i+1];
		}
		else // A side
		{
			c[i+1].face = 0;
			c[i+1].val = a[i+1];
			d[i+1] = a[i+1];
		}
	}

	sort(d+1,d+n+1);

	for (int i=1;i<=n;i++) // 构造答案 
	{
		bool flag = 0;
		for (int j=i;j<=n;j++)
			if ( (c[j].val == d[i]) && (c[j].face == (j-i)%2) )
			{
				flag=1;
				ret+=j-i;
				for (int k=j-1;k>=i;k--)
				{
					swap(c[k],c[k+1]);
					c[k+1].face^=1;
				} 
				break;
			}
		if (!flag) return 2*1e9;
	}

	return ret;
}

int main()
{
	cin>>n;
	for(int i=1;i<=n;i++)
	{
		cin>>a[i];
	}
	for(int i=1;i<=n;i++)
	{
		cin>>b[i];
	}

	int ans=2*1e9;
	for (int i=0;i<(1<<n);i++)
	{
		ans=min(ans,solve(i));
	}

	if (ans== 2*1e9) ans=-1;
	printf("%d\n",ans);
}

