pair<bool , int> check(int mask , vector<int> &a , vector<int> &b , int n) {
	vector<int> res(n , -1) , flag(n,0) , index(n);
	int cnt = 0;
	for(int i = 0; i < n; i++) index[i] = i;
	for(int i = n-1 , j = 0; j < n-1; j++ , i--) {
		if(mask & (1 << i)) {
			cnt++;
			int temp = index[j+1];
			if(flag[index[j+1]] == 0) {
				res[j] = b[index[j+1]];
				flag[index[j+1]] = 1;
				index[j+1] = index[j];
			}
			else if(flag[index[j+1]] == 1){
				res[j] = a[index[j+1]];
				flag[index[j+1]] = 0;
				index[j+1] = index[j];
			}
			if(flag[index[j]] == 0) {
				res[j+1] = b[index[j]];
				flag[index[j]] = 1;
				index[j] = temp;
			}
			else if(flag[index[j]] == 1) {
				res[j+1] = a[index[j]];
				flag[index[j]] = 0;
				index[j] = temp;
			}
		}
		else {
			if(res[j] == -1) res[j] = a[j];
			if(res[j+1] == -1) res[j+1] = a[j+1]; 
		}
	}
	bool ok = true;
	for(int i = 1; i < n; i++) {
		if(res[i] < res[i-1]) {
			ok = false;
			break;
		}
	}
	if(ok) return {true , cnt};
	else return {false , -1};
}

signed main() {
    ios_base::sync_with_stdio(0);
    cin.tie(0);

	int n;
	cin >> n;
	vector<int> a(n) , b(n);
	for(int i = 0; i < n; i++) cin >> a[i];
	for(int i = 0; i < n; i++) cin >> b[i];
	int ans = 1e9+7 , found = 0;
	for(int mask = 0; mask < (1 << n); mask++) {
		pair<bool , int> res = check(mask , a , b , n);
		if(res.first) {
			ans = min(ans , res.second);
			found = 1;
		}
	}
	if(!found) cout << -1 << "\n";

	else cout << ans << "\n";

    return 0;
}

#include <bits/stdc++.h>

using namespace std;
using ll = long long;

const int INF = 0x3f3f3f3f;

int main() {
    int N;
    cin >> N;
    vector<int> A(N);
    vector<int> B(N);

    for (int i = 0; i < N; ++i) {
        cin >> A[i];
    }
    for (int i = 0; i < N; ++i) {
        cin >> B[i];
    }
    vector<vector<int>> dp((1 << N), vector<int>(N, INF));
    // dp[mask][i]: the minimum operation when cards in mask are in leftmost and the ith card is in the end
    for (int i = 0; i < N; ++i) {
        dp[1 << i][i] = 0;  // there is no card in leftmost whose id larger than i
    }
    for (int s = 0; s < (1 << N); ++s) {
        for (int i = 0; i < N; ++i) {
            if (((s >> i) & 1) == 0)
                continue;                  // i is not in state
            int c = __builtin_popcount(s); // card number in s
            int value_i = (c % 2) == (i % 2) ? B[i] : A[i];
            int cost = c; // the number of card in s, whose id is larger than j
            for (int j = 0; j < N; ++j) {
                if (((s >> j) & 1) == 1) {
                    --cost;
                    continue; // j is in state already
                }
                int value_j = (j % 2) == (c % 2) ? A[j] : B[j];
                if (value_j >= value_i) {
                    dp[s | (1 << j)][j] =
                        min(dp[s | (1 << j)][j], dp[s][i] + cost);
                }
            }
        }
    }
    int ans = INF;
    for (int i = 0; i < N; ++i) {
        ans = min(ans, dp[(1 << N) - 1][i]);
    }
    ans = ans >= INF ? -1 : ans;
    cout << ans << endl;
    return 0;
}

