template<class T> inline bool UpdateMin(T& a, T b) {
  if (a > b) { a = b; return 1; } return 0;
}

template<class T> inline bool UpdateMax(T& a, T b) {
  if (a < b) { a = b; return 1; } return 0;
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  int n;
  cin >> n;
  vector<int> xs(n), ys(n);
  for (int i = 0; i < n; i++) {
    cin >> xs[i];
  }
  for (int i = 0; i < n; i++) {
    cin >> ys[i];
  }

  auto process_pattern_fn = [&](int p) -> int {
    vector<int> flags(n);
    for (int i = 0; i < n; i++) {
      if (p & (1 << i)) flags[i] = 1;
    }

    vector<int> vs(n);
    for (int i = 0; i < n; i++) {
      if (flags[i]) vs[i] = ys[i];
      else vs[i] = xs[i];
    }
    sort(vs.begin(), vs.end());

    vector<int> used(n);
    vector<int> indexes(n, -1);
    for (int k = 0; k < n; k++) {
      for (int i = 0; i < n; i++) {
        if (used[i]) continue;
        if (abs(k - i) % 2 != flags[i]) continue;
        int v = flags[i] ? ys[i] : xs[i];
        if (vs[k] != v) continue;
        used[i] = 1;
        indexes[k] = i;
        break;
      }
      if (indexes[k] == -1) return -1;
    }

    int r = 0;
    for (int i = 0; i < n; i++) {
      for (int j = i + 1; j < n; j++) {
        if (indexes[i] > indexes[j]) r++;
      }
    }
    return r;
  };

  int ans = INT_MAX;
  for (int p = 0; p < 1 << n; p++) {
    int r = process_pattern_fn(p);
    // cout << p << " " << r << endl;
    if (r >= 0) {
      UpdateMin(ans, r);
    }
  }
  if (ans == INT_MAX) {
    ans = -1;
  }
  cout << ans << endl;
}

