    if(i>n&&b==n/2)
    {
        vector<PII> red,blue;
        for(int j=1;j<=n;j++)
            if(j&1)
            {
                if(c[j]==0)red.pb({a[j],j});
                if(c[j]==1)blue.pb({b2[j],j});
            }
            else
            {
