void jud(int s){
	for(int i=0;i<n;++i){
		if(s&(1<<i)) p[i]=1;
		else p[i]=0;
		t[i]=a[i][p[i]];
		b[i][0]=a[i][0];
		b[i][1]=a[i][1];
	}
	sort(t,t+n);
	bool flag=0;
	int val=0;
	for(int i=0;i<n;++i){
		int j=i;
		for(;j<n;++j)
			if(b[j][p[j]]==t[i]&&((j-i)^p[j])==0) break;
		if(j>=n) {
			flag=1;
			break;
		}
		for(;j>i;--j){
			swap(b[j][0],b[j-1][1]);
			swap(b[j][1],b[j-1][0]);
			swap(p[j],p[j-1]);
			p[j]^=1;p[j-1]^=1;
			++val;
		}
	}
	if(flag) return;
	ans=min(ans,val);
}
