    int32 cnt = 0;
    REP(i,n-1){
      FORR(j,n-2,i){
        if(x[j].fi > x[j+1].fi){
          swap(x[j], x[j+1]);
          x[j].se = !x[j].se;
          x[j+1].se = !x[j+1].se;
          ++cnt;
        }else if(x[j].fi == x[j+1].fi && x[j].se){
          swap(x[j], x[j+1]);
