ll func(ll idx,int s,ll mask)
{
    if(mask==(1<<n)-1){return 0;}

    if(dp[idx][s][mask]==-1){
    ll ans=inf;
    ll count=0;
    for(ll i=0;i<n;++i){
        if((mask&(1<<i))!=0){++count;}
    }
    for(ll i=0;i<n;++i)
    {
        if((mask&(1<<i))==0)
        {
            ll cost=0;
            if(i>count){cost=i-count;}
            ll val=INT_MIN;
            if(count>0)
            {val=ar[idx].first;
            if(s){val=ar[idx].second;}
            }
            ll myval=ar[i].first;
