#include <bits/stdc++.h>
using namespace std;
const int MX=1e9;
int dp[1000000][52];
int c[1000000][20];
int n;
int a[20];
int b[20];
int main(){
    cin.tie(0);
    ios_base::sync_with_stdio(0);
    cin>>n;
    int i,j,k;
    for(i=0 ; i<n ; i++)cin>>a[i];
    for(i=0 ; i<n ; i++)cin>>b[i];
    for(i=0 ; i<=50 ; i++)dp[0][i]=0;
    for(i=1 ; i<(1<<n) ; i++)for(j=0 ; j<=50 ; j++)dp[i][j]=MX;
    for(i=0 ; i<(1<<n) ; i++){
        int k=n;
        for(j=n-1 ; j>=0 ; j--){
            if(((1<<j)&i)==0){
                c[i][j]=k--;
            }
        }
    }
    for(i=1 ; i<(1<<n) ; i++){
        int t=i;
        int s=0;
        while(t){
            s+=t%2;
            t/=2;
        }
        for(k=0 ; k<n ; k++){
            if(((1<<k)&i)==0)continue;
            if(s%2!=k%2){
                dp[i][a[k]]=min(dp[i][a[k]],dp[i^(1<<k)][a[k]]+abs(s-c[i^(1<<k)][k]));
            }
            else{
                dp[i][b[k]]=min(dp[i][b[k]],dp[i^(1<<k)][b[k]]+abs(s-c[i^(1<<k)][k]));
            }
        }
        for(j=1 ; j<=50 ; j++)dp[i][j]=min(dp[i][j],dp[i][j-1]);

    }
    int ans=dp[(1<<n)-1][50];
    if(ans<MX)cout<<ans;
    else cout<<-1;
    return 0;
}

