ll n,k,x,y;



class Bit
{
  public:
  ll size;
  vector<ll> data;
  Bit(ll n)
  {
    data.resize(n+1);
    REP(i,n+1)
      data[i]=0;
    size=n;
  }
  //(1-i)までの合計を返す
  ll Sum(ll i){
    ll s = 0;
    while (i > 0){
        s += data[i];
        i -= i & (-i);
    }
    return s;
  }
  //Add
  void Add(ll i,ll x){
    while (i <= size){
      data[i] += x;
      i += i & (-i);
    }
  }
};


int bbit(int ii,int t){
  return (ii>>t)%2;
}

vector<int> nmn(18);
