int solve(vector<int> &v,vi &a,vi &b)
{
  int wki=0;
  int wgu=0;
  for(int i=0;i<n;i++){
    if ((v[i]+i%2)%2==0){
      if (v[i]==0){
        gu[wgu].first=a[i];
        nmn[i]=a[i];
      }else{
        gu[wgu].first=b[i];
        nmn[i]=b[i];
      }
      gu[wgu].second=i;
      wgu++;

    }else{
      if (v[i]==1){
        ki[wki].first=b[i];
        nmn[i]=b[i];
      }else{
        ki[wki].first=a[i];
        nmn[i]=a[i];
      }
      ki[wki].second=i;
      wki++;
    }
  }
  if (wki!=(n/2)) 
    return -1;



  int an=0;

  sort(gu.begin(), gu.begin()+wgu);
  sort(ki.begin(), ki.begin()+wki);
  int tmp=0,flag=0,ttmp=0;
  for(int i=0;i<n;i++){
    if (i%2==0){
      if (tmp>gu[i/2].first)flag=1;
      tmp=gu[i/2].first;
      ttmp=gu[i/2].second;
    }else{
      if (tmp>ki[i/2].first)flag=1;
      tmp=ki[i/2].first;
      ttmp=ki[i/2].second;
    }
    nm[i].first=tmp;
    nm[i].second=ttmp;
  }
  if (flag==1)return -1;


  Bit bit(64);
  for(int i=0;i<n;i++){
    bit.Add(nmn[i],1);
    an+=i+1-(int)bit.Sum(nmn[i]);
  }




