int main(int argc, char const *argv[]) {
  ll n;std::cin >> n;
  vll a(n), b(n);
  re(i, n) std::cin >> a[i];
  re(i, n) std::cin >> b[i];
  ll ans = 100000000;
  for(int i=0;i<(1<<n);i++){
    ll s = 0, tmp = 0;
    bitset<18> k(i);
    re(j, n) if(k[j]) s++;
    if(s%2) continue;
    vll num(n);
    vvl z = vv(n, 3, 0, ll);
    re(j, n) {
      num[j] = (k[j]?b[j]:a[j]);
      z[j] = vll{num[j], j, 0};
    }
    segtree seg(51, 0), rev(51, 0);
    vll x(n, 0);
    for(int j=0;j<n;j++) {
      ll q = seg.query(num[j]+1, 51);
      tmp += q, x[j]+=q;
      seg.update(1, num[j]);
    }
    for(int j=n-1;j>=0;j--){
      ll q = rev.query(0, num[j]);
      x[j]+=q;
      rev.update(1, num[j]);
    }
    re(j, n) {
      if(k[j]!=x[j]%2) z[j][2] = 1;
      else z[j][2] = -1;
    }
    sort(all(z));
    bool flag = true;

    re(j, n){
      if(z[j][2]==-1) continue;
      if(z[j][2]==1&&(j==n-1||z[j][0]!=z[j+1][0])) {
        flag = false;
        break;
      }
      tmp++;
      z[j][2]=-1, z[j+1][2]*=-1;
    }
    if(flag) ans = min(tmp, ans);
  }
  if(ans==100000000){
    while(true) n++;
  }
  std::cout << (ans==100000000?-1:ans) << '\n';
  return 0;
}

