#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
typedef long double ld;
typedef pair<ll, ll> ii;
typedef tuple<ll, ll, ll> iii;
typedef vector<ll> vi;
typedef vector<ii> vii;
typedef vector<iii> viii;
typedef vector<vi> vvi;
typedef vector<vii> vvii;
#define REP(i,n) for (ll i = 0; i < n; ++i)
#define REPR(i,n) for (ll i = n-1; i >= 0; --i)
#define FOR(i,m,n) for (ll i = m; i < n; ++i)
#define FORR(i,m,n) for (ll i = n-1; i >= m; --i)
#define FORE(x,xs) for (const auto& x : xs)
#define ALL(v) v.begin(), v.end()

const int MAX = 20;
const ll NG = 1e18;

int N;
int A[MAX], B[MAX];


struct BIT {
    vector<ll> data;
    int N;

    BIT(int n) {
        N = n;
        data = vector<ll>(N+1);
    }

    void add(int i, ll x) {
        for (int k = i; k <= N; k += k&-k) data[k] += x;
    }

    ll sum(int i) {
        ll res = 0;
        for (int k = i; k > 0; k -= k&-k) res += data[k];
        return res;
    }
};

ll inversion(vi a) {

    REP (i, N) a[i] += 1;
    BIT bit(N);

    ll res = 0;
    for (int i = 0; i < N; i++) {
        res += i-bit.sum(a[i]-1);
        bit.add(a[i], 1);
    }

    return res;
}

inline int get_bit(ll flag, int n) {
    return (flag >> n) & 1;
}

ll sub(ll flag) { // flagの0のビットが赤、1のビットが青
    if (__builtin_popcount(flag) & 1) return NG; // 青のカードは偶数個
    vii nums(N);
    REP (i, N) {
        if (get_bit(flag, i)) nums[i] = make_pair(B[i], i);
        else nums[i] = make_pair(A[i], i);
    }
    sort(ALL(nums));

    vi target; // flagのようにひっくり返って、かつ最小回数でソートしたときの状態
    REP (left, N) {
        int right = left;
        set<ll> odd, even; // nums[left].firstと同じ値のカードの位置の集合の偶奇
        while (right < N && nums[right].first == nums[left].first) {
            // 0枚目が赤ならevenになる
            if ((nums[right].second & 1) ^ (get_bit(flag, nums[right].second) & 1)) {
                odd.insert(nums[right].second);
            } else {
                even.insert(nums[right].second);
            }
            right++;
        }

        if (left & 1) swap(odd, even); // 処理の簡単にするために常にevenから値を取り出すことにする
        if (even.size() < odd.size() || even.size() - odd.size() > 1)
            return NG; // evenがodd以上で、evenとoddの差はたかだか1

        vi even_vec(ALL(even)), odd_vec(ALL(odd));
        REP (i, even.size() + odd.size()) target.push_back((i&1) ? odd_vec[i>>1] : even_vec[i>>1]); // 交互に追加

        left = right - 1;
    }

    return inversion(target);
}

ll solve() {
    ll ans = NG;
    REP (i, 1ll << N) ans = min(ans, sub(i));
    if (ans == NG) return -1;
    return ans;
}

int main() {
    cin >> N;
    REP (i, N) cin >> A[i];
    REP (i, N) cin >> B[i];
    cout << solve() << endl;
}

