int pop_count(int n){
    int res = 0;
    while(n > 0){
        res += (n&1);
        n >>= 1;
    }
    return res;
}

int main(){
    int n;
    cin >> n;
    vector<vector<int>> v(2, vector<int>());
    for(int i=0;i<n;++i){
        int tmp;
        cin >> tmp;
        v[0].push_back(tmp);
    }
    for(int i=0;i<n;++i){
        int tmp;
        cin >> tmp;
        v[1].push_back(tmp);
    }
    vector<vector<int>> dp(1<<n, vector<int>(n, INF));
    for(int i=0;i<n;++i)dp[0][i] = 0;
    for(int i=0;i<(1<<n);++i){
        for(int j=0;j<n;++j){
            if(dp[i][j] == INF)continue;
            if(i != 0 && !(i&(1<<j)))continue;
            for(int k=0;k<n;++k){
                if(i&(1<<k))continue;
                int m = pop_count(i);
                int front = (i == 0 ? 0 : v[abs(m-1-j)%2][j]);
                int next = v[abs(m-k)%2][k];
                if(next < front)continue;
                int idx = k - pop_count(((1<<(k+1))-1)&i) + m;
                // cerr << idx << endl;
                dp[i|(1<<k)][k] = min(dp[i|(1<<k)][k], dp[i][j]+abs(m-idx));
            }
        }
    }

    int ans = INF;
    for(int i=0;i<n;++i){
        ans = min(ans, dp[(1<<n)-1][i]);
    }

    cout << (ans == INF ? -1 : ans) << endl;

    return 0;
}

