        // p.first　は　元のindex, p.second　は　移動後のindex
        // 移動した後のindexがソート済みの右側から小さい順に並んでいると貪欲に示せる

        int a;

        if( abs(p.first-res) % 2 == 0 ){ 
          a = A[p.first];
        }
        else{
          a = B[p.first];
        }

        if( a < s ){ continue;}


        chmin( dp[bit|(1<<p.first)][a], dp[bit][s]+abs(p.second-res) );

      }//p

    }//s

  }//bit

  int ans = inf;

  for(int i = 0; i <= 50; i++){
    chmin(ans, dp[(1<<N)-1][i]);
  }

  if( ans == inf){ ans = -1;}

  cout << ans << endl;

  return 0;
}

