int N;
vector<int> A, B;
int memo[1<<18][51][2];
bool visited[1<<18][51][2];
const int INF = 1<<29;
vector<int> aa;
int f(int p, int n, int m, int q) {
	if (p == N) {
		int r = 0;
		for (int i = 0; i < N; ++ i) {
			for (int j = i+1; j < N; ++ j) {
				if (aa[i] > aa[j]) ++ r;
			}
		}
		return r;
	}
	if (visited[n][m][q]) return memo[n][m][q];
	visited[n][m][q] = true;
	int r = INF;
	for (int i = 0; i < N; ++ i) if (((n>>i)&1)==0) {
		int qq = abs(p-i) % 2;
		int x = (qq == 0) ? A[i] : B[i];
		if (x < m) continue;
		if (q == 1) {
			 if (qq == 0) continue;
			 qq = 0;
		}
		aa.push_back(i);
		r = min(r, f(p+1, n | (1<<i), x, qq));
		aa.pop_back();
	}
	return memo[n][m][q] = r;
}
