bool is_enable(int n, vector<int> e, vector<int> o) {

    if (!(e.size() == (n + 1) / 2)) return false;
    if (!(o.size() == n / 2)) return false;

    sort(e.begin(), e.end());
    sort(o.begin(), o.end());
    vector<int> tmp;
    rep(i, e.size()) {
        tmp.push_back(e[i]);
        if (o.size() > i) tmp.push_back(o[i]);
    }


    rep(i, tmp.size() - 1) {
        if (!(tmp[i] <= tmp[i + 1])) return false;
    }
    return true;

}

int calc(vector<P> v) {
    int n = v.size();

    vector<int> tmp;
    for (P p : v) tmp.push_back(p.first);
    sort(tmp.begin(), tmp.end());

    vector<int> rank(n, -1);
    rep(i, n) {
        rep(j, n) {
            if (
                    v[j].first == tmp[i] &&
                    i % 2 == v[j].second &&
                    rank[j] == -1
                    ) {
                rank[j] = i;
                break;
            }
        }
    }


    int ans = 0;
    for (int i = 1; i < n; i++) {
        for (int j = 0; j < i; j++) {
            if (rank[j] > rank[i]) ans++;
        }
    }

    return ans;
}


