int main() {
    constexpr int inf = std::numeric_limits<int>::max();
    int n;
    std::cin >> n;
    std::vector<int> a(n), b(n);
    for (auto &e : a) std::cin >> e;
    for (auto &e : b) std::cin >> e;

    int ret = inf;
    for (int bit = 0; bit < (1 << n); bit++) {
        std::map<int, std::vector<std::pair<int, int>>> v;
        for (int i = 0; i < n; i++) {
            int f = (bit & (1 << i)) > 0;
            // f == 1 -> reversed, odd
            // f == 0 -> otherwise
            v[f ? b[i] : a[i]].emplace_back(i, f);
        }

        int pos = 0, s = 0;
        bool flg = true;
        for (auto &e : v) {
            auto &q = e.second;
            int cnt = q.size();
            std::set<int> odd, even;
            for (int i = 0; i < cnt; i++) {
                if ((q[i].first % 2) ^ q[i].second) odd.insert(q[i].first);
                else even.insert(q[i].first);
            }

            for (int i = 0; i < cnt; i++) {
                if (pos % 2) {
                    if (odd.empty()) {
                        flg = false;
                        break;
                    }
                    auto j = odd.begin();
                    s += abs(pos - *j);
                    odd.erase(j);
                } else {
                    if (even.empty()) {
                        flg = false;
                        break;
                    }
                    auto j = even.begin();
                    s += abs(pos - *j);
                    even.erase(j);
                }
                pos++;
            }
        }

        if (flg) ret = std::min(ret, s);
    }

    std::cout << (ret == inf ? -1 : ret / 2) << std::endl;

    return 0;
}

