  vector<ll> A(N), B(N);
  for (ll i = 0; i < N; i++) {
    if (i % 2 == 0) cin >> A.at(i);
    else            cin >> B.at(i);
  }
  for (ll i = 0; i < N; i++) {
    if (i % 2 == 0) cin >> B.at(i);
    else            cin >> A.at(i);
  }
  ll cost = LLONG_MAX;
  for (ll x = 0; x < (1LL << N); x++) {
    DLOG("x", x, popcount(x));
    if (popcount(x) != (N+1) / 2) continue;
    vector<ll> u, v;
    for (ll i = 0; i < N; i++) {
      if (x & (1LL << i)) u.push_back(A.at(i));
      else                 v.push_back(B.at(i));
    }
    sort(u.begin(), u.end());
    sort(v.begin(), v.end());

    DLOG("u", u);
    DLOG("v", v);

    auto ordok = [&]() -> bool {
      for (ll i = 0; i < N / 2; i++) if (u.at(i) > v.at(i)) return false;
      for (ll i = 0; i < N / 2 - 1; i++) {
	if (v.at(i) > u.at(i+1)) return false;
      }
      if (N % 2 == 1 && v.at(N / 2 - 1) > u.at((N+1) / 2 - 1)) return false;
      return true;
    };

    if (!ordok()) continue;

    vector<ll> z;
    for (ll i = 0; i < N; i++) {
      if (x & (1LL << i)) z.push_back(A.at(i));
      else                 z.push_back(B.at(i));
    }
    ll cnt = 0;
    for (ll i = 0; i < N; i++) {
      for (ll j = i+1; j < N; j++) {
	if (z.at(i) > z.at(j)) cnt++;
      }
    }
    cost = min(cost, cnt);
  }

  if (cost == LLONG_MAX) {
    cout << -1 << endl;
  }else {
    cout << cost << endl;
  }

  return 0;
}

