i64 solve(i64 m) {
    map<i64, map<i64, vector<i64>>> e;
    for (i64 i = 0; i < n; i += 1) {
        pair<i64, i64> p = { i, (m & (1ll << i) ? 1 : 0) };
        e[val(p)][p.second].push_back(p.first);
    }

    vector<i64> r;
    i64 ts = 0;
    for (auto& u : e) {
        auto& t = u.second;

        vector<i64> c[2];
        for (auto v : t[0]) {
            c[v % 2].push_back(v);
        }
        for (auto v : t[1]) {
            c[(v + 1) % 2].push_back(v);
        }

        i64 z[2] = { 0, 0 };
        i64 tt = (t[0].size() + t[1].size());
        z[0] = tt / 2 + tt % 2;
        z[1] = tt / 2;
        if (ts % 2) {
            swap(z[0], z[1]);
        }

        if (c[0].size() != z[0] || c[1].size() != z[1]) {
            return inf;
        }

        sort(c[0].data(), c[0].data() + c[0].size());
        sort(c[1].data(), c[1].data() + c[1].size());

        for (i64 i = 0; i < t[0].size() + t[1].size(); i++) {
            r.push_back(c[(ts + i) % 2][i / 2]);
        }


        ts += t[0].size() + t[1].size();
    }

    return val(r);
}

