bool checkOK(vector<LL>& check){
    for(LL i = 0; i+1 < check.size(); ++i){
        if(check[i] > check[i+1]) return false;
    }
    return true;
}

LL iabs(LL v){
    if(v < 0) return -v;
    return v;
}

LL moveCount(vector<LL> index){
    LL cnt = 0;
    for(LL i = 0; i < index.size(); ++i){
        for(LL j = i+1; j < index.size(); ++j){
            if(index[i] > index[j]) ++cnt;
        }
    }
    return cnt;
}

int main(){
    LL n;
    cin >> n;
    vector<pair<LL, LL>> a_odd, a_even, b_odd, b_even;
    for(LL i = 0; i < n; ++i){
        LL v;
        cin >> v;
        if((i&1) == 0){
            a_even.emplace_back(v, i);
        }else{
            b_even.emplace_back(v, i);
        }
    }
    for(LL i = 0; i < n; ++i){
        LL v;
        cin >> v;
        if((i&1) == 0){
            b_odd.emplace_back(v, i);
        }else{
            a_odd.emplace_back(v, i);
        }
    }
    sort(a_even.begin(), a_even.end());
    sort(b_even.begin(), b_even.end());
    sort(a_odd.begin(), a_odd.end());
    sort(b_odd.begin(), b_odd.end());
    /*
    cerr << "a_even=" << a_even << endl;
    cerr << "a_odd=" << a_odd << endl;
    cerr << "b_even=" << b_even << endl;
    cerr << "b_odd=" << b_odd << endl;
    */
    vector<LL> used(n);
    vector<LL> check(n), index(n);
    LL ans = -1;
    for(LL i = 0; i < (1<<n); ++i){
        LL a_even_i = 0, b_even_i = 0;
        LL a_odd_i = 0, b_odd_i = 0;
        for(LL cur = 0; cur < n; ++cur){
            used[cur] = 0;
            index[cur] = -1;
            check[cur] = -1;
        }
        LL move_cnt = 0;
        for(LL cur = 0; cur < n; ++cur){
            if((cur&1) == 0){
                if(((i>>cur)&1) == 0){
                    //cerr << "a_even" << endl;
                    while(a_even_i < a_even.size() && used[a_even[a_even_i].second]) ++a_even_i;
                    if(a_even_i >= a_even.size()) break;
                    move_cnt += iabs(a_even[a_even_i].second - cur);
                    used[a_even[a_even_i].second] = 1;
                    index[cur] = a_even[a_even_i].second;
                    check[cur] = a_even[a_even_i++].first;
                }else{
                    //cerr << "a_odd" << endl;
                    while(a_odd_i < b_odd.size() && used[a_odd[a_odd_i].second]) ++a_odd_i;
                    if(a_odd_i >= a_odd.size()) break;
                    move_cnt += iabs(a_odd[a_odd_i].second - cur);
                    used[a_odd[a_odd_i].second] = 1;
                    index[cur] = a_odd[a_odd_i].second;
                    check[cur] = a_odd[a_odd_i++].first;
                }
            }else{
                if(((i>>cur)&1) == 0){
                    //cerr << "b_even" << endl;
                    while(b_even_i < b_even.size() && used[b_even[b_even_i].second]) ++b_even_i;
                    if(b_even_i >= b_even.size()) break;
                    move_cnt += iabs(b_even[b_even_i].second - cur);
                    used[b_even[b_even_i].second] = 1;
                    index[cur] = b_even[b_even_i].second;
                    check[cur] = b_even[b_even_i++].first;
                }else{
                    //cerr << "b_odd" << endl;
                    while(b_odd_i < b_odd.size() && used[b_odd[b_odd_i].second]) ++b_odd_i;
                    if(b_odd_i >= b_odd.size()) break;
                    move_cnt += iabs(b_odd[b_odd_i].second - cur);
                    used[b_odd[b_odd_i].second] = 1;
                    index[cur] = b_odd[b_odd_i].second;
                    check[cur] = b_odd[b_odd_i++].first;
                }
            }
        }
        if(checkOK(check)){
            //cerr << "debug i=" << i << ", " << move_cnt << ", " << check<< endl;
            if(ans == -1){
                ans = moveCount(index);
            }else{
                ans = min(ans, moveCount(index));
            }
        }
    }
    cout << ans << endl;
    return 0;
}

