int N;
int A[18];
int B[18];
int C[18];
int sub(int s) {
	int odd = 0;
	int even = 0;
	REP(k, 0, N) {
		if ((s >> k) & 1) {
			++(k % 2 == 0 ? even : odd);
		}
	}

	if (even != odd) return INF;

	vector<int> odda;
	vector<int> evena;
	REP(k, 0, N) {
		bool flip = (s >> k) & 1;
		if (flip) {
			C[k] = B[k];
		} else {
			C[k] = A[k];
		}

		if ((k % 2 == 0) ^ flip) {
			evena.push_back(C[k]);
		} else {
			odda.push_back(C[k]);
		}
	}

	int cnt = 0;
	REP(i, 0, N) {
		REP(j, i + 1, N) {
			if (C[i] > C[j]) ++cnt;
		}
	}

	sort(C, C + N);

	vector<int> oddb;
	vector<int> evenb;
	REP(i, 0, N) {
		if (i % 2 == 0) {
			evenb.push_back(C[i]);
		} else {
			oddb.push_back(C[i]);
		}
	}
	sort(evena.begin(), evena.end());
	sort(evenb.begin(), evenb.end());
	sort(odda.begin(), odda.end());
	sort(oddb.begin(), oddb.end());
	if (odda != oddb || evena != evenb) return INF;
	return cnt;
}

int main() {
	cin >> N;
	REP(i, 0, N) {
		cin >> A[i];
	}
	REP(i, 0, N) {
		cin >> B[i];
	}

	int mn = INF;
	REP(s, 0, 1 << N) {
		mn = min(mn, sub(s));
	}
	cout << (mn == INF ? -1 : mn) << endl;
	return 0;
}

