        sort(all(odd));

        if ((int)odd.size() != n/2) continue;
        if(__builtin_popcount(mask) & 1) continue;
        vector<int> v;
        rep(i,n){
            v.push_back((i&1) ? odd[i/2].second : even[i/2].second);
        }
        {
            bool ng = false;
            rep(i,n-1){
                if (v[i] > v[i+1]) ng = true;
            }
            if (ng) continue;
        }

        res = min(mergecount(v), res);
    }
    cout << (res == INF ? -1 : res) << endl;
    return 0;
}

