const int INF = 0x3f3f3f3f;
const int MAXN = 18;
const int MAXX = 50;

int N;
int A[MAXN + 1];
int B[MAXN + 1];

vector<int> oddA[MAXX + 1];
vector<int> evenA[MAXX + 1];
vector<int> oddB[MAXX + 1];
vector<int> evenB[MAXX + 1];

int X[MAXN + 1];
int oddA2[MAXX + 1];
int evenA2[MAXX + 1];
int oddB2[MAXX + 1];
int evenB2[MAXX + 1];

int calcDist(int idx) {
    int val = X[idx];

    int res = INF;
    if (idx & 1) {
        int dA = INF;
        int posA = INF;
        for (auto i : oddA[val]) {
            if (oddA2[val] & (1 << i))
                continue;
            if (abs(idx - i) < dA) {
                posA = i;
                dA = abs(idx - i);
            }
        }

        int dB = INF;
        int posB = INF;
        for (auto i : oddB[val]) {
            if (oddB2[val] & (1 << i))
                continue;
            if (abs(idx - i) < dB) {
                posB = i;
                dB = abs(idx - i);
            }
        }

        if (dA <= dB) {
            if (dA < res) {
                res = dA;
                oddA2[val] |= 1 << posA;
            }
        } else {
            if (dB < res) {
                res = dB;
                oddB2[val] |= 1 << posB;
            }
        }
    } else {
        int dA = INF;
        int posA = INF;
        for (auto i : evenA[val]) {
            if (evenA2[val] & (1 << i))
                continue;
            if (abs(idx - i) < dA) {
                posA = i;
                dA = abs(idx - i);
            }
        }

        int dB = INF;
        int posB = INF;
        for (auto i : evenB[val]) {
            if (evenB2[val] & (1 << i))
                continue;
            if (abs(idx - i) < dB) {
                posB = i;
                dB = abs(idx - i);
            }
        }

        if (dA <= dB) {
            if (dA < res) {
                res = dA;
                evenA2[val] |= 1 << posA;
            }
        } else {
            if (dB < res) {
                res = dB;
                evenB2[val] |= 1 << posB;
            }
        }
    }

    return res;
}

int main(void) {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N;

    for (int i = 0; i < N; i++)
        cin >> A[i];
    for (int i = 0; i < N; i++)
        cin >> B[i];

    for (int i = 0; i < N; i++) {
        if (i & 1) {
            oddA[A[i]].push_back(i);
            evenB[B[i]].push_back(i);
        } else {
            evenA[A[i]].push_back(i);
            oddB[B[i]].push_back(i);
        }
    }

    int res = INF;

    for (int i = 0; i < (1 << N); i++) {
        for (int j = 0; j < N; j++) {
            if (i & (1 << j))
                X[j] = B[j];
            else
                X[j] = A[j];
        }
        sort(X, X + N);

        memset(oddA2, 0, sizeof(oddA2));
        memset(evenA2, 0, sizeof(evenA2));
        memset(oddB2, 0, sizeof(oddB2));
        memset(evenB2, 0, sizeof(evenB2));

        int d = 0;
        for (int j = 0; j < N; j++) {
            int r = calcDist(j);
            if (r >= INF) {
                d = -1;
                break;
            }
            d += r;
        }

        if (d >= 0)
            res = min(res, d);
    }

    if (res >= INF)
        cout << -1 << endl;
    else
        cout << res / 2 << endl;

    return 0;
}

