using namespace std;
vector<pair<int, int>> reds, blues;

int getCard(vector<int> &A, vector<int> &B, int card, int depth){
    if(abs(card-depth) % 2 == 0){
        return A[card];
    }else{
        return B[card];
    }
}

int fn(vector<int> &A, vector<int> &B, vector<int> &p, int depth, set<int> &usedCards){
    if(depth == 0){
        int cand;
        for(cand=0;cand<A.size();cand++){
            if(usedCards.count(cand) == 0){break;}
        }
        p[0]=cand;
        // for(int i=0;i<A.size();i++){
        //     cout << p[i];
        // }
        // cout << endl;
        // for(int i=0;i<A.size();i++){
        //     cout << getCard(A,B,p[i],i);
        // }
        // cout << endl;
        if(getCard(A,B,cand, 0) > getCard(A,B,p[1],1)){return 1000000;}
        int sum=0;
        for(int i=0;i<A.size();i++){
            sum += abs(p[i]-i);
        }
        return sum/2;
        //数を計算してreturnする。
    }
    int minRes = 1000000;
    int i = 0;
    for(i=0;i<A.size();i++){
        int cand;
        if(depth % 2 == 0){
            cand = reds[i].second;
        }else{
            cand = blues[i].second;
        }
        if(usedCards.count(cand) > 0){continue;}
        if(depth < A.size()-1 && getCard(A, B, cand, depth) > getCard(A, B, p[depth+1], depth+1)){
            continue;
        }
        p[depth] = cand;
        usedCards.insert(cand);
        int res = fn(A, B, p, depth-1, usedCards);
        minRes = min(res, minRes);
        usedCards.erase(cand);
    }
    return minRes;
}



