		for(j=0;j<50;j++){chmin(dp[bi][j+1],dp[bi][j]);}
		for(i=0;i<n;i++){
			//使用するカード
			if(bi&(1<<i)){continue;}
			int s=((i+u)%2==0?A[i]:B[i]);
			chmin(dp[bi+(1<<i)][s],dp[bi][s]+F);
			F++;
		}
	}
	dp[(1<<n)-1][50]+=mod;
	if(dp[(1<<n)-1][50]==mod){dp[(1<<n)-1][50]=-1;}
	cout<<dp[(1<<n)-1][50]<<endl;
}

