#define FOR(i,k,n) for(int i=(k);i<(n);++i)

template<typename T>
class BIT{
public:
    vector<T> bit;
    int size;
    BIT(int size):
        bit(vector<T>(size+1,0)),size(size){}

    T sum(int i){
        if(!i) return 0;
        return bit[i]+sum(i-(i&(-i)));
    }

    void add(int i,T x){
        if(i>size)return;
        bit[i]+=x;
        add(i+(i&(-i)),x); 
    }   
};

int inversion(const vector<pair<int,int>> &v) {
    BIT<int> bit(55);
    int res = 0;
    REP(i,v.size()) {
        res += i - bit.sum(v[i].second+1);
        bit.add(v[i].second+1,1);
    }
    return res;
} 

bool is_monotone_increasing(const vector<pair<int,int>> &v) {
    int n = v.size();
    bool res = true;
    FOR(i,1,n){ if(v[i].first<v[i-1].first) res = false; }
    return res;
}

int main() {
    int N; cin >> N;
    vector<pair<int,int>> v(N);
    REP(i,N) cin >> v[i].first;
    REP(i,N) cin >> v[i].second;
    int ans = 1<<29;
    REP(i,1<<N) {
        int odd_cnt = 0, even_cnt = 0;
        REP(j,N) {
            if( ( (j%2==0) && ((i>>j)&1)==0 ) || (j%2)&((i>>j)&1) ) even_cnt ++;
            else odd_cnt ++; 
        }
        if( !(even_cnt == N-N/2 && odd_cnt == N/2) ) continue;
        vector<pair<int,int>> evens, odds;
        REP(j,N) {
            int c = (((i>>j)&1) ? v[j].second : v[j].first);
            if( ( (j%2==0) && ((i>>j)&1)==0 ) || (j%2)&((i>>j)&1) ) {
                evens.push_back(make_pair(c,j));
            }
            else odds.push_back(make_pair(c,j));
        }
        sort(all(evens));
        sort(all(odds));
        vector<pair<int,int>> w;
        REP(j,N){
            if(j%2 == 0) w.push_back(evens[j/2]);
            else w.push_back(odds[j/2]);
        }
        if(!is_monotone_increasing(w)) continue;
        ans = min(ans, inversion(w));
    }
    cout << (ans==1<<29 ? -1 : ans) << endl;
}

