int bubbleSort(vector <pair <int, int > >& c, int ptn)
{
	int num = 0;

	const int N = SZ(c);

	for (int k = 0; k < N - 1; ++k)
	{
		bool checkK = (abs(c[k].second - k) % 2 == 0) ^ IsBit(ptn, k);
		if (checkK && c[k].first == c[k + 1].first)
		{
			swap(c[k], c[k + 1]);
			num++;
		}
	}

	for (int i=0;i<N - 1;i++)
	{
		for (int k = N-1; k >= i+1; --k)
		{
			if (c[k].first < c[k - 1].first)
			{
				swap(c[k], c[k - 1]);
				num++;
			}
		}
	}


	return num;
}





