using namespace std;

struct Card
{
	int a, b;
	int oriPos;
	bool isUsed;
};
Card cards[20];
Card newCards[20];
int n;
int minSteps;

void swap(int a[], int i, int j) {
	int temp;
	temp = a[i];
	a[i] = a[j];
	a[j] = temp;
}

//计算步数的过程，本质是一个冒泡排序的过程
int calcSteps(Card cards[]) {
	int step = 0;
	int a[20];	//简便起见，我们不去尝试改变cards里面的位置，而只是调整索引 
	for (int i = 0 ; i < n ; i++) {
		a[i] = cards[i].oriPos;
	}

	for (int i = 0 ; i < n - 1 ; i++) {
		for (int j = 0 ; j < n - i - 1 ; j++) {
			if (a[j] > a[j + 1]) {
				swap(a, j, j + 1);
				step++;
			}
		}
	}

	return step;
}

void doGenerate(int depth, int curNum) {
	if (depth == n) {
		int curSteps = calcSteps(newCards);
		if ((minSteps == -1) || (minSteps > curSteps))
			minSteps = curSteps;
	} else {
		int newNum;
		for (int i = 0 ; i < n ; i++) {
			if (true == cards[i].isUsed)
				continue;
			if ((cards[i].oriPos % 2) == (depth % 2))
				newNum = cards[i].a;
			else
				newNum = cards[i].b;

			if (curNum > newNum)
				continue;

			newCards[depth].a = newNum;
			newCards[depth].oriPos = cards[i].oriPos;
			cards[i].isUsed = true;
			doGenerate(depth + 1, newNum);
			cards[i].isUsed = false;
		}
	}
}

int main()
{
	scanf("%d", &n);

	for (int i = 0 ; i < n ; i++)
	{
		scanf("%d", &(cards[i].a));
		cards[i].oriPos = i;
		cards[i].isUsed = false;
	}

	for (int i = 0 ; i < n ; i++)
		scanf("%d", &(cards[i].b));

	minSteps = -1;

	doGenerate(0, -1);


	printf("%d\n", minSteps);


	return 0;
}

