inline ll bpow(ll a, ll d, ll mod) 
{
	ll res = 1, p = a;
	while (d != 0)
	{
		if (d & 1)
		{
			res *= p;
			res %= mod;
		}
		p = (p * p) % mod;
		d >>= 1;
	}

	return res;
}
