	for (int i = 0; i < n; ++i)
		dp[(1 << i)][i] = i;

	for (int i = 1; i < (1 << n); ++i)
	{
		int cnt = popcnt(i);
		for (int j = 0; j < n; ++j)
			if ((i & (1 << j)) && dp[i][j] == -1)
			{
				dp[i][j] = INF;
				int umask = i & ~(1 << j);
				int shift = abs(cnt - 1 - j);
				for (int k = 0; k < n; ++k)
					if ((umask & (1 << k)) && value(v, j, cnt - 1) >= value(v, k, cnt - 2))
						dp[i][j] = min(dp[umask][k] + shift, dp[i][j]);
			}
	}

	int ans = INF;

	for (int i = 0; i < n; ++i)
		if (dp[(1 << n) - 1][i] != -1)
			ans = min(ans, dp[(1 << n) - 1][i]);

	if (ans < INF)
		cout << ans / 2;
	else
		cout << -1;
}

