        bit.add(cc.mp[a[N-1-j]],1);
        rev += (j-bit.sum(cc.mp[a[N-1-j]]));
      }else{
        bit.add(cc.mp[b[N-1-j]],1);
        rev += (j-bit.sum(cc.mp[b[N-1-j]]));
      }
    }
    if(rev==(c+1)||rev==(N-c-1)){ 
      ans = min(ans,rev); 
    }else{
      continue; 
    }
  }
  if(ans == 1e9){ 
