constexpr int I_INF = numeric_limits<int>::max();
constexpr ll L_INF = numeric_limits<ll>::max();

//==================================

int N;
Vi A, B;
int dp[(1 << 18) + 1][20];

int bit_dp(int bit, int v) {
    // メモ済みならメモの値を返す
    if (dp[bit][v] != -1) {
        return dp[bit][v];
    }

    // 初期値
    if (bit == (1 << v)) {
        return dp[bit][v] = 0;
    }

    int res = I_INF;

    int prev_bit = bit & ~(1 << v);
    int v_pos = __builtin_popcount(bit) - 1;  // v番目のカードがおかれる位置
    int v_val;
    // v番目のカードの表の値を求める
    if (abs(v_pos - v) & 1) {
        v_val = B[v];
    }
    else {
        v_val = A[v];
    }

    for (int u = 0; u < N; u++) {
        // prev_bit に u が無かったら飛ばす
        if (!(prev_bit & (1 << u))) continue;

        // u番目とカードの表の値を求める
        int u_pos = v_pos - 1;
        int u_val;
        if (abs(u_pos - u) & 1) {
            u_val = B[u];
        }
        else {
            u_val = A[u];
        }
        if (u_val > v_val) continue;  // 広義単調増加出なければ飛ばす

        // v番目のカードを追加することによる転倒数の増分を求める
        int dtento = 0;
        for (int k = 0; k < N; k++) {
            if (!(prev_bit & (1 << k))) continue;
            if (k > v) ++dtento;
        }

        if (bit_dp(prev_bit, u) != I_INF)
            res = min(res, bit_dp(prev_bit, u) + dtento);
    }

    return dp[bit][v] = res;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    cin >> N;
    A.resize(N), B.resize(N);
    for (int i = 0; i < N; i++) {
        cin >> A[i];
    }
    for (int i = 0; i < N; i++) {
        cin >> B[i];
    }

    for (int i = 0; i < (1 << N); i++) {
        for (int j = 0; j < N; j++) {
            dp[i][j] = -1;
        }
    }

    int ans = I_INF;
    for (int i = 0; i < N; i++) {
        ans = min(ans, bit_dp((1 << N) - 1, i));
    }

    if (ans == I_INF) {
        ans = -1;
    }

    cout << ans << endl;

    return 0;
}

