    for(int i = 2; i <= n; i++) 
    {
        if(a[i] < a[i-1]) return false;
    }
    return true;
}

void dfs(int xz,int res)
{
    if(judge())
    {
        ans = min(ans,res);
        return;
    }
    for(int i = xz; i <= n-1; i++)
    {
        swap(a[i],b[i+1]);swap(a[i+1],b[i]);
        dfs(i+1,res+1);
        swap(a[i],b[i+1]);swap(a[i+1],b[i]);
    }
}

