void dpseeker(std::vector<std::vector<int>>& dp, int& n, int bitmask, int size, int last, std::vector<int>& a, std::vector<int>& b)
{
    if (size == 0) {
        for (int i = 0; i < n; i++) {
            int nextmask = (1 << i);
            int val = (abs(i - size) % 2 == 0) ? a[i] : b[i];
            chmin(dp[nextmask][val], (int)0);
            dpseeker(dp, n, nextmask, size + 1, val, a, b);
        }
    } else if (size == n) {
        ;
    } else {
        for (int i = 0; i < n; i++) {
            if ((bitmask & (1 << i)) == (1 << i)) {
                continue;
            }
            int nextmask = (bitmask | (1 << i));
            int val = (abs(i - size) % 2 == 0) ? a[i] : b[i];
            if (val < last) {
                continue;
            }
            int count = 0;
            for (int j = i + 1; j < n; j++) {
                if ((nextmask & (1 << j)) == (1 << j)) {
                    count++;
                }
            }
            if (dp[nextmask][val] < dp[bitmask][last] + count) {
                continue;
            }
            chmin(dp[nextmask][val], dp[bitmask][last] + count);
            dpseeker(dp, n, nextmask, size + 1, val, a, b);
        }
    }
}


signed main()
{
    int n;
    cin >> n;
    std::vector<int> a(n);
    std::vector<int> b(n);
    std::vector<std::vector<int>> dp(((int)1 << n), std::vector<int>(51, MOD));
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }
    for (int i = 0; i < n; i++) {
        cin >> b[i];
    }
    dpseeker(dp, n, 0, 0, 0, a, b);
    int out = MOD;
    for (int i = 0; i < 51; i++) {
        chmin(out, dp[(1 << n) - 1][i]);
    }
    if (out == MOD) {
        cout << -1 << endl;
    } else {
        cout << out << endl;
    }
    return 0;
}

