			if (buf[j].F > buf[j+1].F) {
				swap(buf[j],buf[j+1]);
				buf[j].S = 1-buf[j].S;
				buf[j+1].S = 1-buf[j+1].S;
				cnt++;
			}
		}
		}

		rep(c,0,N+1) {
		rep(j,0,N-1) {
