using namespace std;
typedef long long ll;
typedef pair<int, int> P;
int N;
int A[18], B[18];
int C[18];
int cnt[18];
int cnt_same[51];
int cnt_inv[51];
vector<int> v[51];
P p[18];

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout << setprecision(10) << fixed;
    cin >> N;
    for(int i = 0; i < N; i++){
        cin >> A[i];
    }
    for(int i = 0; i < N; i++){
        cin >> B[i];
    }
    int ans = 100000;
    for(int i = 0; i < (1<<N); i++){
        int tmp = 0;
        for(int j = 1; j <= 50; j++) {
            cnt_same[j] = 0;
            cnt_inv[j] = 0;
            v[j].clear();
        }
        for(int j = 0; j < N; j++){
            if(i&(1<<j)) C[j] = B[j];
            else C[j] = A[j];
            p[j] = P(C[j], j);
            cnt_same[C[j]]++;
        }
        sort(p, p+N);
        for(int j = 0; j < N; j++) {
            cnt[j] = 0;
        }
        for(int j = 0; j < N; j++){
            for(int k = j+1; k < N; k++){
                if(p[j].second > p[k].second) {
                    cnt[p[j].second]++;
                    cnt[p[k].second]++;
                    tmp++;
                }
            }
        }

        for(int j = 0; j < N; j++){
            if(i&(1<<j)){
                if(cnt[j]%2 == 0) {
                    cnt_inv[C[j]]++;
                    v[C[j]].push_back(1);
                }else{
                    v[C[j]].push_back(0);
                }
            }else{
                if(cnt[j]%2 == 1) {
                    cnt_inv[C[j]]++;
                    v[C[j]].push_back(1);
                }else{
                    v[C[j]].push_back(0);
                }
            }
        }

        bool ok = true;
        for(int j = 1; j <= 50; j++){
            if(cnt_inv[j]%2 == 1) ok = false;
            else {
                int cur = 0;
                int state = 0;
                for(int k = 0; k < v[j].size(); k++){
                    if(v[j][k] == 0){
                        if(state == 0){}
                        else{
                            cur++;
                        }
                    }else{
                        if(state == 0){
                            state = 1;
                        }
                        else{
                            cur++;
                            state = 0;
                        }
                    }
                }
                if(state == 1) return -1;
                tmp += cur;
            }
        }
        if(ok) ans = min(ans, tmp);
    }
    if(ans >= 100000){
        cout << -1 << endl;
    }else{
        cout << ans << endl;
    }
}

