struct Card {
    int v;
    int r;
    int b;
    int i;
    bool operator<(const Card &other) const {
        pii a = make_pair(other.v, other.i);
        pii b = make_pair(v, i);
        return a > b;
    } 
};

int minswaps(vector<Card> a, vector<Card> b) {
    int nswaps = 0;
    int seen[22]; memset(seen, 0, sizeof seen);
    for (int i = 0; i < b.size(); i++) {
        if(!seen[i]) {
            int j = i;
            while (a[j].i != i) {
                j = a[j].i;
                seen[j] = 1;
                nswaps +=1;
            }
        }
    }
    return nswaps;
}
