            }
        }
        sort(t.begin(), t.end());

        bool possible = true;



        int prev = t[0].v;
        int i = 0;
        while(i < n) {
            vector<Card> odd, even;
            int oddcnt = 0;
            int evencnt = 0;
            int start = i;
            while(i < n and prev == t[i].v) i++;

            int end = i;

            end--;

            for(int j = start ; j <= end; j++) {
                // if(mask == 0) cout << t[j].i << " " <<  j << endl;
                if(t[j].i % 2 == 1) {
                    if(mask & (1<<j))
                        even.push_back(t[j]);
