#include <bits/stdc++.h>
using namespace std;
const int MAXN=60;
int N,Ans,A[MAXN],B[MAXN],C[MAXN],pos[MAXN];
bool Mark[MAXN],flag[MAXN];
void solve()
{
	int sum=0;
	for (int i=1;i<=N;++i) Mark[i]=false,pos[i]=i;
	for (int i=1;i<=N;++i)
	{
		int p=i;
		for (int j=i+1;j<=N;++j)
			if (C[j]<C[p])
				p=j;
		if (p>i)
		{
			sum+=p-i;
			for (int j=p;j>=i;--j) Mark[pos[j]]^=1;
			for (int j=p;j>i;--j)
			{
				swap(C[j],C[j-1]);
				swap(pos[j],pos[j-1]);
			}
		}
	}
	for (int i=1;i<=N;++i)
		if (Mark[pos[i]]!=flag[pos[i]])
		{
			if (i==N) return ;
			if (C[i]==C[i+1])
			{
				Mark[pos[i+1]]^=1;
				++sum;
			}
			else return ;
		}
	/*
	printf("c=");
	for (int i=1;i<=N;++i) printf("%d ",C[i]);cout<<endl;
	for (int i=1;i<=N;++i) printf("%d ",flag[i]);cout<<endl;
	cout<<sum<<endl;
	*/
	if (Ans==-1) Ans=sum;
	else Ans=min(Ans,sum);
}
void dfs(int x)
{
	if (x==N+1)
	{
		for (int i=1;i<=N;++i) C[i]=(flag[i]?B[i]:A[i]);
		solve();
		return ;
	}
	flag[x]=true;
	dfs(x+1);
	flag[x]=false;
	dfs(x+1);
}
int main()
{
	cin>>N;
	for (int i=1;i<=N;++i) cin>>A[i];
	for (int i=1;i<=N;++i) cin>>B[i];
	Ans=-1; 
	dfs(1);
	cout<<Ans<<endl;
	return 0;
}

