int dfs(int hav, int ma,int cnt)
{
	if(cnt == n) return 0;
	if(dp[hav][ma] != -1) return dp[hav][ma];
	dp[hav][ma] = 10086;
	int dx,ans,tot = 0;
	for(int i = 0; i < n;i ++){
