				else last = B[k]; 
				if(last >= j) dp[i + (1 << k)][last] = min(dp[i + (1 << k)][last], dp[i][j] + used[k] - pop); 
			}			
		}
	}
	int ans = INF; 
	for(int k = 0; k <= 50; k++){
		ans = min(ans, dp[(1 << N) - 1][k]); 
	}
