	    dp[msk][i] = inf;
    }
    for(int msk = 1; msk < (1<<n); msk++){
	int SZ = __builtin_popcount(msk);
	if(SZ == 1){
	    int id = __builtin_ctz(msk);
	    dp[msk][id] = 0;
