	    for(int j = 0; j < n; j++){
		if(bit(msk, j) && i != j){
		    if(a[(i ^ 1 ^ SZ) &1][i] < a[(j ^ SZ) &1][j])
			continue;
		    dp[msk][i] = min( dp[msk][i], dp[msk ^ (1<<i)][j] + SZ - 1 - cnt );
		}
	    }
	    cnt++;
	}
    }
    int ans = inf;
    for(int i = 0; i < n; i++)
	ans = min(ans, dp[(1<<n)-1][i]);
