int N, A[18], B[18], ans = INT_MAX;

void dfs(vector<int> vec, int count){
    if(count < N-1){
        for(int i=0;i<N-1;i++){
            swap(vec[i], vec[i+1]);
            vec[i] = vec[i]*-1;
            vec[i+1] = vec[i+1]*-1;
            dfs(vec, count+1);
            vec[i] = vec[i]*-1;
            vec[i+1] = vec[i+1]*-1;
            swap(vec[i], vec[i+1]);
        }
    }
    for(int i=0;i<N-1;i++){
        int l, r;
        if(vec[i] > 0)
            l = A[vec[i]-1];
        else
            l = B[abs(vec[i])-1];
        if(vec[i+1] > 0)
            r = A[vec[i+1]-1];
        else
            r = B[abs(vec[i+1])-1];
        if(l > r)
            return;
    }
    if(count < ans)
        ans = count;
}

