                } else {
                    L = B[i];
                }

                if (abs(n + __pop_count(n_mask)) % 2 == 0) {
                    R = A[n];
                } else {
                    R = B[n];
                }
                if (L > R) {
                    continue;
                }



                Int cost = 0;

                for (int j = 0; j < i; ++j) {
                    if (!(mask >> j & 1)) {
                        cost++;
                    }
                }

                Int tmp = rec(i, n_mask) + cost;
                chmin(ret, tmp);
            }
        }

        return dp[n][mask] = ret;
    }

    void solve() {
        cin >> N;
        A.resize(N);
        B.resize(N);

        for (int i = 0; i < N; ++i) {
            cin >> A[i];
        }
        for (int i = 0; i < N; ++i) {
            cin >> B[i];
        }

        dp.resize(N, vector<Int>(1 << N, -1));

        Int ans = INFl;
        for (int i = 0; i < N; ++i) {
            Int tmp = rec(i, (1ull << N) - 1);
            chmin(ans, tmp);
        }

        if (ans == INFl) {
            cout << -1 << endl;
            return;
        }

        cout << ans << endl;


    }
};


int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(10);

    Solve().solve();


    return 0;
}

