        rep (idx, n) if (ptn & (1LL<<idx)) {
            idxptn.set(idx);
            idxcnt++;
        }
        if (ptn == 10LL) debug_printf("idxcnt=%lld\n", idxcnt);
        if (idxcnt != n/2LL) continue;
        if (ptn == 10LL) debug_printf("xx1\n");

        V<t2> odd_validxs;
        rep (i, n) if (idxptn.test(i)) odd_validxs.pb(t2(oddlist[i], i));
        sort(odd_validxs);

        V<t2> even_validxs;
        rep (i, n) if (!idxptn.test(i)) even_validxs.pb(t2(evenlist[i], i));
        sort(even_validxs);

        if (ptn == 10LL) {
            debug_printf("odd_validxs\n");
            debug_print(odd_validxs);
            debug_printf("even_validxs\n");
            debug_print(even_validxs);
        }

        V<t2> validxs;
        rep (i, n) {
            if (i & 1LL) validxs.pb(odd_validxs[i/2]);
            else validxs.pb(even_validxs[i/2]);
        }

        ll prev = -1LL;
        bool ng = false;
        for (auto validx : validxs) {
            ll val = get<0>(validx);
            if (val < prev) {
                ng = true;
                break;
            }
            prev = val;
        }

        if (ptn == 10LL) debug_printf("xx5\n");
        if (ng) continue;
        if (ptn == 10LL) debug_printf("xx6\n");

        ll total = 0LL;
        tree.init(0LL);
        if (ptn == 10LL) debug_printf("sum1=%lld\n", tree.sum(1LL));
        if (ptn == 10LL) debug_printf("sum2=%lld\n", tree.sum(2LL));
        if (ptn == 10LL) debug_printf("sum3=%lld\n", tree.sum(3LL));
        if (ptn == 10LL) debug_printf("sum4=%lld\n", tree.sum(4LL));
        for (auto validx : validxs) {
            ll idx = get<1>(validx);
            if (ptn == 10LL) debug_printf("  idx=%lld\n", idx);
            total += (tree.sum(20LL) - tree.sum(idx + 1LL));
            tree.add(idx + 1LL, 1LL);
        }

        if (ptn == 10LL) debug_printf("  total=%lld\n", total);
        ans = min(ans, total);
    }

    if (ans >= 1e17) cout << -1 << endl;
    else cout << ans << endl;
}

