	FOR(s,0,(1<<N)){
		vector<int> zero,one;
		vector<pair<int,int>> onex,zerox;
		int invcount = 0;
		FOR(i,0,N)if(s&(1<<i))invcount++;
		if(invcount%2) continue;
		FOR(i,0,N){
			if(s&(1<<i)){//裏返す
				if(i&1){
					zero.push_back(i);
					zerox.push_back({B[i],i});
				}else{
					one.push_back(i);
					onex.push_back({B[i],i});
				}
			}else{//裏返さない
				if(i&1){
