int dyn[MASK][LIM];

int recurse(int mask, int last, int idx) {
    if (idx >= n)
        return 0;
    int& ans = dyn[mask][last];
    if (ans != -1)
        return ans;

    ans = INF;

    vector <int> parity(n, 0);
    int cur = 0;
    for (int i = n - 1; i >= 0; i--) {
        cur ^= !!(mask & (1 << i));
        parity[i] = cur;
    }

    int dist = 0;
    for (int i = 0; i < n; i++) if (!(mask & (1 << i))) {
        int side = parity[i] ^ (dist % 2);
        if (a[i][side] >= last) {
            ans = min(ans, recurse(mask | (1 << i), a[i][side], idx + 1) + dist);
        }
        dist++;
    }

    return ans;
}

int solve() {
    memset(dyn, -1, sizeof(dyn));
    int ans = recurse(0, 0, 0);
    return ans >= INF ? -1 : ans;
}

