int d2i(int bi, int usd){
    int id = bi;
    id *= (1<<n); id += usd;
    return id;
}

int f(int bi, int usd){
    if(usd == ((1<<n)-1)) return 0;
    int id = d2i(bi, usd);
    if(dp[id] != -1) return dp[id];
    int res = n*n, t = 0, s= 0;
    for(int i=0;i<n;i++) t += ((usd>>i)&1);
    for(int i=n-1;i>=0;i--){
        if(((usd>>i)&1) == 0){
            if(t > 0){
                int iv, bv;
                if((t+i)%2 == 0) iv = a[i];
                else iv = b[i];
                if((t+bi)%2 == 1) bv = a[bi];
                else bv = b[bi];

                if(iv < bv) continue;
            }
            int u = abs(i-t)-s;
            u += f(i, usd | (1<<i));
            if(res > u) res = u;
        }else{
            s++;
        }
    }

    return dp[id] = res;
}

