sint card_num(uint8_t card, vector<sint> const& As, vector<sint> const& Bs) {
	if ((card & 0x80) == 0) {
		return As[card & 0x7f];
	}
	else {
		return Bs[card & 0x7f];
	}
}

bool is_sorted(vector<uint8_t> const& cards, vector<sint> const& As, vector<sint> const& Bs) {
	for (sint i = 0; i < isize(cards) - 1; ++i) {
		if (card_num(cards[i], As, Bs) > card_num(cards[i + 1], As, Bs)) {
			return false;
		}
	}
	return true;
}


sint foo(vector<uint8_t> const& init_cards, vector<sint> const& As, vector<sint> const& Bs) {
	queue<pair<vector<uint8_t>, sint>> q;
	set<vector<uint8_t>> mark;

	q.push(make_pair(init_cards, 0));
	mark.insert(init_cards);

	while(!q.empty()) {
		vector<uint8_t> cards = q.front().first;
		sint n = q.front().second;
		q.pop();

		if (is_sorted(cards, As, Bs)) {
			return n;
		}
		for (sint i = 0; i < isize(cards) - 1; ++i) {
			vector<uint8_t> next_cards = cards;
			swap(next_cards[i], next_cards[i + 1]);
			next_cards[i] ^= 0x80;
			next_cards[i + 1] ^= 0x80;

			if (mark.find(next_cards) == mark.end()) {
				mark.insert(next_cards);
				q.push(make_pair(move(next_cards), n + 1));
			}
		}
	}

	return -1;
}

void run() {
	sint N; cin >> N;
	vector<sint> As(N); cin >> As;
	vector<sint> Bs(N); cin >> Bs;

	vector<uint8_t> cards;
	for (sint i = 0; i < N; ++i) {
		cards.push_back(i);
	}

	sint score = foo(cards, As, Bs);
	cout << score << endl;
}

