        int pre = abs(j - (now - 1)) % 2 == 0 ? A[j] : B[j];
        int cur = abs(k - now) % 2 == 0 ? A[k] : B[k];
        if(pre <= cur) chmin(dp[i | (1 << k)][k], dp[i][j] + add);
        ++add;
      }
    }
  }
  int ret = inf;
  for(int i = 0; i < N; i++) chmin(ret, dp[(1 << N) - 1][i]);
  if(ret >= inf) ret = -1;
  cout << ret << endl;
