const int INF = 100000000;

int dp[1 << 18][50 + 5];

int main() {
	cin >> N;
	for (int i = 0; i < N; i++)cin >> A[i];
	for (int i = 0; i < N; i++)cin >> B[i];

	for (int i = 0; i < (1 << N); i++)for (int j = 0; j <= 50; j++)dp[i][j] = INF;

	dp[0][0] = 0;
	for (int bit = 0; bit < (1 << N); bit++) {
		int nowpos = 0;
		for (int i = 0; i < N; i++)
			if ((bit >> i) & 1)nowpos++;
		for (int i = 0; i <= 50; i++) {
			if (dp[bit][i] == INF)continue;
			for (int j = 0; j < N; j++) {
				if ((bit >> j) & 1)continue;
				int target = (j - nowpos + 100) % 2 == 0 ? A[j] : B[j];
				if (target >= i) {
					dp[bit | (1 << j)][target] = min(dp[bit | (1 << j)][target], dp[bit][i] + abs(j - nowpos));
				}
			}
		}
	}
	int ans = INF;
	for (int i = 0; i <= 50; i++) {
		ans = min(ans, dp[(1 << N) - 1][i]);
	}
	if (ans == INF)cout << -1 << endl;
	else cout << ans / 2 << endl;
