void make(int st) {
	for(int i=0; i<N; i++) {
		if((1 << i) & st) {
			isodd[i+1] = 1;
			int cur = i + 1;
			if(cur % 2) arr[cur] = A[cur];
			else arr[cur] = B[cur];
		} 
		else {
			isodd[i+1] = 0;
			int cur = i + 1;
			if(cur % 2 == 0) arr[cur] = A[cur];
			else arr[cur] = B[cur];
		}
	}
}

bool chk() {
	vector<int> o, e;
	for(int i=1; i<=N; i++) {
		if(isodd[i]) o.push_back(arr[i]);
		else e.push_back(arr[i]);
	}

	sort(o.begin(), o.end());
	sort(e.begin(), e.end());
	int a=0, b=0;
	vector<int> v;
	for(int i=1; i<=N; i++) {
		if(i % 2) v.push_back(o[a++]);
		else v.push_back(e[b++]);
	}
	for(int i=1; i<v.size(); i++) if(v[i-1] > v[i]) return 0;

	memset(num, 0, sizeof(num));

	for(int i=1; i<=50; i++) {
		int idx = lower_bound(v.begin(), v.end(), i) - v.begin() + 1;
