		if(idx % 2) {
			num[i][0] = 2;
			num[i][1] = 1;
		}
		else {
			num[i][0] = 1;
			num[i][1] = 2;
		}
	}

	for(int i=1; i<=N; i++) {
		arr2[i]	= num[arr[i]][i%2];
		num[arr[i]][i%2] += 2;
	}

	return 1;
}

int cnti() {
	int cnt = 0;
	for(int i=1; i<=N; i++) {
		for(int j=i+1; j<=N; j++) {
			if(arr[j] < arr[j-1]) {
				swap(arr[j], arr[j-1]);
				swap(arr2[j], arr2[j-1]);
				cnt++;
			}
			else if(arr[j-1] == arr[j] && arr2[j] < arr2[j-1]) {
				swap(arr[j], arr[j-1]);
				swap(arr2[j], arr2[j-1]);
				cnt++;
			}
		}
	}
	return cnt;
}

