vector <pair<int,int> > ima_swap(vector <pair<int,int> > ima, int i)
{
    int a[2],b[2];

    a[0] = ima[i].first;
    b[0] = ima[i].second;

    a[1] = ima[i+1].first;
    b[1] = ima[i+1].second;

    ima[i].first = b[1];
    ima[i].second = a[1];

    ima[i+1].first = b[0];
    ima[i+1].second = a[0];

    return ima;
}

bool tancyo(vector <pair<int,int> > ima)
{
    bool isOK = true;
    for(int i = 0; i < ima.size()-1; ++i)
    {
        if(ima[i].first > ima[i+1].first)
        {
            isOK = false;
            break;
        }
    }

    return isOK;
}

int iMin = 40;

int dfs(vector <pair<int,int> > ima, int cnt,int mae)
{
    if(cnt >= iMin)return 0;

    if(tancyo(ima))
    {
        iMin = min(iMin, cnt);
        return 0;
    }

    //入れ替えてみる
    for(int i = 0; i < ima.size()-1;++i)
    {
        if(mae == i)continue;
        if(mae != -1 && i + 2 <= mae)continue;

        dfs(ima_swap(ima, i), cnt + 1, i);
    }

    return 0;

}

