int N;
int A[18];
int B[18];
int C[18];
int sub(int s) {
	int odd = 0;
	int even = 0;
	REP(k, 0, N) {
		if ((s >> k) & 1) {
			++(k % 2 == 0 ? even : odd);
		}
	}

	if (even != odd) return INF;

	vector<int> sorted;
	vector<int> original;

	REP(k, 0, N) {
		bool flip = (s >> k) & 1;
		if (flip) {
			C[k] = B[k];
		} else {
			C[k] = A[k];
		}

		original.push_back(C[k]);
		sorted.push_back(C[k]);
	}
	sort(sorted.begin(), sorted.end());

	vector<bool> used(N, false);
	vector<int> perm(N);
	REP(i, 0, N) {
		int parity = (i % 2) ^ ((s >> i) & 1);
		int p = -1;
		REP(k, 0, N) {
			if (used[k]) continue;
			if (sorted[k] != original[i]) continue;
			if (k % 2 != parity) continue;
			p = k;
			break;
		}

		if (p == -1) return INF;
		used[p] = true;
		perm[i] = p;
	}

	int cnt = 0;
	REP(i, 0, N) {
		REP(j, i + 1, N) {
			if (perm[i] > perm[j]) ++cnt;
		}
	}
	return cnt;
}

