int main() {
    int N;
    cin >> N;
    vector<int> A(N);
    vector<int> B(N);
    rep(i, N) cin >> A[i];
    rep(i, N) cin >> B[i];

    // シャッフル番号
    vector<int> v(N);
    iota(v.begin(), v.end(), 0);

    int ans = 1e9;

    do {
        bool visOK = true;
        for (int i = 1; i < N; i++) {
            // v[i]はシャッフルされる前のカード番号
            // i はシャッフルされた後のカード番号
            bool isXomote = abs(v[i - 1] - (i - 1)) % 2 == 0;
            bool isYomote = abs(v[i] - i) % 2 == 0;
            int X         = isXomote ? A[v[i - 1]] : B[v[i - 1]];
            int Y         = isYomote ? A[v[i]] : B[v[i]];
            if (Y - X >= 0) {
                continue;
            } else {
                visOK = false;
            }
        }

        if (visOK) {
            int count = 0;
            vector<int> a(N);
            // 配列PをAにコピーする
            copy(all(v), a.begin());
            rep(i, N-1) for(int j=N-1;j>i;j--) {
                if (a[j] < a[j - 1]) {
                    int t    = a[j];
                    a[j]     = a[j - 1];
                    a[j - 1] = t;
                    count++;
                }
            }
            ans = min(ans, count);
        }
    } while (next_permutation(v.begin(), v.end()));

    if (ans == 1e9)
        cout << -1 << endl;
    else
        cout << ans<< endl;
}

