int dfs(int n,int z,int prev, int nwans){
  //dfs????
  int ans = -1;
  if(n+1==z){
    return nwans;
    int ans = 0;
    int M = 0;
    vector<int> hak(n);
    for(int i = 0; n > i; i++){
      hak[i] = nya[i];
    }
    for(int i = 1; n >= i; i++){
      for(int j = 0+M; n > j; j++){
        if(i == hak[j-M]){
          ans += (j+1)-i;
          hak.erase(hak.begin()+(j-M));
          break;
        }
      }
      M++;
    }
    hak.clear();
    return ans;
  }
  int nwnwans;
  for(int i = 0; n > i; i++){
    nwnwans = nwans+abs(z-(i+1));
    //cout << z << " " << i << " " << z-(i+1) << endl;
    if(nw.find(i) != nw.end())continue;
    if(prev > (z%2?od[i].second:ev[i].second))continue;
    nw.insert(i);
    nya.push_back(i+1);
    int KK = dfs(n,z+1,(z%2?od[i].second:ev[i].second),nwnwans);
    if(ans == -1)ans = KK;
    else if(KK != -1) ans = min(ans,KK);
    //cout <<z << " " << i  << " " << ans << endl;
    if(nwnwans > ans && ans != -1)return ans;
    nya.pop_back();
    nw.erase(i);
  }
  return ans;
}
