template<class T> class segtree {
    int n = 1;
    vector<T> dat;
    T def;

public:
    segtree(int _n, T _def) : def(_def) {
        while (n < _n)n *= 2;
        dat.resize(2 * n, def);
    }

    T fun(T x, T y) { return x + y; }

    void update(int i, T a) {
        i += n;
        dat[i] += a;
        while (i > 1) {
            i /= 2;
            dat[i] = fun(dat[2 * i], dat[2 * i + 1]);
        }
    }

    T value(int l, int r) {
        l += n, r += n;

        T ret = def;
        for (; l < r; l /= 2, r /= 2) {
            if (l & 1) {
                ret = fun(ret, dat[l]);
                l++;
            }
            if (r & 1) {
                --r;
                ret = fun(ret, dat[r]);
            }
        }

        return ret;
    }
};

int main() {
    init();

    int n; cin >> n;
    VI a(n), b(n); cin >> a >> b;
    FOR(i, 0, n)--a[i], --b[i];

    int m = (n + 1) / 2, k = n - m, ans = INF;
    FOR(bit, 0, 1 << n) {
        VI x, y;
        FOR(i, 0, n){
            if (bit & (1 << i))x.push_back(i);
            else y.push_back(i);
        }
        if (x.size() != m)continue;

        VI v(n), z(n);
        vector<pair<int,int>> d(m), f(k);
        FOR(i, 0, m)d[i] = { (x[i] % 2 == 0 ? a[x[i]] : b[x[i]]), x[i] };
        FOR(i, 0, k)f[i] = { (y[i] % 2 == 1 ? a[y[i]] : b[y[i]]), y[i] };
        SORT(d), SORT(f);
        FOR(i, 0, m) {
            v[i * 2] = d[i].second;
            z[i * 2] = d[i].first;
        }
        FOR(i, 0, k) {
            v[i * 2 + 1] = f[i].second;
            z[i * 2 + 1] = f[i].first;
        }

        int cnt = 0;
        segtree<int> seg(n, 0);
        FOR(i, 0, n) {
            cnt += seg.value(v[i] + 1, n);
            seg.update(v[i], 1);
        }

        bool ng = false;
        FOR(i, 0, n - 1)ng |= z[i] > z[i + 1];
        if (!ng)chmin(ans, cnt);
    }

    cout << (ans == INF ? -1 : ans) << "\n";
}

