void Main() {
    ll N; cin>>N;
    vector<ll> A(N);
    vector<ll> B(N);
    rep(i,N) cin>>A[i];
    rep(i,N) cin>>B[i];
    ll ans=INF;
    rep(i,1<<N){
        vector<ll> tyo(N);
        bool gu[N]={};
        ll ct=0;
        rep(j,N){
            if(i>>j&1){
                tyo[j]=A[j];
                gu[j]=true;
            }
            else{
                tyo[j]=B[j];
                ++ct;
            }
        }
        if(ct%2==1) continue;
        auto moto=tyo;
        SORT(tyo);
        bool used[N]={};
        bool ok=true;
        ll buf=0;
        rep(j,N){ //jからkに移動
            rep(k,N){
                if(used[k]) continue;
                if(abs(k-j)%2==1 and gu[j]) continue;
                if(abs(k-j)%2==0 and !gu[j]) continue;
                if(moto[j]==tyo[k]){
                    used[k]=true;
                    buf+=abs(j-k);
                    break;
                }
            }
        }
        buf/=2;
        rep(j,N) if(used[j]==false) ok=false;
        if(ok) mini(ans,buf);
    }

    cout<< ( ans==INF ? -1 : ans )<<"\n";

}

