	rep( i, 1, n ) a[i] = gi() ; 
	rep( i, 1, n ) b[i] = gi() ;
	dfs( 1 ) ;
	if( Ans >= inf ) puts("-1") ;
	else cout << Ans / 2 << endl ; 
	return 0 ;
}

