				for(int k=j+1;v[k].F==v[j].F;k++){
					if(abs(j-v[k].S)%2==use[v[k].S]){
						for(int l=k;l>j;l--){
							swap(v[l].S,v[l-1].S);
						}
					}
				}
			}
			f(k,n){
				if(zz[k]==v[j].S){
					vj=k;
					break;
				}
