int dp[20][51][262144];
int bcs[262144];

void chmin(int& a, int b) {
	a = min(a, b);
}

int main() {
	int N, n;
	cin >> N;
	n = N / 2;
	vector<int> A(N), B(N);
	for (int i = 0;i < N;i++) {
		cin >> A[i];
	}
	for (int i = 0;i < N;i++) {
		cin >> B[i];
	}
	for (int i = 0;i < 20;i++) {
		for (int k = 0;k < 51;k++) {
			for (int j = 0;j < 262144;j++) {
				dp[i][k][j] = INT32_MAX / 5;
			}
		}
	}

	dp[0][0][0] = 0;

	int bc = 0;
	for (int i = 0;i < 262144;i++) {
		bc = 0;
		for (int k = 0;k < 18;k++) {
			if (i & (1 << k))bc++;
		}
		bcs[i] = bc;
	}

	int obs[18], al = (1 << N);

	for (int i = 0;i < N;i++) {
		for (int mx = 0;mx <= 50;mx++) {
			for (int j = 0;j < al;j++) {
				if (bcs[j] != i)continue;

				if (dp[i][mx][j] > INT32_MAX / 6)continue;

				obs[0] = 0;
				for (int k = 0;k < N;k++) {
					if (j & (1 << k))obs[k + 1] = obs[k];
					else obs[k + 1] = obs[k] + 1;
				}

				for (int k = 0;k < N;k++) {
					if (j & (1 << k))continue;
					//cout << A[i] << " " << B[i] << " " << mx << " " << obs[k] << endl;
					if (abs(k - i) & 1) {
						if (B[k] >= mx) {
							chmin(dp[i + 1][B[k]][j | (1 << k)], dp[i][mx][j] + obs[k]);
						}
					}
					else {
						if (A[i] >= mx) {
							chmin(dp[i + 1][A[k]][j | (1 << k)], dp[i][mx][j] + obs[k]);
						}
					}
				}
			}
		}
	}
	int ans = INT32_MAX;
	for (int j = 0;j < (1 << N);j++) {
		for (int i = 0;i < 51;i++) {
			ans = min(dp[N][i][j], ans);
		}
	}
	if (ans > INT32_MAX / 6)cout << -1 << endl;
	else cout << ans << endl;
}

