    for(int i = 0; i < (1<<(n-1)); i++){
        a = ina, b = inb;
        for(int j = 0; j < n; j++){
            if(i&(1<<j)){
                swap(a[j], b[j+1]);
                swap(b[j], a[j+1]);
            }
        }
        int cnt = __builtin_popcount(i);
        //try greedy bubble sort for even and odd
        memset(done, 0, sizeof done);
        for(int k = 0; k < n+n; k++){
            for(int j = 0; j < n-2; j += 2){
                if(a[j] > a[j+2]){
                    swap(a[j], a[j+2]);
                    cnt += 3;
                    if((i&(1<<(j+1))) and !done[j+1]){
                        done[j+1] = 1;
                        cnt -= 2;
                    }
                }
            }
            for(int j = 1; j < n-2; j += 2){
                if(a[j] > a[j+2]){
                    swap(a[j], a[j+2]);
                    cnt += 3;
                    if((i&(1<<(j+1))) and !done[j+1]){
                        done[j+1] = 1;
                        cnt -= 2;
                    }
                }
            }
        }
