template<class T>bool chmin(T &a, const T &b) { if (b<a) { a=b; return 1; } return 0; }

bool dfs(int &m, int &n, VI &a, VI &b, int idx, int cnt) {
    /*
    cerr << idx << ", " << cnt << endl;
    REP(i,0,n) cerr << a[i] << " ";
    cerr << endl;
    REP(i,0,n) cerr << b[i] << " ";
    cerr << endl;
    */

    if (cnt > m) return false;
    if (idx == n) {
        return true;
    }
    REP(i,idx, n) {
        RREP(j,idx,i) {
            swap(a[j], b[j+1]);
            swap(b[j], a[j+1]);
        }
        bool isok = false;
        if (idx == 0 || a[idx] >= a[idx-1]) {
            bool bo = true;
            REP(j,idx+1,n) {
                if (a[idx] > max(a[j], b[j])) {
                    bo = false;
                    break;
                }
            }
            if (bo) {
                if (dfs(m,n,a,b,idx+1, cnt + i - idx)) {
                    isok = true;
                }
            }
        }
        REP(j,idx,i) {
            swap(a[j], b[j+1]);
            swap(b[j], a[j+1]);
        }
        if (isok) return true;
    }
    return false;
}

bool solve(int &m, int &n, VI &a, VI &b) {
    return dfs(m,n,a,b,0,0);
}

int meguru_bin(int &n, VI &a, VI &b) {
    int ok = (n * n - n) / 2 +1;
    int ng = -1;

    while (abs(ok - ng) > 1) {
        int mid = ng + (ok - ng) / 2;
        if (solve(mid,n,a,b)) ok = mid;
        else ng = mid;
    }

    return ok;
}

void solve() {
    int n;
    cin >> n;
    VI a(n), b(n);
    REP(i,0,n) cin >> a[i];
    REP(i,0,n) cin >> b[i];
    int ans = meguru_bin(n,a,b);

    cout << (ans == (n * n - n) / 2 +1 ? -1 : ans ) << endl;
}

signed main() {
    solve();

    return 0;
}

