	for(S = 0; S < (1 << N); S++){
		vector<pair<int, int>> V_eo(N);
		for(i = 0; i < N; i++){
			if((S | (1 << i)) == S){
				V_eo[i].first = B[i];
				V_eo[i].second = (i + 1) % 2;
			}
			else{
				V_eo[i].first = A[i];
				V_eo[i].second = i % 2;
			}
		}
		int f = 1;
		int now = inversion_number(V_eo.begin(), V_eo.end(), [](auto a, auto b){return a.first < b.first;});
		for(i = 0; i < N; i = j){
			for(j = i + 1; j < N && V_eo[j].first == V_eo[i].first; j++);
			int Ol[2] = {0, 0};
			vector<int> sub(j - i);
			for(k = i; k < j; k++){
