int main(){
	int n;
    cin>>n;
    vi a(n);
    vi b(n);
    dp=vii(51,vi(1<<n,mod));
    ex=vi(51,0);
    FOR(i,0,n){
        cin>>a[i];
        ex[a[i]]=1;
    }
    FOR(i,0,n){
        cin>>b[i];
        ex[b[i]]=1;
    }
    queue<pii> q;
    dp[0][0]=0;
    FOR(i,0,n){
        int f=0,t;
        if((i&1)==f){
            dp[a[i]][1<<i]=i;
            t=a[i];
        }else{
            dp[b[i]][1<<i]=i;
            t=b[i];
        }
        q.push(MP(t,1<<i));
    }
    while(q.size()){
        auto pr=q.front();
        q.pop();
        auto mx=pr.ST;
        auto st=pr.ND;
        //cerr<<mx<<" "<<bitset<20>(st)<<" "<<dp[mx][st]<<endl;
        int sc=dp[mx][st];
        if(st==(1<<n)-1){
            ans=min(ans,dp[mx][st]);
            continue;
        }
        int c=0;
        FOR(i,0,n){
            if(st&(1<<i)){
                c++;
            }
        }
        int ex_c=0;
        FOR(i,0,n){
            if(st&(1<<i)){
                continue;
            }
            int f=c&1,t;
            if((i&1)==f){
                t=a[i];
            }else{
                t=b[i];
            }
            if(mx<=t){
                int nst=st|(1<<i);
                int nsc=sc+ex_c;

                if(dp[t][nst]==mod){
                    dp[t][nst]=nsc;
                    q.push(MP(t,nst));
                }else{
                    dp[t][nst]=min(dp[t][nst],nsc);
                }
                }

            ex_c++;
        }
    }

    if(ans==mod){
        cout<<-1<<endl;
    }else{
        cout<<ans;
    }

}

