ll dif(vector<ll>& card, ll odd) {
  ll res = 0;
  vector<ll> temp = card;
  vector<bool> used(N, false);
  sort(temp.begin(), temp.end());
  for (ll i = 0; i < N; ++i) {
    ll want = temp.at(i);
    bool not_found = true;
    ll cnt = -1;
    for (ll j = 0; j < N; ++j) {
      if (used.at(j)) {
        continue;
      }
      cnt += 1;
      if (card.at(j) != want) {
        continue;
      }
      if ((odd & (ll)pow(2, j)) != 0) {
        if (abs(i - j) % 2 == 1) {
          // cout << "odd" << i << ' ' << j << "\n";
          // cout << "cnt" << cnt << "\n";
          res += cnt;
          used.at(j) = true;
          not_found = false;
          break;
        }
      }
      else {
        if (abs(i - j) % 2 == 0) {
          // cout << "even" << i << ' ' << j << "\n";
          // cout << "cnt" << cnt << "\n";
          res += cnt;
          used.at(j) = true;
          not_found = false;
          break;
        }
      }
    }
    if (not_found) {
      // cout << "not found" << "\n";
      return INF;
    }
  }
  // cout << res << "\n";
  return res;
}

