constexpr int inf = 1e9 + 334 + 810 + 1919;
std::vector<int> A, B;
std::vector<std::pair<int, int>> Odd, Even;
std::vector<int> Idx;

int main(void){
    int n; scanf("%d", &n);
    A.resize(n); REP(i, n) scanf("%d", &A[i]);
    B.resize(n); REP(i, n) scanf("%d", &B[i]);


    Odd.resize(n); Even.resize(n);
    Idx.resize(n);

    const int Nodd = n >> 1;
    const int Neven = n - Nodd;
    int N = 1 << n;

    int res = inf;
    REP(state, N){
        int odd = 0, even = 0;
        REP(i, n){
            if(bitUP(state, i)){ // 偶奇反転
                if(i % 2 == 0) Odd[odd++] = {B[i], i};
                else Even[even++] = {B[i], i};
            }
            else{
                if(i % 2 == 0) Even[even++] = {A[i], i};
                else Odd[odd++] = {A[i], i};
            }
        }
        if(odd != Nodd or even != Neven) continue;

        // 0 1 2 3 4 ... n - 1の順に並べる
        std::sort( Odd.begin(),  Odd.begin() + odd );
        std::sort(Even.begin(), Even.begin() + even);


        bool isSorted = true;
        for(int i = 0; i < odd; ++i){
            if(Even[i].first > Odd[i].first){isSorted = false; break;}
            if(i + 1 < even and Odd[i].first > Even[i+1].first){isSorted = false; break;}
        }
        if(not isSorted) continue;

        REP(i, odd) Idx[Odd[i].second] = 2 * i + 1;
        REP(i, even) Idx[Even[i].second] = 2 * i;

        // 転倒数を数える
        int cnt = 0;
        REP(i, n) for(int j = i + 1; j < n; ++j) if(Idx[i] > Idx[j]) cnt++;
        if(res > cnt) res = cnt;
    }
    if(res == inf) puts("-1");
    else printf("%d\n", res);




    return 0;
}

