const int INF = 1e9;

int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    int n;
    cin >> n;
    vector< vector<int> > a(2, vector<int>(n));
    for (int i = 0; i < 2; ++i) {
        for (int j = 0; j < n; ++j) {
            cin >> a[i][j];
        }
    }

    int ans = INF;
    for (int i = 0; i < (1 << n); ++i) {
        if (__builtin_popcount(i) % 2 == 1) continue;

        vector<int> v(n), ids(n);
        for (int j = 0; j < n; ++j) {
            v[j] = a[i >> j & 1][j];
            ids[j] = j;
        }

        vector<int> f(n, 0);
        int cnt = 0;
        for (int j = 0; j < n - 1; ++j) {
            for (int k = 1; k < n - j; ++k) {
                if (v[ids[k]] < v[ids[k - 1]]) {
                    swap(ids[k], ids[k - 1]);
                    cnt++;
                    f[ids[k]] = 1 - f[ids[k]];
                    f[ids[k - 1]] = 1 - f[ids[k - 1]];
                }
            }
        }

        for (int jj = 0; jj < n; ++jj) {
            int& j = ids[jj];
            if ((i >> j & 1) != f[j]) {
                if (jj == n - 1) {
                    cnt = INF;
                    break;
                }

                int& k = ids[jj + 1];
                if (v[j] == v[k] && (i >> k & 1) != f[k]) {
                    swap(j, k);
                    cnt++;
                    f[j] = 1 - f[j];
                    f[k] = 1 - f[k];
                } else {
                    cnt = INF;
                    break;
                }
            }
        }
        ans = min(ans, cnt);
    }
    cout << (ans >= INF ? -1 : ans) << "\n";
    return 0;
}

