struct IO {
#ifdef _WIN32
  inline char getchar_unlocked() { return getchar(); }
  inline void putchar_unlocked(char c) { putchar(c); }
#endif
  string separator = " ";
  template <class T>
  inline void read(T &x) {
    char c;
    do {
      c = getchar_unlocked();
    } while (c != '-' && (c < '0' || '9' < c));
    bool minus = 0;
    if (c == '-') {
      minus = 1;
      c = getchar_unlocked();
    }
    x = 0;
    while ('0' <= c && c <= '9') {
      x *= 10;
      x += c - '0';
      c = getchar_unlocked();
    }
    if (minus) x = -x;
  }
  inline void read(string &x) {
    char c;
    do {
      c = getchar_unlocked();
    } while (c == ' ' || c == '\n');
    x.clear();
    do {
      x += c;
      c = getchar_unlocked();
    } while (c != ' ' && c != '\n' && c != EOF);
  }
  template <class T>
  inline void read(vector<T> &v) {
    for (auto &x : v) read(x);
  }
  template <class Head, class... Tail>
  inline void read(Head &head, Tail &... tail) {
    read(head);
    read(tail...);
  }
  template <class T>
  inline void write(T x) {
    char buf[32];
    int p = 0;
    if (x < 0) {
      x = -x;
      putchar_unlocked('-');
    }
    if (x == 0) putchar_unlocked('0');
    while (x > 0) {
      buf[p++] = (x % 10) + '0';
      x /= 10;
    }
    while (p) {
      putchar_unlocked(buf[--p]);
    }
  }
  inline void write(string x) {
    for (char c : x) putchar_unlocked(c);
  }
  inline void write(const char s[]) {
    for (int i = 0; s[i] != 0; ++i) putchar_unlocked(s[i]);
  }
  template <class T>
  inline void write(vector<T> v) {
    for (auto itr = v.begin(); itr + 1 != v.end(); ++itr) {
      write(*itr);
      write(separator);
    }
    write(v.back());
  }
  template <class Head, class... Tail>
  inline void write(Head head, Tail... tail) {
    write(head);
    write(separator);
    write(tail...);
  }
  void set_separator(string s) { separator = s; }
} io;

int mergecount(vector<int> &a) {
  int count = 0;
  int n = a.size();
  if (n > 1) {
    vector<int> b(a.begin(), a.begin() + n / 2);
    vector<int> c(a.begin() + n / 2, a.end());
    count += mergecount(b);
    count += mergecount(c);
    for (int i = 0, j = 0, k = 0; i < n; ++i)
      if (k == c.size())
        a[i] = b[j++];
      else if (j == b.size())
        a[i] = c[k++];
      else if (b[j] <= c[k])
        a[i] = b[j++];
      else {
        a[i] = c[k++];
        count += n / 2 - j;
      }
  }
  return count;
}

int main() {
  int N;
  io.read(N);
  vector<int> A(N), B(N);
  io.read(A, B);
  int ans = INF;
  REP(b, 1 << N) {
    int pop = __builtin_popcount(b);
    if (pop % 2 == 1) continue;
    vector<Pii> list(N);
    REP(i, N) {
      if ((b >> i) & 1)
        list[i] = Pii(B[i], i);
      else
        list[i] = Pii(A[i], i);
    }
    sort(ALL(list));
    vector<Pii> even_list, odd_list;
    REP(i, N) {
      if (i % 2 == 0)
        even_list.push_back(Pii(list[i].first, i));
      else
        odd_list.push_back(Pii(list[i].first, i));
    }
    bool ok = 1;
    vector<int> used_even(51), used_odd(51);
    vector<int> swp(N);
    REP(i, N) {
      if (!((i % 2) ^ ((b >> i) & 1))) {
        int num = ((b >> i) & 1) ? B[i] : A[i];
        auto itr = lower_bound(ALL(even_list), Pii(num, -1));
        if (itr == even_list.end() || itr->first != num ||
            itr->second + 2 * used_even[num] >= N) {
          ok = 0;
          break;
        } else {
          swp[itr->second + 2 * used_even[num]] = i;
          used_even[num]++;
        }
        // debug(0, num, *itr, t);
      } else {
        int num = ((b >> i) & 1) ? B[i] : A[i];
        auto itr = lower_bound(ALL(odd_list), Pii(num, -1));
        if (itr == odd_list.end() || itr->first != num ||
            itr->second + 2 * used_odd[num] >= N) {
          ok = 0;
          break;
        } else {
          swp[itr->second + 2 * used_odd[num]] = i;
          used_odd[num]++;
        }
        // debug(1, num, *itr, t);
      }
    }
    // debug((int)ok, t, list, even_list, odd_list);
    if (ok) {
      // debug(swp);
      int t = mergecount(swp);
      // debug(t);
      ans = min(ans, t);
    }
  }
  io.write(ans == INF ? -1 : ans);
  io.write("\n");
  return 0;
}

