ll n, N;
vector<ll> A;
vector<ll> B;

int solve()
{
  using pint = pair<int, int>;
  vector<vector<int>> dp((1 << N) + 1, vector<int>(55, INF));
  dp[0][0] = 0;
  for (int bit = 0; bit < (1 << N); ++bit)
  {
    int con = 0;
    for (int i = 0; i < N; ++i)
      if (bit & (1 << i))
        ++con;

    // bit に含まれない残りの要素が何番目に対応するか
    vector<pint> ords;
    int iter = con;
    for (int i = 0; i < N; ++i)
      if (!(bit & (1 << i)))
        ords.emplace_back(i, iter++);

    for (int s = 0; s <= 50; ++s)
    {
      if (dp[bit][s] >= INF)
        continue;
      for (auto p : ords)
      {
        // p.first: もともとの a の index
        // p.second: dp[bit][s] の状態での index
        int ns = -1;
        if (abs(p.first - con) % 2 == 0)
          ns = A[p.first];
        else
          ns = B[p.first];

        if (ns >= s)
        {
          chmin(dp[bit | (1 << p.first)][ns], dp[bit][s] + abs(p.second - con));
        }
      }
    }
  }
  int res = INF;
  for (int s = 0; s <= 50; ++s)
    chmin(res, dp[(1 << N) - 1][s]);
  if (res < INF)
    return res;
  else
    return -1;
}

