int dfs(int p, int op, int la)
{

	if(op==3)
	int lxy=1;

	if(vi[op][la])return h[op][la];
	vi[op][la]=1;
	if(!p)return h[op][la]=0;
	h[op][la]=INF;
	int w,pp,ss,_ss=0,_w;
	if(abs(la-p)&1)w=b[la];else w=a[la];
	pp=op^(1<<la);
	F2(i,la+1,n)if(pp&(1<<i))++_ss;
	F2(i,0,n)if(pp&(1<<i)){
		if(abs(i-p)&1)_w=a[i];else _w=b[i];
		if(_w>w)continue;
		ss=dfs(p-1,pp,i)+_ss;
		chmin(h[op][la],ss);
	}
	return h[op][la];
}

