int kthbit(int A, int K) { return (A >> K) & 1; }

struct card{ int val; int firstPos; int nSwapped; bool isTable; };

int main(){
    int N;  cin >> N;
    vector<pair<int, int>> P(N);
    for(int i=0; i<N; i++)
        cin >> P[i].first;
    for(int i=0; i<N; i++)
        cin >> P[i].second;

    int ans = 1e9;
    for(int n=0; n<(1<<N); n++){
        vector<card> C(N);
        for(int i=0; i<N; i++){
            C[i].firstPos = i;
            C[i].nSwapped = 0;
            if(kthbit(n, i) == 1){
                C[i].val = P[i].second;
                C[i].isTable = false;
            }else{
                C[i].val = P[i].first;
                C[i].isTable = true;
            }
        }

        int cnt = 0;
        for(int i=0; i<N-1; i++) for(int j=N-1; j>i; j--){
            if(C[j-1].val > C[j].val){
                C[j].nSwapped++;
                C[j-1].nSwapped++;
                swap(C[j], C[j-1]);
                cnt++;
            }
        }

        // cout << n << endl;
        // for(card c : C){
        //     cout << c.val << " " << c.firstPos << " " << c.nSwapped << endl;
        // }
        // cout << "------------------" << endl;

        bool ok = true;
        for(int i=0; i<N; i++){
            if(C[i].isTable && C[i].nSwapped%2==1){
                ok = false;
            }else if(!C[i].isTable && C[i].nSwapped%2==0){
                ok = false;
            }
        }

        if(ok){
            ans = min(ans, cnt);   
        }
    }
    if(ans != 1e9){
        cout << ans << endl;
    }else{
        cout << -1 << endl;
    }
}

