int main(){
    cin >> n;
    for(ll i=0;i<n;i++){
        cin >> x[i];
        used[x[i]] = true;
    }
    for(ll i=0;i<n;i++){
        cin >> y[i];
        used[y[i]] = true;
    }
    used[0] = true;
    ll bit = (1ll << n);
    for(ll i=0;i<bit;i++){
        for(ll j=0;j<=50;j++){
            dp[i][j] = INF;
        }
    }
    dp[0][0] = 0;
    for(ll i=0;i<bit;i++){
        for(ll j=0;j<n;j++){
            // memo[i][j]を求める
            for(ll k=j+1;k<n;k++){
                if((i >> k) & 1)memo[i][j] ++;
            }
        }
    }
    for(ll i=0;i<bit;i++){
        ll idx = 0;
        for(ll k=0;k<n;k++){
            if((1ll << k) & i)idx++;
        }
        for(ll j=0;j<=50;j++){
            if(!used[j])continue;
            // dp[i][j]から配る先を求めるよ
            for(ll k=0;k<n;k++){
                // すでに使っているなら
                if((i >> k) & 1)continue;
                ll afterbit = i ^ (1ll << k);
                bool flip = (abs(idx - k) % 2 == 0);
                ll value = (flip ? x[k] : y[k]);
                if(value < j)continue;

                ll inversion = memo[i][k];
                dp[afterbit][value] = min(dp[afterbit][value], dp[i][j] + inversion);
            }
        }
    }
    ans = INF;
    for(ll i=0;i<=50;i++){
        ans = min(ans, dp[(1ll << n) - 1][i]);
    }
    if(ans == INF){
        ans = -1;
    }
    p(ans);


    return 0;
}

