    int ans = inf;
    do {
        // cout << endl; rep(i, n) cout << a[i].F.F << " " << a[i].F.S << " " << a[i].S << endl;
        int last = 0;
        int sum = 0;
        BIT<int> bit(n);

        rep(i, n) {
            int now = ((i - a[i].S) % 2 ? a[i].F.S : a[i].F.F);
            // cout << now << endl;
            if (now < last) break;

            last = now;
            if (i == n - 1) {
                // rep(j, n) cout << a[j].S << " "; cout << endl;
                vector<pii> v;
                rep(j, n) v.eb(pii(a[j].S, j));
                sort(all(v), greater<pii>());
                rep(j, n) {
                    sum += bit.sum(v[j].S);
                    bit.add(v[j].S + 1, 1);
                }

                // cout << sum << endl;
                chmin(ans, sum);
            }
        }
    } while(next_permutation(all(a)));
    cout << (ans == inf ? -1 : ans) << endl;
}

