using namespace std;

typedef long long ll;
typedef pair<ll, ll> P;

int N, a[50], b[50];
int finalRes = 1000000;


int check(int *indexes, int n){
    int index = 0;
    vector<P> eve, od;
    for(int i = 0; i < N; i++){
        if(index < n && indexes[index] == i){   // 奇数番目に入るもの
            if(i % 2 == 1){
                od.push_back(P(a[i], i));
            }
            else{
                od.push_back(P(b[i], i));
            }
            index++;
        }
        else {                                  // 偶数番目に入るもの
            if(i % 2 == 1){
                eve.push_back(P(b[i], i));
            }
            else{
                eve.push_back(P(a[i], i));
            }
        }
    }

    sort(eve.begin(), eve.end());
    sort(od.begin(), od.end());


    bool ok = true;
    vector<P> total;
    for(int i = 0; i < N; i++){
        if(i % 2 == 0){
            total.push_back(eve[i/2]);
        }
        else{
            total.push_back(od[i/2]);
        }
    }
    for(int i = 1; i < N; i++){
        if(total[i].fs < total[i-1].fs){
            ok = false;
            break;
        }
    }
    if(ok){
        vector<int> dest(N, 0);
        for(int i = 0; i < N; i++){
            dest[total[i].sc] = i;
        }
        int res = 0;
        for(int i = 0; i < N; i++){
            for(int j = N-1; j >= i+1; j--){
                if(dest[j-1] > dest[j]){
                    swap(dest[j-1], dest[j]);
                    res++;
                }
            }
        }
        finalRes = min(res, finalRes);
    }
}

void recursive_comb(int *indexes, int s, int rest, int n) {
    if (rest == 0) {
        check(indexes, n);
    } else {
        if (s < 0) return;
        recursive_comb(indexes, s - 1, rest, n);
        indexes[rest - 1] = s;
        recursive_comb(indexes, s - 1, rest - 1, n);
    }
}

// nCkの組み合わせに対して処理を実行する
void foreach_comb(int n, int k) {
    int indexes[k];
    recursive_comb(indexes, n - 1, k, k);
}


