    for(int i = 0; i < N; i++){
        cin >> a[i];
    }
    for(int i = 0; i < N; i++){
        cin >> b[i];
    }

    foreach_comb(N, N/2);

    if(finalRes == 1000000){
        cout << -1 << endl;
    }
    else{
        cout << finalRes << endl;
    }




    return 0;
}

