    int n;
    cin >> n;
    vector<int> a(n);
    vector<int> b(n);
    cin >> a >> b;
    int ans = 1e9;
    for (int i = 0; i < (1 << n); ++i) {
        vector<int> v(n, false);
        for (int j = 0; j < n; ++j) {
            if ((i >> j) & 1) {
                v[j] = true;
            }
        }
        vector<int> res;
        for (int j = 0; j < n; ++j) {
            if (v[j]) res.pb(b[j]);
            else res.pb(a[j]);
        }
        sort(res.begin(), res.end());
        vector<int> has;
        for (int j = 0; j < n; ++j) {
            int k = a[j];
            if (v[j]) {
                k = b[j];
            }
            has.pb(k);
        }
        int sm = 0;
        bool ok = true;
        for (int i = 0; i < n; ++i) {
            ok = false;
            for (int j = 0; j < n; ++j) {
                if (has[i] == res[j] && ((i + v[i]) % 2 == j % 2)) {
                    res[j] = -1;
                    sm += abs(i - j);
                    ok = true;
                    break;
                }
            }
            if (!ok) break;
        }
        if (!ok) continue;
        if (sm % 2 == 1) continue;
        ans = min(ans, sm / 2);
    }
    if (ans == 1e9) ans = -1;
    cout << ans << endl;

    return 0;
}

