                    value = y[k];
                }
                if(value < j)continue;

                ll inversion = 0;

                for(ll a=k+1;a<n;a++){
                    if((i >> a) & 1)inversion++;
                }
                dp[afterbit][value] = min(dp[afterbit][value], dp[i][j] + inversion);
            }
        }
    }
    ans = INF;
    for(ll i=0;i<=50;i++){
        ans = min(ans, dp[(1ll << n) - 1][i]);
    }
    if(ans == INF){
        ans = -1;
    }
    p(ans);


