const int INF = 0x3f3f3f3f;
const int MAXN = 18;
const int MAXX = 50;

int N;
int A[MAXN + 1];
int B[MAXN + 1];

int main(void) {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N;

    for (int i = 0; i < N; i++)
        cin >> A[i];
    for (int i = 0; i < N; i++)
        cin >> B[i];

    bool ok = true;
    for (int i = 1; i < N; i++) {
        if (A[i - 1] > A[i]) {
            ok = false;
            break;
        }
    }
    if (ok) {
        cout << 0 << endl;
        return 0;
    }

    int res = INF;
    for (int i = 0; i < (1 << N); i++) {
        int bit = popcount(i);
        if (bit & 1)
            continue;

        vector<tuple<int, int, bool>> even;
        vector<tuple<int, int, bool>> odd;
        int oddB = 0, evenB = 0;
        for (int j = 0; j < N; j++) {
            if (i & (1 << j)) {
                if (j & 1) {
                    even.emplace_back(B[j], j, true);
                    evenB++;
                } else {
                    odd.emplace_back(B[j], j, true);
                    oddB++;
                }
            } else {
                if (j & 1)
                    odd.emplace_back(A[j], j, false);
                else
                    even.emplace_back(A[j], j, false);
            }
        }
        if (oddB != evenB)
            continue;

        sort(odd.begin(), odd.end());
        sort(even.begin(), even.end());

        vector<tuple<int, int, bool>> X(N);
        for (int i = 0; i < int(odd.size()); i++)
            X[i * 2 + 1] = odd[i];
        for (int i = 0; i < int(even.size()); i++)
            X[i * 2] = even[i];

        int dist = 0;
        for (int j = 0; j < N; j++) {
            if (j > 0 && get<0>(X[j - 1]) > get<0>(X[j])) {
                dist = INF;
                break;
            }
            for (int k = j + 1; k < N; k++)
                //dist += (get<1>(X[j]) > get<1>(X[k]));
                dist += max(0, get<1>(X[j]) - get<1>(X[k]));
        }
        res = min(res, dist);
    }

    if (res >= INF)
        cout << -1 << endl;
    else
        cout << res / 2 << endl;

    return 0;
}

