template<class Monoid>
class SegmentTree {
    using Func = std::function<Monoid(Monoid, Monoid)>;
    int N;

    std::vector<Monoid> segment;

    const Func op;
    const Monoid id;

    bool dirty_flag;
public:
    // id : op = max なら -INT_MAX
    SegmentTree(int n, const Func biop, const Monoid& M1)
    : op(biop), id(M1), dirty_flag(false) {
        N = 1;
        while(N < n) N *= 2;
        segment.assign(2 * N, id);
    }

    void set(int k, const Monoid &a){
        dirty_flag = true;
        UPMIN(segment[k + N] , a);
    }

    void build() {
        for (int k = N - 1; k > 0; --k) {
            segment[k] = op(segment[2 * k], segment[2 * k + 1]);
        } // end k
        dirty_flag = false;
    }

    void update(int k, const Monoid& a){
        k += N;
        segment[k] = a;
        while(k /= 2){
            segment[k] = op(segment[k*2], segment[k*2+1]);
        }
    }

    // -> op [a,b)
    Monoid query(unsigned a, unsigned b){
        if(dirty_flag) build();
        dirty_flag = false;
        Monoid L = id, R = id;
        for (a += N, b += N; a < b; a >>= 1u, b >>= 1u) {
            if(a & 1u) L = op(L, segment[a++]);
            if(b & 1u) R = op(segment[--b], R);
        } // end i
        return op(L, R);
    }

    Monoid operator[](const int &k) const{
        return segment[k + N];
    }
};


class solver{
    istream& is;
    ostream& os;

public:
    solver(istream& I, ostream& O) :is(I), os(O) {}

    int N;
    array<vector<int>,2> X;
    bool input() {
        is >> N;
        X[0].resize(N);
        X[1].resize(N);
        is >> X[0] >> X[1];
        return !!is;
    }

    int popcount(int i){
        int c = 0;
        while(i){
            c += i&1;
            i >>=1;
        }
        return c;
    }

    int pl(int x, int j){
        int c =0;
        for (int k = 0; k < j; ++k) {
            int bk = 1<<k;
            c += (x & bk) == 0;
        } // end k
        return c;
    }

    void run();
};

