	vis[st][val] = true;
	DP[st][val] = INF;

	vector<pii> G;
	int tmp = 0;

	for (int i = n-1; i >= 0; --i) {
		if (st & (1 << i)) tmp ^= 1;
		else G.push_back(make_pair(i, tmp));
	}

	reverse(G.begin(), G.end());

	int len = G.size(), id;
	for (int i = 0; i < len; ++i) {
		tmp = (i + G[i].second) & 1;
		id = G[i].first;
		if (in[id][tmp] >= in[val][index]) {
			DP[st][val] = min(dp(st + (1 << id), id, tmp) + i, DP[st][val]);
		}
	}
	return DP[st][val];
}

