struct BIT
{
private:
    vector<int> bit;
    int N;

public:
    BIT(int size)
    {
        N = size;
        bit.resize(N + 1);
    }

    // 一点更新です
    void add(int a, int w)
    {
        for (int x = a; x <= N; x += x & -x)
            bit[x] += w;
    }

    // 1~Nまでの和を求める。
    int sum(int a)
    {
        int ret = 0;
        for (int x = a; x > 0; x -= x & -x)
            ret += bit[x];
        return ret;
    }
};

void solve(long long N, std::vector<long long> A, std::vector<long long> B)
{
    vector<ll> perm(N);
    for (int i = 0; i < N; i++)
    {
        perm[i] = i + 1;
    }
    ll ans = 100000000;
    do
    {
        vector<ll> tmp(N);
        for (int i = 0; i < N; i++)
        {
            if (abs(perm[i] - (i + 1)) % 2 == 0)
            {
                tmp[i] = A[perm[i] - 1];
            }
            else
            {
                tmp[i] = B[perm[i] - 1];
            }
        }
        bool largerflag = true;
        ll prev = tmp[0];
        for (int i = 1; i < N; i++)
        {
            if (prev > tmp[i])
            {
                largerflag = false;
                break;
            }
            else
            {
                prev = tmp[i];
            }
        }

        if (largerflag)
        {
            ll now = 0;
            BIT b(N); // これまでの数字がどんな風になってるのかをメモる為のBIT
            for (int i = 0; i < N; i++)
            {
                now += i - b.sum(perm[i]); // BITの総和 - 自分より左側 ＝ 自分より右側
                b.add(perm[i], 1);         // 自分の位置に1を足す(ダジャレではないです)
            }
            ans = min(now, ans);
        }

    } while (next_permutation(perm.begin(), perm.end()));

    if (ans == 100000000)
    {
        cout << -1 << endl;
    }
    else
    {
        cout << ans << endl;
    }
}

