  vector<vector<long long>> dp(1<<n, vector<long long>(51, INF));
  dp[0][0] = 0;
  REP(s, (1<<n)){
    //REP(v,51){
    vector<int> ni;//sにおいて立ってないビット
    int bits = 0;//sにおいて立っているビットの数
    BIT<int> tree(n);//sにおいて立っているビットの管理
    vector<int> upbits//sにおいて立っているビット
    REP(j,n){
      if(s & (1<<j)){
        bits++;
        tree.add(j);
        upbits.push_back(j);
      }else{
        ni.push_back(j);
      }
    }
    for(int now:upbits){
      int v;
      if(bits == 0){
        v = 0;
      }else{
        if(((bits - 1) - now) % 2 == 0){
          v = a[i];
