int bubbleSort(vector <pair <int, int > >& c, int ptn)
{
	int num = 0;
	for (int i=0;i<SZ(c);i++)
	{
		for (int k = 1; k < SZ(c)-i; ++k)
		{
			if (c[k].first < c[k - 1].first)
			{
				swap(c[k], c[k - 1]);
				num++;
			}
		}
	}

	for (int i = 0; i<SZ(c); i++)
	{
		for (int k = 1; k < SZ(c) - i; ++k)
		{
			if (c[k].first == c[k - 1].first && (((abs(c[k].second - k) % 2 == 0) ^ (IsBit(ptn, k))) || (((abs(c[k-1].second - (k-1)) % 2 == 0) ^ (IsBit(ptn, k-1)))) ) )
			{
				swap(c[k], c[k - 1]);
				num++;
			}
		}
	}



	return num;
}


