bool is_enable(int n, vector<int> e, vector<int> o) {

    if (!(e.size() == (n + 1) / 2)) return false;
    if (!(o.size() == n / 2)) return false;

    sort(e.begin(), e.end());
    sort(o.begin(), o.end());
    vector<int> tmp;
    rep(i, e.size()) {
        tmp.push_back(e[i]);
        if (o.size() > i) tmp.push_back(o[i]);
    }

    rep(i, tmp.size() - 1) {
        if (!(tmp[i] <= tmp[i + 1])) return false;
    }
    return true;

}

int calc(vector<P> pe, vector<P> po) {
    sort(pe.begin(), pe.end());
    sort(po.begin(), po.end());

    vector<P> tmp;
    rep(i, pe.size()) {
        tmp.push_back(pe[i]);
        if (po.size() > i) tmp.push_back(po[i]);
    }
    rep(i, tmp.size() - 1) {
        assert(tmp[i].first <= tmp[i + 1].first);
    }
    int ans = 0;
    rep(i, tmp.size())ans += max<int>(i - tmp[i].second, 0);
    return ans;
}


