        rep(j, n) {

            if (j % 2 == 0) {
                if ((i >> j) & 1) {
                    o.push_back(b[j]);
                    po.push_back({b[j], j});
                } else {
                    e.push_back(a[j]);
                    pe.push_back({a[j], j});
                }
            } else {
                if ((i >> j) & 1) {
                    e.push_back(b[j]);
                    pe.push_back({b[j], j});

                } else {
                    o.push_back(a[j]);
                    po.push_back({a[j], j});
                }
            }
        }

        bool ok = is_enable(n, e, o);
        if (!ok) continue;
        int cost = calc(pe, po);
        cmin(ans, cost);
    }
