int const inf = 1000000;

map<vector<pair<int,int>>, int> dp;

int solve(vector<pair<int,int>> v, int lv, int rv) {
    if (v.empty()) {
        return lv <= rv ? 0 : inf;
    }
    if (v.size() == 1) {
        return lv <= v[0].first && v[0].first <= rv ? 0 : inf;
    }
    v.emplace_back(lv, rv);
    auto it = dp.find(v);
    if (it != dp.end())
        return it->second;
    v.pop_back();
    int best = inf;
    for (int i = 0; i < v.size(); ++i) {
        int cur = 0;
        auto nv = v;
        for (int j = 1; j <= i; ++j) {
            swap(nv[j - 1], nv[j]);
            swap(nv[j - 1].first, nv[j - 1].second);
            swap(nv[j].first, nv[j].second);
            ++cur;
        }
        if (nv[i].first < lv || nv[i].first > rv)
            continue;
        vector<pair<int,int>> lvec;
        vector<pair<int,int>> rvec;
        for (int j = 0; j < i; ++j)
            lvec.push_back(nv[j]);

        for (int j = i + 1; j < v.size(); ++j)
            rvec.push_back(nv[j]);
        cur += solve(lvec, lv, nv[i].first) + solve(rvec, nv[i].first, rv);
        best = min(best, cur);
    }
    v.emplace_back(lv, rv);
    return dp[v] = best;
}


