    rep(i, N) cin>>B[i];

    ll mi = inf;
    ll odd = N/2;
    ll even = N-odd;
    rep(f, 1LL<<N){
      vector<PII> OD; // odd vector // {val, index}のリスト
      vector<PII> EV; // even vector // 〃
      rep(i, N){
        if(f>>i&1){
          // 1だとひっくり返ってるとする
          if(i%2==0){
            OD.push_back(MP(B[i], i));
          }else{
            EV.push_back(MP(B[i], i));
          }
        }else{
          if(i%2==0){
            EV.push_back(MP(A[i], i));
          }else{
            OD.push_back(MP(A[i], i));
          }
        }
      }
      if(odd==SZ(OD) && even==SZ(EV)){
        // ok
      }else{
        // debug("skip by size");
        continue;
      }

      // odd, evenの数は合っている
      SORT(EV);
      SORT(OD);
      // zip (合成する)
      vector<PII> SO; // sorted vector
      rep(i, SZ(OD)){
        SO.push_back(EV[i]);
        SO.push_back(OD[i]);
      }
      if(SZ(EV)!=SZ(OD)){
        SO.push_back(EV.back());
      }

      // これがsortedかチェック
      if(isIncreasing2(SO)){
        // ok
      }else{
        // debug("skip by not sorted");
        continue;
      }

      // original vectorをsortedにするまでの回数が反転数
      VI I;
      for(auto pa : SO){
        I.push_back(pa.second);
      }

      ll h = bubble_sort(I);
      chmin(mi, h);
    }

    if(mi==inf){
      p(-1);
    }else{
      p(mi);
    }

    return 0;
}

