int main(){
  using namespace std;
  int n;
  cin>>n;
  int a[n], b[n];
  REP(i,n){
    cin>>a[i];
  }
  REP(i,n){
    cin>>b[i];
  }
  vector<vector<long long>> dp(1<<n, vector<long long>(55, INF));
  dp[0][0] = 0;
  REP(s, (1<<n)){
    REP(v,55){
      vector<int> ni;
      int bits = 0;
      REP(j,n){
        if(s & (1<<j)){
          bits++;
        }else{
          ni.push_back(j);
        }
      }
      for(int i:ni){
        int nv;
        if((bits - i) % 2 == 0){
          nv = a[i];
        }else{
          nv = b[i];
        }
        if(nv < v)continue;
        long long cnt = 0;
        REP(j,n){
          if((s & (1<<j)) && j > i)cnt++;
        }
        dp[s | (1<<i)][nv] = min(dp[s | (1<<i)][nv], dp[s][v] + cnt);
      }
    }
  }
  long long res = INF;
  REP(v,55){
    res = min(res, dp[(1<<n) - 1][v]);
  }
  if(res == INF){
