  for(i = 1; i < m; ++i) {
    cnt = 0;
    for(j = 0; j < n; ++j) if((i >> j) & 1) ++cnt;
    for(j = 0; j < n; ++j) {
      now = ((cnt & 1) == (j & 1) ? b[j] : a[j]);
      for(k = 0; k < n; ++k) {
        now2 = ((cnt & 1) == (k & 1) ? a[k] : b[k]);
        if(now <= now2 && dp[i][j] + abs(k - cnt) < dp[i | (1 << k)][k])
          dp[i | (1 << k)][k] = dp[i][j] + abs(k - cnt);
      }
    }
