const int INF = 1e9;
const int MOD = INF + 7;
const LL LLINF = 1e18;

int N;
int A[20], B[20];
int dp[20][1 << 20];

int main(void) {
    cin >> N;
    REP(i, N) {
        cin >> A[i];
    }
    REP(i, N) {
        cin >> B[i];
    }

    REP(i, N) REP(j, 1 << N) {
        dp[i][j] = INF;
    }

    REP(i, N) {
        dp[i][1 << i] = i;
    }
    REP(bit, 1 << N) {
        const int bit_cnt = __builtin_popcount(bit);
        REP(j, N) if ((bit & (1 << j)) && dp[j][bit] < INF) {
            const int cur_val = (abs(bit_cnt - j - 1) % 2 == 0 ? A : B)[j];
            REP(k, N) if ((bit & (1 << k)) == 0) {
                const int nxt_val = ((abs(bit_cnt - k) % 2 == 0 ? A : B)[k]);
                if (nxt_val < cur_val) continue;
                const int add = __builtin_popcount((bit ^ 0xffffffff) & ((1 << k) - 1));
                chmin(dp[k][bit | (1 << k)], dp[j][bit] + add);
            }
        }
    }

    // REP(i, N) REP(j, (1 << N)) cout << i << " " << j << " " << dp[i][j] << endl;

    int ans = INF;
    REP(i, N) {
        chmin(ans, dp[i][(1 << N) - 1]);
    }
    if (ans == INF) {
        ans = -1;
    }
    cout << ans << endl;
}

