#define MAX 20

using namespace std;
typedef long long ll;

class Solution {
 public:
  void solve() {
    int n;
    cin >> n;
    int a[2][MAX]{};
    for (int i = 0; i < n; ++i) cin >> a[0][i];
    for (int i = 0; i < n; ++i) cin >> a[1][i];
    int ans = INT_MAX;
    for (int i = 0; i < (1 << n); ++i) {
      bitset<20> bs(i);
      if (bs.count() % 2 != 0) continue;
      vector<pair<int, int>> x;
      for (int j = 0; j < n; ++j) {
        x.push_back(make_pair(a[bs[j]][j], j));
      }
      sort(x.begin(), x.end());
      int dist = 0;
      bool ok = true;
      for (int j = 0; j < n; ++j) {
        int part = abs(x[j].second - j);
        if (part % 2 != bs[x[j].second]) {
          ok = false;
          break;
        }
        dist += part;
      }
      if (dist % 2 != 0) {
        ok = false;
      }
      if (ok && dist / 2 < ans) {
        ans = dist / 2;
      }
    }

    cout << (ans == INT_MAX ? -1 : ans);
  }
};

int main() {
  Solution solution = Solution();
  solution.solve();
}

