const int inf = -1*((1<<31)+1);

using namespace std;

int main(void){
    cin.tie(0);
    ios::sync_with_stdio(false);
    cout<<fixed<<setprecision(20);
    int N,ans = inf;
    cin >> N;
    vector<int> A(N),B(N);
    rep(i,N)cin >> A[i];
    rep(i,N)cin >> B[i];
    for(int bit = 0 ;bit<(1<<N);bit++){
        //bitが1になっていたら裏を使う
        vector<int> ura(N);
        for(int i=0;i<N;i++){
            //もしも、bitのi bit目が立っていたら、そのカードは裏面を使う
            if((bit>>i)&1)ura[i] = 1;
        }
        int even = 0,odd = 0; 
        //evenは偶数番目に置いたカードの枚数
        //oddは奇数番目に置いたカードの枚数

        vector<pair<int,int>> e,o;
        //eは偶数番目に使うカードの集合
        //oは奇数番目に使うカードの集合

        for(int i=0;i<N;i++){
            //i番目のカードについて考える
            if(i%2==0){
                //偶数番目のカードについて
                if(ura[i]){
                    //もしも裏面を使う場合は
                    //奇数番目に置く必要がある
                    odd++;
                    o.push_back({B[i],i});
                    //ここのiは何番目のカードかの情報
                    //最後に条件を満たす数列を作った場合に、操作回数を求めるのに使う
                }else{
                    //偶数番目に置く必要がある
                    e.push_back({A[i],i});
                    even++;
                }
            }else{
                //奇数番目のカードについて
                if(ura[i]){
                    //もしも裏面を使う場合は偶数番目に配置する必要がある
                    e.push_back({B[i],i});
                    even++;
                }else{
                    o.push_back({A[i],i});
                    odd++;
                }
            }
        }
        if(odd!= (N/2))continue;//奇数番目に置くカードの枚数が N/2じゃなかったらその置き方はできない
        sort(ALL(e));//とりあえず条件を満たすようにソートする
        sort(ALL(o));//とりあえず条件を満たすようにソートする
        //偶数、奇数と並べていく
        int evennow = 0,oddnow = 0;
        vector<pair<int,int>> p;
        for(int i=0;i<N;i++){
            if(i%2==0){
                p.push_back(e[evennow]);
                evennow++;
            }else{
                p.push_back(o[oddnow]);
                oddnow++;
            }
        }
        bool ok = 1;
        //ここでは、pが条件を満たす数列かどうかを判別する
        for(int i=0;i<N-1;i++){
            if(p[i].first>p[i+1].first)ok = 0;
        }
        if(!ok)continue;
        //pが条件を満たす数列だった場合は、操作回数を求める
        int cnt = 0;
        for(int i=0;i<N;i++){
            for(int j=i+1;j<N;j++){
                //何か自分より右にあるindex番号が小さいやつの個数を足していくと
                //バブルソートのスワップ回数になるらしい
                //証明はまだしらない
                if(p[i].second>p[j].second)cnt++;
            }
        }
        ans = min(ans,cnt);
    }
    if(ans==inf)ans = -1;
    cout << ans << endl;
}

