		{
			tot=0;
			for(int j=0;j<n;j++)if(i>>j&1)p[++tot]=(node){a[j][1],j};
			ans=min(ans,solve());
		}
	if(ans==1e9+10)puts("-1");
	else printf("%d\n",ans);
	return 0;
}

