bool check(vector<int> now)
{
	int lst = INT_MIN;
	rep(i, 0, now.size())
	{
		int curr = now[i];
		int pos = abs(curr);
		int cc;
		if(curr > 0) 
		{
			cc = v[pos-1].f;
		}
		else
		{
			cc = v[pos-1].s;
		}
		if(cc < lst) return 0;
		lst = cc;
	}
	return 1;
}

ll bfs(vector<int> tar)
{
	queue<pair<vector<int>, ll>> q;
	ll curr = 0;
	q.push(make_pair(tar, curr));
	mp[tar] = 1;
	while(!q.empty())
	{
		vector<int> now = q.front().f;
		ll c = q.front().s;
		if(check(now)) return c;
		q.pop();
		mp[now] = 1;
		rep(i, 0, n)
		{
			rep(j, i+1, n)
			{
				if(i != j)
				{
					swap(now[i], now[j]);
					now[i] = -now[i];
					now[j] = -now[j];
					if(mp[now] == 0)
					{
						if(check(now))
						{
							return (c + 1);
						}
						mp[now] = 1;
						q.push(make_pair(now, c+1));
					}
				}
			}
		}
	}
	return -1;
}

