int B[25];

int perm[25];

int set1[25];
int set2[25];

const int INF = 1012345678;

long long nxs(long long r){
    long long ls1 = r&(-r);
    long long rest = r+ls1;
    return rest|(((rest^r)/ls1) >> 2);
}

int main(){
    int N;
    scanf("%d", &N);

    for(int i = 0; i < N; i ++){
        scanf("%d", &A[i]);
    }

    for(int i = 0; i < N; i ++){
        scanf("%d", &B[i]);
    }

    int ans = INF;
    int noBits = (N+1)>>1;
    for(int i = (1<<noBits)-1; i < (1<<N); i = nxs(i)){
        //printf("i=%d\n", i);
        int size1 = 0;
        int size2 = 0;
        for(int j = 0; j < N; j ++){
            if(i&(1<<j)){
                // Place in first set, parity is even (0-indexed)
                if((j&1) == 0){
                    set1[size1++] = (A[j]<<6)|j;
                }else{
                    set1[size1++] = (B[j]<<6)|j;
                }
            }else{
                // Place in second set, parity is odd
                if((j&1) == 0){
                    set2[size2++] = (B[j]<<6)|j;
                }else{
                    set2[size2++] = (A[j]<<6)|j;
                }
            }
        }

        sort(set1, set1+size1);
        sort(set2, set2+size2);

        bool boleh = true;
        for(int j = 0; j < (int)size2; j ++){
            //printf("set1[%d]=ii(%d, %d), set2[%d]=ii(%d, %d)\n", j, set1[j].first, set1[j].second, j, set2[j].first, set2[j].second);
            if((set1[j]>>6) > (set2[j]>>6)){
                boleh = false;
                break;
            }

            if( ((N&1) == 0) && j == (int)size2-1 ){
                break;
            }

            if( (set1[j+1]>>6) < (set2[j]>>6) ){
                boleh = false;
                break;
            }
        }

        if(boleh){
            for(int j = 0; j < size2; j ++){
                perm[j<<1] = set1[j]&63;
                perm[(j<<1)|1] = set2[j]&63;
            }
            if(N&1){
                perm[N-1] = set1[size2]&63;
            }

            int inv = 0;
            for(int j = 0; j < N; j ++){
                for(int k = j+1; k < N; k ++){
                    if(perm[j] > perm[k]){
                        inv ++;
                    }
                }
            }

            ans = min(ans, inv);
        }
    }

    if(ans == INF){ans = -1;}
    printf("%d", ans);
    return 0;
}

