        int sum = 0;
        vector<pair<int, int>> v(N);
        for(int j = 0; j < N; j++){
            if(i & (1 << j)){
                sum++;
                v[j] = make_pair(B[j], j);
            }
            else{
                v[j] = make_pair(A[j], j);
            }
        }

        if(sum % 2 == 1){
            continue;
        }

        sort(v.begin(), v.end());
        int num = 0;
        vector<int> cnt(N, 0);

        for(int j = 0; j < N; j++){
            for(int k = j + 1; k < N; k++){
                if(v[j].second > v[k].second){
                    num++;
                    cnt[v[j].second]++;
                    cnt[v[k].second]++;
                }
            }
        }

        for(int j = 0; j < N; j++){
            cnt[j] = (cnt[j] % 2);
        }

        vector<int> cnt1(51, 0);
        for(int j = 0; j < N; j++){
            if(i & (1 << j)){
                cnt1[B[j]] += cnt[j];
            }
            else{
                cnt1[A[j]] += cnt[j];
            }
        }

        vector<int> cnt2(51, 0);
        for(int j = 0; j < N; j++){
            if(i & (1 << j)){
                cnt2[B[j]] += 1;
            }
        }

        bool isOk = true;
        for(int j = 0; j < 51; j++){
            if(cnt1[j] != cnt2[j]){
                isOk = false;
                break;
            }
        }

        if(isOk){
            vector<vector<pair<int, int>>> v01(51);
            for(int j = 0; j < N; j++){
                if(i & (1 << j)){
                    v01[B[j]].push_back(make_pair(cnt[j], 1));
                }
                else{
                    v01[A[j]].push_back(make_pair(cnt[j], 0));
                }
            }

            int cost = 0;
            for(int j = 0; j < 51; j++){
                int vSize = (int)v01[j].size();
                int indexFirst = 0;
                int indexSecond = 0;
                while(indexFirst < vSize && indexSecond < vSize){
                    if(v01[j][indexFirst].first == 1 && v01[j][indexSecond].second == 1){
                        cost += abs(indexSecond - indexFirst);
                        indexFirst++;
                        indexSecond++;
                    }
                    else if(v01[j][indexFirst].first == 1){
                        indexSecond++;
                    }
                    else{
                        indexFirst++;
                    }
                }
            }

            ans = min(ans, num + cost);
        }
    }

    if(ans == INF){
        cout << -1 << endl;
    }
    else{
        cout << ans << endl;
    }

    return 0;
}

