int judge(vector<int> &even_rev, vector<int> &odd_rev, vector<vector<int> > &card){
    vector<vector<int> > perm_even(0);
    vector<vector<int> > perm_odd(0);
    for(int i=0; i<(int)even_rev.size(); i++){
        if(even_rev[i]==1){
            perm_odd.push_back({card[2*i][1], card[2*i][2]});
        }else{
            perm_even.push_back({card[2*i][0], card[2*i][2]});
        }

        if(i<(int)odd_rev.size()){
            if(odd_rev[i]==1){
                perm_even.push_back({card[2*i+1][1], card[2*i+1][2]});
            }else{
                perm_odd.push_back({card[2*i+1][0], card[2*i+1][2]});
            }
        }
    }
    sort(perm_even.begin(), perm_even.end());
    sort(perm_odd.begin(), perm_odd.end());


    for(int i=0; i<(int) odd_rev.size(); i++){

        if(perm_even[i][0] <= perm_odd[i][0]){
            if(i+1==(int)perm_even.size())continue;
            if(perm_odd[i][0]<=perm_even[i+1][0]){
                continue;
            }
        }
        return -1;
    }
    vector<vector<int> > new_card(0);
    for(int i=0; i<(int) odd_rev.size(); i++){
        new_card.push_back(perm_even[i]);
        new_card.push_back(perm_odd[i]);
    }
    if((int)odd_rev.size()<(int)even_rev.size()){
        new_card.push_back(perm_even[(int)even_rev.size()-1]);
