vector<int> swapA(vector<int> A, vector<int> B,int x, int y) {
  int ax = A.at(x);
  int ay = A.at(y);
  int bx = B.at(x);
  int by = B.at(y);
  vector<int> nA = A;
  vector<int> nB = B;
  nA.at(x) = by;
  nA.at(y) = bx;
  nB.at(x) = ay;
  nB.at(y) = bx;
  return nA;
}
vector<int> swapB(vector<int> A, vector<int> B,int x, int y) {
  int ax = A.at(x);
  int ay = A.at(y);
  int bx = B.at(x);
  int by = B.at(y);
  vector<int> nA = A;
  vector<int> nB = B;
  nA.at(x) = by;
  nA.at(y) = bx;
  nB.at(x) = ay;
  nB.at(y) = bx;
  return nB;
}



