	int ret = 1e9;
	if (C[idx].a <= C[idx + 1].a) ret = min(ret, f(idx + 1));

	swapAndFilp(C[idx], C[idx + 1]);
	ret = min(ret, 1 + f(idx + 1));
	swapAndFilp(C[idx], C[idx + 1]);

	return ret;
}


