				swap(d[k],d[k+1]);
			}
			break;
		}
		if(!f) return 1e9;
	}
	return ans;
}
int main() {
	scanf("%d",&n);
	for(int i=0;i<n;i++) scanf("%d",&a[i]);
	for(int i=0;i<n;i++) scanf("%d",&b[i]);
	int ans=1e9;
	for(int i=0;i<1<<n;i++) {
		ans=min(ans,cal(i));
	}
	if(ans==1e9) ans=-1;
	printf("%d\n",ans);
	return 0;
}

