[[noreturn]] void impossible() {
    PRINTLN(-1);
    exit(0);
}

void solve() {
    i64 N = RD();
    auto A = RD_VEC(N);
    auto B = RD_VEC(N);

    i64 ans = INF;
    vector<pair<i64,i64>> cards(N);  // (c,v)
    vector<i64> ms(N);  // カードcの移動回数
    REP(mask, 1LL<<N) {
        REP(i, N) {
            i64 v = (mask&(1LL<<i)) ? B[i] : A[i];
            cards[i] = {i,v};
        }
        ALL(fill, ms, 0);
        DBG(cards, ms);

        i64 cur = 0;
        bool ok = true;
        REP(i, N) {
            i64 vmin   = INF;
            i64 vmin_j = -1;
            FOR(j, i, N) {
                i64 c,v; tie(c,v) = cards[j];
                i64 m = ms[c];
                bool front = (mask&(1LL<<c)) == 0;
                i64 d = j-i;
                DBG(i,j,c,front,m,d);

                bool vmin_updated = chmin(vmin, v);
                if(vmin_updated)
                    vmin_j = -1;
                if( front && (m+d)%2!=0) continue;
                if(!front && (m+d)%2==0) continue;

                if(vmin_updated)
                    vmin_j = j;
            }
            DBG(i,vmin,vmin_j);
            if(vmin_j < 0) {
                ok = false;
                break;
            }

            for(i64 j = vmin_j; j > i; --j) {
                i64 c1 = cards[j].first;
                i64 c2 = cards[j-1].first;
                ++ms[c1];
                ++ms[c2];
                swap(cards[j], cards[j-1]);
                ++cur;
            }

            DBG(i, cards, ms);
        }

        if(ok) {
            DBG("ok", cur);
            chmin(ans, cur);
        }
    }

    if(ans == INF) impossible();

    PRINTLN(ans);
}

signed main() {


    solve();

    return 0;
}

