int main(int argc, char *argv[]) {
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);
  cout << setprecision(20);

  ll N; cin >> N;
  vector<ll> A(N), B(N);
  for (ll i = 0; i < N; i++) {
    if (i % 2 == 0) cin >> A.at(i);
    else            cin >> B.at(i);
  }
  for (ll i = 0; i < N; i++) {
    if (i % 2 == 0) cin >> B.at(i);
    else            cin >> A.at(i);
  }
  ll K = (N+1) /2;
  ll cost = LLONG_MAX;
  for (ll x = 0; x < (1LL << N); x++) {
    if (__builtin_popcountll(x) != K) continue;
    vector<pair<ll, ll>> u, v, w;
    for (ll i = 0; i < N; i++) {
      if ((x >> i) & 1LL) u.emplace_back(A.at(i), i);
      else                v.emplace_back(B.at(i), i);
    }
    sort(u.begin(), u.end());
    sort(v.begin(), v.end());
    for (ll i = 0; i < K; i++) {
      w.push_back(move(u.at(i)));
      if (i < N/2) w.push_back(move(v.at(i)));
    }
    auto doit = [&]() -> void {
      for (ll i = 1; i < N; i++) if (w.at(i-1).first > w.at(i).first) return;
      ll cnt = 0;
      for (ll i = 0; i < N; i++) {
	for (ll j = i+1; j < N; j++) {
	  if (w.at(i).second > w.at(j).second) cnt++;
	}
      }
      cost = min(cost, cnt);
    };
    doit();
  }

  if (cost == LLONG_MAX) {
    cout << -1 << endl;
  }else {
    cout << cost << endl;
  }

  return 0;
}

