		cout << 0;
		return 0;
	}

	vector<uint> perm(N);
	iota(perm.begin(), perm.end(), 0);

	uint ans = UINT_MAX;
	bool aexist = false;

	do {
		bool sorted = true;
		for(int i=1; i<N; i++) {
			int c = perm[i-1];
			uint ap = (abs(i - 1 - c) % 2 == 0) ? AB[c].first : AB[c].second;

			int d = perm[i];
			uint ac = (abs(i - d) % 2 == 0) ? AB[d].first : AB[d].second;

			sorted &= ap <= ac;

			if(!sorted) break;
		}

		if(sorted) {
			aexist = true;
			uint nans = 0;

			vector<uint> po(N);
