int main(){
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    int n; cin >> n;
    vector<int> a(n), b(n);
    rep(i, n) cin >> a[i];
    rep(i, n) cin >> b[i];
    int EVEN = (n+1) / 2; // 0-index
    int ODD = n / 2;

    int const inf = 1<<29;
    int ans = inf;
    // 各カードについて、どちらの数値を表にするかの状態を全探索
    // bit が立っていたら b[i] 
    rep(bit, 1<<n) {
        vector<pair<int, int>> even, odd;
        rep(i, n) {
            if (bit&1<<i) {
                if(i&1) even.emplace_back(b[i], i);
                else odd.emplace_back(b[i], i);
            } else {
                if(i&1) odd.emplace_back(a[i], i);
                else even.emplace_back(a[i], i);
            }
        }

        if (ODD!=odd.size() || EVEN!=even.size()) continue;
        sort(even.begin(), even.end());
        sort(odd.begin(), odd.begin());
        vector<pair<int, int>> v;
        rep(i, ODD) {
            v.push_back(even[i]);
            v.push_back(odd[i]);
        }
        if(n%2) v.push_back(even.back());
        bool ok = true;
        repr(i, 1, n) if (v[i].first < v[i-1].first) { ok = false; break; }
        if (!ok) continue;
        int cnt = 0;
        rep(i, n) repr(j, 1, n) if (v[i].second > v[j].second) ++cnt;
        chmin(ans, cnt);
    }
    cout << (ans==inf? -1:ans) << endl;

    return 0;
}

