  for(int i=0;i<n;++i) {
    cin >> a[i];
  }
  for(int i=0;i<n;++i) {
    cin >> b[i];
  }

  vvi v(2, vi(n));
  for(int i=0;i<n;++i) {
    if(i%2) {
      v[1][i] = a[i];
      v[0][i] = b[i];
    } else {
      v[1][i] = b[i];
      v[0][i] = a[i];
    }
  }

  priority_queue<Elm> pq;
  pq.push({0, 0, 0, 0});
  vector<vector<map<int, int>>> d(19, vector<map<int, int>>(51));
  d[0][0][0] = 0;
  while(!pq.empty()) {
    Elm now = pq.top(); pq.pop();
    if(d[now.pos][now.val].find(now.used) == d[now.pos][now.val].end()) continue;
    if(now.cost > d[now.pos][now.val][now.used]) continue;
    cout << now.cost << ":" << now.val << ":" << now.pos << ":" << bitset<18>(now.used) << endl;
    for(int i=0;i<n;++i) {
      if((now.used>>i)&1) continue;
      if(v[now.pos%2][i] < now.val) continue;

      if(d[now.pos+1][v[now.pos%2][i]].find(now.used|(1<<i)) == d[now.pos+1][v[now.pos%2][i]].end() ||
          now.cost + abs(i - now.pos) < d[now.pos+1][v[now.pos%2][i]][now.used|(1<<i)]) {
        d[now.pos+1][v[now.pos%2][i]][now.used|(1<<i)] = now.cost + abs(i-now.pos);
        pq.push({now.cost + abs(i-now.pos), v[now.pos%2][i], now.pos+1, now.used|(1<<i)});
      }
    }
  }
  int mi = INF;
  for(int i=1;i<=50;++i) {
    if(d[n][i].find((1<<n)-1) != d[n][i].end()) mi = min(mi, d[n][i][(1<<n)-1]);
  }
  cout << (mi == INF ? -1 : mi/2) << endl;
}

