const int oo = 1000000;
int ans =oo;
int f[(1<<maxn)][18];
bool d[(1<<maxn)][18];
int dp(int tt,int las)
{
    if (__builtin_popcount(tt)==1) return 0;
    else if (d[tt][las]) return f[tt][las];
    else
    {
        f[tt][las] = oo;
        int sbit = __builtin_popcount(tt),cnt =0 ;
        int val1 = (sbit%2==(las+1)%2) ? a[las] : b[las];
        for(int i = n-1; i>=0; --i)
        {
            if (((tt>>i)&1)==1) ++cnt;
            if (i==las) break;
        }
        cnt--;
        _for(i,0,n)
        {
            if (i!=las && ((tt>>i)&1)==1)
            {
                int val2 = ((sbit-1)%2==(i+1)%2) ? a[i] : b[i];
                if (val2<=val1)
                    f[tt][las] = min(f[tt][las], dp(tt - (1<<las), i) + cnt );
            }
        }
        d[tt][las] = true;
        return f[tt][las];
    }
}
void solve()
{
    _for(i,0,n)
    {
        ans = min(ans, dp((1<<n)-1, i));

    }
    if (ans==oo) cout<<"-1";
    else cout<<ans;
}

int main()
{
