	rep(i, n) cin >> a[i];
	rep(i, n) cin >> b[i];

	const int thr = (n + 1) / 2;

	int base = 0;
	rep(i, n) if(i % 2) base |= (1 << i);

	using state = tuple<int, int, int>;
	using pii = pair<int, int>;

	const int inf = 1 << 20;
	int ans = inf;

	rep(mask, 1 << n){
		const int cur_mask = base ^ mask;
		if(__builtin_popcount(cur_mask) != n - thr) continue;

		vector<state> tmp;
		rep(i, n) {
			const int parity = (cur_mask >> i) & 1;

			if((mask >> i) & 1) {
				tmp.push_back(state(parity, b[i], i));
			} else {
				tmp.push_back(state(parity, a[i], i));
			}
		}

		sort(begin(tmp), end(tmp));

		bool ok = true;
		vector<pii> ary;

		rep(i, n) {
			const int pos = (i % 2) ? (i / 2) + thr : (i / 2); 
			int val, idx;
			tie(ignore, val, idx) = tmp[pos];
			ary.push_back(pii(val, idx));
		}

		rep(i, n - 1) {
			if(ary[i].first > ary[i + 1].first) {
				ok = false;
			}
		}

		if(ok == false) continue;

		int num = 0;
		vector<int> base_ary(n);
		iota(begin(base_ary), end(base_ary), 0);

		rep(i, n) {
			int tar = i;

			rep(j, i + 1, n) {
				if(ary[i].second == base_ary[j]) {
					tar = j;
				}
			}

			while(tar > i) {
				swap(base_ary[tar - 1], base_ary[tar]);
				num++, tar--;
			}
		}

		chmin(ans, num);
	}

