using P = pair<int, int>;

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n;
    cin >> n;
    vector<int> a(n), b(n);
    for(int i = 0; i < n; i++) {
        cin >> a[i];
    }
    for(int i = 0; i < n; i++) {
        cin >> b[i];
    }
    int ans = INF;
    for(int bit = 0; bit < (1 << n); bit++) {
        // true:表 false:裏
        vector<bool> ch(n, false);
        for(int i = 0; i < n; i++) {
            if(bit & (1 << i)) {
                ch[i] = true;
            }
        }
        // 奇数番目に置かれるカードの枚数
        int oddCnt = 0;
        // 偶数番目に置かれるカードの枚数
        int evenCnt = 0;
        // 奇数番目、偶数番目に使うカードの集合
        vector<P> po, pe;

        for(int i = 0; i < n; i++) {
            if(i % 2 == 0) {
                if(ch[i]) {
                    // 偶数番目かつ表なら、偶数番目に置く必要がある
                    evenCnt++;
                    pe.emplace_back(P(a[i], i));
                } else {
                    // 偶数番目かつ裏なら、奇数番目に置く必要がある
                    oddCnt++;
                    po.emplace_back(P(b[i], i));
                }
            } else {
                if(ch[i]) {
                    // 奇数番目かつ表なら、奇数番目に置く必要がある
                    oddCnt++;
                    po.emplace_back(P(a[i], i));
                } else {
                    // 奇数番目かつ裏なら、偶数番目に置く必要がある
                    evenCnt++;
                    pe.emplace_back(P(b[i], i));
                }
            }
        }
        // 奇数番目に置かれるカードの数は必ずn/2枚のはず
        if(oddCnt != (n / 2)) {
            continue;
        }
        sort(ALL(po));
        sort(ALL(pe));
        // 偶数、奇数の順番に並べる
        vector<P> sorted;
        int o = 0, e = 0;
        for(int i = 0; i < n; i++) {
            if(i % 2) {
                sorted.emplace_back(po[o]);
                o++;
            } else {
                sorted.emplace_back(pe[e]);
                e++;
            }
        }
        // 広義単調増加になっているか調べる
        bool ok = true;
        for(int i = 0; i < n - 1; i++) {
            if(sorted[i].first > sorted[i + 1].first) {
                ok = false;
            }
        }
        if(!ok) {
            continue;
        }
        // 転倒数==swapに必要な回数なので、
        // 転倒数を求める
        int cnt = 0;
        for(int i = 0; i < n; i++) {
            for(int j = i + 1; j < n; j++) {
                if(sorted[i].second > sorted[j].second) {
                    cnt++;
                }
            }
        }
        chmin(ans, cnt);
    }
    cout << (ans == INF ? -1 : ans) << endl;
}

