void solve() {
    int n;
    cin >> n;
    vector<int> a(n), b(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }
    for (int i = 0; i < n; ++i) {
        cin >> b[i];
    }
    int res = -1;
    for (int m = 0; m < (1 << n); ++m) {
        int x = __popcount((unsigned int)m);
        if (x & 1)
            continue;
        int cur = solve(n, a, b, m);
        if (cur == -1)
            continue;
        if (res == -1)
            res = cur;
        else
            res = min(res, cur);        
    }
    cout << res << endl;
}


