void bt(int i,int r,int b)
{
    //cout<<i<<" "<<r<<" "<<b<<'\n';
    if(i>n&&b==n/2)
    {
        vector<PII> red,blue;
        for(int j=1;j<=n;j++)
            if(j&1)
            {
                if(c[j]==0)red.pb({a[j],j});
                if(c[j]==1)blue.pb({b2[j],j});
            }
            else
            {
                if(c[j]==0)red.pb({b2[j],j});
                if(c[j]==1)blue.pb({a[j],j});
            }
        sort(all(red),greater<PII>());
        sort(all(blue),greater<PII>());
        int cur=-1,pos[30],val[30];
        for(int i=1;i<=n;i++)
        {
            if(i&1)
            {
                if(red.back().fi<cur)return;
                cur=red.back().fi;
                pos[i]=red.back().se;
                red.pop_back();
            }
            else
            {
                if(blue.back().fi<cur)return;
                cur=blue.back().fi;
                pos[i]=blue.back().se;
                blue.pop_back();
            }
        }
        for(int i=1;i<=n;i++)val[i]=i;
        int res=0,flag;
        for(int i=1;i<=n;i++)
        {
            flag=0;
            for(int j=1;j<=n;j++)
            {
                if(flag)val[j]--;
                if(pos[j]==i)
                {
                   //cout<<val[j]<<'\n';
                   res+=max(0LL,val[j]-i);
                   flag=1;
                }
            }
        }
        //for(int i=1;i<=n;i++)cout<<pos[i]<<" ";cout<<'\n';
        //cout<<res<<'\n';
        ans=min(ans,res);
        return;
    }
    else
    {
        c[i]=0;
        bt(i+1,r+1,b);
        c[i]=1;
        bt(i+1,r,b+1);
    }
    return;
}
