bool cmp( const Card &a, const Card &b ){
    if(a.number == b.number) return a.id < b.id;
    return a.number < b.number;
}

bool cmpId( const Card &a, const Card &b ){
    return a.id < b.id;
}

void dfs( vector<bool> &red, int depth){

    if(depth == N){
        sort( all(v), cmpId );
        for(int i = 0; i < N; i++){
            if(red[i]) v[i].number = v[i].red;
            else v[i].number = v[i].blue;
        }
