            if(  (diff % 2) == red[ v[i].id ] ) {
                fail = true;
                break;
            }
            else tmp += diff;

        }
        if(!fail){
            if( ans == -2 ) ans = tmp;
            else ans = min(ans, tmp);
        }
        return;
    }

    red[depth] = true;
    dfs( red, depth + 1);
    red[depth] = false;
    dfs( red, depth + 1);


}



