using ll = long long int;
using vi = vector<ll>;
using vvi = vector<vi>;

vi used, red, blue, perm, s_perm;
int ans = -1, n;

bool valid(int i, int idx){
    if (idx == 0) return true;

    int next;
    if ((i%2) == (idx%2)) next = red[i];
    else next = blue[i];

    int last;
    if ((idx-1)%2 == (perm[idx-1]%2)) last = red[perm[idx-1]];
    else last = blue[perm[idx-1]];

    return next >= last;
}

bool cheap(int idx){
    return true;
}

int cost(){
    vi ciclo(n, -1);
    vi lengths;
    int act = 1;
    for (int i = 0; i < n; i++) {
        if (ciclo[i] == -1) {
            ciclo[i] = act;
            int j = i, len = 0;
            while (perm[j] != i) {
                j = perm[j];
                ciclo[j] = act;
                len++;
            }
            act++;
            lengths.push_back(len);
        }
    }
    int res = 0;
    for (int a : lengths) res += a;
    return res;
}

void solve(int idx){
    if (idx == n) {
        int c = cost();
        if (ans != -1) ans = min(ans, c);
        else ans = c;
        s_perm = perm;
    } else if (cheap(idx)){
        for (int i = 0; i < n; i++) {
            if (not used[i] and valid(i, idx)){
                used[i] = true;
                perm[idx] = i;
                solve(idx+1);
                used[i] = false;
            }
        }
    }
}

