int ans;
int astar()
{
	int tp = 0;
	for(int i = 2;i <= n;i++)
	{
		if(e[val[i]].v[f[i]] < e[val[i - 1]].v[f[i - 1]])tp++;		
	}
	if(tp == 0)return 0;
	if(tp % 3 == 0)return tp / 3;
	else return tp / 3 + 1;
}
void dfs(int maxlen,int t,int fc)
{
	if(ans)return;
	for(int i = 2;i <= n;i++)
	{
		if(i == fc) continue;
		swap(val[i],val[i - 1]);
		f[i] ^= 1;
		f[i - 1] ^= 1;
		int tt = astar();
		if(tt == 0)
		{
			ans = 1;
			return;
		}
		if(t + tt <= maxlen)dfs(maxlen,t + 1,i);
		f[i] ^= 1;
		f[i - 1] ^= 1;
		swap(val[i],val[i - 1]);
	}
}
