			for (int i = 1; i < odd.size(); i++) {
				if (even[i - 1].first > odd[i].first)judge = true;
			}
			for (int i = 0; i < odd.size(); i++) {
				if (odd[i].second < i*2)left += i*2 - odd[i].second;
				else right += odd[i].second-i*2;
			}
			if (judge)continue;
			if (left != right)continue;
			ans = min(ans, left);
		}
	}
	if (ans == INT_MAX)cout << -1;
	else cout << ans;
}

