int f(int mask , int last)
{
    if( mask == ((1<<n)-1) ) return 0 ;
    if( dp[mask][last] != -1 ) return dp[mask][last] ;

    int idx = 0 ;
    for(int i=0 ; i<n ; i++) idx += ( (mask>>i)&1 ) ;

    int cost = 0 ;

    int res = INF , fl=(idx%2) ;

    for(int i=0 ; i<n ; i++)
    {
        if( (mask&(1<<i)) ) continue ;

        if( idx>0 )
        {
            if( a[(fl^1)][last] <= a[fl][i] ) res = min(res,cost+f((mask|(1<<i)),i) ) ;
        }
        else{
            res = min(res,cost + f((mask|(1<<i)),i) ) ;
        }
        cost++ ;
    }

    return dp[mask][last] = res ;
}

