int N;
vector<vector<int>> a;

void solve(vector<int> ind, int &mn)
{
  if (SIZ(ind) == N)
  {

    vector<int> ta(N);
    vector<vector<vector<int>>> h(2, vector<vector<int>>(50));
    vector<vector<int>> idh(2, vector<int>(50,0));
    vector<int> p(N);

    REP(i, N)
    {
      ta[i] = a[i][ind[i]];
    }

    sort(ALL(ta));

    REP(i, N)
    {
      h[i & 1][ta[i]].push_back(i);
    }

    REP(i, N)
    {
      int eoro = ((i & 1) ^ ind[i]);

      if ( SIZ(h[eoro][a[i][ind[i]]]) <= idh[eoro][a[i][ind[i]]] )
      {
        return;
      }

      p[i] = h[eoro][a[i][ind[i]]][idh[eoro][a[i][ind[i]]]];
      ++ idh[eoro][a[i][ind[i]]];
    }

    int res = 0;
    REP(j, N)
    {
      REP(i, j)
      {
        if (p[j] < p[i])
        {
          ++res;
        }
      }
    }

    mn = min(mn, res);
    return;
  }

  REP(k, 2)
  {
    vector<int> temp = ind;
    temp.push_back(k);
    solve(temp, mn);
  }
}

signed main()
{
  IOS; /* making cin faster */
  SCAND(N);
  a.resize(N, vector<int>(2));
  REP(j, 2)
  {
    REP(i, N)
    {
      SCAND(a[i][j]);
      --a[i][j];
    }
  }

  int mn = INF;
  solve(vector<int>(0), mn);

  if (mn == INF)
  {
    PRINTD(-1);
  }
  else
  {
    PRINTD(mn);
  }
}

