    vector<int> A(N);
    vector<int> B(N);
    cin >> A >> B;
    int ret = INF;
    for (int _ : range(1 << N)) {
        bitset<20> b(_);
        vector<pair<int, int>> c;
        for (int i : range(N)) {
            if (b[i]) {
                c.push_back({B[i], 1});
            }
            else {
                c.push_back({A[i], 0});
            }
        }
        int cost = 0;
        for (int i : range(N)) {
            for (int j : range(1, N)) {
                if (c[j - 1].first > c[j].first) {
                    swap(c[j - 1], c[j]);
                    c[j - 1].second ^= 1;
                    c[j].second ^= 1;
                    cost++;
                }
            }
        }
        for (int i : range(N)) {
            if (c[i].second == 1) {
                if (i + 1 < N && c[i].first == c[i + 1].first) {
                    c[i].second ^= 1;
                    c[i + 1].second ^= 1;
                    cost++;
                }
                else {
                    cost = INF;
                }
            }
        }
        chmin(ret, cost);
    }
    if (ret == INF) {
        cout << -1 << endl;
    }
    else {
        cout << ret << endl;
        exit(-1);
    }
    return 0;
}

