    for (int mask = 1; mask < (1 << n); mask++) {
        for (int i = 0; i < n; i++) {
            if (!(mask & (1 << i))) continue;
            if (dp[mask][i] > INF) continue;
            int idx = __builtin_popcount(mask) - 1;
            int pre = a[(i ^ idx) & 1][i];
            for (int j = 0; j < n; j++) if (!(mask & (1 << j))) {
