const int M=18;
const int INF=0x3f3f3f3f;
int n;
int a[M][2];
int dp[1<<M][M];
int cnt[M];

int main()
{
	scanf("%d",&n);
	for(int i=0;i<n;i++)
		scanf("%d",&a[i][0]);
	for(int i=0;i<n;i++)
		scanf("%d",&a[i][1]);
	int m=1<<n;
	memset(dp,INF,sizeof(dp));
	dp[0][0]=0;
	for(int i=1;i<m;i++)
		cnt[i]=cnt[i>>1]+(i&1);
	for(int s=1;s<m;s++)
	{
		int p=cnt[s]-1;
		for(int i=0;i<n;i++)
		{
			if(!(s&(1<<i))) continue;
			int w=0;
			for(int j=0;j<n;j++)
			{
				if(!(s&(1<<j)) && j<i) w++;
			}
			if((s^(1<<i))==0)
			{
				dp[s][i]=w;
				continue;
			}
			for(int j=0;j<n;j++)
			{
				if(!((1<<j)&(s^(1<<i)))) continue;
				if(a[i][abs(i-p)&1]<a[j][abs(j-(p-1))&1]) continue;
				dp[s][i]=min(dp[s][i],dp[s^(1<<i)][j] + w);
			}
		}
	}
	int ans=INF;
	for(int i=0;i<n;i++)
		ans=min(ans,dp[m-1][i]);
	if(ans==INF) ans=-1;
	printf("%d\n",ans);
	return 0;
}

