// 多次元 vector 生成
template <class T> vector<T> make_vec(size_t a) { return vector<T>(a); }
template <class T, class... Ts> auto make_vec(size_t a, Ts... ts) {
    return vector<decltype(make_vec<T>(ts...))>(a, make_vec<T>(ts...));
}
template <class T> bool chmax(T &a, const T &b) {
    if (a < b) {
        a = b;
        return 1;
    }
    return 0;
}
template <class T> bool chmin(T &a, const T &b) {
    if (b < a) {
        a = b;
        return 1;
    }
    return 0;
}
int main() {
    // cin.tie(0);
    // ios::sync_with_stdio(false);

    int N;
    cin >> N;
    vector<int> A(N), B(N);
    REP(i, N) { cin >> A.at(i); }
    REP(i, N) { cin >> B.at(i); }

    int ans = INF;
    int bit = 0;
    while (bit < 1 << N) {
        vector<pair<int, int>> even, odd;
        int mask = 1;
        int sum = 0;
        REP(i, N) {
            if (mask & bit) { // ビットが立てば裏
                if (i % 2 == 0) {
                    odd.push_back(make_pair(B[i], i));
                } else {
                    even.push_back(make_pair(B[i], i));
                }
            } else {
                if (i % 2 == 0) {
                    even.push_back(make_pair(A[i], i));
                } else {
                    odd.push_back(make_pair(A[i], i));
                }
            }
            mask = mask << 1;
        }

        sort(ALL(even));
        sort(ALL(odd));

        if (!((even.size() == (N + 1) / 2) && (odd.size() == N / 2))) {
            bit++;
            continue;
        }

        bool flag = false;
        REP(i, odd.size()) {
            if (odd[i].first < even[i].first) {
                flag = true;
            }
        }
        FOR(i, 1, even.size()) {
            if (odd[i - 1].first > even[i].first) {
                flag = true;
            }
        }

        vector<int> ind;
        REP(i, N) {
            if (i % 2 == 0) {
                // cout << even[i / 2] << " ";
                ind.push_back(even[i / 2].second);
            } else {
                // cout << odd[i / 2] << " ";
                ind.push_back(odd[i / 2].second);
            }
        }

        int t = 0;
        for (int i = 0; i < N - 1; i++) {
            for (int j = 0; j < N - i - 1; j++) {
                if (ind[j] > ind[j + 1]) { // 右隣が小さければ入れ替える
                    swap(ind[j], ind[j + 1]);
                    t++;
                }
            }
        }

        if (flag) {
            bit++;
            continue;
        }
        chmin(ans, t);
        bit++;
    }

    if (ans == INF) {
        cout << -1 << endl;
    } else {
        cout << ans << endl;
    }
    return 0;
}

