int dp[1 << 18][20];
signed main() {
	cin >> n;
	rep(i, n) cin >> a[i].fs;
	rep(i, n) cin >> a[i].sc;
	int ans = inf;
	rep(i, 1 << n) {
		rep(j, n+1) {
			dp[i][j] = inf;
		}
	}
	dp[0][n] = 0;
	rep(i, 1 << n) {
		rep(j, n + 1) {
			if (dp[i][j] == inf) continue;
			int bit[20], rui[20], cnt = 0;
			rep(k, n) {
				bit[k] = 0;
				if ((1 & (1 << k)) != 0) bit[k] = 1;
				cnt += bit[k];
			}
			rep(k, n) {
				rui[k] = bit[k];
			}
			req(n - 1, k) rui[k] += rui[k + 1];
			int preval = a[j].fs;
			if (j == n) preval = -inf;
			else if (abs(cnt - j) % 2 == 0) preval = a[j].sc;
			rep(k, n) {
				if (bit[k] == 1) continue;
				int r = a[k].fs;
				if (abs(cnt - k) % 2 == 1) r = a[k].sc;
				if (preval <= r) {
					dp[i + (1 << k)][k] = min(dp[i + (1 << k)][k], dp[i][j] + rui[k]);
				}
			}
		}
	}
	int ans = inf;
	rep(i, n) ans = min(ans, dp[(1 << n) - 1][i]);
	if (ans == inf) cout << -1 << endl;
	else cout << ans << endl;
}

