template<class T>
inline bool chmin(T& a, const T b) { return a > b && (a = b, true); }

int main() {

	int N;
	cin >> N;

	vector<int> A(N), B(N);
	for (int i = 0; i < N; i++) cin >> A[i];
	for (int i = 0; i < N; i++) cin >> B[i];

	int ans = INF;
	auto check = [&](auto &C) {

		DMP(C);
		vector<pair<int, int>> CI(N);
		for (int i = 0; i < N; i++) CI[i] = { C[i], i };
		sort(CI.begin(), CI.end());

		bool res = true;
		int cnt = 0;
		for (int i = 0; i < N; i++) {
			const auto& [c, idx] = CI[i];
			cnt += abs(i - idx);
			if ((idx - i) & 1) res &= c == B[idx];
			else res &= c == A[idx];
			if (!res) break;
		}

		if (res) {
			assert(cnt % 2 == 0);
			chmin(ans, cnt / 2);
		}

		return res;

	};

	for (int bit = 0; bit < (1 << N); bit++) {
		auto C = A;
		for (int i = 0; i < N; i++) {
			if ((bit >> i) & 1) C[i] = B[i];
		}
		check(C);
	}

	cout << (ans == INF ? -1 : ans) << "\n";

	return 0;
}

