int main(int argc, char *argv[])
{
	ios::sync_with_stdio(false); cin.tie(0);
	int n;
	cin >> n;
	vector<int> a(n), b(n);
	for (int i = 0; i < n; i++) cin >> a[i];
	for (int i = 0; i < n; i++) cin >> b[i];

	int ans = -1;
	for (int k = 0; k < (1 << n); k++) {
		if (__builtin_popcount(k) % 2 != 0) continue;
		vector<pair<int, pair<int, int> > > t(n);
		for (int i = 0, z = k; i < n; i++, z >>= 1)
			t[i] = make_pair(z % 2 == 0 ? a[i] : b[i], make_pair(i, z % 2));
		sort(t.begin(), t.end());
		int ok = 1, count = 0;
		for (int i = 0; i < n; i++) {
			int d = abs(i - t[i].second.first);
			if (d % 2 != t[i].second.second) {
				ok = 0;
				break;
			}
			count += d;
		}
		count /= 2;
		if (ok && (ans < 0 || count < ans)) ans = count;
	}

	cout << ans << endl;

	return 0;
}

#include <bits/stdc++.h>
using namespace std;
#define rep(i,n) for(int i = 0; i < (int)n; i++)
using P = pair<int,int>;
const int INF = 1e9;

int mod(int a, int b) {
  return ((a-b) % 2 + 2) % 2;
}

template <typename T>
class BIT {
  int n;
  vector<T> bit;
public:
  BIT(int _n) {
    n = _n;
    bit = vector<T>(n+1,(T)0);
  }
  T sum(int i) {
    T s = 0;
    while(i > 0){
    s += bit[i];
    i -= i & -i;
  }
  return s;
  }
  void add(int i, T x) {
    while(i <= n){
    bit[i] += x;
    i += i & -i;
    }
  }
};

int main(){
  int n;
  cin >> n;
  int a[n], b[n];
  rep(i,n) cin >> a[i];
  rep(i,n) cin >> b[i];
  int ans = INF;
  rep(i,1<<n) {
    vector<vector<P>> v(51);
    rep(j,n) {
      if((1<<j) & i) v[a[j]].push_back(P(j,0));
      else v[b[j]].push_back(P(j,1));
    }
    bool can = true;
    vector<int> p(n,2);
    int c = 0;
    rep(j,51) {
      sort(v[j].begin(),v[j].end());
      int l = v[j].size();
      int f = c, s = c+1;

      for(auto k : v[j]) {
        if(mod(c,k.first) == k.second) {
          if(f >= c+l) {
            can = false;
            break;
          }
          p[f] = k.first;
          f += 2;
        } else {
          if(s >= c+l) {
            can = false;
            break;
          }
          p[s] = k.first;
          s += 2;
        }
      }
      c += l;
    }
    if(can) {
      int res = 0;
      BIT<int> bit(n);
      rep(j,n) {
        res += j - bit.sum(p[j]+1);
        bit.add(p[j]+1,1);
      }
      ans = min(ans,res);
    }
  }
  if(ans == INF) cout << -1 << endl;
  else cout << ans << endl;
}

