const int INF = 1145141919;

int color(int init, int pos) {
    if (init < pos)swap(init, pos);
    return (init - pos) % 2;
}

int main() {
    int n;
    cin >> n;
    vector<vector<int>> card(n, vector<int>(2));
    for (int i = 0; i < n; i++)cin >> card[i][0];
    for (int i = 0; i < n; i++)cin >> card[i][1];

    vector<vector<int>> dp(1 << n, vector<int>(n, INF));
    dp[0][0] = 0;
    for (int nowBit = 0; nowBit < 1 << n; nowBit++) {
        int bitCount = 0;
        for (int i = 0; i < n; i++) {
            if (nowBit & (1 << i))bitCount++;
        }

        if (nowBit == 0) {
            for (int next = 0; next < n; next++) dp[1 << next][next] = dp[0][0] + next;
        } else {
            for (int prev = 0; prev < n; prev++) {
                if ((nowBit & (1 << prev)) == 0)continue;

                int notused = 0;
                for (int next = 0; next < n; next++) {
                    if (nowBit & (1 << next))continue;

                    int prevnum = card[prev][color(prev, (bitCount - 1) % 2)];
                    int nextnum = card[next][color(next, bitCount % 2)];
                    if (prevnum <= nextnum) {
                        int nextBit = nowBit | (1 << next);
                        dp[nextBit][next] = min(dp[nextBit][next], dp[nowBit][prev] + notused);
                    }
                    notused++;
                }
            }
        }
    }

    int ret = INF;
    for (auto x:dp[(1 << n) - 1])ret = min(ret, x);
    cout << (ret == INF ? -1 : ret) << endl;
    return 0;
}

