const int INF = (int)1e9;

int dp[1 << 18][18];

int A[18], B[18];

int n;

bool bit(int x, int p) {
    return x & (1 << p);
}

void solve() {
    scanf("%d", &n);

    for (int i = 0; i < n; ++i) {
        scanf("%d", &A[i]);
    }

    for (int i = 0; i < n; ++i) {
        scanf("%d", &B[i]);
    }

    for (int i = 0; i < n; ++i) {
        if (i & 1) {
            swap(A[i], B[i]);
        }
    }

    /*
    for (int i = 0; i < n; ++i) {
        printf("%d %d\n", A[i], B[i]);
    }
    */

    for (int i = 0; i < (1 << n); ++i) {
        for (int j = 0; j < n; ++j) {
            dp[i][j] = INF;
        }
    }

    for (int i = 0; i < n; ++i) {
        dp[1 << i][i] = 0;
    }

    for (int mask = 0; mask < (1 << n); ++mask) {
        int bpop = __builtin_popcount(mask);

        for (int i = 0; i < n; ++i) {
            if (dp[mask][i] == INF) {
                continue;
            }

            if (bit(mask, i)) {
                int cur = (bpop % 2 ? A[i] : B[i]);
                int w = 0;

                for (int j = n - 1; j >= 0; --j) {
                    if (!bit(mask, j)) {
                        int nxt = (bpop % 2 ? B[j] : A[j]);

                        if (nxt >= cur) {
                            dp[mask + (1 << j)][j] = min(dp[mask + (1 << j)][j], dp[mask][i] + w);
                        }
                    }
                    else {
                        ++w;
                    }                
                }                
            }            
        }   
    }

    int ans = INF;

    for (int i = 0; i < n; ++i) {
        ans = min(ans, dp[(1 << n) - 1][i]);
    }

    if (ans >= INF) {
        ans = -1;
    }

    printf("%d\n", ans);
}

int main() {
    int tt = 1;

    while (tt--) {
        solve();
    }

    return 0;
}

