	m = n - l;
	for (int i = 0; i < rui[n]; i++) {
		l = i;
		k = 0;
		for (int j = 0; j < n; j++) {
			t[j] = l % 2;
			l /= 2;
			if (t[j])k++;
		}
		if (k == m) {
			pn = 0; qn = 0; x = 0;
