			for (int j = 0; j < pn - (n % 2); j++) {
				if ((p[j] / 100) > (q[j] / 100))g = 0;
			}
			for (int j = 0; j < qn - ((n + 1) % 2); j++) {
				if ((q[j] / 100) > (p[j + 1] / 100))g = 0;
			}
			if (g && ans > (x / 2))ans = x / 2;
		}
	}
