class DSwapAndFlip {
public:

    void solve(std::istream &cin, std::ostream &cout, std::ostream &cerr) {
        int N;
        cin >> N;
        int ans = 1e9;
        vector<Card> cards(N);
        REP(i, N)cin >> cards[i].c0;
        REP(i, N)cin >> cards[i].c1;
        vector<PII > order;
//        vector<int> order(55);
//        G(order, 55);

        auto ok = [&](int mask) {
            int sum = 0;
            vector<int> pairing(N,-1);
            ERR(mask)
            REP(i,N){
                int num;
                if(mask & BIT(i))num = cards[i].c1;else num = cards[i].c0;
                REP(j,N){
                    ERR(i,j,num,order[j].F)
                    ERR(num == order[j].F )
                    ERR((abs(i-j)%2 ), ( mask & BIT(i)))
                    ERR( pairing[j])
                    if(num == order[j].F && ((abs(i-j)%2 )== !!( mask & BIT(i))) && pairing[j] == -1){
                        ERR(i,j)
                        pairing[j] = i;
                        break;
                    }
                }
            }
            ERR(pairing)
            REP(j,N)if(pairing[j] == -1)return -1;
//
//            REP(i, N) {
//                if (abs(order[i].S - i) % 2) { if (order[i].F != cards[order[i].S].c1){ERR(i,order[i].F,cards[order[i].S].c1);return -1;} }
//                else { if (order[i].F != cards[order[i].S].c0){ERR(i,order[i].F,cards[order[i].S].c0);return -1;} }
//            }
            REP(i,N-1)FOR(j,i+1,N)if(pairing[i] > pairing[j])sum ++;
            return sum;
        };
        REP(mask, BIT(N)) {
            order.clear();

            REP(i, N) {
                if (mask & BIT(i))
//                    order[cards[i].c1].EB(i);
                    order.PB({cards[i].c1, i});
                else order.PB({cards[i].c0, i});
            }
            sort(ALL(order));

            ERR(order)
            int t = ok(mask);
            ERR(t)
            if (~t) {
                Chmin(ans, t);
            }
        }
        print((ans > 1e8) ? -1 : ans);
    }


};


