				if(j%2==1){Odd.push_back({A[j],j});}
				else{Odd.push_back({B[j],j});}
			}
		}
		SortedOdd=Odd;
		SortedEven=Even;
		sort(SortedOdd.begin(),SortedOdd.end());
		sort(SortedEven.begin(),SortedEven.end());
		long long int now=0;
		bool Breaker=false;
		for(int j=0;j<SortedEven.size();j++){
			if(now<=SortedEven[j].first){
				now=SortedEven[j].first;
				Check[SortedEven[j].second]=2*SortedEven[j].first+2*j;
			}
			else{Breaker=true;break;}
			if(N%2==1&&j==SortedEven.size()-1){break;}

			if(now<=SortedOdd[j].first){
				now=SortedOdd[j].first;
				Check[SortedOdd[j].second]=2*SortedOdd[j].first+2*j+1;
			}
			else{Breaker=true;break;}
		}
		if(Breaker){continue;}
		long long int rev=0;
		for(int i=0;i<N;i++){
			for(int j=i+1;j<N;j++){
				if(Check[i]>Check[j]){rev++;}
			}
		}
		res=min(res,rev);
	}
	if(res==INF){res=-1;}
	cout<<res;
}

