  for (ll i = 0; i < n; i++) scanf("%lld", &b[i]);
  for (ll i = 0; i < (1LL << n); i++) {
    if (__builtin_popcountll(i) % 2 == 1) continue;
    for (ll j = 0; j < n; j++) p[j] = (i & (1LL << j)) > 0 ? P(b[j], 1) : P(a[j], 0);
    ll temp = 0;
    while (1) {
      bool ok = true;
      for (ll j = 0; j < n-1; j++) {
        if (p[j].first > p[j+1].first) {
          swap(p[j], p[j+1]);
          p[j].second++, p[j+1].second++;
          ok = false;
          temp++;
        }
      }
      if (ok) break;
    }
    bool ok = true;
    for (ll j = 0; j < n-1; j++) {
      if (p[j].second % 2 == 1) {
        ll k = j+1;
        while (k < n && p[k].second % 2 == 0) k++;
        if (k == n) {
          ok = false;
          break;
        }
        k -= 2;
        while (k >= j) {
          swap(p[k], p[k+1]);
          p[k].second++, p[k+1].second++;
          temp++;
          k -= 2;
        }
        if (p[j].second % 2 == 1) {
          swap(p[j], p[j+1]);
          p[j].second++, p[j+1].second++;
          temp++;
        }
      }
    }
    for (ll j = 0; j < n; j++) {
      if (p[j].second % 2 == 1) {
        ok = false;
        break;
      }
    }
    for (ll j = 0; j < n-1; j++) {
      if (p[j].first > p[j+1].first) {
        ok = false;
        break;
      }
    }
    if (ok) {
      ans = min(ans, temp);
      /*
      printf("%lld\n", temp);
      for (ll j = 0; j < n; j++) printf("%lld ", p[j].first); printf("\n");
      */
    }
  }
  if (ans == INF) ans = -1;
  printf("%lld\n", ans);
}

