const int MAX_N = 18;

class BIT {
public:
  vector <ll> bit;
  int N;

  BIT(int n) {
    N = n;

    for (int i = 0; i <= N; ++i) {
      bit.push_back(0);
    }
  }

  ll sum(int i) {
    ll ret = 0;

    while (i > 0) {
      ret += bit[i];
      i -= i & -i;
    }

    return ret;
  }

  void add(int i, ll x) {
    while (i <= N) {
      bit[i] += x;
      i += i & -i;
    }
  }
};

ll sort_count(vector<int> orders, int N) {
  ll ans = 0;
  BIT bit(N);

  for (int i = 0; i < N; ++i) {
    int a = orders[i];
    ans += i - bit.sum(a);
    bit.add(a, 1);
  }

  return ans;
}

int main() {
  int N;
