  for (int i = 0; i < N; ++i) {
    cin >> a;
    A.push_back(a);
  }

  for (int i = 0; i < N; ++i) {
    cin >> b;
    B.push_back(b);
  }

  vector<Card> EVEN_CARDS;
  vector<Card> ODD_CARDS;

  for (int i = 0; i < N; ++i) {
    if (i % 2 == 0) {
      EVEN_CARDS.push_back(A[i]);
      ODD_CARDS.push_back(B[i]);
    } else {
      EVEN_CARDS.push_back(B[i]);
      ODD_CARDS.push_back(A[i]);
    }
  }

  ll ans = LONG_MAX;

  do {
    int nums[N];
    vector<int> list(N);

    for (int i = 0; i < N; ++i) {
      int order = orders[i];
      list[i] = order + 1;

      if (i % 2 == 0) {
        nums[i] = EVEN_CARDS[order].num;
      } else {
        nums[i] = ODD_CARDS[order].num;
      }
    }

    bool sorted = true;

    for (int i = 0; i < N - 1 && sorted; ++i) {
      if (nums[i] > nums[i + 1]) {
        sorted = false;
      }
    }

    if (sorted) {
      ll cnt = sort_count(list, N);

      if (ans > cnt) {
        ans = cnt;
      }
    }
  } while (next_permutation(orders, orders + N));

  if (ans == LONG_MAX) {
    cout << -1 << endl;
  } else {
    cout << ans << endl;
  }

  return 0;
}

