#ifdef __GNUC__
#define popcount __builtin_popcount
#elif _MSC_VER >= 1400
#include <intrin.h>
#define popcount __popcnt
#else
static inline int popcount(unsigned int b) {
	b = (b & 0x55555555) + (b >> 1 & 0x55555555);
	b = (b & 0x33333333) + (b >> 2 & 0x33333333);
	b = (b & 0x0F0F0F0F) + (b >> 4 & 0x0F0F0F0F);
	b += b >> 8;
	return (b + (b >> 16)) & 0x3F;
}
#endif

int main(int argc, char* argv[]) {
#ifdef _MSC_VER
	while (true)
#endif
	{
		static const unsigned int INF = -1;
		int n = 0;
		cin >> n;
		if (n <= 0) return 0;
		vector<int> a[2];
		for (int j = 0; j < 2; ++j) {
			a[j] = vector<int>(n);
			for (int i = 0; i < n; ++i) {
				cin >> a[j][i];
			}
		}
		unsigned int dp[1 << 18][18];
		memset(dp, -1, sizeof(dp));
		for (int c = 0; c < n; ++c) {
			dp[1 << c][c] = 0;
		}
		for (int b = 1; b < (1 << n); ++b) {
			int digits = popcount(b);
			for (int c = 0; c < n; ++c) {
				if (dp[b][c] >= INF) continue;
				int p = a[(digits + c - 1) & 1][c];
				for (int d = 0; d < n; ++d) {
					int q = a[(digits + d) & 1][d];
					if (p > q) continue;
					if (b & (1 << d)) continue;
					unsigned int cost = dp[b][c] + popcount(b & ~((1 << d) - 1));
					int e = b | (1 << d);
					dp[e][d] = min(dp[e][d], cost);
				}
			}
		}
		unsigned int ans = INF;
		for (int c = 0; c < n; ++c) {
			ans = min(ans, dp[(1 << n) - 1][c]);
		}
		cout << (int)ans << endl;
	}
	return 0;
}

