	rep(i, 1 << n) {
		rep(j, n + 1) {
			if (dp[i][j] == inf) continue;
			int bit[20], rui[20], cnt = 0;
			rep(k, n) {
				bit[k] = 0;
				if ((i & (1 << k))) bit[k] = 1;
				cnt += bit[k];
			}
			rep(k, n) {
				rui[k] = bit[k];
			}
			req(n - 1, k) rui[k] += rui[k + 1];
			int preval = a[j].fs;
			if (j == n) preval = -inf;
			else if (abs(cnt - j) % 2 == 0) preval = a[j].sc;
			rep(k, n) {
