#define REP(i,n) for (ll i = 0; i < (n); ++i)

vector<vector<ll>> num;

map<pair<ll, ll>, ll> dp;

ll solve_sub(ll used, ll last){
    const ll N = num.size();

    if(dp.count({used, last})){
        return dp.at({used, last});
    }

    vector<ll> not_used;
    REP(i, N){
        if(((used >> i) & 1) == 0){
            not_used.push_back(i);
        }
    }

    if(not_used.size() == 0){
        dp[{used, last}] = 0;
        return 0;
    }

    const ll cur_pos = N - not_used.size();
    ll ret = -1;
    for(ll j : not_used){
        if(num.at(j).at(cur_pos) < last){
            continue;
        }
        ll tmp = solve_sub(
            used | (1 << j),
            num.at(j).at(cur_pos)
        );
        if(tmp == -1){ continue; }
        for(ll j2 : not_used){
            tmp += (j2 < j);
        }
        if(ret == -1 || tmp < ret){
            ret = tmp;
        }
    }

    dp[{used, last}] = ret;
    return ret;
}

