    num.resize(N);
    REP(i, N){
        num.at(i).resize(N);
        REP(j, N){
            if((i - j) % 2 == 0){
                num.at(i).at(j) = A.at(i);
            }else{
                num.at(i).at(j) = B.at(i);
            }
        }
    }

    ll ans = solve_sub(0, -100);
    cout << ans << endl;
}

