            if(U[j]<U[j-1]){
                ll tmp = U[j-1];
                U[j-1] = U[j];
                U[j] = tmp;
                ret++;
            }
        }
    }
    ll f = 0;
    ll bef=INF;
    vector<ll> used(n,0),ch(n,0);
    for(ll i=0;i<n;i++){
        for(ll j=0;j<n;j++){
            if(used[j]==0 && U[i]==P[j]){
                //if(x == 2 && i == 1) cout << ((i % 2) + (j % 2)) % 2 << " " << (x >> j) % 2 << endl;
                if(((i%2)+(j%2))%2 != (x>>j)%2){
                    ch[i] = 1;
                }
                used[j] = 1;
                break;
            }
        }
    }

    for(ll i=0;i<n;i++){
        f += used[i];
    }
    for(ll i=0;i<n;i++){        
        if(ch[i]==1){
            if(i==n-1)return INF;
            if(U[i]==U[i+1] && ch[i+1]==1){
                ret++;
                ch[i] = ch[i+1] = 0;
            }else{
                return INF;
            }
        }
    }
    if(f==n){
        return ret;
    }
    return INF;
}

