using namespace std;

const int INF = (int) 1e9;
const int N = 18;
const int L = 50;

int n;
int a[N];
int b[N];
int dp[1 << N][L + 1];

void read()
{
        cin >> n;
        for (int i = 0; i < n; i++)
                cin >> a[i];
        for (int i = 0; i < n; i++)
                cin >> b[i];
}

void init()
{
        for (int i = 0; i < (1 << N); i++)
                for (int j = 0; j <= 50; j++)
                        dp[i][j] = INF;
        dp[0][1] = 0;
}

bool is(int mask, int i)
{
        if (mask & (1 << i))
                return 1;
        else
                return 0;
}

void compute()
{
        for (int mask = 0; mask < (1 << n) - 1; mask++)
        {
                int p = 0;
                for (int i = 0; i < n; i++)
                        if (is(mask, i))
                                p++;
                for (int i = 0; i < n; i++)
                        if (!is(mask, i))
                        {
                                int cntb = 0;
                                for (int j = i; j < n; j++)
                                        cntb += is(mask, j);

                                int dist = abs(i - p), nval;
                                if (dist % 2 == 0)
                                        nval = a[i];
                                else
                                        nval = b[i];

                                for (int cur = 1; cur <= nval; cur++)
                                        dp[mask + (1 << i)][nval] = min(dp[mask + (1 << i)][nval], i + cntb - p + dp[mask][cur]);
                        }
        }
}

int solve()
{
        int sol = INF;
        for (int last = 1; last <= 50; last++)
                sol = min(sol, dp[(1 << n) - 1][last]);
        if (sol == INF)
                return -1;
        else
                return sol;
}

int main()
{
        ios_base::sync_with_stdio(0); cin.tie(0); cout.tie(0);

        read();
        init();
        compute();
        cout << solve() << "\n";
}

