using namespace std;
const int MAXN=60;
int N,Ans,A[MAXN],B[MAXN],C[MAXN],pos[MAXN];
bool Mark[MAXN],flag[MAXN];
void solve()
{
	int sum=0;
	for (int i=1;i<=N;++i) Mark[i]=false,pos[i]=i;
	for (int i=1;i<=N;++i)
	{
		int p=i;
		for (int j=i+1;j<=N;++j)
			if (C[j]<C[p])
				p=j;
		if (p>i)
		{
			sum+=p-i;
			for (int j=p;j>i;--j)
			{
				Mark[pos[j]]^=1;
				Mark[pos[j-1]]^=1;
				swap(C[j],C[j-1]);
				swap(pos[j],pos[j-1]);
			}
		}
	}
	for (int i=1;i<=N;++i) Mark[pos[i]]^=flag[pos[i]];
	for (int i=1;i<=N;++i)
	{
		int j=i;
		while (j<N && C[j]==C[j+1]) ++j;
		int cnt=0;
		for (int k=i;k<=j;++k) cnt+=Mark[pos[k]];
		if (cnt&1) return ;
		if (i==j)
		{
			if (cnt==0) continue;
			else return ;
		}
		else sum+=cnt/2;
		i=j;
	}
	/*
	printf("c=");
	for (int i=1;i<=N;++i) printf("%d ",C[i]);cout<<endl;
	for (int i=1;i<=N;++i) printf("%d ",flag[i]);cout<<endl;
	cout<<sum<<endl;
	*/
	if (Ans==-1) Ans=sum;
	else Ans=min(Ans,sum);
}
void dfs(int x)
{
	if (x==N+1)
	{
		for (int i=1;i<=N;++i) C[i]=(flag[i]?B[i]:A[i]);
		solve();
		return ;
	}
	flag[x]=true;
	dfs(x+1);
	flag[x]=false;
	dfs(x+1);
}
