    }

    rep(i,0,n-1) {
      if (bad[i] and bad[i+1] and x[i] == x[i+1]) bad[i] = bad[i+1] = 0;
    }

    if (*max_element(all(bad)) == 0LL) {
      if (ans == -1) ans=swp;
      ans = min(ans, swp);
    }
  }
  cout << ans << endl;
}

