struct card {
  Z pos, num;
  bool blue;
};

class fenwick {
  private:
    int len;
    vector<Z> data;
  public:
    fenwick(int n) {
      len = 1;
      while (len < n) len *= 2;
      len++;
      data.resize(len);
    }
    Z sum(Z to) {
      to++;
      Z total = 0;
      for (Z i = to; i > 0; i -= i & -i) {
        total += ix(data, i);
      }
      return total;
    }
    void add(Z pos, Z x) {
      pos++;
      for (Z i = pos; i < len; i += i & -i) {
        ix(data, i) += x;
      }
    }
};


int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);
  cout.precision(10);
  cout << fixed;
  Z N;
  cin >> N;
  vector<Z> As(N), Bs(N);
  cin >> As >> Bs;
  Z ans = INF;
  for (auto i = 0; i < (1 << N); i++) {
    if (__builtin_popcount(i) % 2 == 1) continue;
    dump(i);
    vector<card> cards(N);
    for (auto j = 0; j < N; j++) {
      if (i & (1 << j)) {
        ix(cards, j) = {j, ix(Bs, j), true};
      }
      else {
        ix(cards, j) = {j, ix(As, j), false};
      }
    }
    sort(begin(cards), end(cards),
        [] (auto const& x, auto const& y) {
          if (x.num != y.num) return x.num < y.num;
          else return x.pos < y.pos;
        }
    ) ;
    Z cost = 0, different = 0;
    cards.push_back({-1, INF, true});
    bool possible = true;
    for (auto j = 0; j < N; j++) {
      if (different > j) continue;
      while (ix(cards, different).num == ix(cards, j).num)
        different++;
      vector<Z> bads;
      for (auto k = j; k < different; k++) {
        if (abs(ix(cards, k).pos - k) % 2 != ix(cards, k).blue) {
          bads.push_back(k);
        }
      }
      if (bads.size() % 2 == 1) {
        possible = false;
        break;
      }
      for (auto it = begin(bads); it != end(bads); it += 2) {
        Z diff = *(it + 1) - *it;
        if (diff % 2 == 0) {
          possible = false;
          break;
        }
        cost += diff / 2 + (diff / 2 + 1);
      }
    }
    dump(possible);
    if (!possible) continue;
    dump(cost);
    fenwick fwt(51);
    for (auto j = 0; j < N; j++) {
      Z num = (i & (1 << j)) ? ix(Bs, j) : ix(As, j);
      cost += j - fwt.sum(num);
      fwt.add(num, 1);
    }
    dump(cost);
    ans = min(cost, ans);
  }
  cout << (ans == INF ? -1 : ans) << endl;
}

