void shushoku(vector <ll> &arr, ll pad){
    vector <ll> arr2 = arr;
    sort(arr2.begin(), arr2.end());
    ll size = arr.size();
    REP(i, size){
        REP(j, size){
            if (arr2[i] == arr[j]){
                arr[j] += 200*i + pad;
                break;
            }
        }
    }
}

