    if (flipped.count() % 2) continue;
    vector<int> u(n), v;
    for (int i = 0; i < n; i++) u[i] = a[flipped[i]][i];
    v = u;
    sort(v.begin(), v.end());

    int t = 0;
    bitset<18> used;
    for (int i = 0; i < n; i++) {
      int nearest_j = -1;
      for (int j = 0; j < n; j++) {
        if (used[j]) continue;
        if (u[j] == v[i] && abs(i - j) % 2 == flipped[j]) {
          if (nearest_j == -1 || abs(i - j) < abs(i - nearest_j)) nearest_j = j;
        }
      }
      if (nearest_j == -1) {
        t = 2e9;
        break;
      } else {
        t += abs(i - nearest_j);
        used[nearest_j] = true;
      }
    }
    r = min(r, t / 2);
  }
  cout << (r == 1e9 ? -1 : r) << endl;
}

