void update(int tmp,int v)
{
    while(tmp){
        tree[tmp]+=v;
        tmp>>=1;
    }

    return;
}

int getans(int L,int R)
{
    int res = 0;

    while(L<=R){
        if(L&1){res+=tree[L]; L++;}
        if(!(R&1)){res+=tree[R]; R--;}
        L>>=1; R>>=1;
    }

    return res;
}


int solve(int n,int x)
{
    int cnt = 0;

    for(int i=0;i<n;i++){
        if((1<<i)&x)cnt++;
    }

    if(cnt!=(n>>1))return INF;

    vector<pii> even;
    vector<pii> odd;

    for(int i=0;i<n;i++){
        if((1<<i)&x){
            if(i&1)odd.push_back(pii(A[i],i));
            else odd.push_back(pii(B[i],i));
        }
    }

    for(int i=0;i<n;i++){
        if(!((1<<i)&x)){
            if(!(i&1))even.push_back(pii(A[i],i));
            else even.push_back(pii(B[i],i));
        }
    }

    sort(odd.begin(),odd.end());
    sort(even.begin(),even.end());

    for(int i=0;i<even.size();i++){
        vv[(i<<1)] = even[i].f;
    }

    for(int i=0;i<odd.size();i++){
        vv[(i<<1)|1] = odd[i].f;
    }

    bool judge = true;

    for(int i=1;i<n;i++){
        judge&=(vv[i]>=vv[i-1]);
    }

    if(!judge)return INF;

    for(int i=0;i<even.size();i++)
        ord[even[i].s] = (i<<1);

    for(int i=0;i<odd.size();i++)
        ord[odd[i].s] = (i<<1)|1;

    int base = 1;
    int res =0;

    for(;base<n;base<<=1);

    for(int i=1;i<(base<<1);i++)
        tree[i] = 0;

    for(int i=0;i<n;i++){
        res+=getans(base+ord[i],(base<<1)-1);
        update(base+ord[i],1);
    }
    return res;
}


