int dfs(int hav, int ma,int cnt)
{
	if(dp[hav][ma] != -1) return dp[hav][ma];
	if(cnt == n) return 0;
	dp[hav][ma] = 1008610086;
	int dx,ans;
	for(int i = 0; i < n;i ++){
		if(hav & (1 << i)) continue;
