struct card
{
	vector<int> r;
	vector<int> b;
	//int size;
	int now;
	bool operator<(const card& rhs)const
	{
		if(rhs.r==r&&rhs.b==b)return true;

		return false;

	}
};

int main()
{
	int n;
	cin >> n;
	card a;
	//a.size=n;
	map<vector<int>,bool> mp;
	rep(i,n)
	{
		int foo;
		cin >> foo;
		a.r.push_back(foo);
	}
	rep(i,n)
	{
		int foo;
		cin >> foo;
		a.b.push_back(foo);
	}
	queue<card> Q;
	a.now=0;
	Q.push(a);
	while(!Q.empty())
	{
		//cout<<Q.size()<<endl;
		if(isgreater(Q.front().r))
		{
			cout<<Q.front().now<<endl;
			return 0;
		}

		if(mp[Q.front().r])
		{
			Q.pop();
			continue;
		}
		mp[Q.front().r]=true;
		rep(i,n-1)
		{
			card now = Q.front();
			swap(now.r[i],now.b[i+1]);
			swap(now.b[i],now.r[i+1]);
			now.now++;
			Q.push(now);
		}
		Q.pop();
	}
	cout<<-1<<endl;

	return 0;
}

