            for (int k = 0; k < 2; ++k)
                dp[i][j][k] = INF;
    for (int i = 0; i < n; ++i)
        dp[1 << i][i][i % 2] = i;
    for (int mask = 1; mask < (1 << n) - 1; ++mask)
    {
        vector<int> r;
        for (int i = 0; i < n; ++i)
