                            }
                        }
                        else
                        {
                            if (j == 0)
                            {
                                if (a[i].x <= a[r[k]].y)
                                    dp[mask | (1 << r[k])][r[k]][1] = min(dp[mask | (1 << r[k])][r[k]][1], dp[mask][i][j] + k);
                            }
                            else
                            {
                                if (a[i].y <= a[r[k]].y)
                                    dp[mask | (1 << r[k])][r[k]][1] = min(dp[mask | (1 << r[k])][r[k]][1], dp[mask][i][j] + k);
                            }
                        }
                    }
                    else
                    {
                        if (p[k] == 0)
                        {
                            if (j == 0)
                            {
                                if (a[i].x <= a[r[k]].y)
                                    dp[mask | (1 << r[k])][r[k]][1] = min(dp[mask | (1 << r[k])][r[k]][1], dp[mask][i][j] + k);
                            }
                            else
                            {
                                if (a[i].y <= a[r[k]].y)
                                    dp[mask | (1 << r[k])][r[k]][1] = min(dp[mask | (1 << r[k])][r[k]][1], dp[mask][i][j] + k);
                            }
                        }
                        else
                        {
                            if (j == 0)
                            {
                                if (a[i].x <= a[r[k]].x)
                                    dp[mask | (1 << r[k])][r[k]][0] = min(dp[mask | (1 << r[k])][r[k]][0], dp[mask][i][j] + k);
                            }
                            else
                            {
                                if (a[i].y <= a[r[k]].x)
                                    dp[mask | (1 << r[k])][r[k]][0] = min(dp[mask | (1 << r[k])][r[k]][0], dp[mask][i][j] + k);
                            }
                        }
                    }
                }
            }
        }
    }
    int odp = INF;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < 2; ++j)
            odp = min(odp, dp[(1 << n) - 1][i][j]);
    if (odp == INF)
        odp = -1;
    cout << odp;
    return 0;
}

