int N;
int A[55], B[55], C[55], D[55];
int INF = 12345678;

int main() {
	cin >> N;
	int ans = INF;
	for (int i = 0; i < N; ++i) {
		cin >> A[i];
	}
	for (int i = 0; i < N; ++i) {
		cin >> B[i];
	}
	for (int bit = 0; bit < (1 << N); ++bit) {
		bool F[55] = {};
		for (int i = 0; i < N; ++i) {
			F[i] = (bit & (1 << i));
			C[i] = (F[i] ? B[i] : A[i]);
		}
		int can = 0;
		for (int i = 0; i < N; ++i) {
			for (int j = 0; j < i; ++j) {
				if (C[i] < C[j]) {
					F[i] = !F[i];
					F[j] = !F[j];
					can++;
				}
			}
		}
		map<int, vector<int>>tt;
		for (int i = 0; i < N; ++i) {
			tt[C[i]].push_back(F[i]);
		}
		for (auto p : tt) {
			for (int x = 0; x < (int)p.second.size() - 1; ++x) {
				if (p.second[x]) {
					p.second[x] = !p.second[x];
					p.second[x + 1] = !p.second[x + 1];
					++can;
				}
			}
			if (p.second.back()) {
				can = INF;
				break;
			}
		}
		ans = min(ans, can);
	}
	if (ans == INF)ans = -1;
	cout << ans << endl;
	return 0;
}

