bool check(int *x){
    for(int i=0;i<n-1;i++)
        if(x[i]>x[i+1])
            return false;
    return true;
}
void solve(int *a,int *b,int j,int step){
    if(j==n)
        return;
    if(check(a)){
        ans=min(ans,step);
        return;
    }
    int x[20],y[20];
    for(int i=0;i<n;i++)
        x[i]=a[i];
    for(int i=0;i<n;i++)
        y[i]=b[i];
    solve(x,y,j+1,step);
    swap(x[j],y[j+1]);
    swap(x[j+1],y[j]);
    solve(x,y,j+1,step+1);
}
