	bool operator <(const node &no)const {
		for(int i=1;i<=n;i++){
			if(a1[i]==no.a1[i]) {
				continue;
			}
			return a1[i]<no.a1[i];
		}
		for(int i=1;i<=n;i++){
			if(b1[i]==no.b1[i]){
				continue;
			}
			return b1[i]<no.b1[i];
		}
		return false;
	}
}sta;
map<node,bool> mp;
bool judge(node no){
	for(int i=1;i<n;i++){
		if(no.a1[i]>no.a1[i+1]){
			return false;
		}
	}
	return true;
}
int bfs(){
	bool flag=0;
	queue<node> q;
	q.push(sta);
	while(!q.empty()){
		node u=q.front();
		q.pop();
		/*
		for(int i=1;i<=n;i++){
			printf("%d ",u.a1[i]);			
		}printf("\n");
		for(int i=1;i<=n;i++){
			printf("%d ",u.b1[i]);			
		}printf("%d \n",u.step);
		printf("\n");
		*/
		if(judge(u)){
			flag=1;
			return u.step;
		}
		for(int i=1;i<n;i++){
			node v=u;
			swap(v.a1[i],v.b1[i]);
			swap(v.a1[i+1],v.b1[i+1]);
			swap(v.b1[i],v.b1[i+1]);
			swap(v.a1[i],v.a1[i+1]);
			if(!mp[v]){
				mp[v]=1;
				v.step++;
				q.push(v);
			}
		}
	}

	if(!flag) return -1;
}
