          order[i]= odd[i/2].second;
        }
      }
      int tans=0;
      for(int i=0;i<num;i++) {
        for(int j=0;j<torder.size();j++) {
          if(torder[j]==order[i]) {
            tans+=j;
            torder.erase(torder.begin()+j);
          }
        }
      }
      if(ans=-1) {
        ans=tans;
      }
      else {
        ans=min(ans,tans);
      }
    }
  });
  cout << ans << endl;
}

