using namespace std;
using P = pair<int, int>;

vector<int> w;
vector<vector<int>> u;

int func(vector<P> &v, vector<vector<int>> &dp, int m, int s){
	if(dp[m][s] < 1e9) return dp[m][s];
	int n = v.size();
	int k = w[s];
	if(k == n) return dp[m][s] = 0;
	int mi = 1e9;
	for(int i=0; i<(int)u[s].size(); ++i){
		if((s >> u[s][i]) & 1) continue;
		int x = (k % 2 == 0 ? v[u[s][i]].first : v[u[s][i]].second);
		if(x < m) continue;
		mi = min(mi, i+func(v, dp, x, s|(1<<u[s][i])));
	}
	return dp[m][s] = min(dp[m][s], mi);
}

int main(){
