	for(int i=0; i<n; ++i) cin >> b[i];
	vector<P> v(n);
	for(int i=0; i<n; ++i) v[i] = (i % 2 == 0 ? P(a[i], b[i]) : P(b[i], a[i]));
	vector<vector<int>> dp(51, vector<int>(1<<n, 1e9));
	w.resize(1<<n);
	u.resize(1<<n);
	for(int i=0; i<(1<<n); ++i){
		int t = 0;
		for(int j=0; j<n; ++j){
			if((i>>j) & 1) ++t;
			else u[i].push_back(j);
		}
		w[i] = t;
	}
	func(v, dp, 0, 0);
	cout << (dp[0][0] == 1e9 ? -1 : dp[0][0]) << "\n";
}

