            if (check[i]) continue;
            int j=v[i].second;
            if (((bit&1<<j)&&i%2!=j%2)||!(bit&1<<j)&&i%2==j%2){
                int n=v[i].first,now=i+1;
                while(true){
                    if (now>=N||v[now].first!=n){ok=false; break;}
                    int k=v[now].second;
                    if (((bit&1<<now)&&k%2!=now%2)||!(bit&1<<now)&&k%2==now%2){
                        cnt+=now*2-1;
                        check[now]=true;
                        break;
                    }
                    now+=2;
                }
            }
            if (!ok) break;
            check[i]=true;
        }
