ll mergecount(vector<ll> &a)
{
  int count = 0;
  int n = a.size();
  if (n > 1)
  {
    vector<ll> b(a.begin(), a.begin() + n / 2);
    vector<ll> c(a.begin() + n / 2, a.end());
    count += mergecount(b);
    count += mergecount(c);
    for (int i = 0, j = 0, k = 0; i < n; ++i)
      if (k == c.size())
        a[i] = b[j++];
      else if (j == b.size())
        a[i] = c[k++];
      else if (b[j] <= c[k])
        a[i] = b[j++];
      else
      {
        a[i] = c[k++];
        count += n / 2 - j;
      }
  }
  return count;
}

