    sort(Sen.begin(), Sen.end());
    vpi R(n);
    for (int i = 0; i < (int)Par.size(); ++i) R[2*i] = Par[i];
    for (int i = 0; i < (int)Sen.size(); ++i) R[2*i+1] = Sen[i];
    bool pots = true;
    for (int i = 1; i < n; ++i) {
      if (R[i-1].first > R[i].first) {
        pots = false;
        break;
      }
    }
    if (!pots) continue;
    int resu = 0;
    for (int i = 0; i < n; ++i) {
      int ind = i;
      while (R[ind].second != i) ++ind;
      while (ind != i) {
        ++resu;
        swap(R[ind], R[ind-1]);
        --ind;
      }
    }
    if (res == -1) res = resu;
    res = min(res, resu);
  }
  cout << res << endl;
}

