                        if(p2[j]==p1[i]) {
                            tmp+=abs(j-i);
                            vis[j]=1;
                            pos=j;
                        }
                    }
                    if(pos!=-1) break;
                }
                if(pos==-1) { f=0; break; }
            }
            if(f) ans=min(ans,tmp);
        }
    }
    if(ans>100000) printf("-1\n");
    else printf("%d\n", ans/2);
}

