    int seen[22]; memset(seen, 0, sizeof seen);
    for (int i = 0; i < b.size(); i++) {
        if(!seen[i]) {
            int j = i;
            while (a[j].i != i) {
                j = a[j].i;
                seen[j] = 1;
                nswaps +=1;
            }
        }
    }
    return nswaps;
