using namespace std;

// zero-based numbering
template<class T> struct Fenwick {
    vector<T> bit; int N;
    Fenwick(int n) : N(n) { bit.assign(n+1, 0); }
    // add w to a
    void add(int a, T w) {
        for (int x = ++a; x <= N; x += x & -x) bit[x] += w;
    }
    // sum [0, a)
    T sum(int a) {
        T ret = 0;
        for (int x = a; x > 0; x -= x & -x) ret += bit[x];
        return ret;
    }
    // sum [a, b)
    T sum(int a, int b) { return sum(b) - sum(a); }
};

int n;
vector<int> a, b;

int calc(int bit) {
    vector<array<int, 2>> v;
    vector<int> c(n);
    for (int i = 0; i < n; i++) {
        if (bit & (1 << i)) v.push_back({b[i], i}), c[i] = 1;
        else v.push_back({a[i], i}), c[i] = 0;
    }
    sort(v.begin(), v.end());
    int minop = 0;
    vector<int> op(n, 0), used(n, 0);
    for (int i = 0; i < n; i++) {
        auto x = v[i][1];
        used[x]++;
        for (int j = 0; j < x; j++) {
            if (!used[j]) op[j]++, op[x]++, minop++;
        }
    }
    for (int i = 0; i < n-1; i++) {
        if (v[i][0] != v[i+1][0]) continue;
        auto &x = v[i][1];
        auto &y = v[i+1][1];
        if ((op[x] & 1) != c[x] && (op[y] & 1) != c[y]) {
            op[x]++; op[y]++;
            swap(x, y);
        }
    }
    int sum = 0;
    for (int i = 0; i < n; i++) {
        if ((op[i] & 1) != c[i]) return -1;
        sum += op[i];
    }
    return sum / 2;
}

int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    cin >> n;
    a.resize(n), b.resize(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    for (int i = 0; i < n; i++) cin >> b[i];
    int ans = 1e9;
    for (int bit = 0; bit < (1 << n); bit++) {
        int d = calc(bit);
        if (d >= 0) ans = min(d, ans);
    }
    cout << (ans == 1e9 ? -1 : ans) << "\n";
    return 0;
}

