int dp[18][1 << 18];

int solve(void){
    int n;
    cin >> n;

    vector<int> a(n);
    rep(i, n){
        cin >> a[i];
        --a[i];
    }

    vector<int> b(n);
    rep(i, n){
        cin >> b[i];
        --b[i];
    }

    vector<int> v1(n), v2(n);
    rep(i, n){
        if(i & 1){
            v1[i] = a[i];
            v2[i] = b[i];
        }else{
            v1[i] = b[i];
            v2[i] = a[i];
        }
    }

    fill(dp[0], dp[n], IINF);
    dp[0][0] = 0;
    rep(i, n){
        dp[i][1 << i] = i;
    }

    vector<int> v;
    REP(i, 1, 1 << n){
        v.emplace_back(i);
    }

    auto comp = [&](int i, int j){
        int cnti = 0;
        int cntj = 0;
        rep(k, n){
            cnti += (i >> k & 1);
            cntj += (j >> k & 1);
        }
        return cnti < cntj;
    };

    sort(v.begin(), v.end(), comp);

    for(auto bit : v){
        vector<int> sumi, mada;
        int cnt = 0;
        rep(i, n){
            if(bit >> i & 1){
                sumi.emplace_back(i);
                ++cnt;
            }else{
                mada.emplace_back(i);
            }
        }

        for(auto mae : sumi){
            for(auto tsugi : mada){
                if(cnt & 1){
                    if(v2[mae] > v1[tsugi]){
                        continue;
                    }
                }else{
                    if(v1[mae] > v2[tsugi]){
                        continue;
                    }
                }
                int cost = IINF;
                if(tsugi < cnt){
                    cost = abs((cnt-tsugi)-(sumi.end()-upper_bound(sumi.begin(), sumi.end(), tsugi)));
                }else{
                    cost = (tsugi-cnt)+(sumi.end()-upper_bound(sumi.begin(), sumi.end(), tsugi));
                }
                chmin(dp[tsugi][bit | (1 << tsugi)], dp[mae][bit]+cost);
            }
        }
    }

    int res = IINF;
    rep(i, n){
        chmin(res, dp[i][(1 << n)-1]);
    }

    if(res < IINF){
        return res;
    }

    return -1;
}

