int dp[1 << 18][51];
int main() {
	ios_base::sync_with_stdio(false); cin.tie(NULL); cout.tie(NULL);
	ll n;
	cin >> n;
	vi a(n), b(n);
	for (int i = 0; i < n; i++) cin >> a[i];
	for (int i = 0; i < n; i++) cin >> b[i];
	int m = (1 << n);
	for (int i = 0; i < m; i++)
		for (int j = 0; j <= 50; j++)
			dp[i][j] = INT_MAX;
	dp[0][0] = 0;
	for (int mask = 0; mask < m; mask++) {
		int nextpos = __builtin_popcount(mask);
		for (int last = 0; last <= 50; last++) {
			int taken = 0;
			for (int pos = 0; pos < n; pos++) {
				if (mask & (1 << pos)) {
					taken++;
				}
				else {
					int newmask = (mask | 1 << pos);
					int val;
					if ((pos & 1) == (nextpos & 1))
						val = a[pos];
					else
						val = b[pos];
					if (val >= last && dp[mask][last] != INT_MAX) {
						dp[newmask][val] = min(dp[newmask][val], dp[mask][last] + pos - taken);
					}

				}
			}
		}
	}
	int ans = INT_MAX;
	for (int i = 0; i <= 50; i++)
		ans = min(ans, dp[m - 1][i]);
	cout << ans;
	return 0;
}

