int ans[51][1 << 18];
const int inf = 1e5;

int Solve(int last, int mask, const vector<int>& a, const vector<int>& b) {
  if (mask == 0) return 0;
  int& result = ans[last][mask];
  if (result != -1) return result;
  result = inf;
  vector<int> A, B, ind;
  int parity = 0;
  for (int i = a.size() - 1; i >= 0; --i) if (mask & (1 << i)) {
    A.push_back(parity == 0 ? a[i] : b[i]);
    B.push_back(parity == 1 ? a[i] : b[i]);
    ind.push_back(i);
  } else {
    parity ^= 1;
  }
  reverse(A.begin(), A.end());
  reverse(B.begin(), B.end());
  reverse(ind.begin(), ind.end());
  for (int i = 0; i < A.size(); ++i) {
    int cur = A[i];
    if (i % 2) cur = B[i];
    if (last > cur) continue;
    result = min(result, i + Solve(cur, mask ^ (1 << ind[i]), a, b));
  }
  return result;
}

