int v1[N], v2[N];


int solve1(vector<pair<int, int>>& v1, vector<pair<int, int>>& v2, int n) {
	sort(v1.begin(), v1.end());
	sort(v2.begin(), v2.end());
	vector<pair<int, int>> v(n);
	for (int i = 0; i < n; i += 2) {
		v[i] = v1[i / 2];
	}
	for (int i = 1; i < n; i += 2) {
		v[i] = v2[i / 2];
	}
	for (int i = 0; i + 1 < n; i++) {
		if (v[i].first > v[i + 1].first) {
			return INF;
		}
	}
	int ans = 0;
	for (int i = 0; i < n; i++) {
		for (int j = i + 1; j < n; j++) {
			if (v[i].second > v[j].second) {
				ans++;
			}
		}
	}
	return ans;
}

