				}
				else {
					v2.push_back({ a[i][1], i });
				}
			}
		}
		ans = min(ans, solve1(v1, v2, n));
	}
	if (ans == INF) {
		cout << -1 << endl;
	}
	else {
		cout << ans << endl;
	}

}

