int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(NULL);
  ll N;
  cin >> N;
  vl A(N), B(N);
  vector<pll> C(N);
  vl D(N);
  REP(i, N) cin >> A[i];
  REP(i, N) cin >> B[i];
  ll ans = llINF;
  REP(i, 1 << N) {
    ll po = i;
    REP(j, N) {
      if (po % 2 == 0) {
        C[j] = make_pair(A[j], j);
      } else {
        C[j] = make_pair(B[j], j);
      }
      D[j] = po % 2;
      po /= 2;
    }
    sort(ALL(C));
    bool ok = true;
    ll count = 0;
    REP(j, N) {
      count += abs(C[j].second - j);
      if (abs(C[j].second - j) % 2 != D[C[j].second]) {
        ok = false;
        break;
      }
    }
    if (!ok)
      continue;
    else
      ans = min(ans, count);
  }
  if (ans < llINF)
    cout << (ans / 2) << endl;
  else
    cout << -1 << endl;

  return 0;
}

#include<iostream>
