using namespace std;
int main(){
	int N,A[18],B[18],k[18],k2[18],K[18],m[18],sum,pre,minL=10000;
	bool flag,can;
	cin>>N;
	for(int i=0;i<N;i++)cin>>A[i];
	for(int i=0;i<N;i++)cin>>B[i];
	for(int i=0;i<(1<<N);i++){
		pre=i;sum=0;
		for(int j=0;j<N;j++){
			m[j]=j;
			K[j]=pre%2;sum+=K[j];
			if(pre%2)k[j]=B[j];
			else k[j]=A[j];
			k2[j]=k[j];
			pre/=2;
		}
		if(sum%2)continue;
		sort(k2,k2+N);

		can=true;
		//cout<<k[0]<<k[1]<<k[2]<<endl;
		//cout<<k2[0]<<k2[1]<<k2[2]<<endl;
		//cout<<K[0]<<K[1]<<K[2]<<endl;
		for(int j=0;j<N;j++){
			flag=false;
			for(int l=0;l<N;l++){
				flag |= (k[j]==k2[l] && (l-j+N*2)%2==K[j]);
			}
			can &= flag;
			//cout<<flag;
		}
		//cout<<endl<<endl;
		if(can==false)continue;
		sum=0;
		for(int j=0;j<N-1;j++){
			for(int l=0;l<N-j-1;l++){
				if(k[l]>k[l+1]){
					swap(k[l],k[l+1]);
					swap(K[l],K[l+1]);
					swap(m[l],m[l+1]);
					sum++;
				}
			}
		}
		for(int j=0;j<N-1;j++){
			if((m[j]-j+N*2)%2!=K[j]){
				swap(k[j],k[j+1]);
				swap(K[j],K[j+1]);
				swap(m[j],m[j+1]);
				sum++;
			}
		}
		minL=min(minL,sum);
	}
	if(minL==10000)cout<<-1;
	else cout<<minL;
	return 0;
}

