using namespace std;
int n;

vector<int> ina, inb, a, b;

int main(){
    scan(n);
    if(n == 1){
        puts("0");
        return 0;
    }
    a.resize(n);
    b.resize(n);
    for(int i = 0; i < n; i++)
        scan(a[i]);
    for(int i = 0; i < n; i++)
        scan(b[i]);
    ina = a, inb = b;

    int ans = 1e9;
    for(int i = 0; i < (1<<(n-1)); i++){
        a = ina, b = inb;
        for(int j = 0; j < n; j++){
            if(i&(1<<j)){
                swap(a[j], b[j+1]);
                swap(b[j], a[j+1]);
            }
        }
        int cnt = __builtin_popcount(i);
        //try greedy bubble sort for even and odd
        for(int k = 0; k < n+n; k++){
            for(int j = 0; j < n-2; j += 2){
                if(a[j] > a[j+2]){
                    swap(a[j], a[j+2]);
                    cnt += 3;
                }
            }
            for(int j = 1; j < n-2; j += 2){
                if(a[j] > a[j+2]){
                    swap(a[j], a[j+2]);
                    cnt += 3;
                }
            }
        }
        int st = 1;
        for(int j = 0; j < n-1; j++){
            if(a[j] > a[j+1])
                st = 0;
        }
        if(st){
            ans = min(ans, cnt);
        }
    }
    if(ans == 1e9)
        puts("-1");
    else
        print(ans);

    return 0;
}

