using namespace std;

const long long MOD = 1000000007;

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);

	int n;
	cin >> n;
	pii* ab;
	ab = new pii[n];
	rep(i, n) cin >> ab[i].first;
	rep(i, n) cin >> ab[i].second;

	int ans = MOD;

	pii* t;
	t = new pii[n];
	rep(i, 1 << n) {
		rep(j, n) {
			t[j].first = ((1 << j)&i ? ab[j].second : ab[j].first);
			t[j].second = j;
		}

		sort(t, t + n);

		bool flag = false;
		rep(j, n) {
			if (abs(j - t[j].second) & 1) {
				if ((i&(1 << t[j].second)) == 0) {
					if (j == n - 1) {
						flag = true;
						break;
					}
					else if (t[j + 1] == t[j]) swap(t[j].second, t[j + 1].second);
					else {
						flag = true;
						break;
					}
				}
			}
			else {
				if ((i&(1 << t[j].second)) == 1) {
					if (j == n - 1) {
						flag = true;
						break;
					}
					else if (t[j + 1] == t[j]) swap(t[j].second, t[j + 1].second);
					else {
						flag = true;
						break;
					}
				}
			}
		}
		if (flag) continue;

		int sum = 0;
		rep(j, n) {
			REP(k, j, n) {
				if (t[j].second > t[k].second) ++sum;
			}
		}

		ans = min(ans, sum);
	}

	if (ans == MOD) {
		cout << -1 << "\n";
	}
	else {
		cout << ans << "\n";
	}

	return 0;
}

