const int inf=1e9+7;
const ll mod=1e9+7;
const ll big=1e18;
const double PI=2*asin(1);

int N;
int A[20], B[20];
int DP[(1<<20)][20];

int solve(int S, int x) {
  if(DP[S][x]>0) return DP[S][x];
  int tmpnum = 0;
  for(int i=0;i<x;++i) {
    if((S&(1<<i))==0) tmpnum++;
  }
  if(S==0) {
    return DP[S][x] = tmpnum;
  }
  DP[S][x] = inf;
  int num = -1; // Sのうちの最後の値のインデックス
  for(int i=0;i<N;++i) {
    if((S&(1<<i))!=0) num++;
  }
  int tmp1, tmp2;
  for(int i=0;i<N;++i) {
    if((S&(1<<i))==0) continue;
    if((x-(num+1))%2==0) tmp1 = A[x];
    else tmp1 = B[x];
    if((i-num)%2==0) tmp2 = A[i];
    else tmp2 = B[i];
    if(tmp1<tmp2) continue;
    DP[S][x] = min(DP[S][x], solve(S^(1<<i), i)+tmpnum);
  }
  return DP[S][x];
}

int main() {
  cin>>N;
  for(int i=0;i<N;++i) cin>>A[i];
  for(int i=0;i<N;++i) cin>>B[i];
  int ans = inf;
  int S = (1<<N) - 1;
  for(int i=0;i<N;++i) {
    ans = min(ans, solve(S^(1<<i), i));
  }
  if(ans==inf) cout<<-1<<endl;
  else cout<<ans<<endl;
}

