vector<int> normalize(const vector<int> v) {
  const int N = v.size();
  vector<int> res(N);
  vector<pair<int,int> > t(N);
  REP(i, N) t[i] = { v[i], i };
  sort(ALL(t));
  int r = 0;
  REP(i, N) {
    r += (i > 0 && t[i - 1].first != t[i].first);
    res[t[i].second] = r;
  }
  return res;
}

int get(const vector<int>&A, const vector<int>& B, int pos, int c) {
  if ((pos - c) & 1) {
    return B[c];
  }
  return A[c];
}

int main2() {

  REP(i, 1<<MAX_N) REP(j, MAX_N + 2) dp[i][j + 1] = INF;

  int N = nextInt();

  vector<int> v(2 * N);
  REP(i, 2*N) v[i] = nextInt();
  v = normalize(v);

  vector<int> A(N);
  vector<int> B(N);
  REP(i, N) A[i] = v[i] + 1;
  REP(i, N) B[i] = v[N+i] + 1;

  // pv(ALL(A));
  // pv(ALL(B));

  dp[0][0] = 0;
  for (int s = 0; s < (1 << N); s++) {
    for (int l = 0; l <= 2*N; l++) {
      if (dp[s][l] >= INF/2) continue;
      // cout << s << " " << l << " " << dp[s][l] << endl;
      int pos = __builtin_popcount(s);
      REP(c, N) if ((s >> c & 1) == 0) {
        int f = get(A, B, pos, c);
        if (l > f) continue;
        int cost = 0;
        for (int i = c + 1; i < N; i++) if (s >> i & 1) cost++;
        // cout << "cost=" << cost << " , c=" << c  << " l=" << l << " f="<< f << endl;
        int ns = s | (1 << c);
        chmin(dp[ns][f], dp[s][l] + cost);
      }
    }
  }

  int ans = INF;
  REP(i, 2*N) {
    chmin(ans, dp[(1 << N) - 1][i+1]);
  }
  if (ans > INF / 2)
    cout << -1 << endl;
  else
    cout << ans << endl;
  return 0;
}

