const int inf=0x3f3f3f3f;
const int maxn=2e5+5;
pair<int,int>pre[maxn],after[maxn];
int n;
int vis[maxn],a[maxn],b[maxn];
int solve(int s){
	int cnt=0;
	for(int i=0;i<n;i++)vis[i]=0;
	for(int i=0;i<n;i++){
		if((s)&(1<<i)){
			cnt++;
			pre[i]=mkp(b[i],1);
			after[i]=pre[i];
		}
		else {
			pre[i]=mkp(a[i],0);
			after[i]=pre[i];
		}
	}
	if(cnt&1)return inf;
	cnt=0;
	sort(after,after+n);
	//for(int i=0;i<n;i++)cout<<after[i].first<<" "<<after[i].second<<endl;
	for(int i=0;i<n;i++){
		for(int j=0;j<n;j++){
			if(after[j].first==pre[i].first&&(abs(i-j)%2==pre[i].second)&&vis[j]==0)vis[j]=1,cnt++;
		}
	}
//	cout<<cnt<<" "<<n<<endl;
	if(cnt!=n)return inf;
	int ans=0;
	for(int i=0;i<n;i++){
		for(int j=i+1;j<n;j++){
			if(pre[j].first<pre[i].first)ans++;
		}
	}
	return ans;
}
