int ans_cand = 0;
VEC<int> bub_sort_cnt(VEC<int> C, int rev) {
  int N = C.size();
  VEC<int> cnt(N, 0);
  VEC<int> index(N);
  REP(i, 0, N) { index[i] = i; }

  REP(i, 0, N) {
    REP(j, 0, N - i - 1) {
      if (C[j] > C[j + 1]) {
        swap(index[j], index[j+1]);
        swap(C[j], C[j + 1]);
        cnt[index[j]]++;
        cnt[index[j + 1]]++;
        ans_cand++;
      }
    }
  }

  // fix
  REP(i, 0, N - 1) {
    int expect = (rev >> i) & 1;
    int actual = cnt[i] % 2;
    if (expect != actual && C[i] == C[i + 1]) {
      cnt[i]++;
      cnt[i + 1]++;
    }
  }
  return cnt;
}
VEC<bool> gOK;
bool verify(VEC<int> &C, VEC<int> &cnt, int rev) {
  int N = cnt.size();
  VEC<bool> ok(N, 0);
  REP(i, 0, N) {
    int expect = (rev >> i) & 1;
    int actual = cnt[i] % 2;
    ok[i] = (expect == actual);
  }
  gOK = ok;
  REP(i, 0, N) {
    if (!ok[i]) {
      return 0;
    }
  }
  return 1;
}

int main() {
  int N;
  cin >> N;
  VEC<int> A(N), B(N);
  REP(i, 0, N) cin >> A[i];
  REP(i, 0, N) cin >> B[i];
  VEC<int> C(N, 0);
  int mi = INT32_MAX;
  VEC<bool> rev_array(N, 0);
  REP(rev, 0, 1 << N) {
    REP(i, 0, N) {
      rev_array[i] = (rev >> i) & 1;
      if ((rev >> i) & 1) {
        C[i] = B[i];
      } else {
        C[i] = A[i];
      }
    }
    ans_cand = 0;
    auto cnt = bub_sort_cnt(C, rev);
    if (verify(C, cnt, rev)) {
      mi = min(mi, ans_cand);
    }
    // DUMP(rev, C, rev_array, cnt, gOK, mi);
  }
  cout << (mi == INT32_MAX ? -1 : mi) << endl;

  return 0;
}

