void solve()
{
    int n;
    cin >> n;
    akari<int> as(n), bs(n);
    for (int i = 0; i < n; i++)
    {
        cin >> as[i] >> bs[i];
    }
    yukari<int> dp(1 << n, akari<int>(51, 1e9));
    dp[0][0] = 0;
    for (int s = 0; s < 1 << n; s++)
    {
        int popcnt = __builtin_popcount(s);
        for (int i = 0; i < n; i++)
        {
            if (s >> i & 1)
            {
                continue;
            }
            int invcnt = abs(popcnt - i), x = (invcnt & 1) ? bs[i] : as[i];
            int mask = s | 1 << i;
            for (int j = 0; j <= x; j++)
            {
                dp[mask][x] = min(dp[mask][x], dp[s][j] + invcnt);
            }
        }
    }
    int ans = *min_element(dp.back().begin(), dp.back().end());
    if (ans == 1e9)
    {
        ans = -1;
    }
    else
    {
        ans = max(0, ans - 1);
    }
    cout << ans << endl;
}

int main()
{
    solve();
    return 0;
}

