int main() {
    ll n;
    std::cin >> n;
    // vector<ll> a(n),b(n);
    vector<vector<ll>> ab(n,vector<ll>(2,0));

    for (int i = 0; i < n; i++) {
        std::cin >> ab[i][0];
    }
    for (int i = 0; i < n; i++) {
        std::cin >> ab[i][1];
    }

    vector<vector<ll>> dp((1<<n)+1,vector<ll>(100,1e10));

    dp[0][0] = 0;

    for (int i = 1; i < (1<<n); i++) {
        ll cnt = __builtin_popcount(i);
        for (int j = 0; j < n; j++) {
            if(i&(1<<j)){
                // jをc+1番目として追加するとき
                // ab[j][abs(j-cnt)%2]以下なら追加できる
                for (int k = 0; k <= ab[j][abs(j-cnt+1)%2]; k++) {
                    // 移動のコスト
                    dp[i][ab[j][abs(j-cnt+1)%2]] = min(dp[i][ab[j][abs(j-cnt+1)%2]], dp[i&(~(1<<j))][k]+abs(j-cnt));
                }

            }
        }
    }
    ll ans = 1e10;
    for (int i = 0; i <= 50; i++) {
        // std::cout << i<<" "<<dp[(1<<n)-1][i] << std::endl;
        ans = min(ans, dp[(1<<n)-1][i]);
    }
    if(ans==1e10){
        std::cout << -1 << std::endl;
        return 0;
    }
    std::cout << ans/2 << std::endl;
}

