int next_combination(int S){
    int x = S & -S, y = S + x;
    return (((S & ~y) / x) >> 1) | y;
}

int main(){
    int n;
    scanf("%d", &n);
    if(n == 1){
        printf("%d\n", 0);
        return 0;
    }
    int a[n], b[n];
