    rep(i, n) scanf("%d", &b[i]);

    int ans=MAX;
    for(int k=n/2, S=(1<<k)-1; S<1<<n; S=next_combination(S)){
        deque<pii> even, odd;
        rep(i, n){
            int t=(i%2==(S>>i&1) ? a[i] : b[i]);
            if(S>>i&1) odd.emplace_back(t, i);
            else even.emplace_back(t, i);
