// https://codeforces.com/contest/1354/problem/D
struct BIT {
    vector<ll> dat;

    BIT(int n) {
        dat.resize(n + 1);
        for(int i = 0; i < (int)dat.size(); i++)
            dat[i] = 0;
    }

    void init() {
        for(int i = 0; i < (int)dat.size(); i++) {
            dat[i] = 0;
        }
    }

    // a is 1-indexed
    void add(int a, ll x) {
        for(int i = a; i < (int)dat.size(); i += i & -i)
            dat[i] = dat[i] + x;
    }

    // [1,a], a is 1-indexed
    ll sum(int a) {
        ll res = 0;
        for(int i = a; i > 0; i -= i & -i) {
            res = res + dat[i];
        }
        return res;
    }

    // [a,b), a and b are 1-indexed
    ll sum(int a, int b) { return sum(b - 1) - sum(a - 1); }

    // k-th number (k is 1-indexed)
    // lower_bound
    int get(ll k) {
        if(k <= 0)
            return 0;
        int res = 0;
        int N = 1;
        while(N < (int)dat.size())
            N *= 2;
        for(int i = N / 2; i > 0; i /= 2) {
            if(res + i < (int)dat.size() && dat[res + i] < k) {
                k = k - dat[res + i];
                res = res + i;
            }
        }
        return res + 1;
    }
};

int main() {
    int N;
    cin >> N;
    vector<int> A(N), B(N);
    rep(i, N) cin >> A[i];
    rep(i, N) cin >> B[i];
    BIT fenwick(100);
    int res = INF;
    for(int bit = 0; bit < (1 << N); bit++) {
        if(__builtin_popcount(bit) != N / 2)
            continue;
        vector<pii> odd, even;
        rep(i, N) {
            if(bit & (1 << i))
                odd.emplace_back((i % 2 ? A[i] : B[i]), i);
            else
                even.emplace_back((i % 2 ? B[i] : A[i]), i);
        }
        sort(All(odd));
        sort(All(even));
        vector<pii> all;
        for(int i = 0; i < even.size(); i++) {
            all.pb(even[i]);
            if(i < odd.size())
                all.pb(odd[i]);
        }
        bool ok = 1;
        for(int i = 0; i < N - 1; i++) {
            if(all[i].first > all[i + 1].first)
                ok = 0;
        }
        if(ok) {
            vector<int> ids(N);
            rep(i, N) ids[i] = all[i].second + 1;
            fenwick.init();
            int tmp = 0;
            rep(i, N) {
                fenwick.add(ids[i], 1);
                tmp += i + 1 - fenwick.sum(ids[i]);
            }
            res = min(res, tmp);
        }
    }
    cout << (res == INF ? -1 : res) << endl;
    return 0;
}

