int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(NULL);
  ll N;
  cin >> N;
  vl A(N), B(N);
  vvl DP = VVL((1 << 18) + 1, 20, llINF);
  REP(i, N) cin >> A[i];
  REP(i, N) cin >> B[i];
  REP(i, 1 << N) {
    REP(j, N) {
      if (!(i & (1 << j)))
        continue;
      ll cnt = 0;
      ll n = i - (1 << j);
      while (n > 0) {
        cnt += n % 2;
        n /= 2;
      }
      if (cnt == 0) {
        DP[i][j] = 0;
        continue;
      }
      // j番目の数が、k番目に移動した時、
      REP(k, N) {
        if (!((i - (1 << j)) & (1 << k)))
          continue;
        ll mxj = (abs(cnt - j) % 2 == 0) ? A[j] : B[j];
        ll mxk = (abs(cnt - 1 - k) % 2 == 0) ? A[k] : B[k];
        if (mxj < mxk)
          continue;
        ll add = 0;
        FOR(l, j + 1, N) add += (1 & (i >> l));
        DP[i][j] = min(DP[i][j], DP[i - (1 << j)][k] + add);
      }
    }
  }
  ll ans = llINF;
  REP(j, N) ans = min(ans, DP[(1 << N) - 1][j]);
  if (ans == llINF)
    cout << -1 << endl;
  else
    cout << ans << endl;

  return 0;
}

