//空vectorを要素数NのsegTreeとしてzで初期化
template<class T>
void segTree_init(vector<T>& vec, int N, T z) {
	int RN = 1;
	while (RN < N)RN *= 2;
	vec.resize(2 * RN, z);
}

//vecをsegTreeとしてn番目をxに
template<class T>
void segTree_set(vector<T>& vec, int n, T x, function<T(T, T)> f, int k = -1) {
	int RN = (vec.size() + 1) / 2;
	if (k == -1) {
		k = n + RN;
		vec[k] = x;
		segTree_set(vec, n, x, f, k / 2);
	}
	else if (k != 0) {
		vec[k] = f(vec[2 * k], vec[2 * k + 1]);
		segTree_set(vec, n, x, f, k / 2);
	}
}

//vecがsegTreeの時の、n番目の要素
template<class T>
T segTree_at(vector<T>& vec, int n) {
	int RN = (vec.size()) / 2;
	return vec[RN + n];
}

//get [a,b]
template<class T>
T segTree_get(vector<T>& vec, int a, int b, function<T(T, T)> f, T e, int k = 1, int l = 0, int r = -1) {
	if (r == -1)r = vec.size() / 2 - 1;
	if (b < l || r < a)return e;
	else if (a <= l && r <= b)return vec[k];
	else return f(
		segTree_get(vec, a, b, f, e, 2 * k, l, (l + r) / 2),
		segTree_get(vec, a, b, f, e, 2 * k + 1, (l + r) / 2 + 1, r)
	);
}

function<LL(LL, LL)> lambda = [](LL a, LL b) {
	return a + b;
};

int main() {
	std::ios::sync_with_stdio(false);
	std::cin.tie(0);
	LL N;
	cin >> N;
	VLL A(N);
	VLL B(N);
	for (LL n = 0; n < N; n++)cin >> A[n];
	for (LL n = 0; n < N; n++)cin >> B[n];
	LL ans = 1e10;
	for (LL code = 0; code < ((LL)1 << N); code++) {
		vector<pll> V(N);
		for (LL n = 0; n < N; n++) {
			if ((code & (1 << n)) != 0) {
				V[n] = pll(B[n], n);
			}
			else V[n] = pll(A[n], n);
		}
		sort(V.begin(), V.end(), [](pll a, pll b) {
			if (a.first != b.first)return a.first < b.first;
			else return a.second < b.second;
		});
		bool flag = true;
		for (LL n = 0; n < N; n++) {
			LL de;
			if ((code & (1 << V[n].second)) != 0) {
				de = 1;
			}
			else de = 0;
			if ((V[n].second - n - de) % 2 != 0) {
				flag = false;
				break;
			}
		}
		if (flag == false)continue;
		VLL seg;
		segTree_init(seg, N+1,(LL)0);
		LL temp = 0;
		for (LL n = 0; n < N; n++) {
			temp += segTree_get(seg, V[n].second + 1, N, lambda, (LL)0);
			segTree_set(seg, V[n].second, (LL)1, lambda);
		}
		ans = min(ans, temp);
	}
	if (ans == 1e10)cout << -1 << "\n";
	else cout << ans << "\n";
	return 0;
}

