  dp[0][0] = 0;
  rep(i, 1<<n) {
    vector<pair<int, pii>> kouho;
    int cnt = 0;
    rep(j, n) {
      if (!(i>>j & 1)) {
        int cost = j - cnt;
        kouho.push_back({j, {cost, cnt}});
      }
      else cnt++;
    }
    rep(j, 51) {
      if (dp[i][j] == INF) continue;
      for (auto p : kouho) {
        int k = p.fi;
        int cost = p.se.fi;
        int pre_cnt = p.se.se;
        int cnt_flip = cnt - pre_cnt + cost;
        int val = 0;
        if (cnt_flip % 2 == 0) val = a[k];
        else val = b[k];
        if (val < j) continue;
        int mx = val;
        int nx = i + (1<<k);
        dp[nx][mx] = min(dp[nx][mx], dp[i][j] + cost);
      }
    }
  }
  int ans = INF;
  rep(j, 51) {
    ans = min(ans, dp[(1<<n)-1][j]);
  }
  if (ans == INF) cout << -1 << endl;
