int main()
{
    const auto N  = in<int>();
    const auto as = in_v<ll>({N});
    const auto bs = in_v<ll>({N});
    const int M   = 1 << N;
    auto memo     = make_v({N, M, N}, -1);
    auto dp       = mfp([&](auto&& self, const int i, const int mask, const int last) -> int {
        if (i == N) { return 0; }
        if (memo[i][mask][last] != -1) { return memo[i][mask][last]; }
        ll lv = -inf_v<ll>;
        if (i > 0) {
            const int ld = std::abs(last - i + 1);
            lv           = (ld % 2 == 0 ? as : bs)[last];
        }
        int large = popcount(mask);
        int min   = inf_v<int>;
        for (int nl = 0; nl < N; nl++) {
            if (btest(mask, nl)) {
                large--;
                continue;
            }
            const int nd = std::abs(nl - i);
            const ll nv  = (nd % 2 == 0 ? as : bs)[nl];
            if (lv > nv) { continue; }
            const int cnt = large + self(self, i + 1, mask | (1 << nl), nl);
            chmin(min, cnt);
        }
        return memo[i][mask][last] = min;
    });
    const int ans = dp(0, 0, 0);
    outln(ans == inf_v<int> ? -1 : ans);
    return 0;
}

