template <class T>
struct Bit{
	std::vector<T> v;
	int n;
	Bit(int n_): n(n_){ v.assign(n_, 0); }
	// i must be 0 <= i < n
	T sum(int i){
		T s=0;
		while(i>0){ s += v[i]; i -= i & -i; }
		return s;
	}
	// i must be 1 <= i < n
	void add(int i, T x){
		while(i < n){ v[i] += x; i += i & -i; }
	}
};

// v: permutation of (1, ... , n)
int crossing(std::vector<int> &v){
	Bit<int> bit(v.size()+1);
	int count = 0;
	for(int i=0; i<v.size(); i++){
		count += i - bit.sum(v[i]);
		bit.add(v[i], 1);
	}
	return count;
}

int N;
int dfs(vector<int> &p, vector<bool> &used, vector<int> &a, vector<int> &b){
	int ret = 1e9;
	if(p.size()==N) {
		return crossing(p);
	}
	for(int i=0; i<N; i++){
		//debug((int)p.size(), i);
		if(used[i]) continue;
		int val;
		if(i%2 == p.size()%2){
			val = a[i];
		} else {
			val = b[i];
		}

		if(p.size() > 0){
			int last_idx = p[p.size()-1]-1;
			int last_val;
			if(last_idx%2==(p.size()-1)%2){
				last_val = a[last_idx];
			} else {
				last_val = b[last_idx];
			}
			if(val < last_val) continue;
		}

		p.push_back(i+1);
		used[i] = true;
		ret = min(ret, dfs(p, used, a, b));
		p.pop_back();
		used[i] = false;
	}
	return ret;
}

