const int sz = 20;

int dp[1 << sz][sz];
int a[sz], b[sz];

class Solution
{
private:
public:
    Solution() {}
    ~Solution() {}
    void solveCase()
    {
        int n;
        cin >> n;
        for (size_t i = 0; i < n; i++)
            cin >> a[i];
        for (size_t i = 0; i < n; i++)
            cin >> b[i];
        memset(dp, -1, sizeof dp);
        for (size_t i = 0; i < n; i++)
            dp[1 << i][i] = 0;
        for (int mask = 1; mask < (1 << n); mask++)
        {
            int c = __builtin_popcount(mask);
            for (int i = 0; i < n; i++)
            {
                if (!(mask >> i & 1) || dp[mask][i] == -1)
                    continue;
                int w = (i % 2) == (c % 2) ? b[i] : a[i];
                int cost = c;
                for (int j = 0; j < n; j++)
                    if (mask >> j & 1)
                        cost--;
                    else
                    {
                        int v = j % 2 == c % 2 ? a[j] : b[j];
                        if (w <= v)
                        {
                            int vl = dp[mask][i] + cost;
                            if (dp[mask | 1 << j][j] == -1 || dp[mask | 1 << j][j] > vl)
                                dp[mask | 1 << j][j] = vl;
                        }
                    }
            }
        }
        int ret = -1;
        for (int i = 0; i < n; i++)
            if (dp[(1 << n) - 1][i] != -1)
                if (ret == -1 || ret > dp[(1 << n) - 1][i])
                    ret = dp[(1 << n) - 1][i];
        cout << ret << '\n';
    }
};

