                        {
                            int cost = nxt - __builtin_popcount(S & ((1 << nxt) - 1));
                            mmin(DP[nxt][S + (1 << nxt)], DP[j][S] + cost);
                        }
                    }
                }
            }
            if (S == 0) break;
            S = next_combination(S);
        }
    }

