int N, ans = 1e9;
int A[18], B[18];
int DP[int(1e6)][51], Bit[20];

int make_cnt(int num){
  int ans = 0, now = num;
  while (now > 0){
    ans += now % 2; now /= 2;
  }
  return ans;
}

int Solve(int num){
  int cnt = make_cnt(num);

  for (int j = 0; j <= 50; j++){
    if (DP[num][j] == 1e9) continue;

    for (int i = 0; i < N; i++){
      int judge = Bit[i] & num;
      if (judge > 0) continue;

      int order = 0;
      for (int k = 0; k < i; k++){
        judge = num & Bit[k];
        if (judge == 0) order++;
      }

      int next = num | Bit[i];
      if ((cnt-i) % 2 == 0 && j <= A[i]){
        DP[next][A[i]] = min(DP[next][A[i]], DP[num][j] + order);
      }else if ((cnt-i) % 2 != 0 && j <= B[i]){
        DP[next][B[i]] = min(DP[next][B[i]], DP[num][j] + order);
      }
    }
  }

  return 0;
}


int main(){
  cin >> N;
  for (int i = 0; i < N; i++) cin >> A[i];
  for (int i = 0; i < N; i++) cin >> B[i];
  Bit[0] = 1;
  for (int i = 1; i <= N; i++) Bit[i] = Bit[i-1] * 2;

  fill((int*)DP, (int*)(DP+Bit[N]+1), 1e9);
  DP[0][0] = 0;

  for (int i = 0; i < Bit[N]; i++) Solve(i);

  for (int i = 0; i <= 50; i++){
    ans = min(ans, DP[Bit[N] - 1][i]);
  }
  if (ans == 1e9) ans = -1;
  cout << ans << endl;

  return 0;
}

