int bubblesort(int n){
  int cc,dd,ee,ff,g=0;
  for(int i = 0; i < n;i++){
    e[i] = 0;
    f[i] = c[i];
  }
  for(int i = 0; i < n;i++){
    for(int j = n-1; j>i;j--){
      if(f[j] < f[j-1]){
        cc = e[j-1]+1;
        dd = e[j]+1;
        ee = f[j-1];
        ff = f[j];
        e[j-1] = dd;
        e[j] = cc;
        f[j-1] = ff;
        f[j] = ee;
      }
    }
  }
  for(int i = 0; i < n; i++){
    g += e[i];
    if(e[i]%2 != d[i]) return -1;
  }
  return g/2;
}

int search(int i,int n){
  if(i >= n){
    int x = bubblesort(n);
    return x;
  }
  else{
    c[i] = a[i];
    d[i] = 0;
    int e = search(i+1,n);
    c[i] = b[i];
    d[i] = 1;
    int f = search(i+1,n);
    if(e == -1){
      return f;
    }
    if(f == -1){
      return e;
    }
    return min(e,f);
  }
}




