  rep(i, N) cin >> A[i];
  rep(i, N) cin >> B[i];
  rep(i, 1<<20)rep(j, 55) dp[i][j] = INFL;


  rep(i, 1<<N)rep(j, N){
    ll cnt = 0;
    for(ll k = j + 1; k < N; k++){
      if(((i>>k) & 1) == 0) continue;
      add[i][j]++;
    }
  }
  dp[0][0] = 0;
  rep(j, 1<<N)rep(i, N)rep(k, 55){
    ll cnt = cnt_bit(j);
    if((j>>i)&1) continue;
    ll nj = j + (1<<i);
    if((cnt % 2 == 1 && i % 2 == 1) || (cnt % 2 == 0 && i % 2 == 0)){
