      if(k > B[i]) continue;
      dp[nj][B[i]] = min(dp[nj][B[i]], dp[j][k] + add[j][i]);
    }
  }
  ll ans = INFL;
  rep(i, 55) ans = min(ans, dp[(1<<N)-1][i]);
  if(ans == INFL) ans = -1;
  cout << ans << endl;
}


