    for(int i = 0; i < n; ++i)
        scanf("%d", &a[i]);
    for(int i = 0; i < n; ++i)
        scanf("%d", &b[i]);
    a[n] = b[n] = 0;
    dp[0][n] = 0;
    int full = (1 << n) - 1;
    for(int S = 0; S < full; ++S) {
        int pp = __builtin_popcount(S), ptr1 = 0, ptr2 = pp;
        static int idx[MAXN];
        for(int i = 0; i < n; ++i) {
            if(S >> i & 1) idx[i] = ptr1++;
            else idx[i] = ptr2++;
        }
        for(int i = 0; i <= n; ++i) if(dp[S][i] != INF) {
            int las = ((pp & 1) ^ (i & 1)) ? a[i] : b[i];
            for(int j = 0; j < n; ++j) if(~S >> j & 1) {
                int cur = ((pp & 1) ^ (j & 1)) ? b[j] : a[j];
                if(cur < las) continue;
                umin(dp[S ^ (1 << j)][j], dp[S][i] + idx[j] - pp);
            }
        }
    }
    int ans = *min_element(dp[full], dp[full] + n);
