int BIT[MAX], M=60;//Nは要素数
int bitsum(int i) {
	int s = 0;
	while (i > 0) {
		s += BIT[i];
		i = i & (i - 1);
	}
	return s;
}
void bitadd(int i, int x) {
	while (i <= M) {
		BIT[i] += x;
		i += i & -i;
	}
}
void solve() {
	int N;
	cin >> N;
	vector<int>A(N), B(N);
	REP(i, N) {
		cin >> A[i];
	}
	REP(i, N) {
		cin >> B[i];
	}
	int perm[20];
	REP(i, N) {
		if (i < (N + 1) / 2)perm[i] = 0;
		else perm[i] = 1;
	}
	int ans = 1e9;
	do {
		vector<int>v(N);
		vector<int>r, b;
		REP(i, N) {
			int id = perm[i] + i;
			if (id %2 == 0)v[i] = A[i];
			else v[i] = B[i];
			if (perm[i] == 0)b.push_back(v[i]);
			else r.push_back(v[i]);

