		VSORT(b); VSORT(r);
		vector<int>v2;
		REP(i, N) {
			if (i % 2 == 0)v2.push_back(b[i / 2]);
			else v2.push_back(r[i / 2]);
		}
		int res = 0;
		FOR(i, 1, N) {
			if (v2[i] < v2[i - 1])goto END;
		}

		REP(j, 61)BIT[j] = 0;
		REP(j, N) {
			res += j - bitsum(v[j]);
			bitadd(v[j], 1);
		}
		//DEBUG(res);
