        for (int last = 0; last < n; ++last) {
            for (int tp = 0; tp < 2; ++tp) {
                dp[mask][last][tp] = inf;
            }
        }
    }
    for (int i = 0; i < n; ++i) {
        dp[1 << i][i][i % 2] = i;
    }
    for (int mask = 0; mask < max_mask; ++mask) {
        int tot = __builtin_popcount(mask);
        for (int last = 0; last < n; ++last) {
            for (int tp = 0; tp < 2; ++tp) {
