                        upd(mask | (1 << nxt), nxt, (cnt + to_right) % 2, dp[mask][last][tp] + cnt);
                    }
                    to_left += get_bit(mask, nxt);
                }
            }
        }
    }
    int ans = inf;
    for (int last = 0; last < n; ++last) {
        for (int tp = 0; tp < 2; ++tp) {
            ans = min(ans, dp[(1 << n) - 1][last][tp]);
        }
    }
    if (ans == inf) {
