		}
		Cards(const Cards &dst){
			cards=dst.cards;
			count=dst.count;
		}
		Cards swap_(int i,int j){
			if(i<0||j>=cards.size())
				return Cards();
			vector<pair<int,int>> cards_=cards;
			auto tmp=cards_[i];
			swap(tmp.first,tmp.second);
			cards_[i]=cards_[j];
			swap(cards_[i].first,cards_[i].second);
			cards_[j]=tmp;
			return Cards(&cards_,count+1);
		}
		const int size()const{
			return cards.size();
		}
		const pair<int,int> operator[](int i)const{
			return cards[i];
		}
		string str(){
			ostringstream osm;
			REP(i,cards.size())
				osm<<"("<<cards[i].first<<","<<cards[i].second<<")"<<endl;
			return osm.str();
		}
};

