    rep(i, pe.size()) {
        tmp.push_back(pe[i]);
        if (po.size() > i) tmp.push_back(po[i]);
    }
    rep(i, tmp.size() - 1) {
        assert(tmp[i] <= tmp[i + 1]);
    }
    int ans = 0;
    rep(i, tmp.size())ans += max<int>(i - tmp[i].second, 0);
    return ans;
}


