using namespace __gnu_pbds;
using namespace std;

typedef long long ll;
typedef pair<int,int> ii;
typedef tree<ii,null_type,less<ii>,rb_tree_tag,tree_order_statistics_node_update> indexed_set;

int eval(priority_queue<ii> &odd, priority_queue<ii> &even) {
	vector<int> a,b;
	while(!odd.empty()) {
		ii cur=odd.top(); odd.pop();
		a.push_back(-cur.first);
		b.push_back(-cur.second);
		swap(odd,even);
	}
	int N=a.size();
	for (int i=0; i<N-1; i++)
		if(a[i]>a[i+1])
			return -1;
	int ret=0;
	for (int i=0; i<N; i++) {
		int idx=-1;
		for (int j=i; j<N; j++)
			if(b[j]==i) {
				idx=j; break;
			}
		for (int t=idx; t>=i+1; t--)
			swap(b[t],b[t-1]), ret++;
	}
	return ret;
}

int main() {
	cin.tie(0); cout.tie(0); ios_base::sync_with_stdio(0);
	int N; cin>>N;
	vector<ii> V(N);
	for (int i=0; i<N; i++)
		cin>>V[i].first;
	for (int i=0; i<N; i++)
		cin>>V[i].second;
	int O=(N+1)/2;
	int ret=-1;
	for (int i=0; i<(1<<N); i++) {
		if(__builtin_popcount(i)!=O)
			continue;
		priority_queue<ii> odd, even;
		for (int j=0; j<N; j++) {
			ii top={-V[j].first,-j};
			ii bot={-V[j].second,-j};
			if(i&(1<<j)) {
				j%2 ? odd.push(bot) : odd.push(top);
			}
			else {
				j%2 ? even.push(top) : even.push(bot);
			}
		}
		int cur=eval(odd,even);
		if(cur==-1)
			continue;
		if(ret==-1) ret=cur;
		else ret=min(ret,cur);
	}
	cout<<ret<<endl;
	return 0;
}

