using namespace std;
struct C{
  long x;
  long id;
  C(long x_,long id_):x(x_),id(id_){}
  C(){}
};
bool cmp(C c1,C c2){
  if(c1.x==c2.x)return c1.id<c2.id;
  return c1.x<c2.x;
}
int main(){
  long N;cin>>N;long ans=-1;
  vector<long>A(N),B(N);
  for(long i=0;i<N;i++)cin>>A[i];
  for(long i=0;i<N;i++)cin>>B[i];
  for(long bit=0;bit<(1<<N);bit++){
    bitset<18>b(bit);
    if((N-b.count())%2!=0)continue;
    vector<C>even;
    vector<C>odd;
    for(long i=0;i<N;i++){
      if((i+b.test(i))%2)even.push_back(C((b.test(i)?A[i]:B[i]),i));
      else odd.push_back(C((b.test(i)?A[i]:B[i]),i));
    }
    if(even.size()-odd.size()!=N%2)continue;
    sort(even.begin(),even.end(),cmp);
    sort(odd.begin(),odd.end(),cmp);
    vector<C>X(N);
    for(long i=0;i<N;i++)
      X[i]=(i%2==0?even[i/2]:odd[i/2]);
    bool ok=1;
    for(long i=0;i<N-1;i++)if(X[i].x>X[i+1].x)ok=0;
    if(!ok)continue;
    //コストの計算
    long s=0;
    for(long i=0;i<N;i++)s+=abs(X[i].id-i);
    s/=2;
    ans=(ans==-1?s:min(ans,s));

  }
  cout<<ans;
}

