            if(xs[i&1][pos] <= cur){
                cur = xs[i&1][pos];
                p[i&1] = pos - 1;
                bound[i] = cur;
                break;
            }
        }
    }

    priority_queue<tuple<int, int, string>> q;
    q.push({0, 0, s});
    while(!q.empty()){
        int nx, cnt;
        string st;
        tie(cnt, nx, st) = q.top();
        q.pop();
        if(nx == n){ cout << -cnt << endl; return 0; }
        for(int i=nx;i<n;++i){
            if((nx==0 || st[nx-1] <= st[i+18*((i-nx)&1)]) && st[i+18*((i-nx)&1)] <= bound[i]){
                string t{st};
                t[nx] = st[i+18*((i-nx)&1)];
                t[nx+18] = st[i+18*((i-nx+1)&1)];
                for(int p=nx+1;p<=i;++p){
                    t[p] = st[p-1+18];
                    t[p+18] = st[p-1];
                }
                q.emplace(cnt - (i-nx), nx+1, t);
            }
        }
    }
    cout << -1 << endl;
    return 0;
}

