int ans_cand = 0;
VEC<int> bub_sort_cnt(VEC<int> C, int rev) {
  int N = C.size();
  VEC<int> cnt(N, 0);
  VEC<int> index(N);
  REP(i, 0, N) { index[i] = i; }

  REP(i, 0, N) {
    REP(j, 0, N - i - 1) {
      if (C[j] > C[j + 1]) {
        swap(index[j], index[j + 1]);
        swap(C[j], C[j + 1]);
        cnt[index[j]]++;
        cnt[index[j + 1]]++;
        ans_cand++;
      }
    }
  }

  // DUMP("  ", C, cnt);
  // fix
  REP(i, 0, N - 1) {
    int expect = (rev >> i) & 1;
    int actual = cnt[i] % 2;
    if (expect != actual && C[i] == C[i + 1]) {
      cnt[index[i]]++;
      cnt[index[i + 1]]++;
    }
  }
  return cnt;
}
VEC<bool> gOK;
bool verify(VEC<int> &C, VEC<int> &cnt, int rev) {
  int N = cnt.size();
  VEC<bool> ok(N, 0);
  REP(i, 0, N) {
    int expect = (rev >> i) & 1;
    int actual = cnt[i] % 2;
    ok[i] = (expect == actual);
  }
  gOK = ok;
  REP(i, 0, N) {
    if (!ok[i]) {
      return 0;
    }
  }
  return 1;
}

