    REP(i, 0, N) {
      rev_array[i] = (rev >> i) & 1;
      if ((rev >> i) & 1) {
        C[i] = B[i];
      } else {
        C[i] = A[i];
      }
    }
    ans_cand = 0;
    auto cnt = bub_sort_cnt(C, rev);
    if (verify(C, cnt, rev)) {
      mi = min(mi, ans_cand);
    }
    // DUMP(rev, C, rev_array, cnt, gOK, mi);
  }
