#include <bits/stdc++.h>
using namespace std;
using lint = long long int;
#define bit(n) (1LL<<(n))

int main() {
    lint n;
    cin >> n;

    vector<lint> a(n);
    for(auto& elem : a)  cin >> elem;

    vector<lint> b(n);
    for(auto& elem : b)  cin >> elem;

    auto next_combination = [](lint sub) {
        lint x = sub & -sub;
        lint y = sub + x;
        return (((sub & ~y) / x) >> 1) | y;
    };

    // 1. 偶数番目(0, 2, ...)に使うカードで全探索
    lint k = (n+1)/2;
    lint ans = 1e18;
    for(lint mask = bit(k)-1; mask < bit(n); mask = next_combination(mask)) {
        bitset<30> bs(mask);
        vector<lint> seq;
        vector<lint> odd, even;
        for(lint i=0; i<n; i++) {
            if(bs.test(i)) {
                seq.push_back(i%2 ? b[i] : a[i]);
                even.push_back(i%2 ? b[i] : a[i]);
            } else {
                seq.push_back(i%2 ? a[i] : b[i]);
                odd.push_back(i%2 ? a[i] : b[i]);
            }
        }

        // 2. バブルソートのswap回数
        lint counter = 0;
        for(lint i=0; i<n; i++)
        for(lint j=i+1; j<n; j++) {
            if(seq[i] > seq[j])  counter++;
        }

        // 3. ソートした結果が条件を満たしているか
        bool ok = true;
        sort(even.begin(), even.end());
        sort(odd.begin(), odd.end());
        sort(seq.begin(), seq.end());
        for(lint i=0; i<n; i++) {
            if(i%2) {
                ok &= odd[(i-1)/2] == seq[i];
            } else {
                ok &= even[i/2] == seq[i];
            }
        }

        if(ok)  ans = min(ans, counter);
    }

    cout << (ans == 1e18 ? -1 : ans) << endl;
}

