const int N = 23;
int n;
pair<int, int> cards[N];

struct card {
    int val, i, odd;

    card(int _v, int _i, int _o) {
        val = _v;
        i = _i;
        odd = _o;
    }

    bool operator<(const card& other) const {
        if(val != other.val)
            return val < other.val;
        return i < other.i;
    }

    void print() {
        cerr << val << ' ' << i << ' ' << odd << "  ";
    }
};

int32_t main() {

    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    cin >> n;
    for(int i = 0; i < n; ++i) {
        cin >> cards[i].first;
    }
    for(int i = 0; i < n; ++i) {
        cin >> cards[i].second;
    }

    int ans = -1;
    for(int mask = 0; mask < (1<<n); ++mask) {
        if(__builtin_popcount(mask)%2) continue;

        vector<card> v;
        for(int i = 0; i < n; ++i) {
            if(mask & (1 << i)) {
                v.emplace_back(cards[i].second, i, (i+1)%2);
            } else {
                v.emplace_back(cards[i].first, i, i%2);
            }
        }

        sort(v.begin(), v.end());

        int i = 0, cand = 0;
        while(i < n) {
            int j = i;
            int ct[2] = {0, 0};
            int cti[2] = {0, 0};
            while(j < n && v[i].val == v[j].val) {
                ct[v[j].odd % 2]++;
                cti[j%2]++;
                j++;
            }

            if(ct[0] != cti[0] || ct[1] != cti[1]) {
                break;
            }

            int onxt = i, enxt = i;
            if(i%2) enxt++; else onxt++;
            for(int k = i; k < j; ++k) {
                if(v[k].odd) {
                    cand += abs(v[k].i - onxt);
                    onxt += 2;
                } else {
                    cand += abs(v[k].i - enxt);
                    enxt += 2;
                }
            }

            i = j;
        }

        if(i == n && (ans == -1 || cand < ans)) {
            ans = cand;
        }
    }

    if(ans != -1) {
        ans /= 2;
    }
    cout << ans << endl;

    return 0;
}

