int gi() {
	char cc = getchar() ; int cn = 0, flus = 1 ;
	while( cc < '0' || cc > '9' ) {  if( cc == '-' ) flus = - flus ; cc = getchar() ; }
	while( cc >= '0' && cc <= '9' )  cn = cn * 10 + cc - '0', cc = getchar() ;
	return cn * flus ;
}
const int N = 50 ; 
const int inf = 123456789 ;
int n, a[N], b[N], col[N], w[N], Ans, st0[N], top0, st1[N], us0[N], us1[N], t0, t1, top1 ; 
struct node {
	int id, w ; 
} s[N] ;
bool cmp( node x, node y ) {
	return x.w < y.w ; 
}
void check() {
	rep( i, 1, n ) w[i] = ( col[i] == 0 ) ? a[i] : b[i] ;
	rep( i, 1, n ) s[i].id = i, s[i].w = w[i] ;
	sort( s + 1, s + n + 1, cmp ) ; t0 = t1 = top0 = top1 = 0 ;
	int bef = 1, S0 = 0, S1 = 0, ans = 0 ;
	rep( i, 1, n ) {
		if( i & 1 ) st1[++ top1] = i ;
		else st0[++ top0] = i ; 
		if( s[i].w == s[i + 1].w ) continue ;
		rep( j, bef, i ) {
			if( col[j] ) {
				if( s[j].id & 1 ) us0[++ t0] = s[j].id ;
				else us1[++ t1] = s[j].id ;
			}
			else {
				if( s[j].id & 1 ) us1[++ t1] = s[j].id ;
				else us0[++ t0] = s[j].id ;
			}
		}
		sort( us1 + 1, us1 + t1 + 1 ), sort( us0 + 1, us0 + t0 + 1 ) ;
		if( t0 != top0 || t1 != top1 ) return ;
		for( re int j = 1; j <= t1; ++ j ) ans += abs(us1[j] - st1[j]) ;
		for( re int j = 1; j <= t0; ++ j ) ans += abs(us0[j] - st0[j]) ;
		t0 = t1 = top0 = top1 = 0, bef = i + 1 ; 
	}
	Ans = min( Ans, ans ) ; 
} 
void dfs( int x ) {
	if( x == n + 1 ) {
		check() ; return ; 
	}
	col[x] = 0, dfs( x + 1 ),
	col[x] = 1, dfs( x + 1 ) ;
}
