inline void chkmin(int& x, int y) {
    if (x == -1 || (y != -1 && y < x)) {
        x = y;
    }
}

inline int get(int x, int y) {
    return (x - y) & 1 ? b[x] : a[x];
}

inline void work() {
    cin >> n;
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }
    for (int i = 0; i < n; ++i) {
        cin >> b[i];
    }

    vector<vector<int>> f(1 << n, vector<int>(n, -1));
    for (int i = 0; i < (1 << n); ++i) {
        int c = __builtin_popcount(i);
        if (c == 1) {
            f[i][__builtin_ctz(i)] = 0;
        }
        else {
            int mov = c;
            for (int j = 0; j < n; ++j) {
                if (i & (1 << j)) {
                    --mov;
                    for (int k = 0; k < n; ++k) {
                        if ((i & (1 << k)) && j != k && f[i ^ (1 << j)][k] != -1) {
                            if (get(j, c - 1) >= get(k, c - 2)) {
                                chkmin(f[i][j], f[i ^ (1 << j)][k] + mov);
                            }
                        }
                    }
                }
            }
        }
    }

    int ans = -1;
    for (int i = 0; i < n; ++i) {
        chkmin(ans, f[(1 << n) - 1][i]);
    }
    cout << ans << "\n";
}

int main() {
    // freopen("input.txt", "r", stdin);
    quickread();
    work();
    return 0;
}

