int main(int argc, char* argv[]){
  init_io(argc, argv);

  int N;
  cin >> N;
  VI xs_(N), ys_(N);
  cin >> xs_ >> ys_;

  auto swapv = [](VI& a, VI& b, int i){
    swap(a[i], b[i+1]);
    swap(a[i+1], b[i]);
  };

  const int INF = 1e9;
  int ans = INF;
  int n2 = N / 2 + N % 2;
  REP(b,1<<N){
    if(__builtin_popcount(b) != n2) continue;
    VI as = xs_, bs = ys_;
    vector<PII> keys;
    REP(i,N) {
      if(b>>i&1){
        keys.EB(i % 2 == 0 ? as[i] : bs[i], i);
      }
    }
    SORT(keys);
    VI tos(N, -1);
    REP(i,n2){
      tos[keys[i].SS] = i * 2;
    }

    // DEBUG(keys, tos);

    int op = 0;
    for(int i=0;i<N;++i){
      if(tos[i] == i) continue;
      if(tos[i] != -1 && tos[i] < i){
        int j = i;
        int dst = tos[i];
        while(dst < j){
          swapv(as, bs, j-1);
          swap(tos[j-1], tos[j]);
          --j;
          ++op;
        }
      }
      else if(tos[i] != -1 && i % 2 == 1){
        int j = i + 1;
        while(j < N && tos[j] != -1){
          ++j;
        }
        if(j == N){
          DEBUG("NG");
        }
        else{
          --j;
          while(j >= i){
            swapv(as, bs, j);
            swap(tos[j], tos[j+1]);
            ++op;
            --j;
          }
        }
      }
      else{
        FOR(j,i+1,N){
          if(tos[j] == i){
            while(i < j){
              swapv(as, bs, j-1);
              swap(tos[j-1], tos[j]);
              --j;
              ++op;
            }
            break;
          }
        }
      }
    }

    // DEBUG(op);
    // DEBUG(as);
    // DEBUG(bs);

    int e = N - 1 - (N % 2);
    for(int i=1;i+2<N;i+=2){
      for(int j=e-2;j>=i;j-=2){
        if(as[j] > as[j+2]){
          swap(as[j], as[j+2]);
          op += 1;
        }
      }
    }

    bool ok = true;
    REP(i,N-1) ok &= as[i] <= as[i+1];

    // DEBUG(ok);

    if(ok) mini(ans, op);
  }

  cout << (ans == INF ? -1 : ans) << endl;

  return 0;
}

