int F(int i,int j,int ok)
{
    if(f[i][j][ok]!=-1) return f[i][j][ok];
    else if(i==(1<<n)-1) return 0;
    else
    {
        int res=1e9,sl=0;
        for(int id=1;id<=n;id++)
        {
            if(((i>>(id-1))&1)==1) sl++;
        }
        //cout<<i<<" "<<j<<" "<<ok<<" "<<sl<<'\n';
        sl++;
        int cnt=0;
        for(int id=1;id<=n;id++)
        {
            if(((i>>(id-1))&1)==0)
            {
                //cout<<id<<'\n';
                int okms=abs(id-sl)%2;
                //cout<<id<<" "<<okms<<" "<<abs(id-sl)<<'\n';
                if(a[id][okms]>=a[j][ok]) res=min(res,F(i+(1<<(id-1)),id,okms)+id-1-cnt);
            }
            else cnt++;
        }
        f[i][j][ok]=res;
        return res;
    }
}

