using namespace std;

const int N = 1 << 18;
const int INF = 1e6;

int n;
int a[N + 5], b[N + 5];
int dp[N + 5][51];
int val[N + 5];

int f(int id, int mask){
	int ret = 0;
	for(int i=0; i<id; i++){
		if((1 << i) & mask) continue;
		ret++;
	}
	return ret;
}

int solve(int mask, int last, int vlast){
	if(mask == (1 << n) - 1) return 0;
	int& ret = dp[mask][vlast];
	if(ret != -1) return ret;
	ret = INF;
	for(int i=0; i<n; i++){
		if(mask & (1 << i)) continue;
		int v = abs(val[mask] - i) % 2 == 0 ? a[i] : b[i];
		if(vlast > v) continue;
		ret = min(ret, solve(mask | (1 << i), i, v) + f(i,mask));
	}
	return ret;
}

int main(){
	ios_base :: sync_with_stdio(0); cin.tie(0); cout.tie(0);
	for(int i=0; i<N; i++){
		int cnt = 0;
		for(int j=0; j<18; j++) if(i & (1 << j)) cnt++;
		val[i] = cnt;
	}
	cin >> n;
	for(int i=0; i<n; i++) cin >> a[i];
	for(int i=0; i<n; i++) cin >> b[i];
	memset(dp,-1,sizeof dp);
	int ans = INF;
	for(int i=0; i<n; i++){
		ans = min(ans, solve(1 << i, i, (i % 2 == 0) ? a[i] : b[i]) + i);
	}
	if(ans >= 1000) ans = -1;
	cout << ans << endl;
	return 0;
}

#include <bits/stdc++.h>
using namespace std;
#define inf (int)(1e9)

template<class Iterator, class Compare>
int inversion_number(Iterator l, Iterator r, Compare comp){
	if(r - l <= 1) return 0;
	Iterator i, j, k, h = l + (r - l) / 2;
	int ans = inversion_number(l, h, comp) + inversion_number(h, r, comp);
	auto x = *l;
	vector<decltype(x)> tmp(l, r);
	for(i = l, j = l, k = h; i < r; i++){
		if(k == r || (j < h && !comp(tmp[k - l], tmp[j - l]))){
			*i = tmp[j - l];
			j++;
		}
		else{
			*i = tmp[k - l];
			ans += k - i;
			k++;
		}
	}
	return ans;
}

int main(){
	int N, i, j, k, S;
	scanf("%d", &N);
	vector<int> A(N), B(N);
	for(i = 0; i < N; i++){
		scanf("%d", &A[i]);
	}
	for(i = 0; i < N; i++){
		scanf("%d", &B[i]);
	}
	int ans = inf;
	for(S = 0; S < (1 << N); S++){
		vector<pair<int, int>> V_eo(N);
		for(i = 0; i < N; i++){
			if((S | (1 << i)) == S){
				V_eo[i].first = B[i];
				V_eo[i].second = (i + 1) % 2;
			}
			else{
				V_eo[i].first = A[i];
				V_eo[i].second = i % 2;
			}
		}
		int f = 1;
		int now = inversion_number(V_eo.begin(), V_eo.end(), [](auto a, auto b){return a.first < b.first;});
		for(i = 0; i < N; i = j){
			for(j = i + 1; V_eo[j].first == V_eo[i].first; j++);
			int Ol[2] = {0, 0};
			for(k = i; k < j; k++){
				Ol[V_eo[k].second]++;
			}
			if(i % 2 == 0){
				if(Ol[0] != (j - i + 1) / 2 || Ol[1] != (j - i) / 2){
					f = 0;
					break;
				}
			}
			else{
				if(Ol[0] != (j - i) / 2 || Ol[1] != (j - i + 1) / 2){
					f = 0;
					break;
				}
			}
			vector<int> sub(j - i);
			Ol[0] = 0;
			Ol[1] = 0;
			for(k = i; k < j; k++){
				if(i % 2 == 0){
					sub[k - i] = 2 * Ol[V_eo[k].second] + V_eo[k].second;
				}
				else{
					sub[k - i] = 2 * Ol[V_eo[k].second] + 1 - V_eo[k].second;
				}
				Ol[V_eo[k].second]++;
			}
			now += inversion_number(sub.begin(), sub.end(), [](auto a, auto b){return a < b;});
		}
		if(f == 1){
			ans = min(ans, now);
		}
	}
	if(ans >= inf){
		printf("-1\n");
	}
	else{
		printf("%d\n", ans);
	}
	return 0;
}

