    cin >> n;
    akari<int> as(n), bs(n);
    for (int i = 0; i < n; i++)
    {
        cin >> as[i];
    }
    for (int i = 0; i < n; i++)
    {
        cin >> bs[i];
    }
    yukari<int> dp(1 << n, akari<int>(51, 1e9));
    dp[0][0] = 0;
    for (int s = 0; s < 1 << n; s++)
    {
        int popcnt = __builtin_popcount(s), off = 0;
        for (int i = 0; i < n; i++)
        {
            if (s >> i & 1)
            {
                continue;
