            int x = abs(i - popcnt) & 1 ? bs[i] : as[i];
            int mask = s | 1 << i;
            for (int j = 0; j <= x; j++)
            {
                dp[mask][x] = min(dp[mask][x], dp[s][j] + off);
            }
            off++;
        }
    }
    int ans = *min_element(dp.back().begin(), dp.back().end());
    if (ans == 1e9)
    {
        ans = -1;
    }
    cout << ans << endl;
}

