template<class T> using invec = inseq<vector<T>>;

auto solve() {
  in<int> N;
  invec<int> A(N), B(N);
  int r = 9999999;

  auto sol = [&](auto f, vector<int> A, vector<int> B, int ifs) {
        bool cant = false;
        REP(i, N-1) {
          if (A[i] > A[i+1]) {
            cant = true;
            break;
          }
        }
        if (!cant)
        	return 0;

    if (ifs >= N - 1)
      return 99999999;

  int r = 99999999;
  for(int i = ifs; i < N - 1; i++) {

      if (true) {
        vector<int> Ac = A, Bc = B;

        swap(Ac[i], Bc[i+1]);
        swap(Ac[i+1], Bc[i]);

        r = min(r, f(f, Ac, Bc, i + 1) + 1);
      }

  }
    return r;
  };
  int flag = 1 << (N - 1) - 1;
  auto solr = [&](auto f, vector<int> A, vector<int> B, int ifs) {
        bool cant = false;
        REP(i, N-1) {
          if (A[i] > A[i+1]) {
            cant = true;
            break;
          }
        }
        if (!cant)
        	return 0;

    if (ifs >= flag)
      return 99999999;

  int r = 99999999;
  for(int i = 0; i < N - 1; i++) {

      if (!((ifs >> i) & 1)) {
        vector<int> Ac = A, Bc = B;

        swap(Ac[i], Bc[i+1]);
        swap(Ac[i+1], Bc[i]);

        r = min(r, f(f, Ac, Bc, i | (1 << i)) + 1);
      }

  }
    return r;
  };



  auto res = sol(sol, A, B, 0);

  res = min(res, solr(sol,A,B,0));
  return (res >= 9999999 ? -1 : res);
}

