int check(int *c, int n, int s) {
    map<int, vector<int> > mp;
    for (int i = 0; i < n; i++) mp[c[i]].push_back(i);
    vector<int> perm;
    for (auto &p : mp) {
        int v = p.first;
        vector<int> v0, v1;
        for (int j : p.second) {
            if (((s >> j) & 1) ^ (j & 1)) v1.push_back(j);
            else v0.push_back(j);
        }
        if (perm.size() % 2) swap(v0, v1);
        if (v0.size() != (1 + p.second.size()) / 2) return -1;
        for (int i = 0; i < v0.size(); i++) {
            perm.push_back(v0[i]);
            if (i < v1.size()) perm.push_back(v1[i]);
        }

    }

    int ans = 0;
    for (int i = 0; i < n; i++)
        for (int j = i+1; j < n; j++)
            if (perm[i] > perm[j]) ans++;
    return ans;
}

