    if(s%2) continue;
    vll num(n);
    vvl z = vv(n, 3, 0, ll);
    re(j, n) {
      num[j] = (k[j]?b[j]:a[j]);
      z[j] = vll{num[j], j, 0};
    }
    segtree seg(51, 0), rev(51, 0);
    vll x(n, 0);
    for(int j=0;j<n;j++) {
      ll q = seg.query(num[j]+1, 51);
      tmp += q, x[j]+=q;
      seg.update(1, num[j]);
    }
    for(int j=n-1;j>=0;j--){
      ll q = rev.query(0, num[j]);
      x[j]+=q;
      rev.update(1, num[j]);
    }
    re(j, n) if(k[j]!=x[j]%2) z[j][2] = 1;
    sort(all(z));
    bool flag = true;
    re(j, n){
      if(z[j][2]==0) continue;
      if(z[j][2]&&((j==n-1)||(z[j][0]!=z[j+1][0])||z[j+1][2]==0)) {
        flag = false;
        break;
      }
      tmp += 1;
      z[j][2] = 0, z[j+1][2] = 0;
    }
    if(flag) ans = min(tmp, ans);
  }
