int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n;
    cin >> n;
    vector<int> a(n), b(n);
    REP(i, n) cin >> a[i];
    REP(i, n) cin >> b[i];
    vector<vector<vector<int>>> dp(2, vector<vector<int>>(1 << n, vector<int>(51, inf)));
    dp[0][0][0] = 0;
    FOR(i, 1, n + 1) REP(j, (1 << n)) {
        bitset<18> bi(j);
        FOR(k, 1, 51) dp[!(i % 2)][j][k] = min(dp[!(i % 2)][j][k], dp[!(i % 2)][j][k - 1]);
        if(bi.count() != i) continue;
        REP(k, 51) dp[i % 2][j][k] = inf;
        int c = 0;
        for(int k = n - 1; k >= 0; k--) {
            if(bi[k] == 0) continue;
            bi[k] = 0;
            if(abs(i - 1 - k) % 2 == 0) {
                dp[i % 2][j][a[k]] = min(dp[i % 2][j][a[k]], dp[!(i % 2)][bi.to_ullong()][a[k]] + c);
            } else {
                dp[i % 2][j][b[k]] = min(dp[i % 2][j][b[k]], dp[!(i % 2)][bi.to_ullong()][b[k]] + c);
            }
            bi[k] = 1;
            c++;
        }
    }
    ll ans = inf * inf;
    REP(j, 51) ans = min(ans, (ll)dp[n % 2][(1 << n) - 1][j]);
    if(ans >= 1000000) {
        cout << -1 << endl;
    } else {
        cout << ans << endl;
    }
    return 0;
}

