const int M = 18;
int dp[M][(1<<M)],a[M],b[M],val[M][(1<<M)];
int n;
int getVal(int prv, int mask)
{
	int t = __builtin_popcount(mask);
	t--;
	t = abs(t - prv);
	if(t%2)
		return b[prv];
	else
		return a[prv];
}
int solve(int x,int mask)
{
	if(mask+1 == (1<<n))
		return 0;
	if(dp[x][mask] != -1)
		return dp[x][mask];
	dp[x][mask] = 1e9;
	int z = getVal(x,mask);
	for(int j=0;j<n;j++)
	{
		if((mask&(1<<j))==0)
		{
			int newMask = (mask|(1<<j));
			int y = getVal(j,newMask);
			if(y>=z)
				dp[x][mask] = min(dp[x][mask], val[j][mask]+solve(j,newMask));
		}
	}
	return dp[x][mask];
}
int main()
{
	cin>>n;
	for(int i=0;i<n;i++)
		cin>>a[i];
	for(int i=0;i<n;i++)
		cin>>b[i];
	memset(dp,-1,sizeof(dp));
	int ans = 1e9;
	for(int i=0;i<n;i++)
	{
		for(int mask = 0;mask<(1<<n);mask++)
		{
			if((mask&(1<<i)))
				continue;
			int z = 0;
			for(int j=0;j<n;j++)
			{
				if(j<i)
				{
					if((mask&(1<<j))==0)
						z++;
				}
				if(j>i)
				{
					if((mask&(1<<j)))
						z++;
				}
			}
			val[i][mask] = z;
		}
	}
	for(int i=0;i<n;i++)
	{
		ans = min(ans,i+solve(i,(1<<i)));
	}
	if(ans!=1e9)
		ans/=2;
	if(ans==1e9)
		ans = -1;
	cout<<ans<<"\n";
	return 0;
}

