	if(i==n){
		sort(v2.begin(),v2.end());
		ll a1=0,a2=0,b=0,c=0;
		ll m[51]={0};
		rep(i,0,n){
			if(v2[i].S>=i){
				a1+=v2[i].S-i;
			}else
				a2+=i-v2[i].S;
			if(v[v2[i].S].S.F==v[v2[i].S].S.S){
				c=1;
			}

			else{
				if(v2[i].F==v[v2[i].S].S.F){
					if((((v2[i].S)%2)^(i%2))){
						m[v2[i].F]++;
					}
				}else{
					if((((v2[i].S+1)%2)^(i%2))){
						m[v2[i].F]++;
					}

				}
			}
			if(v2[i].F==v[v2[i].S].S.S){
				b++;
			}

		}
		rep(i,0,51){
			if(m[i]%2)
				return inf;
		}
		if((c||!(b%2))&&a1==a2){
			return a1;
		}
		return inf;
	}
	vpll v3,v4;
	v3=v2;
	v4=v2;
	v3.pb({v[i].S.F,i});
	v4.pb({v[i].S.S,i});
	return min(func(i+1,v3),func(i+1,v4));
}


