struct segtree{
  ll M=1;
  vector<ll> dat;
  segtree(ll N, ll num){
    while(M<N) M*=2;
    for(int i=0;i<M*2-1;i++)  dat.push_back(num);
  }
  void update(ll x, ll k, ll l=0, int r=-1){
    if(r==-1) r = M;
    k+=M-1;
    dat[k] += x;
    while(k>0) k = (k-1)/2, dat[k] += x;
  }
  ll query(ll a, ll b=-1, ll k=0, ll l=0, ll r=-1){
    if(r==-1) r = M;
    if(b==-1) b = M;
    if(r<=a || b<=l) return 0;
    if(a<=l && r<=b) return dat[k];
    ll A = query(a, b, k*2+1, l, (l+r)/2);
    ll B = query(a, b, k*2+2, (l+r)/2, r);
    return A + B;
  }
};
deque<pair<char, ll>> staccum(string st){
  char now = '?';
  deque<pair<char, ll>> ret;
  ll c = 0;
  for(int i=0;i<st.size();i++){
    if(now!=st[i]){
      if(now!='?') ret.push_back(make_pair(now, c));
      now = st[i], c = 1;
    }else c++;
    if(i==st.size()-1) ret.push_back(make_pair(now, c));
  }
  return ret;
}
