int main(int argc, char const *argv[]) {
  ll n;std::cin >> n;
  vll a(n), b(n);
  re(i, n) std::cin >> a[i];
  re(i, n) std::cin >> b[i];
  ll ans = 100000000;
  for(int i=0;i<(1<<n);i++){
    ll s = 0, tmp = 0;
    bitset<18> k(i);
    re(j, n) if(k[j]) s++;
    if(s%2) continue;
    vll num(n);
    vvl z = vv(n, 3, 0, ll);
    re(j, n) {
      num[j] = (k[j]?b[j]:a[j]);
      z[j] = vll{num[j], j, 0};
    }
    segtree seg(51, 0), rev(51, 0);
    vll x(n, 0);
    for(int j=0;j<n;j++) {
      ll q = seg.query(num[j]+1, 51);
      tmp += q, x[j]+=q;
      seg.update(1, num[j]);
    }
    for(int j=n-1;j>=0;j--){
      ll q = rev.query(0, num[j]);
      x[j]+=q;
      rev.update(1, num[j]);
    }
    re(j, n) if(k[j]!=x[j]%2) z[j][2] = 1;
    sort(all(z));
    bool flag = true;
    vector<string> t(51, "");
    re(j, n) t[z[j][0]]+=+z[j][2]+'0';

    re(j, 51){
      if(t[j].size()==0) continue;
      deque<pair<char, ll>> now = staccum(t[j]);
      if(!now.empty()&&now.front().first=='0') now.pop_front();
      if(!now.empty()&&now.back().first=='0') now.pop_back();
      ll W=0, B=0;
      bool T1=true;
      while(!now.empty()){
        pair<char, ll> T = now.front();
        now.pop_front();
        if(T.first=='1'){
          W+=T.second;
          if(T1&&T.second%2) T1 = false;
          else if(!T1&&T.second%2) T1 = true;
        }else{
          if(T1) continue;
          if(T.second%2) flag = false;
          B+=T.second;
        }
      }
      if(!T1) flag = false;
      tmp += (W+B)/2 + B/2;
    }
    if(flag) ans = min(tmp, ans);
  }
  std::cout << (ans==100000000?-1:ans) << '\n';
  return 0;
}

