ll cal(vector<ll> odd, vector<ll> even){
//    cerr <<"=====================" << endl;
    vector<pair< pair<ll,ll>, ll> > odd_card;
    vector<pair< pair<ll,ll>, ll> > even_card;

    rep(i, odd.size()){
        ll idx = odd[i];
        odd_card.pb( card_cardId[idx] );
//        cerr << idx << ":::::::" << card_cardId[idx].first.first << ", " << card_cardId[idx].first.second << endl;
        if((idx % 2) == 1) {
            swap(odd_card[i].first.first, odd_card[i].first.second);
//            cerr << "odd:" << idx << ", swap" ;
        }
//        else{
//            cerr << "odd:" << idx << ", not swap";
//        }
//        cerr << ", choose: " << odd_card[i].first.first << endl;
    }

    rep(i, even.size()){
        ll idx = even[i];
//        cerr << idx << ":::::::" << card_cardId[idx].first.first << ", " << card_cardId[idx].first.second << endl;
        even_card.pb(card_cardId[idx]);
        if((idx % 2) == 0) {
            swap(even_card[i].first.first, even_card[i].first.second);
//            cerr << "even:" << idx << ", swap";
        }
//        else{
//            cerr << "even:" << idx << ", swap" ;
//        }
//        cerr << ", choose: " << even_card[i].first.first << endl;
    }

    sort(all(odd_card), func);
    sort(all(even_card), func);

    vector<ll> num, finalidx;

    rep(i, odd_card.size()){
        num.pb(odd_card[i].first.first);
        finalidx.pb(odd_card[i].second);

        if(i != even_card.size()){
            num.pb(even_card[i].first.first);
            finalidx.pb(even_card[i].second);
        }
    }

    ll ans = 0;

    rep(i, (num.size()-1)){
        if(num[i + 1] < num[i]) return FAILFAIL;
    }

//    cerr << "vvvvvv" << endl;
//    rep(i, num.size()){
//        cerr << num[i] << " ";
//    }
//    cerr << endl;

    rep(i, finalidx.size()){
        ans += abs(finalidx[i] - i);
    }

    return ans / 2;

}


