        int cnt = 0;    // 左から何桁埋めたか
        vector<int> InversionNumber(n, 0);
        for(int i = 0; i < n; ++i){
            if((bit >> i) & 1){
                ++cnt;
                InversionNumber[i] = 1;
            }
        }
        // 転倒数の前計算
        for(int i = n - 1; i > 0; --i){
            InversionNumber[i - 1] += InversionNumber[i];
        }

        for(int i = 0; i < n; ++i){
            if(dp[bit][i] == INF)   continue;

            for(int j = 0; j < n; ++j){
                if((bit >> j) & 1)  continue;

                // 直前と現在の表になっている数を求める
                int pre = (cnt - 1 - i) % 2 == 0 ? a[i] : b[i];
                int cur = (cnt - j) % 2 == 0 ? a[j] : b[j];
                // 広義単調増加になっていなければ continue
                if(pre > cur)   continue;

                dp[bit | (1 << j)][j] = dp[bit][i] + InversionNumber[j];
            }
        }
    }

    int ans = INF;
    for(int i = 0; i < n; ++i)  chmin(ans, dp[(1 << n) - 1][i]);
    if(ans == INF)  ans = -1;
    cout << ans << endl;
}

