        vector<ll> member;
        vector<ll> memberc;
        for (int j = 0; j < n; j++) {
            if(i & (1<<j)){
                member.push_back(ab[j].second);
            }else{
                member.push_back(ab[j].first);
            }
        }

        for (auto e : member) {
            memberc.push_back(e);
        }
        sort(memberc.begin(),memberc.end());

        vector<bool> used(n,false);
        ll dif = 0;

        fenwick_tree f_tree(100);

        // std::cout << bitset<5>(i) << std::endl;
        for (int j = 0; j < n; j++) {
            dif += j - f_tree.sum(member[j]);
            f_tree.add(member[j], 1);
            // std::cout << member[j]<<" "<<dif << std::endl;
            // std::cout << f_tree.sum(member[j]) << std::endl;
        }
        // std::cout << std::endl;
        bool ok = true;
        for (int j = 0; j < n; j++) {
            bool exist = false;
            for (int k = 0; k < n; k++) {
                if(used[k])continue;
                if(member[j] == memberc[k]){
                    if(i & (1<<j)){
                        if( (k-j+1000000)%2==0 ){
                            continue;
                        }
                        used[k] = true;
