int main()
{
    cin.tie(nullptr);
    ios_base::sync_with_stdio(false);
    cout << fixed << setprecision(15);

    int n;
    cin >> n;
    vector <int> num(2 * n);
    vector <int> numcpy(2 * n);
    int          cnt = 0;
    bool         fg  = true;
    ll           min = INF;

    rep(i, n) {
        cin >> num.at(i); // 1～nは赤、n+1～2nは青
        cin >> num.at(i + n);
        numcpy.at(i)     = num.at(i);
        numcpy.at(i + n) = num.at(i + n);
    }


    while (cnt < (2 << n)) {
        bitset <18> card(cnt); // 0なら赤
        rep(i, n - 1) {
            if (card[i] == 1) {
                // swap
                int temp = num.at(i);
                num.at(i)         = num.at(i + 1);
                num.at(i + 1)     = temp;
                temp              = num.at(i + n);
                num.at(i + n)     = num.at(i + n + 1);
                num.at(i + n + 1) = temp;

                // turn
                temp              = num.at(i);
                num.at(i)         = num.at(i + n);
                num.at(i + n)     = temp;
                temp              = num.at(i + 1);
                num.at(i + 1)     = num.at(i + n + 1);
                num.at(i + n + 1) = temp;
            }
        }
        rep(j, n - 1) {
            if (num.at(j) > num.at(j + 1)) {
                fg = false;
            }
        }
        if (fg && min > (int) card.count()) {
            min = card.count();
        }
        fg = true;
        cnt++;
        rep(i, 2 * n) {
            num.at(i) = numcpy.at(i);
        }
    }

    if (min == INF) { cout << -1 << endl; }
    else { cout << min << endl; }

    return 0;
}

