int solve(int n, const vector<int>& a, const vector<int>& b, int m) {
    vector<int> c(n);
    for (int i = 0; i < n; ++i) {
        if ((m >> i) & 1)
            c[i] = b[i];
        else c[i] = a[i];
    }
    vector<int> d(c);
    sort(d.begin(), d.end());
    vector<int> used(n, 0);
    int res = 0;
    for (int i = 0; i < n; ++i) {
        int st = (i + (m >> i)) & 1;
        int ok = 0;
        for (int j = st; j < n; j += 2) {
            if (used[j])
                continue;
            if (c[i] == d[j]) {
                res += abs(i - j);
                ok = 1;
                used[j] = 1;
                break;
            }
        }
        if (ok == 0)
            return -1;
    }
    return res / 2;
}

void solve() {
    int n;
    cin >> n;
    vector<int> a(n), b(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }
    for (int i = 0; i < n; ++i) {
        cin >> b[i];
    }
    int res = -1;
    for (int m = 0; m < (1 << n); ++m) {
        int x = __popcount((unsigned int)m);
        if (x & 1)
            continue;
        int cur = solve(n, a, b, m);
        if (cur == -1)
            continue;
        if (res == -1)
            res = cur;
        else
            res = min(res, cur);        
    }
    cout << res << endl;
}


