template<class T> inline bool chmin(T &a, const T &b) { if (b < a) { a = b; return 1; } return 0; }

int main() {
    int N; cin >> N;
    vector<vector<int>> A(2, vector<int>(N));
    for(int i = 0; i < 2; ++i) {
        for(int j = 0; j < N; ++j) {
            cin >> A[i][j];
        }
    }
    const int INF = 1e9;
    vector<vector<int>> dp((1 << N) + 1, vector<int>(51, INF));
    dp[0][0] = 0;
    for(int mask = 0; mask < (1 << N); ++mask) {
        int last = __builtin_popcount(mask);
        vector<pair<int, int>> id;
        int itr = last;
        for(int i = 0; i < N; ++i) {
            if(!(mask & 1 << i)) {
                id.emplace_back(i, itr++);
            }
        }
        for(int s = 0; s <= 50; ++s) {
            if(dp[mask][s] == INF) continue;
            for(auto &p : id) {
                int i, j; tie(i, j) = p;
                int ns = A[abs(i - last) % 2][i];
                int d = abs(j - last);
                if(ns >= s) {
                    chmin(dp[mask | (1 << i)][ns], dp[mask][s] + d);
                }
            }
        }
    }
    int ans = INF;
    for(int s = 0; s <= 50; ++s) {
        chmin(ans, dp[(1 << N) - 1][s]);
    }
    cout << (ans == INF ? -1 : ans) << '\n';
    return 0;
}

