int popcount32(unsigned int x) {
	x = x - ((x >> 1) & 0x55555555);
	x = (x & 0x33333333) + ((x >> 2) & 0x33333333);
	x = (x + (x >> 4)) & 0x0F0F0F0F;
	x = x + (x >> 8);
	x = x + (x >> 16);
	return x & 0x0000003F;
}

int dp[1 << 18][18];


int main() {
	ios::sync_with_stdio(0);
	cin.tie(0);

	int n;
	int ab[2][18];

	cin >> n;
	rep(i, n)cin >> ab[0][i];
	rep(i, n)cin >> ab[1][i];

	rep(i, 1 << n)rep(j, n)dp[i][j] = INF;
	rep(i,n) {
		dp[1 << i][i] = i;
	}

	rep(i, 1 << n)rep(j, n)if (dp[i][j] != INF) {
		int p = popcount32(i);
		int prev = ab[abs((p - 1) - j) % 2][j];

		rep(k, n) if ((i >> k & 1) == 0) {
			int dif = abs(p - k) % 2;
			if (prev > ab[dif][k])continue;

			dp[i | 1 << k][k] = min(dp[i | 1 << k][k]
				, dp[i][j] + k - popcount32(i & ((1 << k) - 1)));
		}
	}

	int ans = INF;
	rep(i, n)ans = min(ans, dp[(1 << n) - 1][i]);
	if (ans == INF) {
		cout << -1 << endl;
	}
	else {
		cout << ans << endl;
	}



	return 0;
}

