template <class T>
inline void read(T &x) {
    x = 0;
    char ch = getchar(), w = 0;
    while (!isdigit(ch)) w = (ch == '-'), ch = getchar();
    while (isdigit(ch)) x = (x << 1) + (x << 3) + (ch ^ 48), ch = getchar();
    x = w ? -x : x;
    return;
}

int main() {
    read(n);
    for (R int i = 0; i < n; ++i) read(a[i]);
    for (R int i = 0; i < n; ++i) read(b[i]);
    int ans = inf;
    for (R int i = 0; i < 1 << n; ++i) {
        int num = 0;
        for (R int j = 0; j < n; ++j) num ^= (i >> j) & 1;
        if (num) continue;
        tmp.clear();
        for (R int i = 0; i <= 50; ++i) buc[i][0].clear(), buc[i][1].clear();
        for (R int j = 0; j < n; ++j) {
            int w = i & (1 << j) ? b[j] : a[j];
            tmp.push_back(w);
            buc[w][((i >> j) ^ j) & 1].push_back(j);
        }
        sort(tmp.begin(), tmp.end());
        int fl = 1;
        for (R int j = n - 1; fl && ~j; --j) {
            if (!buc[tmp[j]][j & 1].size()) fl = 0;
            else {
                pos[buc[tmp[j]][j & 1].back()] = j;
                buc[tmp[j]][j & 1].pop_back();
            }
