using namespace std;
int n,a[20],b[20],ans=1987654321;
struct st{int x;int k;};
st tem[20],tem2[20];
bool nondec()
{
    for(int i=0;i<n-1;i++)
    {
        if(tem[i].x>tem[i+1].x||tem[i].k+tem[i+1].k)
        {
            return false;
        }
    }
    return true;
}
void swfl(int x)
{
    st ret={tem[x].x,tem[x].k};
    tem[x]={tem[x+1].x,1-tem[x+1].k};
    tem[x+1]={ret.x,1-ret.k};
}
int main()
{
    scanf("%d",&n);
    for(int i=0;i<n;i++)
    {
        scanf("%d",a+i);
    }
    for(int i=0;i<n;i++)
    {
        scanf("%d",b+i);
    }
    for(int i=0;i<(1<<n);i++)
    {
        for(int j=0;j<n;j++)
        {
            if(i&(1<<j))
            {
                tem[j]={b[j],1};
                tem2[j]=tem[j];
            }
            else
            {
                tem[j]={a[j],0};
                tem2[j]=tem[j];
            }
        }
        int cnt=0;
        for(int j=0;j<n-1;j++)
        {
            if(tem[j+1].k)
            {
                swfl(j);
                cnt++;
            }
        }
        if(nondec())
        {
            ans=min(ans,cnt);
        }
        cnt=0;
        for(int j=0;j<n;j++)
        {
            tem[j]=tem2[j];
        }
        for(int j=n-1;j>0;j--)
        {
            if(tem[j].k)
            {
                swfl(j-1);
                cnt++;
            }
        }
        if(nondec())
        {
            ans=min(ans,cnt);
        }
    }
    if(ans==1987654321)
    {
        printf("-1");
        return 0;
    }
    printf("%d",ans);
}

