//感想：2020/01/09時点で全く手が付けられないため，bit DPなるものを学習した後再チャレンジの必要あり．

//dp[i][j] = i:用いるカードの集合？，j:?
int dp[(1 << 19)][51];

void solve(){

	//配列dpを1e9で初期化
	for(int i = 0; i < (1 << 19); i++){
		for(int q = 0; q < 51; q++){
			dp[i][q] = 1e9;
		}
	}

	dp[0][0] = 0;

	//入力を受け取る
	int n; cin >> n;
	vector<pair<int, int>> inputs;
	for(int i = 0; i < n; i++){
		int a; cin >> a;
		inputs.push_back(make_pair(a, 1));
	}
	for(int i = 0; i < n; i++){
		cin >> inputs[i].second;
	}

	//dpのiループ
	for(int i = 0; i < (1 << n)-1; i++){

		//何番目のカードが裏返っているかを格納するための配列？
		int is_B[20] = {};

		//今回のループで用いられているカードの集合？
		int taken[20] = {};

		//右からq番目のカードが用いられていたらインクリメント
		for(int q = 0; q < n; q++){
			if((1 << q) & i){
				is_B[q]++;
				taken[q] = 1;
			}
		}

		//右から数えて偶数番目かどうかを判定
		for(int q = n-2; q >= 0; q--){
			is_B[q] += is_B[q+1];
			is_B[q] %= 2;
		}

		//表裏を判定するための端からの距離を格納
		int dist = 0;

		//次のカードを選択するjループ
		for(int j = 0; j < n; j++){

			//カードが既に用いられていなければ
			if(taken[j] == false){

				//用いているカードの集合に次のカードを追加
				int next_go = i + (1 << j);

				//
				int cost = dist;

				//次のカードが表裏どちらの状態か判定
				int nexe_value = (is_B[j] + dist) % 2;

				//次のカードの値を格納
				if(nexe_value == 0) nexe_value = inputs[j].first;
				else nexe_value = inputs[j].second;

				//dpを更新
				for(int q = 0; q < nexe_value + 1; q++){
					dp[next_go][nexe_value] = min(dp[next_go][nexe_value], dp[i][q] + cost);
				}

				//端からの距離を更新
				dist++;
			}
		}
	}

	//ansを求める
	int ans = 1e9;
	for(int q = 0; q < 51; q++){
		ans = min(ans, dp[(1 << n) - 1][q]);
	}
	if(ans == 1e9) ans = -1;

	//出力
	cout << ans << endl;
}

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	solve();
	return 0;
}

