void fin(T const& t){ std::cout << t << std::endl; exit(0); }

template<typename T>
std::vector<std::vector<T>> mk2d(size_t s1, size_t s2, T const& val) {
  std::vector<T> tmp(s2, val);
  return std::vector<std::vector<T>>(s1, tmp);
}

bool next_choice(std::vector<int>& ixh, int N) {
  int h = ixh.size();
  for(int i = h-1, n = N; i >= 0; --i, --n) {
    if(ixh[i]+1 < n) {
      int v = ixh[i]+1;
      for(int j = i; j < h; ++j) ixh[j] = v++;
      return true;
    }
  }
  return false;
}

int calc(std::vector<int>& ix) {
  int res = 0;
  for(int i = 0; i < ix.size()-1; ++i) {
    if(ix[i] == i) continue;
    for(int j = i+1; j < ix.size(); ++j) if(ix[j]==i) {
      res += j-i;
      for(int k = j; k > i; --k) ix[k]=ix[k-1];
      break;
    }
  }
  return res;
}

int main() {
  std::cin.tie(0); std::ios::sync_with_stdio(false);
  int N; std::cin >> N;
  auto ab = mk2d<int>(2, N, 0);
  for(int i = 0; i < N; ++i) std::cin >> ab[i%2][i];
  for(int i = 0; i < N; ++i) std::cin >> ab[(i+1)%2][i];
  std::vector<int> ix(N), ixh((N+1)/2), ixe((N+1)/2), ixo(N/2);
  std::vector<bool> used(N);
  std::iota(ix.begin(), ix.end(), 0);
  std::iota(ixh.begin(), ixh.end(), 0);

  int ans = 10000;
  // check all possibility; MAX: comb(18,9) < 50000
  for(;;) {
    // prepare even
    std::copy(ixh.begin(), ixh.end(), ixe.begin());
    std::sort(ixe.begin(), ixe.end(), 
      [&](int l, int r){ return ab[0][l] < ab[0][r]; });

    // prepare odd
    std::fill_n(used.begin(), N, false);
    for(int i: ixh) used[i] = true;
    ixo.resize(0);
    for(int i = 0; i < N; ++i) if(!used[i]) ixo.push_back(i);
    std::sort(ixo.begin(), ixo.end(),
      [&](int l, int r){ return ab[1][l] < ab[1][r]; });

    // check if sorted
    bool sorted = true;
    for(int i = 0; i < ixo.size(); ++i) {
      if(ab[0][ixe[i]] > ab[1][ixo[i]]) { sorted = false; break; }
      if(i+1 < ixe.size() &&  ab[1][ixo[i]] > ab[0][ixe[i+1]]) { sorted = false; break; }
    }
    if(sorted) {
      // merge
      for(int i = 0; i < ixe.size(); ++i) ix[i*2] = ixe[i];
      for(int i = 0; i < ixo.size(); ++i) ix[i*2+1] = ixo[i];
      ans = std::min(ans, calc(ix));
    }

    if(!next_choice(ixh, N)) break;
  }
  if(ans > 9999) ans = -1;
  fin(ans);
  return 0;
}

