const int INF = 1e6;
int dp[1<<18][51];
int bit_count[1<<18];

void renum(vector<int> &A, vector<int> &B) {
    vector<int> v = A;
    v.insert(v.end(), B.begin(), B.end());
    sort(v.begin(), v.end());
    v.erase(unique(v.begin(), v.end()), v.end());
    for (int &a: A) a = lower_bound(v.begin(), v.end(), a) - v.begin();
    for (int &b: B) b = lower_bound(v.begin(), v.end(), b) - v.begin();
}

void bit_init() {
    for (int i=0; i<(1<<18); ++i) {
        bit_count[i] = __builtin_popcount(i);
    }
}

int main() {
    bit_init();
    static_fill(dp, INF);

    int N;
    cin >> N;
    vector<int> A(N), B(N);
    for (int i=0; i<N; ++i) cin >> A[i];
    for (int i=0; i<N; ++i) cin >> B[i];
    renum(A, B);

    int M = max(*max_element(A.begin(), A.end()), *max_element(B.begin(), B.end()));

    // 位置iにあるカードを位置jに置くときの表の数字
    auto face = [&](int i, int j){
        return abs(i-j) % 2 ? B[i] : A[i];
    };

    for (int i=0; i<N; ++i) {
        dp[1<<i][face(i, 0)] = 0;
    }
    for (int mask=1; mask<(1<<N); ++mask) {
        for (int i=0; i<=M; ++i) {
            for (int j=0; j<N; ++j) {
                if ((mask >> j) & 1) continue;

                int p = bit_count[mask];
                if (i <= face(j, p)) {
                    int inv = bit_count[mask / (1<<(j+1))];
                    chmin(dp[mask|(1<<j)][face(j, p)], dp[mask][i] + inv);
                }
            }
        }
    }
    int res = INF;
    for (int i=0; i<=M; ++i) {
        res = min(res, dp[(1<<N)-1][i]);
    }
    cout << (res == INF ? -1 : res) << endl;

    return 0;
}

