int dp[1 << 18][51];
int main() {
  ios_base::sync_with_stdio(false); cin.tie(NULL); cout.tie(NULL);
  int n;
  cin >> n;
  int a[n], b[n];
  for (int i = 0; i < n; i++)
    cin >> a[i];
  for (int i = 0; i < n; i++)
    cin >> b[i];
  int m = (1 << n);
  // dp[mask][val] = use all elements in mask s.t. sequence ends in val and no. of swaps is least
  for (int i = 0; i < m; i++)
    for (int j = 0; j <= 50; j++)
      dp[i][j] = INT_MAX;
  dp[0][0] = 0;
  for (int mask = 0; mask < m; mask++) {
    for (int last = 0; last <= 50; last++) {
      // already mask elements are taken and their last element is last.
      int taken = 0;
      for (int pos = 0; pos < n; pos++) {
        if (mask & (1 << pos)) // this pos already taken so can't take it again
          taken++;
        else {
          int newmask = (mask | 1 << pos), nextpos = __builtin_popcount(mask), curr;
          if ((pos & 1) == (nextpos & 1)) // same parity, so when pos will come on nextpos, a will be present in a[nextpos]
            curr = a[pos];
          else
            curr = b[pos];
          if (curr >= last && dp[mask][last] != INT_MAX) // the last state was reachable and curr element is greater than last element of the sequence
            dp[newmask][curr] = min(dp[newmask][curr], dp[mask][last] + pos - taken);
        }
      }
    }
  }
  int ans = INT_MAX;
  for (int i = 0; i <= 50; i++)
    ans = min(ans, dp[m - 1][i]);
  if (ans == INT_MAX)
    ans = -1;
  cout << ans;
  return 0;
}

