using namespace std;

const int INF = 1e9;

int main(){

    int N;
    cin >> N;
    vector<int> A(N), B(N);
    for(int i = 0; i < N; i++){
        cin >> A[i];
    }
    for(int j = 0; j < N; j++){
        cin >> B[j];
    }

    int ans = INF;
    int com = pow(2, N);
    for(int i = 0; i < com; i++){
        int sum = 0;
        vector<pair<int, int>> even;
        vector<pair<int, int>> odd;
        for(int j = 0; j < N; j++){
            if(i & (1 << j)){
                if(j % 2 == 0){
                    odd.push_back(make_pair(B[j], j));
                }
                else{
                    even.push_back(make_pair(B[j], j));
                }
                sum++;
            }
            else{
                if(j % 2 == 0){
                    even.push_back(make_pair(A[j], j));
                }
                else{
                    odd.push_back(make_pair(A[j], j));
                }
            }
        }

        if(sum % 2 == 1){
            continue;
        }

        if((int)even.size() != ceil(N / 2.0) || (int)odd.size() != N / 2){
            continue;
        }

        sort(even.begin(), even.end());
        sort(odd.begin(), odd.end());

        vector<pair<int, int>> v(N);
        for(int j = 0; j < ceil(N / 2.0); j++){
            v[2 * j] = even[j];
        }
        for(int j = 0; j < N / 2; j++){
            v[2 * j + 1] = odd[j];
        }

        bool isOk = true;
        for(int j = 1; j < N; j++){
            if(v[j - 1].first > v[j].first){
                isOk = false;
                break;
            }
        }

        if(!isOk){
            continue;
        }

        int cnt = 0;
        for(int j = 0; j < N; j++){
            for(int k = j + 1; k < N; k++){
                if(v[j].second > v[k].second){
                    cnt++;
                }
            }
        }

        ans = min(ans, cnt);
    }

    if(ans == INF){
        cout << -1 << endl;
    }
    else{
        cout << ans << endl;
    }

    return 0;
}

