constexpr int INF = 1e6;

lint next_combination(lint comb)
{
    lint x = comb & -comb, y = comb + x;
    return ((comb & ~y) / x >> 1) | y;
}


int main()
{
    int N;
    cin >> N;
    vector<int> A(N), B(N);
    cin >> A >> B;
    for (int j = 1; j < N; j += 2) swap(A[j], B[j]);

    A.push_back(0);
    B.push_back(0);

    vector<vector<int>> DP(N + 1, vector<int>(1 << N, INF));
    DP[N][0] = 0;

    REP(n, N)
    {
        int S = (1 << n) - 1;
        while (S < (1 << N))
        {
            REP(j, N + 1)
            {
                if (DP[j][S] < INF)
                {
                    int last = (n % 2 ? A[j] : B[j]);

                    REP(nxt, N)
                    if (!((S >> nxt) & 1))
                    {
                        // dbg(nxt);
                        int nxtv = (n % 2 ? B[nxt] : A[nxt]);
                        // dbg(nxtv);
                        if (nxtv >= last)
                        {
                            mmin(DP[nxt][S + (1 << nxt)], DP[j][S] + abs(nxt - n));
                        }
                    }
                }
            }
            if (S == 0) break;
            S = next_combination(S);
        }
    }
    // dbg(DP);

    int ret = INF;
    REP(i, N) mmin(ret, DP[i].back());
    if (ret == INF) puts("-1");
    else cout << ret / 2 << endl;
}

