class fenwick {
  private:
    int len;
    vector<Z> data;
  public:
    fenwick(int n) {
      len = 1;
      while (len < n) len *= 2;
      len++;
      data.resize(len);
    }
    Z sum(Z to) {
      to++;
      Z total = 0;
      for (Z i = to; i > 0; i -= i & -i) {
        total += ix(data, i);
      }
      return total;
    }
    void add(Z pos, Z x) {
      pos++;
      for (Z i = pos; i < len; i += i & -i) {
        ix(data, i) += x;
      }
    }
};


