        }
        REP(k, K) {
            if (k) chmin(dp[S][k], dp[S][k - 1]);
        }
    }
    dump(dp);
    Int all = (1 << n) - 1;
    cout << (dp[all][K - 1] == INF ? -1 : dp[all][K - 1]) << endl;
}

