int n;
vector <int> a, b;

int go(int mask, int last) {
  if(mask == (1 << n) - 1) return 0;
  if(dp[mask][last] != -1) return dp[mask][last];
  int ans = 1e9 + 10;
  int idx = 0; int cur = __builtin_popcount(mask);
  for(int i = 0; i < n; i++) {
    if((mask >> i) & 1) {
      cur++;
      continue;
    }
    if((cur + idx) & 1) {
      if(b[i] >= last) ans = min(ans, idx + go(mask | (1 << i), b[i]));
    }
    else {
      if(a[i] >= last) ans = min(ans, idx + go(mask | (1 << i), a[i]));
    }
    idx++;
  }
  return dp[mask][last] = ans;
}

