    if (pos == N) { return 0; }
    auto& memo = dp[min][mask.to_ulong()];
    if (memo != -1) { return memo; }
    memo = 100100;
    int pos2 = pos % 2;
    int npos = -1;
    for (int32_t i = 0; i < N; i++)
    {
        if (mask[i]) {
            ++npos;
            if(min <= A[i][pos2]) {
                mask[i] = false;

                memo = std::min(memo, func(pos + 1, A[i][pos2], mask) + npos);
                mask[i] = true;
            }
        }
    }
    return memo;
}

