int ans=INF;
int n;
int a[20][2],p[20],t[20],b[20][2];
void jud(int s){
	int x=0;
	for(int i=0;i<n;++i) if(s&(1<<i)) ++x;
	if(x&1) return;
	for(int i=0;i<n;++i){
		if(s&(1<<i)) p[i]=1;
		else p[i]=0;
		t[i]=a[i][p[i]];
		b[i][0]=a[i][0];
		b[i][1]=a[i][1];
	}
	sort(t,t+n);
	bool flag=0;
	int val=0;
	for(int i=0;i<n;++i){
		int j=i;
		for(;j<n;++j)
			if(b[j][p[j]]==t[i]&&((j-i)^p[j])==0) break;
		if(j>=n) {
			flag=1;
			break;
		}
		for(;j>i;--j){
			swap(b[j][0],b[j-1][1]);
			swap(b[j][1],b[j-1][0]);
			swap(p[j],p[j-1]);
			p[j]^=1;p[j-1]^=1;
			++val;
		}
	}
	if(flag) return;
	ans=min(ans,val);
}
int main(){
	scanf("%d",&n);
	for(int i=0;i<n;++i) scanf("%d",&a[i][0]);
	for(int i=0;i<n;++i) scanf("%d",&a[i][1]);
	for(int s=0;s<(1<<n);++s) jud(s);
	printf("%d\n",ans==INF?-1:ans);
	return 0;
}

