const int MAX = 1e5 + 5;
const int INF = 1001001001;
const int MOD = 1e9 + 7;

int cost(vector<int> & v) {
    int n = v.size();

    rep(i, n) {
        if (i % 2 == v[i] % 2 && 20 <= v[i]) return INF;
        if (i % 2 != v[i] % 2 && v[i] < 20) return INF; 
    }

    int res = 0;
    rep(i, n) {
        for (int j = i + 1; j < n; ++j) {
            int a = v[i], b = v[j];
            if (20 <= a) a-=20;
            if (20 <= b) b-=20;
            if (a > b) res++;
        }
    }
    return res;
}

int N;
vector<int> G[40];
int ans;
void dfs(int n, vector<int> v = vector<int>()) {
    v.push_back(n);

    if (v.size() == N) {
        ans = min(ans, cost(v));
        return;
    }

    for (int next : G[n]) {
        bool used = false;
        for (int i : v) {
            if (next == i || next - 20 == i) {
                used = true;
                break;
            }
        }
        if (!used) dfs(next, v);
    }
}

int main(){
    cin >> N;

    vector<int> A(N), B(N);
    rep(i, N) cin >> A[i];
    rep(i, N) cin >> B[i];

    rep(i, N) {
        rep(j, N) {
            if (i == j) continue;
            if (i % 2 == j % 2) {
                if (A[i] <= B[j]) G[i].push_back(20 + j);
            } else {
                if (A[i] <= A[j]) G[i].push_back(j);
            }
        }
    }

    rep(i, N) {
        rep(j, N) {
            if (i == j) continue;
            if (i % 2 == j % 2) {
                if (B[i] <= A[j]) G[20 + i].push_back(j);
            } else {
                if (B[i] <= B[j]) G[20 + i].push_back(20 + j);
            }
        }
    }

    ans = INF;
    rep(i, N) {
        dfs(i);
    }

    rep(i, N) {
        dfs(20 + i);
    }

    if (ans != INF) cout << ans << endl;
    else cout << -1 << endl;
}

