  do {
    pair<int, int> even[r], odd[N - r];
    int ei = 0, oi = 0;
    for (int i = 0; i < N; i++) {
      if (v[i]) {
        even[ei++] = {A[i], i};
      } else {
        odd[oi++] = {B[i], i};
      }
    }
    sort(even, even + r);
    sort(odd, odd + N - r);
