                tmp++;
                v[j]=make_tuple(b[j],j,1);
            }
        }
        if(tmp%2)continue;
        sort(all(v));
        bool b=1;
        map<lint,vector<lint>>v1;//奇数番
        map<lint,vector<lint>>v2;//奇数番
        map<lint,vector<lint>>v3;//偶数番
        map<lint,vector<lint>>v4;//偶数番
        vector<lint>ans(n);
        rep(j,n){
            if((get<1>(v[j])+get<2>(v[j]))%2){
                v1[get<0>(v[j])].push_back(get<1>(v[j]));
            }else{
                v3[get<0>(v[j])].push_back(get<1>(v[j]));
            }
            if(j%2)v2[get<0>(v[j])].push_back(j);
            else v4[get<0>(v[j])].push_back(j);
        }
        for(auto d:v1){
            if(v1[d.first].size()!=v2[d.first].size()){
                b=0;
