                for(int i=0;i<(int)v1[d.first].size();i++){
                    ans[v2[d.first][i]]=v1[d.first][i];
                }
            }
        }
        for(auto d:v3){
            if(v3[d.first].size()!=v4[d.first].size()){
                b=0;
