                for(int i=0;i<(int)v3[d.first].size();i++){
                    ans[v4[d.first][i]]=v3[d.first][i];
                }
            }
        }
        if(!b)continue;
        SEG<lint>seg(n,0);
        lint ans3=0;
        rep(i,n){
            ans3+=seg.get(ans[i],n);
            seg.update(ans[i],1);
        }
        chmin(ans2,ans3);
    }
    if(ans2==INF){
        cout<<-1<<endl;
    }
    else cout<<ans2<<endl;
}

