#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

const int mxn = 50;
const int inf = 1e5;
int n, a[mxn], b[mxn];

int dp[19][mxn][mxn][mxn];

int dfs( int idx, int last, int al, int bl ) {
    if( idx == n ) return 0;
    int& ret = dp[idx][last][al][bl];
    if( ~ret ) return ret;

    ret = inf;
    if( al <= a[idx] and al >= last ) {
        ret = min(ret, dfs( idx + 1, al, a[idx], b[idx] ));
    }
    else {
        if( b[idx] >= last ) {
            ret = min(ret, 1 + dfs( idx + 1, b[idx], bl, al ));
        }
    }
    return ret;
}

int main() {
    ios_base :: sync_with_stdio(0);
    cin.tie(0), cout.tie(0);
    cin >> n;
    map<int, int> mp;
    for(int i = 0; i < n; i++) cin >> a[i], mp[a[i]] = 1;
    for(int i = 0; i < n; i++) cin >> b[i], mp[b[i]] = 1;
    if( n == 1 ) {
        cout << "0\n";
        exit(0);
    }

    int m = 0;
    for(auto& i : mp) {
        i.second = m++;
    }
    for(int i = 0; i < n; i++) {
        a[i] = mp[a[i]];
        b[i] = mp[b[i]];
    }
    memset(dp, -1, sizeof dp);
    int res = inf;
    if( a[1] >= a[0] ) {
        res = min(res, dfs( 2, a[0], a[1], b[1] ));
    }
    if( b[1] <= b[0] ) {
        memset(dp, -1, sizeof dp);
        res = min(res, 1 + dfs( 2, b[1], b[0], a[0] ));
    }
    if( res >= inf ) res = -1;
    cout << res << "\n";
}

