int main() {
    int N;
    cin >> N;
    vector<int> A(2 * N);
    rep(i, 2 * N) cin >> A[i];

    vector<int> num(N);
    vector<int> idx(N);
    iota(all(idx), 0);
    int ans = INF;
    rep(bit, 0, 1 << N) {
        bool ok = true;
        rep(i, N) ok ^= bit >> i & 1;
        if (!ok) continue;

        rep(i, N) num[i] = A[i + N * (bit >> i & 1)];
        stable_sort(all(idx), [&](int l, int r) { return num[l] < num[r]; });

        vector<int> eo[2];
        for (int i = 0, j; i < N; i = j) {
            for (j = i + 1; j < N; ++j) {
                if (num[idx[j]] != num[idx[i]]) break;
            }

            if (j - i == 1) {
                if ((abs(i - idx[i]) & 1) ^ (bit >> idx[i] & 1)) {
                    ok = false;
                    break;
                }
            }
            else {
                eo[0].resize(0);
                eo[1].resize(0);
                rep(k, i, j) {
                    eo[(abs(i - idx[k]) & 1) ^ (bit >> idx[k] & 1)].push_back(idx[k]);
                }
                if ((int)eo[0].size() - (int)eo[1].size() != (j - i) % 2) {
                    ok = false;
                    break;
                }

                int ke = 0, ko = 0;
                rep(k, i, j) {
                    if ((k ^ i) & 1) {
                        idx[k] = eo[1][ko];
                        ko++;
                    }
                    else {
                        idx[k] = eo[0][ke];
                        ke++;
                    }
                }
            }
        }
        if (!ok) continue;

        int move = 0;
        rep(i, N - 1) {
            int j = 0;
            for (j = i; j < N; ++j) {
                if (idx[j] == i) break;
            }
            for (; j != i; --j) {
                swap(idx[j], idx[j - 1]);
                move++;
            }
        }

        ans = min(ans, move);
    }

    write(ans == INF ? -1 : ans);
}

