    ll bit = (1ll << n);
    for(ll i=0;i<bit;i++){
        for(ll j=0;j<=50;j++){
            dp[i][j] = INF;
        }
    }
    dp[0][0] = 0;
    for(ll i=0;i<bit;i++){
        for(ll j=0;j<=50;j++){
            // dp[i][j]から配る先を求めるよ

            ll idx = 0;
            for(ll k=0;k<n;k++){
                if((1ll << k) & i)idx++;
            }

            for(ll k=0;k<n;k++){
                // すでに使っているなら
                if((i >> k) & 1)continue;
                ll afterbit = i ^ (1ll << k);
                bool flip = (abs(idx - k) % 2 == 0);
                ll value;
                if(flip){
                    value = x[k];
                }else{
                    value = y[k];
                }
                if(value < j)continue;

                ll inversion = 0;

                for(ll a=k+1;a<n;a++){
                    if((i >> k) & a)inversion++;
                }
                dp[afterbit][value] = min(dp[afterbit][value], dp[i][j] + inversion);
            }
        }
    }
    ans = INF;
    for(ll i=0;i<=50;i++){
        ans = min(ans, dp[(1ll << n) - 1][i]);
    }
