#include <bits/stdc++.h>
using namespace std;

const int inf = 1000003;

int N;

int A[18], B[18];
int dp[36][(1<<18)];

int solve(int pos, int mask, int prev)
{
    if(pos == N)
        return 0;

    if(dp[prev][mask] != -1)
        return dp[prev][mask];

    int ans = inf;

    for(int i=0; i<N; i++)
    {
        if(mask & (1<<i))
            continue;

        if(abs(i - pos) % 2)
        {
            if(B[i] >= prev)
                ans = min(ans, solve(pos+1, (mask | (1 << i)), B[i]) + abs(i - pos));
        }
        else
        {
            if(A[i] >= prev)
                ans = min(ans, solve(pos+1, (mask | (1 << i)), A[i]) + abs(i - pos));
        }
    }

    return dp[prev][mask] = ans;
}

int compress()
{
    map<int, int> M;

    for(int i=0; i<N; i++)
        M[ A[i] ], M[ B[i] ];

    int k = 0;

    for(auto &it : M)
        it.second = k++;

    for(int i=0; i<N; i++)
        A[i] = M[ A[i] ], B[i] = M[ B[i] ];

    return k;
}

int main()
{
    ios::sync_with_stdio(0);
    cin.tie(NULL), cout.tie(NULL);

    cin >> N;

    for(int i=0; i<N; i++)
        cin >> A[i];
    for(int i=0; i<N; i++)
        cin >> B[i];

    int maxx = compress();

    int ans = inf;
    memset(dp, -1, sizeof(dp));

    for(int i=0; i<maxx; i++)
        ans = min(ans, solve(0, 0, 0));

    if(ans == inf)
        ans = -1;
    else
        ans /= 2;

    cout << ans << "\n";
    return 0;
}

