const int MAXN=20;
int n,ans=INF;
int a[MAXN],b[MAXN],c[MAXN],v[MAXN][2];
int w[MAXN],pos[MAXN],vis[MAXN];
struct wy
{
	int x;
	int op;
}t[MAXN];
inline void calc()
{
	int cnt=0;
	for(int i=1;i<=n;++i)
	{
		if(c[i])w[i]=a[i];
		else w[i]=b[i];
		t[i]=(wy){i,0};
	}
	sort(w+1,w+1+n);
	for(int i=1;i<=n;++i)//谁到第一个位置
	{
		for(int j=i;j<=n;++j)
		{
			int d=j-i;
			int ww=t[j].op^(d&1);
			if(v[t[j].x][ww]==w[i])
			{
				for(int k=j;k>i;--k)
				{
					swap(t[k],t[k-1]);
					t[k].op=t[k].op^1;++cnt;
					t[k-1].op=t[k-1].op^1;
					if(cnt>=ans)return;
				}
				break;
			}
		}
		if(v[t[i].x][t[i].op]!=w[i])return;
	}
	ans=min(ans,cnt);
}
inline void dfs(int x)
{
	if(x==n+1)
	{
		calc();
		return;
	}
	c[x]=1;
	dfs(x+1);
	c[x]=0;
	dfs(x+1);
}
