const int N=20,INF=1e9;
int a1[N],a2[N],n;
bool b[N];
struct node {
	int val,id;
	node(int v=0,int i=0):val(v),id(i){}
	bool operator<(const node &t) const{
		if(this->val==t.val)
			return this->id<t.id;
		return this->val<t.val;
	}
}c[N];
int solve() {
	for(int i=1;i<=n;i++)
		if(b[i])
			c[i]=node(a2[i],i);
		else
			c[i]=node(a1[i],i);
	sort(c+1,c+1+n);
	for(int i=1;i<=n;) {
		/*找下有多少个连续相等的*/
		int len=1;
		while(i+len<=n && c[i+len].val==c[i].val)
			len++;
		int s=0,w1;
		for(int j=i;j<i+len;j++) {
			/*这个IF代表J的位置不对，需要修改*/
			if(abs(j-c[j].id+b[c[j].id])%2) {	
				s++;
				if(s==1) {
					w1=j;
				} else {
					s=0;
					swap(c[w1],c[j]);
				}
			}

		} 
		i+=len;
		if(s!=0)
				return -1;
	}

	/*求逆序对*/
	int ans=0;
	for(int i=1;i<=n;i++)
		for(int j=i+1;j<=n;j++) 
			if(c[i].id>c[j].id)
				ans++;
	return ans;
}
int main(){

	cin>>n;
	for(int i=1;i<=n;i++)
		cin>>a1[i];
	for(int i=1;i<=n;i++)
		cin>>a2[i];
	int s=(1<<n)-1;
	int ans=INF;
	for(int i=0;i<=s;i++) {	//1代表翻面 
//		i=6;
		int fl=0;
		for(int j=0;j<n;j++)
			if(i&(1<<j))
				b[j+1]=1,fl++;
			else 
				b[j+1]=0;
		if(fl&1)continue;
		int al=solve();
		if(al!=-1)
			ans=min(ans,al);
	}
	if(ans!=INF)
		printf("%d\n",ans);
	else
		printf("%d\n",-1);
	return 0;
}

