    return true;
}

void func(vector<int>& A,vector<int>& B,int cnt,int ind){
    if(ind==0){
        if(check(A))
        {
            if(ans==-1){
                cnt=ans;
            }
            else
            ans=min(ans,cnt);
        }
        return;
    }

    func(A,B,cnt,ind-1);
    if(ind>0){
        swap(A[ind],B[ind-1]);
        swap(A[ind-1],B[ind]);

        func(A,B,cnt+1,ind-1);

        swap(A[ind],B[ind-1]);
        swap(A[ind-1],B[ind]);
    }
}

