ll Check_swapCount(vector<tuple<ll, ll>> &bufA, vector<tuple<ll, ll>> &bufB){
	ll Anum = (ll)bufA.size();
	ll Bnum = (ll)bufB.size();
	ll N = Anum+Bnum;
	vll idxbuf(N);

	//単調増加チェック
	ll okNum = 0;
	if (Anum == Bnum){
		REP(i, Anum){
			if (get<0>(bufA[i]) <= get<0>(bufB[i])) okNum++;
		}
		REP(i, Bnum-1){
			if (get<0>(bufB[i]) <= get<0>(bufA[i+1])) okNum++;
		}
	} else{
		REP(i, Anum-1){
			if (get<0>(bufA[i]) <= get<0>(bufB[i])) okNum++;
		}
		REP(i, Bnum){
			if (get<0>(bufB[i]) <= get<0>(bufA[i+1])) okNum++;
		}
	}
	if (okNum != N-1) return INF;

	//交換回数
	REP(i, Anum) idxbuf[i*2] = get<1>(bufA[i]);
	REP(i, Bnum) idxbuf[i*2+1] = get<1>(bufB[i]);
	ll swapNum = 0;
	REPS(i, 0, N-2)REPS(j, i+1, N-1){
		if (idxbuf[i] > idxbuf[j]) swapNum++;
	}
	return swapNum;
}


