	if (N == 1) bye(0);

	REP(i, N){
		if (i%2 == 1) swap(A[i], B[i]);
	}

	ll maskNum = CEIL(N, 2);
	ll Anum = maskNum;
	ll Bnum = N-maskNum;
	vector<tuple<ll, ll>> bufA(Anum);
	vector<tuple<ll, ll>> bufB(Bnum);

	ll ans = INF;
	REP(mask, (1LL<<N)){
		//1の数がCEIL(N,2)以外はskip
		ll m = 0;
		REP(i, N) m += ((mask>>i)&1);
		if (m != maskNum) continue;

		//
		ll Acount = 0, Bcount = 0;
		REP(i, N){
			ll bit_ = (mask>>i)&1;
			if (bit_ == 1){
				get<0>(bufA[Acount]) = A[i];
				get<1>(bufA[Acount]) = i;
				Acount++;
			}
			else{
				get<0>(bufB[Bcount]) = B[i];
				get<1>(bufB[Bcount]) = i;
				Bcount++;
			}
		}
		sort(bufA.begin(), bufA.end());
		sort(bufB.begin(), bufB.end());

		ll swapNum = Check_swapCount(bufA, bufB);
		chmin(ans, swapNum);
	}
	if (ans == INF) bye(-1);
	cout << ans << '\n';
}


