class DSwapAndFlip {
public:
    void solve(istream& inp, ostream& outp) {
        Input in(inp);
        Output out(outp);

        int n = in.readInt();
        auto a = in.readIntArray(n);
        auto b = in.readIntArray(n);

        int inf = numeric_limits<int>::max() / 2;
        arr2d<int> answer(1 << n, n, inf);
        for (int i : range(n)) {
            answer(1 << i, i) = 0;
        }
        for (int i : range(1, (1 << n) - 1)) {
            for (int j : range(n)) {
                if (answer(i, j) == inf) {
                    continue;
                }
                int pos = bitCount(i);
                int val = ((j & 1) == (pos & 1)) ? b[j] : a[j];
                int delta = 0;
                for (int k : RevRange(n)) {
                    if ((i >> k & 1) == 1) {
                        delta++;
                        continue;
                    }
                    int cval = ((k & 1) == (pos & 1)) ? a[k] : b[k];
                    if (val <= cval) {
                        minim(answer(i + (1 << k), k), answer(i, j) + delta);
                    }
                }
            }
        }
        int result = *min_element(all(answer[answer.dim1() - 1]));
        if (result == inf) {
            result = -1;
        }
        out.printLine(result);
    }
};


