    for (ll i = 0; i < n; i++) {
      if ((mask >> i) & 1) {
        event[b[i]][1 - (i & 1)].push_back(i);
      } else {
        event[a[i]][i & 1].push_back(i);
      }
    }

    vector<ll> indices;
    for (ll i = 0; i < n; i++)
      indices.push_back(i);
    ll st = 0;
    bool bad = false;
    ll cost = 0;
    for (ll i = 1; i <= 50; i++) {
      if (event[i][0].empty() && event[i][1].empty())
        continue;

      ll sz = event[i][0].size() + event[i][1].size();

      ll cntOdd = sz / 2;
      ll cntEven = sz - cntOdd;

      if (st & 1)
        swap(cntOdd, cntEven);

      if (event[i][1].size() != cntOdd or event[i][0].size() != cntEven) {
        bad = true;
        break;
      }

      ll itOdd = 0, itEven = 0;
      for (ll j = st; j < st + sz; j++) {
        if (j & 1) {
          ll indx = find(indices.begin(), indices.end(), event[i][1][itOdd]) -
                    indices.begin();

          //   cout << indx << " " << event[i][1][itOdd] << endl;
          cost += indx;
          indices.erase(indices.begin() + indx);
          itOdd++;
        } else {
          ll indx = find(indices.begin(), indices.end(), event[i][0][itEven]) -
                    indices.begin();

          // cout << indx << " " << event[i][0][itEven] << endl;
          cost += indx;
          indices.erase(indices.begin() + indx);
          itEven++;
        }
      }
      st += sz;
    }
    if (bad)
      continue;
    res = min(res, cost);
  }
  cout << ((res == inf) ? -1 : res) << en;

  return 0;
}

