int DP(int s, int x)
{
    if(dp[s][x] != INF) return dp[s][x];

    int sta = s ^ (1 << x);
    if(sta == 0)
    {
        return dp[s][x] = x;
    }

    int pos = -1;
    for(int i = 0; i < n; i++) if((s >> i) & 1) pos++;

    for(int i = 0; i < n; i++)
    {
        if((sta >> i) & 1)
        {
            int p = abs(pos - x) & 1 ? b[x] : a[x];
            int q = abs(pos - 1 - i) & 1 ? b[i] : a[i];

            if(p >= q)
            {
                auto chmin = [](int &a, int b) {if(a > b) a = b;};

                chmin(dp[s][x], DP(sta, i) + abs(x - pos));
            }
        }
    }

    return dp[s][x];
}

