class BIT {
public:
	int N;
	vi vallist;

	void init() {
		rep(i, N + 1)
			vallist.push_back(0);
		return;
	}

	void add(int i, int val) {
		for (int x = i + 1; x <= N; x += x & -x) // x += x & -x : 100101000 -> 100110000
			vallist[x] += val;
		return;
	}

	int sum(int i) { // 0~i
		int val = 0;
		for (int x = i + 1; x > 0; x -= x & -x)
			val += vallist[x];
		return val;
	}

	int sum_LR(int L, int R) { // L~R
		int val = sum(R) - sum(L - 1);
		return val;
	}
};

