                d.pb({a[j],{j,0}});
            }else{
                d.pb({b[j],{j,1}});
            }
        }
        sort(d.begin(),d.end());
        bool ok=1;
        rep(k,n){
            rep(j,n-1){
                if(abs(j-d[j].se.fi)%2==0 && d[j].se.se==1 && d[j].fi==d[j+1].fi) swap(d[j],d[j+1]);
                else if(abs(j-d[j].se.fi)%2!=0 && d[j].se.se==0 && d[j].fi==d[j+1].fi) swap(d[j],d[j+1]);
            }
        }
        rep(j,n){
            if(abs(j-d[j].se.fi)%2==0 && d[j].se.se==1) ok=0;
            else if(abs(j-d[j].se.fi)%2!=0 && d[j].se.se==0) ok=0;
        }
        if(ok){
            all=0;
            //cout << "ok" << endl;
            int res=0;
            rep(j,n-2){
                rep(k,n){
                    if(d[j].fi!=d[j+2*k].fi||n<=j+2*k) break;
                    if(d[j].fi==d[j+2*k].fi && abs(j-d[j].se.fi)+abs(j+2*k-d[j+2*k].se.fi)>abs(j+2*k-d[j].se.fi)+abs(j-d[j+2*k].se.fi)) swap(d[j],d[j+2*k]);
                }
            }
            rep(j,n){
                res+=abs(j-d[j].se.fi);
            }
            res/=2;
            if(ans==-1) ans=res;
            ans=min(ans,res);
        }
    }
    if(all){
        cout << -1 << endl;
        return 0;
    }
    cout << ans << endl;
}

