void _main()
{
    ll n; llin(n);
    S V<ll> alist; llina(alist, n);
    S V<ll> blist; llina(blist, n);

    S V<ll> oddlist;
    S V<ll> evenlist;
    rep (i, n) {
        if (i & 1LL) {
            oddlist.pb(alist[i]);
            evenlist.pb(blist[i]);
        }
        else {
            oddlist.pb(blist[i]);
            evenlist.pb(alist[i]);
        }
    }

    ll ans = 1e18;
    BIT tree(20, 0LL);

    rep (ptn, pow(2, 18)) {
        bitset<200> idxptn;
        ll idxcnt = 0LL;
        rep (idx, n) if (ptn & (1LL<<idx)) {
            idxptn.set(idx);
            idxcnt++;
        }
        if (idxcnt != n/2LL) continue;

        V<t2> odd_validxs;
        rep (i, n) if (idxptn.test(i)) odd_validxs.pb(t2(oddlist[i], i));
        sort(odd_validxs);

        V<t2> even_validxs;
        rep (i, n) if (!idxptn.test(i)) even_validxs.pb(t2(evenlist[i], i));
        sort(even_validxs);

        V<t2> validxs;
        rep (i, n) {
            if (i & 1LL) validxs.pb(odd_validxs[i/2]);
            else validxs.pb(even_validxs[i/2]);
        }

        ll prev = -1LL;
        bool ng = false;
        for (auto validx : validxs) {
            ll val = get<0>(validx);
            if (val < prev) {
                ng = true;
                break;
            }
            prev = val;
        }
        if (ng) continue;

        ll total = 0LL;
        tree.init(0LL);
        for (auto validx : validxs) {
            ll idx = get<1>(validx);
            total += (tree.sum(20LL) - tree.sum(idx + 1LL));
            tree.add(idx + 1LL, 1LL);
        }

        ans = min(ans, total);
    }

    if (ans >= 1e17) cout << -1 << endl;
    else cout << ans << endl;
}

