using namespace std;
const int inf = 1e9;

int popcount(int n){
    n = (n & 0x55555555) + (n >> 1 & 0x55555555);
    n = (n & 0x33333333) + (n >> 2 & 0x33333333);
    n = (n & 0x0f0f0f0f) + (n >> 4 & 0x0f0f0f0f);
    n = (n & 0x00ff00ff) + (n >> 8 & 0x00ff00ff);
    return (n & 0x0000ffff) + (n >>16 & 0x0000ffff);
}

int main(){
	int n;
	cin >> n;
	vector<int> a(n),b(n);
	for(int i=0; i<n; i++){
		cin >> a[i];
	}
	for(int i=0; i<n; i++){
		cin >> b[i];
	}

	// dp[i][j]: iの組み合わせで選んで、最後がjのときの最小コスト
	vector<vector<int>> dp(1<<n, vector<int>(n, inf));
	for(int i=0; i<n; i++){
		dp[1<<i][i] = i;
	}
	for(int i=1; i<(1<<n); i++){
		int count = popcount(i);
		for(int j=0; j<n; j++){
			if(!(i>>j&1)) continue;
			if(dp[i][j] == inf) continue;
			//cout << i << " " << j << endl;
			int last = ((count-1-j)%2==0)? a[j]: b[j];
			for(int k=0; k<n; k++){
				if(i>>k&1) continue;
				//cout << i << " " << j << " " << k << endl;
				int newlast = ((count-k)%2==0)? a[k]: b[k];
				//cout << "last " << last << " " << newlast << endl;
				if(newlast < last) continue;
				int smallcount = 0;
				for(int l=0; l<k; l++){
					if(i>>l&1) smallcount++;
				}
				int cost = max(k-smallcount, 0);
				int newset = i|(1<<k);
				dp[newset][k] = min(dp[newset][k], dp[i][j]+cost);
			}
		}
	}
	/*
	for(int i=0; i<(1<<n); i++){
		cout << "i= " << i << endl;
		for(int j=0; j<n; j++){
			cout << dp[i][j] << endl;
		}
	}
	*/
	int ans = *min_element(dp[(1<<n)-1].begin(), dp[(1<<n)-1].end());
	if(ans == inf) ans = -1;
	cout << ans << endl;
	return 0;
}

