void solve() {
  int n;
  cin >> n;
  vi32 a(n), b(n);
  cin >> a >> b;
  rep(i, n) a[i]--, b[i]--;
  using T = tuple<int, int, int>; // count, last, used set
  pqasc<T> q;
  q.emplace(0, 0, 0);
  vector<vi32> dp(50, vi32(bit32(n), 1e9));
  while (sz(q)) {
    int cnt, prev, used;
    tie(cnt, prev, used) = q.top();
    q.pop();
    if (dp[prev][used] != 1e9) {
      continue;
    }
    dp[prev][used] = cnt;
    if (used == bit32(n) - 1) {
      cout << cnt << endl;
      return;
    }
    int c = __builtin_popcount(used);
    rep(i, n) {
      if (used & bit32(i)) continue;
      int now;
      if (c % 2 == i % 2) {
        now = a[i];
      } else {
        now = b[i];
      }
      if (prev > now) continue;
      int from = i + __builtin_popcount(used & ((bit32(n) - 1) ^ (bit32(i) - 1)));
      q.emplace(cnt + from - c, now, used | bit32(i));
    }
  }
  cout << -1 << endl;
}

