int dp(int msk, int x, int nm){
    if(x==n){
        return 0;
    }
//    cout<<x<<" "<<n<<" "<<nm<<" "<<mem[msk][nm]<<endl;
    if(mem[msk][nm]!=-1){
        return mem[msk][nm];
    }
    int res=1e9;
    for(int i=0; i<n; ++i){
        if(msk&(1<<i)){
            continue;
        }
        int tmp=0;
        for(int j=0; j<i; ++j){
            if(!(msk&(1<<j))){
                ++tmp;
            }
        }
        if(i%2==x%2){
            if(a[i]<nm)
                continue;
            res=min(res, tmp+dp(msk|(1<<i), x+1, a[i]));
        }
        else{
            if(b[i]<nm){
                continue;
            }
            res=min(res, tmp+dp(msk|(1<<i), x+1, b[i]));
        }
    }
//    cout<<msk<<" "<<nm<<" "<<x<<" "<<res<<endl;
    mem[msk][nm]=res;
    return res;
}
