typedef long long ll;

const int MAX_N = 18;
const int MAX_V = 51;

int main() {
  int N;
  cin >> N;

  vector<int> A;
  vector<int> B;

  int a, b;
  for (int i = 0; i < N; ++i) {
    cin >> a;
    A.push_back(a);
  }

  for (int i = 0; i < N; ++i) {
    cin >> b;
    B.push_back(b);
  }

  int dp[1 << N][MAX_V];
  memset(dp, -1, sizeof(dp));
  dp[0][0] = 0;

  for (int c = 0; c < N; ++c) {
    for (int mask = 0; mask < (1 << N); ++mask) {
      if (__builtin_popcount(mask) != c) continue;

      for (int v = 0; v <= 50; ++v) {
        int cnt = dp[mask][v];
        if (cnt == -1) continue;

        int shift_cnt = 0;

        for (int i = N - 1; i >= 0; --i) {
          if (mask >> i & 1) {
            shift_cnt++;
            continue;
          }

          int move_cnt = abs((i + shift_cnt) - c);
          int num = (abs(i - c) % 2 == 0) ? A[i] : B[i];

          if (num < v) continue;

          int nmask = mask | (1 << i);
          /*
          fprintf(stderr, "%d: c: %d, move_cnt: %d, mask: %d, nmask: %d, num: %d\n",
              i, c, move_cnt, mask, nmask, num);
              */

          if (dp[nmask][num] == -1) {
            dp[nmask][num] = dp[mask][v] + move_cnt;
          } else {
            dp[nmask][num] = min(dp[nmask][num], dp[mask][v] + move_cnt);
          }
        }
      }
    }
  }

  int ans = INT_MAX;

  for (int v = 1; v <= 50; ++v) {
    if (dp[(1 << N) - 1][v] == -1) continue;

    ans = min(ans, dp[(1 << N) - 1][v]);
  }

  if (ans == INT_MAX) {
    cout << -1 << endl;
  } else {
    cout << ans << endl;
  }

  return 0;
}

