int n, a[NMAX], b[NMAX], s[NMAX], t[NMAX], p[NMAX];
int main() {
    // solution
    while (std::cin >> n) {
        for (int i = 0; i < n; i++) std::cin >> a[i];
        for (int i = 0; i < n; i++) std::cin >> b[i];
        int answ = INF;
        for (int mask = 0; mask < (1 << n); mask++) {
            for (int i = 0; i < n; i++) {
                p[i] = ((mask >> i) & 1);
                s[i] = t[i] = (p[i] ? b[i] : a[i]);
            }
            std::sort(s,s+n);
            int curr = 0;
            for (int i = 0; i < n; i++) {
                // want s[i]
                int pos = -1;
                for (int j = i; j < n; j++) {
                    if (t[j] == s[i] && (j - i) % 2 == p[j]) {
                        pos = j;
                        break;
                    }
                }
                if (pos == -1) { curr = INF; break; }
                for (int j = i; j < pos; j++) {
                    curr++;
                    std::swap(t[j], t[j+1]);
                    std::swap(p[j], p[j+1]);
                    p[j] = 1 - p[j];
                    p[j+1] = 1 - p[j+1];
                }
            }
            std::remin(answ, curr);
        }
        if (answ == INF) answ = -1;
        std::cout << answ << std::endl;
    }
    return 0;
}

