const int N = 1 << 18;
const int INF = 10000;

int n;
int a[N + 5], b[N + 5];
int dp[N + 5][20];
int val[N + 5];

int solve(int mask, int last){
	if(mask == (1 << n) - 1) return 0;
	int& ret = dp[mask][last];
	if(ret != -1) return ret;
	ret = INF;
	for(int i=0; i<n; i++){
		if(mask & (1 << i)) continue;
		int bef = abs(val[mask] - last+1) % 2 == 0 ? a[last] : b[last];
		int v = abs(val[mask] - i) % 2 == 0 ? a[i] : b[i];
//		printf("bef %d, v %d, last %d, now %d\n",bef ,v,last,i);
		if(bef > v) continue;
		ret = min(ret, solve(mask | (1 << i), i) + abs(val[mask] - i));
	}
//	printf("%d %d -> %d\n",mask,last,ret);
	return ret;
}

