int solve(void){
    int n;
    cin >> n;

    vector<int> a(n);
    rep(i, n){
        cin >> a[i];
        --a[i];
    }

    vector<int> b(n);
    rep(i, n){
        cin >> b[i];
        --b[i];
    }

    vector<int> v1(n), v2(n);
    rep(i, n){
        if(i & 1){
            v1[i] = a[i];
            v2[i] = b[i];
        }else{
            v1[i] = b[i];
            v2[i] = a[i];
        }
    }

    fill(dp[0], dp[n+1], IINF);
    dp[n][0] = 0;

    rep(i, n){
        rep(j, 1 << n){
            vector<int> sumi, mada;
            rep(k, n){
                if(j >> k & 1){
                    sumi.emplace_back(k);
                }else{
                    mada.emplace_back(k);
                }
            }
            if((int)sumi.size() != i){
                continue;
            }

            vector<int> cost(mada.size());
            rep(k, mada.size()){
                if(mada[k] < i){
                    cost[k] = abs((i-mada[k])-(sumi.end()-upper_bound(sumi.begin(), sumi.end(), mada[k])));
                }else{
                    cost[k] = (mada[k]-i)+(sumi.end()-upper_bound(sumi.begin(), sumi.end(), mada[k]));
                }
            }

            if(sumi.empty()){
                rep(k, n){
                    chmin(dp[k][1 << k], k);
                }
            }else{
                for(auto l : sumi){
                    rep(m, mada.size()){
                        if(i & 1){
                            if(v2[l] > v1[mada[m]]){
                                continue;
                            }
                        }else{
                            if(v1[l] > v2[mada[m]]){
                                continue;
                            }
                        }
                        chmin(dp[mada[m]][j | (1 << mada[m])], dp[l][j]+cost[m]);
                    }
                }
            }
        }
    }

    int res = IINF;
    rep(i, n){
        chmin(res, dp[i][(1 << n)-1]);
    }

    if(res < IINF){
        return res;
    }

    return -1;
}

