int inversion(vector<T> &A) {
    vector<T> B = A;
    int ans = 0;
    for (int i = 0; i < B.size(); i++) {
        for (int j = B.size() - 1; j - 1 >= 0; j--) {
            if (B[j - 1] > B[j]) swap(B[j - 1], B[j]), ans++;
        }
    }
    return ans;
}
int main() {
    int N; cin >> N;
    vector<int> A(N), B(N);
    for (auto &a : A) cin >> a;
    for (auto &b : B) cin >> b;
    int half = (N + 1) / 2;
    int ans = 1e9;
    for (int mask = 0; mask < (1 << N); mask++) if (__builtin_popcount(mask) == half) {
        vector<pair<int, int>> C, D;
        for (int i = 0; i < N; i++) {
            if ((1 << i) & mask) {
                if (i % 2 == 0) C.emplace_back(A[i], i);
                else C.emplace_back(B[i], i);
            } else {
                if (i % 2 == 0) D.emplace_back(B[i], i);
                else D.emplace_back(A[i], i);
            }
        }
        sort(begin(C), end(C));
        sort(begin(D), end(D));
        auto E = merge(C, D);
        vector<int> F;
        for (int i = 0; i + 1 < E.size(); i++) {
            if (E[i].first > E[i + 1].first) {
                goto NEXT;
            }
        }
        for (int i = 0; i < E.size(); i++) {
            F.push_back(E[i].second);
        }
        ans = min(ans, inversion(F));
        NEXT:;
    }
    cout << (ans == 1e9 ? -1 : ans) << endl;
    return 0;
}

