#include <bits/stdc++.h>
using namespace std;
using lint = long long int;
#define bit(n) (1LL<<(n))

int main() {
    lint n;
    cin >> n;

    vector<lint> a(n);
    for(auto& elem : a)  cin >> elem;

    vector<lint> b(n);
    for(auto& elem : b)  cin >> elem;

    auto next_combination = [](lint sub) {
        lint x = sub & -sub;
        lint y = sub + x;
        return (((sub & ~y) / x) >> 1) | y;
    };

    // 1. 偶数番目(0, 2, ...)に使うカードで全探索
    lint k = (n+1)/2;
    lint ans = 1e18;
    for(lint mask = bit(k)-1; mask < bit(n); mask = next_combination(mask)) {
        bitset<30> bs(mask);
        vector<pair<lint, lint>> seq;
        vector<pair<lint, lint>> odd, even;
        for(lint i=0; i<n; i++) {
            if(bs.test(i)) {
                seq.emplace_back(i%2 ? b[i] : a[i], i);
                even.emplace_back(i%2 ? b[i] : a[i], i);
            } else {
                seq.emplace_back(i%2 ? a[i] : b[i], i);
                odd.emplace_back(i%2 ? a[i] : b[i], i);
            }
        }

        // 2. 目標とする並び順を決める
        sort(even.begin(), even.end());
        sort(odd.begin(), odd.end());

        vector<lint> vec(n);
        map<pair<lint,lint>, lint> mp;
        for(lint i=0; i<n; i++) {
            vec[i] = (i%2 ? odd[(i-1)/2] : even[i/2]).first;
            mp[(i%2 ? odd[(i-1)/2] : even[i/2])] = i;
        }
        if(!is_sorted(vec.begin(), vec.end()))  continue;

        vector<lint> ind;
        for(auto elem : seq)  ind.push_back(mp[elem]);

        // 3. バブルソートのswap回数
        lint counter = 0;
        for(lint i=0; i<n; i++)
        for(lint j=i+1; j<n; j++) {
            if(ind[i] > ind[j])  counter++;
        }
        ans = min(ans, counter);
    }

    cout << (ans == 1e18 ? -1 : ans) << endl;
}

