  ifstream ifs("in.txt");
  cin.rdbuf(ifs.rdbuf());
#endif
  int N;
  while (cin >> N) {
    vector<int> A(N), B(N);
    for (int i = 0; i < N; i++) cin >> A[i];
    for (int i = 0; i < N; i++) cin >> B[i];
    vec<int, 3> dp = make_v(1 << N, N, 2, INF);
    for (int i = 0; i < N; i++) {
      dp[1 << i][i][i & 1] = i;
    }
    for (int m = 1; m < (1 << N); m++) {
      vector<int> hit;
      vector<pii> miss;
      for (int i = N - 1; i >= 0; i--) {
        if ((m >> i) & 1) {
          hit.push_back(i);
        } else {
          miss.emplace_back(i, hit.size() & 1);
        }
      }
      reverse(hit.begin(), hit.end());
      reverse(miss.begin(), miss.end());
      for (int i : hit) {
        for (int p = 0; p < 2; p++) {
          if (dp[m][i][p] >= INF) continue;
          int v = p == 0 ? A[i] : B[i];
          int k = 0;
          for (auto y : miss) {
            int j = y.fst, jp = y.snd;
            int np = (jp ^ k) & 1;
            int nv = np == 0 ? A[j] : B[j];
            if (v <= nv) {
              chmin(dp[m | (1 << j)][j][np], dp[m][i][p] + k);
            }
            ++k;
          }
        }
      }
    }
    int res = INF;
    for (int i = 0; i < N; i++) {
      for (int p = 0; p < 2; p++) {
        chmin(res, dp[(1 << N) - 1][i][p]);
      }
    }
    cout << (res >= INF ? -1 : res) << endl;
  }
  return 0;
}

