        for(ll k=j-1; k>=i; --k){
          V_copy[k+1] = V_copy[k];
          Vb[k+1] = Vb[k]+1;
          Vb[k+1]%=2;
        }
        V_copy[i] = V[i];
        Vb[i] = 0;
