    for (int i = 1; i <= n; i++) {
        cin >> a[i];
    }
    for (int i = 1; i <= n; i++) {
        cin >> b[i];
    }
    a[0] = b[0] = -1e9;
    for (int i = 0; i <= n; i++) {
        for (int j = 0; j <= n; j++) {
            fill(dp[i][j], dp[i][j] + topkek, 1e9);
        }
    }
    dp[0][0][0] = 0;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j <= n; j++) {
            for (int mask = 0; mask < topkek; mask++) {
                if (dp[i][j][mask] == 1e9) {
                    continue;
                }
                for (int k = 1; k <= n; k++) {
                    if (mask & (1 << (k - 1))) {
                        continue;
                    }
                    int cur = a[k];
                    if (abs(i + 1 - k) & 1) {
                        cur = b[k];
                    }
                    int prev = a[j];
                    if (abs(i - j) & 1) {
                        prev = b[j];
                    }
                    if (cur >= prev) {
                        int dist = 0;
                        for (int x = 0; x + 1 < k; x++) {
                            if (!(mask & (1 << x))) {
                                dist++;
                            }
                        }
                        dp[i + 1][k][mask | (1 << (k - 1))] = min(dp[i + 1][k][mask | (1 << (k - 1))], dp[i][j][mask] + dist);
                    }
                }
            }
        }
