void swapLine(int i) {
	ll a1 = as[i][0];
	ll a2 = as[i+1][0];
	ll b1 = as[i][1];
	ll b2 = as[i+1][1];
	as[i][0] = b2;
	as[i+1][0] = b1;
	as[i][1] = a2;
	as[i+1][1] = a1;
}

ll dfs(int index, ll c) {
	ll m = 1e15;
	if (index == n - 1) {
		if (as[index][0] >= c) return 0;
		return m;
	}
	for (int i = index; i < n; i++) {
		ll val = abs(index - i);
		for (int j = i - 1; j >= index; j--) {
			swapLine(j);
		}
		if (as[index][0] >= c) {
			val += dfs(index + 1, as[index][0]);
			m = min(m, val);
		}
		for (int j = i - 1; j >= index; j--) {
			swapLine(j);
		}
	}
	return m;
}

