struct state {
	vector<int> p;
	int mask;

	state() {
	}

	state(vector<int> tp, int tmask = 0) {
		p = tp;
		mask = tmask;
	}

	bool operator<(const state & s) const {
		if (mask != s.mask) {
			return (mask < s.mask);
		}
		return (p < s.p);
	}
};

queue<state> q;
