			for (int j = i + 1; j < n; ++j) {
				if (c[j] < c[i]) {
					++cnt;
				}
			}
			for (int j = i - 1; j >= 0; --j) {
				if (c[j] > c[i]) {
					++cnt;
				}
			}
			now += cnt;
