int bubbleSort(vector<pair<int, int>> &array) {
    int i, j, k;
    int cnt = 0;
    int array_size = array.size();
    for (i = 0; i < (array_size - 1); i++) {
        for (j = (array_size - 1); j > i; j--) {
            if (array[j].first < array[j - 1].first) {
                swap(array[j], array[j - 1]);
                cnt++;
            }
        }
    }
    return cnt;
}

