                swap(now[j],now[j+1]);
                now[j].k^=1;
                now[j+1].k^=1;
                ans++;
            }
        }
    }
    for(int i=0;i<n;i++){
        if(now[i].k!=now[i].fz){
            bool ff2=false;
            for(int j=i+1;j<n;j+=2){
