vector<int> mask[19];

int main(){
    memset(dp, 0x3f, sizeof dp);
    scan(n);
    for(int i = 0; i < n; i++)
        scan(a[i]);
    for(int i = 0; i < n; i++)
        scan(b[i]);
    for(int i = 0; i < (1<<n); i++)
        mask[__builtin_popcount(i)].emplace_back(i);
    dp[0][0][0] = 0;
    for(int i = 1; i <= n; i++){
        for(int pre : mask[i-1]){
            //previously taken
            for(int l = 0; l < 51; l++){
                //last number
                for(int j = 0; j < n; j++){
                    if(dp[i-1][pre][l] == 0x3f3f3f3f)
                        continue;
                    //take # j
                    if(!(pre&(1<<j))){
                        int cur = pre|(1<<j);
                        int val;
                        if((j^i)&1) //if same parity
                            val = a[j];
                        else
                            val = b[j];
                        if(val < l)
                            continue;

                        int mv = 0, ij = j;
                        //get index of j
                        for(int k = 0; k < j; k++){
                            if((pre&(1<<k)))
                                ij--;
                        }
                        for(int k = j+1; k < n; k++){
                            if(pre&(1<<k))
                                ij++;
                        }
                        mv = abs(ij);
                        //print(i-1, pre, l, i, cur, val, mv);
                        dp[i][cur][val] = min(dp[i][cur][val], dp[i-1][pre][l] + mv);
                    }
                }
            }
        }
    }

    int i = (1<<n)-1;
    int ans = *min_element(dp[n][i], dp[n][i]+51);
    if(ans == 0x3f3f3f3f)
        puts("-1");
    else
        print(ans/2);

    return 0;
}

