    if(!OK)continue;

    vector<long>v;long S=0;
    for(long d=0;d<2;d++){
      for(long i=d;i<N;i+=2){
        v.push_back(i);
        if(i+2>=N||X[i].first!=X[i+2].first){
          long ms=LONG_MAX;
          do{
            long s=0;
            for(long id:v)s+=abs(X[id].second.first-id);
            ms=min(ms,s);
          }while(next_permutation(v.begin(),v.end()));
          S+=ms;
          v.clear();
        }
      }
    }

    S/=2;
    if(OK)ans=(ans==-1?S:min(ans,S));
  }
  cout<<ans;
}

