};

struct Range {
  int left, right;
};

int N;
vector<Card> cards;
int check_answer = numeric_limits<int>::max();
map<pair<int, vector<int>>, int> min_steps;

bool sorted(int mask, vector<int> order) {
  vector<int> numbers(N);
  for (int i = 0; i < N; i++) {
    int j = order[i];
    if ((mask >> j) & 1) {
      numbers[i] = cards[j].B;
    } else {
      numbers[i] = cards[j].A;
    }
  }
  return is_sorted(all(numbers));
}

void rec(int mask, vector<int> order, int steps) {
  if (steps >= check_answer) {
    return;
  }
  pair<int, vector<int>> key = {mask, order};
  auto it = min_steps.find(key);
  if (it != min_steps.end() && steps >= it->second) {
    return;
  }
  min_steps[key] = steps;
  if (sorted(mask, order)) {
    check_answer = steps;
    return;
  }
  for (int i = 0; i < N - 1; i++) {
    int lhs = order[i], rhs = order[i + 1];
    int new_mask = mask;
    new_mask ^= (1 << lhs);
    new_mask ^= (1 << rhs);
    auto new_order = order;
    swap(new_order[i], new_order[i + 1]);
    rec(new_mask, new_order, steps + 2);
  }
}

