int solve(vector<int> &V, int N, bitset<18> &bit){
  int ret = 0;
  bool flag = true;
  vector<int> count(N,0);
  for(int i=0;flag;i++){
    flag = false;
    for(int j=N-1;j>=i+1;j--){
      if(V[j]<V[j-1]){
        swap(V[j],V[j-1]);
        count[j]++;
        count[j-1]++;
        swap(count[j],count[j-1]);
        if(bit[j]!=bit[j-1]){
          bit.flip(j);
          bit.flip(j-1);
        }
        flag=1;
        ret++;
      }
    }
  }

  for(int i=0;i<N;i++){
    if(i!=N-1){
      if(count[i]%2!=bit[i] && count[i+1]%2!=bit[i+1] && V[i]==V[i+1]){
        i++;
        continue;
      }
    }
    if(count[i]%2!=bit[i]) return 1001001001;
  }

  return ret;
}

