ll cal(){
	memset(cnt, 0, sizeof(cnt));

	ll res = 0;
	rrep(i, n-1, 1){
		zep(j, 0, i){
			if(a[p[j].second][p[j].first] > a[p[j+1].second][p[j+1].first]){
				cnt[p[j].second]++;
				cnt[p[j+1].second]++;

				P tmp = p[j];
				p[j] = p[j+1];
				p[j+1] = tmp;

				res++;
			}
		}
	}

	zep(i, 0, n-1){
		if(cnt[p[i].second] % 2 != p[i].first){
			zep(j, i+1, n){
				if((cnt[p[j].second] % 2 != p[j].first) && ((j-i+1)%2 == 0) && (a[p[i].second][p[i].first] == a[p[j].second][p[j].first])){
					res += j-i;
					cnt[p[i].second] = p[i].first;
					cnt[p[j].second] = p[j].first;
				}
				break;
			}
		}
	}

	zep(i, 0, n){
		if(cnt[p[i].second] % 2 != p[i].first){
			return INF;
		}
	}
	return res;
}

