const int INF = 0x3f3f3f3f;
const int MAXN = 1e5 + 5;

mt19937 rng(chrono::steady_clock::now().time_since_epoch().count());

bool valid(vector<pii>& a) {
	for (int i = 1; i < (int)a.size(); i++)
		if (a[i].fi < a[i-1].fi) return false;
	return true;
}

inline bool vale(int i, vector<pii>& a, int n) {
	if (a[i].fi > a[i+1].fi) return true;
	if (a[i+1].fi > a[i].fi && a[i+1].se > a[i].se) return false;
	return true;
}

set<vector<pii>> st;
int solve(vector<pii> a, int n) {
	if (st.count(a)) return INF;
	if (valid(a)) return 0;
	st.insert(a);

	int ret = INF;
	for (int i = 0; i < n-1; i++) {
		if (!vale(i, a, n)) continue;

		swap(a[i], a[i+1]);
		swap(a[i].fi, a[i].se);
		swap(a[i+1].fi, a[i+1].se);

		ret = min(ret, 1 + solve(a, n));

		swap(a[i], a[i+1]);
		swap(a[i].fi, a[i].se);
		swap(a[i+1].fi, a[i+1].se);
	}

	return ret;	
}

int main() {
	int n; scanf("%d", &n);
	vector<pii> a(n);
	for (int i = 0; i < n; i++) scanf("%d", &a[i].fi);
	for (int i = 0; i < n; i++) scanf("%d", &a[i].se);
	int ans = solve(a, n);
	printf("%d\n", ans >= INF ? -1 : ans);

	return 0;
}

