                if(abs(t-j)%2==0){
                    if(a[j]>=k){
                        dp[i|(1<<j)][a[j]]=min(dp[i|(1<<j)][a[j]],dp[i][k]+p);
                    }
                }
                else{
                    if(b[j]>=k){
                        dp[i|(1<<j)][b[j]]=min(dp[i|(1<<j)][b[j]],dp[i][k]+p);
                    }
                }
            }
        }
    }
    int ans=1e9;
    for(int i=0;i<=50;i++){
        ans=min(ans,dp[(1<<n)-1][i]);
    }
    if(ans==1e9){
        cout << -1 << endl;
    }
    else{
        cout << ans << endl;
    }
}

