const int INF = 1LL << 29;
const ll LONGINF = 1LL << 60;
const ll MOD = 1000000007LL;

int dp[1 << 18][51];
int main() {
    int N; cin >> N;
    vector<int> A(N), B(N);
    for(int i=0; i<N; i++) cin >> A[i];
    for(int i=0; i<N; i++) cin >> B[i];

    fill(dp[0], dp[1 << N], INF);
    dp[0][0] = 0;
    for(int bit=0; bit<(1<<N); bit++) {
        for(int v=0; v<=50; v++) {
            if(dp[bit][v] == INF) continue;
            // fprintf(stderr, "dp[%d][%d] = %d\n", bit, v, dp[bit][v]);
            for(int i=0; i<N; i++) {
                if(bit >> i & 1) continue;
                // 前に行ったやつ + 元々前にいるやつ
                int c = __builtin_popcount(bit), b = c;

                // bit の補集合であって i 以前のもの
                // i bit 目を含めないようにする
                int rem = (((1 << N) - 1 - bit) & ((1 << i) - 1));
                c += __builtin_popcount(rem);
                // cerr << "rem = " << rem << endl;
                // cerr << "c = " << c << endl;

                // 現在の値 (元インデックスと偶奇違うなら反転)
                int val = (c - i) % 2 ? B[i] : A[i];

                // 現在のインデックスが c
                // 目標インデックスが b -> dist = c - b
                // 目標との偶奇が違うなら反転
                int dist = c - b;
                if(dist % 2) val ^= (A[i] ^ B[i]);

                if(v <= val) {
                    int nbit = bit | (1 << i);
                    chmin(dp[nbit][val], dp[bit][v] + dist);
                }
            }
        }
    }

    int ans = *min_element(dp[(1<<N)-1], dp[(1<<N)-1] + 51);
    cout << (ans == INF ? -1 : ans) << endl;
    return 0;
}

