                int m = pop_count(i);
                int front = (i == 0 ? 0 : v[abs(m-1-j)%2][j]);
                int next = v[abs(m-k)%2][k];
                if(next < front)continue;
                dp[i|(1<<k)][k] = min(dp[i|(1<<k)][k], dp[i][j]+abs(m-k));
            }
        }
    }

    int ans = INF;
    for(int i=0;i<n;++i){
        ans = min(ans, dp[(1<<n)-1][i]);
    }

    cout << (ans == INF ? -1 : ans/2) << endl;

    return 0;
}

