int BIT[MAX], M = 100;//Nは要素数
int bitsum(int i) {
	int s = 0;
	while (i > 0) {
		s += BIT[i];
		i = i & (i - 1);
	}
	return s;
}
void bitadd(int i, int x) {
	while (i <= M) {
		BIT[i] += x;
		i += i & -i;
	}
}
