void dfs(int val, vector <int>& idx) {
	if (idx.size() == N){
		//隣接互換の回数を求める
		int cnt = 0;
		for (int ii = 1; ii < N; ++ii){
			int val1 = idx[ii];
			for (int jj = 0; jj < ii; ++jj){
				int val2 = idx[jj];
				if (val2 > val1){
					cnt++;
				}
			}
		}

		ans = min(ans, cnt);

		return;
	}

	int size = idx.size();
	for (int ii = 0; ii < N; ++ii){
		if (used[ii] == 1) continue;
		int nval = (size % 2 == 0) ? first[ii] : second[ii];
		if (nval < val) continue;
		idx.push_back(ii);
		used[ii] = 1;
		dfs(nval, idx);
		idx.pop_back();
		used[ii] = 0;
	}
}


