// メイン
struct SWAP_INFO {
	int val;
	bool isRed;
	int cnt;
};

bool sortOne(int N, vector<SWAP_INFO> &swapRes, ll &swapCntAll)
{
	swapCntAll = 0;
	REP(i, N - 1) {
		for (int j = N - 1; j > i; j--) {
			if (swapRes[j].val < swapRes[j - 1].val) {
				swapRes[j].cnt++;
				swapRes[j - 1].cnt++;
				swapCntAll++;
				swap(swapRes[j], swapRes[j - 1]);
			}
		}
	}

	REP(i, N - 1) {
		for (int j = N - 1; j > i; j--) {
			bool swapExec = false;
			if (swapRes[j].isRed) {
				if (!IsEven(swapRes[j].cnt)) {
					if (swapRes[j].val == swapRes[j - 1].val) {
						swapExec = true;
					}
				}
			} else {
				if (!IsOdd(swapRes[j].cnt)) {
					if (swapRes[j].val == swapRes[j - 1].val) {
						swapExec = true;
					}
				}
			}

			if (swapExec) {
				swapRes[j].cnt++;
				swapRes[j - 1].cnt++;
				swapCntAll++;
				swap(swapRes[j], swapRes[j - 1]);
			}
		}
	}

	REP(i, N) {
		if (swapRes[i].isRed) {
			if (!IsEven(swapRes[i].cnt)) {
				return false;
			}
		} else {
			if (!IsOdd(swapRes[i].cnt)) {
				return false;
			}
		}
	}

	return true;
}

