	vector<int>	A(N), B(N);
	REP(i, N) cin >> A[i];
	REP(i, N) cin >> B[i];

	ll ans = INF;
	for (ll bitPtn = 0; bitPtn < ((ll)1 << N); bitPtn++) {
		int swapCnt = 0;
		vector<SWAP_INFO>	swapRes(N);
		REP(i, N) {
			auto &one = swapRes[i];
			if (bitPtn & ((ll)1 << i)) {
				one.val = A[i];
				one.isRed = true;
			} else {
				one.val = B[i];
				one.isRed = false;
			} 
			one.cnt = 0;
		}

		ll swapCntAll = 0;
		if (sortOne(N, swapRes, swapCntAll)) {
