				posActu--;
			}
		}
		else if (i > posActu)
		{
			while (posActu < i)
			{
				int t = actu[posActu + 1];
				actu[posActu + 1] = actu[posActu];
				actu[posActu] = t;
				posActu++;
			}
		}
	}
	rep = min(rep , total);
}

