int main(void){
    cin.tie(0);
    ios::sync_with_stdio(false);
    cout<<fixed<<setprecision(20);
    cin >> N;
    vector<int> A(2*N),B(N);
    int  ans = inf;
    rep(i,N)cin >> A[i];
    rep(i,N){
        cin >> B[i];
        A[N+i] = B[i];
    }
    //上の段の偶数番目と
    //下の段の奇数番目が同じペア
    vector<int> v;
    rep(i,N){
        if(i%2==0)v.push_back(i);
        else v.push_back(i+N);
    }
    vector<int> moto = v;
    sort(ALL(v));
    do {
        //ここでvの順番が決まるので
        //vが偶数番目だったらそのままA[v[i]]を採用して
        //vが奇数番目だったら
        //N未満だったらv[i]+Nを出して
        //N以上だったらv[i]を出す
        vector<int> t;
        for(int i=0;i<N;i++){
            if(i%2==0){
                t.push_back(A[v[i]]);
            }else{
                if(v[i]<N)t.push_back(A[v[i]+N]);
                else t.push_back(A[v[i]-N]);
            }
        }
        if(check(t)){
            //元の数列からの操作回数を計算する
            //042から402にするのにかかる回数
            vector<int> now = v;
            int cnt = 0;
            while(now != moto){
                for(int i=0;i<N;i++){
                    if(moto[i]!=now[i]){
                        for(int j=i;j<N;j++){
                            if(now[j]==moto[i]){
                                swap(now[j],now[j-1]);
                                cnt++;
                                break;
                            }
                        }
                    }
                }
            }
            ans = min(ans,cnt);
        }
    } while (std::next_permutation(v.begin(), v.end()));

    if(ans == inf)cout << -1 << endl;
    else cout << ans << endl;
}

