using namespace std;

const int INF = 100100100;
const int MAXN = 20;
int N;
int first[MAXN];
int second[MAXN];
int used[MAXN];
int ans;

void dfs(int val, vector <int>& idx) {
	if (idx.size() == N){
		int cnt = 0;
		set<int> s;
		for (int ii = 0; ii < N; ++ii){
			auto itr = s.lower_bound(idx[ii]);
			int dif = distance(s.begin(), itr);
			cnt += ii - dif;
			s.insert(idx[ii]);
		}
		ans = min(ans, cnt);
		return;
	}

	int size = idx.size();
	for (int ii = 0; ii < N; ++ii){
		if (used[ii] == 1) continue;
		int nval = (size % 2 == 0) ? first[ii] : second[ii];
		if (nval < val) continue;
		idx.push_back(ii);
		used[ii] = 1;
		dfs(nval, idx);
		idx.pop_back();
		used[ii] = 0;
	}
}


