    if (end == n / 2LL) {
        bool idxflags[20] = {};
        V<t2> ais, bis;
        rep (i, end) {
            idxflags[idxs[i]] = true;
            bis.pb(t2(blist[idxs[i]], idxs[i]));
        }
        rep (i, n) {
            if (idxflags[i]) continue;
            ais.pb(t2(alist[i], i));
        }

        sort(ais);
        sort(bis);

        debug_printf("---- ais\n");
        debug_print(ais);
