        debug_print(bis);

        ll prev = -1e18;
        V<ll> resultidxs;
        rep (i, n) {
            ll val;
            ll idx;
            if (i & 1LL) {
                val = get<0>(bis[i/2]);
                idx = get<1>(bis[i/2]);
            }
            else {
                val = get<0>(ais[i/2]);
                idx = get<1>(ais[i/2]);
            }
            if (prev > val) return 1e18;
            prev = val;
            resultidxs.pb(idx);
        }

        ll total = 0;
        rep (i, n) srep (j, i+1, n) if (resultidxs[i] > resultidxs[j]) total++;
        debug_printf("---- total=%lld\n", total);
        return total;
    }

    ll si = 0;
    if (end) si = idxs[end-1] + 1;

    ll ret = 1e18;

    srep (i, si, n) {
        idxs[end] = i;
        ret = min(ret, dfs(alist, blist, n, idxs, end+1));
    }

    return ret;
}

