typedef long long int64;
const int INF = 1e9;

int inversion(const vector<int> V, int64 mask) {
    int N = V.size();
    int res = 0, cnt = 0;
    for(int i = 0; i < N; ++i) {
        if(mask & (1 << i)) ++cnt;
        int n = 0;
        for(int j = i + 1; j < N; ++j) {
            if(V[i] > V[j]) {
                ++n, ++res;
            }
        }
        if(n == 0 && !(mask & (1 << i))) return INF + 1;
    }
    if((N - cnt) % 2) {
        if((N - cnt) / 2 != cnt) return INF;
    }
    if(res == 1 && N - cnt != 2) return INF + 2;
    if(res == 2 && N - cnt != 4) return INF;
    if(res * 2 != (N - cnt)) return INF;
    return res;
}

int main() {
    int N; cin >> N;
    vector<vector<int>> A(2, vector<int>(N));
    for(int i = 0; i < N; ++i) cin >> A[0][i];
    for(int i = 0; i < N; ++i) cin >> A[1][i];
    auto rec = [&](auto &&rec, int64 mask, int n) -> int {
        if(n == N) {
            vector<int> V;
            for(int i = 0; i < N; ++i) {
                if(mask & (1 << i)) {
                    V.push_back(A[0][i]);
                } else {
                    V.push_back(A[1][i]);
                }
            }
            int res = inversion(V, mask);
            return res;
        }
        return min(rec(rec, mask | (1 << n), n + 1), rec(rec, mask, n + 1));
    };
    int ans = rec(rec, 0LL, 0);
    if(ans >= INF) ans = -1;
    cout << ans << '\n';
    return 0;
}

