ll tr(vector<int> v){
  ll res = 0;
  rep(i, sz(v)){
    FOR(j, i + 1, sz(v)){
      if(v[i] > v[j])++res;
    }
  }
  return res;
}

int main(int argc, char const* argv[])
{
  int n; cin >> n;
  vector<int> a(n), b(n); cin >> a >> b;
  ll res = linf;
  rep(i, bit(n)){
    vector<P> odd, even;
    rep(j, n){
      int c = ((i >> j) & 1) + (j & 1);
      vector<P> &C = ((c & 1) ? odd: even);
      if((i >> j) & 1)C.pb(b[j], j);
      else C.pb(a[j], j);
    }
    if(!(sz(even) == sz(odd) || sz(even) == sz(odd) + 1))continue;
    sort(whole(even));
    sort(whole(odd));
    vector<int> v;
    vector<int> vv;
    rep(j, sz(even)){
      v.pb(even[j].second);
      if(j < sz(odd))v.pb(odd[j].second);
      vv.pb(even[j].first);
      if(j < sz(odd))vv.pb(odd[j].first);
    }
    bool ok = true;
    rep(j, n - 1){
      if(vv[j] > vv[j+1]){
        ok = false;
        break;
      }
    }
    if(!ok)continue;
    // cerr << bitset<5>(i) << "|" << odd << "|" << even << "|" << v << "|" << tr(v) << endl;
    res = min(res, tr(v));
  }
  cout << (res == linf ? -1: res) << endl;
  return 0;
}

