void solver::run(){
    if(!input()) return;
    int mx = 1 << N;
    auto dp = VEC(mx,
            SegmentTree<int>(51,
                    [](const int& a,const int& b){ return min(a, b);},
                    INF));
    dp[0].update(0, 0);
    for (int i = 0; i < mx; ++i) {
        int b = popcount(i);
        for (int j = 0; j < N; ++j) {
            int bj = 1 << j;
            if(i & bj) continue;
            int x = X[(b+j)&1][j];
            int c = dp[i].query(0, x+1) + max(0, j-b);
            dp[i|bj].set(x, c);
        } // end j
    } // end i
    int ans = dp.back().query(0, 51);
    if(ans == INF) ans = -1;
    os << ans << endl;
}

