    int odd_blue = 0;
    int even_red = 0;
    int even_blue = 0;
    vector<int> v;
    for(int i = 0;i < N;i++){
        if(i % 2 == 0){
            if(mass[i]){
                odd_red++;
            }else{
                odd_blue++;
            }
        }else{
            if(mass[i]){
                even_red++;
            }else{
                even_blue++;
            }
        }    
        if(mass[i]){
            v.push_back(A[i]);
        }else{
            v.push_back(B[i]);
        }
    }
    if(odd_blue != even_blue){
        return 1e9;
    }

    sort(v.begin(), v.end());

    vector<bool> flag(N, false);
    int _ans = 0;
    for(int i = 0;i < N;i++){
        for(int j = 0;j < N;j++){
            if(flag[j])continue;
            if((i % 2 == j % 2) == mass[i]){
                if(mass[i]){
                    if(A[i] == v[j]){
                        flag[j] = true;
                        _ans += abs(j - i);
                      //  cout<<i<<" "<<j<<endl;
                    }
                }else{
                    if(B[i] == v[j]){
                        flag[j] = true;
                        _ans += abs(j - i);
                        //cout<<i<<" "<<j<<endl;
                    }
                }
            }
        }
    }
    for(int i = 0;i < N;i++)if(flag[i] == false)return 1e9;
    //cout<<_ans<<endl;
    return _ans/2;
}

