int cnt_bit(int x){
	int ret = 0;
	while(x > 0){
		ret += x&1;
		x/=2;
	}
	return ret;
}

bool cek_bit(int x, int mask){
	return (1<<x) & mask;
}

int tog_bit(int x, int mask){
	return (1<<x) ^ mask;
}

bool cek(int x){
	int bef = -1;
	for(int i=0;i<n;i++){
		int idd;
		if(cek_bit(i,x)){
			idd = 1;
		} else {
			idd = 0;
		}
		if(li[idd][i] < bef) return false;
		bef = li[idd][i];
	}
	return true;
}

int get_ans(int mask){
	int ret = 0;
	for(int i=0;i<n-1;i++){
		if(cek_bit(i,mask)){
			ret++;
			mask = tog_bit(i+1,mask);
		}
	}
	return ret;
}

ll memo[(1<<18)][52];

ll dp(int id, int mask, int last){
	if(mask == (1<<n)-1) return 0;
	ll &ret = memo[mask][last];
	if(ret!=-1) return ret;
	ret = INF;
	for(int i=0;i<n;i++){
		if(cek_bit(i,mask)) continue;
		int pake = -1;
		if(abs(i-id)&1){
			pake = li[1][i];
		} else {
			pake = li[0][i];
		}
		if(pake >= last){
			ret = min(ret,dp(id+1,tog_bit(i,mask),pake) + (ll)abs(i-id));
		}
	}
	return ret;
}


