    REP(i, N) { cin >> A.at(i); }
    REP(i, N) { cin >> B.at(i); }

    int ans = INF;
    int bit = 0;
    while (bit < 1 << N) {
        vector<pair<int, int>> use(N);
        vector<int> even, odd;
        int mask = 1;
        int sum = 0;
        REP(i, N) {
            if (mask & bit) { // ビットが立てば裏
                use[i] = make_pair(B[i], i);
                if (i % 2 == 0) {
                    odd.push_back(B[i]);
                } else {
                    even.push_back(B[i]);
                }
            } else {
                use[i] = make_pair(A[i], i);
                if (i % 2 == 0) {
                    even.push_back(A[i]);
                } else {
                    odd.push_back(A[i]);
                }
            }
            mask = mask << 1;
        }

        sort(ALL(even));
        sort(ALL(odd));

