    for(int i = 0;i < N;i++){
        for(int j = 0;j < N;j++){
            if(flag[j]){
                continue;
            }
            if((i % 2 == j % 2) == mass[i]){
                if(mass[i]){
                    if(A[i] == v[j]){
                        flag[j] = true;
                        _ans += abs(j - i) + Seg.getsum(i, j);
                        Seg.add(j, j, 1);
