template<class T> bool chmin(T &a, const T &b) { if (b < a) { a = b; return true; } return false; }

const int INF = sizeof(int) == sizeof(long long) ? 0x3f3f3f3f3f3f3f3fLL : 0x3f3f3f3f;
const int MOD =  (int)1e9 + 7;
const double EPS = 1e-9;

int N;
int X[20], Y[20];
int B[20];
vector<vector<int>> vs;

void func(int idx, int cnt)
{
	if (N - idx + cnt < N / 2)return;
	if (idx == N)
	{
		vector<int> v;
		rep(i, 0, N)
		{
			v.push_back(B[i]);
		}
		vs.push_back(v);
	}
	else
	{
		if (N - cnt - cnt > 1)
		{
			B[idx] = 1;
			func(idx + 1, cnt + 1);
		}
		B[idx] = 0;
		func(idx + 1, cnt);
	}
}

signed main()
{
	cin.tie(0);
	ios::sync_with_stdio(false);

	cin >> N;
	rep(i, 0, N)
	{
		cin >> X[i];
	}
	rep(i, 0, N)
	{
		cin >> Y[i];
	}

	if (N == 1)
	{
		cout << 0 << endl;
		return 0;
	}

	func(0, 0);

	int ans = INF;

	for (const auto& v : vs)
	{
		vector<pii> odd, eve;
		rep(i, 0, N)
		{
			if (v[i] == 1)
			{
				if (i % 2 == 0)
				{
					odd.push_back(mp(Y[i], i));
				}
				else
				{
					odd.push_back(mp(X[i], i));
				}
			}
			else
			{
				if (i % 2 == 0)
				{
					eve.push_back(mp(X[i], i));
				}
				else
				{
					eve.push_back(mp(Y[i], i));
				}
			}
		}
		sort(all(odd));
		sort(all(eve));

		bool ok = true;
		rep(i, 0, N - 1)
		{
			if (i % 2 == 0)
			{
				if (eve[i / 2].first > odd[(i + 1) / 2].first)
				{
					ok = false;
				}
			}
			else
			{
				if (odd[i / 2].first > eve[(i + 1) / 2].first)
				{
					ok = false;
				}
			}
		}
		if (!ok)continue;
		int NP[20];
		rep(i, 0, SZ(eve))
		{
			NP[2 * i] = eve[i].second;
		}
		rep(i, 0, SZ(odd))
		{
			NP[2 * i + 1] = odd[i].second;
		}
		int res = 0;
		vector<int> tv;
		vector<int> ttv;
		rep(i, 0, N)
		{
			tv.push_back(i);
			ttv.push_back(i);
		}
		rep(i, 0, N)
		{
			while (ttv[i] != NP[i])
			{
				swap(ttv[tv[NP[i]]], ttv[tv[NP[i]] - 1]);
				if (tv[NP[i]] < i)
				{
					tv[NP[i]]++;
					tv[NP[i] - 1]--;
				}
				else
				{
					tv[NP[i]]--;
					tv[NP[i] - 1]++;
				}

				res++;
			}
		}
		chmin(ans, res);
	}

	if (ans == INF)
	{
		cout << -1 << endl;
	}
	else
	{
		cout << ans << endl;
	}

	return 0;
}

