                if(p[j].second > p[k].second) {
                    tmp++;
                }
            }
        }

        for(int j = 0; j < N; j++){
            if(i&(1<<j)){
                if((j+1)%2 == 0) odd[C[j]].push_back(j);
                else even[C[j]].push_back(j);
            }else{
                if((j+1)%2 == 1) odd[C[j]].push_back(j);
                else even[C[j]].push_back(j);
            }
        }

        bool ok = true;
        int cur = 0;
        int pos = 0;
        for(int j = 1; j <= 50; j++){
            vector<int> buf;
            if(pos%2 == 0){
                if(odd[j].size() == even[j].size() || odd[j].size() == even[j].size()+1){
                    int s = even[j].size();
                    for(int k = 0; k < s; k++){
                        buf.push_back(odd[j][k]);
                        buf.push_back(even[j][k]);
                    }
                    if(odd[j].size() == even[j].size()+1) buf.push_back(odd[j][s]);
                }else{
                    ok = false;
                }
            }else{
                if(odd[j].size() == even[j].size() || odd[j].size()+1 == even[j].size()){
                    int s = odd[j].size();
                    for(int k = 0; k < s; k++){
                        buf.push_back(even[j][k]);
                        buf.push_back(odd[j][k]);
                    }
                    if(odd[j].size()+1 == even[j].size()) buf.push_back(even[j][s]);
                }else{
                    ok = false;
                }
            }
            pos += (odd[j].size() + even[j].size());
            if(ok){
                for(int k = 0; k < buf.size(); k++){
                    for(int l = k+1; l < buf.size(); l++){
                        if(buf[k] > buf[l]) cur++;
                    }
                }
            }
        }
        tmp += cur;
        if(ok) {
            find = true;
            ans = min(ans, tmp);
        }
    }
    if(!find){
        cout << -1 << endl;
