const int N = 18;
const int L = 50 + 1;
const int INF = (int) 1e9;
int n;
int a[N];
int b[N];
int dp[1 << N][L];

void make(int mask)
{
        for (int x = 1; x < L; x++)
                dp[mask][x] = min(dp[mask][x], dp[mask][x - 1]);
}

int main()
{
        ios_base::sync_with_stdio(0); cin.tie(0); cout.tie(0);

        cin >> n;
        for (int i = 0; i < n; i++)
                cin >> a[i];
        for (int i = 0; i < n; i++)
                cin >> b[i];

        for (int mask = 0; mask < (1 << n); mask++)
                for (int x = 0; x < L; x++)
                        dp[mask][x] = INF;
        dp[0][0] = 0;
        for (int mask = 0; mask + 1 < (1 << n); mask++)
        {
                make(mask);
                int pos = 0;
                for (int i = 0; (1 << i) <= mask; i++)
                        if (mask & (1 << i))
                                pos++;

                for (int i = 0; i < n; i++)
                        if ((mask & (1 << i)) == 0)
                        {
                                int d = abs(i - pos), nx;

                                if (d % 2 == 0)
                                        nx = a[i];
                                else
                                        nx = b[i];

                                for (int x = 0; x <= nx; x++)
                                        dp[mask + (1 << i)][nx] = min(dp[mask + (1 << i)][nx], d + dp[mask][x]);
                        }
        }
        make((1 << n) - 1);
        int sol = dp[(1 << n) - 1][L - 1];
        if (sol == INF)
                cout << "-1\n";
        else
                cout << sol / 2 << "\n";
}

