#define rep(i, n) for(int i=0;i<(n);++i)
typedef pair<int, int> pii;
const int INF = 1l << 60;

int N;
int A[20], B[20];

signed main() {
    cin >> N;
    if(N%2==0)return -1;
    bool noop = true;//既にソート済み?
    rep(i, N) {
        cin >> A[i];
        if (i && A[i] < A[i - 1])noop = false;
    }
    if (noop) {
        cout << 0 << endl;
        return 0;
    }
    rep(i, N) {
        cin >> B[i];
    }
    bool blue[20];
    int ans = INF;
    rep(i, (1 << N)) {
        int cnt = 0;
        rep(j, N) {
            if ((i >> j) & 1) {
                cnt++;
                blue[j] = true;
            } else {
                blue[j] = false;
            }
        }
        if (cnt % 2 == 1)continue;//青は偶数個
        //cout << "a" << endl;
        vector<int> val(N);
        rep(j, N) {
            val[j] = blue[j] ? B[j] : A[j];
        }
        vector<int> A, B;
        vector<int> Aval, Bval;

        rep(j, N) {
            if ((j % 2 == 0 && !blue[j]) || (j % 2 == 1 && blue[j])) {
                A.push_back(j);
                Aval.push_back(val[j]);
            } else {
                B.push_back(j);
                Bval.push_back(val[j]);
            }
        }
        if (!(A.size() == B.size() || A.size() == B.size() + 1))continue;
        //cout << "b" << endl;
        int res = 0;
        vector<int> cur(N);
        rep(j, N) {
            cur[j] = j;
        }
        sort(Aval.begin(), Aval.end());
        sort(Bval.begin(), Bval.end());
        rep(j, B.size()) {
            if (Aval[j] > Bval[j])goto next;
            if (A.size() >= j + 1 + 1) {
                if (Aval[j + 1] < Bval[j])goto next;
            }
        }
        //cout << "c" << endl;
        rep(j, N) {
            //cout << j << endl;
            if (j % 2 == 0) {
                //Aval[j/2]を探す
                rep(k, A.size()) {
                    if (val[A[k]] == Aval[j / 2]) {
                        //これをj番目に動かす
                        res += cur[A[k]] - j;
                        //cerr << "A" << A[k] << " " << cur[A[k]] - j << endl;
                        val[A[k]] = -1;
                        //既に前方に移動させたもの以外は前後関係は変わっていない
                        rep(l, A[k]) {
                            cur[l]++;
                        }
                    }
                }
            } else {
                //Bval[j/2]を探す
                rep(k, B.size()) {
                    if (val[B[k]] == Bval[j / 2]) {
                        res += cur[B[k]] - j;
                        //cerr << "B" << B[k] << " " << cur[B[k]] - j << endl;
                        val[B[k]] = -1;
                        rep(l, B[k]) {
                            cur[l]++;
                        }
                    }
                }
            }
        }
        ans = min(ans, res);
        //cout << "!-1" << endl;
        next:;
    }
    if (ans == INF) {
        cout << -1 << endl;
        return 0;
    }
    cout << ans << endl;
    return 0;
}

#include<bits/stdc++.h>

using namespace std;

const int N = 1 << 18;
const int INF = 1e6;

int n;
int a[N + 5], b[N + 5];
int dp[N + 5][20];
int val[N + 5];

int solve(int mask, int last){
	if(mask == (1 << n) - 1) return 0;
	int& ret = dp[mask][last];
	if(ret != -1) return ret;
	ret = INF;
	for(int i=0; i<n; i++){
		if(mask & (1 << i)) continue;
		int bef = abs(val[mask] - last+1) % 2 == 0 ? a[last] : b[last];
		int v = abs(val[mask] - i) % 2 == 0 ? a[i] : b[i];
		if(bef > v) continue;
//		printf("bef %d, v %d, last %d, now %d\n",bef ,v,last,i);
		ret = min(ret, solve(mask | (1 << i), i) + abs(val[mask] - i));
	}
//	printf("%d %d -> %d\n",mask,last,ret);
	return ret;
}

int main(){
	ios_base :: sync_with_stdio(0); cin.tie(0); cout.tie(0);
	for(int i=0; i<N; i++){
		int cnt = 0;
		for(int j=0; j<18; j++) if(i & (1 << j)) cnt++;
		val[i] = cnt;
	}
	cin >> n;
	for(int i=0; i<n; i++) cin >> a[i];
	for(int i=0; i<n; i++) cin >> b[i];
	memset(dp,-1,sizeof dp);
	int ans = INF;
	for(int i=0; i<n; i++){
		ans = min(ans, solve(1 << i, i) + i);
	}
	if(ans >= 1000) ans = -1;
	else ans = (ans + 1) / 2;
	cout << ans << endl;
	return 0;
}

