const int N = 18;
int n , dp[1 << N][51],A[N],B[N];

int call(int pos,int mask,int pre)
{
    if(pos == n){
        return 0;
    }
    if(dp[mask][pre] != -1)return dp[mask][pre];
    int ret = 1e9;
    vector<pair<int,int>>v1,v2;

    int got = pos;
    for(int i = 0;i < n;i++){
        if(!(mask & (1 << i))){
            if(got % 2 == 0){
                v1.push_back(mk(A[i],i));
                v2.push_back(mk(B[i],i));
            }else{
                v2.push_back(mk(A[i],i));
                v1.push_back(mk(B[i],i));
            }
        }else got++;
    }
//    cout << mask << " " << pre << " " << endl;
//    cout << "eleA: ";
//    for(int i = 0;i < v1.size();i++)cout << v1[i].first << " " << v1[i].second << "\t";
//    cout << endl;
//    cout << "eleB: ";
//    for(int i = 0;i < v2.size();i++)cout << v2[i].first << " " << v2[i].second << "\t";
//    cout << endl;
    for(int i = 0;i < v1.size();i += 2){
        int newmask = mask | (1 << v1[i].second);
        if(v1[i].first >= pre){
//            cout << "up dhuksi\n";
//            cout << "A: " << mask << " " << v1[i].first << "\n";
            ret = min(ret, i + call(pos + 1,newmask,v1[i].first));
        }
    }
    for(int i = 1;i < v2.size();i += 2){
        int newmask = mask | (1 << v2[i].second);
        if(v2[i].first >= pre){
//            cout << "down dhuksi\n";
//            cout << "B: " << mask << " " << v2[i].first << "\n";
            ret = min(ret, i + call(pos + 1,newmask,v2[i].first));
        }
    }
//    cout << mask << " " << pre << " " << ret << "\n";
    return dp[mask][pre] = ret;
}
