    }
    for (ll i=0;i<N;i++){
      scanf("%lld",&B[i]);
    }
    for (ll i=1;i<N;i+=2){
      swap(A[i],B[i]);
    }

    v_ll S(N/2,0);
    for (ll i=0;i<N/2;i++){
      S[i]=i;
    }
    bool flag=true;
    ans=-1;
    while (flag){
      v_ll T1;
      v_ll T2;
      ll k=0;
      bool good=true;
      for (ll i=0;i<N;i++){
        if (k<N/2&&i==S[k]){
          k++;
          T2.push_back(i);
        }else{
          T1.push_back(i);
        }
      }

      sort(T1.begin(),T1.end(),[&](const ll &x,const ll &y){
        if (A[x]<A[y])return true;
        if (A[x]==A[y] && x<y)return true;
        return false;
      });
      sort(T2.begin(),T2.end(),[&](const ll &x,const ll &y){
        if (B[x]<B[y])return true;
        if (B[x]==B[y] && x<y)return true;
        return false;
      });


      for (ll i=0;i<T2.size();i++){
        if (B[T2[i]]<A[T1[i]]) good = false;
      }
      for (ll i=1;i<T1.size();i++){
        if (A[T1[i]]<B[T2[i-1]]) good = false;
      }
      v_ll U;
      if (good){
        for (ll i=0;i<T1.size();i++){
          U.push_back(T1[i]);
          if (i<T2.size()){
            U.push_back(T2[i]);
          }
        }
        BIT bit(U.size()+1);
        ll a=0;
        for(ll i=0;i<U.size();i++) {
          a+=bit.sum(U.size())-bit.sum(U[i]);
          bit.add(U[i],1);
        }
        if (ans<0||a<ans) ans=a;
      }
      ll i=0;
      for (i=N/2-1;i>=0;i--){
        S[i]++;
        if (S[i]<=N-(N/2)+i){i++;break;}
        if (i==0) flag=false;
      }
      for (;i<N/2;i++){
        if (i>0)S[i]=S[i-1]+1;
      }
    }
    cout << ans << endl;
}

