#include<bits/stdc++.h>
#define fo(i,a,b) for(int i=(a);i<=(b);++i)
#define rv(i,a,b) for(int i=(a);i>=(b);--i)
#define P pair<int,int>
#define all(x) x.begin(),x.end()
#define SZ(x) ((int)x.size())
using namespace std;
typedef long long LL;
const int M = 1200000;
const int inf = 0x3f3f3f3f;
int n,m,k;
int a[20][2];
int cal(int t[]){
	int ret=0;
	fo(i,0,n-1){
		fo(j,0,i-1){
			if(t[j]>t[i])
				++ret;
		}
	}
	return ret;
}
int main() {
	cin>>n;
	int ans=inf;
	fo(i,0,n-1)
		cin>>a[i][0];
	fo(i,0,n-1)
		cin>>a[i][1];
	int al=(1<<n)-1;
	fo(i,0,al){
		vector<P> v[2];
		fo(j,0,n-1){
			int to=((i>>j)&1);
			v[to^(j&1)].push_back({a[j][to],j});
		}
		if(SZ(v[1])!=n/2 || SZ(v[0])!=(n+1)/2) continue;
		if(!v[0].empty())
			sort(all(v[0]));
		if(!v[1].empty())
			sort(all(v[1]));
		int tar[20];
		int pre=-inf;
		bool bk=0;
		fo(j,0,n-1){
			P cur=v[j&1][j>>1];
			if(cur.first<pre) {
				bk=1;
				break;
			}
			pre=cur.first;
			tar[j]=cur.second;
		}
		if(bk) continue;
		ans=min(ans,cal(tar));
	}
	if(ans==inf) cout<<-1<<endl;
	else cout<<ans<<endl;
	return 0;
}

