			return -1;
		}
		// cerr << "find: " << find << endl;
		ans += find - i;
		flag[find] = -100;
		for (int j = find; j > i; j --) {
			swap (x[j], x[j - 1]);
			flag[j] *= -1;
			flag[j - 1] *= -1;
			swap (flag[j], flag[j - 1]);
		}
	}
