template<class T>
struct conbination_generator{
    std::vector<T> vec;
    unsigned int n;
    std::vector<unsigned int> idxs;
    bool isFinished;

    conbination_generator( const std::vector<T>& vec, unsigned int n )
    : vec(vec), n(n), idxs(n), isFinished(false)
    { 
        for( unsigned int i = 0; i < n; i++){
            idxs[i] = i;
        }
    }

    std::vector<T> get_combination(void) const {
        std::vector<T> ret(n);
        for( unsigned int i = 0; i < n; i++){
            ret[i] = vec[idxs[i]];
        }
        return ret;
    }
    std::vector<T> operator* (void) const {
        return get_combination();
    }

    operator bool() const {
        return ! isFinished;
    }

    conbination_generator<T>& operator++ (void){
        unsigned int N = vec.size();
        unsigned int i = 1; // 1 -> n //

        while(true) {
            idxs[n-i]++;
            for( unsigned int j = 1; j < i; j++ ){
                idxs[n-i+j] = idxs[n-i] + j;
            }
            if( idxs[n-i] > N-i ){
                i++;
                if( i > n ){
                    isFinished = true;
                    return *this;
                }
            } else {
                break;
            }
        }
        return *this;
    }

    conbination_generator<T>& operator++ (int){
        return ++(*this);
    }
};

