ll n;

//セグ木
ll dat[2560000], sz;

void init(ll n) {
	sz = 1;
	while (sz < n)sz *= 2;
	REP(i, sz * 2 - 1) dat[i] = 0;
}

void update(ll k, ll a) { //場所(0-indexed), 値
	k += sz - 1;
	dat[k] = a;
	while (k > 0) {
		k = (k - 1) / 2;
		dat[k] =dat[k * 2 + 1] + dat[k * 2 + 2]; //更新
	}
}

ll query(ll a, ll b, ll k, ll l, ll r) { //[a, b) 呼ぶとき (a, b, 0, 0, sz)
	if (r <= a or b <= l)return 0;
	if (a <= l and r <= b)return dat[k];
	ll v1 = query(a, b, k * 2 + 1, l, (l + r) / 2);
	ll v2 = query(a, b, k * 2 + 2, (l + r) / 2, r);
	return v1 + v2; //戻り値
}

ll ans = INF;
int main() {
	cin >> n;
	vector<ll> x(n), y(n);
	REP(i, n)cin >> x[i];
	REP(i, n)cin >> y[i];
	REP(i, 1ll << n) {
		ll c1 = 0, c2 = 0;
		bool ok = true;
		REP(j, n) {
			if (i & (1ll << j)) {
				if (j % 2 == 0)c1++;
				else c2++;
			}
		}
		if (c1 != c2)continue;
		vector<P> a, b, c;
		REP(j, n) {
			if ((i & (1ll << j))) {
				if (j % 2 == 0) b.push_back(P(y[j], j));
				else a.push_back(P(y[j], j));
			}
			else {
				if (j % 2 == 0) a.push_back(P(x[j], j));
				else b.push_back(P(x[j], j));
			}
		}
		sort(ALL(a));
		sort(ALL(b));
		REP(j, n) {
			if (j % 2 == 0)c.push_back(a[j / 2]);
			else c.push_back(b[j / 2]);
		}
		REP(j, n - 1) {
			if (c[j].first > c[j + 1].first)ok = false;
		}
		if (!ok)continue;
		init(60);
		ll now = 0;
		REP(j, n) {
			now += query(c[j].second, 60, 0, 0, sz);
			update(c[j].second, 1);
		}
		ans = min(ans, now);
	}
	if (ans == INF)cout << -1 << endl;
	else cout << ans << endl;
}

#include <bits/stdc++.h>

const int N = 19;
const int M = 60;

int dp[1 << N][M];
int a[N], b[N];

void update(int &a, int b){
    if (b == -1){
        return;
    }
    if (a == -1 || a > b){
        a = b;
    }
}

int main(){
    memset(dp, -1, sizeof(dp));
    dp[0][0] = 0;
    int n;
    scanf("%d", &n);
    for (int i = 0; i < n; ++ i){
        scanf("%d", &a[i]);
    }
    for (int i = 0; i < n; ++ i){
        scanf("%d", &b[i]);
    }
    for (int i = 1; i < 1 << n; ++ i){
        for (int j = 0; j < n; ++ j){
            if (i >> j & 1){
                int pre = i ^ 1 << j;
                int pos = __builtin_popcount(i) - 1;
                int value = (pos - j) & 1 ? b[j] : a[j];
                int inv = 0;
                for (int k = 0; k < n; ++ k){
                    if (i >> k & 1){
                        inv += k > j;
                    }
                }
                for (int k = 0; k <= value; ++ k){
                    if (dp[pre][k] == -1){
                        continue;
                    }
                    update(dp[i][value], dp[pre][k] + inv);
                }
            }
        }
    }
    int ans = -1;
    for (int i = 0; i < M; ++ i){
        update(ans, dp[(1 << n) - 1][i]);
    }
    printf("%d\n", ans);
    return 0;
}

