  constexpr decltype(auto) operator()(Args &&... args) const {
    return F::operator()(*this, std::forward<Args>(args)...);
  }
};

template <typename F>
static inline constexpr decltype(auto) make_fix_point(F &&f){
  return FixPoint<F>(std::forward<F>(f));
}

template <typename T>
inline auto make_vector(int N, int M, const T &value){
  return std::vector<std::vector<T>>(N, std::vector<T>(M, value));
}


int main(){
  int N;
  while(cin >> N){
    vector<int> A(N), B(N); cin >> A >> B;

    vector<vector<int>> d(N);

    REP(i,N){
      d[i].resize(N);

      REP(j,N){
        if((i-j) % 2 == 0){
          d[i][j] = A[i];
        }else{
          d[i][j] = B[i];
        }
      }
    }

    auto dp = make_vector(18, 1<<18, INT_MAX);
    auto check = make_vector(18, 1<<18, false);

    auto f =
      make_fix_point([&](auto &&f, int i, int j) -> LLI{
                       if(check[i][j]) return dp[i][j];
                       check[i][j] = true;

                       if(not (j & bit(i))) return dp[i][j];

                       int p = __builtin_popcount(j);

                       if(p == 1) return dp[i][j] = 0;

                       int t = __builtin_popcount(j & ~(bit(i+1) - 1));

                       REP(k,N){
                         if(not (j & bit(k))) continue;

                         auto r = f(k, j ^ bit(i));

                         if(d[k][p-2] <= d[i][p-1]){
                           chmin(dp[i][j], r + t);
                         }
                       }

                       return dp[i][j];
                     });


    LLI ans = INT_MAX;

    REP(i,N){
      chmin(ans, f(i, bit(N)-1));
    }

    if(ans == INT_MAX){
      cout << -1 << endl;
    }else{
      cout << ans << endl;
    }
  }

  return 0;
}

