int bubbleSort(vector <pair <int, int > >& c, int ptn)
{
	int num = 0;

	const int N = SZ(c);


	for (int i=0;i<N - 1;i++)
	{
		for (int k = N-1; k >= i+1; --k)
		{
			if (c[k].first < c[k - 1].first)
			{
				swap(c[k], c[k - 1]);
				num++;
			}
		}
	}

	for (int k = 0; k < N - 1; ++k)
	{
		bool checkK = (abs(c[k].second - k) % 2 == 0) ^ IsBit(ptn, k);
		bool checkK1 = (abs(c[k+1].second - (k+1)) % 2 == 0) ^ IsBit(ptn, k+1);
		if (checkK && checkK1 && c[k].first == c[k + 1].first)
		{
			swap(c[k], c[k + 1]);
			num++;
		}
	}


	return num;
}





