            int idx = distance(v.begin(), min_element(next(v.begin(), j), v.end()));
            while(idx != j){
                ++cnt;
                swap(v[idx], v[idx - 1]);
                if(bs[idx] == bs[idx - 1]){
                    bs.flip(idx);
                    bs.flip(idx - 1);
                }
                --idx;
            }
        }

        for(int j = 0; j < n - 1; ++j)
            if(bs[j] & bs[j + 1]){
                bs.flip(j);
                bs.flip(j + 1);
                swap(v[j], v[j + 1]);
                ++cnt;
            }

        if(v != v_b){
            continue;
        }
        chmin(ans, cnt + int(bs.count() / 2));
    }
    cout << (ans == MOD ? -1 : ans) << endl;
}


