    if( n == 1 ) {
        cout << "0\n";
        exit(0);
    }

    int m = 0;
    for(auto& i : mp) {
        i.second = m++;
    }
    for(int i = 0; i < n; i++) {
        a[i] = mp[a[i]];
        b[i] = mp[b[i]];
    }
    memset(dp, -1, sizeof dp);
    int res = inf;
    if( a[1] >= a[0] ) {
        res = min(res, dfs( 2, a[0], a[1], b[1] ));
    }
    if( b[1] <= b[0] ) {
        memset(dp, -1, sizeof dp);
        res = min(res, 1 + dfs( 2, b[1], b[0], a[0] ));
    }
    if( res >= inf ) res = -1;
