void merge(std::vector<ll>& a,int& ans,int l, int q,int r){//転倒数を求める(元配列はsortされるので注意)
    std::vector<ll> d,dd;
    rrep(i,l,q+1){
        d.pb(a[i]);
    }
    rrep(i,q+1,r+1){
        dd.pb(a[i]);
    }
    d.pb(INF64);
    dd.pb(INF64);
    int p=0,pp=0;
    int i=0,j=0;
    int dum=d.size()-1;
    rrep(ii,l,r+1){
        if(d[i]>dd[j]){
            ans+=dum-i;
            a[ii]=dd[j];
            j++;
        }
        else{
            a[ii]=d[i];
            i++;
        }
    }
}
void merge_sort(std::vector<ll>& a,int& ans,int l,int r){
    int q=(r+l)/2;
    if(l<r){
        merge_sort(a,ans,l,q);
        merge_sort(a,ans,q+1,r);
        merge(a,ans,l,q,r);
        //out();
    }
    return;
}
int inversion(std::vector<ll> a){
    int ans=0;
    merge_sort(a,ans,0,a.size());
    if(a.size()%2==0)return ans-a.size();
    else return ans;
}




