class Card {
public:
	int val;
	int n;
	Card(int _val, int _n): n(_n), val(_val) {}
};
bool cmpc(const Card &a, const Card &b) {
	return a.val < b.val;
}
vector<int> getS(int S) {
	vector<int> res;
	vector<int> resa;
	res.clear();
	vector<Card> odd, even;
	for (int i = 0; i < n; ++i) {
		if ((i % 2) ^ ((S >> i) & 1)) {
			odd.push_back(Card((((S >> i) & 1) ? B[i] : A[i]), i));
		}
		else {
			even.push_back(Card((((S >> i) & 1) ? B[i] : A[i]), i));
		}
	}
	// cout << "S = " << S << endl;
	// cout << odd.size() << ' ' << even.size() << endl;
	int oddn = n / 2, evenn = (n + 1) / 2;
	if (oddn != odd.size() || evenn != even.size()) {
		return res;
	}
	sort(odd.begin(), odd.end(), cmpc);
	sort(even.begin(), even.end(), cmpc);
	for (int i = 0; i < n; ++i) {
		if (i % 2) {
			res.push_back(odd[i / 2].n);
			resa.push_back(odd[i / 2].val);
		}
		else {
			res.push_back(even[i / 2].n);
			resa.push_back(even[i / 2].val);
		}
	}
	for (int i = 0; i < n - 1; ++i) {
		if (resa[i] > resa[i + 1]) {
			return vector<int>();
		}
	}
	return res;
}

void calc() {
	int res = inf;
	for (int S = 0; S < (1 << n); ++S) {
		vector<int> od = getS(S);
		if (od.size() == 0) {
			continue;
		}
		int dis = 0;
		for (int i = 0; i < n; ++i) {
			for (int j = 0; j < n; ++j) {
				if (j < i && od[j] > od[i]) {
					++dis;
				}
				if (j > i && od[j] < od[i]) {
					++dis;
				}
			}
		}
		res = min(res, dis / 2);
	}
	if (res == inf) {
		cout << (-1) << endl;
	}
	else {
		cout << res << endl;
	}
}
int main() {
	read_in();
	calc();
	return 0;
}

