template<class T> class segtree {
    int n = 1;
    vector<T> dat;
    T def;

public:
    segtree(int _n, T _def) : def(_def) {
        while (n < _n)n *= 2;
        dat.resize(2 * n, def);
    }
    segtree(vector<T> a, T _def) : def(_def) {
        int _n = a.size();
        while (n < _n)n *= 2;
        dat.resize(2 * n, def);
        FOR(i, 0, _n)dat[i + n] = a[i];
        rFOR(i, 1, n)dat[i] = fun(dat[2 * i], dat[2 * i + 1]);
    }

    //Custmize here
    //sum,min,max,etc...
    T fun(T x, T y) { return x + y; }

    //assignment,chmin,chmax,etc...
    void update(int i, T a) {
        i += n;
        dat[i] += a;
        while (i > 1) {
            i /= 2;
            dat[i] = fun(dat[2 * i], dat[2 * i + 1]);
        }
    }

    T value(int l, int r) {
        l += n, r += n;

        T ret = def;
        for (; l < r; l /= 2, r /= 2) {
            if (l & 1) {
                ret = fun(ret, dat[l]);
                l++;
            }
            if (r & 1) {
                --r;
                ret = fun(ret, dat[r]);
            }
        }

        return ret;
    }

    T operator[](int k) { return dat[k + n]; }
};


