    vector<vector<deque<int>>> h(2, vector<deque<int>>(50));
    vector<int> p(N);

    REP(i, N)
    {
      ta[i] = a[i][ind[i]];
    }

    sort(ALL(ta));

    REP(i, N)
    {
      h[i & 1][ta[i]].push_back(i);
    }

    REP(i, N)
    {
      int eoro = ((i & 1) ^ ind[i]);

      if (h[eoro][a[i][ind[i]]].empty())
      {
        return;
      }

      p[i] = h[eoro][a[i][ind[i]]].front();
      h[eoro][a[i][ind[i]]].pop_front();
    }

    int res = 0;
    REP(j, N)
    {
      REP(i, j)
      {
        if (p[j] < p[i])
        {
          ++res;
        }
      }
    }

    mn = min(mn, res);
    return;
  }

  REP(k, 2)
  {
    vector<int> temp = ind;
    temp.push_back(k);
    solve(temp, mn);
  }
}

