        cin>>a[i][1];
    }
    int all=(1<<n);
    set<pii>st[2];
    vi b(n),d(n);
    int ans=-1;
    for(int i=0;i<all;i++){
        int cnt=0,otv=0,p=0;
        for(int j=0;j<2;j++)
            st[j].clear();
        for(int j=0;j<n;j++){
            if(i&(1<<j)){
                p++;
                if(j&&(i&(1<<(j-1)))&&p%2==0)
                    otv--;
                st[1-j%2].insert({a[j][1],j});
                cnt++;
            }else{
                st[j%2].insert({a[j][0],j});
            }
        }
        if(cnt&1)
            continue;
        bool fl=true;
        for(int j=0;j<n;j++){
            int u=(j&1);
            if(!SZ(st[u])){
                fl=false;
                break;
            }
            auto it=st[u].begin();
            pii v=*it;
            b[j]=v.first;
            d[j]=v.second;
            st[u].erase(it);
        }
        if(!fl)
            continue;
        vi c=b;
        sort(ALL(c));
        if(c!=b)
            continue;
        vi e=f,g=f;
        for(int i=0;i<n;i++){
            int v=d[i];
            while(g[i]!=v){
                int k=e[v];
                int u=g[k-1];
                swap(e[u],e[v]);
                swap(g[k],g[k-1]);
                otv++;
            }
        }
        otv+=cnt/2;
        if(ans==-1||otv<ans){
            ans=otv;
        }
    }
    cout<<ans;
}

