int ans = INF;

int cntSwap(vector<P> ab) {
  int flag = 1;
  int cnt = 0;
  for (int i = 0; i < n - 1; ++i) {
    int mi = i;
    for (int j = i + 1; j < n; ++j) {
      if (ab[mi] > ab[j]) mi = j;
    }
    if (mi != i) {
      swap(ab[i], ab[mi]);
      cnt++;
    }
  }

  int prev = 1;
  for (int i = 0; i < n; ++i) {
    if (ab[i].second == prev) return INF;
    prev = ab[i].second;
  }
  return cnt;
}

void check(vector<P> ab) {
  ans = min(cntSwap(ab), ans);
  return;
}

void rec(int cur, vector<P> ab) {
  if (cur == n) {
    check(ab);
    return;
  }

  ab[cur] = a[cur];
  rec(cur + 1, ab);
  ab[cur] = b[cur];
  rec(cur + 1, ab);
}

