  if(n==a) {
    r.push_back(v);
    return;
  }
  int m;
  if(n) m=v[n-1];
  else m=-1;
  rep2(i,m+1,all-a+n+1) {
    v.push_back(i);
    dfs(a,all,v,r);
    v.pop_back();
  }
}

