        rep(j, n) if (i & (1 << j)) v[j] = 1;
        int tmp = 0;
        vector<int> cnt(n, 0);
        vector<int> c = a;
        rep(j, n) if (v[j] == 1) c[j] = b[j];
        rep(j, n)
        {
            Rep(k, j + 1, n)
            {
                if (c[j] > c[k])
                {
                    tmp++;
                    cnt[j]++;
                    cnt[k]++;
                }
            }
        }
        vector<P> num[51];
        rep(j, n)
        {
            if ((cnt[j] % 2) == v[j])
                num[c[j]].push_back({0, j});
            else
                num[c[j]].push_back({1, j});
        }
        rep(j, 51)
        {
            rep(k, num[j].size())
            {
                if (k == num[j].size() - 1)
                    continue;
                if (num[j][k].first == 1)
                {
                    if (num[j][k + 1].second == 0)
                        num[j][k + 1].second = 1;
                    else
                        num[j][k + 1].second = 0;
                    tmp++;
                    cnt[num[j][k].second]++;
                    cnt[num[j][k + 1].second]++;
                }
            }
        }
        bool f = true;
        rep(j, n) if ((cnt[j] % 2) != v[j])
            f = false;
        if (f)
            ans = min(ans, tmp);
    }
    if (ans == INF)
        ans = -1;
    cout << ans << endl;
}

