  CombinationTable(int size) : val(size + 1, vector<long long>(size + 1)) //constructor
  {
    for (int i = 0; i <= size; ++i) // note that 0 <= i <= size
    {

      for (int j = 0; j <= i; ++j)
      {

        if (j == 0 or j == i)
        {
          val[i][j] = 1LL;
        }
        else
        {
          val[i][j] = val[i - 1][j - 1] + val[i - 1][j];
        }
      }
    }
  }
};

