int N;
vector<vector<int>> a;

struct item
{
  int val;
  int pos;
  int isrev;

  bool operator<(const struct item &other) const
  {
    return val < other.val;
  }
};

void solve(vector<int> ind, int &mn)
{
  if (SIZ(ind) == N)
  {
    int res = 0;
    vector<item> vp(N);
    REP(i, N)
    {
      vp[i] = {a[i][ind[i]], i, ind[i]};
    }

    sort(ALL(vp));

    vector<bool> used(N, false);
    int id = 0;

    while (id < N)
    {
      int idmx = id;
      while (idmx < N and vp[idmx].val == vp[id].val)
      {
        ++idmx;
      }

      int id0 = id;
      for (; id < idmx; ++id)
      {
        int idiff = -1;
        for (int i1 = id0; i1 < idmx; ++i1)
        {
          if (used[vp[i1].pos] or (abs(id - vp[i1].pos) & 1) != vp[i1].isrev)
          {
            continue;
          }

          if (idiff == -1 or abs(id - vp[i1].pos) < abs(id - vp[idiff].pos))
          {
            idiff = i1;
          }
        }

        if (idiff == -1)
        {
          return;
        }

        res += abs(id - vp[idiff].pos);
        used[vp[idiff].pos] = true;
      }
    }

    res >>= 1;
    mn = min(mn, res);
    return;
  }

  REP(k, 2)
  {
    vector<int> temp = ind;
    temp.push_back(k);
    solve(temp, mn);
  }
}

