  cin>>n;
  REP(i, n){
    cin>>a[i];
  }
  REP(i, n){
    cin>>b[i];
  }
  int ans=INF;
  REP(i, 1<<n){
    vi u, v, w;
    REP(j, n){
      if(i>>j&1){
        u.push_back(a[j]);
        v.push_back(j);
        if(j&1){
          w.push_back(1);
        }
        else{
          w.push_back(0);
        }
      }
      else{
        u.push_back(b[j]);
        v.push_back(j);
        if(j&1){
          w.push_back(0);
        }
        else{
          w.push_back(1);
        }
      }
    }
    vi ord(n);
    iota(ALL(ord), 0);
    sort(ALL(ord), [&u, &v](int x, int y){
      if(u[x]==u[y]) return v[x]<v[y];
      return u[x]<u[y];
    });
    int idx=0;
    bool ok=true;
    int sum=0;
    while(idx<n){
      int tmp=idx, cnt=0;
      vi odd, evn;
      if(w[ord[idx]]){
        ++cnt;
        odd.push_back(idx);
      }
      else{
        evn.push_back(idx);
      }
      while(idx<n-1 && u[ord[idx]]==u[ord[idx+1]]){
        if(w[ord[idx+1]]){
          ++cnt;
          odd.push_back(idx+1);
        }
        else{
          evn.push_back(idx+1);
        }
        ++idx;
      }
      int m=idx-tmp+1;
      if(tmp&1){
        if(m/2!=m-cnt){
          ok=false;
          break;
        }
      }
      else{
        if(m/2!=cnt){
          ok=false;
          break;
        }
      }
      int oi=0, ei=0;
      FOR(j, tmp, idx+1){
        if(j&1){
          sum+=abs(ord[odd[oi]]-j);
          ++oi;
        }
        else{
          sum+=abs(ord[evn[ei]]-j);
          ++ei;
        }
      }
      ++idx;
    }
    if(ok){
      CHMIN(ans, sum/2);
    }
  }
  cout<<(ans==INF ? -1 : ans)<<'\n';
  return 0;
}

