       vector<int> swid(N, 0);
       int swnum = 0;
       REP(i, N) {
           FOR(j, 1, N-i) {
               if(p[j] < p[j-1]) {
                    swap(p[j], p[j-1]);
                    swid[id[j]]++;
                    swid[id[j-1]]++;
                    swap(id[j], id[j-1]);
                    swnum++;
               }
           }
       }
       bool flg = true;
       REP(i, N) {
           if(((k>>i)&1)==1 && swid[i]%2 == 1 || ((k>>i)&1)==0 && swid[i]%2 == 0) {
               flg = false;
               break;
           } 
       }
       if(flg) {
           if(swnum < ans) ans = swnum;
       }
   } 
   if(ans == 1e9) ans = -1;
   cout << ans << endl;
}

