        for(int k = 0; k <= 1; ++k)
                for(int i = 1; i <= n; ++i) cin >> a[i][k];
        for(int mask = 0; mask < (1 << n); ++mask) {
                vector<Vec> v(n + 1);
                int moves = 0, step = n;
                for(int i = 1; i <= n; ++i) v[i] = {a[i][0], a[i][1], ((mask >> (i - 1)) & 1)};
                while(step > 0 && !is_sorted(v.begin() + 1, v.end())) {
                        int mxval = 0, pos = 0;
                        for(int i = 1; i <= step; ++i)
                                if(v[i].x >= mxval && (step - pos + 1) % 2 == v[i].t)
                                        mxval = v[i].x, pos = i;
                        if(pos == 0) {
                                moves = 2e9;
                                break;
                        }
                        for(int i = pos; i < step; ++i, ++moves) {
                                swap(v[i].x, v[i].y);
                                v[i].t ^= 1;
                                swap(v[i + 1].x, v[i + 1].y);
                                v[i + 1].t ^= 1;
                                swap(v[i], v[i + 1]);
                        }
                        --step;
                }
                if(is_sorted(v.begin() + 1, v.end())) ans = min(ans, moves);
        }
