	for (int i = 0; i < 1<<n; ++i)
	{
		int bp = __builtin_popcount(i);
		for (int k = 0; k <= 2*n; ++k)
		{
			int val = (k < 2*n) ? ( (k < n) ? a[k] : b[k-n] ) : 0;

