					f[j] = (f[j] ^ cost) & 1;
					int val2 = f[j] ? b[j] : a[j];
					if (val2 >= val)
						dp[f[j]*n+j][i|1<<j] = min(dp[f[j]*n+j][i|1<<j], dp[k][i] + cost);
				}
		}
	}

	int ans = inf;
	for (int k = 0; k <= 2*n; ++k)
		ans = min(ans, dp[k][(1<<n)-1]);

