int N;
int A[60], B[60];
set<vector<pair<int, int> > > visited;
queue<pair<vector<pair<int, int> >, int> > q;
bool flag = false;
int ans;

void bfs(vector<pair<int, int> > AB_vec, int depth) {
    bool check = true;
    for (int i = 0; i < N-1; i++) {
        if (AB_vec[i].first > AB_vec[i+1].first) {
            check = false;
            break;
        }
    }
    if (check) {
        ans = depth;
        flag = true;
        return;
    }

    vector<pair<int, int> > tmp = AB_vec;
    for (int i = 0; i < N-1; i++) {
        swap(tmp[i], tmp[i+1]);
        swap(tmp[i].first, tmp[i].second);
        swap(tmp[i+1].first, tmp[i+1].second);

        auto c = visited.find(tmp); 
        if (c == visited.end()) {
            q.push({tmp, depth+1});
            visited.insert(AB_vec);
        }

        swap(tmp[i+1].first, tmp[i+1].second);
        swap(tmp[i].first, tmp[i].second);
        swap(tmp[i], tmp[i+1]);
    }
}

