void solve(long long N, std::vector<long long> A, std::vector<long long> B){
	rep(i, N) {
		if (i % 2 == 1) swap(A[i], B[i]);
	}
	vector<int> per(N);
	int res = 1e9;
	rep(i, N/2) per[i] = 1;
	reverse(all(per));
	do {
		vector<pair<int, int>> vp;
		rep(i, N) {
			if (per[i]) vp.emplace_back(B[i], i);
			else vp.emplace_back(A[i], i);
		}
		int r = 0;
		rep(i, N) {
			rreps(j, N-1, i) {
				if (vp[j].first > vp[j+1].first) {
					swap(vp[j], vp[j+1]);
					r++;
				}
			}
		}
		vector<bool> vb(N);
		rep(i, N) {
			if ((vp[i].second & 1) == per[vp[i].second]) {
				vb[i] = abs(vp[i].second - i) % 2 == 0;
			} else {
				vb[i] = abs(vp[i].second - i) % 2 == 1;
			}
		}
		// rep(i, N) cout << vb[i] << ' '; cout << endl;
		rep(i, N-1) {
			if (vb[i]) continue;
			vb[i] = true;
			int cnt = 2; i++;
			while (i < N && vb[i]) i++, cnt++;
			if (i == N || cnt % 2 == 0) {
				vb[0] = false;
				break;
			}
			r += cnt - 1;
			vb[i] = true;
		}
		rep(i, N) {
			if (!vb[i]) r = 1e9;
		}
		chmin(res, r);
	} while (next_permutation(all(per)));
	if (res >= 1e5) cout << -1 << endl;
	else cout << res << endl;
}

