        }
      }
      for (int i = 0; i + 1 < SZ(poses); i += 2) {
        ok &= (poses[i + 1] - poses[i]) % 2 == 1;
        sum += poses[i + 1] - poses[i];
      }
      if (ok) ans = min(ans, sum);  
    }
  }
  cout << (ans == 1e9  ? -1 : ans) << '\n';
}

