        for (int lst = 0; lst < n; lst++) {
            if (mask & (1 << lst)) {
                for (int who = 0; who < n; who++) {
                    if (who == lst) continue;
                    if (who > lst && (mask & (1 << who))) invs[mask][lst]++;
                    if (who < lst && !(mask & (1 << who))) invs[mask][lst]++;
                }
            }
        }
    }
    for (int i = 0; i < (1 << n); i++) {
        for (int j = 0; j < n; j++) {
            dp[i][j] = INF;
        }
    }
    for (int i = 0; i < n; i++) {
        dp[(1 << i)][i] = invs[(1 << i)][i];
    }
    for (int mask = 1; mask < (1 << n); mask++) {
        for (int was = 0; was < n; was++) {
            if (!(mask & (1 << was))) continue;
            if (dp[mask][was] == INF) continue;
            int val1 = (invs[mask][was] % 2) ? b[was] : a[was];
            for (int new_was = 0; new_was < n; new_was++) {
                if (mask & (1 << new_was)) continue;
