                if (val2 < val1) continue;
                dp[mask | (1 << new_was)][new_was] = min(dp[mask | (1 << new_was)][new_was], dp[mask][was] + invs[mask | (1 << new_was)][new_was]);
            }
        }
    }
    int best = INF;
    for (int i = 0; i < n; i++) best = min(best, dp[(1 << n) - 1][i]);
    if (best == INF) cout << -1 << '\n';
    else cout << best / 2;
    return 0;
}

