}

struct Card {
  int R, B;
};

struct Hoge {
  bool red;
  int v;
};

int main() {
  int N;
  cin >> N;

  vector<Card> C(N);
  rep(i, N) {
    if (i % 2 == 0) {
      cin >> C[i].R;
    } else {
      cin >> C[i].B;
    }
  }
  rep(i, N) {
    if (i % 2 == 0) {
      cin >> C[i].B;
    } else {
      cin >> C[i].R;
    }
  }

  int nRed = (N + 1) / 2;
  int red = first_fixed_size_subset(N, nRed);

  int ans = 1e9;

  do {
    int cost = 0;

    vector<Hoge> foo(N);
    rep(i, N) {
      if ((red >> i) & 1) {
        foo[i] = Hoge{true, C[i].R};
      } else {
        foo[i] = Hoge{false, C[i].B};
      }
    }

    bool flag = true;
    for (int i = 0; flag; i++) {
      flag = false;
      for (int j = N - 1; j >= i + 1; --j) {
        if (foo[j].v < foo[j - 1].v) {
          swap(foo[j], foo[j - 1]);
          flag = 1;
          ++cost;
        }
      }
    }

    do {
      flag = false;
      rep(i, N - 1) {
        if (foo[i].v == foo[i + 1].v &&
            (i % 2 == 0 && !foo[i].red && foo[i + 1].red)) {
          swap(foo[i], foo[i + 1]);
          ++cost;
        }
      }
    } while (flag);

    rep(i, N) {
      if (i % 2 == 0 && !foo[i].red) {
        int j = i + 1;
        while (j < N && foo[i].v == foo[j].v && !foo[j].red) ++j;
        if (j == N || foo[i].v != foo[j].v) goto hoge;
        for (int k = j; k > i; --k) {
          swap(foo[k], foo[k - 1]);
          ++cost;
        }
      }
      if (i % 2 == 1 && foo[i].red) {
        int j = i + 1;
        while (j < N && foo[i].v == foo[j].v && foo[j].red) ++j;
        if (j == N || foo[i].v != foo[j].v) goto hoge;
        for (int k = j; k > i; --k) {
          swap(foo[k], foo[k - 1]);
          ++cost;
        }
      }
    }

    ans = min(ans, cost);
  hoge:;
  } while (next_fixed_size_subset(N, nRed, red));

  cout << (ans == 1e9 ? -1 : ans) << endl;

  return 0;
}

