    vector<int> a(n), b(n);
    rep(i,n) cin >> a[i];
    rep(i,n) cin >> b[i];
    int res = INF;
    rep(mask, 1<<n){
        using P = pair<int,int>;
        vector<P> even, odd;
        rep(i,n){
            bool is_back = mask & bit(i);
            if ((i&1)^is_back) {
                odd.push_back({is_back ? b[i] : a[i], i});
            } else {
                even.push_back({is_back ? b[i] : a[i], i});
            }
        }
        sort(all(even));
        sort(all(odd));

        bool ng = false;
        {
            int E = even.size();
            int O = odd.size();
            if (n & 1) {
                if (E-O != 1) ng = true;
            } else {
                if (E != O) ng = true;
            }
        }

        {
            int back_count = 0;
            rep(i,n){
                if(mask & bit(i)) back_count++;
            }
            if (back_count & 1) {
                ng = true;
            }
        }
        if (ng) continue;

        {
            rep(i,n-1){
                if (i % 2 == 0) {
                    if (even[i/2] > odd[i/2]) ng = true;
                } else {
                    if (odd[i/2] > even[(i+1)/2]) ng = true;
                }
            }
        }
        if (ng) continue;

        vector<int> v;
        rep(i,n){
            v.push_back((i % 2 == 0) ? even[i/2].second : odd[i/2].second);
        }
        res = min(mergecount(v), res);
    }
    cout << (res == INF ? -1 : res) << endl;
    return 0;
}

