// https://atcoder.jp/contests/chokudai_S001/submissions/1460844
ll merge_sort(vi &a) {
  int n = a.size();
  if (n == 1) {
    return 0;
  }
  ll ret = 0;
  vi b(begin(a), begin(a) + n/2);
  vi c(begin(a) + n/2, end(a));
  ret += merge_sort(b);
  ret += merge_sort(c);
  int sz_b = b.size();
  int sz_c = c.size();
  for (int i = 0, j = 0, k = 0; i < n; ++i) {
    if (j >= sz_b) {
      a[i] = c[k]; k += 1;
    } else if (k >= sz_c) {
      a[i] = b[j]; j += 1;
    } else if (b[j] <= c[k]) {
      a[i] = b[j]; j += 1;
    } else {
      a[i] = c[k]; k += 1;
      ret += n/2 - j;
    }
  }
  return ret;
}

int main() {
  scan(n);
  vi a(n), b(n);
  scan(a);
  scan(b);
  int m = (1 << n);
  ll ans = LLONG_MAX;
  rep (i, m) {
    if (__builtin_popcount(i) != n / 2) {
      continue;
    }
    vvi evens;
    vvi odds;
    rep (j, n) {
      bool odd = ((i >> j) & 1);
      if (odd) {
        if (j & 1) {
          odds.push_back({a[j], j});
        } else {
          odds.push_back({b[j], j});
        }
      } else {
        if (j & 1) {
          evens.push_back({b[j], j});
        } else {
          evens.push_back({a[j], j});
        }
      }
    }
    sort(all(evens));
    sort(all(odds));
    auto merged = merge(evens, odds);
    if (sorted(merged)) {
      vi idx(n);
      rep (i, n) {
        idx[i] = merged[i][1];
      }
      ll cans = merge_sort(idx);
      ans = min(ans, cans);
    }
  }
  if (ans == LLONG_MAX) {
    ans = -1;
  }
  print(ans);

  return 0;
}

