                if (j % 2 == 0) {
                    v1.push_back(P(a[j], j));
                } else {
                    v2.push_back(P(a[j], j));
                }
            } else {
                if (j % 2 == 0) {
                    v2.push_back(P(b[j], j));
                } else {
                    v1.push_back(P(b[j], j));
                }
            }
        }
        sort(all(v1));
        sort(all(v2));
        int i1 = 0, i2 = 0, s = 0, be = -1, f = true;
        for (int j = 0; j < n; j++) {
            if (j % 2 == 0) {
                if (i1 >= v1.size()) {
                    f = false;
                    break;
                }
                int t = v1[i1].first, id = v1[i1].second;
                if (t < be) {
                    f = false;
                    break;
                }
                be = t;
                s += abs(id - j);
                i1++;
            } else {
                if (i2 >= v2.size()) {
                    f = false;
                    break;
                }
                int t = v2[i2].first, id = v2[i2].second;
                if (t < be) {
                    f = false;
                    break;
                }
                be = t;
                s += abs(id - j);
                i2++;
            }
        }
        if (f) {
            chmin(res, s);
        }
    }
    if (res == INF) {
        cout << -1 << endl;
    } else {
        cout << res / 2 << endl;
    }
}

