void dfs(long long int odd,long long int even){
    if(odd>N/2||even>(N+1)/2){
        return;
    }else if(odd==N/2&&even==(N+1)/2){
        for(long long int i = 0; i < odd; i++){
            if(oddcard[i]%2==1){
                oddnum[i]=card[oddcard[i]].first;
