                sortcard[oddcard[i]]={card[oddcard[i]].second*2+1,oddcard[i]};
                tentou[oddcard[i]]=card[oddcard[i]].second*2+1;
            }

        }
        for(long long int i = 0; i < even; i++){

            if(evencard[i]%2==0){
                    evennum[i]=card[evencard[i]].first;
                    sortcard[evencard[i]]={card[evencard[i]].first*2,evencard[i]};
                    tentou[evencard[i]]=card[evencard[i]].first*2;
                }
            else{
