void bruteforce(int kth, int mx, int moves) {
        if(kth == 0) {
                ans = min(ans, moves);
                return;
        }
        int backup[19][2];
        for(int i = 1; i <= n; ++i) backup[i][0] = curr[i][0], backup[i][1] = curr[i][1];
        for(int i = 1; i <= kth; ++i) {
                int value = curr[i][(kth - i) % 2];
                if(value > mx) continue;
                int mn = 2e9;
                for(int j = 1; j <= kth; ++j) mn = min(curr[i][0], curr[i][1]);
                if(mx < mn) continue;
                int lastmoves = moves;
                for(int j = i; j < kth; ++j) {
                        swap(curr[j][0], curr[j + 1][1]);
                        swap(curr[j][1], curr[j + 1][0]);
                        ++lastmoves;
                }
                bruteforce(kth - 1, value, lastmoves);
                for(int j = 1; j <= n; ++j) curr[j][0] = backup[j][0], curr[j][1] = backup[j][1];
        }
}
