const ll MAXN = 18;
ll n, a[MAXN + 5][2];
ll dp[(1 << 20) + 5][55];
const ll inf = (ll)1e9;

ll rek(int mask, int prev){
	if(!mask)
		return 0;
	ll &ret = dp[mask][prev];
	if(ret != -1)
		return ret;
	ret = inf;
	for(int i = 0 ; i < n ; ++i){
		if(!(mask & (1 << i)))
			continue;
		int cur = n - __builtin_popcount(mask);
		int br = cur - (i - __builtin_popcount(mask & ((1 << i) - 1)));
		//cout << mask << ' ' << cur << ' ' << br << ' ' << i << endl;
		cur = abs(cur - i);
		int sad = a[i][(cur & 1)];
		if(sad >= prev){
			ret = min(ret, rek(mask ^ (1 << i), sad) + br);
		}
	}
	return ret;
}

