int main(){
  cin >> N;
  C = vector<P>(N);
  llvec a(N), b(N);
  rep(i, N)cin >> a[i];
  rep(i, N)cin >> b[i];
  rep(i, N){C[i]={a[i], b[i]};}
  //cout << "done..."<<endl;

  vector<llvec> dp(1<<N, llvec(N, 1e18));
  /*dp[i][j]
    状態: i
    最後のカードj つまり、最後の値は
    abs(loc-1-j)%2==0?: a[j].first:a[j].second;
   */
  //initialization
  rep(ii, N){
    ll i = 1<<ii;
    dp[i][ii] = 0;
  }
  rep(i, 1<<N){
    ll loc=0;
    rep(n, N){loc += (i&1<<n?1:0);}
    rep(k, N){
      if(dp[i][k]==1e18)continue;
      ll last = abs(loc-1-k)%2==0? C[k].first:C[k].second;
      rep(j, N){
        if(i&1<<j)continue;
        ll cand = abs(loc-j)%2==0? C[j].first:C[j].second;
        if(last<=cand){// ok
          ll cnt=0;
          FOR(n, j+1, N)if(i&1<<n)cnt++;
          dp[i|1<<j][j] = min(dp[i][k]+cnt, dp[i|1<<j][j]);
        }
      }
    }
  }

  ll ans = 1e18;
  rep(i, N){
    ans = min(ans, dp[(1<<N)-1][i]);
  }
  ans = ans==1e18?-1:ans;
  cout << ans << endl;

  return 0;
}

