int cost[N + 5][20];

int f(int mask, int id){
	if(cost[mask][id] != -1) return cost[mask][id];
	int ret = 0;
	for(int i=id+1; i<n; i++){
		if(mask & (1 << i)) ret += i - id;
	}
	return cost[mask][id] = ret;
}

int solve(int mask, int last){
	if(mask == (1 << n) - 1) return 0;
	int& ret = dp[mask][last];
	if(ret != -1) return ret;
	ret = INF;
	for(int i=0; i<n; i++){
		if(mask & (1 << i)) continue;
		int bef = abs(val[mask] - last+1) % 2 == 0 ? a[last] : b[last];
		int v = abs(val[mask] - i) % 2 == 0 ? a[i] : b[i];
		if(bef > v) continue;
//		printf("bef %d, v %d, last %d, now %d\n",bef ,v,last,i);
		ret = min(ret, solve(mask | (1 << i), i) + f(mask,i));
	}
//	printf("%d %d -> %d\n",mask,last,ret);
	return ret;
}

