typedef pair<int, int> P;

struct BIT {
    int n;
    vector<int> bit; // 1-indexd

    BIT(int sz) {
        bit.resize(sz + 1);
        n = sz;
    }

    int sum(int i) {
        int s = 0;
        while (i > 0) {
            s += bit[i];
            i -= i & -i;
        }
        return s;
    }

    void add(int i, int x) {
        while (i <= n) {
            bit[i] += x;
            i += i & -i;
        }
    }
};

class DSwapAndFlip {
public:
    void solve(std::istream& cin, std::ostream& cout) {
        int N;
        cin >> N;
        vector<int> A(N), B(N);
        REP(i, N) cin >> A[i];
        REP(i, N) cin >> B[i];

        int res = INF;
        REP(s, 1LL << N) {
            vector<pair<int, P>> v(N);
            REP(i, N) {
                if ((s >> i) & 1) {
                    v[i] = {B[i], {i, 1}};
                } else {
                    v[i] = {A[i], {i, 0}};
                }
            }
            sort(v.begin(), v.end());

            bool ok = true;
            REP(i, v.size()) {
                int idx = v[i].second.first;
                int state = v[i].second.second;

                if (idx % 2 == 0) {
                    if (i % 2 == state) {
                    } else {
                        ok = false;
                    }
                } else {
                    if (i % 2 != state) {
                    } else {
                        ok = false;
                    }
                }
            }
            //for (int i = 1; i < v.size(); i += 2) {
            //    if (v[i].second.second != v[i - 1].second.second) {
            //        ok = false;
            //    }
            //}
            if (!ok) continue;

            int tmp = 0;
            BIT bit(51);
            REP(i, v.size()) {
                int idx = v[i].second.first + 1;
                bit.add(idx, 1);
                tmp += i + 1 - bit.sum(idx);
            }
            res = min(res, tmp);
        }

        if (res == INF) {
            cout << -1 << endl;
        } else {
            cout << res << endl;
        }


    }
};


