			right_most = i;
			break;
		}
	}

	if (right_most == -1) {
		return 0; /*終わり*/
	}

	for (int i = right_most; i < num * 2; i++) {
		if (comb[i] == 1) {
			sonomigi++;
		}
	}
	comb[right_most] = 0;
	for (int i = right_most + 1; i < right_most + 1 + sonomigi; i++) {
		comb[i] = 1;
	}
	for (int i = right_most + 1 + sonomigi; i < num * 2; i++) {
		comb[i] = 0;
	}

	return 1;
}

