    fpoint operator*(const ld a) const {return fpoint(*this) *= a;}
    fpoint operator/(const ld a) const {return fpoint(*this) /= a;}
    ld dot(const fpoint& p) const {return x * p.x + y * p.y;}
    ll cross(const fpoint& p) const {return x * p.y - y * p.x;}
