/*
      x: 1001 1010  1100 1011 1101  1111
x & ~ x: 0001 0010  0100 0001 0001  0001
    sum: 1010 1100 10000 1100 1100 10000

####### Attention #######
S | (1 << i) -> S union {i}
S & ~(1 << i) -> S - {i}

# inclusion-exclusion principle
|U[i = 1 to n] Ai| = sum[i = 1 to n] |Ai| - sum[i < j]|Ai ^ Aj| + ... + (-1)^(n - 1) |^[i = 1 to n]Ai|
*/

const ll MAX_N = 200005;
const size_t MAX_BIT = 160 * 160 + 10;
typedef bitset<MAX_BIT> bts;
typedef vector<bts> vbt;
typedef vector<vbt> vbt2;
typedef vector<vbt2> vbt3;

void solve(){
    // generate_array(size, min, max);
    ll n; vl as, bs;
    in1(n);
    read_vector(n, as);
    read_vector(n, bs);
    ll M = max(*max_element(all(as)), *max_element(all(bs)));
    ll answer = INF, bM = 1LL << n;
    vl2 dp(bM, vl(M + 1, INF));

    // 自力AC
    dp[0][0] = 0;
    For(bit, 1, bM){
        ll num = popcount(bit) - 1; ll cnt, pre, v0;
        rep(i, n){
            if (!(1LL << i & bit)) continue;
            cnt = popcount(bit >> (i + 1)), pre = bit & ~(1LL << i), v0 = abs(i - num) % 2 ? bs[i] : as[i];
            rep(v, v0 + 1) if (dp[pre][v] != INF) chmin(dp[bit][v0], dp[pre][v] + cnt);
        }
    }

    answer = *min_element(all(dp[bM - 1]));
    prl(answer == INF ? -1 : answer);

    // ### DEBUG PART ###
    auto naive_solver = [&](){
    };
    #ifdef _LOCAL
        naive_solver();
    #endif
}

