// 0-indexed
// [l, r)
template <typename T>
struct Bit {
    V<T> data;
    T id_ele;

    Bit(ll size, T id_ele) : id_ele(id_ele) {
        ll bsize = 1;
        while(bsize < size) bsize *= 2;
        data = V<T>(bsize + 1, id_ele);
    }

    T sum(ll pos) {
        T ret = id_ele;
        for(; 0 < pos; pos -= pos & -pos) ret += data[pos];
        return ret;
    }

    T sum(ll l, ll r) { return sum(r) - sum(l); }

    void add(ll pos, T delta) {
        for(++pos; pos < data.size(); pos += pos & -pos) data[pos] += delta;
    }
};

int main() {
    ll N;
    cin >> N;
    V<ll> A(N), B(N);
    for (ll &e : A) cin >> e;
    for (ll &e : B) cin >> e;
    ll ans = inf;
    for (ll S = 0; S < (1ll << N); S++) {
        V<PLL> odds, evens;
        for (ll i = 0; i < N; i++) {
            bool p = ((S >> i) & 1 ? true : false);
            ll n = (p ? B[i] : A[i]);
            if (i % 2 == 0) (p ? odds : evens).emplace_back(n, i);
            else (p ? evens : odds).emplace_back(n, i);
        }

        sort(ALL(odds));
        sort(ALL(evens));
        ll pre = -1;
        Bit<ll> bt(N + 10, 0);
        ll cnt = 0;
        bool ok = true;
        for (ll i = 0; i < N; i++) {
