            }
            PLL ele = v[i / 2];
            ll a, b;
            tie(a, b) = ele;
            if (a < pre) {
                ok = false;
                break;
            }
            cnt += bt.sum(b, N + 10);
            bt.add(b, 1);
            pre = a;
