template<class T> int cou_big(vector<T> &b) {
    int n = sz(b);
    int size = max(b);
    assert(size < 1e8);
    BIT<int> bt(size + 3);
    int cou = 0;
    rer(i, n - 1) {
        cou += bt.get(b[i]);
        bt.add(b[i], 1);
    }
    return cou;
}

