    vector<vector<int>> dp(1 << n, vector<int>(n + 1, INF));
    dp[0][n] = 0;
    rep(bit, 1 << n) rep(i, n + 1) rep(j, n) {
        if (bit >> j & 1) continue;

        int cnt = popcnt(bit);
        int last_num = 0;
        if (i < n) last_num = x[abs(cnt - 1 - i) % 2][i];
        int new_num = x[abs(cnt - j) % 2][j];
        if (last_num <= new_num) {
            int rev = 0;
            repr(k, j, n) if (bit >> k & 1) rev++;
            chmin(dp[bit | (1 << j)][j], dp[bit][i] + rev);
        }
    }

    int ans = INF;
    rep(i, n) chmin(ans, dp[(1 << n) - 1][i]);
    if (ans == INF) cout << -1 << endl;
    else cout << ans << endl;
}

