void solve()
{
    int n;
    cin >> n;
    akari<int> as(n), bs(n);
    for (int i = 0; i < n; i++)
    {
        cin >> as[i];
    }
    for (int i = 0; i < n; i++)
    {
        cin >> bs[i];
    }
    int ans = 1e9;

    for (int s = 0; s < (1 << (n - 1)); s++)
    {
        akari<int> xs(n), ys(n), ws;
        for (int i = 0; i < n; i++)
        {
            ys[i] = i + 1;
        }
        for (int i = 0; i < n - 1; i++)
        {
            if (s >> i & 1)
            {
                ws.push_back(i);
            }
        }
        for (int f = 0; f < 10; f++)
        {
            if (f)
            {
                random_shuffle(ws.begin(), ws.end());
            }
            for (int i : ws)
            {
                swap(ys[i], ys[i + 1]);
                ys[i] *= -1;
                ys[i + 1] *= -1;
            }
            if (f & 1)
            {
                random_shuffle(ws.begin(), ws.end());
                for (int i : ws)
                {
                    swap(ys[i], ys[i + 1]);
                    ys[i] *= -1;
                    ys[i + 1] *= -1;
                }
            }
            akari<int> os, es, os2, es2;
            for (int i = 0; i < n; i++)
            {
                if (ys[i] > 0)
                {
                    xs[i] = as[ys[i] - 1];
                }
                else
                {
                    xs[i] = bs[-(ys[i]) - 1];
                }
                if (i & 1)
                {
                    os.push_back(xs[i]);
                }
                else
                {
                    es.push_back(xs[i]);
                }
            }
            os2 = os, es2 = es;
            sort(os.begin(), os.end());
            sort(es.begin(), es.end());
            akari<int> check(n);
            for (int i = 0; i < n; i++)
            {
                if (i & 1)
                {
                    check[i] = os[i / 2];
                }
                else
                {
                    check[i] = es[i / 2];
                }
            }
            if (!is_sorted(check.begin(), check.end()))
            {
                continue;
            }
            int res = 0, cnt = 0;
            BIT<int> bit(100), bit2(100);
            for (int o : os2)
            {
                res += cnt - bit.sum(o);
                bit.add(o, 1);
                cnt++;
            }
            cnt = 0;
            for (int e : es2)
            {
                res += cnt - bit2.sum(e);
                bit2.add(e, 1);
                cnt++;
            }
            res *= 3;
            res += __builtin_popcount(s);
            // cout << bitset<4>(s) << ' ';
            // for (int x : ys)
            // {
            //     cout << x << ' ';
            // }
            // print();
            // for (int x : xs)
            // {
            //     cout << x << ' ';
            // }
            // print(res);
            ans = min(ans, res);
        }
    }
    if (ans == 1e9)
    {
        ans = -1;
    }
    cout << ans << endl;
}

int main()
{
    solve();
    return 0;
}

