#include <bits/stdc++.h>

using namespace std;
const int maxn = 20;
int a[maxn], b[maxn];

int Check(int state, int n) {
    bool flag = true;
    int tmp = state;
    while (tmp) {
        if (tmp & 1) flag = flag ^ 1;
        tmp = tmp >> 1;
    }
    if (!flag) return -1;
    vector<pair<int, int>> ji, ou, tot;
    for (int i = 0; i < n; i++) {
        bool j = i & 1, fan = false;
        if (state & (1 << i)) {
            j = j ^ 1;
            fan = true;
        }
        if (j) {
            ji.emplace_back(fan ? b[i] : a[i], i);
        } else {
            ou.emplace_back(fan ? b[i] : a[i], i);
        }
    }
    if ((ji.size() != ou.size() - (n & 1))) {
        return -1;
    }
    sort(ji.begin(), ji.end());
    sort(ou.begin(), ou.end());
    {
        auto j = ji.begin();
        auto o = ou.begin();
        while (j != ji.end() || o != ou.end()) {
            if (o != ou.end()) {
                tot.push_back(*o);
                o++;
            }
            if (j != ji.end()) {
                tot.push_back(*j);
                j++;
            }
        }
//        for (int i = 0; i < tot.size(); i++) {
//            printf("%d %d  ss %d\n", tot[i].first, tot[i].second, state);
//        }
    }

    int ans = 0;
    for (int i = 1; i < n; i++) {
        if (tot[i - 1].first > tot[i].first)
            return -1;
        for (int j = 0; j < i; j++) {
            if (tot[j].second > tot[i].second) ans++;
        }
    }
    return ans;

}

int main() {
    int n;
    scanf("%d", &n);
    for (int i = 0; i < n; ++i) {
        scanf("%d", a + i);
    }
    for (int i = 0; i < n; i++) {
        scanf("%d", b + i);
    }
    int ans = 10000;
    for (int now = (1 << n) - 1; now >= 0; now--) {
        int t = Check(now, n);
//        printf("%d %d\n", now, t);
        if (t + 1) {
            ans = min(ans, t);
        }
    }
    printf("%d\n", ans == 10000 ? -1 : ans);
    return 0;
}

