int solve(int t, int u, int mask) {
    if (mask==0) dp[u][mask] = 0;
    if (dp[u][mask] == -1) {
        dp[u][mask] = INF;
        REP(card, 0, n) if (mask>>card&1LL) {
            int cardval = a[(card+t)%2][card];
            if (cardval < u) continue;
            int dist = 0;
            REP(i, 0, card) if (mask>>i&1LL) ++dist;
            dp[u][mask] = min(dp[u][mask], dist + solve(t+1, cardval, mask^(1<<card)));
        }
    }
    return dp[u][mask];
}

