      if ((i >> j) % 2 == 1) continue;
      int nxtBit = i | (1 << j);
      int usedCnt = 0, tmp = i;
      while (tmp > 0) {
        if (tmp % 2) ++usedCnt;
        tmp /= 2;
      }
      int nxtNum = (usedCnt % 2 == j % 2) ? a[j] : b[j];
