int main(int argc, char *argv[])
{
	ios::sync_with_stdio(false); cin.tie(0);

	int n;
	cin >> n;
	vector<int> a(n), b(n);
	for (int i = 0; i < n; i++) cin >> a[i];
	for (int i = 0; i < n; i++) cin >> b[i];

	int ans = -1;
	for (int k = 0; k < (1 << n); k++) {
		if (__builtin_popcount(k) % 2 != 0) continue;
		vector<pair<int, pair<int, int> > > t(n);
		for (int i = 0, z = k; i < n; i++, z >>= 1)
			t[i] = make_pair(z % 2 == 0 ? a[i] : b[i], make_pair(i, z % 2));
		int count = 0;
		for (int i = 0; i < n; i++)
			for (int j = i + 1; j < n; j++)
				if (t[i] > t[j]) count++;
		stable_sort(t.begin(), t.end());
		int ok = 1;
		for (int i = 0; i < n; i++) {
			int d = i - t[i].second.first;
			if (abs(d) % 2 != t[i].second.second) {
				ok = 0;
				break;
			}
		}
		if (!ok) continue;
		if (ans < 0 || ans > count) ans = count;
	}

	cout << ans << endl;

	return 0;
}

#include <bits/stdc++.h>
using namespace std;
const int inf = 0x3f3f3f3f;
const int maxn = 20;
int n,ans;

int a[maxn];
int b[maxn];

bool judge()
{
    for(int i = 2; i <= n; i++) 
    {
        if(a[i] < a[i-1]) return false;
    }
    return true;
}

void dfs(int xz,int res)
{
    if(judge())
    {
        ans = min(ans,res);
        return;
    }
    for(int i = 2; i < xz; i++) 
    {
        if(a[i] < a[i-1]) return;
    }
    for(int i = xz; i <= n-1; i++)
    {
        for(int j = 1; j <= n-1-i; j++)
        {
            swap(a[i],b[i+j]);swap(a[i+j],b[i]);
            dfs(i+j,res+j);
            swap(a[i],b[i+j]);swap(a[i+j],b[i]);
        }
    }
}

int main()
{
    cin>>n;
    for(int i = 1; i <= n; i++) 
    {
        cin>>a[i];
    }
    for(int i = 1; i <= n; i++) 
    {
        cin>>b[i];
    }
    ans = inf;
    dfs(1,0);
    if(ans == inf) puts("-1");
    else printf("%d\n",ans);
    return 0;
}

