int main() {
    int n;
    cin >> n;
    vector<int> a(n), b(n);
    REP(i, n) { cin >> a[i]; }
    REP(i, n) { cin >> b[i]; }

    int ans = -1;
    RFOR(bit, (1 << n) - 1, 0) {
        vector<int> hanten(n, 0);
        REP(i, n)
        if ((bit >> i) & 1)
            hanten[i] = 1;
        vector<pii> newa(n);
        REP(i, n) {
            if (hanten[i] == 0)
                newa[i] = {a[i], i};
            else
                newa[i] = {b[i], i};
        }
        sort(newa.begin(), newa.end());

        bool ok = true;
        REP(i, n) {
            if (abs(newa[i].second - i) % 2 != hanten[newa[i].second]) {
                if (i == n-1 || newa[i].first != newa[i+1].first){
                    ok = false;
                    break;
                }
                else{
                    int j = i;
                    while(j < n && newa[j].first == newa[i].first && abs(newa[j].second - i) % 2 != hanten[newa[j].second]) j++;
                    if(j == n || newa[j].first != newa[j].first){
                        ok = false;
                        break;
                    }
                    else{
                        swap(newa[i], newa[j]);
                    }
                }
            }
        }
        if(!ok)
            continue;

        int cnt = 0;
        vector<int> to_sort(n);
        REP(i, n){
            to_sort[newa[i].second] = i;
        }
        // バブルソート
        REP(i, n - 1) {
            RFOR(j, n - 1, i+1) {
                if (to_sort[j] < to_sort[j - 1]) {
                    swap(to_sort[j], to_sort[j - 1]);
                    cnt++;
                }
            }
        }
        if(ans == -1)
            ans = cnt;
        else
            ans = min(ans, cnt);
    }
    cout << ans << endl;
    return 0;
}

