typedef long long LL;

LL n,m,k,cc;
LL a[55],b[55];
LL lis[55],tmp[55];
LL chg[55];
LL cnt[55] = {0};
LL ans = -1;

struct BIT{
	LL tr[50005];
	LL lowbit(LL x){ return (x & (-(x))); }
	void modify(LL x,LL v){ for(;x <= 100;x += lowbit(x)) tr[x] += v; }
	LL query(LL x){ LL ret = 0; for(;x;x -= lowbit(x)) ret += tr[x]; return ret; }
}s;

int main(){
	ios::sync_with_stdio(false);
	memset(s.tr,0,sizeof(s.tr));
	cin >> n;
	for(LL i = 1;i <= n;i ++) cin >> a[i];
	for(LL i = 1;i <= n;i ++) cin >> b[i];

	for(LL i = 0;i < (1LL << n);i ++){
		memset(cnt,0,sizeof(cnt));
		memset(chg,0,sizeof(chg));
		for(LL j = 0;j < n;j ++){
			if((i >> j) & 1){ lis[j + 1] = b[j + 1]; chg[lis[j + 1]] ++; }
			else{ lis[j + 1] = a[j + 1]; }
		}
		for(LL j = 1;j <= n;j += 2) cnt[lis[j]] ++;
		for(LL j = 1;j <= n;j ++) tmp[j] = lis[j];
		sort(lis + 1,lis + 1 + n);
		for(LL j = 1;j <= n;j += 2) cnt[lis[j]] --;
		LL flg = 1;
		for(LL j = 1;j <= n;j ++) if(abs(cnt[lis[j]]) != chg[lis[j]]) flg = 0;

		if(!flg) continue;

//		cout << i << endl;
//		for(LL j = 1;j <= n;j ++) cout << tmp[j] << (j == n ? '\n' : ' ');
//		for(LL j = 1;j <= n;j ++) cout << lis[j] << (j == n ? '\n' : ' ');
//		for(LL j = 1;j <= n;j ++) cout << chg[j] << (j == n ? '\n' : ' ');

		cc = 0;
		for(LL j = 1;j <= n;j ++){
			s.modify(tmp[j],1);
			cc += (j - s.query(tmp[j]));
		}
		for(LL j = 1;j <= n;j ++) s.modify(tmp[j],-1);
		if(ans == -1) ans = cc;
		ans = min(ans,cc);
//		cout << cc << endl;
	}
	cout << ans << endl;
	return 0;
}

