template<class T> constexpr T INF = ::numeric_limits<T>::max()/32*15+208;

template <class T, class U>
vector<T> make_v(U size, const T& init){ return vector<T>(static_cast<size_t>(size), init); }

template<class... Ts, class U>
auto make_v(U size, Ts... rest) { return vector<decltype(make_v(rest...))>(static_cast<size_t>(size), make_v(rest...)); }

template<class T> void chmin(T &a, const T &b){ a = (a < b ? a : b); }
template<class T> void chmax(T &a, const T &b){ a = (a > b ? a : b); }

int main() {
    int n;
    cin >> n;
    vector<int> A(n), B(n);
    for (auto &&i : A) scanf("%d", &i);
    for (auto &&i : B) scanf("%d", &i);
    auto dp = make_v(n, 1 << n, INF<int>), dp2 = dp;
    auto cnt = make_v(1 << n, 0);
    for (int i = 0; i < 1 << n; i++) {
        for (int j = 0; j < n; j++) {
            dp[j][i] = 0;
            if ((i >> j) & 1)continue;
            for (int k = j + 1; k < n; k++) {
                if ((i >> k) & 1)dp2[j][i]++;
            }
        }
    }
    for (int i = 0; i < n; ++i) {
        dp[i][1 << i] = i;
    }
    for (int i = 0; i < 1 << n; ++i) {
        cnt[i] = __builtin_popcount(i)-1;
    }
    auto f = [&](int i, int j){ // 添字iをjに置く
        if(abs(i-j)&1) return B[i];
        else return A[i];
    };
    for (int S = 1; S < 1 << n; ++S) {
        if(cnt[S] < 1) continue;
        for (int i = 0; i < n; ++i) {
            if(!(S & (1 << i))) continue;
            int from = S ^ (1 << i);
            int cc = 0;
            for (int j = 0; j < n; ++j) {
                if(!(from & (1 << j))) {
                    if(i < j) cc++;
                    continue;
                }
                if(f(j, cnt[S]-1) <= f(i, cnt[S])){
                    dp[i][S] = min(dp[i][S], dp[j][from]+dp2[i][from]);
                }
            }
        }
    }
    int ans = INF<int>;
    for (int i = 0; i < n; ++i) {
        ans = min(ans, dp[i].back());
    }
    if(ans == INF<int>){
        puts("-1");
    }else {
        cout << ans << "\n";
    }
    return 0;
}

