  }


  int ans = INF;

  rep(b, bit(N)) {
    int num = __builtin_popcount(b);  // 裏
    if (num % 2 == 1)
      continue;

    vector<int> o, e;
    vector<int> use(N);

    int cnt = 0;
    rep(i, N) {
      if ((b >> i) & 1) {  // 裏
        cnt++;
        use[i] = B[i];
        if (i % 2 == 0)
          e.pb(B[i]);
        else
          o.pb(B[i]);
      } else {  // 表
        use[i] = A[i];
        if (i % 2 == 0)
          o.pb(A[i]);
        else
          e.pb(A[i]);
      }
    }

    if (!(len(o) == len(e) || len(o) == len(e) + 1))
      continue;

    auto o_cp = o, e_cp = e;

    sort(all(o));
    sort(all(e));

    int oo = 0, ee = 0;
    vector<int> sorted(N);
    rep(i, N) {
      if (i % 2 == 0)
        sorted[i] = o[oo++];
      else
        sorted[i] = e[ee++];
    }

    bool ok = true;
    rep(i, N - 1) {
      if (sorted[i] > sorted[i + 1])
        ok = false;
    }
    if (!ok)
      continue;

    for (int i = 0; i < len(o_cp) - 1; i++) {
      for (int j = len(o_cp) - 1; j > i; j--) {
        if (o_cp[j] < o_cp[j - 1]) {
          swap(o_cp[j], o_cp[j - 1]);
          cnt += 2;
        }
      }
    }
    for (int i = 0; i < len(e_cp) - 1; i++) {
      for (int j = len(e_cp) - 1; j > i; j--) {
        if (e_cp[j] < e_cp[j - 1]) {
          swap(e_cp[j], e_cp[j - 1]);
          cnt += 2;
        }
      }
    }
    cnt /= 2;
    chmin(ans, cnt);
  }

  if (ans == INF) {
    puts("-1");
  } else {
    cout << ans << "\n";
  }
}

