void brute_force(int k, vector<iii> vec)
{
	if(k == n)
	{
		sort(vec.begin(), vec.end());
		// for(int i = 0; i < n; i++)
		// 	printf("%d|%d|%d ", vec[i].fi.fi, vec[i].se, vec[i].fi.se); printf("\n");

		int res = 0;
		for(int i = 0; i < n; i++)
		{
			int tar = vec[i].fi.se;
			int idx = i;
			while(idx > tar)
			{
				res++;
				vec[idx].se ^= 1;
				vec[idx-1].se ^= 1;
				swap(vec[idx], vec[idx-1]);
				idx--;
			}			
		}
		for(int i = 0; i < n-1; i++)
		{
			if(vec[i].se && vec[i].fi.fi == vec[i+1].fi.fi)
			{
				res++;
				vec[i].se ^= 1;
				vec[i+1].se ^= 1;
			}
		}

		bool bol = 1;
		for(int i = 0; i < n; i++)
			if(vec[i].se)
				bol = 0;

		if(bol)
			mn = min(mn, res);

		// for(int i = 0; i < n; i++)
		// 	printf("%d|%d|%d ", vec[i].fi.fi, vec[i].se, vec[i].fi.se); printf("\n");

	}
	else
	{
		vec.push_back({{A[k], k}, 0});
		brute_force(k+1, vec);
		vec.pop_back();

		vec.push_back({{B[k], k}, 1});
		brute_force(k+1, vec);
		vec.pop_back();
	}
}


