        // cout << vec[i].b << " | ";
    }

    // cout << " --- kdlsd " << endl;

    int ans = 1e9;

    for(int mask = 0; mask < (1<<n); mask++) {
        vector<Card> t = vec;
        for(int i = 0; i < n; i++) {
            if(mask & (1<<i)) {
                t[i].v = t[i].b;
            }
        }
        sort(t.begin(), t.end());

        bool possible = true;



        int prev = t[0].v;
        int i = 0;
        while(i < n) {
            vector<Card> odd, even;
            int oddcnt = 0;
            int evencnt = 0;
            int start = i;
            while(i < n and prev == t[i].v) i++;

            int end = i;

            end--;

            for(int j = start ; j <= end; j++) {
                // if(mask == 0) cout << t[j].i << " " <<  j << endl;
                if(t[j].i % 2 == 1) {
                    if(mask & (1<<t[j].i))
                        even.push_back(t[j]);
                    else odd.push_back(t[j]);
                }
                else {
                    if(mask & (1<<t[j].i))
                        odd.push_back(t[j]);
                    else even.push_back(t[j]);
                }
                if(j % 2 == 1) oddcnt++;
                else evencnt++;
            }

            // if(mask == 0) cout << oddcnt << " _ " << evencnt << endl;
            // if(mask == 0) cout << odd.size() << " _ " << even.size()<< endl;
            if(oddcnt != odd.size()) possible = 0;
            if(evencnt != even.size()) possible = 0;

            if(!possible) break;

            sort(odd.begin(), odd.end());
            sort(even.begin(), even.end());

            int k = 0;
            int r = 0;
            for(int j = start; j <= end; j++) {
                if(j % 2 == 0) {
                    t[j] = even[k++];
                }else t[j] = odd[r++];
            }



            if(i < n)
                prev = t[i].v;
        }

        if(possible) {
            // cout << " mask " << mask << endl;
            // for(int i = 0; i < n; i++) {
            //     cout << t[i].v << "," ;
            // }
            // cout << " -- \n"; 
            ans = min(ans, minswaps(t, vec));
        }



    }

    if(ans == 1e9) cout << -1 << endl;
    else cout << ans << endl;



    return 0;
}

