template<class Iterator, class Compare>
int inversion_number(Iterator l, Iterator r, Compare comp){
	if(r - l <= 1) return 0;
	Iterator i, j, k, h = l + (r - l) / 2;
	int ans = inversion_number(l, h, comp) + inversion_number(h, r, comp);
	auto x = *l;
	vector<decltype(x)> tmp(l, r);
	for(i = l, j = l, k = h; i < r; i++){
		if(k == r || (j < h && !comp(tmp[k - l], tmp[j - l]))){
			*i = tmp[j - l];
			j++;
		}
		else{
			*i = tmp[k - l];
			ans += k - i;
			k++;
		}
	}
	return ans;
}

int M;

int solve(int N, vector<int> &A, vector<int> &B, int d){
	if(d > M){
		return inf;
	}
	int i, f = 1;
	for(i = 1; i < N; i++){
		if(A[i - 1] > A[i]){
			f = 0;
		}
	}
	if(f == 1){
		return 0;
	}
	int ans = inf;
	for(i = 1; i < N; i++){
		swap(A[i - 1], B[i]);
		swap(A[i], B[i - 1]);
		ans = min(ans, solve(N, A, B, d + 1) + 1);
		M = min(M, ans + d);
		swap(A[i - 1], B[i]);
		swap(A[i], B[i - 1]);
	}
	return ans;
}

