const int inf = 1000003;

int N;

int A[18], B[18];
int dp[36][(1<<18)];

int solve(int pos, int mask, int prev)
{
    if(pos == N)
        return 0;

    if(dp[prev][mask] != -1)
        return dp[prev][mask];

    int ans = inf, x = __builtin_popcount(mask);

    for(int i=0; i<N; i++)
    {
        if(mask & (1<<i))
        {
            x--;
            continue;
        }

        if(abs(i - pos) % 2)
        {
            if(B[i] >= prev)
                ans = min(ans, solve(pos+1, (mask | (1 << i)), B[i]) + abs(i + x - pos));
        }
        else
        {
            if(A[i] >= prev)
                ans = min(ans, solve(pos+1, (mask | (1 << i)), A[i]) + abs(i + x - pos));
        }
    }

    return dp[prev][mask] = ans;
}

