class Card {
public:
    int a, b, index;
    Card() {}
    Card(int a, int b, int index) {
        this->a = a;
        this->b = b;
        this->index = index;
    }
    int value(int i) {
        return abs(i-index) % 2 == 0 ? a : b;
    }
};

int ans = (int)1e9;
int N;

void dfs(int index, vector<Card>& cards, vector<int>& numbers, vector<bool>& used, vector<int>& indexes, int cost) {
    if (cost >= ans) {
        return;
    }

    if (index == N) {
        ans = min(ans, cost);
        return;
    }

    for (int i=0; i<N; i++) {
        int v = cards[i].value(index);
        if ((index == 0 || v >= cards[indexes[index-1]].value(index-1)) && (v <= numbers[N+index]) && !used[i]) {
            indexes[index] = i;
            used[i] = true;
            int count = 0;
            for (int j=i+1; j<N; j++) {
                if (used[j]) count++;
            }
            dfs(index+1, cards, numbers, used, indexes, cost + abs(cards[i].index+count-index));
            //out.print(list, " ");
            //out.println(index + ", " + res);
            indexes[index] = -1;
            used[i] = false;
        }
    }
}

