int main() {
	read(n);
	for (int i = 0; i < n; ++i) {
		read(a[i]);
	}
	for (int i = 0; i < n; ++i) {
		read(b[i]);
	}
	int ans = INF;
	for (int S = 0; S < (1 << n); ++S) {
		std::vector<int> p[2];
		for (int i = 0; i < n; ++i) {
			p[S >> i & 1].push_back(i);
		}
		if ((int)p[1].size() != n / 2) {
			continue;
		}
		std::stable_sort(p[0].begin(), p[0].end(), [&](int x, int y) {
			return getv(x, 0) < getv(y, 0);
		});
		std::stable_sort(p[1].begin(), p[1].end(), [&](int x, int y) {
			return getv(x, 1) < getv(y, 1);
		});
		bool flag = 1;
		for (int i = 0; i < n; ++i) {
			s[i] = p[i & 1][i >> 1];
			if (i && getv(s[i], i & 1) < getv(s[i - 1], (i - 1) & 1)) {
