				break;
			}
		}
		if (!flag) {
			continue;
		}
		int sum = 0;
		for (int i = 0; i < n; ++i) {
			for (int j = i + 1; j < n; ++j) {
				sum += s[i] > s[j];
			}
		}
		ans = std::min(ans, sum);
	}
	if (ans == INF) {
		print(-1);
	} else {
		print(ans);
	}
