using namespace std;

void solve() {
  ll N;
  cin >> N;
  vector<ll> A(N);
  vector<ll> B(N);
  rep (i, N) cin >> A[i];
  rep (i, N) cin >> B[i];

  ll all_blue = 0;
  rep (i, N) {
    all_blue <<= 1;
    all_blue += 1;
  }

  ll ans = -1;

  for (ll T = 0; T <= all_blue; T++) {
    vector<ll> tmp(N);
    vector<ll> _tmp(N);
    unordered_map<ll, ll> odd;
    unordered_map<ll, ll> even;
    rep (i, N) {
      if (((T >> i) & 1) == 0) {
        tmp[i] = A[i];
        if (i % 2 == 0) even[A[i]]++;
        else odd[A[i]]++;
      }
      else {
        tmp[i] = B[i];
        if (i % 2 == 0) odd[B[i]]++;
        else even[B[i]]++;
      }
    }
    _tmp = tmp;
    sort(tmp.begin(), tmp.end());
    bool flag = true;
    rep (i, N) {
      if (i % 2 == 0) {
        even[tmp[i]]--;
        if (even[tmp[i]] < 0) flag = false;
      } else {
        odd[tmp[i]]--;
        if (odd[tmp[i]] < 0) flag = false;
      }
    }
    if (not flag) continue;
    cerr << "---- T" << endl;
    cerr << T << endl;
    cerr << "---- _tmp" << endl;
    rep (i, N) cerr << _tmp[i] << " ";
    cerr << endl;
    cerr << "---- tmp" << endl;
    rep (i, N) cerr << tmp[i] << " ";
    cerr << endl;
    unordered_set<ll> rest;
    rep (i, N) rest.insert(i);
    vector<ll> order(N);
    rep (i, N) {
      ll diff = 0;
      if (((T >> i) & 1) == 1) diff = 1;
      for (; diff < N; diff += 2) {
        if (i - diff >= 0 and rest.count(i-diff) and tmp[i-diff] == _tmp[i]) {
          order[i] = i - diff;
          rest.erase(i-diff);
          break;
        }
        if (i + diff < N and rest.count(i+diff) and tmp[i+diff] == _tmp[i]) {
          order[i] = i + diff;
          rest.erase(i+diff);
          break;
        }
      }
    }
    // if (rest.size() != 0) continue;
    cerr << "---- order" << endl;
    rep (i, N) cerr << order[i] << " ";

    ll tmp_ans = 0;
    for (ll i = 0; i < N; i++) for (ll j = 0; j < i; j++) if (order[j] > order[i]) tmp_ans++;

    if (ans == -1) ans = tmp_ans;
    else ans = min(ans, tmp_ans);

    cerr << endl;
  }

  cout << ans << endl;
}

int main(void) {
  cin.tie(0);
  ios::sync_with_stdio(false);
  cout.precision(12);
  cout << fixed;
  solve();
  return 0;
}

