template <class T> class bit {
public:
  vector<T> dat;
  int n;

  bit(int n) : n(n) { dat.assign(n, 0); }
  bit(int n, T ini) : n(n) { dat.assign(n, ini); }
  // sum [0,i)
  T sum(int i) {
    int ret = 0;
    for (--i; i >= 0; i = (i & (i + 1)) - 1)
      ret += dat[i];
    return ret;
  }
  // sum [i,j)
  T sum(int i, int j) { return sum(j) - sum(i); }
  // add x to i
  void add(int i, T x) {
    for (; i < n; i |= i + 1)
      dat[i] += x;
  }
};
int trans(vector<int> a) {
  int n = a.size();
  vector<pair<int, int>> v;
  rep(i, n) v.push_back(make_pair(a[i], i));
  bit<lli> bi(n);
  lli sum = 0;
  sort(v.begin(), v.end());
  rep(i, n) {
    sum += bi.sum(v[i].second, n);
    // cout << bi.sum(v[i].second, n) << endl;
    bi.add(v[i].second, 1);
  }
  return sum;
}
void solve(long long N, std::vector<long long> A, std::vector<long long> B) {
  rep(i, 1 << N) dp[i] = 1e9;

  lli ans = 1e9;
  rep(i, 1 << N) {
    vector<int> u(N);
    rep(j, N) {
      if ((1 << j) & i) {
        u[j] = B[j];
      } else {
        u[j] = A[j];
      }
      // cout << u[j] << " ";
    }
    vector<int> v = u;
    vector<int> g(N);
    bool used[55] = {};
    sort(v.begin(), v.end());
    rep(j, N) {
      if ((i & (1 << j)) == 0) {
        rep(l, N) {
          if (((j % 2) == (l % 2)) && v[l] == u[j] && !used[l]) {
            g[j] = l;
            used[l] = true;
            break;
          }
        }
      } else {
        rep(l, N) {
          if (((j % 2) != (l % 2)) && v[l] == u[j] && !used[l]) {
            g[j] = l;
            used[l] = true;
            break;
          }
        }
      }
    }
    bool flag = true;
    rep(j, N) {
      if (!used[j])
        flag = false;
    }
    if (flag) {
      ans = min(ans, (lli)trans(g));
    }
  }
  if (ans != 1e9) {
    cout << ans << endl;
  } else {
    cout << -1 << endl;
  }
}

