signed main() {
	INIT;

	VAR(int, n);
	VEC(int, a, n);
	VEC(int, b, n);

	int ans = INFLL;
	REP(bit, 1 << n) {
		std::priority_queue<PAIR, V<PAIR>, std::greater<PAIR>> pq[2];
		REP(i, n) {
			if (!(bit & 1 << i)) {
				pq[i % 2].emplace(a[i], i);
			}
			else {
				pq[1 - i % 2].emplace(b[i], i);
			}
		}

		int val = 0;
		int pre = -1;
		REP(i, n) {
			if (pq[i % 2].empty()) {
				val = INFLL;
				break;
			}
			PAIR t = pq[i % 2].top(); pq[i % 2].pop();
			if (pre > t.first) {
				val = INFLL;
				break;
			}
			pre = t.first;
			val += std::abs(i - t.second);
		}
		CHMIN(ans, val);
	}
	if (ans >= INFINT) ans = -2;
	OUT(ans / 2)BR;

	return 0;
}

