using namespace std;
constexpr ll INF = 1ll << 61;
vector<vector<ll>> dp;
vector<int> a, b;
int n;

ll dfs(ll s, ll l, int c) {
  // s:状態。立っているビットは未使用であることを示す
  // l:最後のカードの値
  // c:使ったカードの枚数(dpに影響なし)
  if (s == 0) {
    dp[s][l] = 0;
  }
  if (dp[s][l] != -1) {
    return dp[s][l];
  }
  dp[s][l] = INF;
  for (int i = 0; i < n; i++) {
    // 次のカード
    if ((s >> i) & 1) {
      // 未使用
      int next = ((i + c) % 2 == 0) ? a[i] : b[i];
      if (next < l)
        continue;
      int d = 0;
      for (int j = 0; j < i; j++) {
        // nextのカードよりも前にあって、まだ使っていないカードの枚数を数える
        // つまりnextを前に持っていくのに必要なコスト
        if (s >> j & 1) {
          d++;
        }
      }
      dp[s][l] = min(dp[s][l], d + dfs(s & ~(1 << i), next, c + 1));
    }
  }
  return dp[s][l];
}

