    ans = min(ans, dfs((1 << n) - 1, i, 0));
  }
  // ans = min(ans, dfs((1 << n) - 1, 1, 0));
  if (ans == INF) {
    cout << -1 << endl;
  } else {
    cout << ans << endl;
  }
}

