#include<bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef vector<ll> vec;
typedef vector<vec> mat;
typedef pair<ll,ll> pll;
const ll mod=1e9+7;
//const ll mod=998244353;
const ll inf=5e18;

ll n;
mat a(20,vec(2));
ll dfs(set<ll> odd, ll res, ll id) {
  ll ans=inf;
  if(id==n) {
    vector<pll> od,ev;
    for(ll i=0;i<n;i++) {
      if(odd.count(i)) {
        ll tmp=a[i][(i+1)%2];
        od.push_back({tmp,i});
      }
      else {
        ll tmp=a[i][i%2];
        ev.push_back({tmp,i});
      }
    }
    sort(od.begin(),od.end());
    sort(ev.begin(),ev.end());
    vector<pll> so;
    for(ll i=0;i<n;i++) {
      if(i%2) {
        so.push_back(od[i/2]);
      }
      else {
        so.push_back(ev[i/2]);
      }
    }
    ll f=0;
    for(ll i=0;i<n-1;i++) {
      if(so[i].first>so[i+1].first) f=1;
    }
    if(f) return ans;
    ans=0;
    vec num(n);
    for(ll i=0;i<n;i++) {
      num[i]=i;
    }
    for(ll i=0;i<n;i++) {
      ll tmp=i;
      while(num[tmp]!=so[i].second) {
        tmp++;
      }
      for(ll j=tmp;j-1>=i;j--) {
        ll ch=num[j];
        num[j]=num[j-1];
        num[j-1]=ch;
        ans++;
      }
    }
  }
  else {
    if(res<n-id) ans=min(ans,dfs(odd,res,id+1));
    if(res!=0) {
      odd.insert(id);
      res--;
      ans=min(ans,dfs(odd,res,id+1));
    }
  }
  return ans;
}

int main() {
  cin >> n;
  for(ll i=0;i<2;i++) for(ll j=0;j<n;j++) cin >> a[j][i];
  set<ll> b;
  ll ans=dfs(b,n/2,0);
  if(ans==inf) ans=-1;
  cout << ans << endl;
}

