int main() {
	uint N;
	cin >> N;

	uint pA = 0;
	bool iniA = true;
	vector<uint> A(N);
	for(uint i=0; i<N; i++) {
		cin >> A[i];
		iniA &= pA <= A[i];
		pA = A[i];
	}

	vector<pair<uint, uint>> AB(N);
	for(uint i=0; i<N; i++) {
		uint B;
		cin >> B;
		AB[i] = make_pair(A[i], B);
	}

	if(iniA) {
		cout << 0;
		return 0;
	}

	vector<uint> perm(N);
	iota(perm.begin(), perm.end(), 0);

	uint ans = UINT_MAX;
	bool aexist = false;

	do {
		bool sorted = true;
		for(int i=1; i<N; i++) {
			int c = perm[i-1];
			uint ap = (abs(i - 1 - c) % 2 == 0) ? AB[c].first : AB[c].second;

			int d = perm[i];
			uint ac = (abs(i - d) % 2 == 0) ? AB[d].first : AB[d].second;

			sorted &= ap <= ac;

			if(!sorted) break;
		}

		uint nans = 0;

		if(sorted) {
			aexist = true;

			set<uint> po;
			for(int i=0; i<N; i++) po.insert(i);

			for(int i=0; i<N; i++) {
				auto itr = find(po.begin(), po.end(), perm[i]);
				auto dst = distance(po.begin(), itr);
				po.erase(itr);
				nans += dst;

				if(nans >= ans) break;
			}

			ans = min(ans, nans);
		}

		if(nans >= ans) break;

	} while(next_permutation(perm.begin(), perm.end()));

	if(aexist) {
		cout << ans;
	} else {
		cout << -1;
	}

	return 0;
}

