using namespace std;

struct Card
{
	int a, b;
	int maxNum;
	int setNum;
	int oriPos;
	bool isUsed;
};
Card cards[20];
Card newCards[20];
int n;
int minSteps;
std::set<int> minSet;

void swap(int a[], int i, int j) {
	int temp;
	temp = a[i];
	a[i] = a[j];
	a[j] = temp;
}

//计算步数的过程，本质是一个冒泡排序的过程
int calcSteps(Card cards[]) {
	int step = 0;
	int a[20];	//简便起见，我们不去尝试改变cards里面的位置，而只是调整索引 
	for (int i = 0 ; i < n ; i++) {
		a[i] = cards[i].oriPos;
	}

	for (int i = 0 ; i < n - 1 ; i++) {
		for (int j = 0 ; j < n - i - 1 ; j++) {
			if (a[j] > a[j + 1]) {
				swap(a, j, j + 1);
				step++;
			}
		}
	}

	return step;
}

void doGenerate(int depth, int curNum, int stepNow) {
	if (depth == n) {
		int curSteps = calcSteps(newCards);
		if ((minSteps == -1) || (minSteps > curSteps))
			minSteps = curSteps;
	} else {
		int newNum;
		int newStep;
		for (int i = 0 ; i < n ; i++) {
			if (true == cards[i].isUsed)
				continue;
			if ((cards[i].oriPos % 2) == (depth % 2))
				newNum = cards[i].a;
			else
				newNum = cards[i].b;

			if (curNum > newNum)
				continue;

			newStep = stepNow + abs(cards[i].oriPos - depth);
			if (minSteps < (newStep / 2))
				continue;

			minSet.erase(cards[i].setNum);

			int curMinNum;
			if (minSet.size() != 0) {
				curMinNum = *(minSet.begin());
				curMinNum = curMinNum / 1000;
			} else {
				curMinNum = 10000;
			}

			if (curMinNum >= newNum) {
				newCards[depth].a = newNum;
				newCards[depth].oriPos = cards[i].oriPos;
				cards[i].isUsed = true;
				doGenerate(depth + 1, newNum, newStep);
				cards[i].isUsed = false;
			}

			minSet.insert(cards[i].setNum);
		}
	}
}

int main()
{
	scanf("%d", &n);

	for (int i = 0 ; i < n ; i++)
	{
		scanf("%d", &(cards[i].a));
		cards[i].oriPos = i;
		cards[i].isUsed = false;
	}

	minSet.clear();
	for (int i = 0 ; i < n ; i++){
		scanf("%d", &(cards[i].b));
		if (cards[i].a > cards[i].b)
			cards[i].maxNum = cards[i].a;
		else
			cards[i].maxNum = cards[i].b;
		cards[i].setNum = cards[i].maxNum * 1000 + cards[i].oriPos;	//唯一性键 
		minSet.insert(cards[i].setNum);
	}

	minSteps = 500;

	doGenerate(0, -1, 0);

	if (minSteps == 500)
		minSteps = -1;

	printf("%d\n", minSteps);


	return 0;
}

