  int INF = 1e9;
  for(auto&& i:irange(0,n)) {
    int len = i+1;
    vecint dist(1<<len, INF);
    dist[0] = 0;
    queue<int> q;
    q.push(0);
    while (!q.empty()) {
      int j = q.front();
      q.pop();
      bitset<18> bs(j);
      for(auto&& k:irange(0,len-1)) {
        if (bs[k] == bs[k+1]) {
          auto tmp = bs;
          tmp.flip(k);
          tmp.flip(k+1);
          int nx = tmp.to_ulong();
          if (dist[nx] > dist[j]+1) {
            dist[nx] = dist[j]+1;
            q.push(nx);
          }
        }
      }
    }
    table[i] = move(dist);
  }
  vecint a(n);
  vecint b(n);
  for(auto&& e:a) cin>>e;
  for(auto&& e:b) cin>>e;
  ll ans = INF;
  for(auto&& i:irange(0,1<<n)) {
    vector<tuple<int,int,int>> c(n);
    int cnt=0;
    for(auto&& j:irange(0,n)) {
      if ((i>>j)&1) {
        c[j] = make_tuple(b[j], true, 0);
        ++cnt;
      } else {
        c[j] = make_tuple(a[j], false, 0);
      }
    }
    if ((cnt%2) == 1) continue;
    ll swp = 0;
    for(auto&& j:irange(0,n)) {
      for(auto&& k:irange(0,n-1)) {
        int v1 = get<0>(c[k]);
        int v2 = get<0>(c[k+1]);
        if (v1 > v2) {
          ++swp;
          swap(c[k], c[k+1]);
          ++get<2>(c[k]);
          ++get<2>(c[k+1]);
        }
      }
    }
    int val = 0;
    int len = 0;
    int old = -1;
    for(auto&& j:irange(0,n)) {
      int v,o,s;
      tie(v,o,s) = c[j];
      int parity = o != ((s % 2) == 1);
      if (v != old) {
        swp += table[len][val];
        val = parity;
        len = 1;
        old = v;
      } else {
        val *= 2;
        val += parity;
        ++len;
      }
    }
    ans = min(ans, swp);
  }
  if (ans < INF) {
    cout<<ans<<endl;
  } else {
    cout<<-1<<endl;
  }
  return 0;
}

