/*
      x: 1001 1010  1100 1011 1101  1111
x & ~ x: 0001 0010  0100 0001 0001  0001
    sum: 1010 1100 10000 1100 1100 10000

####### Attention #######
S | (1 << i) -> S union {i}
S & ~(1 << i) -> S - {i}

# inclusion-exclusion principle
|U[i = 1 to n] Ai| = sum[i = 1 to n] |Ai| - sum[i < j]|Ai ^ Aj| + ... + (-1)^(n - 1) |^[i = 1 to n]Ai|
*/

const ll MAX_N = 200005;
const size_t MAX_BIT = 160 * 160 + 10;
typedef bitset<MAX_BIT> bts;
typedef vector<bts> vbt;
typedef vector<vbt> vbt2;
typedef vector<vbt2> vbt3;

void solve(){
    // generate_array(size, min, max);
    ll n; vl as, bs;
    in1(n);
    read_vector(n, as);
    read_vector(n, bs);
    ll M = max(*max_element(all(as)), *max_element(all(bs)));
    ll answer = INF;
    vl2 dp(M + 1, vl(1LL << n, INF));

    dp[0][0] = 0;
    For(bit, 1, 1LL << n){
        ll num = popcount(bit) - 1;
        rep(i, n){
            if (!(1LL << i & bit)) continue;
            ll pre = bit & ~(1LL << i);
            ll v0 = abs(i - num) % 2 ? bs[i] : as[i];
            rep(v, v0 + 1){
                if (dp[v][pre] != INF)
                    chmin(dp[v0][bit], dp[v][pre] + abs(i - num));
            }
        }
    }

    /*
    3
    3 4 3
    3 2 3
      000 001 010 011 100 101 110 111
    0 { 0, 10, 10, 10, 10, 10, 10, 10},
    1 {10, 10, 10, 10, 10, 10, 10, 10},
    2 {10, 10,  1, 10, 10, 10, 10, 10},
    3 {10,  0, 10,  2,  2,  1,  2,  2},
    4 {10, 10, 10,  0, 10, 10,  2, 10}}
    */

    ll bM = 1LL << n;
    answer = INF;
    For(v, 1, M + 1) chmin(answer, dp[v][bM - 1]);
    prl(answer == INF ? -1 : answer / 2);

    // ### DEBUG PART ###
    auto naive_solver = [&](){
        answer = INF;
        vl ids(n, 0), vs(n, 0);
        rep(i, n) ids[i] = i;
        do{
            bool okay = true; ll cnt = 0;
            rep(i, n){
                vs[ids[i]] = abs(i - ids[i]) % 2 ? bs[i] : as[i];
                cnt += abs(i - ids[i]);
            }

            rep(i, n - 1) if (vs[i] > vs[i + 1]) okay = false;
            if (okay) chmin(answer, cnt / 2);
        }while(next_permutation(all(ids)));
        prl(answer == INF ? -1 : answer);
    };
    #ifdef _LOCAL
        naive_solver();
    #endif
}

void test(ll num = 0, bool verbose = false){
    rep(i, max(1LL, num)){
        ll t = clock();
        if (verbose) prl4("\n#####", i + 1, "#####", "\n## Answer ##");
        solve();
        if (verbose) {prl(""); prl_time(t);}
    }
}

