template <class T, class U> inline bool chmax(T& lhs, const U& rhs) { if (lhs < rhs) { lhs = rhs; return 1; } return 0; }
template <class T, class U> inline bool chmin(T& lhs, const U& rhs) { if (lhs > rhs) { lhs = rhs; return 1; } return 0; }

constexpr int inf = (1 << 30) - 1;

int N;
int A[18], B[18];
int dp[2][50][1 << 18];
// dp[][i][j]: i: 最後においたカードの数字 j: 今までに並べたカードの集合

int main() {

  std::cin >> N;
  rep (i, N) {
    std::cin >> A[i];
    --A[i];
  }
  rep (i, N) {
    std::cin >> B[i];
    --B[i];
  }

  rep (i, 2) {
    rep (j, 50) {
      rep (k, 1 << N) {
        dp[i][j][k] = inf;
      }
    }
  }

  dp[0][0][0] = 0;
  int i = 0, ni = 1;
  rep (step, N) {
    rep (S, 1 << N) {
      if (__builtin_popcount(S) != step) {
        continue;
      }
      rep (last, 50) {
        int cnt = 0;
        rep (l, N) {
          if ((1 << l) & S) {
            ++cnt;
            continue;
          }
          int num = std::abs(l - step) % 2 == 0 ? A[l] : B[l];
          if (num < last) {
            continue;
          }
          chmin(dp[ni][num][S | (1 << l)], dp[i][last][S] + l - cnt);
        }
        dp[i][last][S] = inf;
      }
    }
    std::swap(i, ni);
  }

  int ans = inf;
  rep (k, 50) {
    rep (j, 1 << N) {
      chmin(ans, dp[i][k][j]);
    }
  }
  std::cout << (ans == inf ? -1 : ans) << '\n';

}

