  ll pos_0 = 0b101010101010101010;

  vector<ll> C(N);
  vector<ll> P(N);

  ll n_operation;

  for(ll color=0; !(color>>N); ++color) {
    ll sum_color = 0;
    ll pos_1 = color ^ pos_0;
    for(ll i=0; i<N; ++i) {
      C[i] = ((color>>i)&1 ? B[i] : A[i]);
      P[i] = (pos_1>>i)&1;
      sum_color += ((color>>i)&1);
    }
    if (sum_color&1) continue;

    vector<ll> C_sorted(C);
    sort(C_sorted.begin(), C_sorted.end());

    n_operation = 0;
