int solve(vector<pair<int, int> > &inp) {
	int ret = 0;
	loop(i, 1, inp.size() - 1) {
		int cur = i;
		while (cur > 0 && inp[cur - 1].fi > inp[cur].fi) {
			swap(inp[cur - 1], inp[cur]);
			inp[cur - 1].se ^= 1; inp[cur].se ^= 1;
			cur--;
			ret++;
		}
	}
	for (int i = 0; i < inp.size();) {
		int last = i;
		loop(j, i + 1, inp.size() - 1) {
			if (inp[j].fi != inp[j - 1].fi) break;
			last = j;
		}
		int tick = -1;
		loop(j, i, last) {
			if (inp[j].se == 0) continue;
			if (tick == -1) tick = j;
			else {
				if ((j - tick + 1) % 2 == 0) 
					ret += j - tick;
				else return INF;
				tick = -1;
			}
		}
		if (tick != -1) return INF;
		i = last + 1;
	}
	return ret;
}

