// 裏表のbit全探索で、バブルソートすればよい。
// カードの位置によって裏表が決まるのに注意する。

int N;
vector<int> A,B;

int bubbleSort(vector<pii> &v){
    int n=0;
    int size=v.size();
    for(int i=0;i<size;i++){
        for(int j=size-1;j>i;j--) {
            if(v[j].second <= v[j-1].second){
                swap(v[j],v[j-1]);
                n++;
            }
        }
    }
    return n;
}

