void solve(){
    input();
    int ans=INT_INF;
    // bit全探索。maskの値で表になってるカードを管理する。
    for(ull mask=0;mask<(1ULL<<N);mask++){
        // maskに従い、裏表をひっくり返したXを用意する。
        vector<pii> X;
        for(int i=0;i<N;i++){
            if(mask & (1ULL<<i)) X.push_back(make_pair(i,A[i]));
            else X.push_back(make_pair(i,B[i]));
        }
        int tmp = bubbleSort(X);
        // Xをソートしたものが、とりうる裏表のパターンなのか判断。
        // そうであったら、最小値かどうか判断。
        bool chk=true;
        for(int j=0;j<N;j++){
            if(mask&(1ULL<<j))
                // j番目が表A
                chk &= (abs(j-X[j].first)%2==0);
            else
                // j番目が裏B
                chk &= (abs(j-X[j].first)%2==1);
        }
        if(chk)
            ans = min(ans,tmp);
    }

    if(ans==INT_INF) ans = -1;
    cout << ans << endl;
}


