    dp[0][0] = 0;
    auto chmin = [](int &a, int b) { a = min(a, b); };
    // {0, 1, ..., n-1} の部分集合の全探索
    for (int bit = 0; bit < (1 << n); ++bit) {
        vector<pair<int, int>> rem;
        int ite = 0;
        for (int i = 0; i < n; i++) {
            if ((1 << i) & bit) ite++;
        }
        int cnt = ite;
        for (int i = 0; i < n; i++) {
            if (!((1 << i) & bit)) rem.push_back({i, cnt++});
        }

        for (int s = 0; s <= 50; s++) {
            for (auto p : rem) {
                int i0 = p.first;
                int i1 = p.second;

                int x = abs(i0 - ite) % 2 ? b[i0] : a[i0];
                if (x >= s) {
                    chmin(dp[bit | (1 << i0)][x], dp[bit][s] + abs(i1 - ite));
                }
            }
        }
    }
    int ans = 1e8;
    for (int i = 0; i <= 50; i++) {
        chmin(ans, dp[(1 << n) - 1][i]);
    }
    if (ans == 1e8)
        cout << -1 << endl;
    else
        cout << ans << endl;
    return 0;
}

