int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    int n;
    cin >> n;
    vector< vector<int> > a(2, vector<int>(n));
    for (int i = 0; i < 2; ++i) {
        for (int j = 0; j < n; ++j) {
            cin >> a[i][j];
        }
    }

    int ans = INF;
    vector< vector< deque<int> > > ids(2, vector< deque<int> >(51));
    for (int i = 0; i < (1 << n); ++i) {
        if (__builtin_popcount(i) % 2 == 1) continue;

        vector<int> v(n);
        for (int j = 0; j < n; ++j) {
            v[j] = a[i >> j & 1][j];
        }
        sort(v.begin(), v.end());

        int rest = n;
        for (int j = 0; j < n; ++j) {
            ids[j % 2][v[j]].push_back(j);
        }

        int memo = 0;
        vector<int> nex(n, -1);
        for (int j = 0; j < n; ++j) {
            int hoge = i >> j & 1;
            deque<int>& d = ids[abs(j % 2 - hoge)][a[hoge][j]];
            if (d.empty()) {
                memo = INF;
                break;
            }
            nex[j] = d.front();
            d.pop_front();
            rest--;
        }

        for (int j = 0; j < n; ++j) {
            ids[j % 2][v[j]].clear();
        }

        if (memo >= INF || rest > 0) continue;
        memo = 0;
        for (int j = 0; j < n; ++j) {
            for (int k = 0; k < j; ++k) {
                if (nex[k] > nex[j]) memo++;
            }
        }
        ans = min(ans, memo);
    }
    cout << (ans >= INF ? -1 : ans) << "\n";
    return 0;
}

