			if(use[j])v.push_back({y[j],j});
			else v.push_back({x[j],j});
		}
		sort(all(v));
		f(j,n){
			int vj;
			if(abs(j-v[j].S)%2!=use[v[j].S]){
				for(int k=j+1;v[k].F==v[j].F;k++){
					if(abs(j-v[k].S)%2==use[v[k].S]){
						for(int l=k;l>j;l--){
							swap(v[l].S,v[l-1].S);
						}
						break;
					}
				}
			}
			f(k,n){
				if(zz[k]==v[j].S){
					vj=k;
					break;
				}
			}
			if(abs(j-v[j].S)%2!=use[v[j].S]){
				/*f(k,n){
					cout<<(int)use[k]<<" ";
				}
				cout<<endl<<j<<" "<<vj<<" "<<v[j].S<<endl;*/
				goto loop;
			}
			else{
				if(j>vj){
					for(int k=vj;k<j;k++){
						swap(vx[k],vy[k+1]);
						swap(vy[k],vx[k+1]);
						swap(zz[k],zz[k+1]);
						sum++;
					}
				}
				else{
					for(int k=vj;k>j;k--){
						swap(vx[k],vy[k-1]);
						swap(vy[k],vx[k-1]);
						swap(zz[k],zz[k-1]);
						sum++;
					}
				}
			}
		}
		ans=min(ans,sum);
		loop:;
	}
	if(ans==INF)puts("-1");
	else cout<<ans<<endl;
}

