template<typename T>
void fin(T const& t){ std::cout << t << std::endl; exit(0); }

bool next_choice(int ixh[], int h, int N) {
  for(int i = h-1, n = N; i >= 0; --i, --n) {
    if(ixh[i]+1 < n) {
      int v = ixh[i]+1;
      for(int j = i; j < h; ++j) ixh[j] = v++;
      return true;
    }
  }
  return false;
}

struct bit {
  int data_[32];
  bit() { std::fill_n(data_, 32, 0); }
  int lb(int i){ return i&-i; }
  int query(int i) { // 1-base
    int res = 0;
    while(i > 0) { res += data_[i-1]; i -= lb(i); }
    return res;
  }
  void add(int i, int v) { // 1-base
    while(i <= 32) { data_[i-1] += v; i += lb(i); }
  }
};

int calc(int ix[], int N) {
  bit b;
  int res = 0;
  for(int i = 0; i < N; ++i) {
    res += i - b.query(ix[i]+1);
    b.add(ix[i]+1, 1);
  }
  return res;
}

uint64_t getZ() {
  uint64_t v = 0; int c;
  while((c = getchar_unlocked()) >= '0') v=v*10+c-'0';
  return v;
}

int main() {
  int N = getZ(), H = (N+1)/2;
  int ab[2][18];
  for(int i = 0; i < N; ++i) std::cin >> ab[i%2][i];
  for(int i = 0; i < N; ++i) std::cin >> ab[(i+1)%2][i];
  int ix[18], ixh[9], ixe[9], ixo[9];
  bool used[18];
  std::iota(ixh, ixh+H, 0);

  int ans = 10000;
  // check all possibility; MAX: comb(18,9) < 50000
  for(;;) {
    // prepare even
    std::copy_n(ixh, H, ixe);
    std::sort(ixe, ixe+H, [&](int l, int r){ return ab[0][l] < ab[0][r]; });

    // prepare odd
    std::fill_n(used, N, false);
    for(int i = 0; i < H; ++i) used[ixh[i]] = true;
    int ix_o = 0;
    for(int i = 0; i < N; ++i) if(!used[i]) ixo[ix_o++] = i;
    std::sort(ixo, ixo + N-H, [&](int l, int r){ return ab[1][l] < ab[1][r]; });

    // check if sorted
    bool sorted = true;
    for(int i = 0; i < N-H; ++i) {
      if(ab[0][ixe[i]] > ab[1][ixo[i]]) { sorted = false; break; }
      if(i+1 < H &&  ab[1][ixo[i]] > ab[0][ixe[i+1]]) { sorted = false; break; }
    }
    if(sorted) {
      // merge
      for(int i = 0; i < H; ++i) ix[i*2] = ixe[i];
      for(int i = 0; i < N-H; ++i) ix[i*2+1] = ixo[i];
      ans = std::min(ans, calc(ix, N));
    }

    if(!next_choice(ixh, H, N)) break;
  }
  if(ans > 9999) ans = -1;
  fin(ans);
  return 0;
}

