// 多次元 vector 生成
template <class T> vector<T> make_vec(size_t a) { return vector<T>(a); }
template <class T, class... Ts> auto make_vec(size_t a, Ts... ts) {
    return vector<decltype(make_vec<T>(ts...))>(a, make_vec<T>(ts...));
}
template <class T> bool chmax(T &a, const T &b) {
    if (a < b) {
        a = b;
        return 1;
    }
    return 0;
}
template <class T> bool chmin(T &a, const T &b) {
    if (b < a) {
        a = b;
        return 1;
    }
    return 0;
}
int main() {
    // cin.tie(0);
    // ios::sync_with_stdio(false);

    int N;
    cin >> N;
    vector<int> A(N), B(N);
    REP(i, N) { cin >> A.at(i) >> B.at(i); }

    int ans = INF;
    int bit = 0;
    while (bit < 1 << N) {
        vector<int> use(N);
        int mask = 1;
        int sum = 0;
        // cout << "bit:" << bit << " "; // debug
        REP(i, N) {
            // cout << ((mask & bit) > 0); // debug
            if (mask & bit) { // ビットが立てば裏
                use[i] = B[i];
                sum++;
            } else {
                use[i] = A[i];
            }
            mask = mask << 1;
        }

        if (sum % 2 == 1) {
            bit++;
            // cout << endl; // debug
            continue;
        }
        vector<int> arr = use;
        sort(ALL(use));
        auto ev_od = make_vec<int>(55, 2);
        REP(i, N) {
            if (i % 2 == 0) {
                ev_od[use[i]][0]++;
            } else {
                ev_od[use[i]][1]++;
            }
        }
        bool flag = false;

        mask = 1;
        REP(i, N) {
            if (mask & bit) { // ビットが立てば裏
                if (i % 2 == 0) {
                    if (ev_od[B[i]][1]) {
                        ev_od[B[i]][1]--;
                    } else {
                        flag = true;
                    }
                } else {
                    if (ev_od[B[i]][0]) {
                        ev_od[B[i]][0]--;
                    } else {
                        flag = true;
                    }
                }
            } else {
                if (i % 2 == 0) {
                    if (ev_od[A[i]][0]) {
                        ev_od[A[i]][0]--;
                    } else {
                        flag = true;
                    }
                } else {
                    if (ev_od[A[i]][1]) {
                        ev_od[A[i]][1]--;
                    } else {
                        flag = true;
                    }
                }
            }
            mask = mask << 1;
        }
        if (flag) {
            bit++;
            // cout << endl; // debug
            continue;
        }

        // cout << "OK";

        // bubble
        vector<int> ind(N);
        REP(i, N) { ind[i] = i; }
        int t = 0;
        for (int i = 0; i < N - 1; i++) {
            for (int j = 0; j < N - i - 1; j++) {
                if (arr[j] > arr[j + 1]) { // 右隣が小さければ入れ替える
                    swap(arr[j], arr[j + 1]);
                    swap(ind[j], ind[j + 1]);
                    t++;
                }
            }
        }

        int tmp = 0;
        mask = 1;
        REP(i, N) {
            if (mask & bit) { // ビットが立てば裏
                if (abs(ind[i] - i) % 2 == 0) {
                    tmp++;
                }
            } else {
                if (abs(ind[i] - i) % 2 == 1) {
                    tmp++;
                }
            }
            mask = mask << 1;
        }
        chmin(ans, t + tmp / 2);

        bit++;
        // cout << endl; // debug
    }

    if (ans == INF) {
        cout << -1 << endl;
    } else {
        cout << ans << endl;
    }
    return 0;
}

