        swap(flip[cpos], flip[cpos - 1]);
        flip[cpos] ^= 1;
        flip[cpos - 1] ^= 1;
        cpos--;
        sum++;
      }
      if (sum >= ans) {
        break;
      }
    }
    if (sum < ans) {
      bool ok = true;
      int cval = val[0], cnt = (flip[0] != (mask & 1));
