        for(int k=1;k<n;k++)
            if(copa[k]>copa[k+1]) {
                    f=1;break;
            }
        if(!f) minl=min(minl,cnt);
    }
    printf("%lld\n",minl==INF?-1ll:minl);
    return 0;
}
