int dp[1 << 19][19];

int f(const vector<Pii>& a, int movedIdx, int originalIdx) {
	return (movedIdx - originalIdx) % 2 == 0 ? a[originalIdx].first : a[originalIdx].second;
}

int solve(vector<Pii> a) {
	memset(dp, 0x3F, sizeof(dp));
	const int n = sz(a);
	FOR(i, n) {
		dp[1 << i][i] = 0;
	}

	FOR(F, 1 << n) {
		FOR(i, n) {
			if (dp[F][i] == 0x3F3F3F3F) continue;
			int bitCnt = 0;
			FOR(j, n) if (F & (1 << j)) bitCnt++;
			int counted = 0;
			FOR(j, n) {
				if (F & (1 << j)) {
					counted++;
					continue;
				}
				const int lastVal = f(a, bitCnt - 1, i);
				const int nextVal = f(a, bitCnt , j);
				if (lastVal > nextVal) continue;
				int nF = F | (1 << j);
				chmin(dp[nF][j], dp[F][i] + bitCnt - counted);
			}
		}
	}

	int ans = 0x3F3F3F3F;
	FOR(i, n) {
		int cur = dp[(1 << n) - 1][i];
		ans = min(ans, cur);
	}
	if (ans == 0x3F3F3F3F) return -1;
	else return ans;
}

