const int N = 18;
const int V = 50;
const int inf = 1e15;
int dp[(1 << N)][V + 1];
int a[N];
int b[N];
int off[N][N];

void solve()
{
	int n; cin >> n;
	for(int i=0; i<n; i++) cin >> a[i];
	for(int i=0; i<n; i++) cin >> b[i];
	for(int i=0; i<n; i++)
	{
		for(int j=0; j<n; j++)
		{
			off[i][j] = (i%2 == j%2) ? a[j] : b[j]; 	// (shifting from index j to index i)
		}
	}
	int h = (1 << n); 
	for(int m=0; m<h; m++)
	{
		for(int j=0; j<=V; j++)
		{
			dp[m][j] = inf;
		}
	}
	dp[0][0] = 0;
	for(int m=0; m<h; m++)
	{
		int i = __builtin_popcount(m); // i -> first i positions have been filled elements p_j where j_th bit = 1 in M
		for(int v=0; v<=V; v++) // Last value being v (i.e. value of (i - 1)th index)
		{
			int d = 0;				// how much j_th index is to be shifted after I set indices have been positioned at the begining
			for(int j=0; j<n; j++)
			{
				if(m & (1<<j)) continue;  // if used already, move on
				if(off[i][j] >= v)
				{
					dp[m | (1 << j)][off[i][j]] = min(dp[m | (1 << j)][off[i][j]], dp[m][v] + d);
				}
				d++;
			}
		}
	}
	int ans = inf;
	for(int i=0; i<=V; i++) ans = min(ans, dp[h-1][i]);
	if(ans == inf) { cout << -1 << endl; return; }
	cout << ans << endl;
}

