int F(int i,int j,int ok)
{
    if(f[i][j][ok]!=-1) return f[i][j][ok];
    else if(i==(1<<n)-1) return 0;
    else
    {
        int res=1e9,sl=0,t=0;
        for(int id=1;id<=n;id++)
        {
            if(((i>>(id-1))&1)==1) sl++;
        }
        //cout<<i<<" "<<j<<" "<<ok<<" "<<sl<<'\n';
        for(int id=1;id<=n;id++)
        {
            if(((i>>(id-1))&1)==0)
