int main() {
    int N, ans = inf; cin >> N;
    vvl AB(N, vl(2));
    rep(i,N) cin >> AB[i][0];
    rep(i,N) cin >> AB[i][1];

    rep(bits,(1<<N)) {
        vll num(N); rep(i,N) num[i] = make_pair(AB[i][BIT(bits,i)], i);

        bool ok = true;
        int count = 0;
        rep(i,N-1) {
            int mx = 0, idx = -1;
            rep(j,N-i) {
                if (BIT(bits,num[j].second) != abs(N-1-i - num[j].second)%2) continue;
                int val = num[j].first;
