int solve(int cnt,vector<int> order) {
	if (cnt >= n) {
		return -1;
	}
	bool canIncrease = true;
	int pre_num;
	if (order[0] % 2 == 0) {
		pre_num = a[order[0]];
	}
	else
	{
		pre_num = b[order[0]];
	}
	for (int i = 1;i < n; i++) {
		int num;
		if ((order[i] -i)% 2 == 0) {
			num = a[order[i]];
		}
		else
		{
			num = b[order[i]];
		}

		if (num < pre_num) {
			canIncrease = false;
			break;
		}

		pre_num = num;
	}

	if (canIncrease) {
		return cnt;
	}
	int m = 20;
	for (int i = 0; i < n-1; i++) {
		vector<int> o(order);
		int tmp = o[i];
		o[i] = o[i + 1];
		o[i + 1] = tmp;
		int s = solve(cnt + 1, o);
		if (s >0) {
			m = min(m, s);
		}
	}

	if (m == 20) {
		return -1;
	}
	else {
		return m;
	}

}

