// n個の中からk個選ぶ 0~n-1 bitで表現 n<=18 k<=n
vector<int> combination(int n,int k){
	vector<int> ans;
	int x = (1<<k)-1;
	int f = x<<(n-k);
	while(1){
		ans.push_back(x);
		if(x==f)return ans;
		x += x&-x;
		int pcount = bitset<64>(x).count();
		x|=(1<<(k-pcount))-1;
	}
}

struct Inversions{// tentosu
	// after init,u can get number of inversions num_inversion(A)
	vector<int> L,R;
	void initsize(int n){//input size of A
		L.resize(n/2+2);
		R.resize(n/2+2);
	}
	int merge(vector<int> &A,int n,int left,int mid,int right){
		int i,j,k;
		int cnt = 0;
		int n1 = mid - left;
		int n2 = right - mid;
		for(i=0;i<n1;i++)L[i]=A[left+i];
		for(i=0;i<n2;i++)R[i]=A[mid+i];
		L[n1]=R[n2]=INT_MAX;//
		i=j=0;
		for(k=left;k<right;k++){
			if(L[i]<=R[j]){
				A[k]=L[i++];
			}else{
				A[k]=R[j++];
				cnt += n1-i;
			}
		}
		return cnt;
	}
	int mergeSort(vector<int> &A,int n,int left,int right){
		int mid;
		int v1,v2,v3;
		if(left+1<right){
			mid = (left+right)/2;
			v1 = mergeSort(A,n,left,mid);
			v2 = mergeSort(A,n,mid,right);
			v3 = merge(A,n,left,mid,right);
			return v1+v2+v3;
		}else return 0;
	}
	int num_inversion(vector<int> A){
		vector<int> B=A;//Aの順番を変えたくないなら
		return mergeSort(B,B.size(),0,B.size());
	}
};


int main(){
	ios::sync_with_stdio(false);
	cin.tie(0);
	int N,n,ans=-1;
	cin >> N;
	n = N/2;
	if(N==1){
		cout << 0 << endl;
		return 0;
	}
	vector<int> A(N),B(N);
	for(int i=0;i<N;i++) cin >> A[i];
	for(int i=0;i<N;i++) cin >> B[i];
	for(int ch=0; ch<=n; ch++){
		auto chodd = combination( n,ch );
		auto cheve = combination( N-n,ch );
		for(auto odds : chodd){
			for(auto eves : cheve){
				vector<pair<int,int>> odd,eve;
				for(int i=0;i<n;i++){
					if(odds&(1<<i)){
						eve.push_back({B[2*i+1],2*i+1});
					}else{
						odd.push_back({A[2*i+1],2*i+1});
					}
				}
				for(int i=0;i<N-n;i++){
					if(eves&(1<<i)){
						odd.push_back({B[2*i],2*i});
					}else{
						eve.push_back({A[2*i],2*i});
					}
				}
				sort(odd.begin(), odd.end());
				sort(eve.begin(), eve.end());
				vector<int> to_ind,value;
				for(int i=0;i<n;i++){
					value.push_back(eve[i].first);
					to_ind.push_back(eve[i].second);
					value.push_back(odd[i].first);
					to_ind.push_back(odd[i].second);
				}
				if(N&1){
					value.push_back(eve[n].first);
					to_ind.push_back(eve[n].second);
				}
				bool none = false;
				for(int i=0;i<N-1;i++) if(value[i]>value[i+1]) none = true;
				if(none) continue;
				Inversions inv;
				inv.initsize(N);
				int cnt = inv.num_inversion(to_ind);
				if(ans==-1) ans = cnt;
				ans = min(ans,cnt);
			}
		}
	}
	cout << ans << endl;
}

