}

void dfs(int xz,int res)
{
    if(judge())
    {
        ans = min(ans,res);
        return;
    }
    for(int i = 2; i < xz; i++) 
    {
        if(a[i] < a[i-1]) return;
    }
    for(int i = xz; i <= n-1; i++)
    {
        for(int j = 1; j <= n; j++)
