constexpr ll N_MAX = 18;
constexpr ll A_I_MAX = 50;
constexpr ll B_I_MAX = 50;

ll N;
vector<ll> A;
vector<ll> B;

void solve() {
	scanf("%lld", &N);
	A.assign(N, 0);
	rep(i, N) { scanf("%lld", &A[i]); }
	B.assign(N, 0);
	rep(i, N) { scanf("%lld", &B[i]); }

	if([&]{
		rep(i,N-1){
			if(A[i]>A[i+1])return false;
		}
		return true;
	}()){
		p(0);return;
	}

	//dp[bit][i] = bitが立っているカードは左詰めで整列済み、整列済みの最後の値はi
	vector<vector<ll>> dp((1LL<<N), vector<ll>(51, INF));
	dp[0][0]=0;

	for (ll bit = 0, size = (1LL<<N); bit < size; bit++) {
		ll c=__builtin_popcount(bit);
		vector<pair<ll,ll>> nokori; //{初期のindex, 現bitでのindex}
		rep(i, N) {
			if (!(bit & (1LL<<i))) {
				//まだ整列されていない
				nokori.push_back({i,c});
				c++;
			}
		}
		for(pair<ll,ll> pr:nokori){
			//prを整列済み部分(bit)の末尾(__builtin_popcount(bit)番目)にくっつけようとしている
			ll dif = abs(pr.first-__builtin_popcount(bit));
			ll val = dif%2==0 ? A[pr.first] : B[pr.first];

			ll bitafter=bit|(1LL<<pr.first);
			ll swaptimes=pr.second-__builtin_popcount(bit);
			for(ll i=0;i<=val;i++){
				chmin(dp[bitafter][val], dp[bit][i]+swaptimes);
			}
		}
	}
	debug(dp);
	ll ans = INF;
	rep(i,dp[0].size()){
		chmin(ans,dp[(1<<N)-1][i]);
	}
	if(ans==INF){
		p(-1);return;
	}
	printf("%lld\n", ans);

}

