			if((i >> j) & 1){ lis[j + 1] = b[j + 1]; chg[j + 1] = 1; }
			else{ lis[j + 1] = a[j + 1]; chg[j + 1] = 0; }
		}
		for(LL j = 1;j <= n;j += 2) cnt[lis[j]] ++;
		for(LL j = 1;j <= n;j ++) tmp[j] = lis[j];
		sort(lis + 1,lis + 1 + n);
