	for (auto &i : b) i = ri();

	for (int i = 1; i < n; i += 2) std::swap(a[i], b[i]);

	int dp[1 << n][n];
	for (auto &i : dp) for (auto &j : i) j = 1000000000;
	for (int i = 0; i < n; i++) dp[1 << i][i] = 0;
	for (int i = 0; i < 1 << n; i++) {
		for (int j = 0; j < n; j++) {
			if (dp[i][j] == 1000000000) continue;
			for (int k = 0; k < n; k++) {
				if (i >> k & 1) continue;
