				for (int l = k + 1; l < n; l++) if (i >> l & 1) swapped++;
				dp[i | 1 << k][k] = std::min(dp[i | 1 << k][k], dp[i][j] + swapped);
			}
		}
	}
	int res = *std::min_element(dp[(1 << n) - 1], dp[(1 << n) - 1] + n);
	if (res == 1000000000) puts("-1");
