const int maxn = 18;
int f[1<<maxn][55], a[2][maxn], n;
int solve(int msk, int lst){
	if(msk == (1<<n) - 1) return 0;
	if(~f[msk][lst]) return f[msk][lst];
	int ans = (1<<30), l = n - __builtin_popcount(msk), r = 0;
	for(int i = n - 1; i >= 0; i--){
		if((msk>>i)&1) r++;
		else {
			l--;
			int sig = (l % 2) ^ (r % 2);
			if(a[sig][i] >= lst){
				ans = min(ans, solve(msk | (1<<i), a[sig][i]) + l);
			}
		}
	}
	return f[msk][lst] = ans;
}
