template<class T>
inline bool chmin(T& a, const T b) { return a > b && (a = b, true); }

int main() {

	int N;
	cin >> N;

	vector<int> A(N), B(N);
	for (int i = 0; i < N; i++) cin >> A[i];
	for (int i = 0; i < N; i++) cin >> B[i];

	int ans = INF;
	auto check = [&](auto &vec) {

		DMP(vec);
		vector<pair<int, int>> V(N);
		for (int i = 0; i < N; i++) V[i] = { vec[i], i };

		// buble sort
		int swaps = 0;
		for (int i = 0; i < N - 1; ++i) {
			for (int j = 0; j < N - i - 1; ++j) {
				if (V[j] > V[j + 1]) {
					swap(V[j], V[j + 1]);
					swaps++;
				}
			}
		}
		DMP(V);

		bool res = true;
		for (int i = 0; i < N; i++) {
			const auto& [c, org] = V[i];
			if ((org - i) & 1) res &= c == B[org];
			else res &= c == A[org];
			if (!res) break;
		}

		if (res) chmin(ans, swaps);

		return res;
	};

	for (int bit = 0; bit < (1 << N); bit++) {
		auto vec = A;
		for (int i = 0; i < N; i++) {
			if ((bit >> i) & 1) vec[i] = B[i];
		}
		check(vec);
	}

	cout << (ans == INF ? -1 : ans) << "\n";

	return 0;
}

