int main()
{
    cin >> n;
    myfor(i, 1, n + 1) cin >> a[i];
    myfor(i, 1, n + 1) cin >> b[i];

    int ans = INF;
    myfor(i, 0, (1 << n) - 1) {
        int cnt = 0;
        vector<pair<int,int> > tp;

        myfor (j, 0, n) {
            if ((i >> (n - j - 1)) & 1) tp.pb(make_pair(-b[j + 1], j + 1));
            else tp.pb(make_pair(a[j + 1], j + 1));
        }
        myfor (j, 0, n) {
            for (int k = n - 1; k > j; k--) if (abs(tp[k].first) < abs(tp[k - 1].first)) {
                swap(tp[k], tp[k - 1]);
                cnt++;
            }
        }

        bool flag = true;
        int move_cnt = 0;

        myfor (j, 0, n) {
            move_cnt = abs(tp[j].second - (j + 1));
            if (tp[j].first < 0) {
                if (!(move_cnt & 1)) flag = false;
            }
            else {
                if (move_cnt & 1) flag = false;
            }
        }

        if (flag) ans = min(ans, cnt);
    }

    cout << ((ans == INF) ? -1 : ans) << endl;
    return 0;
}

