#define N_MAX 20

struct bit{
  long long dat[N_MAX + 1];

  void init(){
    for(int i = 0; i < N_MAX; i++){
      dat[i] = 0;
    }
  }

  long long sum(int i){
    long long s = 0;
    while(i > 0){
      s += dat[i];
      i -= i & -i;
    }
    return s;
  }

  void add(int i, long long x){
    while(i <= N_MAX){
      dat[i] += x;
      i += i & -i;
    }
  }
}bit1;

ll f(vector<ll> &v){
  bit1.init();
  ll ans = 0;
  rep(i,0,v.sz){
    ans += i-bit1.sum(v[i]);
    bit1.add(v[i],1);
  }
  return ans;
}

