#include<bits/stdc++.h>
using namespace std;
struct C{
  long x;
  long id;
  C(long x_,long id_):x(x_),id(id_){}
  C(){}
};
bool cmp(C c1,C c2){
  if(c1.x==c2.x)return c1.id<c2.id;
  return c1.x<c2.x;
}

class BIT{
  long n;
  vector<long>B;
  public:
  void add(long i,long x){  
    while(i<=n&&i!=0){B[i]+=x;i+=(i&-i);}
  }
  long sum(long i){
    if(i==0)return 0;
    long ans=0;
    while(i>0){ans+=B[i];i-=(i&-i);}return ans;
  }
  BIT(long N):n(N){
    long t=1;while(t<=n)t*=2;
    for(long i=0;i<=t;i++)B.push_back(0);
  }
};

int main(){
  long N;cin>>N;long ans=-1;
  vector<long>A(N),B(N);
  for(long i=0;i<N;i++)cin>>A[i];
  for(long i=0;i<N;i++)cin>>B[i];
  for(long bit=0;bit<(1<<N);bit++){
    bitset<18>b(bit);
    if(b.count()%2!=0)continue;
    vector<C>even;
    vector<C>odd;
    for(long i=0;i<N;i++){//1なら裏
      if((i+b.test(i))%2)odd.push_back(C((b.test(i)?B[i]:A[i]),i));
      else even.push_back(C((b.test(i)?B[i]:A[i]),i));
    }
    if(even.size()-odd.size()!=N%2)continue;
    sort(even.begin(),even.end(),cmp);
    sort(odd.begin(),odd.end(),cmp);
    vector<C>X(N);
    for(long i=0;i<N;i++)
      X[i]=(i%2==0?even[i/2]:odd[i/2]);
    bool ok=1;
    for(long i=0;i<N-1;i++)if(X[i].x>X[i+1].x)ok=0;
    if(!ok)continue;


    //コストの計算:BITで転倒数

    BIT t(N);
    long s=0;
    for(int i=0;i<N;i++){
      s+=i-t.sum(X[i].id+1);
      t.add(X[i].id+1,1);
    }


    ans=(ans==-1?s:min(ans,s)); 

  }
  cout<<ans<<endl;
}

