int N;
vector<int> A, B;
int ans = INF;

int main(){
  cin >> N;
  A.resize(N), B.resize(N);
  REP(i, N){
    cin >> A[i];
  }
  REP(i, N){
    cin >> B[i];
  }
  REP(b, 1<<N){
    vector<int> retu;
    int cntB = 0;
    REP(i, N){
      if(b >> i & 1){
        retu.push_back(A[i]);
      }
      else{
        cntB++;
        retu.push_back(B[i]);
      }
    }
    if(cntB %2) continue;
    sort(retu.begin(), retu.end());
    // REP(i, N){
    //   cerr << retu[i] << " ";
    // }
    // cerr << endl;
    vector<int> homon(N, false);
    int cost = 0;
    bool flag = true;
    REP(i, N){
      int minc = INF, idx = -1;
      REP(j, N){
        if(homon[j] == true) continue;
        if(b >> i & 1){
          if(abs(i-j) % 2 == 0){
            if(A[j] == retu[i] && abs(i-j) < minc){
              minc = abs(i-j);
              idx = j;
            }
          }
        }
        else{
          if(abs(i-j) % 2 == 1){
            if(B[j] == retu[i] && abs(i-j) < minc){
              minc = abs(i-j);
              idx =j;
            }
          }
        }
      }
      if(idx == -1){
        flag = false;
        break;
      }
      else{
        cost += minc;
        homon[idx] = true;
      }
    }
    if(flag){
      ans = min(cost, ans);
    }
  }
  if(ans == INF){
    cout << "-1" << endl;
  }
  else{
    cout << ans/2 << endl;
  }
  return 0;
}

