  for (int i = 0; i < n; i++) cin >> a[i];
  for (int i = 0; i < n; i++) cin >> b[i];
  int ans = 1 << 30;
  for (int mask = 0; mask < (1 << n); mask++) {
    if (__builtin_popcount(mask) != n / 2) continue;
    vector<pair<int, int>> odd, even;
    for (int j = 0; j < n; j++) {
      if (mask & (1 << j)) odd.emplace_back(j % 2 ? a[j] : b[j], j);
      else even.emplace_back(j % 2 ? b[j] : a[j], j);
    }
    sort(odd.begin(), odd.end());
    sort(even.begin(), even.end());
    vector<pair<int, int>> res;
    for (int i = 0; i < (int) odd.size(); i++) {
      res.push_back(even[i]);
      res.push_back(odd[i]);
    }
    if (even.size() > odd.size()) res.push_back(even.back());
    int cur = 0;
    bool valid = true;
    for (int i = 0; i < n - 1; i++) if (res[i].first > res[i + 1].first) valid = false;
    if (!valid) continue;
    for (int i = 0; i < n; i++) cur += abs(i - res[i].second);

    ans = min(ans, cur / 2);
  }
