					swap(k[l],k[l+1]);
					swap(K[l],K[l+1]);
					sum++;
				}
			}
		}
		for(int j=0;j<N-1;j++){
			if(K[j]!=j%2){
				j++;
				sum++;
			}
		}
		minL=min(minL,sum);
	}
	if(minL==10000)cout<<-1;
	else cout<<minL;
	return 0;
}

