const int max_n=20;
const int inf=0x3f3f3f3f;
int n,a[max_n],b[max_n];
int c[max_n];
int flip[max_n];
int p[max_n];
int solve(int state){
    for(int i=0;i<n;i++)flip[i]=0;
    int res=0;
    for(int i=0;i<n;i++)p[i]=i;
    for(int i=0;i<n;i++){
        for(int j=i+1;j<n;j++){
            if(c[p[j]]<c[p[j-1]]){
                res++;
                flip[p[j]]^=1,flip[p[j-1]]^=1;
                swap(p[j],p[j-1]);
            }
        }
    }
    for(int i=0;i<n;i++){
        int j=i;
        while(j<n&&c[p[j]]==c[p[i]])j++;
        for(int l=i;l<j;l++){
            if(flip[p[l]]!=(state>>l&1)){
                if(l==j-1)return inf;
                res++;
                flip[p[l]]^=1,flip[p[l+1]]^=1;
            }
        }
        i=j-1;
    }
    return res;
}
