                dp[newmask][cur] = min(dp[newmask][cur], dp[mask][val] + cost);
				cost++;
			}
		}
	}
	int ans = inf;
	for(int i = 1; i <= 50; i++){
		ans = min(ans, dp[(1 << n) - 1][i]);
	}
