int calcDist() {
    int res = 0;
    int pos = 0;
    for (int i = 0; i < N; i++) {
        int d = get<1>(X2[i]) - i;
        pos += d;
        res += abs(d);
        if (((abs(d) & 1) != 0) != get<2>(X2[i]))
            return INF;
    }
    if (pos)
        return INF;
    return res;
}

int main(void) {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N;

    for (int i = 0; i < N; i++)
        cin >> A[i];
    for (int i = 0; i < N; i++)
        cin >> B[i];

    for (int i = 0; i < N; i++) {
        if (i & 1) {
            oddA[A[i]].push_back(i);
            evenB[B[i]].push_back(i);
        } else {
            evenA[A[i]].push_back(i);
            oddB[B[i]].push_back(i);
        }
    }

    bool ok = true;
    for (int i = 1; i < N; i++) {
        if (A[i - 1] > A[i]) {
            ok = false;
            break;
        }
    }
    if (ok) {
        cout << 0 << endl;
        return 0;
    }

    int res = INF;

    for (int i = 0; i < (1 << N); i++) {
        int bit = popcount(i);
        if (bit & 1)
            continue;

        for (int j = 0; j < N; j++) {
            if (i & (1 << j))
                X[j] = make_tuple(B[j], j, true);
            else
                X[j] = make_tuple(A[j], j, false);
        }
        memcpy(X2, X, sizeof(X[0]) * N);
        stable_sort(X2, X2 + N);

        res = min(res, calcDist());
    }

    if (res >= INF)
        cout << -1 << endl;
    else
        cout << res / 2 << endl;

    return 0;
}

