int main() {
    ios_base::sync_with_stdio(false); cin.tie(NULL); cout.tie(NULL);

    int n;
    cin >> n;
    vector<int> a(n);
    vector<int> b(n);
    cin >> a >> b;
    int ans = 1e9;
    for (int i = 0; i < (1 << n); ++i) {
        vector<int> v(n, false);
        for (int j = 0; j < n; ++j) {
            if ((i >> j) & 1) {
                v[j] = true;
            }
        }
        vector<int> res;
        for (int j = 0; j < n; ++j) {
            if (v[j]) res.pb(b[j]);
            else res.pb(a[j]);
        }
        sort(res.begin(), res.end());
        vector<int> even, odd;
        vector<int> has;
        for (int j = 0; j < n; ++j) {
            int k = a[j];
            if (v[j]) {
                k = b[j];
            }
            if ((j + v[j]) % 2 == 0)
                even.pb(k);
            else
                odd.pb(k);
            has.pb(k);
        }
        vector<int> real_even, real_odd;
        for (int j = 0; j < n; ++j) {
            if (j % 2 == 0) real_even.pb(res[j]);
            else real_odd.pb(res[j]);
        }
        if (multiset<int>(real_even.begin(), real_even.end()) != multiset<int>(even.begin(), even.end()) ||
            multiset<int>(real_odd.begin(), real_odd.end()) != multiset<int>(odd.begin(), odd.end())) {
            continue;
        }
        int sm = 0;
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                if (has[i] == res[j] && ((i + v[i]) % 2 == j % 2)) {
                    res[j] = -1;
                    sm += abs(i - j);
                }
            }
        }
        if (sm % 2 == 1) continue;
        ans = min(ans, sm / 2);
    }
    if (ans == 1e9) ans = -1;
    cout << ans << endl;

    return 0;
}

