using namespace std;

int solve(vector<int> &V, int N, bitset<18> &bit){
  int ret = 0;
  bool flag = true;
  vector<int> count(N,0);
  for(int i=0;flag;i++){
    flag = false;
    for(int j=N-1;j>=i+1;j--){
      if(V[j]<V[j-1]){
        swap(V[j],V[j-1]);
        count[j]++;
        count[j-1]++;
        swap(count[j],count[j-1]);
        if(bit[j]!=bit[j-1]){
          bit.flip(j);
          bit.flip(j-1);
        }
        flag=1;
        ret++;
      }
    }
  }

  for(int i=0;i<N;i++){
    if(count[i]%2!=bit[i]) return 1001001001;
  }
  return ret;
}

int main() {
  int N,inf=1001001001;
  cin >> N;
  vector<int> A(N),B(N);
  for(int i=0;i<N;i++) cin >> A[i];
  for(int i=0;i<N;i++) cin >> B[i];

  int ans = inf;
  for(int i=0;i<(1<<N);i++){
    bitset<18> bit(i);
    vector<int> V(N);
    for(int j=0;j<N;j++){
      if(bit[j]) V[j] = B[j];
      else V[j] = A[j];
    }
    ans = min(ans,solve(V,N,bit));
  }

  if(ans==inf) cout << -1 << endl;
  else cout << ans << endl;
  return 0;
}

