	for(int i=0; i<n; i++){
		cin >> a[i];
	}
	for(int i=0; i<n; i++){
		cin >> b[i];
	}

	// dp[i][j]: iの組み合わせで選んで、最後がjのときの最小コスト
	vector<vector<int>> dp(1<<n, vector<int>(n, inf));
	for(int i=0; i<n; i++){
		dp[1<<i][i] = i;
	}
	for(int i=1; i<(1<<n); i++){
		int count = popcount(i);
		for(int j=0; j<n; j++){
			if(!(i>>j&1)) continue;
			if(dp[i][j] == inf) continue;
			//cout << i << " " << j << endl;
			int last = ((count-1-j)%2==0)? a[j]: b[j];
			for(int k=0; k<n; k++){
				if(i>>k&1) continue;
				//cout << i << " " << j << " " << k << endl;
				int newlast = ((count-k)%2==0)? a[k]: b[k];
				//cout << "last " << last << " " << newlast << endl;
				if(newlast < last) continue;
				int cost = max(k-count, 0);
				int newset = i|(1<<k);
				dp[newset][k] = min(dp[newset][k], dp[i][j]+cost);
			}
		}
	}
	/*
	for(int i=0; i<(1<<n); i++){
		cout << "i= " << i << endl;
		for(int j=0; j<n; j++){
			cout << dp[i][j] << endl;
		}
	}
	*/
	int ans = *min_element(dp[(1<<n)-1].begin(), dp[(1<<n)-1].end());
	if(ans == inf) ans = -1;
	cout << ans << endl;
	return 0;
}

