void ReadInput()
{
    cin >> n;
    a.resize(n);
    b.resize(n);
    for(int i = 0; i < n; ++i)
        cin >> a[i];
    for(int i = 0; i < n; ++i)
        cin >> b[i];
}

void Init()
{
    val.resize(n, vector<int>(n));
    for(int i = 0; i < n; ++i)
        for(int j = 0; j < n; ++j)
            val[i][j] = (i % 2 == j % 2) ? a[j] : b[j];
}

inline int bit(int k, int x)
{
    return (x >> k & 1);
}

inline void minmim(int&tar, int val)
{
    if(tar > val) tar = val;
}

void Solve()
{
    dp.resize((1 << n), vector<int>(lim + 5, INF));
    dp[0][0] = 0;
    for(int mask = 0; mask < (1 << n); ++mask)
    {
        int pos = __builtin_popcount(mask);
        for(int lst = 0; lst < lim; ++lst)
        {
            int cost = 0;
            for(int i = 0; i < n; ++i)
            {
                if(bit(i, mask)) continue;
                if(val[pos][i] >= lst)
                    minmim(dp[mask | (1 << i)][val[pos][i]], dp[mask][lst] + cost);
                ++cost;
            }
        }
    }
    int ans = INF;
    for(int lst = 1; lst < lim; ++lst)
        minmim(ans, dp[(1 << n) - 1][lst]);
    if(ans == INF) ans = -1;
    cout << ans << '\n';
}

