using vvi = vector<vi>;

vi used, red, blue, perm, s_perm;
int ans = -1, n;

bool valid(int i, int idx){
    if (idx == 0) return true;

    int next;
    if ((i%2) == (idx%2)) next = red[i];
    else next = blue[i];

    int last;
    if ((idx-1)%2 == (perm[idx-1]%2)) last = red[perm[idx-1]];
    else last = blue[perm[idx-1]];

    return next >= last;
}

bool cheap(int idx){
    int temp = 0;
    for (int k = 0; k < idx; k++) {
        for (int l = k + 1; l < idx; l++) {
            if (perm[k] > perm[l])temp++;
        }
    }
    return temp < ans or ans == -1;
}

int cost(){
    int temp = 0;
    for (int k = 0; k < n; k++) {
        for (int l = k + 1; l < n; l++) {
            if (perm[k] > perm[l])temp++;
        }
    }
    return temp;
}

void solve(int idx){
    if (idx == n) {
        int c = cost();
        if (ans != -1) ans = min(ans, c);
        else ans = c;
        s_perm = perm;
    } else if (cheap(idx)){
        for (int i = 0; i < n; i++) {
            if (not used[i] and valid(i, idx)){
                used[i] = true;
                perm[idx] = i;
                solve(idx+1);
                used[i] = false;
            }
        }
    }
}

