void main_() {
  /*
  std::ios::sync_with_stdio(false);
  std::cin.tie(nullptr);
  //*/
  const usize n = scan<usize>();
  struct c_t {
    u32 a, b;
  };
  std::vector<c_t> cs(n);
  for (const auto i : rep(0, n)) {
    std::cin >> cs[i].a;
  }
  for (const auto i : rep(0, n)) {
    std::cin >> cs[i].b;
  }
  const auto get = [&](const usize i, const usize j) {
    return (i ^ j) & 1 ? cs[i].b : cs[i].a;
  };
  auto dp = md_vec(1 << n, n, std::numeric_limits<usize>::max() / 2);
  for (const usize i : rep(0, n)) {
    dp[1 << i][i] = 0;
  }
  for (const usize s : rep(1, 1 << n)) {
    usize pc = 0;
    for (const usize i : rep(0, n)) {
      if (s >> i & 1)
        pc += 1;
    }
    for (const usize i : rep(0, n)) { // next use
      if (s >> i & 1)
        continue;
      usize inv = 0;
      for (const usize j : rep(i + 1, n)) {
        if (s >> j & 1)
          inv += 1;
      }
      for (const usize j : rep(0, n)) { // last used
        if (~s >> j & 1)
          continue;
        if (get(j, pc - 1) > get(i, pc))
          continue;
        chmin(dp[s | (1 << i)][i], dp[s][j] + inv);
      }
    }
  }
  usize ans = std::numeric_limits<usize>::max() / 2;
  for (const usize i : rep(0, n)) {
    chmin(ans, dp.back()[i]);
  }
  if (ans >= std::numeric_limits<usize>::max() / 2) {
    std::cout << "-1" << std::endl;
    return;
  }
  std::cout << ans << std::endl;
}

