#define all(c) (c).begin(), (c).end()
#define REP(s, e, i) for(i=(s); i < (e); ++i)

i64 compute(vvi &count, const vi &A, const vi &B, i64 L, i64 C, i64 M) {
  if(count[L][C] != -2) {
    return count[L][C];
  }

  i64 N = A.size(), i;
  i64 b = 1;
  i64 C1 = C & ~(1LL << L);

  //cout << " call " << L << " " << C << endl;

  i64 ans = -1;
  if(M == 1) {
    ans = L;
  }
  else {
    i64 v_cur = ((M + L + 1) % 2 == 0) ? A[L] : B[L];
    REP(0, N, i) {
      if((C1 & b) != 0) {
	i64 v_prev = ((M + i) % 2 == 0) ? A[i] : B[i];
	if(v_prev <= v_cur) {
	  i64 candidate = compute(count, A, B, i, C1, M-1);
	  if(candidate != -1) {
	    if(ans == -1)
	      ans = candidate;
	    else
	      ans = min(ans, candidate);
	  }
	}
      }
      b *= 2;
    }
    if(ans != -1)
      ans += abs(M - 1 - L);
  }
  //cout << "L " << L << " C " << C << " " << ans << endl;
  count[L][C] = ans;
  return ans;
}

int main(int argc, char *argv[]) {
  i64 N, i;
  cin >> N;
  vi A(N), B(N);
  REP(0, N, i) {
    cin >> A[i];
  }
  REP(0, N, i) {
    cin >> B[i];
  }

  i64 C = 1;
  REP(0, N, i) {
    C = C * 2;
  }

  vvi count(N, vi(C, -2));
  i64 ans = -1;
  REP(0, N, i) {
    i64 ct = compute(count, A, B, i, C-1, N);
    //cout << "AL " << i << " " << ct << endl;
    if(ct != -1) {
      ct /= 2;
      if(ans == -1)
	ans = ct;
      else
	ans = min(ct, ans);
    }
  }
  cout << ans << endl;

  return 0;
}

