bool nondec()
{
    for(int i=0;i<n-1;i++)
    {
        if(tem[i].x>tem[i+1].x||tem[i].k+tem[i+1].k)
        {
            return false;
        }
    }
    return true;
}
void swfl(int x)
{
    st ret={tem[x].x,tem[x].k};
    tem[x]={tem[x+1].x,1-tem[x+1].k};
    tem[x+1]={ret.x,1-ret.k};
}
