const int INF = 1<<29;

int N;
vector<int> A, B;



int solve() {
    vector<vector<int>> dp((1<<N)+10, vector<int>(55, INF));
    dp[0][0] = 0;
    for (int bit = 0; bit < (1<<N); ++bit) {
        int con = 0;
        for (int i = 0; i < N; ++i) if (bit & (1<<i)) ++con;
        map<int,int> ma;
        int iter = con;
        for (int i = 0; i < N; ++i) {
            if (bit & (1<<i)) continue;
            ma[i] = iter++;
        }

        //COUT(bit); COUT(ma);

        for (int s = 0; s <= 50; ++s) {
            if (dp[bit][s] >= INF) continue;

            //cout << bitset<10>(bit) << ", " << s << ": " << dp[bit][s] << endl;

            for (int i = 0; i < N; ++i) {
                if (bit & (1<<i)) continue;
                int dis = abs(ma[i] - con);
                int ns;
                if (abs(i - con) % 2 == 0) ns = A[i];
                else ns = B[i];
                if (ns < s) continue;

                int nbit = bit | (1<<i);
                chmin(dp[nbit][ns], dp[bit][s] + dis);
            }
        }
    }

    int res = INF;
    for (int s = 0; s < 55; ++s) {
        chmin(res, dp[(1<<N)-1][s]);
    }
    if (res < INF) return res;
    else return -1;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    while (cin >> N) {
        A.resize(N);
        B.resize(N);
        for (int i = 0; i < N; ++i) cin >> A[i];
        for (int i = 0; i < N; ++i) cin >> B[i];
        cout << solve() << endl;
    }
}

