using namespace std;

struct P {
	int c;
	int p;
	int i;
};

int count_sort(vector<P>& ps, int n)
{
	int c = 0;
	FOR_LT(i, 0, n) {
		FOR_LT(j, 0, i) {
			if (ps[j].i > ps[i].i) c++;
		}
	}
	return c;
}

