			}
			swap(ps[j], ps[si]);
		}
		if (!is_ok) continue;

		int count = count_sort(ps, n);

		ans = min(ans, count);
	}

	if (ans == INT_MAX) {
		cout << -1 << endl;
	}
	else {
		cout << ans << endl;
	}

	return 0;
}

