    }

    int ans = INF;
    int noBits = (N+1)>>1;
    vector<ii> set1 = vector<ii>();
    vector<ii> set2 = vector<ii>();
    for(int i = (1<<noBits)-1; i < (1<<N); i = nxs(i)){
        //printf("i=%d\n", i);
        set1.clear();
        set2.clear();
        for(int j = 0; j < N; j ++){
            if(i&(1<<j)){
                // Place in first set, parity is even (0-indexed)
                if((j&1) == 0){
                    set1.push_back(ii(A[j], j));
                }else{
                    set1.push_back(ii(B[j], j));
                }
            }else{
                // Place in second set, parity is odd
                if((j&1) == 0){
                    set2.push_back(ii(B[j], j));
                }else{
                    set2.push_back(ii(A[j], j));
                }
            }
        }

        sort(set1.begin(), set1.end());
        sort(set2.begin(), set2.end());

        bool boleh = true;
        for(int j = 0; j < (int)set2.size(); j ++){
