            if(set1[j].first > set2[j].first){
                boleh = false;
                break;
            }

            if( ((N&1) == 0) && j == (int)set2.size()-1 ){
                break;
            }

            if(set1[j+1].first < set2[j].first){
                boleh = false;
                break;
            }
        }

        if(boleh){
            for(int j = 0; j < (int)set2.size(); j ++){
                perm[j<<1] = set1[j].second;
                perm[(j<<1)|1] = set2[j].second;
            }
            if(N&1){
                perm[N-1] = set1[set2.size()].second;
            }

            int inv = 0;
            for(int j = 0; j < N; j ++){
                for(int k = j+1; k < N; k ++){
                    if(perm[j] > perm[k]){
                        inv ++;
                    }
                }
            }

            ans = min(ans, inv);
        }
    }

    if(ans == INF){ans = -1;}
    printf("%d", ans);
    return 0;
}

