const int N = 19, INF = 1000000009;

int n;
int a[N], b[N];

int s[1 << N][N];

int dp[1 << N][N][2];

int main()
{
    scanf("%d", &n);
    for (int i = 0; i < n; ++i)
        scanf("%d", &a[i]);
    for (int i = 0; i < n; ++i)
        scanf("%d", &b[i]);
    for (int x = 0; x < (1 << n); ++x)
    {
        for (int i = n - 1; i >= 0; --i)
        {
            s[x][i] = s[x][i + 1];
            if ((x & (1 << i)))
                ++s[x][i];
        }
    }
    for (int x = 0; x < (1 << n); ++x)
    {
        for (int i = 0; i < n; ++i)
        {
            for (int z = 0; z < 2; ++z)
                dp[x][i][z] = INF;
        }
    }
    for (int x = 0; x < (1 << n); ++x)
    {
        for (int i = 0; i < n; ++i)
        {
            if (!(x & (1 << i)))
            {
                int y = (x | (1 << i));
                int qq = i + s[x][i] - s[x][0];
                int q = s[x][i] + qq;
                q %= 2;
                int u;
                if (q == 0)
                    u = a[i];
                else
                    u = b[i];
                for (int j = 0; j < n; ++j)
                {
                    if ((x & (1 << j)))
                    {
                        if (a[j] <= u)
                            dp[y][i][q] = min(dp[y][i][q], dp[x][j][0] + qq);
                        if (b[j] <= u)
                            dp[y][i][q] = min(dp[y][i][q], dp[x][j][1] + qq);
                    }
                }
                if (x == 0)
                    dp[y][i][q] = min(dp[y][i][q], qq);
            }
        }
    }
    int ans = INF;
    for (int i = 0; i < n; ++i)
    {
        for (int z = 0; z < 2; ++z)
            ans = min(ans, dp[(1 << n) - 1][i][z]);
    }
    if (ans == INF)
        printf("-1\n");
    else
        printf("%d\n", ans);
    return 0;
}

