                vec1[j].first=vec1[j+1].second;
                vec1[j].second=vec1[j+1].first;
                vec1[j+1].first=temp2;
                vec1[j+1].second=temp1;
            }
        }
        int fl=0;
        forn(j,n-1){
            if(vec1[j]>vec1[j+1]){fl=1;break;}
        }
        if(fl==0)dp[i]=1;
    }
    int ans=INT_MAX;
    forn(i,N)if(dp[i]==1)ans=min(ans,__builtin_popcount(i));
    if(ans!=INT_MAX)cout<<ans;
    else cout<<-1;

	return 0;
}

