constexpr ll infl = 1000000000000000007LL;
constexpr int inf = 1000000007;

int main() {
    int n; cin >> n;
    vector<int> ab[2];
    for (int i = 0; i < n; ++i) {
        int a; cin >> a;
        ab[0].push_back(a);
    }
    for (int i = 0; i < n; ++i) {
        int a; cin >> a;
        ab[1].push_back(a);
    }

    vector<int> c(n);
    vector<int> d(n);
    vector<int> e(n);
    vector<bool> used(n);
    int ans = inf;
    for (int bit = 0; bit < (1 << n); ++bit) {
        for (int i = 0; i < n; ++i) {
            c[i] = d[i] = ab[bit >> i & 1][i];
            used[i] = false;
        }
        sort(d.begin(), d.end());
        bool check = true;
        int tans = 0;
        for (int i = 0; i < n; ++i) {
            auto its = lower_bound(d.begin(), d.end(), c[i]);
            auto ite = upper_bound(d.begin(), d.end(), c[i]);
            bool found = false;
            for (auto it = its; it != ite; ++it) {
                int index = it - d.begin();
                if (!used[index] && abs(index - i) % 2 == (bit >> i & 1)) {
                    found = true;
                    used[index] = true;
                    e[i] = index;
                }
            }

            if (!found) check = false;
        }

        if (check) {
            int tans = 0;
            for (int i = n - 1; i >= 0; --i) {
                for (int j = i; j < n - 1; ++j) {
                    if (e[j] > e[j + 1]) {
                        swap(e[j], e[j + 1]);
                        ++tans;
                    }
                }
            }
            ans = min(ans, tans);
        }
    }

    if (ans != inf) cout << ans << endl;
    else cout << -1 << endl;
    return 0;
}

