const int MAXN = (1<<N);
const int MAXVAL = 1e9;

int dp[N + 1][MAXN];

int A[N + 5], B[N + 5];
int n;

int solve(int pre, int bmask) {
	if(bmask == 0) return 0;
	int &res = dp[pre][bmask];
	if(res != -1) return res;
	res = MAXVAL;
	int getID = n + 1 - __builtin_popcount(bmask);
	int pval = A[pre];
	if((getID + pre + 1) % 2) pval = B[pre];
	int pass = getID - 1;
	for(int i = 1;i <= n;i++) {
		if(bmask & (1<<i)) {
			int curval = A[i];
			if((getID + i) % 2) curval = B[i];
			if(pval > curval) continue;
			res = min(res, solve(i, bmask ^ (1<<i)) + (i + pass - getID));
		} else pass--;
	}
	return res;
}

