template<class T> class segtree {
    int n = 1;
    vector<T> dat;
    T def;

public:
    segtree(int _n, T _def) : def(_def) {
        while (n < _n)n *= 2;
        dat.resize(2 * n, def);
    }

    T fun(T x, T y) { return x + y; }

    void update(int i, T a) {
        i += n;
        dat[i] += a;
        while (i > 1) {
            i /= 2;
            dat[i] = fun(dat[2 * i], dat[2 * i + 1]);
        }
    }

    T value(int l, int r) {
        l += n, r += n;

        T ret = def;
        for (; l < r; l /= 2, r /= 2) {
            if (l & 1) {
                ret = fun(ret, dat[l]);
                l++;
            }
            if (r & 1) {
                --r;
                ret = fun(ret, dat[r]);
            }
        }

        return ret;
    }
};

