            if ((i&1)^is_back) {
                odd.push_back({is_back ? b[i] : a[i], i});
            } else {
                even.push_back({is_back ? b[i] : a[i], i});
            }
        }
        sort(all(even));
        sort(all(odd));

        bool ng = false;
        {
            int E = even.size();
            int O = odd.size();
            if (n & 1) {
                if (E-O != 1) ng = true;
            } else {
                if (E != O) ng = true;
            }
        }

        {
            int back_count = 0;
            rep(i,n){
                if(mask & bit(i)) back_count++;
            }
            if (back_count & 1) {
                ng = true;
            }
        }
        if (ng) continue;

        {
            rep(i,n-1){
                if (i % 2 == 0) {
                    if (even[i/2] > odd[i/2]) ng = true;
