const int inf=0x3f3f3f3f;
using namespace std;
struct card{
    int a,b;
}pok[20];
struct card2{
    int x,pos;
    card2(int x,int pos):x(x),pos(pos){}
};
int main(){
    int n;
    cin>>n;
    for(int i=1;i<=n;++i){
        cin>>pok[i].a;
    }
    for(int i=1;i<=n;++i){
        cin>>pok[i].b;
    }
    int ans=0;
    vector<int>v;
    vector<card2>c;
    bool flag;
    int mi=inf;
    for(int i=0;i<1<<n;++i){
        int ans=0;
        c.clear();
        v.clear();
        //cout<<i<<endl;
        for(int j=0;j<n;++j){
            if(i>>j&1){
                v.emplace_back(pok[j+1].b);
                c.emplace_back(card2(pok[j+1].b,1));
            }
            else{
                v.emplace_back(pok[j+1].a);
                c.emplace_back(card2(pok[j+1].a,0));
            }
        }
        sort(v.begin(),v.end());
        for(int j=0;j<n;++j){
            flag=true;
            //cout<<"v[j]=="<<v[j]<<endl;
            for(int k=j;k<n;++k){
                //cout<<"c[k].x=="<<c[k].x<<endl;
                if(c[k].x==v[j]&&((k-j)&1)==c[k].pos){
                    flag=false;
                    ans+=k-j;
                    for(int l=k-1;l>=j;--l){
                        c[l].pos^=1;
                        swap(c[l],c[l+1]);
                    }
                    break;
                }
            }
            if(flag)break;
        }
        if(flag)continue;
        else mi=min(ans,mi);
    }
    cout<<(mi==inf?(-1):mi)<<endl;
}

#include <bits/stdc++.h>
using namespace std;
const int MX=1e9;
int dp[1000000][52];
int c[1000000][20];
int n;
int a[20];
int b[20];
int main(){
    cin.tie(0);
    ios_base::sync_with_stdio(0);
    cin>>n;
    int i,j,k;
    for(i=0 ; i<n ; i++)cin>>a[i];
    for(i=0 ; i<n ; i++)cin>>b[i];
    for(i=0 ; i<=50 ; i++)dp[0][i]=0;
    for(i=1 ; i<(1<<n) ; i++)for(j=0 ; j<=50 ; j++)dp[i][j]=MX;
    for(i=1 ; i<(1<<n) ; i++){
        int k=n;
        for(j=n-1 ; j>=0 ; j--){
            if(((1<<j)&i)==0){
                c[i][j]=k--;
            }
        }
    }
    for(i=1 ; i<(1<<n) ; i++){
        int t=i;
        int s=0;
        while(t){
            s+=t%2;
            t/=2;
        }
        for(k=0 ; k<n ; k++){
            if(((1<<k)&i)==0)continue;
            if(s%2!=k%2){
                dp[i][a[k]]=min(dp[i][a[k]],dp[i^(1<<k)][a[k]]+abs(s-c[i^(1<<k)][k]));
            }
            else{
                dp[i][b[k]]=min(dp[i][b[k]],dp[i^(1<<k)][b[k]]+abs(s-c[i^(1<<k)][k]));
            }
        }
        for(j=1 ; j<=50 ; j++)dp[i][j]=min(dp[i][j],dp[i][j-1]);

    }
    int ans=dp[(1<<n)-1][50];
    if(ans<MX)cout<<ans;
    else cout<<-1;
    return 0;
}

