#include <bits/stdc++.h>
using namespace std;
const int MAX_N = 20;
const int INF = 0x3f3f3f3f;

int n, a[MAX_N], b[MAX_N];
struct Card
{
    int x, p;
    Card(int x=0, int p=0):x(x), p(p) {}
}c[MAX_N];
int d[MAX_N];

int solve(int S)
{
    for (int i = 0; i < n; i++)
    {
        if (S & (1<<i))
        {
            c[i] = Card(b[i], 1);
            d[i] = b[i];
        }
        else
        {
            c[i] = Card(a[i], 0);
            d[i] = a[i];
        }
    }
    sort(d, d+n);
    int ans = 0;
    for(int i = n-1; i >= 0; i--)
    {
        bool flag = false;
        for (int j = i; j >= 0; j--)
        {
            if (c[j].x == d[i] && c[j].p == (i-j&1))
            {
                flag = true;
                ans += i-j;
                for (int k = j; k < i; k++)
                {
                    c[k+1].p ^= 1;
                    swap(c[k], c[k+1]);
                }
                break;
            }
        }

        if (!flag) return INF;
    }
    return ans;
}

