{
    scanf("%d", &n);
    for (int i = 0; i < n; i++) scanf("%d", &a[i]);
    for (int i = 0; i < n; i++) scanf("%d", &b[i]);

    int ans = INF;
    for (int S = 0; S < (1<<n); S++)
    {
        ans = min(ans, solve(S));
    }
    if (ans == INF) ans = -1;
    printf("%d\n", ans);
    return 0;
}

