ll solve(ll d){
    rep(i,n)if(d&(1LL<<i))swap(a[i],b[i]);
    pair<ll,ll> v[18];
    rep(i,n)v[i]=make_pair(a[i],i);
    sort(v,v+n);
    ll ans=0;
    ll bef=-1,ecnt=0,obef=-1;
    rep(i,n){
	ll cnt=0;
	rep(j,n){
	    if(v[i].first==v[j].first)continue;
	    bool vl=(v[j].first<v[i].first);
	    bool vr=(v[j].second<v[i].second);
	    cnt+=vl^vr;
	}
	if(d&(1LL<<v[i].second))cnt++;
	if(v[i].first!=bef){
	    if(~obef)ans=1e9;
	    obef=-1,ecnt=0;
	    bef=v[i].first;
	}
	ecnt++;
	if(cnt%2==1){
	    if(~obef)ans+=(ecnt-obef)*2,obef=-1;
	    else obef=ecnt;
	}
	if(d&(1LL<<v[i].second))cnt--;
	ans+=cnt;
    }
    if(~obef)ans=1e9;
    rep(i,n)if(d&(1LL<<i))swap(a[i],b[i]);
    if(ans<1e6&&ans%2==1)assert(0);
    return ans/2;
}
