template<typename T> class BIT{
public:
	int size;
	vector<T> arr;
	BIT(int n){
		size=n+5;
		arr.resize(size);
	}
	void add(int i,T v){
		for(int x=i+1;x<size;x+=(x&(-x))) arr[x]+=v;
	}
	T sum(int i){
		i=min(i,size-2);
		T res=0;
		for(int x=i+1;x>0;x-=(x&(-x))) res+=arr[x];
		return res;
	}
};
long long inversion_number(vector<int> &a){
	BIT<int> bit(100);
	int n=a.size();
	long long res=0;
	for(int i=n-1;i>=0;i--){
		res+=bit.sum(a[i]-1);
		bit.add(a[i],1);
	}
	return res;
}
