using namespace std;
using ll = int64_t;

struct Card {
  int A, B;
};

struct Range {
  int left, right;
};

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);

  int N;
  cin >> N;
  vector<Card> cards(N);
  for (auto& card : cards) {
    cin >> card.A;
  }
  for (auto& card : cards) {
    cin >> card.B;
  }
  vector<int> order(N);
  vector<Range> ranges(N);
  vector<char> used(N);
  int min_operations = numeric_limits<int>::max();
  int result_mask = -1;
  for (int mask = 0; mask < (1 << N); mask++) {
    if (__builtin_popcount(mask) % 2 != 0) {
      continue;
    }
    for (int i = 0; i < N; i++) {
      if ((mask >> i) & 1) {
        order[i] = cards[i].B;
      } else {
        order[i] = cards[i].A;
      }
    }
    sort(all(order));
    // cerr << "mask: " << mask << endl;
    for (int i = 0; i < N; i++) {
      int number;
      if ((mask >> i) & 1) {
        number = cards[i].B;
      } else {
        number = cards[i].A;
      }
      int left = N, right = -1;
      for (int j = 0; j < N; j++) {
        if (order[j] == number) {
          left = min(left, j);
          right = max(right, j);
        }
      }
      // cerr << "i: " << i << " " << number << " " << left << " " << right << endl;
      assert(left <= right);
      ranges[i] = Range{left, right};
    }
    int operations = 0;
    bool fail = false;
    fill(all(used), false);
    for (int i = 0; i < N && !fail; i++) {
      int odd = (mask >> i) & 1;
      int closest = -1;
      // cerr << "w: " << i << " " << odd << endl;
      for (int j = ranges[i].left; j <= ranges[i].right; j++) {
        if (!used[j] && abs(j - i) % 2 == odd) {
          // cerr << "t: " << j << endl;
          if (closest == -1 || abs(j - i) < abs(closest - i)) {
            closest = j;
          }
        }
      }
      // cerr << "c: " << i << " " << closest << endl;
      if (closest == -1) {
        fail = true;
      } else {
        used[closest] = true;
        operations += abs(closest - i);
      }
    }
    if (!fail && operations < min_operations) {
      min_operations = operations;
      result_mask = mask;
    }
  }
  if (min_operations == numeric_limits<int>::max()) {
    cout << -1 << endl;
    return 0;
  }
  assert(result_mask != -1);
  assert(min_operations % 2 == 0);
  cout << min_operations / 2 << endl;



  return 0;
}

