int dp[19][262144][51];

int solve(int N, vi& a, vi& b) {
    vi u(N), v(N);
    rep(i,N){
        if (i % 2 == 0) {
            u[i] = a[i]; v[i] = b[i];
        } else {
            u[i] = b[i]; v[i] = a[i];
        }
    }
    mset(dp, 0x7f);

    dp[0][0][0] = 0;
    int P = 1 << N;
    rep(i,N){
        rep(p,P){
            rep(last,51){
                if (dp[i][p][last] == 0x7f7f7f7f) continue;
                rep(j,N){
                    int mj = 1 << j;
                    if (p & mj) continue;
                    int d = ABS(j-i)%2;
                    int x = d ? b[j] : a[j];
                    if (last > x) continue;
                    int sw = (i < j)? j-i : 0;
                    amin(dp[i+1][p|mj][x], dp[i][p][last]+sw);
                }
            }
        }
    }
    int res = 0x7f7f7f7f;
    rep(last,51){
        amin(res, dp[N][P-1][last]);
    }
    if (res == 0x7f7f7f7f) return -1;
    return res;
}

int main() {
    int N; cin >> N;
    vi a(N), b(N);
    rep(i,N) cin >> a[i];
    rep(i,N) cin >> b[i];
    cout << solve(N,a,b) << endl;
    return 0;
}

