int main() {
  int n;
  cin >> n;
  vector<vector<int>> a(2, vector<int>(n));
  for (auto &e : a[0]) cin >> e;
  for (auto &e : a[1]) cin >> e;

  int r = 1e9;
  for (int k = 0; k < (1 << n); k++) {
    bitset<18> flipped(k);
    if (flipped.count() % 2) continue;
    vector<int> u(n), v;
    for (int i = 0; i < n; i++) u[i] = a[flipped[i]][i];
    v = u;
    sort(v.begin(), v.end());

    int t = 0;
    bitset<18> used;
    for (int i = 0; i < n; i++) {
      bool found = false;
      for (int j = 0; !found && j < n; j++) {
        if (used[j]) continue;
        if (u[j] == v[i] && abs(i - j) % 2 == flipped[j]) {
          t += abs(i - j);
          found = true;
          used[j] = true;
        }
      }
      if (!found) {
        t = 2e9;
        break;
      }
    }
    if (t != 2e9) {
      for (auto e : v) cerr << e << ' ';
      cerr << endl;
    }
    r = min(r, t / 2);
  }
  if (r == 1e9) return 1;
  cout << (r == 1e9 ? -1 : r) << endl;
}

