	REP(i, lpmax) {
		vector<pii> ca, cb;

		REP(j, n) {
			if (bitcheck(i, j)) {
				ca.push_back({ a[j],j });
			}
			else
				cb.push_back({ b[j],j });
		}
		if (cb.size() != n / 2) continue;

		sort(ALL(ca));
		sort(ALL(cb));
		bool ok = true;
		vector<pii> s(n);
		vector<int> num(n);
