int cnt_(vector<int> &v, int op) {
    if (v.empty()) return 0;
    int cnt[20]={},res=0;
    rep(i,v.size()) {
        int idx=i;
        repo(j,i+1,v.size()) if (v[i] > v[j]) idx = j;
        if (i != idx) {
            swap(v[i], v[idx]);
            cnt[i]++, cnt[idx]++;
            res++;
        }
    }
    int cntcnt=0;
    rep(i,v.size()) if (cnt[i]%2 != op) cntcnt++;
    if (cntcnt%2 || (cntcnt && cntcnt < 3)) return -1;
    res += (cntcnt/4)*3+((cntcnt%4)/2)*4;
    return res;
}

