int count_sort(vector<P>& ps, int n)
{
	int c = 0;
	FOR_LT(i, 0, n) {
		FOR_LT(j, 0, i) {
			if (ps[j].i > ps[i].i) c++;
		}
	}
	return c;
}

int main()
{
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);
	cout << fixed << setprecision(20);

	int n; cin >> n;
	vector<int> as(n);
	for (int i = 0; i < n; i++) {
		cin >> as[i];
	}
