            while(now<n){
                if(visited[now]==0 && mat[now][count%2]==num){
                    visited[now]=1;
                    time += count;
                    break;
                }
                else if(visited[now]==1){
                    now++;
                }
                else{
                    now++;
                    count++;
                }
            }
