				swap += std::abs(2 * i + 1 - for_odd[i].first);
			}
			min_swap = std::min(min_swap, swap >> 1);
		}
	}
	if (min_swap == INT_MAX) {
		std::cout << "-1\n";
	}
	else {
		std::cout << min_swap << '\n';
	}
}

