constexpr int INF = INT_MAX;

int dfs(int n, int c, const int N, const int MAX, vector<int>& A, vector<int>& B) {
  if(is_sorted(begin(A), end(A)))return c;
  if (n + 1 == MAX)return INF;
  int res = INF;
  for (int i = 0; i < N; ++i) {
    if ((n >> i) & 1)continue;
    int nxt = n | (1 << i);
    swap(A[i], B[i + 1]);
    swap(B[i], A[i + 1]);
    int tmp = dfs(nxt, c + 1, N, MAX, A, B);
    swap(A[i], B[i + 1]);
    swap(B[i], A[i + 1]);
    res = min(res, tmp);
  }
  return res;
}

