int bubbleSort(vector <pair <int, int > >& c, int ptn)
{
	int num = 0;

	const int N = SZ(c);


	for (int i=0;i<N - 1;i++)
	{
		for (int k = N-1; k >= i+1; --k)
		{
			if (c[k].first < c[k - 1].first)
			{
				swap(c[k], c[k - 1]);
				num++;
			}
		}
	}

	for (int i=0;i<N - 1;i++)
	for (int k = 0; k < N - 1; ++k)
	{
		bool checkK = (abs(c[k].second - k) % 2 == 0) ^ IsBit(ptn, k);
		bool checkK1 = (abs(c[k+1].second - (k+1)) % 2 == 0) ^ IsBit(ptn, k+1);
		if (checkK && checkK1 && c[k].first == c[k + 1].first)
		{
			swap(c[k], c[k + 1]);
			num++;
		}
	}


	return num;
}





int main()
{
	ios::sync_with_stdio(false);
	cin.tie(nullptr);

	ll ret = BIGLL;

	int N;
	cin >> N;

	vector <int> a = in(N);
	vector <int> b = in(N);

	for (int ptn = 0; ptn < (1LL << (N)); ++ptn)
	{
		vector <pair <int, int > > c;
		int x = 0;
		for (int k = 0; k < N; ++k)
		{
			if (IsBit(ptn, k))
			{
				c.emplace_back(a[k], k);
			}
			else
			{
				c.emplace_back(b[k], k);
				x++;
			}
		}

		if (x % 2 == 1) continue;

		ll num = bubbleSort(c, ptn);

		bool ok = true;
		for (int k = 0; k < N; ++k)
		{
			if ( (abs(c[k].second - k)%2==0) ^ (IsBit(ptn,k)) )
			{
				ok = false;
				break;
			}
		}

		if (ok)
		{
			amin(ret, num);
		}
	}

	if (ret == BIGLL)
	{
		ret = NG;
	}

	cout << setprecision(20) << ret << endl;

	return 0;
}

