int main() {
    int n;
    cin >> n;
    vector<int> A(n), B(n);
    for (auto &&i : A) scanf("%d", &i);
    for (auto &&i : B) scanf("%d", &i);
    auto dp = make_v(n, 1 << n, INF<int>);
    auto cnt = make_v(1 << n, 0);
    for (int i = 0; i < n; ++i) {
        dp[i][1 << i] = i;
    }
    for (int i = 0; i < 1 << n; ++i) {
        cnt[i] = __builtin_popcount(i)-1;
    }
    auto f = [&](int i, int j){ // 添字iをjに置く
        cout << i << " " << j << " " << (abs(i-j)&1 ? B[i] : A[i]) << "\n";
        if(abs(i-j)&1) return B[i];
        else return A[i];
    };
    for (int S = 1; S < 1 << n; ++S) {
        if(cnt[S] < 1) continue;
        for (int i = 0; i < n; ++i) {
            if(!(S & (1 << i))) continue;
            int from = S ^ (1 << i);
            for (int j = 0; j < n; ++j) {
                if(!(from & (1 << j))) continue;
                if(f(j, cnt[S]-1) <= f(i, cnt[S])){
                    dp[i][S] = min(dp[i][S], dp[j][from]+abs(i-cnt[S]));
                }
            }
        }
    }
    int ans = INF<int>;
    for (int i = 0; i < n; ++i) {
        ans = min(ans, dp[i].back());
    }
    if(ans == INF<int>){
        puts("-1");
    }else {
        cout << ans/2 << "\n";
    }
    return 0;
}

