void go(int pos,int lst,int cost)
{
	if(pos==N)
	{
		cmin(ans,cost);
		return;
	}
	if(cost>=ans) return;
	int ncost=0;
	for(int i=0;i<N;i++)
	{
		if(!used[i])
		{
			int& cur=a[i][abs(pos-i)%2];
			if(lst<=cur)
			{
				int cnt=0;
				for(int j=0;j<N;j++)
				{
					if(i!=j && !used[j] && max(a[j][0],a[j][1])>=cur) cnt++;
				}
				if(cnt>=N-1-pos)
				{
					used[i]=true;
					go(pos+1,cur,cost+ncost);
					used[i]=false;					
				}
			}
			ncost++;
		}
	}
}

