    for(int i=0;i<M*2-1;i++)  dat.push_back(num);
  }
  void update(ll x, ll k, ll l=0, int r=-1){
    if(r==-1) r = M;
    k+=M-1;
    dat[k] += x;
    while(k>0) k = (k-1)/2, dat[k] += x;
  }
  ll query(ll a, ll b=-1, ll k=0, ll l=0, ll r=-1){
    if(r==-1) r = M;
    if(b==-1) b = M;
    if(r<=a || b<=l) return 0;
    if(a<=l && r<=b) return dat[k];
    ll A = query(a, b, k*2+1, l, (l+r)/2);
    ll B = query(a, b, k*2+2, (l+r)/2, r);
    return A + B;
  }
};
//-------------------------------------------------------------------
int main(int argc, char const *argv[]) {
  ll n;std::cin >> n;
  vll a(n), b(n);
  re(i, n) std::cin >> a[i];
  re(i, n) std::cin >> b[i];
  ll ans = 1000000000;

  for(int i=0;i<(1<<n);i++){
    ll tmp = 0;
    bitset<18> k(i);
    vll num(n), x(n, 0);;
    vvl z = vv(n, 3, 0, ll);
    re(j, n) {
      num[j] = (k[j]?b[j]:a[j]);
      z[j] = vll{num[j], j, 0};
    }
    segtree seg(51, 0), rev(51, 0);
    for(int j=0;j<n;j++) {
      ll q = seg.query(num[j]+1, 51);
      tmp += q, x[j]+=q;
      seg.update(1, num[j]);
    }
    for(int j=n-1;j>=0;j--){
      ll q = rev.query(1, num[j]);
      x[j]+=q;
      rev.update(1, num[j]);
    }
    re(j, n) if(k[j]!=x[j]%2) z[j][2] = 1;
    sort(all(z));
    bool flag = true;
    re(j, n){
      if(z[j][2]==0) continue;
      if(z[j][2]&&(j==n-1||z[j][0]!=z[j+1][0])) {
        flag = false;
        break;
      }
      tmp += 1;
      z[j][2] = 0, z[j+1][2] = (z[j+1][2]==0?1:0);
    }
    if(flag) ans = min(tmp, ans);
  }
  std::cout << (ans==1000000000?-1:ans) << '\n';
  return 0;
}

