    for(int i = 0; i < n; i++)std::cin >> a[i];
    for(int i = 0; i < n; i++)std::cin >> b[i];

    std::vector<Pi> vec(n);

    //bit全探索
    for(int bit = 0; bit < (1LL << n); bit++){
        std::vector<Pi> ma(n);
        int all_cnt = 0;


        for(int i = 0; i < n; i++){
            if(bit & (1LL << i)){
                ma[i].first  = a[i];
                ma[i].a_or_b = false;
                ma[i].index = i;
                ma[i].second = 0;
