int mat[20][2]={};
int out[20]={};

int get(int num, int keta){
    REP(i,keta){
        int flag = num%2;
        out[i]=mat[i][flag];
        num/=2;
    }
    sort(out,out+keta);
}

int main(){
    int n;
    int a,b;
    int visited[20]={};
    int rotate[20]={};
    int min = 100000;
    scanf("%d",&n);
    REP(i,n){
        scanf("%d",&a);
        mat[i][0]=a;
    }
    REP(i,n){
        scanf("%d",&b);
        mat[i][1]=b;
    }
    REP(i,2<<(n-1)){
        get(i,n);
        REP(j,20)visited[j]=0;
        REP(j,20)rotate[j]=0;
        int time=0;
        REP(j,n){
            int now=0;
            int num=out[j];
            int count=0;
            while(now<n){
                if(visited[now]==0 && mat[now][(count%2+rotate[now])%2]==num){
                    visited[now]=1;
                    time += count;
                    break;
                }
                else if(visited[now]==1){
                    now++;
                }
                else{
                    rotate[now] = 1-rotate[now];
                    now++;
                    count++;
                }
            }
        }
        int flag=1;
        REP(j,n)if(visited[j]==0)flag=0;
        if(flag==1)if(min>time)min=time;

        //REP(j,n)printf("%d,",out[j]);
        //if(flag)printf("   %d###\n",time);
        //else printf("   -1###\n");
    }
    if(min==100000)printf("-100\n");
    else printf("%d\n",min);
    return 0;
}

