                if(abs(Y[j].second-j)%2!=X[Y[j].second]) z=0;
            }
        }
        if(z){
            vec Z;
            rep(j,n) Z.push_back(Y[j].second);
            int c=0;
            rep(j,n){
                rep(k,n-j-1) if(Z[j]>Z[k+j+1]) c++;
            }
            ans=min(c,ans);
        }
    }
    if(ans==1e9) cout<<-1;
    else cout<<ans;
}

