int f(vector<int> v) {
	int res = 0;
	for (int i = 0; i < v.size(); i++) {
		// cout << i << " ";
		for (int j = i + 1; j < v.size(); j++) {
			if (v[i] > v[j]) res++;
		}
	}
	// cout << endl;
	return res;
}

void dfs(const vector<pair<int, int>>& vp1, 
	const vector<pair<int, int>>& vp2,
	int index1, int index2, int last,
	vector<int> seq, vector<int> v, int& res) {
	if (seq.size() == vp1.size()) {
		int r = f(seq);
		if (res == -1 || r < res)
			res = r;
	}

	if (seq.size() % 2 == 0) {
		while (index1 < vp1.size()) {
			if (vp1[index1].first >= last && v[index1] == 0) {
				seq.push_back(vp1[index1].second);
				v[vp1[index1].second] = 1;
				dfs(vp1, vp2, index1 + 1, index2, vp1[index1].first, seq, v, res);
				seq.pop_back();
				v[vp1[index1].second] = 0;
			}
			index1++;
		}
	}
	else {
		while (index2 < vp2.size()) {
			if (vp2[index2].first >= last && v[index2] == 0) {
				seq.push_back(vp2[index2].second);
				v[vp2[index2].second] = 1;
				dfs(vp1, vp2, index1, index2 + 1, vp2[index2].first, seq, v, res);
				seq.pop_back();
				v[vp2[index2].second] = 0;
			}
			index2++;
		}
	}
}

