				vec.pb(b[j]);
			}
		}
		int x = odd.size();
		int y = even.size();
		if (x != y && x != y + 1) continue;
		sort(all(odd)); sort(all(even));
		vector<int> check;
		rep(j, y) {
			check.pb(odd[j]);
			check.pb(even[j]);
		}
		if (x == y + 1) check.pb(odd[y]);
		bool ok = true;
		rep(j, n - 1) {
			if (check[j] > check[j + 1]) ok = false;
		}
		if (!ok) continue;
		int cnt = 0;
		rep(j, n) {
			for (int k = j + 1; k < n; k++) {
				if (vec[j] > vec[k]) cnt++;
			}
		}
		chmin(ans, cnt);
	}
	cout << (ans == INF ? -1 : ans) << endl;
}

