        }
    }
    for(LL i = 0; i < n; ++i){
        LL v;
        cin >> v;
        if((i&1) == 0){
            b_odd.emplace_back(v, i);
        }else{
            a_odd.emplace_back(v, i);
        }
    }
    sort(a_even.begin(), a_even.end());
    sort(b_even.begin(), b_even.end());
    sort(a_odd.begin(), a_odd.end());
    sort(b_odd.begin(), b_odd.end());
    /*
