int check(int *c, int n, int s) {
    int d[n];
    memcpy(d, c, sizeof d);
    sort(d, d+n);
    bool used[n];
    memset(used, 0, sizeof used);
    int ans = 0;
    for (int i = 0; i < n; i++) {
        int v = c[i];
        bool ok = false;
        for (int j = ((s >> i) & 1) ? 1 ^ (i % 2) : i % 2; j < n; j += 2) {
            if (d[j] == v && !used[j]) {
                used[j] = true;
                ok = true;
                ans += abs(i - j);
                // cerr << i << ' ' << j << endl;
                break;
            }
        }
        if (!ok) return -1;
    }
    return ans/2;
}

