const int inf=5000000000000000ll;

int N;
int a[20][2];

int ans=inf;
bool used[20];

void go(int pos,int lst,int cost)
{
	if(pos==N)
	{
		cmin(ans,cost);
		return;
	}
	if(cost>=ans) return;
	int ncost=0;
	for(int i=0;i<N;i++)
	{
		if(!used[i])
		{
			if(lst<=a[i][abs(pos-i)%2])
			{
				used[i]=true;
				go(pos+1,a[i][abs(pos-i)%2],cost+ncost);
				used[i]=false;
			}
			ncost++;
		}
	}
}

