template<class T>
class SegmentTree {
private:
	const T initialValue = 0;
	const T ignoreValue = 0;

	const ll m_size;
	vector<T> m_node;

	ll calcSize(ll n) {
		ll size = 1;
		while (size < n) {
			size *= 2;
		}
		return size;
	}

	/**
	 * 値の更新(更新:=, 加算:+=, etc...)
	 */
	void update(ll k, T x) {
		m_node[k] += x;
	}

	/**
	* 値の併合
	*/
	T merge(T xl, T xr) {
		return xl + xr;
	}
public:
	SegmentTree(ll n) :
		m_size(calcSize(n)),
		m_node(m_size * 2 - 1, initialValue) {}

	void add(ll itr, T val) {
		ll i = itr + m_size - 1;
		update(i, val);

		while (i > 0) {
			i = (i - 1) / 2;
			m_node[i] = merge(m_node[i * 2 + 1], m_node[i * 2 + 2]);
		}
		/**
		cout << "-- tree -- " << endl;
		REP(i, 2 * m_size - 1) {
			cout << m_node[i] << endl;
		}
		/*//**/
	}

	T query(ll a, ll b) { return query(a, b + 1, 0, 0, m_size); }
	T query(ll a, ll b, ll k, ll l, ll r) {
		if (r <= a || b <= l) { return ignoreValue; }
		if (a <= l && r <= b) { return m_node[k]; }
		return merge(
			query(a, b, 2 * k + 1, l, (l + r) / 2),
			query(a, b, 2 * k + 2, (l + r) / 2, r)
		);
	}
};

signed main() {
	ll n;
	cin >> n;
	VL a(n), b(n);
	cin >> a >> b;

	ll ans = 1e10;
	REP(i, 1 << n) {
		V<PAIR> odd, even;
		odd.reserve(n), even.reserve(n);
		REP(j, n) {
			if (((i >> j) & 1) ^ (j & 1)) {
				odd.emplace_back((j & 1) ? a[j] : b[j], j);
			} else {
				even.emplace_back((j & 1) ? b[j] : a[j], j);
			}
		}
		if (even.size() != (n + 1) / 2 || odd.size() != n / 2) { continue; }
		sort(even); sort(odd);

		bool ok = true;
		V<PAIR> all; all.reserve(n);
		REP(i, n) {
			if ((i + 1) < n && even[i / 2].first > odd[(i + 1) / 2].first) { ok = false; break; }
			all.emplace_back(even[i / 2]);
			std::swap(even, odd);
		}
		if (!ok) { continue; }

		ll cnt = 0;
		auto tree = SegmentTree<ll>(n);
		REPC(p, all) {
			auto x = p.second;
			cnt += tree.query(x + 1, n);
			tree.add(x, 1);
		}
		chmin(ans, cnt);
	}

	cout << ((ans > 1e9) ? -1 : ans) << endl;
}

