template<class T> int cou_big_comp_back( vector<T> &b) {    rev(b);    int ret = cou_big_comp(b);    rev(b);    return ret;}
//自分以上の個数
template<class T> int cou_big_eq_comp(vector<T> &a) {    vector<T> b = a;    compress(b);    int n = sz(b);    BIT<int> bt(n + 3);    int cou = 0;    rer(i, n - 1) {        cou += bt.get(b[i] + 1);        bt.add(b[i], 1);    }    return cou;}
template<class T> int cou_big_eq_comp_back( vector<T> &b) {    rev(b);    int ret = cou_big_eq_comp(b);    rev(b);    return ret;}
