}
int main() {
    // cin.tie(0);
    // ios::sync_with_stdio(false);

    int N;
    cin >> N;
    vector<int> A(N), B(N);
    REP(i, N) { cin >> A.at(i); }
    REP(i, N) { cin >> B.at(i); }

    int ans = INF;
    int bit = 0;
    while (bit < 1 << N) {
        vector<pair<int, int>> use(N);
        int mask = 1;
        int sum = 0;
        REP(i, N) {
            if (mask & bit) { // ビットが立てば裏
                use[i] = make_pair(B[i], i);
                sum++;
            } else {
                use[i] = make_pair(A[i], i);
            }
            mask = mask << 1;
        }

        bool flag = false;
        if (sum % 2 == 1) {
            flag = true;
        }

        // bubble
        vector<int> ind(N);
        REP(i, N) { ind[i] = i; }
        int t = 0;
        for (int i = 0; i < N - 1; i++) {
            for (int j = 0; j < N - i - 1; j++) {
                if (use[j] > use[j + 1]) { // 右隣が小さければ入れ替える
                    swap(use[j], use[j + 1]);
                    swap(ind[j], ind[j + 1]);
                    t++;
                }
            }
        }

        mask = 1;

        vector<int> ind2(N);
        REP(i, N) { ind2[ind[i]] = i; }
        REP(i, N) {
            if (mask & bit) { // ビットが立てば裏
                if (abs(ind2[i] - i) % 2 == 0) {
                    flag = true;
                }
            } else {
                if (abs(ind2[i] - i) % 2 == 1) {
                    flag = true;
                }
            }
            mask = mask << 1;
        }
        if (flag) {
            bit++;
            continue;
        }
        chmin(ans, t);
        bit++;
    }

    if (ans == INF) {
        cout << -1 << endl;
    } else {
        cout << ans << endl;
    }
    return 0;
}

