    cin >> N;
    vector<int> A(N);
    vector<int> B(N);
    for (int i = 0; i < N; i++) {
        cin >> A[i];
    }
    for (int i = 0; i < N; i++) {
        cin >> B[i];
    }
    vector<vector<int>> dp(N, vector<int>(1 << N, 1e9));
    for (int i = 0; i < N; i++) {
        dp[i][1 << i] = 0;
    }
    for (int mask = 0; mask < 1 << N; mask++) {
        int p = __builtin_popcount(mask);
        for (int i = 0; i < N; i++) {
            int x = i % 2 == (p - 1) % 2 ? A[i] : B[i];
            for (int j = 0; j < N; j++) {
                if (mask & 1 << j) continue;
                int y = j % 2 == p % 2 ? A[j] : B[j];
                if (x > y) continue;
                dp[j][mask | 1 << j] = min(dp[j][mask | 1 << j], dp[i][mask] + __builtin_popcount(mask >> j));
            }
        }
    }
    int res = 1e9;
    for (int i = 0; i < N; i++) {
        res = min(res, dp[i][(1 << N) - 1]);
    }
    if (res > 1e8) res = -1;
    cout << res << '\n';
    return 0;
}

