const int kINF = 1000000;

int Resolve(vector<int> &errors) {
  int n = errors.size();
  int cnt = 0;
  for (int i = 0; i < n; ++i) {
    if (errors[i] == 1) {
      if (i + 1 < n and errors[i + 1] == 1) {
	errors[i + 1] = 0;
	++cnt;
      } else {
	return -1;
      }
    }
  }
  return cnt;
}

int main() {
  int N;
  cin >> N;
  vector<int> A(N);
  vector<int> B(N);
  for (int i = 0; i < N; ++i) {
    cin >> A[i];
  }
  for (int i = 0; i < N; ++i) {
    cin >> B[i];
  }
  vector<int> C(N);

  int min_cnt = kINF;
  for (int r = 0; r < 1<<N; ++r) {
    for (int i = 0; i < N; ++i) {
      if (r>>i & 1) {
	C[i] = B[i];
      } else {
	C[i] = A[i];
      }
    }

    vector<int> counts(N);
    for (int i = 0; i < N; ++i) {
      int cnt = 0;
      for (int j = 0; j < i; ++j) {
	if (C[j] > C[i]) ++cnt;
      }
      for (int j = i + 1; j < N; ++j) {
	if (C[j] < C[i]) ++cnt;
      }
      counts[i] = cnt;
    }
    int cnt_r = 0;
    for (int i = 0; i < N; ++i) {
      cnt_r += counts[i];
    }
    sort(C.begin(), C.end());
    int p = 0;
    int q = 1;
    bool valid = true;
    while (p < N) {
      while (q < N and C[q] == C[p]) ++q;
      vector<int> errors;
      for (int j = p; j < q; ++j) {
	if (counts[j] % 2 != (r>>j & 1)) {
	  errors.push_back(1);
	} else {
	  errors.push_back(0);
	}
      }
      int tmp = Resolve(errors);
      if (tmp == -1) {
	valid = false;
	break;
      } else {
	cnt_r += tmp;
      }
      p = q;
      q = p + 1;
    }
    if (valid) {
      min_cnt = min(min_cnt, cnt_r);
    }
  }

  if (min_cnt == kINF) {
    cout << -1 << endl;
  } else {
    cout << min_cnt / 2 << endl;
  }

  return 0;
}

