        int inf = numeric_limits<int>::max() / 2;
        arr2d<int> answer(1 << n, n, inf);
        for (int i : range(n)) {
            answer(1 << i, i) = i;
        }
        for (int i : range(1, (1 << n) - 1)) {
            for (int j : range(n)) {
                if (answer(i, j) == inf) {
                    continue;
                }
                int pos = bitCount(i);
                int val = ((j & 1) == (pos & 1)) ? b[j] : a[j];
                for (int k : range(n)) {
                    if ((i >> k & 1) == 1) {
                        continue;
                    }
                    int cval = ((k & 1) == (pos & 1)) ? a[k] : b[k];
                    if (val <= cval) {
                        minim(answer(i + (1 << k), k), answer(i, j) + abs(pos - k));
                    }
                }
            }
        }
        int result = *min_element(all(answer[answer.dim1() - 1]));
        if (result == inf) {
            result = -1;
        } else {
            result /= 2;
        }
        out.printLine(result);
    }
};


