inline int popcount(lint n) {
	n = (n & 0x5555555555555555) + (n >> 1 & 0x5555555555555555);
	n = (n & 0x3333333333333333) + (n >> 2 & 0x3333333333333333);
	n = (n & 0x0f0f0f0f0f0f0f0f) + (n >> 4 & 0x0f0f0f0f0f0f0f0f);
	n = (n & 0x00ff00ff00ff00ff) + (n >> 8 & 0x00ff00ff00ff00ff);
	n = (n & 0x0000ffff0000ffff) + (n >> 16 & 0x0000ffff0000ffff);
	n = (n & 0x00000000ffffffff) + (n >> 32 & 0x00000000ffffffff);
	return n;
}

int main() {

	int N;
	cin >> N;

	vector<int> A(N), B(N);
	for (int i = 0; i < N; i++) cin >> A[i];
	for (int i = 0; i < N; i++) cin >> B[i];

	int ans = INF;
	auto check = [&](auto &vec) {

		//DMP(vec);
		vector<pair<int, int>> V(N);
		for (int i = 0; i < N; i++) V[i] = { vec[i], i };

		// buble sort
		int swaps = 0;
		for (int i = 0; i < N - 1; ++i) {
			int last_j = 0;
			for (int j = 0; j < N - i - 1; ++j) {
				if (V[j].first > V[j + 1].first) {
					swap(V[j], V[j + 1]);
					swaps++;
				}
				if (V[j].first == V[j + 1].first && last_j != j) {
					bool res = false;
					const auto& [c, org] = V[j + 1];
					if (((j + 1) ^ org) & 1) res = c == B[org];
					else res = c == A[org];
					if (!res) {
						swap(V[j], V[j + 1]);
						swaps++;
					}
					last_j = j + 1;
				}
			}
		}
		//DMP(V);

		bool res = true;
		for (int i = 0; i < N; i++) {
			const auto& [c, org] = V[i];
			if ((i ^ org) & 1) res &= c == B[org];
			else res &= c == A[org];
			if (!res) break;
		}

		if (res) chmin(ans, swaps);

		return res;
	};

	for (int bit = 0; bit < (1 << N); bit++) {
      if (popcount(bit) & 1) continue;
      auto vec = A;
		for (int i = 0; i < N; i++) {
			if ((bit >> i) & 1) vec[i] = B[i];
		}
		check(vec);
	}

	cout << (ans == INF ? -1 : ans) << "\n";

	return 0;
}

