const int INF = 1e9;

int bubblesort(vector<pii> A, int N){
    int sw = 0;
    vector<pii> B = A;
    sort(B.begin(), B.end());
    for(int i = 0; i < N; i++){
        int tmp = i;
        while(!(B[i].first == A[tmp].first && A[tmp].second == i%2 ) && tmp < N) tmp++;
        if(tmp == N) return -1;

        for(int j = tmp; j >= i+1; j--){
            if((A[j].first < A[j-1].first && A[j].second == i % 2)){
                swap(A[j], A[j-1]);
                sw++;
            }
        }
    }
    //for(auto e: A) cerr << e.first << " " << e.second << endl;
    rep(i, 0, N){
        if(A[i].second != i % 2) return -1;

        if(i < N -1 && A[i].first > A[i+1].first) return -1;
    }
    return sw;
}

