template <class T>
vector<T> merge(vector<T> &A, vector<T> &B) {
    vector<T> ans;
    for (int i = 0; i < B.size(); i++) {
        ans.push_back(A[i]);
        ans.push_back(B[i]);
    }
    if (A.size() > B.size()) ans.push_back(A[B.size()]);
    return ans;
}
int main() {
    int N; cin >> N;
    vector<int> A(N), B(N);
    for (auto &a : A) cin >> a;
    for (auto &b : B) cin >> b;
    int half = (N + 1) / 2;
    int ans = 1e9;
    for (int mask = 0; mask < (1 << N); mask++) if (__builtin_popcount(mask) == half) {
        vector<pair<int, int>> C, D;
        for (int i = 0; i < N; i++) {
            if ((1 << i) & mask) {
                if (i % 2 == 0) C.emplace_back(A[i], i);
                else C.emplace_back(B[i], i);
            } else {
                if (i % 2 == 0) D.emplace_back(B[i], i);
                else D.emplace_back(A[i], i);
            }
        }
        sort(begin(C), end(C));
        sort(begin(D), end(D));
        auto E = merge(C, D);
        int sum = 0;
        for (int i = 0; i + 1 < E.size(); i++) {
            if (E[i].first > E[i + 1].first) {
                goto NEXT;
            }
        }
        for (int i = 0; i < E.size(); i++) {
            sum += abs(i - E[i].second);
        }
        ans = min(ans, sum / 2);
        NEXT:;
    }
    cout << (ans == 1e9 ? -1 : ans) << endl;
    return 0;
}

