void renum(vector<int> &A, vector<int> &B) {
    vector<int> v = A;
    v.insert(v.end(), B.begin(), B.end());
    sort(v.begin(), v.end());
    v.erase(unique(v.begin(), v.end()), v.end());
    for (int &a: A) a = lower_bound(v.begin(), v.end(), a) - v.begin();
    for (int &b: B) b = lower_bound(v.begin(), v.end(), b) - v.begin();
}

