        for(int i = 0; i < n; i++){
            s += i - bit.sum(p[i].second);
            bit.add(p[i].second, 1);
        }
        for(int i = 0; i < n; i++){
            if(abs(i - p[i].second) % 2 != ((b >> i) & 1)){
                bool g = false;
                for(int j = i + 1; j < n; j++){
                    if(p[i].first != p[j].first) break;
                    if(abs(j - p[j].second) % 2 != ((b >> j) & 1)){
                        g = true;
                        s += j - i;
                        for(int k = j; k >= i; k--) p[k].second++;
                        break;
                    }
                }
                if(!g){
                    f = false;
                    break;
                }
            }
        }
        if(f) ans = min(ans, s);
    }
