int main() {
	int n; std::cin >> n;
	std::vector<int> red(n), blue(n);
	for (auto& r : red) std::cin >> r;
	for (auto& b : blue) std::cin >> b;
	std::vector<std::pair<int, int>> for_odd, for_even;
	std::vector<int> indices(n);
	const auto comparator = [](std::pair<int, int> a, std::pair<int, int> b) {return a.second == b.second ? a.first < b.first : a.second < b.second; };
	int min_swap = INT_MAX;
	for (auto pattern = 0; pattern < (1 << n); ++pattern) {
		for_odd.clear(); for_even.clear();
		for (auto i = 0; i < n; ++i) {
			if ((pattern & (1 << i)) == 0) {//red
				if (i % 2 == 0) {
					for_even.emplace_back(i, red[i]);
				}
				else {
					for_odd.emplace_back(i, red[i]);
				}
			}
			else {//blue
				if (i % 2 == 0) {
					for_odd.emplace_back(i, blue[i]);
				}
				else {
					for_even.emplace_back(i, blue[i]);
				}
			}
		}
		if (for_even.size() == (n + 1) / 2 && for_odd.size() == n / 2) {
			std::sort(for_even.begin(), for_even.end(), comparator);
			std::sort(for_odd.begin(), for_odd.end(), comparator);
			int prev = 0;
			for (auto i = 0; i < n; ++i) {
				if (i % 2 == 0) {
					if (prev <= for_even[i / 2].second) prev = for_even[i / 2].second;
					else {
						prev = -1;
						break;
					}
				}
				else {
					if (prev <= for_odd[i / 2].second) prev = for_odd[i / 2].second;
					else {
						prev = -1;
						break;
					}
				}
			}
			if (prev < 0) continue;
			for (auto i = 0; i < n; ++i) {
				if ((i & 1) == 0) {
					indices[i] = for_even[i >> 1].first;
				}
				else {
					indices[i] = for_odd[i >> 1].first;
				}
			}
			int swap = 0;
			for (auto i = 0; i < n; ++i) {
				for (auto j = 0; j < i; ++j) {
					if (indices[i] < indices[j]) ++swap;
				}
			}
			min_swap = std::min(min_swap, swap);
		}
	}
	if (min_swap == INT_MAX) {
		std::cout << "-1\n";
	}
	else {
		std::cout << min_swap << '\n';
	}
}

