    for (int i = 0; i < N; i++)
        scanf("%d", &A[i]);
    for (int i = 0; i < N; i++)
        scanf("%d", &B[i]);
    for (int S = 0; S < (1 << N); S++)
        for (int i = 0; i < N; i++)
            dp[S][i] = INF;
    dp[0][0] = 0;
    for (int S = 0; S < (1 << N); S++) {
        for (int lst = 0; lst < N; lst++) {
            if (S && !((1 << lst) & S)) continue;
            int cnt = 0;
            for (int i = 0; i < N; i++)
                if ((1 << i) & S)
                    cnt++;
            for (int i = 0; i < N; i++) {
                if ((1 << i) & S) continue;
                int nS = (S | (1 << i));
                int cost = 0;
                for (int j = 0; j < i; j++)
                    if (!((1 << j) & S))
                        cost++;
                int lst_num = A[lst];
                if (abs(lst - (cnt - 1)) % 2)
                    lst_num = B[lst];
                int cur_num = A[i];
                if (abs(i - cnt) % 2)
                    cur_num = B[i];
                if (S && (cur_num < lst_num)) continue;
                dp[nS][i] = min(dp[nS][i], dp[S][lst] + cost);
            }
        }
    }
    int ans = -1;
    for (int i = 0; i < N; i++) {
        int cur = dp[(1 << N) - 1][i];
        if (cur == INF)
            continue;
        else if (ans == -1)
            ans = cur;
        else
            ans = min(ans, cur);
    }
    printf("%d\n", ans);
    return 0;
}

