                for(int k = 0; k <= num; k++) if(dp[now][k] != INF) {
                    chmin(dp[i][num], dp[now][k] + cnt);
                }
            } else cnt++;
        }
    }
    int ans = INF;
    rep(i, 51) {
        chmin(ans, dp[(1<<n)-1][i]);
    }
    cout << (ans == INF?-1:ans) << endl;
}

