            if(set1[j].first > set2[j].first){
                boleh = false;
                break;
            }

            if( ((N&1) == 0) && j == (int)set2.size()-1 ){
                break;
            }

            if(set1[j+1].first < set2[j].first){
                boleh = false;
                break;
            }
        }

        if(boleh){
            for(int j = 0; j < (int)set2.size(); j ++){
                perm.push_back(set1[j].second);
                perm.push_back(set2[j].second);
            }
            if(N&1){
