            }

            /*for(int j = 0; j < N; j ++){
                printf("%d ", perm[j]);
            }
            printf("\n");*/

            int inv = 0;
            for(int j = 0; j < N; j ++){
                for(int k = j+1; k < N; k ++){
                    if(perm[j] > perm[k]){
                        inv ++;
                    }
                }
            }

            ans = min(ans, inv);
        }
    }

    if(ans == INF){ans = -1;}
