            int from = S ^ (1 << i);
            int cc = 0;
            for (int j = 0; j < n; ++j) {
                if(!(from & (1 << j))) {
                    if(i > j) cc++;
                    continue;
                }
                if(f(j, cnt[S]-1) <= f(i, cnt[S])){
                    dp[i][S] = min(dp[i][S], dp[j][from]+cc);
                }

            }
        }
    }
    int ans = INF<int>;
    for (int i = 0; i < n; ++i) {
        ans = min(ans, dp[i].back());
    }
    if(ans == INF<int>){
        puts("-1");
    }else {
        cout << ans << "\n";
    }
    return 0;
}

