vector<vector<int>> up;

void go(vector<int> a, vector<int> b, int i, int ed, int cnt){
    if(i == ed+1){
        run(a, b, cnt);
        return;
    }
    do{
        vector<int> na = a, nb = b;
        for(int j: up[i]){
            swap(na[j], nb[j+1]);
            swap(nb[j], na[j+1]);
        }
        go(na, nb, i+1, ed, cnt);
    } while(next_permutation(up[i].begin(), up[i].end()));
}

