				if (j % 2 == 0)even.pb({a[j],j});
				else odd.pb({a[j],j});
			}
			else {
				if (j % 2 == 0)odd.pb({b[j],j});
				else even.pb({b[j],j});
			}
		}
		if (N % 2 == 0) {
			if (even.size() != odd.size())continue;
		}
		else {
			if (even.size() != odd.size() + 1)continue;
		}

		sort(all(even));
		sort(all(odd));
		vector<pair<int,int>>ans(N);
		for (int j = 0; j < even.size(); j++)ans[2 * j] = even[j];
		for (int j = 0; j < odd.size(); j++)ans[2 * j + 1] = odd[j];
		int ok = 1;
		for (int j = 0; j < N - 1; j++)if (ans[j].first > ans[j + 1].first)ok = 0;
		if (!ok)continue;


		int temp = 0;
		for (int k = 0; k < N; k++) {
			for (int l = k + 1; l < N; l++) {
				if (ans[k].second > ans[l].second)temp++;
			}
		}
		ret = min(ret, temp);
	}
	if (ret == 1e7)puts(-1);
	else puts(ret);

	return 0;
}

