    sort(ALL(ord), [&u, &v](int x, int y){
      if(u[x]==u[y]) return v[x]<v[y];
      return u[x]<u[y];
    });
    int idx=0;
    bool ok=true;
    vi x;
    while(idx<n){
      int tmp=idx, cnt=0;
      vi odd, evn;
      if(w[ord[idx]]){
        ++cnt;
