      int sum=0;
      REP(j, n){
        sum+=j-bt.sum(x[j]+1);
        bt.add(x[j]+1, 1);
      }
      CHMIN(ans, sum);
    }
  }
  cout<<(ans==INF ? -1 : ans)<<'\n';
  return 0;
}

