                    int stan = (p[i] + r[k]) % 2;
                    if (a[i][j] <= a[r[k]][stan])
                        dp[mask | (1 << r[k])][r[k]][stan] = min(dp[mask | (1 << r[k])][r[k]][stan], dp[mask][i][j] + k);
                }
            }
        }
    }
    int odp = INF;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < 2; ++j)
            odp = min(odp, dp[(1 << n) - 1][i][j]);
