int main() {
    cin >> n;

    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }
    for (int i = 0; i < n; i++) {
        cin >> b[i];
    }

    int ans = 1000000000;

    for (int i = 0; i < (1 << n); i++) {
        int j = 1, count = 0;
        vector<int> temp;
        vector<vector<int>> c;
        for (int k = 0; k < n; k++) {
            if ((i & j) == 0) {
                temp = {a[k], k, 0, 0};
                c.push_back(temp);
            } else {
                temp = {b[k], k, 1, 0};
                c.push_back(temp);
                count++;
            }
            j *= 2;
        }
        if (count % 2 != 0) {
            continue;
        }

        for (int l = 0; l < n - 1; l++) {
            for (int j = 0; j < n - 1; j++) {
                if (c[j][0] > c[j + 1][0]) {
                    c[j][3]++;
                    c[j + 1][3]++;
                    swap(c[j], c[j + 1]);
                }
            }
        }
        bool flag = true;
        for (int j = 0; j < n; j++) {
            if (c[j][3] % 2 != c[j][2]) {
                if ((j == n - 1) || (c[j][0] != c[j + 1][0]) ||
                    (c[j + 1][3] % 2 == c[j + 1][2])) {
                    flag = false;
                } else {
                    c[j][3]++;
                    c[j + 1][3]++;
                    swap(c[j], c[j + 1]);
                }
            }
        }
        if (flag) {
            int cost = 0;
            for (int j = 0; j < n; j++) {
                cost += c[j][3];
            }
            ans = min(ans, cost / 2);
        }
    }
    if (ans == 1000000000) {
        cout << -1 << endl;
    } else {
        cout << ans << endl;
    }
}

