int main() {
  i64 N;
  cin >> N;
  vector<i64> A(N), B(N);
  rep(i,0,N) cin >> A[i];
  rep(i,0,N) cin >> B[i];

  i64 ans = 1e18;

  for(i64 s = 0;s < (1 << N);s++) {
    if(__builtin_popcountll(s) % 2 == 1) continue;
    vector<i64> vec(N);
    vector<i64> idx(N);
    vector<i64> flip(N);
    rep(i,0,N) {
      if(s & (1 << i)) vec[i] = B[i], flip[i] = 1;
      else vec[i] = A[i];
      idx[i] = i;
    }
    auto X = vec;
    sort(all(vec));
    i64 res = 0;


    rep(i,0,N) {
      if(vec[i] != X[idx[i]]) {
        flip[idx[i]] ^= 1;
        rep(j,i + 1,N) {
          flip[idx[j]] ^= 1;
          res++;
          if(vec[i] == X[idx[j]]) {
            i64 idxj = idx[j];
            idx.erase(idx.begin() + j);
            idx.insert(idx.begin() + i, idxj);
            break;
          }
        }
      }
    }
    i64 F = 0;
    i64 b = -1;
    rep(ii,0,N) {
      i64 i = idx[ii];
      F += flip[i];
      if(flip[i]) {
        if(b == -1) b = ii;
        else {
          res += (ii - b) * 2;
          b = -1;
        }
      }
    }
    if(0 != F) continue;
    ans = std::min(ans, res);
    i64 t = 0;
    for(i64 i = N;i --> 0;) {
      t |= ((s >> i) & 1) << (N - 1 - i);
    }

  }
  if(ans == 1e18) ans = -1;
  cout << ans << endl;
