    V<queue<ll>> odds(51), evens(51);
    for (ll S = 0; S < (1ll << N); S++) {
        for (ll i = 1; i <= 50; i++) {
            odds[i] = queue<ll>();
            evens[i] = queue<ll>();
        }
        for (ll i = 0; i < N; i++) {
            bool p = ((S >> i) & 1 ? true : false);
            ll n = (p ? B[i] : A[i]);
            arr[i] = n;
            par[i] = p;
            if (i % 2 == 0) (p ? odds : evens)[n].push(i);
            else (p ? evens : odds)[n].push(i);
        }

        sort(ALL(arr));
        ll cnt = 0;
        ll inc = 0;
        bool ok = true;
        for (ll i = 0; i < N; i++) {
            ll n = arr[i];
            auto &&idx_q = (i & 1 ? odds : evens)[n];
            if (idx_q.empty()) {
                ok = false;
                break;
            }
            ll idx = idx_q.front();
            idx_q.pop();
            if (i < idx) {
                cnt += (idx - i);
                inc += (idx - i);
            } else {
                inc -= (i - idx);
            }
        }

        if (ok && inc == 0) chmin(ans, cnt);
    }

    if (ans == inf) cout << -1;
    else cout << ans;
    cout << endl;
    return 0;
}

