int N;
int A[MAXN + 1];
int B[MAXN + 1];

int main(void) {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N;

    for (int i = 0; i < N; i++)
        cin >> A[i];
    for (int i = 0; i < N; i++)
        cin >> B[i];

    bool ok = true;
    for (int i = 1; i < N; i++) {
        if (A[i - 1] > A[i]) {
            ok = false;
            break;
        }
    }
    if (ok) {
        cout << 0 << endl;
        return 0;
    }

    int res = INF;
    for (int i = 0; i < (1 << N); i++) {
        int bit = popcount(i);
        if (bit & 1)
            continue;

        vector<tuple<int, int, bool>> even;
        vector<tuple<int, int, bool>> odd;
        for (int j = 0; j < N; j++) {
            if (i & (1 << j)) {
                if (j & 1)
                    even.emplace_back(B[j], j, true);
                else
                    odd.emplace_back(B[j], j, true);
            } else {
                if (j & 1)
                    odd.emplace_back(A[j], j, false);
                else
                    even.emplace_back(A[j], j, false);
            }
        }
        if (even.size() != (N + 1) / 2)
            continue;

        sort(odd.begin(), odd.end());
        sort(even.begin(), even.end());

        int dist = 0;
        int delta = 0;
        for (int j = 0; j * 2 < N; j++) {
            int evenX = (j < int(even.size())) ? get<0>(even[j]) : -1;
            int oddX = (j < int(odd.size())) ? get<0>(odd[j]) : INF;

            if ((evenX > oddX) || (j > 0 && get<0>(odd[j - 1]) > evenX)) {
                dist = INF;
                break;
            }

            if (j < int(even.size())) {
                dist += abs(get<1>(even[j]) - j * 2);
                delta += get<1>(even[j]) - j * 2;
            }
            if (j < int(odd.size())) {
                dist += abs(get<1>(odd[j]) - j * 2 - 1);
                delta += get<1>(odd[j]) - j * 2 - 1;
            }
        }
        if (dist < INF && delta == 0)
            res = min(res, dist);
    }

    if (res >= INF)
        cout << -1 << endl;
    else
        cout << res / 2 << endl;

    return 0;
}

