// 座圧 {写像, 逆写像} が返る O(NlogN)
template <typename T>
pair<map<T, int>, vector<T>> sahz(const vector<T> &x0) {
    vector<T> x = x0;
    sort(x.begin(), x.end());
    x.erase(unique(x.begin(), x.end()), x.end());
    map<T, int> r;
    for (int i = 0; i < x.size(); i++) {
        r[x[i]] = i;
    }
    return make_pair(r, x);
}

// Binary Indexed Tree モジュール (0-indexed)
template <typename T>
class BIT {
private:
    vector<T> val;
public:
    ull n;
    BIT(ull _n) : val(_n+1, 0), n(_n) {}
    BIT(vector<T> arr) : val(arr.size() + 1, 0), n(arr.size()) {
        REP(i, n) add(i, arr[i]);
    }
    // a[i] に v を足す O(logN)
    void add(const ull _i, const T _v) {
        for (ull i = _i + 1; i <= n; i += i & (-i)) {
            val[i] += _v;
        }
    }
    // [0, _i) の和を求める O(logN)
    T get(ull i) const {
        T ans = 0;
        for (; i > 0; i ^= i & (-i)) {
            ans += val[i];
        }
        return ans;
    }
    // [l, r) の和を求める o(N)
    T sum(const ull l, const ull r) {
        return get(r) - get(l);
    }
};

// BITを用いて数列の転倒数を求める。O(NlogN)。
// bit.cppを必要とする。
template <typename T>
size_t inversion(vector<T> &x0) {

    vector<T> x = x0;
    const int n = x0.size();

    // 座圧
    vector<T> unq = x;
    sort(unq.begin(), unq.end());
    unq.erase(unique(unq.begin(), unq.end()), unq.end());
    map<T, int> sahz;
    for (size_t i = 0; i < unq.size(); i++) sahz[unq[i]] = i;
    for (size_t i = 0; i < x.size(); i++) x[i] = sahz[x[i]];

    // BITで転倒数を求める
    size_t ans = 0;
    BIT<int> bit(n);
    for (int i = 0; i < n; i++) {
        ans += bit.sum(x[i]+1, n);
        bit.add(x[i], 1);
    }

    return ans;

}


