int main() {

    ios::sync_with_stdio(false); // stdioを使うときはコメントアウトすること
    cin.tie(nullptr);            // インタラクティブ問題ではコメントアウトすること

    ll n = inp1;
    vector<ll> a = inp(n), b = inp(n);

    // 座圧
    vector<ll> ab;
    copy(ALL_OF(a), back_inserter(ab));
    copy(ALL_OF(b), back_inserter(ab));
    auto r = sahz(ab);
    for (ll &x : a) x = r.first[x];
    for (ll &x : b) x = r.first[x];

    // DUMPALL(a);
    // DUMPALL(b);

    ll ans = INF;
    REP(i, 1<<n) {
        if (popcountll(i) % 2 == 1) continue;
        vector<pair<ll, ll>> c(n);
        REP(j, n) {
            c[j] = make_pair(i>>j&1, j); // {裏か, 元の位置}
        }
        sort(ALL_OF(c), [&](pair<ll,ll> &x, pair<ll,ll> &y) {
            ll xv = (x.first ? b : a)[x.second];
            ll yv = (y.first ? b : a)[y.second];
            return xv < yv;
        });
        bool okay = true;
        for (ll l = 0, r = 0; l < n;) {
            while (r < n && (c[l].first?b:a)[c[l].second] == (c[r].first?b:a)[c[r].second]) r++;

            vector<pair<ll, ll>> evens, odds;
            RANGE(j, l, r-1) {
                (c[j].first ^ (c[j].second % 2) ? odds : evens).push_back(c[j]);
            }

            sort(ALL_OF(evens), [&](pair<ll, ll> &x, pair<ll, ll> &y) { return x.second < y.second; });
            sort(ALL_OF( odds), [&](pair<ll, ll> &x, pair<ll, ll> &y) { return x.second < y.second; });

            ll ie = 0, io = 0;
            RANGE(j, l, r-1) {
                ll par = j % 2;
                ll &i = par ? io : ie;
                auto &s = par ? odds : evens;
                if (i >= s.size()) {
                    okay = false;
                    break;
                }
                c[j] = s[i++];
            }
            if (!okay) break;

            l = r;
        }
        if (!okay) continue;
        REP(j, n) {
            if (c[j].first ^ (abs(j - c[j].second) % 2)) {
                okay = false;
                break;
            }
        }
        if (!okay) continue;
        vector<ll> idx(n);
        REP(j, n) idx[j] = c[j].second;
        chmin(ans, (ll)inversion(idx));
    }
    if (ans == INF) ans = -1;
    say(ans);

}

