int solve(int n, const vector<int>& a, const vector<int>& b, int m) {
    vector<int> c(n);
    for (int i = 0; i < n; ++i) {
        if ((m >> i) & 1)
            c[i] = b[i];
        else c[i] = a[i];
    }
    vector<int> d(c);
    sort(d.begin(), d.end());
    vector<int> used(n, 0);
    int res = 0;
    for (int i = 0; i < n; ++i) {
        int st = (i + (m >> i)) & 1;
        int ok = 0;
        for (int j = 0; j < n; ++j) {
            if (used[j]) {
                continue;
            }
            if (((j & 1) == st) && (c[i] == d[j])) {
                ok = 1;
                used[j] = 1;
                break;
            }
            else ++res;
        }
        if (ok == 0)
            return -1;
    }
    return res;
}

