bool valid(int i, int idx){
    if (g[i][abs((i-idx)%2)] < n-idx-1) return false;
    if (idx == 0) return true;

    int next;
    if ((i-idx)%2) next = blue[i];
    else next = red[i];

    int last;
    if ((idx - perm[idx-1])%2) last = red[perm[idx-1]];
    else last = blue[perm[idx-1]];

    return next >= last;
}

// k: inversiones que se llevan
void solve(int idx, int k){
    if (idx == n) {
        ans = min(ans, k);
    } else if (k < ans){
        int iv = 0;
        for (int i = 0; i < n; i++) {
            if (not used[i]) {
                if (valid(i, idx)) {
                    used[i] = true;
                    perm[idx] = i;
                    solve(idx+1, k + iv);
                    used[i] = false;
                }
                iv++;
            }
        }
    }
}

