inline ll solve(int s,int e,int l,int r,int face)
{
    if(r<l) return inf;
    if(s==e){
        if(arr[face][s]>=l && arr[face][e]<=r) return 0;
        else return inf;
    }
    ll a=inf,b=inf,ans;
    if(arr[face][s]>=l) a=solve(s+1,e,arr[face][s],r,face);
    if(((e-s)%2==1) && arr[1-face][s]<=r) b=e-s+solve(s+1,e,l,arr[1-face][s],1-face);
    else if(arr[face][s]<=r) b=e-s+solve(s+1,e,l,arr[face][s],1-face);
    ans=min(a,b);
    for(int i=s+1;i<e;i++){
        if((i-s)%2==1){
            ans=min(ans,solve(s+1,i,l,arr[1-face][s],1-face)+solve(i+1,e,arr[1-face][s],r,face)+i-s);
        }
        else{
            ans=min(ans,solve(s+1,i,l,arr[face][s],1-face)+solve(i+1,e,arr[face][s],r,face)+i-s);
        }
    }
