template<typename T>
struct BIT {
    vector<T> bit;
    int sz;

    BIT(int n) : sz(n+1), bit(n+1) {}

    void add(int i, T x) {
        i += 1;
        while (i < sz) { bit[i] += x; i += i & -i; }
    }

    T sum(int i) {
        i += 1; T s = 0;
        while (i > 0) { s += bit[i]; i -= i & -i; }
        return s;
    }
};

template<typename T>
LL inversion(const vector<T>& A)
{
    map<T, int> idx;
    for (const T& a : A) idx[a] = -1;

    int cnt = 0;
    for (auto& p : idx) p.second = cnt++;

    assert(cnt == A.size());

    BIT<int> bit(cnt+1);
    LL res = 0;
    for (int i = 0; i < A.size(); ++i) {
        res += i - bit.sum(idx[A[i]]);
        bit.add(idx[A[i]], 1);
    }

    return res;
}


