            if (i<n-2&&temp[i].F == temp[i + 2].F && temp[i].S && !temp[i + 2].S)
            {
                temp[i].S = 0;
                temp[i + 2].S = 0;
                count += 2;
            }
        }
        bool h=true;
        rep(i,n){
            if(temp[i].S){
                h = false;
                break;
            }
        }
        if(h){
            chmin(res, count);
