const int INF = 1e6;
int dp[1<<18][51];

int main() {
    static_fill(dp, INF);

    int N;
    cin >> N;
    vector<int> A(N), B(N);
    for (int i=0; i<N; ++i) cin >> A[i];
    for (int i=0; i<N; ++i) cin >> B[i];

    // 位置iにあるカードを位置jに置くときの表の数字
    auto face = [&](int i, int j){
        return abs(i-j) % 2 ? B[i] : A[i];
    };

    for (int i=0; i<N; ++i) {
        dp[1<<i][face(i, 0)] = 0;
    }
    for (int mask=1; mask<(1<<N); ++mask) {
        for (int i=0; i<51; ++i) {
            for (int j=0; j<N; ++j) {
                if ((mask >> j) & 1) continue;

                int p = __builtin_popcount(mask);
                if (i <= face(j, p)) {
                    int inv = __builtin_popcount(mask / (1<<(j+1)));
                    chmin(dp[mask|(1<<j)][face(j, p)], dp[mask][i] + inv);
                }
            }
        }
    }
    int res = INF;
    for (int i=0; i<51; ++i) {
        res = min(res, dp[(1<<N)-1][i]);
    }
    cout << (res == INF ? -1 : res) << endl;

    return 0;
}

