				c[i] = b[i];
				change[i] = 1;
			}
		}
		int now = 0;
		for (int i = 0; i < n; ++i) {
			int cnt = 0;
			for (int j = i + 1; j < n; ++j) {
				if (c[j] < c[i]) {
					++cnt;
				}
			}
			for (int j = i - 1; j >= 0; --j) {
				if (c[j] > c[i]) {
					++cnt;
				}
			}
			now += cnt;
			if ((cnt + change[i]) % 2 == 1) {
				num[c[i]].push_back(1);
			} else {
				num[c[i]].push_back(0);
			}
		}
