		for (int k = 0; k <= 50; ++k) {
			int p = 0;
			vector<pair<int, int>> l;
			int last = -1;
			for (int i = 0; i < (int) num[k].size(); ++i) {
				if (num[k][i] == last) {
					++p;
				} else {
					if (last != -1 && p != 0) {
						l.push_back({last, p});
					}
					last = num[k][i];
					p = 1;
				}
			}
			if (last != -1 && p != 0) {
				l.push_back({last, p});
			}
			for (int i = 0; i < (int) l.size(); ++i) {
				if (l[i].first == 0) {
