void solve(){
  ini(N);
  vi A(N) , B(N); in(A , B);

  rep(i , 1 << N) rep(j , 51) dp[i][j] = inf;
  dp[0][0] = 0;
  int nya[20] , rui[20];
  rep(b , 1 << N) rep(j , 51){
    if(dp[b][j] == inf) continue;
    rep(i , N) nya[i] = (b >> i) & 1;
    rui[0] = 0; rep(i , N) rui[i + 1] = rui[i] + nya[i];

    rep(k , N){
      if((b >> k) & 1) continue;
      int nxt = ((rui[N] + k) & 1) ? B[k] : A[k];
      if(nxt < j) continue;
      // 転倒数 kより大きいbitの個数
      amin(dp[b | (1 << k)][nxt] , dp[b][j] + rui[N] - rui[k]);
    }
  }

  int ans = inf;
  rep(j , 51) amin(ans , dp[(1 << N) - 1][j]);
  out( ans == inf ? -1 : ans);



}

