		REP(i, N) m += ((mask>>i)&1);
		if (m != maskNum) continue;

		//
		ll Acount = 0, Bcount = 0;
		REP(i, N){
			ll bit_ = (mask>>i)&1;
			if (bit_ == 1){
				get<0>(bufA[Acount]) = A[i];
				get<1>(bufA[Acount]) = i;
				get<2>(bufA[Acount]) = 1;
				Acount++;
			}
			else{
				get<0>(bufB[Bcount]) = B[i];
				get<1>(bufB[Bcount]) = i;
				get<2>(bufB[Bcount]) = 0;
				Bcount++;
			}
		}
		sort(bufA.begin(), bufA.end());
		sort(bufB.begin(), bufB.end());

		//101010...チェック
#if 0
		ll okNum = 0;
		REP(i, N){
			if (get<2>(buf[i]) == (i+1)%2) okNum++;
		}
		if (okNum != N) continue;
#endif
		ll okNum = 0;
		if (Anum == Bnum){
			REP(i, Anum){
				if (get<0>(bufA[i]) <= get<0>(bufB[i])) okNum++;
			}
			REP(i, Bnum-1){
				if (get<0>(bufB[i]) <= get<0>(bufA[i+1])) okNum++;
			}
		}
		else{
			REP(i, Anum-1){
				if (get<0>(bufA[i]) <= get<0>(bufB[i])) okNum++;
			}
			REP(i, Bnum){
				if (get<0>(bufB[i]) <= get<0>(bufA[i+1])) okNum++;
			}
		}
		if (okNum != N-1) continue;


		//交換回数
#if 0
		ll swapNum = 0;
		REPS(i, 0, N-2)REPS(j, i+1, N-1){
			if (get<1>(buf[i]) > get<1>(buf[j])) swapNum++;
		}
#endif
		REP(i, Anum) idxbuf[i*2] = get<1>(bufA[i]);
		REP(i, Bnum) idxbuf[i*2+1] = get<1>(bufB[i]);
		ll swapNum = 0;
		REPS(i, 0, N-2)REPS(j, i+1, N-1){
			if (idxbuf[i] > idxbuf[j]) swapNum++;
		}

		chmin(ans, swapNum);
	}
	if (ans == INF) bye(-1);
	cout << ans << '\n';
}


