constexpr int N = 18;
int n;
int a[N][2];
int dp[1 << N][N];
int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    std::cin >> n;
    for (int i = 0; i < n; ++i)
        std::cin >> a[i][0];
    for (int i = 0; i < n; ++i) {
        std::cin >> a[i][1];
        if (i % 2 == 1)
            std::swap(a[i][0], a[i][1]);
    }
    for (int i = 0; i < (1 << n); ++i)
        std::fill(dp[i], dp[i] + n, -1);
    for (int i = 0; i < n; ++i)
        dp[1 << i][i] = 0;
    for (int s = 1; s < (1 << n) - 1; ++s) {
        int pos = __builtin_popcount(s) - 1;
        for (int i = 0; i < n; ++i) {
            if ((s >> i & 1) && dp[s][i] != -1) {
                int val = a[i][pos % 2];
                for (int j = 0; j < n; ++j) {
                    if ((~s >> j & 1) && a[j][(pos + 1) % 2] >= val) {
                        int t = s | 1 << j;
                        int tmp = dp[s][i] + pos + 1 - __builtin_popcount(s & ((1 << j) - 1));
                        if (dp[t][j] == -1 || dp[t][j] > tmp)
                            dp[t][j] = tmp;
                    }
                }
            }
        }
    }
    int ans = -1, s = (1 << n) - 1;
    for (int i = 0; i < n; ++i)
        if (dp[s][i] != -1 && (ans == -1 || ans > dp[s][i]))
            ans = dp[s][i];
    std::cout << ans << "\n";
    return 0;
}

