struct BIT{
private:
    vector<ll> a;
    int n;
public:
    BIT(int sz){
        n=sz;
        a.resize(sz+1);
    }
    ll sum(int i){
        ll res=0;
        while(i>0){
            res+=a[i];
            i-=i&-i;
        }
        return res;
    }
    ll sum(int i,int j){
        return sum(j)-sum(i-1);
    }
    void add(int i,ll x){
        while(i<=n){
            a[i]+=x;
            i+=i&-i;
        }
    }
};

int main(){
    int n;
    cin>>n;
    int a[n],b[n];
    for(int i=0;i<n;i++){
        cin>>a[i];
    }
    for(int i=0;i<n;i++){
        cin>>b[i];
    }
    ll ans=LINF;
    int p[n]={};
    for(int i=0;i<(n+1)/2;i++){
        p[n-1-i]=1;
    }
    do{
        bool flag=true;
        vector<pair<int,int>> ev;
        vector<pair<int,int>> od;
        for(int i=0;i<n;i++){
            if(p[i]){
                if(i%2==0)ev.push_back({a[i],i});
                else ev.push_back({b[i],i});
            }
            else{
                if(i%2==0)od.push_back({b[i],i});
                else od.push_back({a[i],i});
            }
        }
        sort(ev.begin(),ev.end());
        sort(od.begin(),od.end());
        int t=-1;
        ll sum=0;
        BIT bit(n);
        for(int i=0;i<(n/2)*2;i++){
            if(i%2==0){
                if(t>ev[i/2].first){
                    flag=false;
                }
                t=ev[i/2].first;
                sum+=abs(ev[i/2].second+bit.sum(ev[i/2].second+1,n)-i);
                bit.add(ev[i/2].second+1,1);
            }
            else{
                if(t>od[i/2].first){
                    flag=false;
                }
                t=od[i/2].first;
                sum+=abs(od[i/2].second+bit.sum(od[i/2].second+1,n)-i);
                bit.add(od[i/2].second+1,1);
            }
        }
        if(n&1){
            if(t>ev.back().first){
                flag=false;
            }
        }
        if(flag){
            ans=min(ans,sum);
        }
    }while(next_permutation(p,p+n));
    if(ans==LINF)cout<<-1<<endl;
    else cout<<ans<<endl;
}

