int main(){
  ll N,ans=-1,cnt=0ll,move=0ll;
  cin>>N;

  ll A[N],B[N],MOVE[N],PP[N];
  REP(i,N) cin>>A[i];
  REP(i,N) cin>>B[i];
  REP(i,N) MOVE[i]=0ll;
  REP(i,N) PP[i]=i;

  bool CAN=true;


  for(ll bit=0ll; bit<(1ll<<N); ++bit){
    vector<pair<ll,ll>> L;
    REP(i,N) MOVE[i]=0ll;
    REP(i,N) PP[i]=i;
    cnt=0ll;
    move=0ll;
    CAN=true;

    for(ll i=0ll; i<N; ++i){
      if(bit & (1ll<<i)) L.push_back(make_pair(B[i],i));
      else L.push_back(make_pair(A[i],i));
