    SORT(L);

    for(ll i=0ll; i<N; ++i){
      MOVE[i]=abs(i-L[i].second);

      if((bit & (1ll<<i)) && MOVE[i]%2==0) cnt++;
      if(!(bit & (1ll<<i)) && MOVE[i]%2==1) cnt++;
    }

    if(cnt%2==1) CAN=false;

    if(CAN){
      if(ans==-1) ans=INF;

      ll t=0;
      for(ll i=0; i<N; ++i){
        move+=L[i].second-PP[i];
        for(ll j=0; j<N; ++j){
          if(j<L[i].second) PP[j]++;
        }
      }

      ans=min(ans,move);
    }

  }

  cout<<ans<<endl;
  return 0;

}

