struct card { int i; int v; };

int main() {
  int N; cin >> N;
  int A[N]; rep(i,N) cin >> A[i];
  int B[N]; rep(i,N) cin >> B[i];

  int result = INF;
  rep(itr,1<<N) {
    vector<card> o,e;
    rep(i,N) {
      if (itr&(1<<i)) {
        if (i%2==0) o.push_back({i,B[i]});
        else e.push_back({i,B[i]});
      }
      else {
        if (i%2==0) e.push_back({i,A[i]});
        else o.push_back({i,A[i]});
      }
    }
    if (e.size()!=(N+1)/2) continue;
    sort(all(e),[](const card &x, const card &y){return x.v<y.v||(x.v==y.v&&x.i<y.i);});
    sort(all(o),[](const card &x, const card &y){return x.v<y.v||(x.v==y.v&&x.i<y.i);});
    bool ok = true;
    rep(i,N/2) if (e[i].v>o[i].v) ok = false;
    rep(i,(N-1)/2) if (o[i].v>e[i+1].v) ok = false;
    if (!ok) continue;

    int pos[N]; rep(i,N) pos[i] = i%2 ? o[i/2].i : e[i/2].i;
    // debug(pos,pos+N);
    SegTree tree(N);
    int rtmp = 0;
    rep(i,N) {
      rtmp += tree.query(pos[i],N);
      tree.update(pos[i],1);
    }
    result = min(result, rtmp);
  }
  cout << result << endl;
  return 0;
}

