int const inf = 1<<29;
int N;
vector<int> A, B;

// 配る bitDP
void solve() {
    vector<vector<int>> dp((1<<N)+1, vector<int>(55, inf));
    dp[0][0] = 0;
    rep(bit, 1<<N) {
        int cnt = __builtin_popcount(bit);

        // bit に含まれない残りの要素が何番目になるか
        vector<pair<int, int>> ords;
        int itr = cnt;
        rep(i, N) if (!(bit&(1<<i))) ords.emplace_back(i, itr++);

        rep(s, 51) {
            if (dp[bit][s] == inf) continue;
            for(auto p: ords) {
                // p.first: 元々の a の index
                // p.second: dp[bit][s] (遷移元)の状態での index
                int ns = -1;
                if (abs(p.first-cnt)%2 == 0) ns = A[p.first];
                else ns = B[p.first];

                if (ns>=s) chmin(dp[bit | 1<<p.first][ns], dp[bit][s] + abs(p.second - cnt));
            }
        }
    }

    int ans = inf;
    rep(s, 51) chmin(ans, dp[(1<<N)-1][s]);
    cout << (ans==inf? -1:ans) << endl;
}

int main(){
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    cin >> N;
    A.resize(N), B.resize(N);
    rep(i, N) cin >> A[i];
    rep(i, N) cin >> B[i];
    solve();

    return 0;
}

