	cin >> N;
	for (int i=0; i<N; i++) cin >> A[i].va;
	for (int i=0; i<N; i++) cin >> A[i].vb;

	for (int i=0; i<(1<<N); i++) {
		for (int j=0; j<N; j++) dp[j][i] = 2e9;
	}
	for (int i=0; i<N; i++) dp[i][1<<i] = 0;

	for (int i=0; i<(1<<N); i++) {
		for (int j=0; j<N; j++) {
			if (!(i>>j&1)) continue;
			int prv = i ^ (1<<j);
			int idx = 0, cost = 0, num;
			for (int k=0; k<N; k++) {
				idx += (prv>>k&1);
				if (k>j) cost += (prv>>k&1);
			}
			if (idx%2 == j%2) num = A[j].va;
			else num = A[j].vb;

			for (int k=0; k<N; k++) {
				if (!(prv>>k&1)) continue;
				int t;
				if (k%2 == idx%2) t = A[k].vb;
				else t = A[k].va;
				if (t > num) continue;
				dp[j][i] = min(dp[j][i], dp[k][prv]+cost);
			}
		}
	}

	int ans = 2e9;
	for (int i=0; i<N; i++)
		ans = min(ans, dp[i][(1<<N)-1]);
