int n;
bool ok(vector<pair<int, int>> vec) {
    vector<int> od, ev;
    rep(i, n) {
        (vec[i].second ? od : ev).push_back(vec[i].first);
    }

    if (sz(ev) != n / 2) {
        return false;
    }

    sort(all(od), greater<int>());
    sort(all(ev), greater<int>());
    vector<int> now;
    rep(i, n) {
        if (i % 2 == 0) {
            now.push_back(od.back());
            od.pop_back();
        } else {
            now.push_back(ev.back());
            ev.pop_back();
        }
    }

    rep(i, n - 1) {
        if (now[i] > now[i + 1]) {
            return false;
        }
    }
    return true;
}

int main() {
    cin >> n;
    vector<int> a(n), b(n);
    rep(i, n) cin >> a[i];
    rep(i, n) cin >> b[i];

    int ans = INF;
    rep(bit, (1 << n)) {
        vector<pair<int, int>> now(n);
        rep(i, n) {
            int odd = 0;
            if (i % 2 == 1 && !(bit & (1 << i))) odd = 1;
            if (i % 2 == 0 && (bit & (1 << i))) odd = 1;
            now[i] = {(bit & (1 << i)) ? a[i] : b[i], odd};
        }

        if (!ok(now)) continue;

        int cnt = 0;
        rep(i, n) {
            rep(j, i) {
                if (now[j].first > now[i].first) cnt++;
            }
        }
        chmin(ans, cnt);

        // rep(i, n) cout << now[i].first << " ";
        // cout << endl;
    }
    cout << (ans == INF ? -1 : ans) << endl;
}

