const int N = 23;
int n;
pair<int, int> cards[N];

struct card {
    int val, i, odd;

    card(int _v, int _i, int _o) {
        val = _v;
        i = _i;
        odd = _o;
    }

    bool operator<(const card& other) const {
        if(val != other.val)
            return val < other.val;
        return i < other.i;
    }

    void print() {
        cerr << val << ' ' << i << ' ' << odd << "  ";
    }
};

void reorder(vector<card>& v, int i, int j) {
    while(true) {
        int bad_odd = i + ((i+1)%2);
        while(bad_odd < j) {
            if(v[bad_odd].odd == 0) break;
            bad_odd += 2;
        }
        int bad_even = i + (i%2);
        while(bad_even < j) {
            if(v[bad_even].odd == 1) break;
            bad_even += 2;
        }

        if(bad_odd >= j || bad_even >= j) break;

        swap(v[bad_odd], v[bad_even]);
    }
}

int32_t main() {

    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    cin >> n;
    for(int i = 0; i < n; ++i) {
        cin >> cards[i].first;
    }
    for(int i = 0; i < n; ++i) {
        cin >> cards[i].second;
    }

    int ans = -1;
    for(int mask = 0; mask < (1<<n); ++mask) {
        if(__builtin_popcount(mask)%2) continue;

        vector<card> v;
        for(int i = 0; i < n; ++i) {
            if(mask & (1 << i)) {
                v.emplace_back(cards[i].second, i, (i+1)%2);
            } else {
                v.emplace_back(cards[i].first, i, i%2);
            }
        }

        sort(v.begin(), v.end());

        int i = 0;
        while(i < n) {
            int j = i;
            int ct[2] = {0, 0};
            int cti[2] = {0, 0};
            while(j < n && v[i].val == v[j].val) {
                ct[v[j].odd]++;
                cti[j%2]++;
                j++;
            }

            if(ct[0] != cti[0] || ct[1] != cti[1]) {
                break;
            }

            reorder(v, i, j);
            i = j;
        }

        if(i < n) continue;

        int cand = 0;
        for(int i = 0; i < n; ++i) {
            for(int j = i+1; j < n; ++j) {
                if(v[i].i > v[j].i) {
                    cand++;
                }
            }
        }
        if(ans == -1 || cand < ans) {
            ans = cand;
        }
    }

    cout << ans << endl;

    return 0;
}

