class SegmentTreeRSQ {
private:
    int n;
    vector<ll> node, lazy;

public:
    void init(vector<ll> v) {
        int sz = (int)v.size();
        n = 1; while(n < sz) n *= 2;
        node.resize(2*n-1);
        lazy.resize(2*n-1, 0);

        for(int i=0; i<sz; i++) node[i+n-1] = v[i];
        for(int i=n-2; i>=0; i--) node[i] = node[i*2+1] + node[i*2+2];
    }

    void eval(int k, int l, int r) {
        if(lazy[k] != 0) {
            node[k] += lazy[k];
            if(r - l > 1) {
                lazy[2*k+1] += lazy[k] / 2;
                lazy[2*k+2] += lazy[k] / 2;
            }
            lazy[k] = 0;
        }
    }

    void add(int a, int b, ll x, int k=0, int l=0, int r=-1) {
        if(r < 0) r = n;
        eval(k, l, r);
        if(b <= l || r <= a) return;
        if(a <= l && r <= b) {
            lazy[k] += (r - l) * x;
            eval(k, l, r);
        }
        else {
            add(a, b, x, 2*k+1, l, (l+r)/2);
            add(a, b, x, 2*k+2, (l+r)/2, r);
            node[k] = node[2*k+1] + node[2*k+2];
        }
    }

   ll getsum(int a, int b, int k=0, int l=0, int r=-1) {
        if(r < 0) r = n;
        eval(k, l, r);
        if(b <= l || r <= a) return 0;
        if(a <= l && r <= b) return node[k];
        ll vl = getsum(a, b, 2*k+1, l, (l+r)/2);
        ll vr = getsum(a, b, 2*k+2, (l+r)/2, r);
        return vl + vr;
    }
};


int calc(){
    for(int i = 0;i < N;i++){
       // cout<<mass[i]<<" ";
    }
  //  cout<<endl;
    int odd_red = 0;
    int odd_blue = 0;
    int even_red = 0;
    int even_blue = 0;
    vector<int> v;
    for(int i = 0;i < N;i++){
        if(i % 2 == 0){
            if(mass[i]){
                odd_red++;
            }else{
                odd_blue++;
            }
        }else{
            if(mass[i]){
                even_red++;
            }else{
                even_blue++;
            }
        }    
        if(mass[i]){
            v.push_back(A[i]);
        }else{
            v.push_back(B[i]);
        }
    }
    if(odd_blue != even_blue){
        return 1e9;
    }

    sort(v.begin(), v.end());

    SegmentTreeRSQ Seg;
    Seg.init(vector<ll>(N));

    vector<bool> flag(N, false);
    int _ans = 0;
    for(int i = 0;i < N;i++){
        for(int j = 0;j < N;j++){
            if(flag[j]){
                continue;
            }
            if((i % 2 == j % 2) == mass[i]){
                if(mass[i]){
                    if(A[i] == v[j]){
                        flag[j] = true;
                        _ans += abs(j - i) + Seg.getsum(i+1, j);
                        Seg.add(j, j+1, 1);
                        Seg.add(i, i+1, -1);
                        break;
                      //  cout<<i<<" "<<j<<endl;
                    }
                }else{
                    if(B[i] == v[j]){
                        flag[j] = true;
                        _ans += abs(j - i) + Seg.getsum(i+1, j);
                        Seg.add(j, j+1, 1);
                        Seg.add(i, i+1, -1);
                        break;
                        //cout<<i<<" "<<j<<endl;
                    }
                }
            }
        }
        //return 1e9;
    }
    for(int i = 0;i < N;i++)
        if(flag[i] == false){
           // cout<<"WWWW"<<endl;
            return 1e9;
        }
    //cout<<_ans<<endl;
    return _ans/2;
}

int zrk(int i){
    if(N == i){
        ans = min(ans, calc());
        return 0;
    }
    mass[i] = 0;zrk(i+1);
    mass[i] = 1;zrk(i+1);
}

void solve(long long _N, std::vector<long long> _A, std::vector<long long> _B){
    N = _N;
    A = _A;
    B = _B;
    zrk(0);
    if(ans == 1e9){
        cout<<-1<<endl;
        return;
    }
    cout<<ans<<endl;
}

