using namespace std;
using P = pair<int, int>;

int func(vector<P> &v, vector<vector<int>> &dp, int m, int s){
	if(dp[m][s] < 1e9) return dp[m][s];
	int n = v.size();
	int k = 0;
	for(int i=0; i<n; ++i)
		if((s >> i) & 1)
			++k;
	if(k == n) return dp[m][s] = 0;
	int cnt = 0;
	int mi = 1e9;
	for(int i=0; i<n; ++i){
		if((s >> i) & 1) continue;
		int x = (k % 2 == 0 ? v[i].first : v[i].second);
		if(x < m){
			++cnt;
			continue;
		}
//		if(x == 38) cout << k << " " << x << " " << s << "\n";
		mi = min(mi, cnt + func(v, dp, x, s|(1<<i)));
		++cnt;
	}
	return dp[m][s] = min(dp[m][s], mi);
}

