int keisan(int b, bool n, int k) {
	if (dp[k][b] != 255) return dp[k][b];
	if (b == (1 << N) - 1) return 0;

	int saishou = 254;
	int num2 = 0;
	char used[36];
	for (int i = k; i <= K; i++) used[i] = 40;

	if (n) {
		rep(i, N) {
			if (!(b >> i & 1)) {
				if (A[i] < k && B[i] < k) return dp[k][b] = 254;
				if (B[i] >= k && used[B[i]] > A[i]) {
					chmin(saishou, keisan(b ^ (1 << i), !n, B[i]) + num2);
					used[B[i]] = A[i];
				}
				num2++;
			}
		}
	}
	else {
		rep(i, N) {
			if (!(b >> i & 1)) {
				if (A[i] < k && B[i] < k) return dp[k][b] = 254;
				if (A[i] >= k && used[A[i]] > B[i]) {
					chmin(saishou, keisan(b ^ (1 << i), !n, A[i]) + num2);
					used[A[i]] = B[i];
				}
				num2++;
			}
		}
	}
	return dp[k][b] = saishou;
}

