#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

const ll INF = 9999999999LL;

int N;

struct State {
	int top[18];
	int bottom[18];
	string state_str;
	int step;
};

queue<State> que;

unordered_set<string> visited;

string create_state_string(State& state) {
	string tb = "#-";
	for (int i=0; i<N; i++) {
		tb += (to_string(state.top[i]) + "-");
	}

	tb += "#-";

	for (int i=0; i<N; i++) {
		tb += (to_string(state.bottom[i]) + "-");
	}

	tb += "#";

	return tb;
}

State operate(State state, int i) {
	swap(state.top[i], state.bottom[i+1]);
	swap(state.bottom[i], state.top[i+1]);
	state.state_str = create_state_string(state);
	state.step++;

	return state;
}

bool check(State& state) {
	for (int i=1; i<N; i++) {
		if (state.top[i-1] > state.top[i]) return false;
	}

	return true;
}

bool check_visited(State& state) {
	return (visited.find(state.state_str) != visited.end());
}

int solve_by_BFS(State state) {
	que.push(state);

	while(!que.empty()) {
		state = que.front();
		que.pop();

		//cout << state.state_str << " " << state.step << endl; // **** debug ****

		if (check_visited(state)) continue;

		visited.insert(state.state_str);

		if (check(state)) {
			//cout << state.state_str << " " << state.step << endl; // **** debug ****
			return state.step;
		}

		for (int i=0; i<N-1; i++) {
			que.push(operate(state, i));
		}
	}

	return -1;
}

int main(){

	cin >> N;

	State state;

	for (int i=0; i<N; i++) {
		cin >> state.top[i];
	}

	for (int i=0; i<N; i++) {
		cin >> state.bottom[i];
	}

	state.state_str = create_state_string(state);
	state.step = 0;

	int ans = solve_by_BFS(state);

	cout << ans << endl;

	return 0;
}

