int merge(vector<int> &da, int le, int mi, int ri, int &co) {
	int n1 = mi - le;
	int n2 = ri - mi;
	vector<int> L(n1 + 1), R(n2 + 1);
	for (int i = 0;i < n1;i++) {
		L[i] = da[le + i];
	}
	for (int i = 0;i < n2;i++) {
		R[i] = da[mi + i];
	}
	L[n1] = INT_MAX;R[n2] = INT_MAX;
	int i = 0, j = 0;
	for (int k = le;k < ri;k++) {
		if (L[i] < R[j]) {
			da[k] = L[i];
			i++;
		}
		else {
			da[k] = R[j];
			j++;
			co += n1 - i;
		}
	}
	return co;
}

int mergesort(vector<int> &da, int le, int ri) {
	int ret = 0;
	if (le + 1 < ri) {
		int mi = (le + ri) / 2;
		ret += mergesort(da, le, mi);
		ret += mergesort(da, mi, ri);
		merge(da, le, mi, ri, ret);
	}
	return ret;
}


