const int INF = 1e9;

int main() {
    int N;
    cin >> N;
    vector<int> A(N), B(N);
    for (int i = 0; i < N; i++) cin >> A[i];
    for (int i = 0; i < N; i++) cin >> B[i];

    vector<vector<int>> dp((1<<N)+1, vector<int>(55, INF));
    dp[0][0] = 0;

    for (int bit = 0; bit < (1<<N); bit++) {

        int done = 0;
        for (int i = 0; i < N; i++) if (bit&(1<<i)) done++;
        int iter = done;
        vector<pair<int, int>> data;
        for (int i = 0; i < N; i++) {
            if (!(bit&(1<<i))) data.emplace_back(i, iter++);
        }

        for (int s = 0; s <= 50; s++) {
            if (dp[bit][s] >= INF) continue;
            for (auto p : data) {
                // p.first : もとのindex
                // p.second : ソート後のindex
                int value = -1;
                if (abs(done-p.first)%2 == 0) value = A[p.first];
                else value = B[p.first];
                if (value >= s) {
                    chmin(dp[bit|(1<<p.first)][value], dp[bit][s] + abs(done-p.second));
                }
            }
        }
    }

    int ans = INF;
    for (int s = 0; s <= 50; s++) chmin(ans, dp[(1<<N)-1][s]);
    cout << ((ans == INF) ? -1 : ans) << endl;
