int const inf = 1<<29;

vector<int> L(20, 0), R(20, 0);

ll merge(vector<int> A, int left, int mid, int right){
    ll cnt = 0;
    int n1 = mid-left;
    int n2 = right-mid;
    for(int i=0; i<n1; ++i) L[i] = A[left+i];
    for(int i=0; i<n2; ++i) R[i] = A[mid+i];
    L[n1] = R[n2] = inf;
    int i=0, j=0;
    for(int k=left; k<right; ++k){
        if(L[i] <= R[j]){
            A[k] = L[i++];
        }
        else{
            A[k] = R[j++];
            cnt += n1 - i;
        }
    }

    return cnt;
}

ll mergeSort(vector<int> A, int left, int right){
    int mid;
    ll v1, v2, v3;
    if(left+1 < right){
        mid = (left+right)/2;
        v1 = mergeSort(A, left, mid);
        v2 = mergeSort(A, mid, right);
        v3 = merge(A, left, mid, right);
        return v1+v2+v3;
    }

    return 0;
}

int bubleSort(vector<int> A){
    int cnt = 0;
    for(int i=0; i<A.size(); ++i) {
        for(int j=A.size()-1; j>=i+1; --j) {
            if(A[j] < A[j-1]) { swap(A[j], A[j-1]); ++cnt; }
        }
    }
    return cnt;
}

