        int fr=i+(i-num);
        res+=(fr-i);
        bit.add(tar+1,1);
      }
      ans=min(ans,res);
    }
  }

  if(ok==false){
    cout<<"-1"<<endl;
    return 0;
  }else cout<<ans<<endl;

  return 0;
}

