#include <bits/stdc++.h>
using namespace std;

const int inf = 1e9;

int solve(vector<int> &c, int index) {
  int n = c.size(), ans = 0;
  vector<pair<int, int>> even, odd, combined(n);
  for (int i = 0; i < n; i++) {
    if (i % 2 == ((index >> i) & 1)) {
      even.emplace_back(c.at(i), i);
    } else {
      odd.emplace_back(c.at(i), i);
    }
  }
  for (int i = 1; i < even.size(); i++) {
    for (int j = i - 1; j >= 0; j--) {
      if (even.at(j) <= even.at(j + 1)) break;
      swap(even.at(j), even.at(j + 1));
    }
  }
  for (int i = 1; i < odd.size(); i++) {
    for (int j = i - 1; j >= 0; j--) {
      if (odd.at(j) <= odd.at(j + 1)) break;
      swap(odd.at(j), odd.at(j + 1));
    }
  }
  for (int i = 0; i < n; i++) {
    if (i % 2 == 0) {
      combined.at(i) = even.at(i / 2);
    } else {
      combined.at(i) = odd.at(i / 2);
    }
  }
  for (int i = 1; i < n; i++) {
    if (combined.at(i).first < combined.at(i - 1).first) return inf;
  }
  for (int i = 1; i < n; i++) {
    for (int j = i - 1; j >= 0; j--) {
      if (combined.at(j).second <= combined.at(j + 1).second) break;
      swap(combined.at(j), combined.at(j + 1));
      ans++;
    }
  }
  return ans;
}

int main() {
  int n, ans = inf;
  cin >> n;
  vector<int> a(n), b(n);
  for (int i = 0; i < n; i++) cin >> a.at(i);
  for (int i = 0; i < n; i++) cin >> b.at(i);
  for (int i = 0; i < (1 << n); i++) {
    if (__builtin_popcount(i & 0x55555) != __builtin_popcount(i & 0xAAAAA)) continue;
    vector<int> c(n);
    for (int j = 0; j < n; j++) {
      if (i & (1 << j)) {
        c.at(j) = b.at(j);
      } else {
        c.at(j) = a.at(j);
      }
    }
    ans = min(ans, solve(c, i));
  }
  if (ans == inf) {
    cout << -1 << endl;
  } else {
    cout << ans << endl;
  }
}

