struct BIT {
    vector<int> dat;
    int n;
    BIT(int n_) {
        n=n_;
        dat=vector<int>(n,0);
    }
    void add(int i,int x) {
        while(i<=n) {
            dat[i]+=x;
            i+=i&-i;
        }
    }
    int sum(int i) {
        int ret=0;
        while(i>0) {
            ret+=dat[i];
            i-=i&-i;
        }
        return ret;
    }
};

