	ll a[n],b[n];
	forn(i,n){
		cin >> a[i];
	}
	forn(i,n){
		cin >> b[i];
	}
	ll ans = INF;
	forn(i,1<<n){
		if(__builtin_popcount(i)%2==0){
			vp64 even,odd;
			forn(j,n){
				if(i&&(1<<j)){
					if(j%2){
						even.pb(mp(b[j],j));
					}
					else{
						odd.pb(mp(b[j],j));
					}
				}
				else{
					if(j%2 == 0){
						even.pb(mp(a[j],j));
					}
					else{
						odd.pb(mp(a[j],j));
					}
				}
			}
			sort(all(even));
			sort(all(odd));
			bool check = 1;
			forn(i,sz(odd)){
				if(odd[i]<even[i]) check=0;
			}
			forsn(i,1,sz(even)){
				if(odd[i-1]>even[i]) check=0;
			}
			if(check){
				int temp[n];
				forn(i,sz(odd)) temp[2*i]=even[i].se,temp[2*i+1]=odd[i].se;
