// fact(n)%MOD, invFact(n)%MOD, inv(n)%MOD, nCk
// Constructor O(N)
// other O(1)
template<typename T>
class Choose {
public:
	vector<T> fact, inv, invFact;

	Choose(T N) :fact(N), inv(N), invFact(N) {
		inv[1] = 1;
		FOR(i, 2, inv.size()) inv[i] = MOD - (MOD / i) * inv[MOD % i] % MOD;
		fact[0] = invFact[0] = 1;
		FOR(i, 1, fact.size()) {
			fact[i] = fact[i - 1] * i % MOD;
			invFact[i] = (invFact[i - 1] * inv[i]) % MOD;
		}
	}

	//Get nCk
	T operator () (T n, T k) const {
		if (not ((T)0 <= k and k <= n)) return 0;
		return (((fact[n] * invFact[k]) % MOD) * invFact[n - k]) % MOD;
	}
};

// count invitation. O(NlogN)
template<class T>
int invitation_count(vector<T> &a) {
	int count = 0;
	int n = a.size();
	if (n > 1) {
		vector<T> b(a.begin(), a.begin() + n / 2);
		vector<T> c(a.begin() + n / 2, a.end());
		count += invitation_count(b);
		count += invitation_count(c);

		for (int i = 0, j = 0, k = 0; i < n; ++i)
			if (k == c.size()) a[i] = b[j++];
			else if (j == b.size()) a[i] = c[k++];
			// invitation_count: i < j and a_i  > a_j
			// this case:        j < k and b[j] > c[k]
			else if (b[j] > c[k]) {
				a[i] = c[k++];
				count += n / 2 - j;
			}
			else {
				a[i] = b[j++];
			}
	}
	return count;
}


int solve(int S, const vector<int>& A, const vector<int>&B) {
	priority_queue<int, vector<int>, greater<int>> As;
	priority_queue<int, vector<int>, greater<int>> Bs;
	map<int, priority_queue<int, vector<int>, greater<int>>> Amemo;
	map<int, priority_queue<int, vector<int>, greater<int>>> Bmemo;
	REP(i, A.size()) {
		if ((S >> i) & 1) {
			As.push(A[i]);
			Amemo[A[i]].push(i);
		}
	}
	REP(i, B.size()) {
		if (((S >> i) & 1) == 0) {
			Bs.push(B[i]);
			Bmemo[B[i]].push(i);
		}
	}
	int res = 0;

	int last = -1;
	vector<int> poses(B.size());
	REP(i, A.size()) {
		if (i % 2 == 0) {
			int a = As.top(); As.pop();
			if (last > a) return inf;
			int index = Amemo[a].top(); Amemo[a].pop();
			poses[index] = i;
			res += max(index - i, 0LL);
			last = a;
		}
		else {
			int b = Bs.top(); Bs.pop();
			if (last > b) return inf;
			int index = Bmemo[b].top(); Bmemo[b].pop();
			poses[index] = i;
			res += max(index - i, 0LL);
			last = b;
		}
	}

	return invitation_count(poses);
}

void solve() {
	int N; cin >> N;
	vector<int> A(N); for (auto& a : A) cin >> a;
	vector<int> B(N); for (auto& a : B) cin >> a;

	REP(i, N) if(i % 2 == 1){
		swap(A[i], B[i]);
	}

	int k = N / 2;
	if (N % 2 == 1) ++k;

	int res = inf;
	for (int x = (1 << k) - 1; x < (1 << N); ) {
		res = min(res, solve(x, A, B));
		int t = x | (x - 1);
		x = (t + 1) | (((~t & -~t) - 1) >> (__builtin_ctz(x) + 1));
	}

	cout << (res >= inf ? -1 : res) << endl;
}

