        if (A[which][j] < val[last]) continue;
        ans = min(ans, inv + go(msk ^ (1 << j), j + j + which, n));
//        cout << which << " w : " << msk << ", " << val[last] << " --> " << j << " ? " << val[j + j + which] << ", " << ans << endl;
    }

    return ans;
}

