int dfs( int idx, int last, int al, int bl ) {
    if( idx == n ) return 0;
    int& ret = dp[idx][last][al][bl];
    if( ~ret ) return ret;

    ret = inf;
    if( al <= a[idx] and al >= last ) {
        ret = min(ret, dfs( idx + 1, al, a[idx], b[idx] ));
    }
    if( b[idx] >= last ) {
        ret = min(ret, 1 + dfs( idx + 1, b[idx], bl, al ));
    }
    return ret;
}

