}

int popcnt(int x)
{
	int cnt = 0;
	while (x)
	{
		cnt++;
		x &= x - 1;
	}
	return cnt;
}

void solve()
{
	ll n; cin >> n;
	const ll MAX_N = 8;
	vector<vector<ll>> v(n);
	int sz = 2;
	for (int j = 0; j < sz; ++j)
		for (int i = 0; i < n; ++i)
		{
			int x; cin >> x;
			v[i].push_back(x);
		}

	int dp[1 << MAX_N][MAX_N];

	for (int i = 0; i < (1 << MAX_N); ++i)
		for (int j = 0; j < MAX_N; ++j)
			dp[i][j] = -1;

	for (int i = 0; i < n; ++i)
		dp[(1 << i)][i] = i;

	for (int i = 1; i < (1 << n); ++i)
	{
		int cnt = popcnt(i);
		int side_effect = cnt - 1;
		for (int j = 0; j < n; ++j)
			if ((i & (1 << j)) && dp[i][j] == -1)
			{
				dp[i][j] = INF;
				int umask = i ^ (1 << j);
				int shift = abs(cnt - 1 - (j + side_effect));
				for (int k = 0; k < n; ++k)
					if ((umask & (1 << k)) && value(v, j, cnt - 1) >= value(v, k, cnt - 2))
						dp[i][j] = min(dp[umask][k] + shift, dp[i][j]);
				--side_effect;
			}
	}

	int ans = INF;

	for (int i = 0; i < n; ++i)
		ans = min(ans, dp[(1 << n) - 1][i]);

	if (ans < INF)
		cout << ans;
	else
		cout << -1;
}

int main() {
	cin.tie(0);
	cout.tie(0);
	ios::sync_with_stdio(0);
#ifdef _DEBUG
	freopen("in.txt", "r", stdin);
	//freopen("out.txt", "w", stdout);
#endif
	solve();
	return 0;
}

