struct state {
	vector<int> p;
	int mask;

	state() {
	}

	state(vector<int> tp, int tmask = 0) {
		p = tp;
		mask = tmask;
	}

	bool operator<(const state & s) const {
		if (mask != s.mask) {
			return (mask < s.mask);
		}
		return (p < s.p);
	}
};

queue<state> q;
set<state> v;
map<state, int> d;

bool ok(state s) {
//	cerr << s.mask << endl;
	vector<int> v;
	for (int i = 0; i < n; i++) {
		if (s.mask & (1 << i)) {
			v.push_back(b[s.p[i]]);
		} else {
			v.push_back(a[s.p[i]]);
		}
	}
	for (int i = 0; i < n - 1; i++) {
		if (v[i + 1] < v[i]) {
//			cerr << v[i] << " " << v[i + 1] << endl;
			return false;
		}
	}
	for (int i = 0; i < n; i++) {
		cerr << v[i] << " ";
	}
