		vs.push_back(i);
	}
	state start(vs, 0);
	d[vs] = 0;
	q.push(vs);
	int it = 0;
	while (!q.empty()) {
		state cur = q.front();
		q.pop();
		v.insert(cur);
		it++;
		if (it > LIMIT) {
			break;
		}
		if (ok(cur)) {
			cout << d[cur] << endl;
			return 0;
		}
		for (int i = 0; i < n - 1; i++) {
			state nnext = cur;
			swap(nnext.p[i], nnext.p[i + 1]);
			int bi = (nnext.mask & (1 << i)) >> i;
			int bii = (nnext.mask & (1 << (i + 1))) >> (i + 1);
			if (!(bi ^ bii)) {
				nnext.mask ^= (1 << i);
				nnext.mask ^= (1 << (i + 1));
			}
			if (!v.count(nnext)) {
				q.push(nnext);
				d[nnext] = d[cur] + 1;
			}
		}
	}
	cout << "-1" << endl;
