ll hanten(vector <ll> arr){
    ll ans = 0;
    ll size = arr.size();
    REP(i, size){
        for(int j=i+1; j<size; j++){
            if (arr[i] > arr[j]){
                ans++;
            }
        }
    }
    return ans;
}

void shushoku(vector <ll> &arr, ll pad){
    vector <ll> arr2 = arr;
    sort(arr2.begin(), arr2.end());
    ll size = arr.size();
    REP(i, size){
        REP(j, size){
            if (arr2[i] == arr[j]){
                arr[j] += 200*i + pad;
                break;
            }
        }
    }
}

bool shushoku2(vector <ll> &arr){
    vector <ll> arr2 = arr;
    sort(arr2.begin(), arr2.end());
    ll size = arr.size();
    REP(i, size){
        bool done = false;
        if (i%2 == 0){
            for(int j=0; j<size; j+=2){
                if (arr2[i] == arr[j]){
                    arr[j] += 100*(i+1);
                    done = true;
                    break;
                }
            }
        }
        if (i%2 == 1) {
            for(int j=1; j<size; j+=2){
                if (arr2[i] == arr[j]){
                    arr[j] += 100*(i+1);
                    done = true;
                    break;
                }
            }
        }
        if (!done){
            return true;
        }
    }
    return false;
}



