            else if (y == 0) {
                if ((p[j].second.second + j)%2 == 1) {
                    check = false;
                    break;
                }
            }else if (y > 0) {
                for (int k = j-y; k <= j; k++) {
                    if ((p[k].second.second + k)%2 == 0) continue;
                    for (int l = k+1; l <= j; l++) {
                        if ((p[l].second.second + p[k].second.second)%2==0) continue;
