int main() {
   ios_base::sync_with_stdio(false);
   cin >> N;
   for (int i = 0; i < N; ++i) cin >> A[i][0];
   for (int i = 0; i < N; ++i) cin >> A[i][1];
   for (int i = 1; i < N; i += 2) swap(A[i][0], A[i][1]);
   for (int mask = 0; mask < (1 << N); ++mask) {
      for (int last = 0; last < N; ++last) {
         dp[mask][last] = 1 << 30;
      }
   }
   for (int i = 0; i < N; ++i) {
      dp[1 << i][i] = 0;
   }
   for (int mask = 1; mask + 1 < (1 << N); ++mask) {
      int cnt = __builtin_popcount(mask);
      for (int last = 0; last < N; ++last) {
         if (dp[mask][last] == (1 << 30)) continue;
         for (int nxt = 0; nxt < N; ++nxt) if (!(mask & (1 << nxt)) && A[last][cnt & 1 ^ 1] <= A[nxt][cnt & 1]) {
            dp[mask | (1 << nxt)][nxt] = min(dp[mask | (1 << nxt)][nxt], dp[mask][last] + cnt - __builtin_popcount(mask & ((1 << nxt) - 1)));
         }
      }
   }
   int ans = *min_element(dp[(1 << N) - 1], dp[(1 << N) - 1] + N);
   if (ans == (1 << 30)) {
      ans = -1;
   }
   cout << ans << "\n";
   return 0;
}

