inline int read()
{
	int x = 0,f = 1; char ch = getchar();
	for(;!isdigit(ch);ch=getchar()) {if(ch=='-') f = -1;}
	for(; isdigit(ch);ch=getchar()) {x = x*10+ch-48;}
	return x*f;
}

const int mxN = 18;
const int INF = 1e4;
int n,ans;
int a[mxN+3],b[mxN+3],c[mxN+3],d[mxN+3],p[mxN+3],p2[mxN+3];

bool cmp(int x,int y) {return c[x]<c[y]||(c[x]==c[y]&&x<y);}

void solve()
{
//	printf("solve\n");
//	for(int i=1; i<=n; i++) printf("%d ",c[i]); puts("");
//	for(int i=1; i<=n; i++) printf("%d ",d[i]); puts("");
	for(int i=1; i<=n; i++) p[i] = i;
	sort(p+1,p+n+1,cmp);
	for(int l=1; l<=n; l++)
	{
		int r = l; while(r<n&&c[p[r+1]]==c[p[l]]) {r++;}
		int cnt0 = 0,cnt1 = 0;
		for(int i=l; i<=r; i++) {if(i&1) cnt1--; else cnt0--;}
		for(int i=l; i<=r; i++) {if(d[p[i]]) cnt1++; else cnt0++;}
//		printf("[%d,%d]",l,r); puts("");
		if(cnt0||cnt1) return;
		for(int i=l,j0=l,j1=l; i<=r; i++)
		{
			if(i&1)
			{
				while(j1<r&&!d[p[j1]]) {j1++;}
				p2[i] = p[j1]; j1++;
			}
			else
			{
				while(j0<r&&d[p[j0]]) {j0++;}
				p2[i] = p[j0]; j0++;
			}
		}
		l = r;
	}
	int ret = 0;
	for(int i=1; i<=n; i++) for(int j=i+1; j<=n; j++) ret += (p2[i]>p2[j]);
	ans = min(ans,ret);
}

int main()
{
	n = read(); ans = INF;
	for(int i=1; i<=n; i++) a[i] = read();
	for(int i=1; i<=n; i++) b[i] = read();
	for(int sta=0; sta<(1<<n); sta++)
	{
		for(int i=1; i<=n; i++)
		{
			c[i] = (sta&(1<<i-1))?b[i]:a[i];
			d[i] = ((sta>>i-1)^i)&1;
		}
		solve();
	}
	printf("%d\n",ans==INF?-1:ans);
	return 0;
}

