ll bubble_sort(vector<ll> &A){
    ll N = A.size();    
    ll cnt=0;
    // iまで見る
    for(int i=N-1; i>=0; i--){
        FOR(j, 0, i){
            if(A[j] > A[j+1]){
                swap(A[j], A[j+1]);
                cnt++;
            }
        }
    }
    return cnt;
}

