using namespace std;

#define N  100005

int n;

int a[20],b[20];

int ass[20];

int mini=1e9;

solve()
{
	vector<pair<int,int>> v;
	for(int i=0;i<n;i++)
	{
		if(ass[i]) v.pb({b[i],1});
		else v.pb({a[i],0});
	}
	int swaps=0;
	for(int i=0;i<n;i++)
	{
		for(int j=i+1;j<n;j++)
		{
			if(v[i].F>v[j].F) 
			{
				swaps++;
			}
		}
	}
	map<int,int> dde,ddo;
	vector<pair<int,int>> vs=v; sort(all(vs));
	for(int i=0;i<n;i++)
	{
		if(i%2==0) dde[vs[i].F]++;
		else ddo[vs[i].F]++;
	}
	map<int,int> cce,cco;
	for(int i=0;i<n;i++)
	{
		if(ass[i]==1)
		{
			if(i%2==1) cce[v[i].F]++;
			else cco[v[i].F]++;
		}
		else
		{
			if(i%2==0) cce[v[i].F]++;
			else cco[v[i].F]++;
		}
	}
	bool isok=1;
	for(int i=1;i<=50;i++) if(cce[i]!=dde[i]||cco[i]!=ddo[i]) isok=0;
	if(isok) mini=min(mini,swaps);
}

void fun(int idx)
{
	if(idx==n)
	{
		int cnt=0;
		for(int i=0;i<n;i++) cnt+=ass[i];
		if(cnt%2==0) solve();
	}
	else
	{
		ass[idx]=0;
		fun(idx+1);
		ass[idx]=1;
		fun(idx+1);
	}
}

