	{
		cin>>n;
		for(int i=0;i<n;i++) cin>>a[i];
		for(int i=0;i<n;i++) cin>>b[i];
		fun(0);
		if(mini!=1e9) cout<<mini<<endl;
		else cout<<-1<<endl;
	}
	return 0;
}

