int main(){
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    /*
        ある数列を広義単調増加にするために必要な最小スワップ数について。
        広義単調増加にするということと、転倒数 0 ということが同値。
        ①スワップ 1 回で転倒数は高々 1 しか減らない。
        ②広義単調増加でないならば必ずスワップ によって転倒数を 1 減らせる箇所がある。
        ①②より最小スワップ数は転倒数
    */

    int n; cin >> n;
    vector<int> a(n), b(n);
    rep(i, n) cin >> a[i] >> b[i];

    int const inf = 1<<29;
    vector<vector<int>> dp((1<<n)+1, vector<int>(51, inf));
    dp[0][0];
    // dp[mask][s] := mask にある集合を左詰めで広義単調増加に並べ、さらに最後の数字が s であるようにした時の最小スワップ数（転倒数）

    rep(bit, 1<<n) {
        int cnt = __builtin_popcount(bit);

        // まだ使っていない要素について (元の位置, 自分より左にいる要素の数+1) を持つ
        vector<pair<int, int>> rest;
        int itr = cnt;
        rep(i, n) if(!(bit&(1<<i))) rest.emplace_back(i, itr++);

        rep(s, 51) {
            if (dp[bit][s] == inf) continue;
            for(auto p: rest){
                int ns = -1;
                if (abs(p.first - cnt)%2 == 0) ns = a[p.first];
                else ns = b[p.first];

                if (ns>=s) chmin(dp[bit | 1<<p.first][ns], dp[bit][s] + p.second - cnt);
            }
        }
    }

    int ans = inf;
    rep(s, 51) chmin(ans, dp[(1<<n)-1][s]);
    cout << (ans == inf? -1:ans) << endl;
    return 0;
}

