int main() {
    int n, ans = 1e9, i, j, k;

    scanf("%d", &n);

    for (i = 1; i <= n; i++) scanf("%d", &a[i]);
    for (i = 1; i <= n; i++) scanf("%d", &b[i]);

    n++;

    for (i = 0; i < (1 << n); i++) {
        for (j = 0; j < n; j++) {
            dp[i][j] = 1e9;
        }
    }

    dp[1][0] = 0;

    for (i = 0; i < (1 << n); i++) {
        for (j = 0; j < n; j++) {
            int x;

            if (dp[i][j] == 1e9) continue;

            if (__builtin_popcount(i) % 2 == j % 2) {
                x = b[j];
            } else {
                x = a[j];
            }

            for (k = 0; k < n; k++) {
                int y, c;

                if ((i >> k) & 1) continue;

                if (__builtin_popcount(i) % 2 == k % 2) {
                    y = a[k];
                } else {
                    y = b[k];
                }

                if (x > y) continue;

                c = k - __builtin_popcount(i & ((1 << k) - 1));

                dp[i | (1 << k)][k] = min(dp[i | (1 << k)][k], dp[i][j] + c);
            }
        }
    }

    for (i = 0; i < n; i++) ans = min(ans, dp[(1 << n) - 1][i]);

    if (ans == 1e9) ans = -1;

    printf("%d\n", ans);

    return 0;
}

