int cal[18][1<<18];
int dp[1<<18][50];

int a[20],b[20];

int main(){
	int n;cin>>n;
	rep(i,n)scanf("%d",&a[i]),a[i]--;
	rep(i,n)scanf("%d",&b[i]),b[i]--;
	rep(i,n)rep(j,1<<n){
		rep(k,n){
			if(k>i&&(j>>k&1))cal[i][j]++;
			if(k<i&&!(j>>k&1))cal[i][j]++;
		}
	}
	memset(dp,0x3f,sizeof(dp));
	dp[0][0]=0;
	rep(i,1<<n)rep(j,50){
		if(dp[i][j]==INF)continue;
		rep(k,n){
			if(i>>k&1)continue;
			int o=cal[k][i]%2;
			int D=(o==0?a[k]:b[k]);
			if(j>D)continue;
			dp[i|1<<k][D]=min(dp[i|1<<k][D],dp[i][j]+cal[k][i]);
		}
	}
	int Min=INF;
	rep(i,50){
		Min=min(Min,dp[(1<<n)-1][i]);
	}
	if(Min==INF)puts("-1");
	else cout<<Min/2<<endl;
}

