class Bit
{
  public:
  ll size;
  vector<ll> data;
  Bit(ll n)
  {
    data.resize(n+1);
    //REP(i,n)
    //  data[i]=0;
    size=n;
  }
  //(1-i)までの合計を返す
  ll Sum(ll i){
    ll s = 0;
    while (i > 0){
        s += data[i];
        i -= i & -i;
    }
    return s;
  }
  //Add
  void Add(ll i,ll x){
    while (i <= size){
      data[i] += x;
      i += i & -i;
    }
  }
};

