void dfs(int pos, int cnt, vp s){
    if(pos == n - 1){
        bool f = true;
        for(int i = 1; i < n; i++){
            if(s[i].fi >= s[i - 1].fi) continue;
            f = false;
        }
        if(f) res = min(res, cnt);
        return;
    }
    dfs(pos + 1, cnt, s);
    swap(s[pos].fi, s[pos].se);
    swap(s[pos + 1].fi, s[pos + 1].se);
    swap(s[pos], s[pos + 1]);
    dfs(pos + 1, cnt + 1, s);
}

