struct Card
{
  int A, B;
};

class Solve
{
  int N;
  vector<Card> V;
  vector<vector<int>> DP;
  vector<vector<bool>> visited;
  using Info = tuple<int, int>;
  queue<Info> Q;

public:
  Solve(int N, vector<Card> const &V) : N{N}, V{V}, DP((1 << N), vector<int>(N + 1, infty)), visited((1 << N), vector<bool>(N + 1, false))
  {
    DP[0][N] = 0;
    Q.push(Info(0, N));
  }

  int answer()
  {
    if (N == 1)
    {
      return 0;
    }
    make_DP();
    int ans{infty};
    for (auto i = 0; i < N; ++i)
    {
      ch_min(ans, DP[(1 << N) - 1][i]);
    }
    return ans;
  }

private:
  void make_DP()
  {
    while (!Q.empty())
    {
      int mask, index;
      tie(mask, index) = Q.front();
      Q.pop();
      if (!visited[mask][index])
      {
#if DEBUG == 1
        cerr << "mask = " << mask << ", index = " << index << endl;
#endif
        visited[mask][index] = true;
        int cnt{count_one(mask)};
        for (auto i = 0; i < N; ++i)
        {
          if (((mask >> i) & 1) == 0)
          {
            int n_mask{mask | 1 << i};
            // DP[n_mask][i] <- DP[mask][index]
            if (index == N)
            {
              ch_min(DP[n_mask][i], DP[mask][index]);
              Q.push(Info(n_mask, i));
            }
            else
            {
              int now_number{cnt % 2 == 1 ? V[index].A : V[index].B};
              int next_number{(cnt + 1) % 2 == 1 ? V[i].A : V[i].B};
              if (now_number <= next_number)
              {
#if DEBUG == 1
                cerr << index << "(" << now_number << ") -> " << i << "(" << next_number << ")" << endl;
#endif
                int dist{0};
                for (auto j = i; j < N; ++j)
                {
                  dist += (mask >> j & 1);
                }
                ch_min(DP[n_mask][i], DP[mask][index] + dist);
                Q.push(Info(n_mask, i));
              }
            }
          }
        }
      }
    }
  }

  static int count_one(int mask)
  {
    int res{0};
    while (mask > 0)
    {
      res += mask & 1;
      mask >>= 1;
    }
    return res;
  }
};

int main()
{
  int N;
  cin >> N;
  vector<Card> V(N);
  for (auto i = 0; i < N; ++i)
  {
    cin >> V[i].A;
  }
  for (auto i = 0; i < N; ++i)
  {
    cin >> V[i].B;
  }
  for (auto i = 1; i < N; i += 2)
  {
    swap(V[i].A, V[i].B);
  }
  Solve solve(N, V);
  int ans{solve.answer()};
  if (ans == infty)
  {
    cout << -1 << endl;
  }
  else
  {
    cout << ans << endl;
  }
}

