    for(int i = 1; i <= n; i++){
        for(int pre = 0; pre < (1<<n); pre++){
            //previously taken
            for(int l = 0; l < 51; l++){
                //last number
                for(int j = 0; j < n; j++){
                    //take # j
                    if(!(pre&(1<<j))){
                        int cur = pre|(1<<j);
                        int val;
                        if((j^i)&1){
                            //if same parity
                            val = a[j];
                        }
                        else{
                            val = b[j];
                        }
                        if(val < l)
