    rep(i,0,S.size()){
        bool flag=1;
        rep(j,i,S.size()){
            if(S[i]==T[j]){
                ret+=j-i;
                flag=0;
                per(k,j,i+1) std::swap(T[k],T[k-1]);
                break;
            }
        }
        if(flag) return INF;
    }
    return ret;
}
