        dp[0][0]=0;
        const int all=(1<<n)-1;

        for(int s=0; s<=all; ++s)
        {
            int cnt=__popcount(s);
            bool pari=cnt&1;
            for(int i=0; i<n; ++i)
            {
                if(s>>i&1)
