  rep(i,n) cin >> card[1][i];

  // dp tanle init
  rep(i,1<<n) rep(j,51) dp[i][j] = 1e10;
  dp[0][0] = 0;

  // solve
  rep(state,(1<<n)-1) rep(maxNum,51) {
    ll nextIdx = __builtin_popcountll(state);

    rep(i,n){
      if( ((state>>i) & 1) == 1 ) continue;
      ll cardFlag = abs(nextIdx - i)%2;

      if(card[cardFlag][i] >= maxNum ){ // 設置できる
        // 遷移コストの計算
        ll mvCost = 0;
        FOR(j,0,i) if(((state>>j) & 1) == 0 ) mvCost++;

        chmin(dp[state | (1<<i)][card[cardFlag][i]], dp[state][maxNum] + mvCost);
      }
    }
  }

  ll ans = INF;
  rep(i,51) ans = min(dp[(1<<n)-1][i],ans);

  if(ans == INF)  cout << -1 << endl;
  else            cout << ans << endl;

  return 0;
}

