#include<bits/stdc++.h>
using namespace std;
#define int long long 

const int MAX_N = 20;
const int MAX_val = 60;
const int inf = 1e8;

int A[MAX_N],B[MAX_N];
int dp[(1<<MAX_N)][MAX_val];

void chmin(int &a, int b ){ if( a > b ){ swap(a,b);} return;}

signed main(void){

  int N; cin >> N;
  for(int i = 0; i < N; i++){ cin >> A[i];}
  for(int i = 0; i < N; i++){ cin >> B[i];}

  for(int i = 0; i < (1<<MAX_N); i++){
    for(int j = 0; j < MAX_val; j++){ 
      dp[i][j] = inf;
    }
  }

  dp[0][0] = 0; //まだ１枚も揃っていない状態を0とする

  for(int bit = 0; bit < (1<<N); bit++){
    //次に何を後ろに持ってくるかが問題
    int cnt = 0;
    for(int k = 0; k < MAX_N; k++){ 
      if( bit>>k&1 ){ cnt++;}
    } //今まで揃えたカードの枚数を記録しておく

    for(int last = 0; last < MAX_val; last++){
      if( dp[bit][last] == inf ){ continue;} //ここから遷移を伸ばす必要はない

      int dist = 0;

      for(int i = 0; i < N; i++){ 


        if( !(bit & (1<<i)) ){ 
          //次にこれを後ろに持ってくることを考える
          //今、このカードはcnt+dist番目にいる

          int origin = i; //元々はi番目にいた　今はcnt+distにいる
                          //これをcntまで持っていきたい

          int next;
          int parity = abs(cnt-origin)%2;


          if(parity){ next = B[i];}
          else{ next = A[i];}


          if( next < last ){ continue;}

          chmin(dp[bit|(1<<i)][next], dp[bit][last]+dist );
          dist++;

        }//if-bit
      } //for-i
    }//for-last
  }//for-bit

  int ans = inf;

  for(int i = 1; i < MAX_val; i++){
    chmin(ans, dp[(1<<N)-1][i]);
  }

  if( ans == inf ){ ans = -1;}

  cout << ans << endl;

  return 0;
}

