typedef long long ll;
typedef pair<ll,ll> P;
const ll INF=2e18;
const ll MOD=1e9+7;

ll N;
ll A[20],B[20];
ll SwapNum(vector<P>& v){
    ll ret=0;
    for(ll i=0;i<v.size();i++){
        for(ll j=i+1;j<v.size();j++){
            if(v[i].first>v[j].first){
                ret++;
                swap(v[i],v[j]);
            }
        }
    }
    return ret;
}
ll ConcatNum(vector<P>& v,ll s,ll t){
    ll cnt=0;
    ll fir=0;
    ll ret=0;
    for(ll i=s;i<t;i++){
        if((v[i].second-i)%2==1){
            cnt++;
            if(cnt==1){
                fir=i;
                ret=-1;
            }else{
                cnt=0;
                ret+=(i-fir)*2-1;
            }
        }
    }
    return ret;
}
int main(){
    cin>>N;
    for(ll i=0;i<N;i++){
        cin>>A[i];
    }
    for(ll i=0;i<N;i++){
        cin>>B[i];
    }
    ll ans=INF;
    for(ll state=0;state<(1<<N);state++){
        ll bitCnt=0;
        vector<ll> v(N);
        vector<P> pV(N);
        for(ll i=0;i<N;i++){
            if(state & (1<<i)){
                bitCnt++;
                v[i]=B[i];
                pV[i]=P(B[i],i+1);
            }else{
                v[i]=A[i];
                pV[i]=P(A[i],i);
            }
        }
        if(bitCnt%2==1)continue;

        unordered_map<ll,ll> mp;
        for(auto x:v){
            mp[x]++;
        }
        bool isAble=true;
        ll swapNum=SwapNum(pV);
        for(ll i=0;i<pV.size();i++){
            if((pV[i].second-i)%2!=0){
                if(mp[pV[i].first]==1){
                    isAble=false;
                    break;
                }
                else{
                    ll concatNum=ConcatNum(pV,i,i+mp[pV[i].first]);
                    if(concatNum!=-1){
                        swapNum+=concatNum;
                        i=i+mp[pV[i].first]-1;
                    }else{  
                        isAble=false;
                        break;
                    }
                }
            }
        }
        if(isAble)
            ans=min(ans,swapNum);
    }
    cout<<((ans==INF)?-1:ans)<<endl;
    return 0;
}

