//各ペアの大きい方の最小値
int minimum(vector<pair<int,int> > a, int now){
    int re = max(a.at(now).first, a.at(now).second) ;
    for (size_t i = now+1; i < a.size(); i++)
    {
        if ( max( a.at(i).first,a.at(i).second ) < re)
        {
            re = max( a.at(i).first,a.at(i).second ) ;
        }

    }
    return re ;
}

void dp(vector<pair<int,int> > a, int n, int now, int nowb, int swaps, int &ans){
    if (n - now == 2)
    {
        if (a.at(n-2).first <a.at(n-1).first )
        {
            if (swaps < ans)
            {
                ans = swaps ;
            }

        }else if (a.at(n-1).second < a.at(n-2).second)
        {
            if (swaps + 1 < ans)
            {
                ans = swaps + 1 ;
            }

        }


    }else
    {
        int border = minimum(a,now) ;
        bool first = true;
        for (size_t i = now; i < n; i++)
        {
            if (first == true)
            {
                if (a.at(i).first >= nowb && a.at(i).first <= border)
                {
                    swaps += i - now ;
                    for (size_t j = now; j < i; i++)
                    {
                        swap(a.at(j).first, a.at(j+1).second) ;
                        swap(a.at(j).second, a.at(j+1).first) ;
                    }
                    dp(a,n,now+1, a.at(now).first, swaps, ans) ;
                    for (size_t j = i; j > now; j--)
                    {
                        swap(a.at(j).first, a.at(j+1).second) ;
                        swap(a.at(j).second, a.at(j+1).first) ;
                    }


                }
                first = false ;
            }else
            {
                if (a.at(i).second >= nowb && a.at(i).second <= border)
                {
                    swaps += i - now ;
                    for (size_t j = now; j < i; i++)
                    {
                        swap(a.at(j).first, a.at(j+1).second) ;
                        swap(a.at(j).second, a.at(j+1).first) ;
                    }
                    dp(a,n,now+1, a.at(now).first, swaps, ans) ;
                    for (size_t j = i; j > now; j--)
                    {
                        swap(a.at(j).first, a.at(j+1).second) ;
                        swap(a.at(j).second, a.at(j+1).first) ;
                    }


                }
                first = true;
            }


        }


    }
    return;
}

