int N;
int A[18], B[18];

int dp[1<<18][51]; // 残り集合 最後の値がk

int main() {
	cin >> N;
	REP(i, N) cin >> A[i];
	REP(i, N) cin >> B[i];

	fill(dp[0], dp[1<<18], INF);

	dp[(1<<N)-1][0] = 0;

	for (int s = (1<<N)-1; s >= 0; --s) {
		REP(k, 51) {
			if (dp[s][k] == INF) continue;
			int cnt = 0;
			REP(j, N) if (s >> j & 1 ^ 1) ++cnt;
			// cnt番目に置く

			int c = 0;
			REP(j, N) {
				if (s >> j & 1) {
					int dif = abs(cnt - j);
					int cur = dif & 1 ? B[j] : A[j];
					if (cur >= k) chmin(dp[s^(1<<j)][cur], dp[s][k] + max(j - cnt, 0));
				}
				else ++c;
			}
		}
	}

	int ans = INF;
	REP(i, 51) chmin(ans, dp[0][i]);
	if (ans == INF) ans = -1;
	cout << ans << endl;

	return 0;
}

