using namespace std;
int main() {
    ll n;
    std::cin >> n;
    vector<pair<ll,ll>> ab(n);
    for (int i = 0; i < n; i++) {
        std::cin >> ab[i].first;
    }
    for (int i = 0; i < n; i++) {
        std::cin >> ab[i].second;
    }

    ll ans = 1e9;

    for (int i = 0; i < (1<<n); i++) {
        ll sum = 0;
        for (int j = 0; j < n; j++) {
            if(i & (1<<j))sum++;
        }
        if(sum%2==1)continue;

        vector<ll> member;
        vector<ll> memberc;
        for (int j = 0; j < n; j++) {
            if(i & (1<<j)){
                member.push_back(ab[j].second);
            }else{
                member.push_back(ab[j].first);
            }
        }

        for (auto e : member) {
            memberc.push_back(e);
        }
        sort(memberc.begin(),memberc.end());

        vector<bool> used(n,false);
        ll dif = 0;
        bool ok = true;
        for (int j = 0; j < n; j++) {
            bool exist = false;
            for (int k = 0; k < n; k++) {
                if(used[k])continue;
                if(member[j] == memberc[k]){
                    if(i & (1<<j)){
                        if( (k-j+1000000)%2==0 ){
                            continue;
                        }
                        dif+= abs(k-j);
                        used[k] = true;
                        exist = true;

                        if(j==k){
                            dif+=2;
                        }

                        break;
                    }else{
                        if( (k-j+1000000)%2==1 ){
                            continue;
                        }
                        dif+= abs(k-j);
                        used[k] = true;
                        exist = true;
                        break;
                    }
                }
            }
            if(!exist){
                ok = false;
                break;
            }
        }
        if(ok){
            ans = min(ans,dif/2);
        }
    }
    if(ans==1e9){
        std::cout << -1 << std::endl;
    }else{
        std::cout << ans << std::endl;
    }
}

#include<bits/stdc++.h>
#define long long long
using namespace std;
const int N=1e6,inf=1e9;
int aa[18+2],bb[18+2],dp[18+2][2][(1<<18)+2],n,pre[18+2][(1<<18)+2];
int dfs(int last,int f,int msk)
{
  if(msk==(1<<n)-1)return 0;
  if(dp[last][f][msk]!=-1)return dp[last][f][msk];
  int l=aa[last];if(f)l=bb[last];
  int ret=inf;int cnt=__builtin_popcount(msk);
  for(int i=0;i<n;i++)
  {
    if(msk&(1<<i))continue;
    int p=pre[i][msk]+i;//current position of i

    int fl=(pre[i][msk]+p-cnt)%2;
    int now=aa[i];if(fl)now=bb[i];
    if(now>=l)ret=min(ret,p-cnt+dfs(i,fl,msk|(1<<i)));
  }
  return ret;
}
int main()
{
  ios_base::sync_with_stdio(0);cin.tie(0);

  cin>>n;
  for(int i=0;i<n;i++)cin>>aa[i];
  for(int i=0;i<n;i++)cin>>bb[i];

  //for(int i=0;i<n;i++)aa[i]=1+rand()%50;
  //for(int i=0;i<n;i++)bb[i]=1+rand()%50;

  for(int i=0;i<n;i++)
  {
    for(int msk=0;msk<(1<<n);msk++)
    {
      int cnt=0;
      if(msk&(1<<i))continue;
      for(int j=i+1;j<n;j++)
        cnt+=(bool)(msk&(1<<j));

      pre[i][msk]=cnt;
    }
  }
  //cout<<pre[0][14]<<endl;
  memset(dp,-1,sizeof(dp));
  int mn=dfs(0,0,(1<<0));
  for(int i=1;i<n;i++)
    mn=min(mn,i+dfs(i,i%2,(1<<i)));
  if(mn==inf)mn=-1;
  cout<<mn<<endl;

  return 0;
}

