#include <bits/stdc++.h>

using namespace std;

int main(int argc, char *argv[])
{
	ios::sync_with_stdio(false); cin.tie(0);

	int n;
	cin >> n;
	vector<int> a(n), b(n);
	for (int i = 0; i < n; i++) cin >> a[i];
	for (int i = 0; i < n; i++) cin >> b[i];

	int ans = -1;
	for (int k = 0; k < (1 << n); k++) {
		if (__builtin_popcount(k) % 2 != 0) continue;
		vector<pair<int, pair<int, int> > > t(n);
		for (int i = 0, z = k; i < n; i++, z >>= 1)
			t[i] = make_pair(z % 2 == 0 ? a[i] : b[i], make_pair(i, z % 2));
		int count = 0;
		for (int i = 0; i < n; i++)
			for (int j = i + 1; j < n; j++)
				if (t[i] > t[j]) count++;
		sort(t.begin(), t.end());
		int ok = 1;
		for (int i = 0; i < n; i++) {
			int d = i - t[i].second.first;
			if (abs(d) % 2 != t[i].second.second) {
				ok = 0;
				break;
			}
		}
		if (!ok) continue;
		if (ans < 0 || ans > count) ans = count;
	}

	cout << ans << endl;

	return 0;
}

