#define FOR(i, begin, end) for(int i=(begin),i##_end_=(end);i<i##_end_;i++)
#define IFOR(i, begin, end) for(int i=(end)-1,i##_begin_=(begin);i>=i##_begin_;i--)
#define REP(i, n) FOR(i,0,n)
#define IREP(i, n) IFOR(i,0,n)
constexpr int MOD = 1000000007;
constexpr int INF = 2147483647;
int main()
{
   int N;
   cin >> N;
   vector<int> A(N);
   REP(i, N) cin >> A[i];
   vector<int> B(N);
   REP(i, N) cin >> B[i];
   int ans = 1e9;
   REP(k, pow(2,N)) {
       vector<int> p(N);
       vector<int> bitid(51, 0);
       vector<int> id(N);
       REP(i, N) {
           p[i] = ((k>>i)&1)==1 ? A[i] : B[i];
           if(((k>>i)&1)==0) bitid[B[i]]++;
           id[i] = i;
       }
       vector<int> swid(51, 0);
       vector<int> swid2(N, 0);
       int swnum = 0;
       REP(i, N) {
           FOR(j, 1, N-i) {
               if(p[j] < p[j-1]) {
                    swap(p[j], p[j-1]);
                    swid[p[j]]++;
                    swid[p[j-1]]++;
                    swid2[id[j]]++;
                    swid2[id[j-1]]++;
                    swap(id[j], id[j-1]);
                    swnum++;
               }
           }
       }
       bool flg = true;
       bool flg2 = false;
       REP(i, 51) {
           if(bitid[i]%2 != swid[i]%2) {
               flg = false;
               break;
           } 
       }
       REP(i, N) {
           if(((k>>i)&1) == 0 && swid2[i]%2 == 0) {
               if(flg2) {
                flg2 = false;
               } else {
                    swnum++;
                    flg2 = true;
               }

           } 
       }
       if(flg) {
           if(swnum < ans) ans = swnum;
       }
   } 
   if(ans == 1e9) ans = -1;
   cout << ans << endl;
}

