template<typename T>
class BinaryIndexedTree {
    int N;
    vector<T> data;
public:
    BinaryIndexedTree(int N) : N(N) {
        data.resize(N + 1, 0);
    }

    T sum(int k) {
        T res = 0;
        for (; k > 0; k -= k & -k) {
            res += data[k];
        }
        return res;
    }

    void add(int k, T x) {
        for (; k <= N; k += k & -k) {
            data[k] += x;
        }
    }

    /**
     * v1 + v2 + ⋯ + vx ≧ W となる最小の 𝑥 を求める
     */
    int lowerBound(int w) {
        if (w <= 0) return 0;
        int x = 0;
        int k = 1;
        while (k * 2 <= N) k *= 2;
        for (; k > 0; k /= 2) {
            if (x + k <= N && data[x + k] < w) {
                w -= data[x + k];
                x += k;
            }
        }
        return x + 1;
    }
};

int main(){
    int N;
    cin>>N;
    vector<int> A(N),B(N);
    REP(i,N) cin>>A[i];
    REP(i,N) cin>>B[i];
    int ans=INF;
    REP(bit,1<<N){
        vector<int> C(N);
        vector<pair<int,int>> odd,even,whole;
        bool ok=true;

        REP(j,N){
            int mask=1<<j;
            if(bit&mask){
                C[j]=A[j];
                if(j%2==0){
                    even.push_back(make_pair(C[j],j));
                }else{
                    odd.push_back(make_pair(C[j],j));
                }
            }else{
                C[j]=B[j];
                if(j%2==1){
                    even.push_back(make_pair(C[j],j));
                }else{
                    odd.push_back(make_pair(C[j],j));
                }
            }
        }

        if(!((even.size()==(N+1)/2)&&(odd.size()==N/2))) continue;
        sort(ALL(even));
        sort(ALL(odd));
        REP(j,N){
            if(j%2==0){
                whole.push_back(even[j/2]);
            }else{
                whole.push_back(odd[j/2]);
            }
        }
        bool ng=false;
        REP(j,N-1){
            if(whole[j].first>whole[j+1].first) ng=true;
        }
        if(ng) continue;

        int sum=0;
        REP(j,N-1){
            REP(k,N-j-1){
                if (whole[k].second > whole[k + 1].second) {
                    swap(whole[k], whole[k + 1]);
                    sum++;
                }
            }
        }
        ans=min(ans,sum);
    }

    if(ans==INF) ans=-1;
    cout<<ans<<endl;
}

#include <bits/stdc++.h>
using namespace std;

vector<int> swapA(vector<int> A, vector<int> B,int x, int y) {
  int ax = A.at(x);
  int ay = A.at(y);
  int bx = B.at(x);
  int by = B.at(y);
  vector<int> nA = A;
  vector<int> nB = B;
  nA.at(x) = by;
  nA.at(y) = bx;
  nB.at(x) = ay;
  nB.at(y) = bx;
  return nA;
}
vector<int> swapB(vector<int> A, vector<int> B,int x, int y) {
  int ax = A.at(x);
  int ay = A.at(y);
  int bx = B.at(x);
  int by = B.at(y);
  vector<int> nA = A;
  vector<int> nB = B;
  nA.at(x) = by;
  nA.at(y) = bx;
  nB.at(x) = ay;
  nB.at(y) = bx;
  return nB;
}



bool check(vector<int> vec) {
  bool ok = true;
  for (int i = 0;i < vec.size()-1;i++) {
    if (vec.at(i) > vec.at(i+1)) ok = false;
  }
  return ok;
}





int bfs(vector<int> A, vector<int> B) {
  pair<vector<int>, vector<int>> p;
  p = make_pair(A,B);
  map<pair<vector<int>, vector<int>>, int> dist;
  queue<vector<int>> aq;   
  queue<vector<int>> bq;
  int cnt = 0;

  //初期値
  dist[p] = 1;   //ごめん、こうするから後で１引いて
  aq.push(A);
  bq.push(B);

  if (check(A)) return 1;

  while(!aq.empty()) {
    vector<int> a = aq.front();
    vector<int> b = bq.front();
    aq.pop();
    bq.pop();

    for (int i = 0;i <A.size();i++) {
      for (int j = 0; j < A.size();j++) {
        vector<int> nA = swapA(a,b,i,j);
        vector<int> nB = swapB(a,b,i,j);
        if (dist[make_pair(nA,nB)] != 0) continue;
        if (check(nA)) {
          cnt = dist[make_pair(a,b)] + 1;
          queue<vector<int>> nq;
          aq = nq;
        dist[make_pair(nA,nB)] = dist[make_pair(a,b)] + 1;
        aq.push(nA);
        bq.push(nB);
        }
      }
    }
  }
  return cnt;
}

int main() {
  int N;
  cin >> N;
  vector<int> A(N);
  vector<int> B(N);
  for (int i = 0; i<N;i++) {
    cin >> A.at(i);
  }
  for (int i = 0;i <N;i++) {
    cin >> B.at(i);
  }
  int ans = bfs(A,B);
  if (ans == 0) cout << '-1' << endl;
  else cout << bfs(A,B)-1 << endl;
}

