class BIT{
public:
	using T=lint;
	vector< T > data;
	BIT(int sz){ data.assign(++sz,0); }
	T sum(int k){//O(log n)
		T ret = 0;
		for(++k; k > 0; k -= k & -k) ret += data[k];
		return (ret);
	}void add(int k,T x){//O(log n)
		for(++k; k < data.size(); k += k & -k) data[k] += x;
	}
};//BIT<int>t(n);



inline lint bitcnt(lint n){
	lint ret=0;
	rep(6)if((n>>i)&1ll)++ret;
	return ret;
}

void solve(lint n, std::vector<lint> a, std::vector<lint> b){
	lint ans=linf;
	rep(bb,(1ll<<n)){//uragaesu
		lint bc=bitcnt(bb);
		if(bc&1)continue;
		vector<lint>c(n),d(n);
		rep(n)c[i]=((bb>>i)&1ll)?b[i]:a[i];
		lint inv=0;
		per(n){
			rep(j,i,n){
				inv+=(c[i]>c[j]);
				if(c[i]>c[j])d[i]^=1,d[j]^=1;
			}
		}
		vector<lint>k(51);
		rep(n){
			if(((bb>>i)&1ll)^(d[i]))k[c[i]]^=1;
		}
		bool f=1;
		each(k)if(e)f=0;
		if(f)chmin(ans,max(bc/2,inv));
	}
	out(ans==linf?-1:ans);
}

