void solve() {
    i64 N = RD();
    auto A = RD_VEC(N);
    auto B = RD_VEC(N);

    i64 ans = INF;
    vector<pair<i64,i64>> cards(N);  // (c,v)
    vector<i64> ms(N);  // カードcの移動回数
    REP(mask, 1LL<<N) {
        REP(c, N) {
            i64 v = (mask&(1LL<<c)) ? B[c] : A[c];
            cards[c] = {c,v};
        }
        ALL(fill, ms, 0);
        DBG(cards, ms);

        i64 cur = 0;
        bool ok = true;
        REP(i, N) {
            i64 vmin   = INF;
            i64 vmin_j = -1;
            FOR(j, i, N) {
                i64 c,v; tie(c,v) = cards[j];
                i64 m = ms[c];
                bool front = (mask&(1LL<<c)) == 0;
                i64 d = j-i;
                DBG(i,j,c,front,m,d);

                bool vmin_updated = chmin(vmin, v);
                if(vmin_updated)
                    vmin_j = -1;
                if( front && (m+d)%2!=0) continue;
                if(!front && (m+d)%2==0) continue;

                if(v <= vmin && vmin_j == -1)
                    vmin_j = j;
            }
            DBG(i,vmin,vmin_j);
