                if(value < j)continue;

                ll inversion = memo[i][k];
                dp[afterbit][value] = min(dp[afterbit][value], dp[i][j] + inversion);
            }
        }
    }
    ans = INF;
    for(ll i=0;i<=50;i++){
        ans = min(ans, dp[(1ll << n) - 1][i]);
    }
    if(ans == INF){
