template <typename T>
struct BIT
{
    int n;
    vector<T> bit;

    BIT(){}

    BIT(int n) : n(n){
        bit.resize(n + 1);
    }

    T sum(int i){
        i++;
        T res = 0;
        while(i){
            res += bit[i];
            i -= (i & -i);
        }
        return res;
    }

    void add(int i, T x){
        i++;
        while(i <= n){
            bit[i] += x;
            i += (i & -i);
        }
    }
};

int main()
{
    int n;
    cin >> n;
    int a[20][2];
    for(int i = 0; i < n; i++) cin >> a[i][0];
    for(int i = 0; i < n; i++) cin >> a[i][1];
    int ans = 10000000;
    for(int b = 0; b < (1 << n); b++){
        P p[20];
        for(int i = 0; i < n; i++){
            p[i] = P(a[i][(b >> i) & 1], i);
        }
        sort(p, p + n);
        BIT<int> bit(60);
        int s = 0;
        bool f = true;
        for(int i = 0; i < n; i++){
            s += i - bit.sum(p[i].second);
            bit.add(p[i].second, 1);
        }
        for(int i = 0; i < n; i++){
            if(abs(i - p[i].second) % 2 != ((b >> p[i].second) & 1)){
                bool g = false;
                for(int j = i + 1; j < n; j++){
                    if(p[i].first != p[j].first) break;
                    if(abs(i - p[j].second) % 2 == ((b >> p[j].second) & 1)){
                        g = true;
                        s += j - i;
                        int t = p[j].second;
                        for(int k = j; k > i; k--){
                            p[k].second = p[k - 1].second;
                            p[i].second = t;
                        }
                        break;
                    }
                }
                if(!g){
                    f = false;
                    break;
                }
            }
        }
        if(f) ans = min(ans, s);
    }
    if(ans == 10000000) cout << -1 << endl;
    else cout << ans << endl;
}

