int fg=0;
int sum=0x3f3f3f3f;
int n;
int a[19];
int b[19];
void dfs(int now,int bu){
	if(now==n){
		for(int i=1;i<n;i++){
			if(a[i]>a[i+1])
			return;
		}
		sum=min(sum,bu);
		fg=1;
		return;
	}
	dfs(now+1,bu);
	swap(a[now],b[now+1]);
	swap(a[now+1],b[now]);
	dfs(now+1,bu+1);
	swap(a[now],b[now+1]);
	swap(a[now+1],b[now]);
}
int main(){
	cin >> n;
	for(int i=1;i<=n;i++){
		cin >> a[i];
	}
	for(int i=1;i<=n;i++){
		cin >> b[i];
	}
	dfs(1,0);
	if(fg==1)
	cout << sum << endl;
	else
	cout << -1 << endl;
	return 0;
}

