int solve(int mask)
{
    vector<int> v[51] , v1[51];

   for (int i = 1;i<=n;i++){
   if (mask&(1<<(i-1))) c[i] = b[i]; else c[i] = a[i];
     v[c[i]].pb(i);
   }

   int ans = 0;
   int ans1 = 0;

   for (int i=1;i<=50;i++)
   {
       for (int j:v[i])
       {
           int cur = 0;
           for (int k=1;k<=n;k++)
            if (k!=j)
            {
                if ((j>k && c[j]<c[k]) || (j<k && c[j]>c[k]))
                {
                    cur++;
                    ans1++;
                }
            }

           int p = 0;

           if ((mask&(1<<(j-1)))) p = 1;

           if ((cur&1) == p)
           v1[i].pb(0); else v1[i].pb(1);

       }
       int last = 0;

       for (int j:v1[i])
        if (j==0)
       {
           if (last&1)  return -1;
           ans+=(last)/2;
       } else
       last++;

       if (last&1) return -1;
       ans+=(last)/2;
   }



   return (ans + ans1/2);

}

