template <class Monoid> struct SegTree {
	int N;
	vector<Monoid> node;
	std::function<Monoid(Monoid, Monoid)> operation;
	Monoid unit;//単位元

	std::function<bool(Monoid, Monoid)> comp;
	Monoid not_find_sgn;

	SegTree(vector<Monoid>& data, std::function<Monoid(Monoid, Monoid)> op, Monoid U) {
		//データ　演算　単位元
		operation = op;
		unit = U;
		int size = data.size();
		N = 1;
		while (N < size)N <<= 1;
		node.resize(2 * N - 1, unit);

		for (int i = 0; i < size; i++) {
			node[i + N - 1] = data[i];
		}

		for (int i = N - 2; i >= 0; i--) {
			node[i] = operation(node[i * 2 + 1], node[i * 2 + 2]);
		}
	}

	void update(int pos, Monoid val) {
		pos += N - 1;
		node[pos] = val;
		while (pos > 0) {
			pos = (pos - 1) / 2;
			node[pos] = operation(node[pos * 2 + 1], node[pos * 2 + 2]);
		}
	}

	Monoid getval(int a, int b, int idx, int l, int r = -1) {
		//[a, b)を求める。　使い方はgetval(a, b, );
		if (r == -1)r = N;
		if (b <= l || r <= a)return unit;
		if (a <= l && r <= b)return node[idx];
		Monoid left = getval(a, b, idx * 2 + 1, l, (l + r) / 2);
		Monoid right = getval(a, b, idx * 2 + 2, (l + r) / 2, r);
		return operation(left, right);
	}

	Monoid getval(int a, int b) {
		//ラッパー。
		return getval(a, b, 0, 0, -1);
	}

	//必ずセットしてから二分探索すること
	void setcomp(std::function<bool(Monoid, Monoid)> _comp, Monoid _nfs) {
		comp = _comp;
		not_find_sgn = _nfs;
	}

	//大丈夫か？
	Monoid lower_bound(Monoid x, int a, int b, int l, int r, int k) {
		if (b <= l || r <= a)return not_find_sgn;
		if (!comp(x, node[k]))return not_find_sgn;
		if (k >= N - 1)return k - (N - 1);
		Monoid tmp = lower_bound(x, a, b, (l + r) / 2, r, k * 2 + 2);
		if (!comp(x, tmp))return tmp;
		return lower_bound(x, a, b, l, (l + r) / 2, k * 2 + 1);
	}
	Monoid lower_bound(Monoid x, int a, int b) {
		return lower_bound(x, a, b, 0, N, 0);
	}
	Monoid lower_bound(Monoid x) {
		return lower_bound(a, 0, N);
	}

	//たぶん大丈夫やろ
	Monoid upper_bound(Monoid x, int a, int b, int l, int r, int k) {
		if (b <= l || r <= a)return not_find_sgn;
		if (!comp(x, node[k]))return not_find_sgn;
		if (k > N - 1)return k - (N - 1);
		Monoid tmp = lower_bound(x, a, b, (l + r) / 2, r, k * 2 + 2);
		if (!comp(x, tmp))return tmp;
		return lower_bound(x, a, b, l, (l + r) / 2, k * 2 + 1);
	}
	Monoid upper_bound(Monoid x, int a, int b) {
		return upper_bound(x, a, b, 0, N, 0);
	}
	Monoid upper_bound(Monoid x) {
		return upper_bound(a, 0, N);
	}
};

