        cin >> a[i].first;
    }
    for(int i=0;i<n;++i) {
        cin >> a[i].second;
    }

    int ans = INF;
    for(int bi=0;bi<(1<<n);++bi) {
        if(count_bit(bi) % 2) continue; // 裏返っているカードの数が奇数にはならない
        // cerr << bitset<10>(bi) << endl;
        vector<Pii> v(n);
        for(int i=0;i<n;++i) {
            if(bi & (1 << i)) {
                v[i] = Pii(a[i].second, i);
            } else {
                v[i] = Pii(a[i].first, i);
            }
        }
        sort(v.begin(), v.end());

        bool is_ok = true;
        for(int i=0;i<n&&is_ok;++i) {
            // cerr << i << ": " << v[i].first << " " << v[i].second << endl;
            if((abs(v[i].second - i) % 2) ^ ((bi >> i) & 1)) {
                is_ok = false;
