        BIT<int> tree(100);
        vector<int> u(n);
        for(int i=0;i<n;++i) u[i] = v[i].second + 1;
        ans = min(ans, tree.count_swap(u));
    }

    cout << ((ans == INF)?-1:ans) << endl;
}

