    cur = xs[(n-1)&1][n-1];
    for(int i=n-1;i>=0;--i){
        for(int pos=p[i&1];pos>=0;--pos){
            if(xs[i&1][pos] <= cur){
                cur = xs[i&1][pos];
                p[i&1] = pos - 1;
                bound[i] = cur;
                break;
            }
        }
    }

    queue<tuple<int, int, string>> q;
    uint64_t ans = ~0ULL;
    q.emplace(0, 0, s);
    while(!q.empty()){
        int nx, cnt;
        string st;
        tie(cnt, nx, st) = q.front();
        q.pop();
        if(-cnt > ans) continue;
        if(nx == n){ ans = min(ans, (uint64_t)(-cnt)); continue; }
        for(int i=nx;i<n;++i){
            if((nx==0 || st[nx-1] <= st[i+18*((i-nx)&1)]) && st[i+18*((i-nx)&1)] <= bound[i]){
                string t{st};
                t[nx] = st[i+18*((i-nx)&1)];
                t[nx+18] = st[i+18*((i-nx+1)&1)];
                for(int p=nx+1;p<=i;++p){
                    t[p] = st[p-1+18];
                    t[p+18] = st[p-1];
                }
                if(-cnt + (i-nx) < ans) q.emplace(cnt - (i-nx), nx+1, t);
            }
        }
    }
    cout << (int64_t)ans << endl;
    return 0;
}

