int bitcnt[1 << 18];
int dp[1 << 18][18];
int a[18], b[18];

int value(int pos, int ind) {
	if ((pos - ind) % 2)return b[ind];
	else return a[ind];
}

int flip(int pos, int bit) {
	return bitcnt[bit & ((1 << 18) - (1 << pos))];
}

void solve()
{
	int n; cin >> n;
	REP(i, n) cin >> a[i];
	REP(i, n) cin >> b[i];
	REP(i, (1 << 18)) REP(j, 18) dp[i][j] = INF;
	dp[0][0] = 0;
	int ans = INF;

	REP(bit, (1 << n)) {
		if (bit) bitcnt[bit] = bitcnt[bit / 2] + bit % 2;
		REP(last, n) {
			if (bit == (1 << n) - 1) ans = min(ans, dp[bit][last]);
			if (bit > 0 && (bit & (1 << last)) == 0) continue;
			REP(nxt, n) {
				if (bit & (1 << nxt)) continue;
				int nxtbit = bit + (1 << nxt);
				if (bit > 0 && value(bitcnt[bit] - 1, last) > value(bitcnt[bit], nxt)) continue;
				dp[nxtbit][nxt] = min(dp[nxtbit][nxt], dp[bit][last] + flip(nxt, bit));
			}
		}
	}
	cout << (ans == INF ? -1 : ans) << endl;
}

int main() {
	ios_base::sync_with_stdio(0); cin.tie(0); cout << fixed << setprecision(13);
	solve();
	return 0;
}

