                    x = a[j];
                else
                    x = b[j];
                if(x < val)
                    continue;
                int inv = __builtin_popcount(mask >> j);
                dp[j][mask | (1 << j)] = min(dp[j][mask | (1 << j)], dp[i][mask] + inv);
            }
        }

    }
