const int INF = 1<<29;

int N;
vector<int> A, B;



int solve() {
    vector<vector<int>> dp((1<<N)+1, vector<int>(55, INF));
    dp[0][0] = 0;
    for (int bit = 0; bit < (1<<N); ++bit) {
        int con = 0;
        for (int i = 0; i < N; ++i) if (bit & (1<<i)) ++con;

        for (int s = 0; s <= 50; ++s) {
            if (dp[bit][s] >= INF) continue;
            for (int i = 0; i < N; ++i) {
                if (bit & (1<<i)) continue;
                int dis = abs(i - con);
                int ns = -1;
                if (dis % 2 == 0) ns = A[i];
                else ns = B[i];
                if (ns < s) continue;

                int nbit = bit | (1<<i);
                chmin(dp[nbit][ns], dp[bit][s] + dis);
            }
        }
    }

    int res = INF;
    for (int s = 0; s <= 50; ++s) {
        chmin(res, dp[(1<<N)-1][s]);
    }
    if (res < INF) return res/2;
    else return -1;
}

