int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);

  int n;
  cin >> n;

  vector<pair<int, int>> x(n);
  for(int i = 0; i < n; i++) cin >> x.at(i).first;
  for(int i = 0; i < n; i++) cin >> x.at(i).second;

  // bit全探索
  int ans = 1e9;
  for(int bit = 0; bit < (1 << n); bit++){
    vector<int> a, b, c;
    for(int j = 0; j < n; j++){
      if(bit & (1 << j)){
        c.push_back(x.at(j).first);
        if(j % 2 == 0){
          a.push_back(x.at(j).first);
        }
        else{
          b.push_back(x.at(j).first);
        }
      }
      else{
        c.push_back(x.at(j).second);
        if(j % 2 == 0){
          b.push_back(x.at(j).second);
        }
        else{
          a.push_back(x.at(j).second);
        }
      }
    }

    // 数の判定
    if(!(a.size() - b.size() == 0 || a.size() - b.size() == 1)){
      continue;
    }

    // 広義単調増加の判定
    sort(a.begin(), a.end());
    sort(b.begin(), b.end());
    bool judge = true;
    for(int j = 1; j < a.size(); j++){
      if(b.at(j - 1) > a.at(j)){
        judge = false;
        break;
      }
    }
    for(int j = 0; j < b.size(); j++){
      if(a.at(j) > b.at(j)){
        judge = false;
        break;
      }
    }
    if(!(judge)) continue;

    // swap数のカウント
    int keep = 0;
    for(int j = 0; j < n - 1; j++){
      for(int k = j + 1; k < n; k++){
        if(c.at(j) > c.at(k)) keep++;
      }
    }
    ans = min(ans, keep);
  }

  if(ans == 1e9) cout << -1 << '\n';
  else cout << ans << '\n';
}

