vec a(18), b(18);
ll solve(ll s){
    vec na(0), nb(0);
    rep(i,N){
        if((((s>>i)&1) ^ i) & 1)nb.push_back(i);
        else na.push_back(i);
    }
    /*if(s == INF){
        cout<<na[0]<<' '<<na[1]<<' '<<na[2]<<endl;
        cout<<nb[0]<<' '<<nb[1]<<endl;
    }*/
    if(nb.size() != N/2) return INF;
    sort(ALL(na), [&](int x, int y){
        if(a[x] == a[y]) return x < y;
        return a[x] < a[y];
    });
    sort(ALL(nb), [&](int x, int y){
        if(b[x] == b[y]) return x < y;
        return b[x] < b[y];
    });
    /*cout<<s<<endl;
    cout<<na[0]<<' '<<na[1]<<endl;
    cout<<nb[0]<<endl;*/
    ll last = a[na[0]], res = 0;
    rep(i,N){
        int id = (i&1 ? nb[i/2] : na[i/2]);
        int ele = (i&1 ? b[id] : a[id]);
        //if(s == 3) cout<<id<<' '<<ele<<endl;
        if(last > ele) return INF;
        res += abs(id - i);
        last = ele;
    }
    return res;
}

