int main(){
    int N;cin>>N;
    vector<int> A(N),B=A;
    REP(i,N) cin>>A[i];
    REP(i,N) cin>>B[i];
    int ans=(N+1)*(N+1);
    REP(bit,1<<N) if(__builtin_popcount(bit)%2==0){
        vector<int> state(N);
        REP(i,N){
            if(bit>>i&1) state[i]=B[i];
            else state[i]=A[i];
        }
        vector<int> co=state;
        sort(All(co));
        bool judge=true;
        vector<bool> used(N,false);
        REP(i,N){
            bool ok=false;
            REP(j,N) if(!used[j]){
                if(co[i]==state[j]&&std::abs(j-i)%2==(bit>>j&1)){
                    ok=true;
                    used[j]=true;
                }
            }
            if(!ok) judge=false;
        }
        int tmp=0;
        if(judge){
            REP(i,N) rep(j,i+1,N) if(state[i]>state[j]){
                tmp++;
            }
            if(ans>tmp){
                ans=tmp;
                // cout<<ans<<endl;
