  }

  int ans = 1000;
  for(int flip = 0; flip < (1 << N); flip++){
    multiset<int> values;
    map<pair<int, bool>, int> val_even_cnt;
    for(int i = 0; i < N; i++){
      if((flip >> i) & 1){
        values.insert(B[i]);
        val_even_cnt[make_pair(B[i], i % 2 == 1)]++;
      }else{
        values.insert(A[i]);
        val_even_cnt[make_pair(A[i], i % 2 == 0)]++;
      }
    }
    /*for(auto x: values){
      cout << x;
    }cout << endl;
    */
    int i = 0;
    bool ok = true;
    for(auto val: values){
      if(val_even_cnt[make_pair(val, i % 2 == 0)] == 0){
        ok = false;
        break;
      }else{
        val_even_cnt[make_pair(val, i % 2 == 0)]--;
      }
      i++;
    }
    if(ok){
      vector<pair<int, int>> val_befidx(N);
      for(int i = 0; i < N; i++){
        if((flip >> i) & 1){
          val_befidx[i] = make_pair(B[i], i);
        }else{
          val_befidx[i] = make_pair(A[i], i);
        }
      }
      sort(val_befidx.begin(), val_befidx.end());
      int ans_tmp = 0;
      for(int i = 0; i < N; i++){
        for(int j = i + 1; j < N; j++){
          if(val_befidx[i].second > val_befidx[j].second){
            ans_tmp++;
          }
        }
      }
      ans = min(ans, ans_tmp);
    }
  }
  if(ans == 1000){
    cout << -1 << endl;
  }else{
    cout << ans << endl;
  }
}

