using namespace std;
using namespace ext;


void solve(long long N, std::vector<long long> A, std::vector<long long> B){
	rep(i, N) {
		if (i % 2 == 1) swap(A[i], B[i]);
	}
	vector<int> per(N);
	int res = 1e9;
	rep(i, N/2) per[i] = 1;
	reverse(all(per));
	do {
		vector<pair<int, int>> vp;
		rep(i, N) {
			if (per[i]) vp.emplace_back(B[i], i);
			else vp.emplace_back(A[i], i);
		}
		int r = 0;
		rep(i, N) {
			rreps(j, N-1, i) {
				if (vp[j].first > vp[j+1].first) {
					swap(vp[j], vp[j+1]);
					r++;
				}
			}
		}
		rep(i, N-1) assert(vp[i].first <= vp[i+1].first);
		vector<bool> vb(N);
		rep(i, N) {
			if ((vp[i].second & 1) == per[vp[i].second]) {
				vb[i] = abs(vp[i].second - i) % 2 == 0;
			} else {
				vb[i] = abs(vp[i].second - i) % 2 == 1;
			}
		}
		// rep(i, N) cout << vb[i] << ' '; cout << endl;
		rep(i, N-1) {
			if (!vb[i]) {
				if (vp[i].first != vp[i+1].first) r = 1e9;
				vb[i] = !vb[i];
				vb[i+1] = !vb[i+1];
				r++;
			}
		}
		if (vb[N-1]) chmin(res, r);
	} while (next_permutation(all(per)));
	if (res == 1e9) cout << -1 << endl;
	else cout << res << endl;
}

