using namespace std;

int a[19], b[19];
int f[300001][19];
int n;

int main() 
{
	ios::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	cin >> n;
	for (int i=1;i<=n;i++)
		cin >> a[i];
	for (int i=1;i<=n;i++)
		cin >> b[i];
	for (int i=0;i<=300000;i++)
		for (int j=0;j<=18;j++)
			f[i][j] = 1e9;
	for (int i=1;i<=n;i++)
		f[(1<<(i-1))][i] = 0;
	for (int mask = 1;mask < (1<<n);mask++)
	{
		int pos = __builtin_popcount(mask) + 1;
		for (int i=0;i<=n-1;i++)
			if ((1<<i) & mask)
			{
				int cnt = 0;
				for (int j=0;j<=n-1;j++)
				{
					if (!((1<<j) & mask))
					{
						int cost = pos - 1 - cnt;
						int pre_val = ((abs((i + 1) - (pos - 1)) % 2) == 0) ? a[i+1] : b[i+1];
						int cur_val = ((abs((j + 1) - pos) % 2) == 0) ? a[j+1] : b[j+1];
						if (cur_val >= pre_val)
							f[mask | (1<<j)][j+1] = min(f[mask | (1<<j)][j+1],f[mask][i+1] + cost);
					}
					else
						cnt++;
				}
			}
	}
	int res = 1e9;
	for (int i=1;i<=n;i++)
		res = min(res,f[(1<<n)-1][i]);
	if (res == 1e9) cout << -1;
	else cout << res;
	return 0;
}

