int a[2][20];
int dp[1 << 19][20];
const int INF = 1e9 + 7;
int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    int n;
    cin >> n;
    for (int i = 0; i < n; i++) cin >> a[0][i];
    for (int i = 0; i < n; i++) cin >> a[1][i];
    bool ok = true;
    for (int i = 0; i < n - 1; i++) ok &= (a[0][i] <= a[0][i + 1]);
    if (ok) {cout << 0 << '\n'; return 0;}
    memset(dp, 0x3f, sizeof(dp));
    for (int i = 0; i < n; i++) dp[1 << i][i] = 1;
    for (int mask = 1; mask < (1 << n) - 1; mask++) {
        for (int i = 0; i < n; i++) {
            if (!(mask & (1 << i))) continue;
            if (dp[mask][i] > INF) continue;
            int idx = __builtin_popcount(mask) - 1;
            int pre = a[(i ^ idx) & 1][i];
            for (int j = 0; j < n; j++) if (!(mask & (1 << j))) {
                int now = a[(j ^ (idx + 1)) & 1][j];
                if (now < pre) continue;
                int cost = j;
                for (int jj = 0; jj < j; jj++) if (mask & (1 << jj)) cost--;
                dp[mask | (1 << j)][j] = min(dp[mask | (1 << j)][j], dp[mask][i] + cost);
            }
        }
    }
    int ans = INF;
    for (int i = 0; i < n; i++) ans = min(ans, dp[(1 << n) - 1][i]);
    cout << ((ans < 1234567) ? ans : -1) << '\n';


    return 0;
}

