//vectorに対しての処理は.vを呼ぶ
template<class T> class ovv{
    optional<T> emp;
public:
    vector<vector<optional<T>> > v ;
    ovv(int i=0, int j=0, T val = 0) : v(i, vector<optional<T>>(j, val) ){}
    ovv(const vector<vector<T> >& S){
        v.resize(S.size());
        for (int h = 0; h < sz(S); h++){
            v[h].resize(sz(S[h]));
            for (int w = 0; w < sz(S[h]); w++){
                v[h][w].set(S[h][w]);
            }
        }
