template<class T, class U> void unique_min(vector<pair<T, U>> &a) {    vector<pair<T, U>> res;    if (sz(a))res.push_back(a[0]);    rep(i, 1, sz(a)) {        if (res.back().fi == a[i].fi) {            chmi(res.back().se, a[i].se);        }else {            res.push_back(a[i]);        }    }   swap(a, res);}
//firstの値が同じ場合secondが最大の物を残す
template<class T, class U> void unique_max(vector<pair<T, U>> &a) {    vector<pair<T, U>> res;    if (sz(a))res.push_back(a[0]);    rep(i, 1, sz(a)) {        if (res.back().fi == a[i].fi) {            chma(res.back().se, a[i].se);        }else {            res.push_back(a[i]);        }    }    swap(a, res);}

template<class T> bool includes(vector<T> &a, vector<T> &b) {    vi c = a;    vi d = b;    sort(c);    sort(d);    return includes(ALL(c), ALL(d));}
template<class T> bool distinct(const vector<T> &A) {    if ((int) (A).size() == 1)return true;    if ((int) (A).size() == 2)return A[0] != A[1];    if ((int) (A).size() == 3)return (A[0] != A[1] && A[1] != A[2] && A[0] != A[2]);    auto B = A;    sort(B);    int N = (B.size());    unique(B);    return N == (int) (B.size());}
template<class H, class... T> bool distinct(const H &a, const T &...b) { return distinct(vector<H>{a, b...}); }

