        cin >> B[i];
    }

    for (int i = 0; i < (1 << N); i++) {
        for (int j = 0; j < N; j++) {
            dp[i][j] = I_INF;
        }
    }
    for (int i = 0; i < N; i++) {
        dp[(1 << i)][i] = 0;
    }

    for (int bit = 0; bit < (1 << N); bit++) {
        for (int i = 0; i < N; i++) {
            if (!(bit & (1 << i))) continue;
            int prev_bit = bit & ~(1 << i);

            int i_pos = __builtin_popcount(bit) - 1;
            int i_val;
            if (abs(i_pos - i) & 1) {
                i_val = B[i];
            }
            else {
                i_val = A[i];
            }

            int cnt = 0;
            for (int j = 0; j < N; j++) {
                if (prev_bit & (1 << j)) {
                    if (i < j) ++cnt;
                }
            }

            for (int j = 0; j < N; j++) {
                if (!(prev_bit & (1 << j))) continue;

                int j_pos = i_pos - 1;
                int j_val;
                if (abs(j_pos - j) & 1) {
                    j_val = B[j];
                }
                else {
                    j_val = A[j];
                }

                if (j_val > i_val) continue;

                if (dp[prev_bit][j] != I_INF)
                    dp[bit][i] = min(dp[bit][i], dp[prev_bit][j] + cnt);
            }
        }
    }

    int ans = I_INF;
    for (int i = 0; i < N; i++) {
        ans = min(ans, dp[(1 << N) - 1][i]);
    }

    if (ans == I_INF) ans = -1;

    cout << ans << endl;

    return 0;
}

