struct FenwickTree {
    typedef ll T;
    vector<T> v;
    void init(ll n) { v.assign(n, T()); }
    void add(ll i, T x) {
        for (; i < (ll)v.size(); i |= i + 1) v[i] += x;
    }
    T sum(ll i) const {  //[0, i)
        T r = T();
        for (--i; i >= 0; i = (i & (i + 1)) - 1) r += v[i];
        return r;
    }
    T sum(ll left, ll right) const {  //[left, right)
        return sum(right) - sum(left);
    }
};

int main() {
    init();
    ll N;
    cin >> N;
    vl AA(N), BB(N);
    rep(i, N) cin >> AA[i];
    rep(i, N) cin >> BB[i];
    rep(i, N) if (i % 2 == 1) swap(AA[i], BB[i]);
    ll ans = 1e9;
    rep(i, 1 << N) {
        vc<pair<ll, ll>> R, B;
        rep(j, N) {
            ll p = (i >> j) & 1;
            if (p == 0)
                R.eb(AA[j], j);
            else
                B.eb(BB[j], j);
        }
        if (R.size() != (N + 1) / 2) continue;
        sort(all(R)), sort(all(B));

        vc<pair<ll, ll>> X;
        rep(j, N / 2) X.eb(R[j]), X.eb(B[j]);
        if (N % 2) X.eb(R[N / 2]);
        bool isok = true;
        // cout << "dddd" << endl;
        repe(i, 1, N) {
            // cout << X[i].first - X[i - 1].first << endl;
            if (X[i].first - X[i - 1].first < 0) {
                isok = false;
                break;
            }
        }
        if (!isok) continue;

        ll tmp = 0;
        vc<ll> K(N);
        rep(i, N) K[i] = X[i].second;

        FenwickTree ft;
        ft.init(N + 1);
        rep(i, N) {
            tmp += i - ft.sum(K[i]);
            ft.add(K[i], 1);
        }
        // cout << "YES  " << tmp << endl;
        ans = min(ans, tmp);
    }
    if (ans == 1e9) ans = -1;
    cout << ans << endl;
    return 0;
}

