ll merge(vector<ll> &a, ll left, ll mid, ll right){
	ll i,j,k;
	ll count = 0;
	ll n1 = mid-left;
	ll n2 = right-mid;
	vector<ll> L(n1+1, 0), R(n2+1, 0);
	for(i=0; i<n1; i++) L[i] = a[left+i];
	for(i=0; i<n2; i++) R[i] = a[mid+i];
	L[n1] = R[n2] = INF;
	i=j=0;
	for(k=left; k<right; k++){
		if(L[i] <= R[j]) {
			a[k] = L[i];
			i++;
		} else {
			a[k] = R[j];
			j++;
			count += n1-i; // = mid+j-k-1
		}
	} 
	return count;
}

ll mergesort(vector<ll> &a, ll left, ll right){
	if(left+1 < right) {
		ll mid = (left+right)/2;
		ll v1 = mergesort(a, left, mid);
		ll v2 = mergesort(a, mid, right);
		ll v3 = merge(a, left, mid, right);
		return v1+v2+v3;
	} else {
		return 0;
	}
}


// (0..n-1)のn個の要素について、nCkの組み合わせに対して関数fを適用する
template<typename Function> void foreach_comb(ll n, ll k, Function f) {
	vector<ll> indexes(k);
	auto recursive_comb = [&](auto&& recursive_comb, vector<ll> &indexes, ll s, ll rest, Function& f){
		if (rest == 0) {
			f(indexes);
		} else {
			if (s < 0) return;
			recursive_comb(recursive_comb, indexes, s - 1, rest, f);
			indexes[rest - 1] = s;
			recursive_comb(recursive_comb, indexes, s - 1, rest - 1, f);
		}
	};
	recursive_comb(recursive_comb, indexes, n - 1, k, f);
}



