const int M = 1 << 18;
int n, m, k, tot;
vpi v;
int cache[M][55];

pii dp(int mask, int pos)
{
	if (mask == tot - 1)
		return {0, 55};

	int ans;

	vi t;
	int ele = 50; ans = 1e9;
	for (int i = 0; i < n; i++)
	{
		if (mask & (1 << i))
			continue;

		t.pb(i);
	}
	for (int i = 0; i < sz(t); i++)
	{
		int used = ((n - t[i] - 1) - (sz(t) - i - 1) + i) % 2;
		pii x;
		if (!used)
		{
			x = dp(mask | (1 << t[i]), pos + 1);
			if (x.S >= v[t[i]].S)
			{
				ans = min(ans, i + x.F);
				ele = v[t[i]].S;
			}
		}
		else
		{
			x = dp(mask | (1 << t[i]), pos + 1);
			if (x.S >= v[t[i]].F)
			{
				ans = min(ans, i + x.F);
				ele = v[t[i]].F;
			}
		}

	}
	return {ans, ele};


}

