    cin >> A >> B;
    auto dp = vector<vector<int>>(1 << N, vector<int>(N, inf));
    for (int i = 0; i < N; i++) {
        dp[1 << i][i] = i;
    }
    for (int i = 1; i < (1 << N); i++) {
        int now = __builtin_popcount(i);
        for (int j = 0; j < N; j++) {
            if (~i & (1 << j)) continue; // 0 continue
