                int before = abs(j - (now - 1)) % 2 == 0 ? A[j] : B[j];
                int select = abs(k - now) % 2 == 0 ? A[k] : B[k];
                if (before <= select) dp[i | (1 << k)][k] = min(dp[i | (1 << k)][k], dp[i][j] + add);
                ++add;
            }
        }
    }
    int ans = inf;
    for (int i = 0; i < N; i++) ans = min(ans, dp[(1 << N) - 1][i]);
