/* v-v-v-v-v-v-v-v-v Main Part v-v-v-v-v-v-v-v-v */
const int MAX_N = 100;
int A[19];
int B[19];

int bit[MAX_N + 1], n;

int sum(int i) {
    int s = 0;
    while (i > 0) {
        s += bit[i];
        i -= i & -i;
    }
    return s;
}

void add_to(int i, int x) {
    while (i <= n) {
        bit[i] += x;
        i += i & -i;
    }
}

int inversion(vector<int> &in) {
    fill(bit, bit + MAX_N, 0);
    int ret = 0;
    for (int j = 0; j < n ;j++) {
        ret += j - sum(in[j]);
        add_to(in[j], 1);
    }
    return ret;
}

signed main() {
    cin >> n;
    for (int i = 0; i< n; i++) cin >> A[i];
    for (int i = 0; i< n; i++) cin >> B[i];
    int ret = INF;

    // 奇数番目に置く場所のビットを立てる
    for (int mask = 0; mask < (1u << n); mask++) {
        if (__builtin_popcount(mask) != n/2) continue;

        vector<P> odds;
        vector<P> evens;
        for (int i = 0; i < n; i++) {
            if (mask & (1 << i)) odds.emplace_back(i % 2 == 0 ? B[i] : A[i], i);
            else evens.emplace_back(i % 2 == 0 ? A[i] : B[i], i);
        }

        sort(odds.begin(), odds.end());
        sort(evens.begin(), evens.end());

        vector<int> values(n);
        vector<int> idxs(n);
        int ii = 0;
        int jj = 0;
        for (int i = 0; i < n; i++) {
            if (i % 2 == 1) {
                values[i] = odds[ii].first;
                idxs[i] = odds[ii].second + 1;
                ii++;
            } else {
                values[i] = evens[jj].first;
                idxs[i] = evens[jj].second + 1;
                jj++;
            }
        }

        bool valid = true;
        for (int i = 0; i < n-1; i++) {
            if (values[i] > values[i+1]) {
                valid = false;
                break;
            }
        }
        if (!valid) continue;

        int tmp = inversion(idxs);
        ret = min(tmp, ret);
    }

    if (ret == INF) ret = -1;
    cout << ret << endl;
    return 0;
}

