const ll MOD = 1000000007;
const ll INF = (ll) 1e15;

ll N;
pll A[30];

ll solve(vector<pll> v) {
    vector<ll> t;
    REP(i, N) {
        t.push_back(v[i].first);
    }
    sort(t.begin(), t.end());
    ll num = 0;
    REP(i, N) {
        ll p = -1;
        FOR(j, N, i) {
            if (t[i] == v[j].first && (j - i) % 2 == v[j].second) {
                p = j;
                break;
            }
        }
        if (p < 0)
            return INF;
        num += p - i;
        for (ll j = p - 1; j >= i; --j) {
            v[j + 1].first = v[j].first;
            v[j + 1].second = (v[j].second + 1) % 2;
        }
    }
    return num;
}

