bool isvalidflip(ll flip)
{

    int one = 0;
    while (flip != 0)
    {
        one != (flip & 1);
        flip >>= 1;
    }
    return (one % 2 == 0);
}

int calc(int n, ll flip, vector<int> &a, vector<int> &b)
{
    vector<int> c(n);
    vector<int> d(n);
    vector<bool> rev(n);
    rep(i, n)
    {
        rev[i] = (flip >> i) & 1;
        if (((flip >> i) & 1) == 0)
        {
            c[i] = a[i];
        }
        else
        {
            c[i] = b[i];
        }
        d[i] = c[i];
    }
    sort(ALL(c));
    bool isok = false;
    map<int, bool> mp;
    mp.clear();
    rep(i, n)
    {
        isok = false;
        rep(j, n)
        {
            if (mp[j] == true)
            {
                continue;
            }
            if (d[i] == c[j] && ((rev[i] == false && abs(i - j) % 2 == 0) || (rev[i] == true && abs(i - j) % 2 == 1)))
            {
                mp[j] = true;
                isok = true;
                break;
            }
        }
        if (isok == false)
        {
            return -1;
        }
    }
    /*
    rep(i, n)
    {
        cerr << c[i] << " ";
    }
    cerr << endl;

    */
    int ret = 0;
    rep(i, n)
    {
        rep(j, i + 1, n)
        {
            if (d[i] > d[j])
            {
                ret++;
            }
        }
    }
    return ret;
}

