/*-----------------------------------------------------------------------------
　処理
 -------------------------------------------------------------------------------*/
// メイン
struct SWAP_INFO {
	int val;
	bool isRed;
	int cnt;
};

bool sortOne(int N, vector<SWAP_INFO> &swapRes, ll &swapCntAll)
{
	swapCntAll = 0;
	REP(i, N - 1) {
		for (int j = N - 1; j > i; j--) {
			if (swapRes[j].val < swapRes[j - 1].val) {
				swapRes[j].cnt++;
				swapRes[j - 1].cnt++;
				swapCntAll++;
				swap(swapRes[j], swapRes[j - 1]);
			}
		}
	}

	REP(i, N - 1) {
		REP(j, N - 1) {
			bool swapExec = false;
			if (swapRes[j].isRed) {
				if (!IsEven(swapRes[j].cnt)) {
					if (swapRes[j].val == swapRes[j + 1].val) {
						swapExec = true;
					}
				}
			} else {
				if (!IsOdd(swapRes[j].cnt)) {
					if (swapRes[j].val == swapRes[j + 1].val) {
						swapExec = true;
					}
				}
			}

			if (swapExec) {
				swapRes[j].cnt++;
				swapRes[j + 1].cnt++;
				swapCntAll++;
				swap(swapRes[j], swapRes[j + 1]);
			}
		}
	}

	REP(i, N) {
		if (swapRes[i].isRed) {
			if (!IsEven(swapRes[i].cnt)) {
				return false;
			}
		} else {
			if (!IsOdd(swapRes[i].cnt)) {
				return false;
			}
		}
	}

	return true;
}

int main()
{
	int N;
	cin >> N;
	vector<int>	A(N), B(N);
	REP(i, N) cin >> A[i];
	REP(i, N) cin >> B[i];

	ll ans = INF;
	for (ll bitPtn = 0; bitPtn < ((ll)1 << N); bitPtn++) {
		vector<SWAP_INFO>	swapRes(N);
		REP(i, N) {
			auto &one = swapRes[i];
			if (bitPtn & ((ll)1 << i)) {
				one.val = A[i];
				one.isRed = true;
			} else {
				one.val = B[i];
				one.isRed = false;
			} 
			one.cnt = 0;
		}

		ll swapCntAll = 0;
		if (sortOne(N, swapRes, swapCntAll)) {
			ans = min(ans, swapCntAll);
		}
	}

	if (ans == INF) {
		cout << -1 << endl;
	} else {
		cout << ans << endl;
	}

	return 0;
}

