        if(i & (1<<k)) continue;
        cnt++;
        llint d = abs(pop[i]-k), v = a[d%2][k];
        if(v < j) continue;
        dp[i|(1<<k)][v] = min(dp[i|(1<<k)][v], dp[i][j] + cnt-1);
      }
    }
  }

  /*for(int i = 0; i < N; i++){
    for(int j = 0; j < 5; j++){
      cout << dp[i][j] << " ";
    }
    cout << endl;
  }*/

  llint ans = inf;
  for(int j = 0; j <= 50; j++) ans = min(ans, dp[N-1][j]);
  if(ans > inf/2) ans = -1;
