int cnt_swap(vector<int> A){
  int c = 0;
  for(size_t i = 0; i < A.size(); ++i){
    for(size_t j = 1; j < A.size(); ++j){
      if(A[j] < A[j-1]){
        swap(A[j],A[j-1]);
        ++c;
      }
    }
  }
  return c;
}

int main(){
