  for(int i = 0; i < N; ++i) cin >> B[i];
  int ans = INF;
  for(int i = 0; i < (1<<N); ++i){
    if(__builtin_popcount(i)%2) continue;
    vector<vector<pair<int,int>>> C(2);
    for(int j = 0; j < N; ++j){
      if(i>>j&1){
        C[(j+1)%2].emplace_back(B[j],j);
