const int INF = 0x3f3f3f3f;
const int MAXN = 18;
const int MAXX = 50;

int N;
int A[MAXN + 1];
int B[MAXN + 1];

tuple<int,int,bool> X[MAXN + 1];

int calcDist() {
    vector<vector<pair<int, bool>>> rev(MAXX + 1);  // (index, B?)
    for (int i = 0; i < N; i++)
        rev[get<0>(X[i])].emplace_back(get<1>(X[i]), get<2>(X[i]));

    int res = 0;

    int x = 1;
    for (int i = 0; i < N; i++) {
        while (rev[x].empty())
            x++;

        int d = INF;
        int pos = INF;
        for (int j = 0; j < int(rev[x].size()); j++) {
            int t = rev[x][j].first - i;
            t = abs(t);
            if (((t & 1) != 0) == rev[x][j].second && t < d) {
                d = t;
                pos = j;
            }
        }
        if (d >= INF)
            return INF;
        swap(rev[x][pos], rev[x].back());
        rev[x].pop_back();
        res += d;
    }
    return res;
}

int main(void) {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N;

    for (int i = 0; i < N; i++)
        cin >> A[i];
    for (int i = 0; i < N; i++)
        cin >> B[i];

    bool ok = true;
    for (int i = 1; i < N; i++) {
        if (A[i - 1] > A[i]) {
            ok = false;
            break;
        }
    }
    if (ok) {
        cout << 0 << endl;
        return 0;
    }

    int res = INF;
    for (int i = 0; i < (1 << N); i++) {
        int bit = popcount(i);
        if (bit & 1)
            continue;

        for (int j = 0; j < N; j++) {
            if (i & (1 << j))
                X[j] = make_tuple(B[j], j, true);
            else
                X[j] = make_tuple(A[j], j, false);
        }
        res = min(res, calcDist());
    }

    if (res >= INF)
        cout << -1 << endl;
    else
        cout << res / 2 << endl;

    return 0;
}

