int count(int s) {
    int a = 0;
    while (s > 0) { if (s & 1) a++; s /= 2; }
    return a;
}

bool check(int *c, int n, int s) {
    int d[n];
    memcpy(d, c, sizeof d);
    sort(d, d+n);
    bool used[n];
    memset(used, 0, sizeof used);
    for (int i = 0; i < n; i++) {
        int v = c[i];
        bool ok = false;
        for (int j = ((s >> i) & 1) ? 1 ^ (i % 2) : i % 2; j < n; j += 2) {
            if (d[j] == v && !used[j]) {
                used[j] = true;
                ok = true;
                // cerr << i << ' ' << j << endl;
                break;
            }
        }
        if (!ok) return false;
    }
    return true;
}

int transpos(int *c, int n) {
    int a  = 0;
    for (int i = 0; i < n; i++)
        for (int j = i+1; j < n; j++)
            if (c[i] > c[j]) a++;
    // cerr << "transp: " << a << endl;
    return a;
}

int main() {
    int n; cin >> n;
    int a[n], b[n];
    for (int i = 0; i < n; i++) cin >> a[i];
    for (int i = 0; i < n; i++) cin >> b[i];
    int ans = 1<<30;
    for (int s = 0; s < 1<<n; s++) {
        if (count(s) % 2) continue;
        int c[n];
        for (int i = 0; i < n; i++) c[i] = ((s >> i) & 1) ? b[i] : a[i];
        // cerr << "s = " << s << endl;
        // cerr << "c: "; for (int i = 0; i < n; i++) cerr << c[i] << ' '; cerr << endl;
        if (check(c, n, s)) {
            // cerr << "ok " << s << endl;
            ans = min(ans, transpos(c, n));
        }
    }
    cout << (ans == 1<<30 ? -1 : ans) << endl;
}

