int bubble_sort(vi a)
{
	int res = 0;
	while (true)
	{
		bool update = false;
		rep(i, sz(a)-1)
		{
			if (a[i] > a[i + 1])
			{
				swap(a[i], a[i + 1]);
				update = true;
				res++;
			}
		}
		if (!update)break;
	}
	return res;
}

