int N;
int A[55], B[55], C[55], D[55];
int INF = 12345678;

int main() {
	cin >> N;
	int ans = INF;
	for (int i = 0; i < N; ++i) {
		cin >> A[i];
	}
	for (int i = 0; i < N; ++i) {
		cin >> B[i];
	}
	for (int bit = 0; bit < (1 << N); ++bit) {
		bool F[55] = {};
		map<int, bool>sum;
		for (int i = 0; i < N; ++i) {
			C[i] = ((bit & (1 << i)) ? B[i] : A[i]);
			sum[C[i]] ^= (bit & (1 << i));
		}
		int can = 0;
		for (int i = 0; i < N; ++i) {
			for (int j = 0; j < i; ++j) {
				if (C[i] < C[j]) {
					F[i] = !F[i];
					F[j] = !F[j];
					can++;
				}
			}
		}
		for (int i = 0; i < N; ++i) {
			sum[C[i]] ^= F[i];
		}
		for (auto p : sum) {
			if (p.second) {
				can = INF;
				break;
			}
		}
		ans = min(ans, can);
	}
	if (ans == INF)ans = -1;
	cout << ans << endl;
	return 0;
}

