const int inf=1e9+7;
const ll mod=1e9+7;
const ll big=1e18;
const double PI=2*asin(1);

int N;
int A[20], B[20];
int DP[(1<<20)][20];

int solve(int S, int x) {
  if(DP[S][x]>0) return DP[S][x];
  if(S==0) {
    return DP[S][x] = x;
  }
  DP[S][x] = inf;
  int pos = -1; // Sのうちビットが立っているものの最後の要素のインデックス
  for(int i=0;i<N;++i) {
    if((S&(1<<i))!=0) pos++;
  }
  int num = 0;
  for(int i=0;i<x;++i) {
    if((S&(1<<i))==0) num++;
  }
  int tmp1, tmp2;
  for(int i=0;i<N;++i) {
    if((S&(1<<i))==0) continue;
    if((i-pos)%2==0) tmp1 = A[i]; 
    else tmp1 = B[i];
    if((x-(pos+1))%2==0) tmp2 = A[x];
    else tmp2 = B[x];
    if(tmp1>tmp2) continue;
    DP[S][x] = min(DP[S][x], solve((S^(1<<i)), i)+num);
  }
  return DP[S][x];
}

int main() {
  cin>>N;
  for(int i=0;i<N;++i) cin>>A[i];
  for(int i=0;i<N;++i) cin>>B[i];
  int S = (1<<N) - 1;
  int ans = inf;
  for(int i=0;i<N;++i) {
    ans = min(ans, solve(S^(1<<i), i));
  }
  if(ans==inf) cout<<-1<<endl;
  else cout<<ans<<endl;
}

