int dp(int tadi, int mask){
    int now = __builtin_popcount(mask);
    if(now == n) return 0;
    int &ret = dep[tadi][mask];
    if(ret != -1) return ret;
    ret = 1e9;
    int bil = -1e9;
    if(mask > 0){
        if((now - 1) % 2 == tadi % 2) bil = a[tadi];
        else bil = b[tadi];
    }
    vector<int> count(n, 0);
    for(int i = 0; i < n; i++){
        if(mask & (1 << i)) count[i] = 1;
    }
    for(int i = n - 2; i >= 0; i--) count[i] += count[i + 1];
    for(int i = 0; i < n; i++){
        if(mask & (1 << i)) continue;
        int cost = 0;
        if(i < n - 1) cost = count[i + 1];
        int apa = b[i];
        if(i % 2 == now % 2) apa = a[i];
        if(bil <= apa) ret = min(ret, dp(i, mask | (1 << i)) + cost);
    }
    return ret;
}

