	for (int set{}; set < limit; set++)
	{
		std::vector<int> sequence(N);
		for (int i{}; i < N; i++)
			sequence[i] = ab[i][set >> i & 1];
		int count{};
		RSumQBIT bit(51);
		std::vector<std::vector<bool>> odd(51);
		for (int i{}; i < N; i++)
		{
			int64_t tmp{bit.get(sequence[i] + 1, 51)};
			odd[sequence[i]].push_back((tmp & 1) != (set >> i & 1));
			count += tmp;
			bit.update(sequence[i], 1);
		}
		for (auto& e: odd)
		{
			int odd_count{};
			for (auto&& f: e)
				if (f)
					odd_count++;
