int n;
vector<pii> line;
//place最後に使った対象,used使用済み
int func(int place,int used,int bp){
	if(used==bit(n)-1){
		return 0;
	}
	static vvector<int> dp(n,vector<int>(bit(n),-1));
	if(dp[place][used]>=0)return dp[place][used];
	int res = INF;
	vector<pii> nows;
	vector<int> bcnt(n+1,0);
	vector<int> fcnt(n,0);
	per(i,n){
		bcnt[i] = bcnt[i+1];
		if(bit(i)&used){
			++bcnt[i];
		}
	}
	rep(i,n){
		if(i){
			fcnt[i]=fcnt[i-1];
		}
		if(~used&bit(i)){
			++fcnt[i];
		}
	}
	for(int i=n-1;i>=0;--i){
		if(used&bit(i))continue;
		if((fcnt[i]+bcnt[i])&1){
			nows.emplace_back(line[i].first,i);
		}else{
			nows.emplace_back(line[i].second,i);
		}
	}
	rep(i,nows.size()){
		if(bp>nows[i].first)continue;
		chmin(res,nows.size()-i-1+func(nows[i].second,used|bit(nows[i].second),nows[i].first));
	}
	return dp[place][used] = res;
}

