using namespace std;
struct Node
{
    int src_pos;
    int v;
    bool is_red;
    bool operator<(const Node&o)const{
        return v < o.v;
    }
};
int count_inv(const vector<Node>&v)
{
    int ans = 0;
    for(int i=0;i<v.size();++i)
    {
        for(int j=i+1;j<v.size();++j)
        {
            if(v[j].src_pos < v[i].src_pos)
                ans++;
        }
    }
    return ans;
}
bool cmp(const Node& a,const Node&b)
{
    return a.src_pos < b.src_pos;
}
bool check(vector<Node>&v,int beg,int end)
{
    queue<Node> q0,q1;
    sort(v.begin()+beg,v.begin()+end,cmp);
    for(int i=beg;i<end;++i)
    {
        if(v[i].is_red^(abs(v[i].src_pos-beg)&1))
            q0.push(v[i]);
        else
            q1.push(v[i]);
    }
    if(q0.size()!=end-beg+1>>1)
        return false;
    bool cnt = 0;
    for(int i=beg;i<end;++i)
    {
        if(!cnt){v[i]=q0.front();q0.pop();}
        else{v[i]=q1.front();q1.pop();}
        cnt = !cnt;
    }
    return true;
}
void solve(int N, std::vector<int> A, std::vector<int> B){
    int lim = (1<<N);
    int ans = INT_MAX;
    for(int i=0;i<lim;++i)
    {
        vector<Node> v;
        for(int j=0;j<N;++j)
            if(i>>j&1)
                v.push_back({j,A[j],true});
            else
                v.push_back({j,B[j],false});
        sort(v.begin(),v.end());
        int p = 0;
        bool flag = true;
        while(p<N)
        {
            int e = p+1;
            while(e<N && v[e].v==v[p].v)e++;
            if(!check(v,p,e)){
                flag = false;
                break;
            }

            p = e;
        }
        if(flag)
            ans = min(ans,count_inv(v));
    }
    if(ans!=INT_MAX)
        cout<<ans<<endl;
    else
        cout<<-1<<endl;
}

int main(){
    int N;
    cin>>N;
    vector<int> A(N);
    for(int i = 0 ; i < N ; i++){
        cin>>A[i];
    }
    std::vector<int> B(N);
    for(int i = 0 ; i < N ; i++){
        cin>>B[i];
    }
    solve(N, std::move(A), std::move(B));
    return 0;
}

