using namespace std;

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);

  int n;
  cin >> n;

  vector<pair<int, int>> x(n);
  for(int i = 0; i < n; i++) cin >> x.at(i).first;
  for(int i = 0; i < n; i++) cin >> x.at(i).second;

  // bit全探索
  int ans = 1e9;
  for(int bit = 0; bit < (1 << n); bit++){
    vector<pair<int, int>> a, b;
    for(int j = 0; j < n; j++){
      if(bit & (1 << j)){
        if(j % 2 == 0){
          a.push_back(make_pair(x.at(j).first, j));
        }
        else{
          b.push_back(make_pair(x.at(j).first, j));
        }
      }
      else{
        if(j % 2 == 0){
          b.push_back(make_pair(x.at(j).second, j));
        }
        else{
          a.push_back(make_pair(x.at(j).second, j));
        }
      }
    }

    // 数の判定
    if(!(a.size() - b.size() == 0 || a.size() - b.size() == 1)){
      continue;
    }

    // 広義単調増加の判定
    sort(a.begin(), a.end());
    sort(b.begin(), b.end());
    bool judge = true;
    for(int j = 1; j < a.size(); j++){
      if(b.at(j - 1).first > a.at(j).first){
        judge = false;
        break;
      }
    }
    for(int j = 0; j < b.size(); j++){
      if(a.at(j).first > b.at(j).first){
        judge = false;
        break;
      }
    }
    if(!(judge)) continue;

    // swap数のカウント
    int keep = 0;
    for(int j = 0; j < a.size(); j++){
      keep += abs(a.at(j).second - 2 * j);
    }
    for(int j = 0; j < b.size(); j++){
      keep += abs(b.at(j).second - (2 * j + 1));
    }

    ans = min(ans, keep / 2);
  }

  if(ans == 1e9) cout << -1 << '\n';
  else cout << ans << '\n';
}

