using namespace std;

SINT64 bits64(SINT64 bits)
{
    bits = (bits & 0x55555555) + (bits >> 1 & 0x55555555);
    bits = (bits & 0x33333333) + (bits >> 2 & 0x33333333);
    bits = (bits & 0x0f0f0f0f) + (bits >> 4 & 0x0f0f0f0f);
    bits = (bits & 0x00ff00ff) + (bits >> 8 & 0x00ff00ff);
    return (bits & 0x0000ffff) + (bits >>16 & 0x0000ffff);
}

int main() {

	SINT64 N;	cin >> N;
	vector<SINT64> A(N);
	vector<SINT64> B(N);
	rep(i,0,N) {
		cin >> A[i];
	}
	rep(i,0,N) {
		cin >> B[i];
	}

	SINT64 ans = INF64;

	rep(i,0,1<<N) {
		if ((bits64(i) % 2) == 1) continue;
		vector<Pll> buf;
		SINT64 cnt = 0;
		rep(j,0,N) {
			if (((i>>j) & 1) == 0) {
				buf.emplace_back(Pll(A[j],0));
			} else {
				buf.emplace_back(Pll(B[j],1));
			}
		}

		rep(c,0,N+1) {
		rep(j,0,N-1) {
			if (buf[j].F > buf[j+1].F) {
				swap(buf[j],buf[j+1]);
				buf[j].S = 1-buf[j].S;
				buf[j+1].S = 1-buf[j+1].S;
				cnt++;
			}
		}
		}

		rep(c,0,N+1) {
		rep(j,0,N-1) {
			if (buf[j].S == 1) {
				SINT64 k = j+1;
				if (buf[j].F == buf[k].F) {
					if (buf[j].S == buf[k].S) {
						buf[j].S = 0;
						buf[k].S = 0;
						cnt += k-j;
					} else {

						rep(kk,k+1,N) {
							if (((kk-j) % 2) == 0) {
								if (buf[j].F == buf[kk].F) {
									if (buf[kk].S == 0) {
										rep(s,0,kk-j) {
											buf[kk-s].S = 1-buf[kk-s-1].S;
										}
										buf[j].S = 0;
										cnt += (kk-j);
										break;
									}

								} else {
									break;
								}

							}
						}
						}

				} else {

				}		
			}
		}
		}

		SINT64 ok = 0;
		rep(j,0,N) {
			if (buf[j].S == 1) {
				ok = 1;
			}
		}

		if(ok == 0) {
		ans = MIN(ans,cnt);
		}

	}

	if (ans == INF64) {
		ans = -1;
	}

	put(ans);
	return 0;
}


