struct Solver {
    int N;
    vector<vector<int>> table;
    vector<vector<int>> dp;

    Solver(int n, vector<vector<int>> v) : N(n),
                                           table(n, vector<int>(n)),
                                           dp(60, vector<int>(1 << n, -1)) {
        REP(i, n){
            REP(j, n){
                table[i][j] = v[j][abs(i-j)%2];
            }
        }
        REP(i, 60) dp[i][0] = 0;
    }

    int solve(int mi, int bit) {
        if(dp[mi][bit] != -1) return dp[mi][bit];
        int res = inf;

        REP(i, N){
            int k = table[__builtin_popcount(bit) - 1][i];
            if(!((bit >> i) & 1) || mi < k) continue;

            int cnt = __builtin_popcount(bit & ~((1 << (i + 1)) - 1));
            cnt += solve(k, bit & ~(1 << i));
            chmin(res, cnt);
        }
        return dp[mi][bit] = min(res, inf);
    }
};

