                while(idx != j){
                    ++cnt;
                    swap(v[idx], v[idx - 1]);
                    if(bs[idx] == bs[idx - 1]){
                        bs.flip(idx);
                        bs.flip(idx - 1);
                    }
                    --idx;
                }
