#define SIZE 20

int dp[1<<18][50];

int main() {
  int N, A[SIZE], B[SIZE];

  cin >> N;

  for (int i=0; i<N; i++) cin >> A[i];
  for (int i=0; i<N; i++) cin >> B[i];

  for (int i=0; i<N; i++) {
    A[i]--; B[i]--;
  }

  for (int i=0; i<(1<<N); i++)
    for (int j=0; j<50; j++)
      dp[i][j] = INF;

  dp[0][0] = 0;

  for (int i=0; i<(1<<N); i++) {
    for (int k=0; k<50; k++) {
      if (dp[i][k] == INF) continue;

      for (int j=0; j<N; j++) {
        if (i & (1 << j)) continue;

        int maskR = ((1 << N) - 1) - ((1 << (j+1)) - 1);
        int maskL = ((1 << j) - 1);

        int cR = __builtin_popcount(i & maskR);
        int cL = j - __builtin_popcount(i & maskL);


        if ((cL + cR) % 2) {
          if (k <= B[j]) {
            dp[i|(1<<j)][B[j]] = min(dp[i|(1<<j)][B[j]], dp[i][k] + cL);
          }
        } else {
          if (k <= A[j]) {
            dp[i|(1<<j)][A[j]] = min(dp[i|(1<<j)][A[j]], dp[i][k] + cL);
          }
        }
      }
    }
  }

  int ans = INF;

  for (int i=0; i<50; i++) {
    ans = min(ans, dp[(1<<N)-1][i]);
  }

  if (ans == INF) ans = -1;

  cout << ans << endl;

  return 0;
}

