int n;
map<vector<int>, int> dp;

bool check(vector<int> &v){
    int l = 0;
    for(int i = 0; i < n; i++){
        if(v[i] < l)
            return 0;
        l = v[i];
    }
    return 1;
}

int go(vector<int> v){
    /*
    cout << "go ";
    for(int i: v)
        cout << i << ' ' ;
    cout << endl;
     */
    if(dp[v])
        return dp[v];
    if(check(v))
        return dp[v] = 0;
    int ans = 1e9;
    dp[v] = ans;
    for(int i = 0; i < n-1; i++){
        vector<int> nx = v;
        swap(nx[i], nx[i+n+1]);
        swap(nx[i+1], nx[i+n]);
        ans = min(ans, go(nx)+1);
    }
    return dp[v] = ans;
}

