int n;

int dp(int mask, int val)
{

     if (mask == ((1 << n) - 1))
          return 0;
     int &ans = cache[mask][val];
     if (ans != -1)
          return ans;

     ans = 1e9;
     vector<int> v;

     for (int i = 0; i < n; i++)
     {
          if (mask & (1 << i))
               v.push_back(i + 1);
     }

     int sz = v.size() + 1;

     for (int i = 0; i < n; i++)
     {
          if (mask & (1 << i))
               continue;

          int temp = v.end() - upper_bound(v.begin(), v.end(), i + 1);

          temp += pos[i + 1];
          temp -= sz;

          if (arr[i + 1].first >= val && (abs(sz - pos[i + 1]) % 2) == 0)
               ans = min(ans, temp + dp((mask | (1 << i)), arr[i + 1].first));

          if (arr[i + 1].second >= val && (abs(sz - pos[i + 1]) % 2) != 0)
               ans = min(ans, temp + dp((mask | (1 << i)), arr[i + 1].second));

     }

     return ans;

}

