using namespace std;

const int N = 18;

int a[N][2];
int l[1 << N][N];
int w[1 << N][N];
int f[1 << N][N];

int main() {
  int n;
  scanf("%d", &n);
  for (int i = 0; i < n; ++i) {
    scanf("%d", a[i] + 0);
  }
  for (int i = 0; i < n; ++i) {
    scanf("%d", a[i] + 1);
  }
  for (int i = 0; i < (1 << n); ++i) {
    for (int j = 0, cnt = 0; j < n; ++j) {
      l[i][j] = cnt;
      if ((i >> j & 1) == 0) {
        ++cnt;
      }
    }
    for (int j = n - 1, cnt = 0; j >= 0; --j) {
      w[i][j] = l[i][j] + cnt;
      w[i][j] %= 2;
      if (i >> j & 1) {
        ++cnt;
      }
    }
  }
  const int inf = 1'000'000'000;
  for (int i = 0; i < (1 << n); ++i) {
    for (int j = 0; j < n; ++j) {
      f[i][j] = inf;
    }
  }
  for (int i = 0; i < n; ++i) {
    f[1 << i][i] = l[1 << i][i];
  }
  for (int i = 0; i < (1 << n); ++i) {
    for (int j = 0; j < n; ++j) {
      if (i >> j & 1) {
        for (int k = 0; k < n; ++k) {
          if (a[k][w[i ^ 1 << j][k]] <= a[j][w[i][j]]) {
            f[i][j] = min(f[i][j], f[i ^ 1 << j][k] + l[i][j]);
          }
        }
      }
    }
  }
  int ans = inf;
  for (int i = 0; i < n; ++i) {
    ans = min(ans, f[(1 << n) - 1][i]);
  }
  if (ans == inf) {
    ans = -1;
  }
  printf("%d\n", ans);
}

