            if ((bits >> i) & 1) {
                v.emplace_back(b[i], i);
                nflip++;
            } else {
                v.emplace_back(a[i], i);
            }
        }
        if (nflip % 2) continue;

        auto vv = v;
        sort(all(v));

        vector<int> used(n, -1);
        rep(i, n) {
            rep(j, n) {
                if (vv[j].first != v[i].first) continue;
                if ((bits >> j) & 1) {
                    if (abs(j - i) % 2 == 0) continue;
                } else {
                    if (abs(j - i) % 2 != 0) continue;
                }
                if (used[j] < 0) {
                    used[j] = i;
                    break;
                }
            }
        }

        bool ok = true;
        int tmp = 0;
        rep(i, n) {
            if (used[i] < 0) {
                ok = false;
                break;
            }
            tmp += abs(used[i] - i);
        }

        if(ok) ans = min(ans, tmp);
    }

    if (ans == (1 << 20)) ans = -1;
    else ans/=2;

    cout << ans << endl;

    return 0;
}

