const int inf = (int)1e9;

int rek(int mask, int prev){
	if(!mask)
		return 0;
	int &ret = dp[mask][prev];
	if(ret != -1)
		return ret;
	ret = inf;
	for(int i = 0 ; i < n ; ++i){
		if(!(mask & (1 << i)))
			continue;
		int br = n - __builtin_popcount(mask);
		br = abs(br - i);
		int sad = a[i][(br & 1)];
		if(sad >= prev){
			ret = min(ret, rek(mask ^ (1 << i), a[i][(br & 1)]) + br);
		}
	}
	return ret;
}

