                            //cerr << "B" << B[k] << " " << cur[B[k]] - j << endl;
                            val[B[k]] = -1;
                            rep(l, B[k]) {
                                cur[l]++;
                            }
                        }
                    }
                }
            }
            ans = min(ans, res);
            //cout << "!-1" << endl;
            next2:;
        }
