            }else{
                if(i % 2 == 0){
                    cnt_odd++;
                }else{
                    cnt_even++;
                }
            }
        }
        if(N % 2 == 0){
            if(cnt_odd != cnt_even) continue;
        }else{
            if(cnt_even != cnt_odd+1) continue;
        }
        // printa(tt, N);
        vector<lpair> odd, even;

        rep(i,0,N){
            if(tt[i] == 0 && i % 2 == 0){
