        rep(i,0,se-1){
            if(even[i].first > odd[i].first) ok = false;
        }
        rep(i,0,so-1){
            if(odd[i].first > even[i+1].first) ok = false;
        }
        if(N % 2 == 0){
            if(even[se-1].first > odd[so-1].first) ok = false;
        }
        if(N % 2 == 1){
            if(odd[so-1].first > even[so].first) ok = false;
        }
        // print(ok);
