    int ans = 1e9;
    for(int mask = 0; mask < (1 << n); mask++) {
        vector<pair<int, int>> v;
        vector<pair<int, int>> odd, even;
        // if present in mask, use b[j], else a[i]
        // b[j] and j will have different parity
        // a[j] and j will have same parity

        for(int j = 0; j < n; j++) {
            if((1 << j) & mask) {
                if(j % 2)
                    even.push_back({b[j], j});
