            else {
                if(j % 2)
                    odd.push_back({a[j], j});
                else
                    even.push_back({a[j], j});
            }
        }
        if(odd.size() != (n / 2))
            continue;
        sort(odd.begin(), odd.end());
        sort(even.begin(), even.end());
        int inv = 0;
        for(int i = 0; i < n; i++) {
            if(i % 2)
                v.push_back(odd[i / 2]);
            else
