            if(i > 0) {
                if(v.back().first < v[i - 1].first)
                    inv = 1e9;
            }
        }
        // sort odd and even and merge alternatively
        for(int i = 0; i < n; i++) {
            for(int j = i + 1; j < n; j++) {
                if(v[i].second > v[j].second)
                    inv++;
            }
        }
        // inversion count is the no of operations
        ans = min(ans, inv);

    }

