        }
    }

    int ans = INF;

    for (int i = 0; i < (1 << n); i++) {
        for (int j = 0; j < n; j++) {
            w[j] = {a[j][(i >> j) & 1], j};
        }

        sort(w, w + n);

        int c[2] = {0, 0};

        bool ok = true;

        vector<pair<int, int>> z[2];

        int last = -1;

        for (int j = 0; j < n; j++) {
            z[(w[j].second & 1) ^ ((i >> j) & 1)].push_back({w[j].second, w[j].first});
            c[j & 1]++;

            if (j + 1 == n || w[j + 1].first != w[j].first) {
                if (c[0] != z[0].size()) {
                    ok = false;
                    break;
                }

                sort(all(z[0]));
                sort(all(z[1]));

                for (int k = j; k > last; k--) {
                    w[k] = {z[k & 1].back().second, z[k & 1].back().first};
                    z[k & 1].pop_back();
                }

                assert(z[0].empty());
                assert(z[1].empty());

                c[0] = c[1] = 0;
                last = j;
            }
        }

