                for (int k = j + 1; k < n; k++) {
                    if (w[j].second > w[k].second) {
                        cur++;
                    }
                }
            }
            ans = min(ans, cur);
        }
    }

    cout << (ans == INF ? -1 : ans);

    return 0;
