            }else{
                mp[PII(sorted[i],1)].eb(i);
            }
        }
        for(auto& p : mp){
            reverse(p.second.begin(), p.second.end());
        }
        REP(i,N){
            if((mask >> i)&1){ //表採用
                VI vi;
                if(i % 2 == 0){
                    vi = mp[make_pair(origin[i],0)];
                }else{
                    vi = mp[make_pair(origin[i],1)];
                }

                if(SZ(vi) == 0){
                    ok = false;
                    break;
                }else{
                    int idx = vi.back();
                    cnt += abs(i-idx);
                    vi.pop_back();
                }
            }else{ //裏採用

                VI vi;
                if(i % 2 == 0){
                    vi = mp[make_pair(origin[i],1)];
                }else{
                    vi = mp[make_pair(origin[i],0)];
                }

                if(SZ(vi) == 0){
                    ok = false;
                    break;
                }else{
                    int idx = vi.back();
                    cnt += abs(i-idx);
                    vi.pop_back();
                }
            }
        }

        if(!ok) continue;
        chmin(ans,cnt);
    }
    if(ans == INF or ans%2 == 1) cout << -1 << endl;
    else cout << ans/2 << endl;

}

