    }
    for(int i = 0; i < n; i++){
        cin >> lis[i][1];
        lis[i][2] = i;
    }
    solve(lis, after, 0);
    if(mi == 1000000){
        cout << -1 << endl;
        return 0;
    }
    cout << mi << endl;
    return 0;
}

