ll func(ll idx,int s,ll mask)
{
    if(mask==(1<<n)-1){return 0;}

    if(dp[idx][s][mask]==-1){
    ll ans=INT_MAX;
    ll count=0;
    int ch[n]={0};
    for(ll i=0;i<n;++i){
        if((mask&(1<<i))!=0){++count;ch[i]=1;}
    }
    for(ll i=n-2;i>=0;--i){ch[i]+=ch[i+1];}
    for(ll i=0;i<n;++i)
    {
        if((mask&(1<<i))==0)
        {
            ll cost=0;
            if(i<n-1){cost=ch[i];}
            ll val=INT_MIN;
            if(count>0)
            {val=ar[idx].first;
            if(s){val=ar[idx].second;}
            }
            ll myval=ar[i].first;
            int ss=abs(i-count);
            if(ss%2==1){myval=ar[i].second;}
            if(val<=myval)
            {
                ans=min(ans,cost+func(i,ss%2,mask|(1<<i)));
            }
        }
    }
    dp[idx][s][mask]=ans;
    }
    return dp[idx][s][mask];
}

