{
//        cout << dp[(1 << 0)][2] << "\n";
//        exit(0);
        int sol = INF;
        for (int last = 1; last <= 50; last++)
                sol = min(sol, dp[(1 << n) - 1][last]);
        if (sol == INF)
                return -1;
        else
                return sol;
}

