      } else {
        x[i] = make_tuple(b[i], i, 'b');
        ++cnt0;
      }
    }
    if (cnt0 % 2 == 1) {
      continue;
    }
    sort(x, x + n);
    bool ok = true;
    for (int i=0; i<n; i++) {
      int v, j;
      char c;
      tie(v, j, c) = x[i];
      if (abs(j - i) % 2 == 1 && c == 'b') {
        continue;
      } else if (abs(j - i) % 2 == 0 && c == 'r') {
        continue;
      }
      if (i == n - 1) {
