void brute_force(int k, vector<iii> vec)
{
	if(k == n)
	{
		// sort(vec.begin(), vec.end());
		// for(int i = 0; i < n; i++)
		// 	printf("%d|%d|%d ", vec[i].fi.fi, vec[i].se, vec[i].fi.se); printf("\n");

		int res = 0;
		for(int i = 0; i < n; i++)
		{
			int idx = i;
			while(idx && vec[idx-1].fi.fi > vec[idx].fi.fi)
			{
				res++;
				vec[idx].se ^= 1;
				vec[idx-1].se ^= 1;
				swap(vec[idx], vec[idx-1]);
				idx--;
			}
		}
		for(int i = 0; i < n-1; i++)
		{
			for(int j = i+1; j < n; j+=2)
			{
				if(vec[i].se && vec[j].se && vec[i].fi.fi == vec[j].fi.fi)
				{
					res += j-i;
					vec[i].se ^= 1;
					vec[j].se ^= 1;
					break;
				}
			}
		}

		bool bol = 1;
		for(int i = 0; i < n; i++)
			if(vec[i].se)
				bol = 0;

		if(bol)
		{
			// printf("%d\n", res);
			// for(int i = 0; i < n; i++)
			// printf("%d|%d|%d ", vec[i].fi.fi, vec[i].se, vec[i].fi.se); printf("\n");

