	}
	else
	{
		vec.push_back({{A[k], k}, 0});
		brute_force(k+1, vec);
		vec.pop_back();

		vec.push_back({{B[k], k}, 1});
		brute_force(k+1, vec);
		vec.pop_back();
	}
}


