// Binary Indexed Tree (Fenwick Tree)
template<typename T> // T: type of cost
struct BIT {
    int n;
    std::vector<T> d;
    BIT(int n=0):n(n),d(n+1) {}
    //配列のインデックスiの要素d[i]に対して、xを加算する。
    void add(int i, T x=1) {
        for (i++; i <= n; i += i&-i) {
            d[i] += x;
        }
    }
    //配列においてインデックスがi以下の要素d[j]たちの和を計算して返す。
    T sum(int i) {
        T x = 0;
        for (i++; i; i -= i&-i) {
            x += d[i];
        }
        return x;
    }
};

int main(){
  using namespace std;
  int n;
  cin>>n;
  int a[n], b[n];
  REP(i,n){
    cin>>a[i];
  }
  REP(i,n){
    cin>>b[i];
  }
  vector<vector<long long>> dp(1<<n, vector<long long>(51, INF));
  dp[0][0] = 0;
  REP(s, (1<<n)){
    //REP(v,51){
    vector<int> ni;//sにおいて立ってないビット
    int bits = 0;//sにおいて立っているビットの数
    BIT<int> tree(n);//sにおいて立っているビットの管理
    vector<int> upbits;//sにおいて立っているビット
    REP(j,n){
      if(s & (1<<j)){
        bits++;
        tree.add(j);
        upbits.push_back(j);
      }else{
        ni.push_back(j);
      }
    }
    for(int now:upbits){
      int v;
      if(bits == 0){
        v = 0;
      }else{
        if(((bits - 1) - now) % 2 == 0){
          v = a[now];
        }else{
          v = b[now];
        }
      }
      for(int i:ni){
        int nv;
        if((bits - i) % 2 == 0){
          nv = a[i];
        }else{
          nv = b[i];
        }
        if(nv < v)continue;
        long long cnt = bits - tree.sum(i);
        dp[s | (1<<i)][nv] = min(dp[s | (1<<i)][nv], dp[s][v] + cnt);
      }
    }
  }
  long long res = INF;
  REP(v,51){
    res = min(res, dp[(1<<n) - 1][v]);
  }
  if(res == INF){
    cout<<-1<<endl;
  }else{
    cout<<res<<endl;
  }
  return 0;
}

