class Solution {
public:
	void solve() {
		int n;
		cin >> n;
		vector<int> a(n, 0), b(n, 0);
		for(int i=0; i<n; i++)cin >> a[i];
		for(int i=0; i<n; i++)cin >> b[i];
		for(int i=1; i < n; i+=2)swap(a[i], b[i]);
		int inf = 1000000000;
		int ans = inf;
		for(int i=0; i < (1<<n); i++){
			if(__builtin_popcount(i) != (n+1)/2)continue;

			vector<pair<int, int>> c(n);
			for(int j=0; j < n; j++){
				if(i & (1 << j))c[j] = make_pair(a[j], 0);
				else c[j] = make_pair(b[j], 1);
			}
			int t = 0;
			for(int j=0; j < n; j++){
				int idx = -1;
				int val = 1e9;
				for(int k = j; k < n; k ++){
					if(c[k].second != j % 2)continue;
					if(c[k].first < val){
						idx=k;
						val = c[k].first;
					}
				}
				while(idx > j){
					swap(c[idx], c[idx-1]);
					t++;
					idx--;
				}
			}
			bool flag = true;
			for(int j = 0; j < n-1; j++){
				if(c[j].first > c[j+1].first)flag = false;
				if(c[j].second != j % 2)flag = false;
			}
			if(flag)updmin(ans, t);
		}
		if(ans == inf)ans = -1;
		cout << ans << "\n";

		return;
	};
};

