int get_steps(vector<int>& from, vector<int>& odd) {

	static vector<int> sorted;
	static vector<bool> used;

	sorted.clear();
	for(auto& a : from) {
		sorted.push_back(a);
	}
	sort(sorted.begin(), sorted.end());
	used.resize(sorted.size());
	fill(used.begin(), used.end(), false);

	const int n = from.size();
	int steps = 0;

	for(int i = 0; i < n; i++) {

		bool ok = false;

		for(int j = 0; j < n; j++) {
			if(used[j]) {
				continue;
			}
			if(sorted[i] == from[j] && (i & 1) == odd[j]) {
				used[j] = true;
				ok = true;
				break;
			}
			steps += 1;
		}

		if(!ok) {
			return -1;
		}
	}

	return steps;
}

