void chmin(int& a, int b){
    a = min(a, b);
}

int nth_bit(int64_t num, int n){
    return (num >> n) & 1;
}

int pop_count(int bits){
    bits = (bits & 0x55555555) + (bits >> 1 & 0x55555555);
    bits = (bits & 0x33333333) + (bits >> 2 & 0x33333333);
    bits = (bits & 0x0f0f0f0f) + (bits >> 4 & 0x0f0f0f0f);
    bits = (bits & 0x00ff00ff) + (bits >> 8 & 0x00ff00ff);
    return (bits & 0x0000ffff) + (bits >>16 & 0x0000ffff);
}

int64_t msb(int64_t v){
  v = v | (v >>  1);
  v = v | (v >>  2);
  v = v | (v >>  4);
  v = v | (v >>  8);
  v = v | (v >> 16);
  v = v | (v >> 32);
  return v ^ (v >> 1);
}

int main(){
    int N;
    cin >> N;
    vector<int> A(N), B(N);
    for(int i=0; i<N; i++) cin >> A[i];
    for(int i=0; i<N; i++) cin >> B[i];
    const int INF = 1e9;
    vector<vector<int>> dp(1<<N, vector<int>(N, INF));
    for(int i=0; i<N; i++) dp[1<<i][i] = 0;

    for(int b=0; b<(1<<N); b++) for(int last=0; last<N; last++){
        if(dp[b][last] == INF) continue;
        int cnt = pop_count(b);
        int v1 = ((cnt-last+1)%2 ? B[last] : A[last]);
        int cost = cnt;
        for(int nxt=0; nxt<N; nxt++){
            if(nth_bit(b, nxt)){
                cost--;
                continue;
            }
            int v2 = ((cnt-nxt)%2 ? B[nxt] : A[nxt]);
            if(v1 > v2) continue;
            int b2 = b + (1<<nxt);
            chmin(dp[b2][nxt], dp[b][last] + cost);
        }
    }
    int ans = INF;
    for(int k=0; k<N; k++) chmin(ans, dp[(1<<N)-1][k]);
    if(ans == INF) ans = -1;
    cout << ans << endl;
    return 0;
}

