int n, m, k;

void solve(int) {
  cin >> n;
  vector<int> a(n), b(n);
  for (int& x : a) {
    cin >> x;
  }
  for (int& x : b) {
    cin >> x;
  }
  int ans = inf;
  for (int i = 0; i < (1 << n); ++i) {
    vector<pair<int, int>> odd, even;
    for (int j = 0; j < n; ++j) {
      if ((i >> j) & 1) {
        if (j & 1) {
          odd.emplace_back(b[j], j);
        } else {
          even.emplace_back(b[j], j);
        }
      } else {
        if (j & 1) {
          even.emplace_back(a[j], j);
        } else {
          odd.emplace_back(a[j], j);
        }
      }
    }
    if (odd.size() == even.size() || odd.size() - 1 == even.size()) {
      sort(begin(odd), end(odd));
      sort(begin(even), end(even));
      int p = -1, p1 = 0, p2 = 0;
      bool ok = true;
      vector<int> d;
      for (int j = 0; j < n; ++j) {
        if (j & 1) {
          ok &= even[p2].first >= p;
          d.push_back(even[p2].second);
          p = even[p2++].first;
        } else {
          ok &= odd[p1].first >= p;
          d.push_back(odd[p1].second);
          p = odd[p1++].first;
        }
      }
      if (ok) {
        vector<int> c(n);
        iota(begin(c), end(c), 0);
        int cur = 0;
        for (int j = 0; j < n; ++j) {
          int p = find(begin(c), end(c), d[j]) - begin(c);
          while (p > j) {
            ++cur;
            swap(c[p], c[p - 1]);
            --p;
          }
        }
        ans = min(ans, cur);
      }
    }
  }
  if (ans == inf) {
    ans = -1;
  }
  cout << ans << '\n';
}

