vector<int> A, B, idx;

int get(int i) {
  int op = abs(idx[i] - i);
  if (op % 2 == 0) return A[idx[i]];
  else             return B[idx[i]];
}

int main() {
  int N; cin >> N;
  A.resize(N), B.resize(N), idx.resize(N);
  for (int i = 0; i < N; ++i) {
    cin >> A[i];
    idx[i] = i;
  }
  for (int i = 0; i < N; ++i) {
    cin >> B[i];
  }

  LL vmin = kInf;
  do {
    LL cnt = 0;
    for (int i = 0; i < N-1; ++i) {
      int v1 = get(i);
      int v2 = get(i + 1);
      if (v1 > v2) {
        cnt = -1;
        break;
      } else {
        LL op = abs(idx[i] - i);
        cnt += op;
      }
    }
    if (cnt < 0) continue;
    vmin = min(vmin, cnt/2LL);
  } while(next_permutation(idx.begin(), idx.end()));

  if (vmin == kInf) cout << -1 << endl;
  else              cout << vmin << endl;
}

