// >>> RLE for vector
template <class T, class F>
vector<tuple<T,int,int> > RLE(vector<T> const& v, F f) {
    if (v.empty()) return {};
    vector<tuple<T,int,int> > ret;
    int ii = -1, n = v.size();
    rep (i,n) if (i == n-1 || f(v[i]) != f(v[i+1])) {
        ret.emplace_back(v[i],ii+1,i+1);
        ii = i;
    }
    return ret;
}
