void solve() {
  int n; cin >> n;
  vi a(n), b(n);
  rep(i,n) cin >> a[i];
  rep(i,n) cin >> b[i];

  vi c = a, d = b;
  rep(i,n) if (i%2) swap(c[i], d[i]);

  int cnt = (n+1) / 2;
  int cnt2 = n/2;
  const int INFTY = 1e9;
  int ans = INFTY;

  rep(tmp,(1<<n)) {
    bitset<18> s(tmp);
    if (s.count() != cnt) continue;

    Graph<int> odd, even;
    rep(i,n) {
      if (s[i]) odd.push_back({c[i], i});
      else even.push_back({d[i], i});
    }
    sort(ALL(odd));
    sort(ALL(even));

    bool possible = true;
    rep(i,cnt2) {
      if (odd[i][0] > even[i][0]) {
        possible = false;
        break;
      }
    }
    if (!possible) continue;
    rep(i,cnt-1) {
      if (even[i][0] > odd[i+1][0]) {
        possible = false;
        break;
      }
    }
    if (!possible) continue;

    vi arr(n);
    rep(i,cnt) arr[i*2] = odd[i][1];
    rep(i,cnt2) arr[i*2+1] = even[i][1];

    int sum = 0;
    vi line(n);
    rep(i,n) line[i] = i;
    rrep(i,n) {
      auto itr = lower_bound(ALL(line), arr[i]);
      int pos = itr - line.begin();
      sum += i - pos;
      line.erase(itr);
    }
    ans = min(ans, sum);
  }

  if (ans == INFTY) cout << -1 << endl;
  else cout << ans << endl;
}


