ll dp[1 << 18][18];
void solve()
{
    ll N;
    in(N);
    vll A(N);
    vin(A, N);
    vll B(N);
    vin(B, N);
    const ll ma = 1LL << N;
    if (N == 1) {
        print(0);
        return;
    }
    // dp[bit][last] = 最小の転倒数
    // bit=使ったら1
    for2 (i, 1, ma) {
        for1 (j, N) {
            dp[i][j] = INF;
        }
    }

    // はじめの1個
    for1 (i, N) {
        dp[1LL << i][i] = i;
    }

    for2 (used, 1, ma) {
        ll cnt = 0;
        for1 (i, N) {
            if (((used >> i) & 1) != 0) cnt++;
        }
        for1 (last, N) {
            if (((used >> last) & 1) == 0) continue;
            for1 (now, N) {
                ll nowb = 1LL << now;
                if (used & nowb) continue;
                ll left = (last - (cnt - 1)) % 2 == 0 ? A[last] : B[last];
                ll right = (now - cnt) % 2 == 0 ? A[now] : B[now];
                // dump(used, last, now, cnt, left, right);
                if (left <= right) {
                    ll used2 = used | nowb;
                    chmin(dp[used2][now], dp[used][last] + abs(now - cnt));
                }
            }
        }
    }
    ll ans = INF;
    for1 (i, N) {
        chmin(ans, dp[ma - 1][i]);
    }
    if (ans == INF) {
        print(-1);
    }
    else {
        print(ans / 2);
    }
}
