		rep(i, N-1) {
			if (!vb[i]) {
				if (vp[i].first == vp[i+1].first) {
					vb[i] = !vb[i];
					vb[i+1] = !vb[i+1];
					// r++;
				}
			}
		}
		rep(i, N) {
			if (!vb[i]) r = 1e9;
		}
		chmin(res, r);
	} while (next_permutation(all(per)));
	if (res >= 1e5) cout << -1 << endl;
	else cout << res << endl;
}

