#define CeilN(x, n)			(((((x))+((n)-1))/(n))*(n))	/* Nの倍数に切り上げ */
#define FloorN(x, n)		((x)-(x)%(n))				/* Nの倍数に切り下げ */
#define IsOdd(x)			(((x)&0x01UL) == 0x01UL)			
#define IsEven(x)			(!IsOdd((x)))						
#define M_PI				3.14159265358979323846
typedef long long			ll;
typedef pair<ll, ll>		P;

/*-----------------------------------------------------------------------------
　処理
 -------------------------------------------------------------------------------*/
struct SWAP_INFO {
	int val;
	bool isRed;
	int idx;
};

ll moveOne(int to, int from, vector<SWAP_INFO> &swapInfo)
{
	ll cnt = 0;
	for (int i = from; to < i; i--) {
		swap(swapInfo[i], swapInfo[i - 1]);
		cnt++;
	}
	return cnt;
}

bool sortOne(int N, vector<SWAP_INFO> &swapInfo, ll &swapCntOne, vector<int>	&sortedVal)
{
	swapCntOne = 0;
	REP(i, N) {
		bool isFind = false;
		int valOne = sortedVal[i];
		REPN(j, i, N) {
			if (valOne == swapInfo[j].val) {
				int diff = abs(swapInfo[j].idx - i);
				if (swapInfo[j].isRed) {
					if (IsEven(diff)) {
						swapCntOne += moveOne(i, j, swapInfo);
						isFind = true;
						break;
					}
				} else {
					if (IsOdd(diff)) {
						swapCntOne += moveOne(i, j, swapInfo);
						isFind = true;
						break;
					}
				}
			}
		}

		if (!isFind) {
			return false;
		}
	}

	return true;
}

