{
	int N;
	cin >> N;
	vector<int>	A(N), B(N);
	REP(i, N) cin >> A[i];
	REP(i, N) cin >> B[i];

	ll ans = INF;
	for (ll bitPtn = 0; bitPtn < ((ll)1 << N); bitPtn++) {
		vector<SWAP_INFO>	swapInfo(N);
		vector<int>	sortedVal(N);
		REP(i, N) {
			auto &one = swapInfo[i];
			if (bitPtn & ((ll)1 << i)) {
				one.val = sortedVal[i] = A[i];
				one.isRed = true;
			} else {
				one.val = sortedVal[i] = B[i];
				one.isRed = false;
			} 
			one.idx = i;
		}

		ll swapCntOne = 0;
		sort(ALL(sortedVal));
		if (sortOne(N, swapInfo, swapCntOne, sortedVal)) {
			ans = min(ans, swapCntOne);
		}
	}

	if (ans == INF) {
		cout << -1 << endl;
	} else {
		cout << ans << endl;
	}

	return 0;
}

