        }

        // bubble
        vector<int> ind(N);
        REP(i, N) { ind[i] = i; }
        int t = 0;
        for (int i = 0; i < N - 1; i++) {
            for (int j = 0; j < N - i - 1; j++) {
                if (use[j] > use[j + 1]) { // 右隣が小さければ入れ替える
                    swap(use[j], use[j + 1]);
                    swap(ind[j], ind[j + 1]);
                    t++;
                }
            }
        }

        mask = 1;
        bool flag = false;
        vector<int> ind2(N);
        REP(i, N) { ind2[ind[i]] = i; }
        REP(i, N) {
            if (mask & bit) { // ビットが立てば裏
                if (abs(ind2[i] - i) % 2 == 0) {
                    flag = true;
                }
            } else {
                if (abs(ind2[i] - i) % 2 == 1) {
                    flag = true;
                }
            }
            mask = mask << 1;
        }
        if (flag) {
            bit++;
            continue;
        }
        // cout << "bit:" << bit << " t:" << t << endl;
        chmin(ans, t);

        bit++;
    }

    if (ans == INF) {
