            if ((i>>n)&1) {
                if (abs(n-m)%2 == 1) {
                    bOk = false;
                }
            } else {
                if (abs(n-m)%2 == 0) {
                    bOk = false;
                }
            }

            if (bOk) continue;

            for (int m = n+1; m < N; ++m) {
                if (V[n].first != V[m].first) {
                    break;
                }
                if (abs(V[n].second - V[m].second)%2 == 1) {
                    swap(V[n], V[m]);
                    bOk = true;
                    break;
                }
            }

            if (!bOk) break;
        }

        if (!bOk) continue;

        int Tmp = 0;
        for (int n = 0; n < N; ++n) {
            for (int m = n+1; m < N; ++m) {
                if (n == V[m].second) {
                    for (int k = m-1; k >= n; --k) {
                        swap(V[k], V[k+1]);
                        ++Tmp;
                    }
                    break;
                }
            }
        }

        if (Tmp < Res) {
            Res = Tmp;
        }
    }

    if (Res != INF) {
        cout << Res << endl;
    } else {
        cout << -1 << endl;
    }

    return 0;
}

