      if(d[now.pos+1][v[now.pos%2][i]].find(now.used|(1<<i)) == d[now.pos+1][v[now.pos%2][i]].end() ||
          now.cost + abs(i - now.pos) < d[now.pos+1][v[now.pos%2][i]][now.used|(1<<i)]) {
        d[now.pos+1][v[now.pos%2][i]][now.used|(1<<i)] = now.cost + abs(i-now.pos);
        if(now.pos + 1 != n) pq.push({now.cost + abs(i-now.pos), v[now.pos%2][i], now.pos+1, now.used|(1<<i)});
      }
