template< typename T >
struct BinaryIndexedTree {
  vector< T > data;
  BinaryIndexedTree(int sz) {
    data.assign(++sz, 0);
  }
  T sum(int k) {
    T ret = 0;
    for(++k; k > 0; k -= k & -k) ret += data[k];
    return (ret);
  }
  void add(int k, T x) {
    for(++k; k < SZ(data); k += k & -k) data[k] += x;
  }
};

ll hanten(VI& A){
    ll N = A.size();
    auto bit = BinaryIndexedTree<ll>(N);
    ll count = 0;
    FOR(i, 0, N){
        ll a = A[i];
        ll num = i - bit.sum(a);
        count += num;
        bit.add(a, 1);
    }
    return count;
}

bool isIncreasing(VI& V){
  VI A = V;
  SORT(A);
  ll N = V.size();
  rep(i, N){
    if(V[i]!=A[i]) return false;
  }
  return true;
}

ll bubble_sort(vector<ll> &A){
    ll N = A.size();    
    ll cnt=0;
    // iまで見る
    for(int i=N-1; i>=0; i--){
        FOR(j, 0, i){
            if(A[j] > A[j+1]){
                swap(A[j], A[j+1]);
                cnt++;
            }
        }
    }
    return cnt;
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    // input
    ll N; 
    cin >> N;

    VI A(N);
    rep(i, N) cin>>A[i];

    VI B(N);
    rep(i, N) cin>>B[i];

    ll mi = inf;
    ll odd = N/2;
    ll even = N-odd;
    rep(f, 1LL<<N){
      VI OD; // odd vector
      VI EV; // even vector
      VI OR; // original vector
      // debug(f);
      rep(i, N){
        if(f>>i&1){
          // 1だとひっくり返ってるとする
          if(i%2==0){
            OD.push_back(B[i]);
          }else{
            EV.push_back(B[i]);
          }
          OR.push_back(B[i]);
        }else{
          if(i%2==0){
            EV.push_back(A[i]);
          }else{
            OD.push_back(A[i]);
          }
          OR.push_back(A[i]);
        }
      }
      if(odd==SZ(OD) && even==SZ(EV)){
        // ok
      }else{
        // debug("skip by size");
        continue;
      }

      // odd, evenの数は合っている
      SORT(EV);
      SORT(OD);
      // zip (合成する)
      VI SO; // sorted vector
      rep(i, SZ(OD)){
        SO.push_back(EV[i]);
        SO.push_back(OD[i]);
      }
      if(SZ(EV)!=SZ(OD)){
        SO.push_back(EV.back());
      }
      // debug(SO);

      // これがsortedか？
      if(isIncreasing(SO)){
        // ok
      }else{
        // debug("skip by not sorted");
        continue;
      }

      // original vectorをsortedにするまでの回数が反転数
      ll h = bubble_sort(OR);
      chmin(mi, h);
    }

    if(mi==inf){
      p(-1);
    }else{
      p(mi);
    }

    return 0;
}

