#define foi(i,k,n) for(int i = (int)k; i < (int)n; ++i)
using namespace std;
using ll = long long;
using ii = pair<int,int>;
constexpr int MAXN = 18;
constexpr int INF = 1e6;

int memo[1<<MAXN][51];
int a[MAXN], b[MAXN], n;
vector<int> posbits[1<<MAXN];

int dp(int bm, int l) {
  if (bm == 0) return 0;
  int& ans = memo[bm][l];
  if (~ans) return ans;

  ans = INF;
  const vector<int>& v = posbits[bm];
  int pos = n - posbits[bm].size();
  for (int x : v) {
    int izq0 = __builtin_popcount((bm ^ ((1 << n) - 1)) & ~((1 << (1 + x)) - 1));
    int currpos = x + izq0;

    int num = (currpos - pos + izq0) & 1 ? b[x] : a[x];
    if (num >= l) {
      ans = min(ans, currpos - pos + dp(bm ^ (1 << x), num));
    }
  }

  return ans;
}

int main() {
  ios::sync_with_stdio(false); cin.tie(nullptr); cout.tie(nullptr);
  cin >> n;
  foi (i,0,n) cin >> a[i];
  foi (i,0,n) cin >> b[i];
  foi (i,0,1<<MAXN) {
    foi (j,0,MAXN) {
      if ((i >> j) & 1) {
        posbits[i].push_back(j);
      }
    }
  }

  memset(memo, -1, sizeof memo);
  cout << (dp((1<<n)-1,0) >= INF ? -1 : dp((1<<n)-1,0)) << '\n';
  return 0;
}

