  {
     cin>>a[i];
  }
  vector<int> b (n,0);
  for (int i = 0; i < n; i++)
  {
     cin>>b[i];
  }
  vector<vector<int> > dp (500000,vector<int>(55,INF));
  dp[0][0] = 0;
  for (int bit = 0; bit < (1<<n); bit++)
  {
    int s_size = 0;
    for (int i = 0; i < n; i++)
    {
      int mask = 1<<i;
      if(bit&mask)s_size++;
    }
    vector<pair<int,int> > inv_s;
    int now = s_size;
    for (int i = 0; i < n; i++)
    {
      int mask = 1<<i;
      if((bit&mask) == 0){
        inv_s.emplace_back(i,now);
        now++;
      }
    }
    for (int last = 0; last < 51; last++)
    {
      for (auto &&v : inv_s)
      {
        int i = v.first;
        int now = v.second;
        int i_val;
        if(abs(i - s_size)%2 == 0){
          i_val = a[i];
        }
        else
        {
          i_val = b[i];
        }
        if(i_val >= last)
        {
          chmin(dp[bit|(1<<i)][i_val],dp[bit][last] + abs(now - s_size));
        }

      }

    }


  }

  int res  = INF;
  for (int i = 0; i < 55; i++)
  {
    chmin(res,dp[(1<<n)-1][i]);
  }
  if(res == INF)
  {
    cout<<-1<<endl;
  }  
  else
  {
    cout<<res<<endl;
  }
  return;

  return;
}

