    vector<vector<int>> v(2, vector<int>());
    for(int i=0;i<2;++i){
        for(int j=0;j<n;++j){
            int tmp;
            cin >> tmp;
            v[i].push_back(tmp);
        }
    }

    int ans = INF;
    for(int i=0;i<(1<<n);++i){
        vector<int> c;
        for(int j=0;j<n;++j){
            c.push_back(v[(i>>j)&1][j]);
        }
        sort(c.begin(), c.end());

        vector<int> indices;
        deque<bool> used(n);
        for(int j=0;j<n;++j){
            for(int k=0;k<n;++k){
                if(used[k])continue;
                int d = (i>>j)&1;
                if(abs(j-k)%2 == d && c[j] == v[d][k]){
                    indices.push_back(k);
                    used[k] = true;
                }
            }
        }

        if(indices.size() != n)continue;

        int inversion = 0;
        for(int j=0;j<n;++j){
            for(int k=j+1;k<n;++k){
                if(indices[j] > indices[k])inversion++;
            }
        }

        ans = min(ans, inversion);
    }

    cout << (ans != INF ? ans : -1) << endl;

    return 0;
}

