i64 solve(const vi& A, const vi &B, i64 N, i64 A_prev) {
  i64 i, j;
  i64 ans = -1;
  /*
  cout << N << " " << A_prev << endl;
  */
  if(N == 0) {
    return 0;
  }
  /*
  cout << "A ";
  REP(0, N, i) {
    cout << A[i] << " ";
  }
  cout << endl;
  cout << "B ";
  REP(0, N, i) {
    cout << B[i] << " ";
  }
  cout << endl;
  */
  vi A_next(N-1), B_next(N-1);
  REP(0, N-1, j) {
    A_next[j] = A[j+1];
    B_next[j] = B[j+1];
  }
  REP(0, N, i) {
    if(ans != -1 && ans < i) {
      break;
    }
    i64 A_cur = (i % 2 == 0 ? A[i] : B[i]);
    if(A_cur >= A_prev) {
      if(i != 0) {
	A_next[i-1] = B[i-1];
	B_next[i-1] = A[i-1];
      }
      i64 candidate = solve(A_next, B_next, N-1, A_cur);
      if(candidate != -1) {
	if(ans != -1)
	  ans = min(ans, candidate + i);
	else
	  ans = candidate + i;
      }
    }
  }
  return ans;
}

