        bool visOK = true;
        for (int i = 1; i < N; i++) {
            // v[i]はシャッフルされる前のカード番号
            // i はシャッフルされた後のカード番号
            bool isXomote = abs(v[i - 1] - (i - 1)) % 2 == 0;
            bool isYomote = abs(v[i] - i) % 2 == 0;
            int X         = isXomote ? A[v[i - 1]] : B[v[i - 1]];
            int Y         = isYomote ? A[v[i]] : B[v[i]];
            if (Y - X >= 0) {
                continue;
            } else {
                visOK = false;
            }
        }

        if (visOK) {
            int count = 0;
            BIT b(N);
            rep(i, N) {
                count += i - b.sum(v[i]);
                b.add(v[i], 1);
            }
            ans = min(ans, count);
        }
    } while (next_permutation(v.begin(), v.end()));

    if (ans == 1e9)
        cout << -1 << endl;
    else
        cout << ans << endl;
}

