    for(i=0; i<n; i++) {
        scanf("%d", &a[i]);
    }
    for(i=0; i<n; i++) {
        scanf("%d", &b[i]);
    }

    ll ans=LINF;
    int m=(n+1)/2;
    int k;
    for(k=0; k<((ll)1<<n); k++) {
        int cnt=0;
        for(i=0; i<n; i++) {
            if(k & ((ll)1<<i)) cnt++;
        }
        if(cnt!=m) continue;

        vector<pair<int,int> > v0, v1;    // v0: 0,2,4,..番目に移動したものの値と元indexのペア
                                          // v1: 1,3,5,..番目に移動したものの値と元indexのペア
        vector<pair<int,int> > v(n);      // v : 移動先の配列の、値と元indexのペア

        for(i=0; i<n; i++) {
            if(k & ((ll)1<<i)) {
                v0.push_back(make_pair((i%2==0? a[i]: b[i]),i));
            }
            else {
                v1.push_back(make_pair((i%2==0? b[i]: a[i]),i));
            }
        }
        sort(v0.begin(),v0.end());
        sort(v1.begin(),v1.end());

        for(i=0; i<m; i++) {
            v[i*2]=v0[i];
        }
        for(i=0; i<n-m; i++) {
            v[i*2+1]=v1[i];
        }
