	idx++;
	if(idx == n+1)return 0;
	int&ans = dp[mask][last];
	//if(ans!=-1)return ans;
	if(visited[mask][last])return ans;
	visited[mask][last] = 1;
	ans = 1e10;
	int a = A[last] , b = B[last];
	if(f)swap(a,b);
	vi C;

	forn(i,0,n-1)if(mask&(1LL<<i))C.pb(i);
	forn(i,0,n-1)
	{
		if((mask&(1LL<<i)) == 0)
		{
			int x = A[i] , y = B[i];
			f = 0;
			if((idx-i)%2)f = 1;
			if(f)swap(x,y);
			if(x>=a)
			{
				int cost = 0;
				for(auto j : C)
				{
					if(j>i)
					{
					cost++;
					}

				}
				ans = min(ans,get(mask|(1LL<<i),i)+cost);
			} 
		}
	}
	return ans;


}


