int N, A[MAXN], B[MAXN], dp[1<<MAXN][51];

int f(int mask, int prev) {
    if (mask == (1<<N)-1) return 0;
    int &ret = dp[mask][prev];
    if (ret == -1) {
        ret = INF;
        int pos = __builtin_popcount(mask);
        int greaterMask = (1<<N)-1;
        for (int i = 0; i < N; i++) {
            greaterMask ^= (1<<i);
            if (mask&(1<<i)) continue;
            int diff = abs(pos - i);
            int val = diff&1 ? B[i] : A[i];
            int swap = abs(pos - (i + __builtin_popcount(mask&greaterMask)));
            if (val >= prev) ret = min(ret, f(mask|(1<<i), val) + swap);
        }
    }
    return ret;
}

