int get(deque<int> &V1) {
    int ans = 0;
    int N = (int)V1.size();
    for (int i = 0; i < N; i++) {
        int cur = 0;
        while (V1[cur] != i)
            cur++;
        ans += cur;
        for (int j = cur; j > 0; j--)
            swap(V1[j], V1[j - 1]);
        V1.pop_front();
    }
    return ans;
}

int solve() {
    vector<int> nV;
    int N = (int)V.size();
    for (int i = 0; i <= 50; i++) {
        opos[i].clear();
        epos[i].clear();
    }
    for (int i = 0; i < N; i++) {
        int tmp = V[i].first;
        if (flip[i]) tmp = V[i].second;
        nV.push_back(tmp);
    }
    sort(nV.begin(), nV.end());
    for (int i = 0; i < N; i++) {
        int cur = nV[i];
        if (i % 2) opos[cur].push_back(i);
        else epos[cur].push_back(i);
    }
    deque<int> idx;
    for (int i = 0; i < N; i++) {
        int take = (i % 2) ^ flip[i];
        int cur = V[i].first;
        if (flip[i]) cur = V[i].second;
        if (take) {
            if (opos[cur].empty()) return -1;
            idx.push_back(opos[cur].front());
            opos[cur].pop_front();
        } else {
            if (epos[cur].empty()) return -1;
            idx.push_back(epos[cur].front());
            epos[cur].pop_front();
        }
    }
    return get(idx);
}

