    REP(bit, 1 << N) {
        REP(i, 55) { dp[bit][i] = INF; }
    }
    dp[0][0] = 0;

    REP(bit, 1 << N) {
        int S_size = 0;
        REP(i, N) {
            int mask = 1 << i;
            if (bit & mask) {
                S_size++;
            }
        }

        vector<pair<int, int>> invS; // first:もともと何番目か、second:カードの現在地
        int now = S_size;
        REP(i, N) {
            int mask = 1 << i;
            if ((bit & mask) == 0) {
                invS.emplace_back(i, now);
                now++;
            }
        }
        // cout << "bit:" << bit << endl;
        REP(last, 51) {
            for (auto v : invS) {
                int i = v.first;
                int now = v.second;
                int i_val;
                if (abs(i - S_size) % 2 == 0) {
                    i_val = A[i];
                } else {
                    i_val = B[i];
                }
                if (i_val >= last) {
                    /*debug
                    if (dp[bit | (1 << i)][i_val] > dp[bit][last] + abs(now - S_size)) {
                        cout << "min last:" << last << " i:" << i << " now:" << now << " i_val:" << i_val
                             << " abs(now - S_size):" << abs(now - S_size) << endl;
                    } else {
                        cout << "no last:" << last << " i:" << i << " now:" << now << " i_val:" << i_val << endl;
                    }*/
                    chmin(dp[bit | (1 << i)][i_val], dp[bit][last] + abs(now - S_size));
                }
            }
        }
    }

    /*
    REP(i, 1 << N) { cout << i << "  "; }
    cout << endl;
    REP(j, 51) {
        REP(i, 1 << N) { cout << dp[i][j] << "  "; }
        cout << endl;
    }
    */

    int ans = INF;
    REP(i, 55) { chmin(ans, dp[(1 << N) - 1][i]); }

    if (ans == INF) {
        cout << -1 << endl;
    } else {
        cout << ans << endl;
    }
    return 0;
}

