int INF = 1e+9;
int n;
int a[18];
int b[18];
int dp[1 << 18][18];

int main() {
	int i, j, k;

	cin >> n;
	rep(i, n) cin >> a[i];
	rep(i, n) cin >> b[i];

	rep(i, (1 << n)) rep(j, n) dp[i][j] = INF;

	rep(i, n) {
		dp[1 << i][i] = 0;
	}

	rep(i, (1 << n) - 1) {
		int bcnt = 0;
		rep(j, n) if ((i >> j) % 2) bcnt++;

		rep(j, n) {
			if (dp[i][j] >= INF) continue;

			int last;
			if (bcnt % 2 != j % 2) { last = a[j]; }
			else { last = b[j]; }

			rep(k, n) {
				if ((i >> k) % 2) { continue; }

				int now;
				if ((bcnt + 1) % 2 != k % 2) { now = a[k]; }
				else { now = b[k]; }
				if (last > now) continue;

				int cst = 0;
				int l;
				for (l = k + 1; l < n; l++) if ((i >> l) & 1) cst++;

				chmin(dp[i + (1 << k)][k], dp[i][j] + cst);
			}
		}
	}

	int ans = INF;
	rep(j, n) {
		chmin(ans, dp[(1 << n) - 1][j]);
	}
	if (ans >= INF) cout << -1 << endl;
	else cout << ans << endl;
	return 0;
}

