			if (((i>>j) & 1) == 0) {
				buf.emplace_back(Pll(A[j],0));
			} else {
				buf.emplace_back(Pll(B[j],1));
			}
		}

		rep(c,0,N+1) {
		rep(j,0,N-1) {
			if (buf[j].F > buf[j+1].F) {
				swap(buf[j],buf[j+1]);
				buf[j].S = 1-buf[j].S;
				buf[j+1].S = 1-buf[j+1].S;
				cnt++;
			}
		}
		}
		rep(f,0,N+1) {
		rep(c,0,N+1) {
		rep(j,0,N-1) {
			if (buf[j].S == 1) {
				SINT64 k = j+1;
				if (buf[j].F == buf[k].F) {
					if (buf[j].S == buf[k].S) {
						buf[j].S = 0;
						buf[k].S = 0;
						cnt += k-j;
					} else {
						if (k != N-1) {
							SINT64 kk = k+1;
							if (buf[j].F == buf[kk].F) {
								buf[j].S = 0;
								buf[k].S = 1-buf[k].S;
								buf[kk].S = 1-buf[kk].S;
								cnt += 2;

							}
						}

					}
				} else {

				}		
			}
		}
		}
		}
		SINT64 ok = 0;
		rep(j,0,N) {
			if (buf[j].S == 1) {
				ok = 1;
			}
		}

		if(ok == 0) {
		ans = MIN(ans,cnt);
		}

	}

	if (ans == INF64) {
		ans = -1;
	}

	put(ans);
	return 0;
}


