vi used, red, blue, perm;
int ans = -1, n;

bool valid(int i, int idx){
    if (idx == 0) return true;

    int next;
    if ((i%2) == (idx%2)) next = red[i];
    else next = blue[i];

    int last;
    if ((idx-1)%2 == (perm[idx-1]%2)) last = red[perm[idx-1]];
    else last = blue[perm[idx-1]];

    return next >= last;
}

bool cheap(int idx){
    int temp = 0;
    for (int k = 0; k < idx; k++) {
        for (int l = k + 1; l < idx; l++) {
            if (perm[k] > perm[l])temp++;
        }
    }
    return temp < ans or ans == -1;
}

int cost(){
    int temp = 0;
    for (int k = 0; k < n; k++) {
        for (int l = k + 1; l < n; l++) {
            if (perm[k] > perm[l])temp++;
        }
    }
    return temp;
}

// k: inversiones que se llevan
void solve(int idx, int k){
    if (idx == n) {
        //assert(cost() == k);
        if (ans != -1) ans = min(ans, k);
        else ans = k;
    } else if (k < ans or ans == -1){
        int iv = 0;
        for (int i = 0; i < n; i++) {
            if (not used[i]) {
                if (valid(i, idx)) {
                    used[i] = true;
                    perm[idx] = i;
                    solve(idx+1, k + iv);
                    used[i] = false;
                }
                iv++;
            }
        }
    }
}

