#include <bits/stdc++.h>

///////////////////////////
// Range Sum Query (BIT) //
///////////////////////////

class RSumQBIT {
private:
	std::vector<int64_t> container_;

	int64_t getHelper(const int index) const
	{
		if (index < 0) return 0;
		if ((int)(container_.size()) <= index) return container_.back();
		int64_t sum{};
		for (int add_place{index}; add_place > 0; add_place -= add_place & -add_place)
			sum += container_[add_place];
		return sum;
	}

public:
	RSumQBIT(const int array_size)
		: container_(array_size + 1) {}
	// indexは0-indexed
	void update(const int index, const int64_t added)
	{
		for (int update_place{index + 1}; update_place < (int)(container_.size()); update_place += update_place & -update_place)
			container_[update_place] += added;
	}
	// left,rightは0-indexed、[left, right)の半開区間
	int64_t get(const int left, const int right) const
	{
		return -getHelper(left) + getHelper(right);
	}
};

int main()
{
	int N;
	scanf("%d", &N);
	std::vector<std::vector<int>> ab(N, std::vector<int>(2));
	for (auto& e: ab)
		scanf("%d", &e[0]);
	for (auto& e: ab)
		scanf("%d", &e[1]);
	int limit{1 << N};
	int min{1 << 30};
	for (int set{}; set < limit; set++)
	{
		std::vector<int> sequence(N);
		for (int i{}; i < N; i++)
			sequence[i] = ab[i][set >> i & 1];
		int count{};
		RSumQBIT bitLeft(51);
		std::vector<int> indices(N);
		std::vector<std::vector<int>> odd(51);
		for (int i{}; i < N; i++)
		{
			int64_t tmp{bitLeft.get(sequence[i] + 1, 51)};
			indices[i] = odd[sequence[i]].size();
			odd[sequence[i]].push_back(tmp);
			count += tmp;
			bitLeft.update(sequence[i], 1);
		}
		RSumQBIT bitRight(51);
		for (int i{N - 1}; i >= 0; i--)
		{
			int64_t tmp{bitRight.get(0, sequence[i])};
			odd[sequence[i]][indices[i]] = (odd[sequence[i]][indices[i]] + tmp) % 2 != (set >> i & 1);
			bitRight.update(sequence[i], 1);
		}
		for (auto& e: odd)
		{
			int odd_count{};
			for (auto&& f: e)
				if (f)
					odd_count++;
			if (odd_count % 2 == 1)
			{
				count = 100'000;
				break;
			}
			while (!e.empty())
			{
				if (e.back())
				{
					e[e.size() - 1] = !e[e.size() - 1];
					e[e.size() - 2] = !e[e.size() - 2];
					count++;
				}
				e.pop_back();
			}
		}
		min = std::min(min, count);
	}
	if (min < 100'000)
		printf("%d\n", min);
	else puts("-1");

	return 0;
}

