bool is(int mask, int i)
{
        if (mask & (1 << i))
                return 1;
        else
                return 0;
}

void compute()
{
        /// primele size(mask) le punem mask
        for (int mask = 0; mask < (1 << n) - 1; mask++)
        {
                int p = 0;
                for (int i = 0; i < n; i++)
                        if (is(mask, i))
                                p++;
                for (int i = 0; i < n; i++)
                        if (!is(mask, i))
                        {
                                int dist = abs(i - p), nval;
                                if (dist % 2 == 0)
                                        nval = a[i];
                                else
                                        nval = b[i];
                                for (int cur = 1; cur <= nval; cur++)
                                        dp[mask + (1 << i)][nval] = min(dp[mask + (1 << i)][nval], dist + dp[mask][cur]);
                        }
        }
}

