LL ans = -1;

struct BIT{
	LL tr[50005];
	LL lowbit(LL x){ return (x & (-(x))); }
	void modify(LL x,LL v){ for(;x <= 100;x += lowbit(x)) tr[x] += v; }
	LL query(LL x){ LL ret = 0; for(;x;x -= lowbit(x)) ret += tr[x]; return ret; }
}s;

int main(){
	ios::sync_with_stdio(false);
	memset(s.tr,0,sizeof(s.tr));
	cin >> n;
	for(LL i = 1;i <= n;i ++) cin >> a[i];
	for(LL i = 1;i <= n;i ++) cin >> b[i];

	for(LL i = 0;i < (1LL << n);i ++){
		memset(cnt,0,sizeof(cnt));
		for(LL j = 0;j < n;j ++){
			if((i >> j) & 1){ lis[j + 1] = b[j + 1]; chg[j + 1] = 1; }
			else{ lis[j + 1] = a[j + 1]; chg[j + 1] = 0; }
		}
		for(LL j = 1;j <= n;j += 2) cnt[lis[j]] ++;
		for(LL j = 1;j <= n;j ++) tmp[j] = lis[j];
		sort(lis + 1,lis + 1 + n);
		for(LL j = 1;j <= n;j += 2) cnt[lis[j]] --;
