			s.modify(tmp[j],1);
			cc += (j - s.query(tmp[j]));
		}
		for(LL j = 1;j <= n;j ++) s.modify(tmp[j],-1);
		if(ans == -1) ans = cc;
		ans = min(ans,cc);
	}
	cout << ans << endl;
	return 0;
}

