int S(int x){int ret=0;while(x){ret++;x^=lowbit(x);}return ret;}
void change(int x,int y)
{
	if(x>y)swap(x,y);
	for(int i=x;i<y;i++){swap(b[i][0],b[i+1][0]);swap(b[i][1],b[i+1][1]);sum++;swap(wh[i],wh[i+1]);}
}
int solve()
{
	sort(p+1,p+tot+1);sum=0;int resum=1e9+10,Qflag=0;
	for(int i=0;i<n;i++)wh[i]=i;
	for(int i=0;i<n;i++)b[i][0]=a[i][0],b[i][1]=a[i][1];
	for(int i=tot;i;i--)change(wh[p[i].id],pos[i]);resum=sum;
	int flag=1;
	for(int now=0,i=1;i<n;i++,now^=1)
		if(b[i][now]<b[i-1][now^1])flag=0;
	Qflag|=flag;
	for(int i=0;i<n;i++)wh[i]=i;sum=0;
	for(int i=0;i<n;i++)b[i][0]=a[i][0],b[i][1]=a[i][1];
	for(int i=1;i<=tot;i++)change(wh[p[i].id],pos[i]);
	resum=min(resum,sum);flag=1;
	for(int now=0,i=1;i<n;i++,now^=1)
		if(b[i][now]<b[i-1][now^1])flag=0;
	Qflag|=flag;
	if(!Qflag)return 1e9+10;
	return resum;
}
