#define MAX 20

using namespace std;
typedef long long ll;

class Solution {
  static int arrange(vector<int> &source, vector<int> &target) {
    if (source.empty()) return 0;
    sort(source.begin(), source.end());
    sort(target.begin(), target.end());
    int ans = 0;
    for (int i = 0; i < source.size(); ++i) ans += abs(source[i] - target[i]);
    return ans;
  }

 public:
  static void solve() {
    int n;
    cin >> n;
    int a[2][MAX]{};
    for (int i = 0; i < n; ++i) cin >> a[0][i];
    for (int i = 0; i < n; ++i) cin >> a[1][i];
    int ans = INT_MAX;
    for (int i = 0; i < (1 << n); ++i) {
      bitset<20> bs(i);
      // if (bs.count() % 2 != 0) continue;
      vector<pair<int, int>> x;
      x.reserve(n + 1);
      for (int j = 0; j < n; ++j) {
        x.emplace_back(a[bs[j]][j], j);
      }
      sort(x.begin(), x.end());
      x.emplace_back(1000, 1000);  // end symbol

      bool ok = true;
      int dist = 0;

      // Treat equal elements
      int curr = -1, cnt = 0;
      for (int j = 0; j <= n; ++j) {
        if (x[j].first != curr) {
          if (cnt >= 1) {
            // Assign elements in [j - cnt, j - 1]
            vector<int> odd, even, pose, poso;
            for (int k = j - cnt; k <= j - 1; ++k) {
              int parity = x[k].second + bs[x[k].second];
              if (parity % 2 == 0)
                even.emplace_back(x[k].second);
              else
                odd.emplace_back(x[k].second);

              if (k % 2 == 0)
                pose.emplace_back(k);
              else
                poso.emplace_back(k);
            }

            int ne = pose.size();
            int no = cnt - ne;
            if (odd.size() != no || even.size() != ne) {
              ok = false;
              break;
            }

            int mine = arrange(even, pose);
            int mino = arrange(odd, poso);
            dist += mine + mino;
          }

          curr = x[j].first;
          cnt = 1;
        } else {
          cnt++;
        }
      }

      if (dist % 2 != 0) {
        ok = false;
      }

      if (ok && dist / 2 < ans) {
        ans = dist / 2;
      }
    }

    cout << (ans == INT_MAX ? -1 : ans);
  }
};

int main() { Solution::solve(); }

