    for(int i = 0; i < n; ++i) {
        cin >> cards[i].first;
    }
    for(int i = 0; i < n; ++i) {
        cin >> cards[i].second;
    }

    int ans = -1;
    for(int mask = 0; mask < (1<<n); ++mask) {
        int bits = __builtin_popcount(mask);

        vector<pair<int, int>> v(n);

        int mv = 0, st = bits;
        for(int i = 0; i < n; ++i) {
            if(mask & 1LL<<i) {
                if((i-mv)%2) {
                    v[mv] = {cards[i].second, i};
                } else {
                    v[mv] = {cards[i].first, i};
                }
                mv++;
            } else {
                if((i-st)%2) {
                    v[st] = {cards[i].second, i};
                } else {
                    v[st] = {cards[i].first, i};
                }
                st++;
            }
        }

        if(!in_order(v)) continue;

        int cand = 0;
        for(int i = 0; i < n; ++i) {
            for(int j = i+1; j < n; ++j) {
                if(v[i].second > v[j].second) {
                    cand++;
                }
            }
        }
        if(ans == -1 || cand < ans) {
            ans = cand;
        }
    }

    cout << ans << endl;

    return 0;
}

