int dp(int id, int mask, int last){
	if(mask == (1<<n)-1) return 0;
	int &ret = memo[mask][last];
	if(ret!=-1) return ret;
	ret = INF;
	for(int i=0;i<n;i++){
		if(cek_bit(i,mask)) continue;
		int pake = -1;
		if(abs(i-id)&1){
			pake = li[1][i];
		} else {
			pake = li[0][i];
		}
		if(pake >= last){
			int co = 0;
			for(int j=0;j<i;j++){
				if(!cek_bit(j,mask)) co++;
			}
//			for(int j=0;j<n;j++) cout << (cek_bit(j,mask) ? 1 : 0);
//			cout << " >> " << i << " ke " << id << " cost " << co << " dengan " << pake << endl;
			ret = min(ret,dp(id+1,tog_bit(i,mask),pake) + co);
		}
	}
	return ret;
}


