int first_fixed_size_subset(int n, int k) { return (1 << k) - 1; }

int next_fixed_size_subset(int n, int k, int& s) {
  int x = s & -s, y = s + x;
  s = (((s & ~y) / x) >> 1) | y;
  if (s >= (1 << n)) return 0;
  return s;
}
template <typename T>
class BinaryIndexedTree {
  int N;
  vector<T> bit;

 public:
  BinaryIndexedTree(int N) : N(N) { bit.resize(N, 0); };

  T sum(int i) {
    T s = 0;
    while (i > 0) {
      s += bit[i];
      i -= i & -i;
    }
    return s;
  }

  void add(int i, T x) {
    while (i <= N) {
      bit[i] += x;
      i += i & -i;
    }
  }
};

struct Card {
  int R, B;
};

int main() {
  int N;
  cin >> N;

  vector<Card> C(N);
  rep(i, N) {
    if (i % 2 == 0) {
      cin >> C[i].R;
    } else {
      cin >> C[i].B;
    }
  }
  rep(i, N) {
    if (i % 2 == 0) {
      cin >> C[i].B;
    } else {
      cin >> C[i].R;
    }
  }

  int nRed = (N + 1) / 2;
  int red = first_fixed_size_subset(N, nRed);

  int ans = 1e9;

  do {
    int cost = 0;
    BinaryIndexedTree<int> bit(51);

    vector<Card> reds, blues;
    rep(i, N) {
      if ((red >> i) & 1) {
        reds.push_back(C[i]);
        cost += i - bit.sum(C[i].R);
        bit.add(C[i].R, 1);
      } else {
        blues.push_back(C[i]);
        cost += i - bit.sum(C[i].B);
        bit.add(C[i].B, 1);
      }
    }

    sort(all(reds), [&](const Card& a, const Card& b) { return a.R < b.R; });

    sort(all(blues), [&](const Card& a, const Card& b) { return a.B < b.B; });

    rep(i, N / 2) {
      if (reds[i].R > blues[i].B) goto hoge;
      if (i + 1 < nRed && blues[i].B > reds[i + 1].R) goto hoge;
    }

    ans = min(ans, cost);
  hoge:;
  } while (next_fixed_size_subset(N, nRed, red));

  cout << (ans == 1e9 ? -1 : ans) << endl;

  return 0;
}

