#include <bits/stdc++.h>
using namespace std;
using ll = long long;
ll N;
vector<long long> A,B;
int mass[20];
int ans = 1e9;

int calc(){
    for(int i = 0;i < N;i++){
       // cout<<mass[i]<<" ";
    }
  //  cout<<endl;
    int odd = 0, even = 0;
    vector<int> v,v1,v2;
    for(int i = 0;i < N;i++){
        if(i % 2 == 0){
            if(mass[i]){
                odd++;
                v1.push_back(A[i]);
            }else{
                even++;
                v2.push_back(B[i]);
            }
        }else{
            if(mass[i]){
                even++;
                v2.push_back(A[i]);
            }else{
                odd++;
                v1.push_back(B[i]);
            }
        }    
        if(mass[i]){
            v.push_back(A[i]);
        }else{
            v.push_back(B[i]);
        }
    }

    if(even != N / 2)return 1e9;
    if(odd != N / 2 + N%2)return 1e9;

    sort(v1.begin(), v1.end());
    sort(v2.begin(), v2.end());
    vector<int> w;
    for(int i = 0;i < N;i++){
        if(i%2 == 0){
            w.push_back(v1[i/2]);
        }else{
            w.push_back(v2[i/2]);
        }
    }
    vector<int> ww = v;
    sort(v.begin(), v.end());
    if(v != w){
        return 1e9;
    }
    int cnt = 0;
    for(int i = N-1;i >= 0;i--){
        for(int j = 0;j < i;j++){
            if(ww[j] > ww[i])cnt++;
        }
    }
    //cout<<cnt<<endl;
    return cnt;
}

int zrk(int i){
    if(N == i){
        ans = min(ans, calc());
        return 0;
    }
    mass[i] = 0;zrk(i+1);
    mass[i] = 1;zrk(i+1);
}

void solve(long long _N, std::vector<long long> _A, std::vector<long long> _B){
    N = _N;
    A = _A;
    B = _B;
    zrk(0);
    if(ans == 1e9){
        cout<<-1<<endl;
        return;
    }
    cout<<ans<<endl;
}

int main(){
    long long N;
    scanf("%lld",&N);
    std::vector<long long> A(N);
    for(int i = 0 ; i < N ; i++){
        scanf("%lld",&A[i]);
    }
    std::vector<long long> B(N);
    for(int i = 0 ; i < N ; i++){
        scanf("%lld",&B[i]);
    }
    solve(N, std::move(A), std::move(B));
    return 0;
}

