const int MOD = ten(9) + 7;

int dp[1 << 18][18];

int f(const vector<Pii>& a, int movedIdx, int originalIdx) {
	return (movedIdx - originalIdx) % 2 == 0 ? a[originalIdx].first : a[originalIdx].second;
}

int solve(vector<Pii> a) {
	memset(dp, -1, sizeof(dp));
	const int n = sz(a);
	FOR(i, n) {
		dp[1 << i][i] = i;
	}
	FOR(F, 1 << n) {
		FOR(i, n) {
			if (dp[F][i] == -1) continue;
			int bitCnt = 0;
			FOR(j, n) if (F & (1 << j)) bitCnt++;
			FOR(j, n) {
				if (F & (1 << j)) continue;
				const int lastVal = f(a, bitCnt - 1, i);
				const int nextVal = f(a, bitCnt , j);
				if (lastVal > nextVal) continue;
				int nF = F | (1 << j);
				if (dp[nF][j] == -1) dp[nF][j] = ten(9);
				chmin(dp[nF][j], dp[F][i] + abs(j - bitCnt));
			}
		}
	}

	int ans = -1;
	FOR(i, n) {
		int cur = dp[(1 << n) - 1][i];
		if (cur == -1) continue;
		if (ans == -1) ans = cur;
		else ans = min(ans, cur);
	}
	if (ans == -1) return ans; 
	else return ans / 2;
}

int main() {
	int n; reader(n);
	vector<Pii> vp(n);
	FOR(i, n) reader(vp[i].first);
	FOR(i, n) reader(vp[i].second);

	int ans = solve(vp);
	writerLn(ans);
	return 0;
}

