using namespace std;
int N,AB[18][2];
int dp[1<<18][51];
//dp[msk][lst] := 既に整列済みの集合がmskで、最後の値がlstであるときの操作の最小値

// 参考にしたサイト: https://www.hamayanhamayan.com/entry/2020/01/18/233933

int main(void){
    cin.tie(0);
    ios::sync_with_stdio(false);
    cout<<fixed<<setprecision(20);

    cin >> N;
    rep(i,N)cin >> AB[i][0]; // i番目のカードの表がAB[i][0];
    rep(i,N)cin >> AB[i][1]; // i番目のカードの裏がAB[i][1];

    for(int mask = 0;mask< (1<<N) ;mask++){
        for(int list = 0;list<51;list++)dp[mask][list] = inf; // inf で初期化することで不可能な遷移を防げる
    }
    dp[0][0] = 0;// 0枚で最後の値を0にするのに必要な操作回数は0
    for(int mask = 0;mask < (1<<N);mask++){
        for(int list = 0;list <51;list++){
            // maskの置き方をすでにしており
            // 最後においた数値がlistのときについて考える

            if(dp[mask][list]==inf)continue;
            int done = 0;//すでに置かれているカードの枚数

            for(int i=0;i<N;i++)if(mask&(1<<i))done++; // maskのiビット目が1だったらカードが置かれている

            for(int i=0;i<N;i++){ // i番目のカードを集合maskの末尾に追加することを考える
                if(mask&(1<<N))continue; //既に集合に追加されていたら遷移を考えない

                int p = abs(done-i)%2; // 現在位置からカードの末尾までの移動距離が abs(done-i) で
                // p は表か裏かを決める　偶数枚置かれていて iが偶数のときは p は0で表面を使う
                // 奇数枚置かれていて iが偶数だったら p は 1で裏面を使う
                if(AB[i][p]<list)continue; // もしも新しく追加する数が末尾の数よりも小さかったら追加できない

                int c = 0; // これは多分操作回数なんだけど
                for(int j=0;j<i;j++)if(!(mask& (1<<j)))c++; // ここの操作よくわからない たすけて

                dp[mask|(1<<i)][AB[i][p]] = min(dp[mask|(1<<i)][AB[i][p]],dp[mask][list]+c);
            }
        }
    }
    int ans = inf;
    for(int i=0;i<51;i++)ans = min(ans,dp[(1<<N)-1][i]);
    if(ans==inf)ans = -1;
    cout << ans << endl;
}

