bool ok(auto& a)
{
    int n=a.size();
    for(int i=1; i<n; ++i)
        if (a[i].first<a[i-1].first) return false;
    return true;
}

void ope(auto& a, int i)
{
    swap(a[i], a[i+1]);
    swap(a[i].first, a[i].second);
    swap(a[i+1].first, a[i+1].second);
}

