int next(int a){
  int b = a + (a & -a);
  int x = __builtin_popcount(a ^ b) - 2;
  return b ^ ((1<<x)-1);
}

unsigned inversion(std::vector<int> &A){
  std::vector<std::pair<int, int> > B;
  for(int i = 0; i < A.size(); i++) B.emplace_back(std::pair<int, int>({A[i], i}));
  std::sort(B.begin(), B.end(), [](auto x, auto y){ return x.first < y.first; });
  int ans = 0;
  for(int i = 0; i < B.size(); i++) ans += std::max(0, i - B[i].second);
  return ans;
}

