				y = (p[j] % 100) - (2 * j);
				if (y < 0)y *= -1;
				x += y;
			}
			for (int j = 0; j < qn; j++) {
				y = (q[j] % 100) - (2 * j + 1);
				if (y < 0)y *= -1;
				x += y;
			}
			g = 1;
			for (int i = 0; i < pn - (n % 2); i++) {
				if ((p[i] / 100) > (q[i] / 100))g = 0;
			}
			for (int i = 0; i < qn - ((n+1) % 2); i++) {
				if ((q[i] / 100) > (p[i + 1] / 100))g = 0;
			}
			if (g && ans > (x / 2))ans = x / 2;
		}
	}
	if (ans == 1000000000)printf("-1\n");
	else printf("%d\n", ans);
}

