int getVal(int prv, int mask)
{
	int t = __builtin_popcount(mask);
	t--;
	t = abs(t - prv);
	if(t%2)
		return b[prv];
	else
		return a[prv];
}
int solve(int x,int mask)
{
	if(mask+1 == (1<<n))
		return 0;
	if(dp[x][mask] != -1)
		return dp[x][mask];
	dp[x][mask] = 1e9;
	int z = getVal(x,mask);
	for(int j=0;j<n;j++)
	{
		if((mask&(1<<j))==0)
		{
			int newMask = (mask|(1<<j));
			int y = getVal(j,newMask);
			int t = __builtin_popcount(mask);
			t = abs(t-j);
			if(y>=z)
				dp[x][mask] = min(dp[x][mask], t+solve(j,newMask));
		}
	}
	return dp[x][mask];
}
