int a[20],b[20];
int f[(1<<18)+5][20],cnt[(1<<18)+5];
int n;
int main()
{
	n=read();
	for(int i=0;i<n;i++)
		a[i]=read();
	for(int i=0;i<n;i++)
		b[i]=read();
	memset(f,0x3f,sizeof(f));
	cnt[0]=0;
	for(int S=1;S<1<<n;S++){
		cnt[S]=cnt[S>>1]+(S&1);
		if(cnt[S]==1){
			for(int i=0;i<n;i++)
				if(S&(1<<i))f[S][i]=0;
			continue;
		}
		for(int i=0;i<n;i++)
			if(S&(1<<i)){
				int val=0;
				for(int j=0;j<n;j++)
					if(S&(1<<j))val+=(j>i);
				int cur=(((cnt[S]-1)-i)&1)?b[i]:a[i];
				for(int j=0;j<n;j++)
					if((i!=j)&&(S&(1<<j))){
						int last=(((cnt[S]-2)-j)&1)?b[j]:a[j];
						if(cur>=last)f[S][i]=std::min(f[S][i],f[S^(1<<i)][j]+val);
					}
			}
	}
	int ans=inf;
	for(int i=0;i<n;i++)
		ans=std::min(ans,f[(1<<n)-1][i]);
