//反転数を求める
int inverse_number(vector<int> z){
	int cnt = 0;

	int n = z.size();
	rep(i,n){
		repr(j,n-1,i+1){
			if(z[j] < z[j-1]){
				cnt++;
				int tmp = z[j];
				z[j] = z[j-1];
				z[j-1] = tmp;
			}
		}
	}

	return cnt;
}

