    for(int j=0;j<n;++j) {
      if((abs(j-tmp[j].second)%2) ^ ((i>>tmp[j].second)&1)) {
        ok = false;
        break;
      }
    }
    if(!ok) continue;
    int cost = 0;
    BIT<int> bit(n+1);
    for(int j=n-1;j>=0;--j) {
      cost += bit.sum(tmp[j].second);
      bit.add(tmp[j].second, 1);
    }
    mi = min(mi, cost);
  }
  cout << (mi == INF ? -1 : mi) << endl;
}

