struct Card {
  int i, A, B;
  int val(int j) { return i - j % 2 == 0 ? A : B; }
};

int main() {
  int N;
  cin >> N;

  vector<Card> C(N);
  rep(i, N) C[i].i = i;
  rep(i, N) cin >> C[i].A;
  rep(i, N) cin >> C[i].B;

  const int INF = 1e9;
  vector<vector<int>> dp((1 << N), vector<int>(N, INF));

  rep(i, N) dp[0][i] = 0;

  rep(s, (1 << N)) {
    int c = __builtin_popcount(s);
    rep(i, N) {
      if (s && !((s >> i) & 1)) continue;
      if (dp[s][i] == INF) continue;

      int inv = -1;
      rep(j, N) {
        if ((s >> j) & 1) continue;
        ++inv;
        if (c && C[i].val(c - 1) > C[j].val(c)) continue;

        dp[s | (1 << j)][j] = min(dp[s | (1 << j)][j], dp[s][i] + inv);
      }
    }
  }

  int ans = *min_element(all(dp[(1 << N) - 1]));
  if (ans == INF) ans = -1;

  cout << ans << endl;

  return 0;
}

