ll Solve(ll x, ll k){
    //cout<<x<<"  "<<k<<endl;
    if(!x) return 0;
    if(dp[x][k]>=0) return dp[x][k];
    vec a;
    rep(i,N) {
        if(x & (1<<i)) a.pb(i);
        else if(i==k) return dp[x][k]=INF;
    }
    ll n=a.size();
    if(n==1) return dp[x][k]=k;
    ll kari=INF;
    rep(i,n) if(a[i]!=k) {
        ll K=a[i];
        ll X=x-(1<<k);
        //cout<<A[abs(n-2-K)%2][K]<<':'<<A[abs(n-1-k)%2][k]<<';'<<K<<' '<<k<<' '<<n<<endl;
        if(A[abs(n-2-K)%2][K]<=A[abs(n-1-k)%2][k]) kari=min(kari,abs(n-1-k)+Solve(X,K));
    }
    return dp[x][k]=kari;
}

