void solve(){
	REP(i, (1 << 19)) {
		REP(q, 51) {
			dp[i][q] = 1e9;
		}
	}
	dp[0][0] = 0;
	int n;
	cin >> n;
	//右に奇数個でBになってる
	vector<pair<int, int>> inputs;
	REP(i, n) {
		int a;
		cin >> a;
		inputs.push_back(mp(a, 1));
	}
	REP(i, n) {
		cin >> inputs[i].second;
	}
	REP(i, (1 << n)-1) {
		int is_B[20] = {};
		int taken[20] = {};
		REP(q, n) {
			if (((1 << q) & i)) {
				//bit is on
				is_B[q]++;
				taken[q] = 1;
			}
		}
		for (int q = n - 2; q >= 0; --q) {
			is_B[q] += is_B[q + 1];
			is_B[q] %= 2;
		}
		int dist = 0;
		for (int j = 0; j < n; ++j) {
			if (taken[j] == false) {
				int next_go = i + (1 << j);
				int cost = dist;
				int next_value = (is_B[j] + dist) % 2;
				if (next_value == 0) {
					next_value = inputs[j].first;
				}
				else {
					next_value = inputs[j].second;
				}
				REP(q, next_value + 1) {
					dp[next_go][next_value] = min(dp[next_go][next_value], dp[i][q] + cost);
				}
				dist++;
			}
		}
	}
	ll ans = 1e9;
	REP(q, 51) {
		ans = min(ans, dp[(1 << n) - 1][q]);
	}
	if (ans == 1e9)ans = -1;
	cout << ans << endl;
}

