using namespace std;

pair <int, int> f[20];

int g[20];
int a[20];
int b[20];
int n,ans;

int getbit(int x, int i)
{
    return (x >> i) & 1;
}

void solve(int mask)
{
    vector <int> val(0);
    for (int i = 0; i < n; i++)
    {
        g[i] = getbit(mask, i);
        if (g[i]) f[i] = mp(b[i], i);
        else f[i] = mp(a[i], i);
        val.push_back(f[i].fi);
    }
    sort(val.begin(), val.end());
    int res = 0;
    for (int cur = 0; cur < n; cur++)
    {
        int x = val[cur];
        bool found = false;
        for (int i = cur; i < n; i++)
        {
            int num = f[i].fi;
            int id = f[i].se;
            if (num == x && (i - cur) % 2 == g[id])
            {
                found = true;
                for (int j = i; j - 1 >= cur; j--)
                {
                    swap(f[j], f[j - 1]);
                    g[f[j].se] ^= 1;
                    res++;
                }
                break;
            }
        }
        if (!found) return;
    }
    ans = min(ans, res);
}

int main()
{
