    for (int i = 0; i < n; i++)
    {
        cin >> a[i];
    }
    for (int i = 0; i < n; i++)
    {
        cin >> b[i];
    }
    ans = (int) 1e9;
    for (int i = 0; i < (1 << n); i++)
    {
        solve(i);
    }
    if (ans == (int) 1e9) cout << -1;
    else cout << ans;
    return 0;
}

