const int N = 18;
const int INF = (int)1e9;

int n;
ii dat[N];
int dp[N+2][(1<<N)+5];

int DP(int last, int mask) {
	if (__builtin_popcount(mask) == n) return 0;
	int& ret = dp[last][mask];
	if (ret != -1) return ret;
	int order = __builtin_popcount(mask) - 1;
	int faceup;
	if (order % 2 == last % 2) faceup = dat[last].fi;
	else faceup = dat[last].se;
	// printf("order = %d, last = %d, mask = %d, faceup = %d\n", order, last, mask, faceup);
	ret = INF;
	for (int nxt = 0; nxt < n; nxt++) {
		if (mask & (1 << nxt)) continue;
		int nxtFaceup;
		if ((order+1)%2 == nxt%2) nxtFaceup = dat[nxt].fi;
		else nxtFaceup = dat[nxt].se;
		if (nxtFaceup < faceup) continue;
		ret = min(ret, abs(order+1-nxt) + DP(nxt, mask | (1<<nxt)));
	}
	// printf("dp[%d][%d] = %d\n", last, mask, ret);
	return ret;
}

int main() {
	scanf("%d", &n);
	for (int i = 0; i < n; i++) scanf("%d", &dat[i].fi);
	for (int i = 0; i < n; i++) scanf("%d", &dat[i].se);
	reset(dp,-1);
	int ans = INF;
	for (int i = 0; i < n; i++) ans = min(ans, i + DP(i, 1<<i));
	if (ans == INF) printf("-1\n");
	else printf("%d\n", ans>>1);
	return 0;
}

