          break;
        }
      }else{
        if(cnt_flip[i] % 2 == 1){
          ok = false;
          break;
        }
      }
    }
    if(ok){
      int tmp_cnt = 0;
      for(int i = 0; i < N; i++){
          tmp_cnt += cnt_flip[i];
      }
      chmin(ans, tmp_cnt);
    }
  }

  if(ans == 1 << 30){
    cout << -1 << endl;
  }else{
    cout << ans << endl;
  }

