		debugv(c);
		debugv(p);
		int cr = crossing(c);
		debug(cr, x);
		if(cr >= x) return x;
	}

	for(int i=0; i<N; i++){
		//debug((int)p.size(), i);
		if(used[i]) continue;
		int val;
		if(i%2 == p.size()%2){
			val = a[i];
		} else {
			val = b[i];
		}

		if(p.size() > 0){
			int last_idx = p[p.size()-1]-1;
			int last_val;
			if(last_idx%2==(p.size()-1)%2){
				last_val = a[last_idx];
			} else {
				last_val = b[last_idx];
			}
			if(val < last_val) continue;
		}

		p.push_back(i+1);
		used[i] = true;
		ret = min(ret, dfs(p, used, ret, a, b));
		p.pop_back();
		used[i] = false;
	}
	return ret;
}

