	cin >> n;

	vector<int> a(n), b(n);

	for(int i = 0; i < n; i++)
		cin >> a[i];

	for(int i = 0; i < n; i++)
		cin >> b[i];

	int ans = oo;

	for(int mask = 0; mask < (1 << n); mask++){

		vector<pii> odd, even;

		for(int i = 0; i < n; i++){
			if(mask & (1 << i)){
				if(i % 2)
					odd.push_back({a[i], i});
				else
					even.push_back({a[i], i});
			}
			else{
				if(i % 2)
					even.push_back({b[i], i});
				else
					odd.push_back({b[i], i});
			}
		}

		sort(odd.begin(), odd.end());
		sort(even.begin(), even.end());

		if(odd.size() != n / 2)
			continue;

		if(even.size() != (n + 1) / 2)
			continue;

		int p1 = 0, p2 = 0;

		vector<int> v(n), vv(n);
