			if(i % 2){
				v[i] = odd[p1].second;
				vv[i] = odd[p1].first;
				p1++;
			}
			else{
				v[i] = even[p2].second;
				vv[i] = even[p2].first;
				p2++;
			}
		}

		if(ok(vv))
			ans = min(ans, invs(v));

	}


	if(ans == oo)
		ans = -1;

	cout << ans << endl;
	return 0;
}

