  if(n+1==z){
    int ans = 0;
    int M = 0;
    vector<int> hak(n);
    for(int i= 0; n > i; i++){
      hak[i] = nya[i];
    }
    for(int i = 1; n >= i; i++){
      for(int j = 0+M; n > j; j++){
        if(i == hak[j-M]){
          ans += (j+1)-i;
          hak.erase(hak.begin()+(j-M));
          break;
        }
      }
      M++;
    }
    //cout << "!" << ans << endl;
    hak.clear();
    return ans;
  }
