		for(int i = 0; i < n; i++)
		{
			int tar = vec[i].fi.se;
			int idx = i;
			while(idx > tar)
			{
				res++;
				vec[idx].se ^= 1;
				vec[idx-1].se ^= 1;
				swap(vec[idx], vec[idx-1]);
				idx--;
			}			
		}
