		cin >> bs[i];
	}

	int ans = INT_MAX;
	vector<P> ps(n);
	FOR_LT(s, 0, (1 << n)) {
		FOR_LT(i, 0, n) {
			ps[i].i = i;
			if ((s >> i) & 1) {
				ps[i].c = bs[i];
				ps[i].p = (i + 1) & 1;
			}
			else {
				ps[i].c = as[i];
				ps[i].p = i & 1;
			}
		}
		stable_sort(ps.begin(), ps.end(), [](const auto & lhs, const auto & rhs) {
			return lhs.c < rhs.c;
			});

		bool is_ok = true;
		FOR_LT(j, 0, n) {
			if (ps[j].p == (j & 1)) {
				int si = ps[j].i;
				int sv = INT_MAX;
				FOR_LT(k, j + 1, n) {
					if (ps[k].c != ps[j].c) break;
					if (ps[j].p != (k & 1)) continue;
					if (ps[k].p != (j & 1)) continue;

					if (ps[k].i < si) {
						si = ps[k].i;
						sv = k;
					}
				}
				if (sv != INT_MAX) {
					swap(ps[j], ps[sv]);
				}
				continue;
			}

			bool is_found = false;
			int  si = INT_MAX;
			int  sv = INT_MAX;
			FOR_LT(k, j + 1, n) {
				if (ps[k].c != ps[j].c) break;
