      i64 i = idx[ii];
      if(flip[i]) {
        if(b == -1) b = ii;
        else if(X[idx[b]] == X[idx[ii]]){
          res += (ii - b);
          b = -1;
        }
        else {
          F = 0;
          break;
        }
      }
    }
    if(F == 0) continue;
    ans = std::min(ans, res);
    i64 t = 0;
    for(i64 i = N;i --> 0;) {
      t |= ((s >> i) & 1) << (N - 1 - i);
    }
    //cout << bitset<5>(t) << " " << res << endl;
  }
  if(ans == 1e18) ans = -1;
  cout << ans << endl;
}

