void solve()
{
	ll N; cin >> N;
	vll A = cinv(N);
	vll B = cinv(N);

	if (N == 1) bye(0);

	REP(i, N){
		if (i%2 == 1) swap(A[i], B[i]);
	}

	vector<tuple<ll, ll, ll>> buf(N);
	ll maskNum = CEIL(N, 2);

	ll ans = INF;
	REP(mask, (1LL<<N)){
		//1の数がCEIL(N,2)以外はskip
		ll m = 0;
		REP(i, N) m += ((mask>>i)&1);
		if (m != maskNum) continue;

		//
		REP(i, N){
			ll bit_ = (mask>>i)&1;
			if (bit_ == 1){
				get<0>(buf[i]) = A[i];
				get<1>(buf[i]) = i;
				get<2>(buf[i]) = 1;
			}
			else{
				get<0>(buf[i]) = B[i];
				get<1>(buf[i]) = i;
				get<2>(buf[i]) = 0;
			}
		}
		sort(buf.begin(), buf.end());

		//101010...チェック
		ll okNum = 0;
		REP(i, N){
			if (get<2>(buf[i]) == (i+1)%2) okNum++;
		}
		if (okNum != N) continue;

		//交換回数
		ll swapNum = 0;
		REPS(i, 0, N-2)REPS(j, i+1, N-1){
			if (get<1>(buf[i]) > get<1>(buf[j])) swapNum++;
		}

		chmin(ans, swapNum);
	}
	if (ans == INF) bye(-1);
	cout << ans << '\n';
}


int main(){
	solve();
	return 0;
}

