using ll = long long;
ll N;
vector<long long> A,B;
int mass[20];
int ans = 1e9;


int calc(){
    for(int i = 0;i < N;i++){
       // cout<<mass[i]<<" ";
    }
  //  cout<<endl;
    int odd_red = 0;
    int odd_blue = 0;
    int even_red = 0;
    int even_blue = 0;
    vector<int> v;
    for(int i = 0;i < N;i++){
        if(i % 2 == 0){
            if(mass[i]){
                odd_red++;
            }else{
                odd_blue++;
            }
        }else{
            if(mass[i]){
                even_red++;
            }else{
                even_blue++;
            }
        }    
        if(mass[i]){
            v.push_back(A[i]);
        }else{
            v.push_back(B[i]);
        }
    }
    if(odd_blue != even_blue){
        return 1e9;
    }

    sort(v.begin(), v.end());

    vector<bool> flag(N, false);
    int _ans = 0;
    for(int i = 0;i < N;i++){
        for(int j = 0;j < N;j++){
            if(flag[j])continue;
            if((i % 2 == j % 2) == mass[i]){
                if(mass[i]){
                    if(A[i] == v[j]){
                        flag[j] = true;
                        _ans += abs(j - i);
                      //  cout<<i<<" "<<j<<endl;
                    }
                }else{
                    if(B[i] == v[j]){
                        flag[j] = true;
                        _ans += abs(j - i);
                        //cout<<i<<" "<<j<<endl;
                    }
                }
            }
        }
    }
    for(int i = 0;i < N;i++)if(flag[i] == false)return 1e9;
    //cout<<_ans<<endl;
    return _ans/2;
}

int zrk(int i){
    if(N == i){
        ans = min(ans, calc());
        return 0;
    }
    mass[i] = 0;zrk(i+1);
    mass[i] = 1;zrk(i+1);
}

void solve(long long _N, std::vector<long long> _A, std::vector<long long> _B){
    N = _N;
    A = _A;
    B = _B;
    zrk(0);
    if(ans == 1e9){
        cout<<-1<<endl;
        return;
    }
    cout<<ans<<endl;
}

