int main() {
    int n;
    cin >> n;
    int a[n], b[n];
    for (auto &ai:a) cin >> ai;
    for (auto &bi:b) cin >> bi;
    int ans = 10000;
    int vals[n];
    for (int i=0; (i >> n) == 0; i++) {
        set<int> cards[51][2];
        for (int j=0; j<n; j++) {
            if ((i >> j) & 1) {
                vals[j] = a[j];
                cards[a[j]][j % 2].insert(j);
            } else {
                vals[j] = b[j];
                cards[b[j]][(j+1) % 2].insert(j);
            }
        }
        sort(vals, vals+n);
        int swap = 0;
        for (int j=0; j<n; j++) {
            if (cards[vals[j]][j%2].empty()) {
                swap = 10000;
                break;
            }
            auto itr = cards[vals[j]][j%2].begin();
            swap += abs(*itr - j);
            cards[vals[j]][j%2].erase(itr);
        }
        assert(swap <= 10000);
        ans = min(ans, swap);
    }
    cout << (ans < 10000 ? ans/2 : -1) << '\n';
    return 0;
}

