template<typename T = int, class F = std::plus<T>, class F_INV = std::minus<T>, const T E = 0>
struct BinaryIndexedTree {
    const F op = F(); const F_INV op_inv = F_INV();
    int n; vector<T> dat;
    void build(const vector<T>& v) {
        n = v.size(); dat.assign(n, E); for (int i = 0; i < n; ++i) add(i, v[i]);
    }
    void add(int k, T v) { for (int i = k; i < n; i |= i + 1) dat[i] = op(dat[i], v); }
    T query(int a, int b) const {
        T ret = E; if (a == b) return ret;
        for (int i = b - 1; i >= 0; i = (i & (i + 1)) - 1) ret = op(ret, dat[i]);
        return op_inv(ret, query(0, a));
    }
};

struct InversionNumber {
    BinaryIndexedTree<int> bit;
    vector<int> vcomp;

    ll inversion_number(const vector<int>& v) {
        vcomp = v;
        sort(vcomp.begin(), vcomp.end());
        vcomp.erase(unique(vcomp.begin(), vcomp.end()), vcomp.end());

        bit.n = v.size();
        bit.dat.assign(v.size(), 0);
        ll res = 0;
        for (int i = 0; i < (int)v.size(); ++i) {
            int j = lower_bound(vcomp.begin(), vcomp.end(), v[i]) - vcomp.begin();
            res += i - bit.query(0, j + 1);
            bit.add(j, 1);
        }
        return res;
    }
};

int main() {
    int N;
    cin >> N;
    vector<int> A(2 * N);
    rep(i, 2 * N) cin >> A[i];

    vector<int> num(N);
    vector<int> idx(N);
    iota(all(idx), 0);
    InversionNumber inv;
    int ans = INF;
    rep(bit, 0, 1 << N) {
        bool ok = true;
        rep(i, N) ok ^= bit >> i & 1;
        if (!ok) continue;

        rep(i, N) num[i] = A[i + N * (bit >> i & 1)];
        stable_sort(all(idx), [&](int l, int r) { return num[l] < num[r]; });

        vector<int> eo[2];
        for (int i = 0, j; i < N; i = j) {
            for (j = i + 1; j < N; ++j) {
                if (num[idx[j]] != num[idx[i]]) break;
            }

            if (j - i == 1) {
                if ((abs(i - idx[i]) & 1) ^ (bit >> idx[i] & 1)) {
                    ok = false;
                    break;
                }
            }
            else {
                eo[0].resize(0);
                eo[1].resize(0);
                rep(k, i, j) {
                    eo[(abs(i - idx[k]) & 1) ^ (bit >> idx[k] & 1)].push_back(idx[k]);
                }
                if ((int)eo[0].size() - (int)eo[1].size() != (j - i) % 2) {
                    ok = false;
                    break;
                }

                int ke = 0, ko = 0;
                rep(k, i, j) {
                    if ((k ^ i) & 1) {
                        idx[k] = eo[1][ko];
                        ko++;
                    }
                    else {
                        idx[k] = eo[0][ke];
                        ke++;
                    }
                }
            }
        }
        if (!ok) continue;

        int move = inv.inversion_number(idx);
        ans = min(ans, move);
    }

    write(ans == INF ? -1 : ans);
}

