ll calc(){
    for(int i = 0;i < N;i++){
       // cout<<mass[i]<<" ";
    }
  //  cout<<endl;
    int odd = 0, even = 0;
    vector<pair<int, int>> v,v1,v2;
    for(int i = 0;i < N;i++){
        if(i % 2 == 0){
            if(mass[i]){
                odd++;
                v1.push_back({B[i], i});
            }else{
                even++;
                v2.push_back({A[i], i});
            }
        }else{
            if(mass[i]){
                even++;
                v2.push_back({B[i], i});
            }else{
                odd++;
                v1.push_back({A[i], i});
            }
        }
    }

    if(odd != N / 2)return 1e18;
    if(even != (N+1) / 2)return 1e18;

    vector<int> ww;
    int od = 0, ev = 0;

    sort(v1.begin(), v1.end());
    sort(v2.begin(), v2.end());
    for(int i = 0;i < N;i++){
        if(i%2 == 0){
            v.push_back(v2[i/2]);
        }else{
            v.push_back(v1[i/2]);
        }
    }
    for(int i = 0;i < N-1;i++){
        if(v[i].first > v[i+1].first)return 1e18;
    }
    ll cnt = 0;

    for(int i = N-1;i >= 0;i--){
        for(int j = 0;j < i;j++){
            if(v[j].second > v[i].second)cnt++;
        }
    }
    return cnt;
}

