void swap(int *a1_, int *a2_, int *b1_, int *b2_){
  int a1 = *a1_;
  int a2 = *a2_;
  int b1 = *b1_;
  int b2 = *b2_;
  *a1_ = b2;
  *a2_ = b1;
  *b1_ = a2;
  *b2_ = a1;
}

int main(){
  int N; cin >> N;
  vector<pair<int,int>> AB(N);
  rep(i,N) cin >> AB[i].first;
  rep(i,N) cin >> AB[i].second;
  int ans = 1e9;
  rep(i,pow(2,N)){
    int now = i;
    vector<bool> useB(N,false);
    rep(j,N){
      if(now%2==1) useB[j] = true;
      now >>= 1;
    }

    vector<pair<int,int>> CD = AB;
    vector<pair<int,int>> EF = AB;
    rep(j,N){
      if(useB[j]){CD[j].first = 100; EF[j].first = 100;}
      else{CD[j].second = 100; EF[j].second = 100;}
      int big = max(CD[j].first, CD[j].second);
      int sma = min(CD[j].first, CD[j].second);
      CD[j] = {sma, big};
    }
    sort(all(CD));
    /*
    rep(i,N) cout << CD[i].first << " ";
    cout << endl;
    rep(i,N) cout << CD[i].second << " ";
    cout << endl;
    rep(i,N) cout << EF[i].first << " ";
    cout << endl;
    rep(i,N) cout << EF[i].second << " ";
    cout << endl;
    cout << "----------------------" << endl;
    */
    int preans = 0;
    rep(j,N-1){
      int flag = false;
      if(CD[j].first == EF[j].first) continue;
      for(int k=j+1; k<N; k++){
        if((k-j)%2==1){
          if(CD[j].first == EF[k].second){
            flag = true;
            for(int l = k-1; l>=j; l--){
              swap(&EF[l].first, &EF[l+1].first, &EF[l].second, &EF[l+1].second);
              preans++;
            }
          }
        }
        else {
          if(CD[j].first == EF[k].first){
            flag = true;
            for(int l = k-1; l>=j; l--){
              swap(&EF[l].first, &EF[l+1].first, &EF[l].second, &EF[l+1].second);
              preans++;
            }
          }
        }
        if(!flag) {preans = 1e9; j=N+1;break;}
      }
    }
    if(CD[N-1].first != EF[N-1].first) preans = 1e9;
    /*
    cout << ans << " " << preans << endl;
    cout << "--------------" << endl;
    */
    ans = min(ans, preans);
  }
  if(ans == 1e9) cout << -1 << endl;
  else cout << ans << endl;
  return 0;
}

