int main() {
  int N; cin >> N;
  vector<int> A(N), B(N);
  cin >> A >> B;

  vector<vector<int>> dp(1 << N, vector<int>(kVmax, kInf));
  dp[0][0] = 0;

  for (int S = 0; S < (1 << N); ++S) {
    bitset<18> b(S);
    int size = b.count();

    vector<pair<int, int>> cands;  // first: original pos, second: now pos
    int now = size;
    for (int i = 0; i < N; ++i) {
      if (!b.test(i)) {
        cands.emplace_back(i, now);
        ++now;
      }
    }

    for (int last = 0; last < kVmax; ++last) {
      for (const auto& cand_pos : cands) {
        int idx = cand_pos.first;
        int now = cand_pos.second;
        int value = (abs(idx - size) % 2 == 0) ? A[idx] : B[idx];
        if (value >= last) {
          int nextS = S | (1 << idx);
          dp[nextS][value] = min(dp[nextS][value], dp[S][last] + abs(now - size));
        }
      }
    }
  }

  int vmin = kInf;
  for (int last = 0; last < kVmax; ++last) {
    vmin = min(vmin, dp[(1 << N) - 1][last]);
  }

  if (vmin == kInf) cout << -1 << endl;
  else              cout << vmin << endl;
}

