//REPマクロ
#define REP(i,n) for(ll i=0;i<(ll)(n);i++)
#define REPD(i,n) for(ll i=n-1;i>=0;i--)
#define REP2(i,a,b) for(ll i=a;i<(ll)(b);i++)
#define REPD2(i,a,b) for(ll i=a;i>(ll)(b);i--)

// 多次元 vector 生成
template<class T>
vector<T> make_vec(size_t a){
    return vector<T>(a);
}
template<class T, class... Ts>
auto make_vec(size_t a, Ts... ts){
  return vector<decltype(make_vec<T>(ts...))>(a, make_vec<T>(ts...));
}

//vectorの扱い
#define ALL(x) (x).begin(),(x).end() //sortなどの引数省略
#define SIZE(x) ((ll)(x).size()) //size
#define MAX(x) *max_element(ALL(x)) //最大値
#define MIN(x) *min_element(ALL(x)) //最小値

template<typename T>
class BinaryIndexedTree {
    int N;
    vector<T> data;
public:
    BinaryIndexedTree(int N) : N(N) {
        data.resize(N + 1, 0);
    }

    T sum(int k) {
        T res = 0;
        for (; k > 0; k -= k & -k) {
            res += data[k];
        }
        return res;
    }

    void add(int k, T x) {
        for (; k <= N; k += k & -k) {
            data[k] += x;
        }
    }

    /**
     * v1 + v2 + ⋯ + vx ≧ W となる最小の 𝑥 を求める
     */
    int lowerBound(int w) {
        if (w <= 0) return 0;
        int x = 0;
        int k = 1;
        while (k * 2 <= N) k *= 2;
        for (; k > 0; k /= 2) {
            if (x + k <= N && data[x + k] < w) {
                w -= data[x + k];
                x += k;
            }
        }
        return x + 1;
    }
};

int main(){
    int N;
    cin>>N;
    vector<int> A(N),B(N);
    REP(i,N) cin>>A[i];
    REP(i,N) cin>>B[i];
    int ans=INF;
    REP(bit,1<<N){
        vector<int> C(N);
        vector<int> swapnum(N,0);
        bool ok=true;

        REP(j,N){
            int mask=1<<j;
            if(bit&mask){
                C[j]=A[j];
            }else{
                C[j]=B[j];
            }
        }

        int sum=0;
        REP(j,N){
            int cnt=0;
            REP2(k,j+1,N){
                if(C[j]>C[k]){
                    cnt++;
                    swapnum[k]++;
                    swapnum[j]++;
                }
            }
            sum+=cnt;
        }

        REP(j,N){
            int mask=1<<j;

            if(bit&mask){
                if(swapnum[j]%2!=0) ok=false;
            }else{
                if(swapnum[j]%2==0) ok=false;
            }
        }
        if(ok){
            ans=min(ans,sum);
        }
    }

    if(ans==INF) ans=-1;
    cout<<ans<<endl;
}

