  		ns.push_back((num){A[(S>>i)&1][i],(int)i,(int)((((S>>i)&1)==0)?(i&1):(1-(i&1)))});
  	}
  	sort(all(ns),[](const num& a,const num& b){
  		return a.val < b.val;
  	});
  	bool ok=true;
  	vector<int> B(N);
  	for(int i=0;i<N;){
  		int j=i;
  		while(j<N&&ns[j].val==ns[i].val)j++;
  		vector<ll> odk,evk;
  		vector<ll> odidx,evidx;
  		repl(k,i,j){
  			if(k%2==0)evk.push_back(k);
  			else odk.push_back(k);
  			if(ns[k].sgn==0) evidx.push_back(ns[k].idx);
  			else odidx.push_back(ns[k].idx);
  		}
  		if(odk.size()!=odidx.size()||evk.size()!=evidx.size()){
  			ok=false;
  			break;
  		}
  		rep(k,odk.size()){
  			B[odk[k]]=odidx[k];
  		}
  		rep(k,evk.size()){
  			B[evk[k]]=evidx[k];
  		}
  		i=j;
  	}
  	if(!ok)continue;
  	int sum=0;
  	rep(i,N)rep(j,i)if(B[i]<B[j])sum++;
  	minch(res,sum);
  }
  if(res==INF)cout<<-1<<endl;
  else cout<<res<<endl;

  return 0;
}

