    for(LL i = 0; i < (1<<n); ++i){
        LL a_even_i = 0, b_even_i = 0;
        LL a_odd_i = 0, b_odd_i = 0;
        for(LL cur = 0; cur < n; ++cur){
            used[cur] = 0;
            index[cur] = -1;
            check[cur] = -1;
        }
        for(LL cur = 0; cur < n; ++cur){
            if((cur&1) == 0){
                if(((i>>cur)&1) == 0){
                    //cerr << "a_even" << endl;
