#include <bits/stdc++.h>
using namespace std;
using P = pair<int, int>;

vector<int> w;
vector<vector<int>> u;
vector<P> v;
vector<vector<int>> dp;

int func(int m, int s){
	if(dp[m][s] < 1e9) return dp[m][s];
	int n = v.size();
	int k = w[s];
	if(k == n) return dp[m][s] = 0;
	int mi = 1e9;
	for(int i=0; i<(int)u[s].size(); ++i){
		if((s >> u[s][i]) & 1) continue;
		int x = (k % 2 == 0 ? v[u[s][i]].first : v[u[s][i]].second);
		if(x < m) continue;
		mi = min(mi, i+func(x, s|(1<<u[s][i])));
	}
	return dp[m][s] = min(dp[m][s], mi);
}

int main(){
	cin.tie(0);
	ios::sync_with_stdio(false);
	int n; cin >> n;
	vector<int> a(n), b(n);
	for(int i=0; i<n; ++i) cin >> a[i];
	for(int i=0; i<n; ++i) cin >> b[i];
	v.resize(n);
	for(int i=0; i<n; ++i) v[i] = (i % 2 == 0 ? P(a[i], b[i]) : P(b[i], a[i]));
	dp.resize(51, vector<int>(1<<n, 1e9));
	w.resize(1<<n);
	u.resize(1<<n);
	for(int i=0; i<(1<<n); ++i){
		int t = 0;
		for(int j=0; j<n; ++j){
			if((i>>j) & 1) ++t;
			else u[i].push_back(j);
		}
		w[i] = t;
	}
	func(0, 0);
	cout << (dp[0][0] == 1e9 ? -1 : dp[0][0]) << "\n";
}

