		if(bef > v) continue;
		printf("bef %d, v %d, last %d, now %d\n",bef ,v,last,i);
		ret = min(ret, solve(mask | (1 << i), i) + abs(val[mask] - i));
	}
	printf("%d %d -> %d\n",mask,last,ret);
	return ret;
}

