struct Problem {

	void Solve() {
		UL N; cin >> N;
		vector<pair<UL, UL>> A(N);
		rep(i, N) cin >> A[i].first;
		rep(i, N) cin >> A[i].second;
		rep(i, N) if (i % 2 == 1) swap(A[i].first, A[i].second);
		UL ans = 10000;
		const UL R = (N + 1) / 2, B = N / 2;
		for (UL i = 0; i < (1 << N); i++) {
			vector<UL> r, b;
			UL f = 0;
			rep(j, N) if (i & (1 << j)) f++;
			if (f != B) continue;
			vector<pair<UL, bool>> C;
			rep(j, N) {
				if (i & (1 << j)) C.push_back({ A[j].second, true });
				else C.push_back({ A[j].first, false });
			}
			UL ansbuf = 0;
			for (UL p = N; p > 0; p--) {
				UL d = 0, di = 0;
				bool col = !(p & 1);
				for (UL q = 0; q < p; q++) {
					if (C[q].second == col)
						if (C[q].first >= d) { di = q; d =  C[q].first; }
				}
				for (UL q = di + 1; q < p; q++) {
					swap(C[q - 1], C[q]);
					ansbuf++;
				}
				if (p != N) if (C[p - 1].first > C[p].first) ansbuf += 10000;
			}
			ans = min(ans, ansbuf);
		}
		if (ans == 10000) cout << -1 << endl;
		else cout << ans << endl;
	}


	Problem();
};
int main() {
	unique_ptr<Problem> p(new Problem());
	p->Solve();
	return 0;
}
