const int MAXN = 18;

struct Node {
  int val, pos;
  bool is_faceup;

  Node(int val, int pos, int is) : val(val), pos(pos), is_faceup(is) {}

  bool operator< (const Node& b) const {
    if (val == b.val) return pos < b.pos;
    return val < b.val;
  }
};

std::pair<int, int> a[MAXN];

int calc_op_num(const std::vector<Node>& a) {
  int ans = 0;
  int n = (int)a.size();
  bool used[n];
  for (int i = 0; i < n; ++i) used[i] = false;

  for (int pos = 0; pos < n; ++pos) {
    int cur_min = 100;
    for (int i = 0; i < n; ++i) {
      if (used[i]) continue;
      cur_min = a[i].val;
      break;
    }
    bool can_find = false;
    for (int i = 0; i < n; ++i) {
      if (used[i]) continue;
      int op_num = std::abs(a[i].pos - pos);
      if (a[i].val == cur_min && (a[i].is_faceup + op_num) % 2 == 1) {
        used[i] = true;
        ans += op_num;
        can_find = true;
        break;
      }
    }
    if (!can_find) return -1;
  }
  assert(ans % 2 == 0);
  return ans / 2;
}

int solve(int n) {
  int ans = -1;
  std::vector<Node> cur;
  int enum_num = 1 << n;
  for (int mask = 0; mask < enum_num; ++mask) {
    cur.clear();
    for (int i = 0; i < n; ++i) {
      if (mask & (1 << i)) {
        cur.emplace_back(a[i].first, i, true);
      } else {
        cur.emplace_back(a[i].second, i, false);
      }
    }
    std::sort(cur.begin(), cur.end());
    int op_num = calc_op_num(cur);
    if (op_num != -1 && (ans == -1 || op_num < ans)) ans = op_num;
  }
  return ans;
}

int main() {
  int n;
  std::cin >> n;
  for (int i = 0; i < n; ++i) std::cin >> a[i].first;
  for (int i = 0; i < n; ++i) std::cin >> a[i].second;
  std::cout << solve(n) << std::endl;
  return 0;
}

