int dp(int id, int mask, int last){
	if(mask == (1<<n)-1) return 0;
	int &ret = memo[mask][last];
	if(ret!=-1) return ret;
	ret = INF;
	for(int i=0;i<n;i++){
		if(cek_bit(i,mask)) continue;
		int pake = -1;
		if(abs(i-id)&1){
			pake = li[1][i];
		} else {
			pake = li[0][i];
		}
		if(pake >= last){
			ret = min(ret,dp(id+1,tog_bit(i,mask),pake) + abs(i-id));
		}
	}
	return ret;
}


