        if (itr == even_list.end() || itr->first != num) {
          ok = 0;
          break;
        } else {
          t += abs(i - (itr->second + 2 * used_even[num]));
          used_even[num]++;
        }
        // debug(0, num, *itr, t);
      } else {
        int num = ((b >> i) & 1) ? B[i] : A[i];
        auto itr = lower_bound(ALL(odd_list), Pii(num, -1));
        if (itr == odd_list.end() || itr->first != num) {
