        } else {
          t += abs(i - (itr->second + 2 * used_odd[num]));
          used_odd[num]++;
        }
        // debug(1, num, *itr, t);
      }
    }
    // debug((int)ok, t, list, even_list, odd_list);
    if (ok) {
      ans = min(ans, t / 2);
    }
  }
  io.write(ans == INF ? -1 : ans);
  io.write("\n");
  return 0;
}

