  int min_operations = numeric_limits<int>::max();
  // int result_mask = -1;
  for (int mask = 0; mask < (1 << N); mask++) {
    if (__builtin_popcount(mask) % 2 != 0) {
      continue;
    }
    for (int i = 0; i < N; i++) {
      if ((mask >> i) & 1) {
        order[i] = cards[i].B;
      } else {
        order[i] = cards[i].A;
      }
    }
    sort(all(order));
    // cerr << "mask: " << mask << endl;
    for (int i = 0; i < N; i++) {
      int number;
      if ((mask >> i) & 1) {
        number = cards[i].B;
      } else {
        number = cards[i].A;
      }
      int left = N, right = -1;
      for (int j = 0; j < N; j++) {
        if (order[j] == number) {
          left = min(left, j);
          right = max(right, j);
        }
      }
      // cerr << "i: " << i << " " << number << " " << left << " " << right << endl;
      assert(left <= right);
      ranges[i] = Range{left, right};
    }
    int operations = 0;
    bool fail = false;
    fill(all(used), -1);
    for (int i = 0; i < N && !fail; i++) {
      int odd = (mask >> i) & 1;
      int closest = -1;
      // cerr << "w: " << i << " " << odd << endl;
      for (int j = ranges[i].left; j <= ranges[i].right; j++) {
        if (used[j] == -1 && abs(j - i) % 2 == odd) {
