          }
        }
      }
      // cerr << "c: " << i << " " << closest << endl;
      if (closest == -1) {
        fail = true;
      } else {
        used[closest] = i;
      }
    }
    for (int i = 0; i < N; i++) {
      for (int j = i + 1; j < N; j++) {
        if (used[i] > used[j]) {
          operations += 2;
        }
      }
    }
    // cerr << "ans: " << fail << " " << operations << endl;
    if (!fail && operations < min_operations) {
      min_operations = operations;
      // result_mask = mask;
    }
  }
  // cerr << min_operations << " " << check_answer << endl;
  if (min_operations == numeric_limits<int>::max()) {
    cout << -1 << endl;
    return 0;
  }
  // assert(result_mask != -1);
  assert(min_operations % 2 == 0);
  cout << min_operations / 2 << endl;



  return 0;
}

