        //REP(i,N){cout << S[i].second << " ";}cout << endl;

        REP(i,N){
            int mn = i;
            for(int j=i;j<N;j++){
                if(S[mn]>S[j]){
                    mn=j;
                }
            }
            //mnをiに移行
            if((mn+i+S[mn].second)%2==1){
                forbid=true;
                break;
            }
            for(int j = mn;j>=i+1;j--){
                swap(S[j],S[j-1]);
                S[j].second ^=1;
                S[j-1].second ^=1;
                num++;
            }
        }

        REP(i,N){
            if(S[i].second==1){
                forbid=true;
            }
        }

        if(forbid==false){
            Ans=min(Ans,num);
        }

        //cout << num << "  " <<(forbid?"true":"false") << endl;

    }

    if(Ans==INF){
        cout << -1 << endl;
    }else{
        cout << Ans << endl;
    }
    return 0;
}

