template< typename T >
struct BinaryIndexedTree {
  vector< T > data;
  BinaryIndexedTree(int sz) {
    data.assign(++sz, 0);
  }
  T sum(int k) {
    T ret = 0;
    for(++k; k > 0; k -= k & -k) ret += data[k];
    return (ret);
  }
  void add(int k, T x) {
    for(++k; k < SZ(data); k += k & -k) data[k] += x;
  }
};

ll hanten(VI& A){
    ll N = A.size();
    auto bit = BinaryIndexedTree<ll>(N);
    ll count = 0;
    FOR(i, 0, N){
        ll a = A[i];
        ll num = i - bit.sum(a);
        count += num;
        bit.add(a, 1);
    }
    return count;
}

