		if (i % 2 == 0)
			vp2.push_back(make_pair(b, i));
		else
			vp1.push_back(make_pair(b, i));
	}

	sort(vp1.begin(), vp1.end());
	sort(vp2.begin(), vp2.end());
	int res = -1;
	for (int i = 0; i < n; i++) {
		int index1 = i, index2 = 0;
		int last = 0;
		vector<int> seq;
		vector<int> v(n, 0);

		for (int j = 0; j < n; j++) {
			if (j % 2 == 0) {
				while (index1 < n) {
					if (v[vp1[index1].second] == 1 || last > vp1[index1].first)
						index1++;
					else
						break;
				}
				if (index1 < n) {
					seq.push_back(vp1[index1].second);
					v[vp1[index1].second] = 1;
					last = vp1[index1].first;
				}
				else {
					break;
				}
			}
			else {
				while (index2 < n) {
					if (v[vp2[index2].second] == 1 || last > vp2[index2].first)
						index2++;
					else
						break;
				}
