int n;
int a[20], b[20];
void solve() {
    cin >> n;
    rep(i, n) cin >> a[i];
    rep(i, n) cin >> b[i];

    int ans = iinf;
    rep(s, 1 << n) {
        bool before = false;
        bool bad = false;
        rep(i, n) {
            if (((s >> i) & 1) == 0) {
                if (before) { bad = true; break; }
            }
            else before = !before;
        }

        if (bad) continue;

        vector<pair<int, int>> v(n);
        rep(i, n)
            if (((s >> i) & 1) == 0) v[i] = make_pair(a[i], i % 2);
            else v[i] = make_pair(b[i], (i + 1) % 2);

        all(sort, v);
        int count[] = { 0,0 }, start = 0;
        bad = false;
        count[v[0].second] = 1;
        reps(i, n - 1) {
            if (v[i - 1].first == v[i].first) ++count[v[i].second];
            else {
                if ((count[0] + count[1]) % 2 == 0 && count[0] != count[1] ||
                    (count[0] + count[1]) % 2 == 1 && start % 2 == 0 && count[0] - count[1] != 1 ||
                    (count[0] + count[1]) % 2 == 1 && start % 2 == 1 && count[1] - count[0] != 1) {
                    bad = true; break;
                }
                count[0] = count[1] = 0;
                start = i;
                ++count[v[i].second];
            }
        }

        if ((count[0] + count[1]) % 2 == 0 && count[0] != count[1] ||
            (count[0] + count[1]) % 2 == 1 && start % 2 == 0 && count[0] - count[1] != 1 ||
            (count[0] + count[1]) % 2 == 1 && start % 2 == 1 && count[1] - count[0] != 1) {
            bad = true;
        }
        if (bad) continue;

        int res = 0;
        vector<bool> vec(n, false);
        rep(i, n) rep(j, n) {
            if ((((s >> i) & 1) + i) % 2 != j % 2) continue;
            int val = (((s >> i) & 1) == 0 ? a[i] : b[i]);

            if (val == v[j].first && !vec[j]) {
                vec[j] = true;
                res += abs(i - j);
                break;
            }
        }

        res /= 2;
        mins(ans, res);

    }

    if (ans == iinf) cout << -1 << endn;
    else cout << ans << endn;

}

