                A.push_back(j);
                Aval.push_back(val[j]);
            } else {
                B.push_back(j);
                Bval.push_back(val[j]);
            }
        }
        if (!(A.size() == B.size() || A.size() == B.size() + 1))continue;
        //cout << "b" << endl;
        int res = 0;
        vector<int> cur(N);
        rep(j, N) {
            cur[j] = j;
        }
        sort(Aval.begin(), Aval.end());
        sort(Bval.begin(), Bval.end());
        rep(j, B.size()) {
            if (Aval[j] > Bval[j])goto next;
            if (A.size() >= j + 1 + 1) {
                if (Aval[j + 1] < Bval[j])goto next;
            }
        }
        //cout << "c" << endl;
        rep(j, N) {
            //cout << j << endl;
            if (j % 2 == 0) {
                //Aval[j/2]を探す
                rep(k, A.size()) {
                    if (val[A[k]] == Aval[j / 2]) {
                        //これをj番目に動かす
                        res += cur[A[k]] - j;
                        //cerr << "A" << A[k] << " " << cur[A[k]] - j << endl;
                        val[A[k]] = -1;
                        //既に前方に移動させたもの以外は前後関係は変わっていない
                        rep(l, A[k]) {
                            cur[l]++;
                        }
                    }
                }
            } else {
                //Bval[j/2]を探す
