        //cout << "!-1" << endl;
        next:;
    }
    if (ans == INF) {
        cout << -1 << endl;
        return 0;
    }
    cout << ans << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
typedef pair<int, int> pii;
typedef long long ll;
#define F first
#define S second
#define pb push_back
mt19937 rnd;

const int N = 19, M = 53, inf = 1e9;
map<pair<vector<pii>, int>, int> mp;

int solve(vector<pii>& a, int mx) {
    if (a.size() == 1) {
        if (a[0].F <= mx) return 0;
        else return inf;
    }
    if (mp.count({a, mx})) {
        return mp[{a, mx}];
    }
    int n = a.size(), ans = inf;
    vector<pii> b;
    for (int i=0; i<n; i++) {
        for (int j=i+1; j<n; j++) {
            b.pb({a[j].S, a[j].F});
        }
        if (a[i].F <= mx && (n - 1 - i)%2 == 0) {
            ans = min(ans, solve(b, a[i].F) + (n - 1 - i));
        }
        if (a[i].S <= mx && (n - 1 - i)%2 == 1) {
            ans = min(ans, solve(b, a[i].S) + (n - 1 - i));
        }
        for (int j=i+1; j<n; j++) {
            b.pop_back();
        }
        b.pb(a[i]);
    }
    return mp[{a, mx}] = ans;
}

