ll N;
vvll X;
vll V_copy;
vll V;
vll Vb;

ll search(ll flag){
  ll flag_copy = flag;
  ll tmp1 = 0;
  REP(i,N){
    V[i] = X[i][flag_copy%2];
    tmp1 += flag_copy%2;
    Vb[i] = flag_copy%2;
    flag_copy>>=1;
  }
  if(tmp1%2==1) return INFLL;
  V_copy = V;
  sort(ALL(V));
  vb touch(N, false);
  ll ans = 0;
  REP(i,N){
    bool flag_tmp = false;
    REP(j,N){
      if(touch[j]) continue;
      if(V[i]==V_copy[j] && (abs(i-j))%2==Vb[i]){
        flag_tmp = true;
        touch[j] = true;
        ans += abs(i-j);
        break;
      }
    }
    if(!flag_tmp) return INFLL;
  }
  return ans;
}

