int dp[51][1 << 18] = {};

int dfs(int idx, int mi, int s, int n, vi &o, vi &e) {
  if (dp[mi][s] != -1) {
    return dp[mi][s];
  }
  if (s == 0) {
    dp[mi][s] = 0;
    return 0;
  }
  int ans = 5000000;
  REP(i, n) {
    int _mi = idx % 2 == 0 ? e[i] : o[i];
    if (!((s >> i) & 1) || _mi < mi)
      continue;
    int move = 0;
    REP(j, i) {
      if (((s >> j) & 1)) {
        move++;
      }
    }
    int tmp = dfs(idx + 1, _mi, (s & (~(1 << i))), n, o, e);
    if (tmp != 5000000) {
      ans = min(move + tmp, ans);
    }
  }
  dp[mi][s] = ans;
  return ans;
}

