fun main(args: Array<String>) {
    val sc = FastScanner(System.`in`)

    val n = sc.nextInt()
    val a = Array(n) { sc.nextInt() }
    val b = Array(n) { sc.nextInt() }

    var best = -1
    for (bit in 0..(1.shl(n))) {
        val res = mutableListOf<Int>()

        var count = 0
        for (x in 0 until n) {
            if (bit.and(1.shl(x)) != 0) {
                res.add(b[x])
                count += 1
            } else res.add(a[x])
        }
        if (count % 2 != 0) continue

        val ch = check(res, bit)
        if ((best == -1 || count < best) && ch!=-1) best = ch /2
    }

    println(best)
}

fun check(cards: MutableList<Int>, bit:Int): Int {
    val flips = Array(51) { 0 }
    for (i in 0 until cards.size) {
        if(bit.and(1.shl(i)) != 0)
            flips[cards[i]] += 1
    }

    val before = Array(51) { 0 }
    for (i in 0 until cards.size) {
        before[cards[i]] += i
    }

    cards.sort()

    val after = Array(51) { 0 }
    for (i in 0 until cards.size) {
        after[cards[i]] += i
    }

    var sum = 0
    for (i in 0..50) {
        sum += Math.abs(before[i] - after[i])
        if ((before[i] + after[i] + flips[i]) % 2 !=0 ){
            return -1
        }
    }
    return sum
}


