fun keyence2020d() {
    val n = readLine()!!.toInt()
    val aList = readLine()!!.split(' ').map { it.toInt() }.toIntArray()
    val bList = readLine()!!.split(' ').map { it.toInt() }.toIntArray()

    val inf = Int.MAX_VALUE / 10
    var answer = inf

    for (mid in 0 until n) {
        for (i in 0L until (1L shl (n - 1))) {
            val bitSet = BitSet.valueOf(longArrayOf(i))
            val front = aList.copyOf()
            val back = bList.copyOf()

            (0 until mid).forEach {
                if (bitSet[it]) {
                    swap(front, back, it)
                }
            }

            (n - 1 downTo mid).forEach {
                if (bitSet[it]) {
                    swap(front, back, it)
                }
            }

            if ((0 until n - 1).all { front[it] <= front[it + 1] }) {
                answer = Math.min(answer, bitSet.cardinality())
            }
        }
    }

    if (answer == inf) answer = -1

    println(answer)
}

private fun swap(arr1: IntArray, arr2: IntArray, idx: Int) {
    val tempFront = arr1[idx]
    val tempBack = arr2[idx]
    arr1[idx] = arr2[idx + 1]
    arr2[idx] = arr1[idx + 1]
    arr1[idx + 1] = tempBack
    arr2[idx + 1] = tempFront
}

