    val AArr = readInputLine().split(" ").map { it.toInt() }.toIntArray()
    val BArr = readInputLine().split(" ").map { it.toInt() }.toIntArray()
    val cardArr = Array(N) { Pair(AArr[it], BArr[it]) }

    var ans = Int.MAX_VALUE
    var maxBit = pow2(N) - 1

    for (i in 0..maxBit) {
        // (元インデックス, カード値)のペア
        val tmpArr = Array(N) { Pair(0, 0) }
        val isRev = BooleanArray(N)
        var bitTmp = i
        for (j in 0 until N) {
            // 末尾ビットから1 -> Blue, 0 -> Redとする
            if (bitTmp % 2 == 1) {
                tmpArr[j] = Pair(j, cardArr[j].second)
                isRev[j] = true
            } else {
                tmpArr[j] = Pair(j, cardArr[j].first)
            }
            bitTmp /= 2
        }

        val sorted = tmpArr.sortedBy { it.second }
        var ok = true
        for ((sortedIndex, card) in sorted.withIndex()) {
            val (cardIndex, value) = card
            if ((Math.abs(cardIndex - sortedIndex) % 2 == 1) != isRev[cardIndex]) {
                ok = false
                break
            }
        }
        if (!ok) {
            continue
        }

//        ans = Math.min(ans, mergeCount(tmpArr, 0, tmpArr.size))
        ans = Math.min(ans, mergeCount(tmpArr))
    }

    if (ans == Int.MAX_VALUE) {
        println(-1)
    } else {
        println(ans)
    }
}

