fun pow2(N: Int): Int {
    var ret = 1
    for (i in 1..N) {
        ret *= 2
    }
    return ret
}

fun mergeCount(arr: Array<Pair<Int, Int>>): Int {
    var count = 0
    for (i in 0 until arr.size) {
        for (j in 0 until i) {
            if (arr[i].second < arr[j].second) {
                count++
            }
        }
    }
    return count
}

