        int N = in.nextInt();
        int[][] AB = new int[N][2];
        for(int i = 0; i < N; i++) AB[i][0] = in.nextInt();
        for(int i = 0; i < N; i++) AB[i][1] = in.nextInt();

        int ans = Integer.MAX_VALUE;
        LOOP:for(int i = 0; i < (1 << (N - 1)); i++){
            int[][] idxFlip = new int[N][2];
            for(int j = 0; j < N; j++){
                idxFlip[j][0] = j;
                idxFlip[j][1] = 0;
            }
            for(int j = 0; j < N-1; j++){
                if(((i >> j) & 1) == 1){
                    int tmp = idxFlip[j][0];
                    idxFlip[j][0] = idxFlip[j+1][0];
                    idxFlip[j+1][0] = tmp;
                    tmp = idxFlip[j][1];
                    idxFlip[j][1] = idxFlip[j+1][1];
                    idxFlip[j+1][1] = tmp;
                    idxFlip[j][1] = (idxFlip[j][1] + 1) % 2;
                    idxFlip[j+1][1] = (idxFlip[j+1][1] + 1) % 2;
                }
            }
            //for(int j = 0; j < N; j++) out.print(AB[idxFlip[j][0]][idxFlip[j][1]] + " ");
            //out.println();
            for(int j = 0; j < N-1; j++)
                if(AB[idxFlip[j][0]][idxFlip[j][1]] > AB[idxFlip[j+1][0]][idxFlip[j+1][1]])
                    continue LOOP;
            ans = Math.min(ans, Integer.bitCount(i));
        }
        out.println(ans == Integer.MAX_VALUE ? "-1" : ans);
    }

