public class Main {
	static InputStream is;
	static PrintWriter out;
	static String INPUT = "";

	static void solve()
	{
		int n = ni();
		int[] a = na(n);
		int[] b = na(n);

		int[][] dp = new int[51][1<<n];
		int I = 999999999;
		for(int i = 0;i < 51;i++){
			Arrays.fill(dp[i], 999999999);
		}
		dp[0][0] = 0;
		for(int j = 0;j < 1<<n;j++){
			int pos = Integer.bitCount(j);
			for(int k = 0;k < n;k++){
				if(j<<~k>=0){
					int val = (pos+k&1) == 0 ? a[k] : b[k];
					int min = I;
					for(int l = 0;l <= val;l++){
						min = Math.min(min, dp[l][j]);
					}
					dp[val][j|1<<k] = Math.min(dp[val][j|1<<k], min + Integer.bitCount(~j&(1<<k)-1));
				}
			}
		}
		int min = I;
		for(int j = 0;j <= 50;j++){
			min = Math.min(min, dp[j][(1<<n)-1]);
		}
		if(min >= I){
			out.println(-1);
		}else{
			out.println(min);
		}
	}

