  static void solve(InputStream is, PrintStream os) {
    Scanner sc = new Scanner(is);

    /* read */
    int n = sc.nextInt();
    int[] a = new int[n];
    int[] b = new int[n];
    for (int i = 0; i < n; i++) {
      a[i] = sc.nextInt();
    }

    for (int i = 0; i < n; i++) {
      b[i] = sc.nextInt();
    }

    if (n == 1) {
      os.println(0);
      return;
    }

    for (long i = 0, bits = 1 << n - 1; i < bits; i++) {
      boolean[] reversed = new boolean[n];
      for (int bit = 0; bit < n; bit++) {
        reversed[bit] = ((i >> bit) & 1) == 1;
      }
      if (check(a, b, reversed, n)) {
        os.println(count(reversed));
        return;
      }
    }
    os.println(-1);
  }

  private static int count(boolean[] reversed) {
    int ans = 0;
    for (int i = 0; i < reversed.length; i++) {
      if (reversed[i]) ans++;
    }
    return ans;
  }

  private static boolean check(int[] a, int[] b, boolean[] reversed, int n) {

    int[] c = new int[n];
    int[] d = new int[n];
    for (int i = 0; i < n; i++) {
      c[i] = a[i];
      d[i] = b[i];
    }
    for (int i = 0; i < n - 1; i++) {
      if (reversed[i]) {
        int lf = c[i];
        int lb = d[i];
        int rf = c[i + 1];
        int rb = d[i + 1];
        c[i] = rb;
        d[i] = rf;
        c[i + 1] = lb;
        d[i + 1] = lf;
      }
    }

    int last = 0;
    for (int i = 0; i < n; i++) {
      if (c[i] < last) {
        return false;
      }
      last = c[i];
    }
    return true;
  }

  private static class GridPointEncoder implements Encoder<GridPoint> {

