		int N = io.nextInt();
		int[] A = io.nextInt(N), B = io.nextInt(N);
		final int INF = 1000000000;
		int ans = INF;
		Pair[] odd = new Pair[N + 1 >> 1], even = new Pair[N >> 1];
		cont: for (int i = 0;i < 1 << N;++ i) { // bit全探索
			int oddSize = 0, evenSize = 0;
			for (int j = 0;j < N;++ j) {
				if (((j ^ i >> j) & 1) == 0) { // この場合、奇数番目
					if (oddSize >= odd.length) continue cont;
					odd[oddSize++] = new Pair((i >> j & 1) == 0 ? A[j] : B[j], j);
				} else {
					if (evenSize >= even.length) continue cont;
					even[evenSize++] = new Pair((i >> j & 1) == 0 ? A[j] : B[j], j);
				}
			}
			Arrays.sort(odd);
			Arrays.sort(even);
			for (int k = 0;k < even.length;++ k) {
				if (odd[k].value > even[k].value) continue cont; // 無理
			}
			for (int k = 1;k < odd.length;++ k) {
				if (odd[k].value < even[k - 1].value) continue cont; // 無理
			}
			/*io.debugln(Integer.toBinaryString(i));
			io.debugln(odd);
			io.debugln(even);*/
			int tmp = 0; // この時の答え
			int[] sort = new int[N];
			for (int k = 0;k < odd.length;++ k) sort[k << 1] = odd[k].index;
			for (int k = 0;k < even.length;++ k) sort[k << 1 | 1] = even[k].index;
			for (int k = 0;k < N;++ k) {
				for (int l = 1;l < N;++ l) {
					if (sort[l - 1] > sort[l]) {
						sort[l - 1] ^= sort[l];
						sort[l] ^= sort[l - 1];
						sort[l - 1] ^= sort[l];
						++ tmp;
					}
				}
			}
			ans = Math.min(ans, tmp);
		}
		io.println(ans == INF ? -1 : ans);
	}

