	class Pair implements Comparable<Pair>{
		final int value;
		final int index;
		Pair(int v, int i) {
			this.value = v;
			this.index = i;
		}
		@Override
		public int compareTo(Pair o) {
			return value != o.value ? Integer.compare(value, o.value) : Integer.compare(index, o.index);
		}

		@Override
		public String toString() {
			return "{" + value + "," + index + "}";
		}
	}

	private void solve(FastIO io, String[] args) {
		/*
		 * author: 31536000
		 * キーエンスプログラミングコンテスト2020 D問題
		 * 考察メモ
		 * まず、カードのパリティを考えれば、位置によって向きは一意に定まる
		 * 各カードについて、奇数回動かすか偶数回動かすかを全部試す(2^N)
		 * この時、数列のソートする回数は転倒数
		 * ただし奇偶は守らなきゃいけないので、その場合をちゃんと考えたい
		 *
		 *
		 */
		int N = io.nextInt();
		int[] A = io.nextInt(N), B = io.nextInt(N);
		final int INF = 100000000;
		int ans = INF;
		Pair[] odd = new Pair[N + 1 >> 1], even = new Pair[N >> 1];
		cont: for (int i = 0;i < 1 << N;++ i) { // bit全探索
			int oddSize = 0, evenSize = 0;
			for (int j = 0;j < N;++ j) {
				if (((j ^ i >> j) & 1) == 0) { // この場合、奇数番目
					if (oddSize >= odd.length) continue cont;
					odd[oddSize++] = new Pair((i >> j & 1) == 0 ? A[j] : B[j], j);
				} else {
					if (evenSize >= even.length) continue cont;
					even[evenSize++] = new Pair((i >> j & 1) == 0 ? A[j] : B[j], j);
				}
			}
			Arrays.sort(odd);
			Arrays.sort(even);
			for (int k = 0;k < even.length;++ k) {
				if (odd[k].value > even[k].value) continue cont; // 無理
			}
			for (int k = 1;k < odd.length;++ k) {
				if (odd[k].value < even[k - 1].value) continue cont; // 無理
			}
			int tmp = 0; // この時の答え
			for (int k = 0;k < oddSize;++ k) tmp += Math.abs(k * 2 - odd[k].index);
			for (int k = 0;k < evenSize;++ k) tmp += Math.abs(k * 2 + 1 - even[k].index);
			ans = Math.min(ans, tmp / 2);
		}
		io.println(ans == INF ? -1 : ans);
	}

