long cal(int a[], int num) {
	BITree bit = new BITree(mm);
	long ans = 0;
	for(int i = 0; i < num; i ++) {
		ans += i - bit.sum(a[i]);
		bit.add(a[i], 1);
	}
	return ans;
}

class BITree {
	int size;
	long sumBIT[];
	BITree(int size) {
		this.size = size;
		sumBIT = new long[size + 1];
		fill(sumBIT, 0);
	}
	BITree(int size, long array[]) {
		this.size = size;
		sumBIT = new long[size + 1];
		fill(sumBIT, 0);
		for(int i = 0; i < size; i ++) {
			add(i + 1, array[i]);
		}
	}

	void add(int a, long x) {
		while(a <= size) {
			sumBIT[a] += x;
			a += Long.lowestOneBit(a);
		}
	}
	long sum(int a) {
		long sum = 0;
		while(a > 0) {
			sum += sumBIT[a];
			a -= Long.lowestOneBit(a);
		}
		return sum;
	}
	long sum(int a, int b) {
		if(a > b) { return 0; }
		else { return sum(b) - sum(a); }
	}
}

