/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        MyInput in = new MyInput(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        DSwapAndFlip solver = new DSwapAndFlip();
        solver.solve(1, in, out);
        out.close();
    }

    static class DSwapAndFlip {
        public void solve(int testNumber, MyInput in, PrintWriter out) {
            int n = in.nextInt();
            int[][] ab = new int[n][2];
            for (int i = 0; i < n; i++) {
                ab[i][0] = in.nextInt();
            }
            for (int i = 0; i < n; i++) {
                ab[i][1] = in.nextInt();
            }

            int ans = Integer.MAX_VALUE;
            int[][] val = new int[n][2];
            for (int i = 0; i < 1 << n; i++) {
                if (Integer.bitCount(i) % 2 == 1) continue;
                for (int j = 0; j < n; j++) {
                    val[j][0] = ab[j][i >>> j & 1];
                    val[j][1] = j;
                }
                Arrays.sort(val, 0, n, Comparator.comparingInt(x -> x[0]));

                int cnt = 0;
                int[] cur = new int[n];
                for (int j = 0; j < n; j++) cur[j] = j;
                for (int j = 0; j < n; j++) {
                    for (int k = j; k < n; k++) {
                        if (val[k][0] == val[k][1] && ((i >>> j & 1) == 0) == (val[k][1] % 2 == j % 2)) {
                            if (pos(cur, val[j][1]) > pos(cur, val[k][1])) {
                                swap(val, j, k);
                            }
                        }
                    }
                    boolean ok = ((i >>> j & 1) == 0) == (val[j][1] % 2 == j % 2);
                    if (ok) {
                        cnt += move(cur, val[j][1], j);
                    } else {
                        cnt = Integer.MAX_VALUE;
                        break;
                    }
                }
//            if (cnt != Integer.MAX_VALUE) {
//                dump(i, Arrays.copyOf(val[0], len[0]), Arrays.copyOf(val[1], len[1]), cur);
//            }
                ans = Math.min(ans, cnt);
            }
            if (ans == Integer.MAX_VALUE) ans = -1;
            out.println(ans);
        }

        int pos(int[] cur, int id) {
            for (int j = 0; j < cur.length; j++) {
                if (cur[j] == id) return j;
            }
            throw new RuntimeException();
        }

        int move(int[] cur, int id, int i) {
            int p = pos(cur, id);
            int res = 0;
            while (p > i) {
                res++;
                swap(cur, p, p - 1);
                p--;
            }
            return res;
        }

        static void swap(int[] xs, int i, int j) {
            int t = xs[i];
            xs[i] = xs[j];
            xs[j] = t;
        }

        static <T> void swap(T[] xs, int i, int j) {
            T t = xs[i];
            xs[i] = xs[j];
            xs[j] = t;
        }

    }

    static class MyInput {
        private final BufferedReader in;
        private static int pos;
        private static int readLen;
        private static final char[] buffer = new char[1024 * 8];
        private static char[] str = new char[500 * 8 * 2];
        private static boolean[] isDigit = new boolean[256];
        private static boolean[] isSpace = new boolean[256];
        private static boolean[] isLineSep = new boolean[256];

        static {
            for (int i = 0; i < 10; i++) {
                isDigit['0' + i] = true;
            }
            isDigit['-'] = true;
            isSpace[' '] = isSpace['\r'] = isSpace['\n'] = isSpace['\t'] = true;
            isLineSep['\r'] = isLineSep['\n'] = true;
        }

        public MyInput(InputStream is) {
            in = new BufferedReader(new InputStreamReader(is));
        }

        public int read() {
            if (pos >= readLen) {
                pos = 0;
                try {
                    readLen = in.read(buffer);
                } catch (IOException e) {
                    throw new RuntimeException();
                }
                if (readLen <= 0) {
                    throw new MyInput.EndOfFileRuntimeException();
                }
            }
            return buffer[pos++];
        }

        public int nextInt() {
            int len = 0;
            str[len++] = nextChar();
            len = reads(len, isSpace);
            int i = 0;
            int ret = 0;
            if (str[0] == '-') {
                i = 1;
            }
            for (; i < len; i++) ret = ret * 10 + str[i] - '0';
            if (str[0] == '-') {
                ret = -ret;
            }
            return ret;
        }

        public char nextChar() {
            while (true) {
                final int c = read();
                if (!isSpace[c]) {
                    return (char) c;
                }
            }
        }

        int reads(int len, boolean[] accept) {
            try {
                while (true) {
                    final int c = read();
                    if (accept[c]) {
                        break;
                    }
                    if (str.length == len) {
                        char[] rep = new char[str.length * 3 / 2];
                        System.arraycopy(str, 0, rep, 0, str.length);
                        str = rep;
                    }
                    str[len++] = (char) c;
                }
            } catch (MyInput.EndOfFileRuntimeException e) {
            }
            return len;
        }

        static class EndOfFileRuntimeException extends RuntimeException {
        }

    }
}

