	static class InputReader { 
		private InputStream in;
		private byte[] buffer = new byte[1024];
		private int curbuf;
		private int lenbuf;
		public InputReader(InputStream in) {
			this.in = in;
			this.curbuf = this.lenbuf = 0;
		}

		public boolean hasNextByte() {
			if (curbuf >= lenbuf) {
				curbuf = 0;
				try {
					lenbuf = in.read(buffer);
				} catch (IOException e) {
					throw new InputMismatchException();
				}
				if (lenbuf <= 0)
					return false;
			}
			return true;
		}

		private int readByte() {
			if (hasNextByte())
				return buffer[curbuf++];
			else
				return -1;
		}

		private boolean isSpaceChar(int c) {
			return !(c >= 33 && c <= 126);
		}

		private void skip() {
			while (hasNextByte() && isSpaceChar(buffer[curbuf]))
				curbuf++;
		}

		public boolean hasNext() {
			skip();
			return hasNextByte();
		}

		public String next() {
			if (!hasNext())
				throw new NoSuchElementException();
			StringBuilder sb = new StringBuilder();
			int b = readByte();
			while (!isSpaceChar(b)) {
				sb.appendCodePoint(b);
				b = readByte();
			}
			return sb.toString();
		}

		public int nextInt() {
			if (!hasNext())
				throw new NoSuchElementException();
			int c = readByte();
			while (isSpaceChar(c))
				c = readByte();
			boolean minus = false;
			if (c == '-') {
				minus = true;
				c = readByte();
			}
			int res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res = res * 10 + c - '0';
				c = readByte();
			} while (!isSpaceChar(c));
			return (minus) ? -res : res;
		}

		public long nextLong() {
			if (!hasNext())
				throw new NoSuchElementException();
			int c = readByte();
			while (isSpaceChar(c))
				c = readByte();
			boolean minus = false;
			if (c == '-') {
				minus = true;
				c = readByte();
			}
			long res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res = res * 10 + c - '0';
				c = readByte();
			} while (!isSpaceChar(c));
			return (minus) ? -res : res;
		}

		public double nextDouble() {
			return Double.parseDouble(next());
		}

		public int[] nextIntArray(int n) {
			int[] a = new int[n];
			for (int i = 0; i < n; i++)
				a[i] = nextInt();
			return a;
		}

		public long[] nextLongArray(int n) {
			long[] a = new long[n];
			for (int i = 0; i < n; i++)
				a[i] = nextLong();
			return a;
		}

		public char[][] nextCharMap(int n, int m) {
			char[][] map = new char[n][m];
			for (int i = 0; i < n; i++)
				map[i] = next().toCharArray();
			return map;
		}
	}
	}

import java.util.*;
import java.util.stream.Collectors;
import java.io.*;
import java.nio.charset.StandardCharsets;

public class Main {
	int N;
	int[] A, B;
	int result = 0;

	static class Tuple {
		int count;
		List<Integer> a, b;

		Tuple() {
			this.count = 0;
			this.a = new ArrayList<>();
			this.b = new ArrayList<>();
		}

		boolean checkCond() {
			// aが降順になっていることが条件
			boolean good = true;
			for (int i = 0; i + 1 < a.size(); ++i) {
				if (a.get(i) < a.get(i + 1)) {
					good = false;
					break;
				}
			}
			return good;
		}

		void show() {
			StringBuilder strBuilder = new StringBuilder();
			strBuilder.append(a.get(0));
			for (int i = 1; i < a.size(); ++i) {
				strBuilder.append(", " + a.get(i));
			}
			System.out.println(strBuilder.toString());
		}
	}

	public static void main(String[] args) throws IOException {
		InputStreamReader reader = new InputStreamReader(System.in, StandardCharsets.UTF_8);
		BufferedReader in = new BufferedReader(reader);
		Main ins = new Main(in);
		ins.calc();
		ins.showResult();
	}

	Main(BufferedReader in) throws IOException {
		this.N = Integer.parseInt(in.readLine());
		this.A = new int[N];
		this.B = new int[N];
		String[] tokens = in.readLine().split(" ");
		for (int i = 0; i < N; ++i) {
			A[i] = Integer.parseInt(tokens[i]);
		}
		tokens = in.readLine().split(" ");
		for (int i = 0; i < N; ++i) {
			B[i] = Integer.parseInt(tokens[i]);
		}
	}

	void swap(int[] a, int[] b, int i) {
		int tempA = a[i];
		int tempB = b[i];
		a[i] = b[i + 1];
		b[i] = a[i + 1];
		a[i + 1] = tempB;
		b[i + 1] = tempA;
	}

	List<Tuple> gen(int[] a, int[] b) {
		if (a.length == 1) {
			Tuple t0 = new Tuple();
			t0.a.add(a[0]);
			t0.b.add(b[0]);
			List<Tuple> list = new ArrayList<>(1);
			list.add(t0);
			return list;
		} else {
			int[] newA = Arrays.copyOf(a, a.length);
			int[] newB = Arrays.copyOf(b, b.length);
			int[] invA = Arrays.copyOf(a, a.length);
			int[] invB = Arrays.copyOf(b, b.length);

			swap(invA, invB, 0);
			List<Tuple> list0 = gen(Arrays.copyOfRange(newA, 1, newA.length), Arrays.copyOfRange(newB, 1, newB.length));
			List<Tuple> list1 = gen(Arrays.copyOfRange(invA, 1, invA.length), Arrays.copyOfRange(invB, 1, invB.length));
			List<Tuple> list = new ArrayList<>(list0.size() + list1.size());
			for (Tuple t : list0) {
				Tuple tuple = new Tuple();
				tuple.a.addAll(t.a);
				tuple.b.addAll(t.b);
				tuple.a.add(newA[0]);
				tuple.b.add(newB[0]);
				tuple.count = t.count;
				list.add(tuple);
			}
			for (Tuple t : list1) {
				Tuple tuple = new Tuple();
				tuple.a.addAll(t.a);
				tuple.b.addAll(t.b);
				tuple.a.add(invA[0]);
				tuple.b.add(invB[0]);
				tuple.count = t.count + 1;
				list.add(tuple);
			}
			return list;
		}
	}

	void calc() {
		List<Tuple> list = gen(A, B);
		list = list.stream().filter(x -> x.checkCond()).collect(Collectors.toList());
		Collections.sort(list, new Comparator<Tuple>() {
			@Override
			public int compare(Tuple o1, Tuple o2) {
				return Integer.compare(o1.count, o2.count);
			}
		});
		if (list.size() == 0) {
			result = -1;
		} else {
			result = list.get(0).count;
		}
	}

	void showResult() {
		System.out.println(result);
	}
}

