public class Main {

    static Set<List<Integer>> cache = new HashSet<>();
    static Queue<List<Integer>> queue = new LinkedList<>();

    static void solve() {
        int n = nextInt();
        List<Integer> a = nextIntList(n);
        List<Integer> b = nextIntList(n);

        a.addAll(b);
        a.add(0);
        queue.add(a);
