    static int bfs() {
        while (!queue.isEmpty()) {
            List<Integer> list = queue.poll();
            List<Integer> a = list.subList(0, (list.size() - 1) / 2);
            List<Integer> b = list.subList((list.size() - 1) / 2, list.size() - 1);
            int count = list.get(list.size() - 1);

            if (isSorted(a))
                return count;

            for (int i = 0; i < a.size() - 1; i++) {
                List<Integer> copyA = new ArrayList<>(a);
                List<Integer> copyB = new ArrayList<>(b);
                int prevA = copyA.get(i);
                int prevB = copyB.get(i);
                copyA.set(i, b.get(i + 1));
                copyB.set(i, a.get(i + 1));
                copyA.set(i + 1, prevB);
                copyB.set(i + 1, prevA);
                List<Integer> key = new ArrayList<>(copyA);
                key.addAll(copyB);
//                debug(() -> key.toString());
                if (!cache.contains(key)) {
                    cache.add(key);
                    List<Integer> key2 = new ArrayList<>(key);
                    key2.add(count + 1);
                    queue.add(key2);
                }
            }
        }
        return -1;
    }

    static boolean isSorted(List<Integer> a) {
        int prev = Integer.MIN_VALUE;
        for (int i = 0; i < a.size(); i++) {
            if (a.get(i) < prev)
                return false;
            prev = a.get(i);
        }
        return true;
    }

    static final int MOD = 1_000_000_007;
    static long[] fac, finv, inv;

    // 階乗(n!)
    static long factorial(long n) {
        long ans = 1;
        for (long i = n; i > 0; i--) {
            ans = ans * i % MOD;
        }
        return ans;
    }

    // nCkの初期化
    static void comInit(int max) {
        fac = new long[max];
        finv = new long[max];
        inv = new long[max];
        fac[0] = fac[1] = 1;
        finv[0] = finv[1] = 1;
        inv[1] = 1;

        for (int i = 2; i < max; i++) {
            fac[i] = fac[i - 1] * i % MOD;
            inv[i] = MOD - inv[MOD % i] * (MOD / i) % MOD;
            finv[i] = finv[i - 1] * inv[i] % MOD;
        }
    }

    // nCkの計算
    static long com(int n, int k) {
        if (n < k)
            return 0;
        if (n < 0 || k < 0)
            return 0;
        return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
    }

    // 2〜nまでの数値を素因数分解したmapを返す.
    // map: 数値 -> (素因数)
    // ex)
    // 2 -> (2)
    // 4 -> (2,2)
    // 12 -> (2,2,3)
    static Map<Integer, List<Integer>> primeFactorizeTo(int n) {
        Map<Integer, List<Integer>> map = new HashMap<>();
        for (int i = 2; i <= n; i++) {
            List<Integer> list = new ArrayList<>();
            int tmp = i;
            for (int j = i - 1; j > 1; j--) {
                if (tmp % j == 0) {
                    if (map.containsKey(j)) {
                        list.addAll(map.get(j));
                    } else {
                        list.add(j);
                    }
                    tmp /= j;
                }
            }
            if (tmp != 1)
                list.add(tmp);
            map.put(i, list);
        }
        return map;
    }

