class Main {
    static In in = new In();
    static Out out = new Out();
    static long mod = 1000000007;
    static long inf = 0xfffffffffffffffL;

    int[] a, b;
    void solve() {
        int n = in.nextInt();
        a = in.nextIntArray(n);
        b = in.nextIntArray(n);
        int ans = -1;
        for (int i = 0; i < 1 << n; i++) {
            int mask = 0;
            int count = 0;
            for (int j = 0; j < n; j++) {
                for (int k = 0; k < j; k++) {
                    if (get(i, k) > get(i, j)) {
                        mask ^= 1 << j;
                        mask ^= 1 << k;
                        count++;
                    }
                }
            }
            int xor = mask ^ i;
            int[] c = new int[51];
            for (int j = 0; j < n; j++) {
                c[get(i, j)] ^= (xor >> j) & 1;
            }
            int add = 0;
            for (int j = 0; j < n; j++) {
                if (((xor >> j) & 1) == 1) {
                    xor ^= 3 << j;
                    add++;
                }
            }
            boolean can = true;
            for (int j : c) {
                can &= j == 0;
            }
            if (i != mask && can) {
                count += add;
                ans = ans == -1 ? count : Math.min(ans, count);
            }
            if (i == mask) {
                ans = ans == -1 ? count : Math.min(ans, count);
            }
        }
        out.println(ans);
    }

    int get(int flags, int i) {
        return ((flags >> i) & 1) == 1 ? b[i] : a[i];
    }

    public static void main(String[]$) {
        new Main().solve();
        out.flush();
    }
}

