public void solve() {
	int num = ni();
	int a[][] = ni(2, num);
	int maxBit = (int)bitFlag(num);
	int b[] = new int[num];
	long min = INF;
	for(long bit = 0; bit < maxBit; bit ++) {
		for(int i = 0; i < num; i ++) {
			b[i] = a[isFlagged(bit, i) ? 1 : 0][i];
		}
		long need = cal(b, num);
		long b2[][] = new long[num][3];
		for(int i = 0; i < num; i ++) {
			b2[i][0] = b[i];
			b2[i][1] = i;
			b2[i][2] = isFlagged(bit, i) ? 1 : 0;
		}
		Arrays.sort(b2, (x, y) -> Long.compare(x[0], y[0]));
		for(int i = 0; i < num; i ++) {
			b2[i][2] ^= (abs(b2[i][1] - i) % 2 != 0) ? 1 : 0;
		}
		boolean ok = true;
		for(int i = 1; i < num; i ++) {
			if(b2[i - 1][0] == b2[i][0]) {
				if(b2[i - 1][2] != 0) {
					b2[i][2] ^= b2[i - 1][2];
					b2[i - 1][2] = 0;
					need ++;
				}
			}
		}
		for(int i = 0; i < num; i ++) {
			ok &= b2[i][2] == 0;
		}

		long cnt[][] = new long[mm][2]; // even odd
		fill(cnt, 0);
		for(int i = 0; i < num; i ++) {
			int index = (isFlagged(bit, i) ? 1 : 0) ^ (i % 2 != 0 ? 1 : 0);
			cnt[b[i]][index] ++;
		}
		Arrays.sort(b);
		long cnt2[][] = new long[mm][2]; // even odd
		fill(cnt2, 0);
		for(int i = 0; i < num; i ++) {
			int index = i % 2 != 0 ? 1 : 0;
			cnt2[b[i]][index] ++;
		}
		for(int i = 0; i < 55; i ++) {
			ok &= cnt[i][0] == cnt2[i][0];
			ok &= cnt[i][1] == cnt2[i][1];
		}

		if(!ok) { continue; }

		min = min(need, min);
	}
	if(isINF(min)) { min = -1; }
	prtln(min);
}

long cal(int a[], int num) {
	BITree bit = new BITree(mm);
	long ans = 0;
	for(int i = 0; i < num; i ++) {
		ans += i - bit.sum(a[i]);
		bit.add(a[i], 1);
	}
	return ans;
}

class BITree {
	int size;
	long sumBIT[];
	BITree(int size) {
		this.size = size;
		sumBIT = new long[size + 1];
		fill(sumBIT, 0);
	}
	BITree(int size, long array[]) {
		this.size = size;
		sumBIT = new long[size + 1];
		fill(sumBIT, 0);
		for(int i = 0; i < size; i ++) {
			add(i + 1, array[i]);
		}
	}

	void add(int a, long x) {
		while(a <= size) {
			sumBIT[a] += x;
			a += Long.lowestOneBit(a);
		}
	}
	long sum(int a) {
		long sum = 0;
		while(a > 0) {
			sum += sumBIT[a];
			a -= Long.lowestOneBit(a);
		}
		return sum;
	}
	long sum(int a, int b) {
		if(a > b) { return 0; }
		else { return sum(b) - sum(a); }
	}
}

