			for (int i = 0; i < n - 1; i++) {
				if (((mask >> i) & 1) == 1) {
					swap(lol, i);
					flip(lol, i);
					flip(lol, i + 1);
				}
			}

			boolean sorted = true;
			for (int i = 1; i < n; i++) {
				if (lol[i][0] < lol[i - 1][0]) {
					sorted = false;
					break;
				}
			}

			if (sorted) {
				moves = Math.min(moves, Integer.bitCount(mask));
			}
		}

		if (moves == n + 1) {
			moves = -1;
		}

		out.println(moves);
	}

	void swap(int[][] lol, int i) {
		for(int j = 0; j < 2; j++) {
			int temp = lol[i][j];
			lol[i][j] = lol[i + 1][j];
			lol[i + 1][j] = temp;
		}
	}

	void flip(int[][] lol, int i) {
		int temp = lol[i][0];
		lol[i][0] = lol[i][1];
		lol[i][1] = temp;
	}

