		fill(dp, inf);
		dp[0][0] = 0;
		for(int i=0;i<1<<n;i++) {
			int bc = Integer.bitCount(i);//次はbc番目にくる
			for(int s=0;s<=50;s++) {//s全ての末尾の値から、場合の数を配る
				if(dp[i][s]==inf) continue;//infなら場合の数は存在しない
				for(int j=0;j<n;j++) {//bitが0の物を次に利用する
					if((i>>j&1)==0) {
