public class Main {

  static FastScanner sc = new FastScanner();
  static Output out = new Output(System.out);

  static final int[] dx = {0, 1, 0, -1};
  static final int[] dy = {-1, 0, 1, 0};

  static final long MOD = (long) (1e9 + 7);
  static final int INF = (int)1e9;

  static final int e5 = (int) 1e5;

  public static class Solver {

    public class Card {
      int a, b, index;
      public Card(int a, int b, int index) {
        this.a = a;
        this.b = b;
        this.index = index;
      }
      public int value(int i) {
        return Math.abs(i-index) % 2 == 0 ? a : b;
      }
    }

    public int dfs(int N, int index, Card[] cards, int[] numbers, ArrayList<Integer> list) {

      if (index == N) return 0;

      int res = INF;
      for (int i=0; i<N; i++) {
        int v = cards[i].value(index);
        if ((index == 0 || v >= cards[list.get(index-1)].value(index-1)) && (v <= numbers[N+index]) && !list.contains(i)) {
          list.add(i);
          int count = 0;
          for (int j=0; j<list.size(); j++) {
            if (list.get(j) > i) count++;
          }
          res = Math.min(res, Math.abs(cards[i].index+count-index) + dfs(N, index+1, cards, numbers, list));
          //out.print(list, " ");
          //out.println(index + ", " + res);
          list.remove(index);
        }
      }

      return res;
    }

    public Solver() {

      int N = sc.nextInt();

      int[] A = sc.nextIntArray(N, false);
      int[] B = sc.nextIntArray(N, false);

      Card[] cards = new Card[N];
      int[] numbers = new int[2*N];
      for (int i=0; i<N; i++) {
        cards[i] = new Card(A[i], B[i], i);
        numbers[2*i] = A[i];
        numbers[2*i+1] = B[i];
      }

      Arrays.sort(numbers);

      int ans = dfs(N, 0, cards, numbers, new ArrayList<Integer>());

      out.println(ans == INF ? -1 : ans);

    }
  }

  public static void main(String[] args) {
    new Solver();
    out.flush();
  }

