class Main{
    static int n;
    static int[][] ud;
    public static void main(String[] args){
        FastScanner fsc=new FastScanner();
        n=fsc.nextInt();
        int[] a=new int[n];
        int[] b=new int[n];
        for(int i=0;i<n;i++){
            a[i]=fsc.nextInt();
        }
        for(int i=0;i<n;i++){
            b[i]=fsc.nextInt();
        }
        fsc.close();
        ud=new int[n+1][1<<n];
        for(int i=1;i<=n;i++){
            for(int j=0;j<(1<<i);j++){
                if(j==0){
                    ud[i][j]=0;
                } else{
                    ud[i][j]=-1;
                }
            }
            ArrayDeque<IJK> dq=new ArrayDeque<>();
            dq.add(new IJK(i, 0, 0));
            while(!dq.isEmpty()){
                IJK ijk=dq.pollFirst();
                for(int bt=0;bt<i-1;bt++){
                    int l=ijk.j&(1<<(bt+1));
                    int r=ijk.j&(1<<bt);
                    int mask=(1<<(bt+1))+(1<<bt);
                    if((r<<1)==l && ud[ijk.i][ijk.j^mask]<0){
                        ud[ijk.i][ijk.j^mask]=ijk.k+1;
                        dq.addLast(new IJK(ijk.i, ijk.j^mask, ijk.k+1));
                    }
                }
            }
        }
        // for(int i=1;i<=n;i++){
        //     for(int j=0;j<(1<<i);j++){
        //         String jbin=String.format("%0"+i+"d", Long.valueOf(Integer.toString(j, 2))); 
        //         System.out.print("ud["+i+"]["+jbin+"]: "+ud[i][j]+" ");
        //     }
        //     System.out.println();
        // }
        int max=Integer.MAX_VALUE;
        int min=max;
        L:for(int i=0;i<(1<<n);i++){
            boolean[] slcta=new boolean[n];
            int[] res=new int[n];
            BinaryIndexedTree bit=new BinaryIndexedTree(50);
            for(int bt=0;bt<n;bt++){
                slcta[bt]=(i&(1<<bt))!=0;
                res[bt]=slcta[bt]?a[bt]:b[bt];
            }
            int inversion=0;
            int cnt=0;
            int cond=0;
            for(int j=0;j<n;j++){
                inversion+=bit.sum(res[j], 50);
                if((slcta[j] && (bit.sum(res[j])-j)%2!=0) ||
                    (!slcta[j] && (bit.sum(res[j])-j)%2==0)){
                    cond+=1<<cnt;
                }
                if(j==n-1){
                    if(ud[cnt+1][cond]>=0){
                        min=Math.min(min, inversion+=ud[cnt+1][cond]);
                    }
                } else if(res[j]!=res[j+1]){
                    if(ud[cnt+1][cond]>=0){
                        inversion+=ud[cnt+1][cond];
                    } else{
                        continue L;
                    }
                    cnt=0;
                } else if(res[j]==res[j+1]){
                    cnt++;
                }
                bit.add(res[j], 1);
            }
        }
        System.out.println(min<max?min:-1);
    }

    static class IJK{
        int i, j, k;
        IJK(int i, int j, int k){
            this.i=i; this.j=j;this.k=k;
        }
    }

    static class BinaryIndexedTree{
        private int[] bit;
        private int[] originalArray;
        private int n;
        /**
         * @param array 0-indexed array.
         */
        public BinaryIndexedTree(int[] array){
            this.originalArray=array.clone();
            this.n=array.length;
            this.bit=new int[n+1];
            init();
        }
        public BinaryIndexedTree(int initial, int n){
            this.originalArray=new int[n];
            this.n=n;
            this.bit=new int[n+1];
            for(int i=0;i<n;originalArray[i++]=initial);
            init();
        }
        public BinaryIndexedTree(int n){
            this(0, n);
        }
        private void init(){
            for(int i=1;i<=n;i++){
                bit[i]+=originalArray[i-1];
                if(i+(-i&i)<=n){
                    bit[i+(-i&i)]+=bit[i];
                }
            }
        }

        /**
         * Calculate the sum of range (l, r] in array (1-indexed).
         * @param l left border (open)
         * @param r right border (closed)
         * @return sum of range (l, r] in array (1-indexed).
         */
        public int sum(int l, int r){
            return sum(r)-sum(l);
        }
        public int sum(int r){
            int ret=0;
            for(;r>0;r-=-r&r){
                ret+=bit[r];
            }
            return ret;
        }
        public int sum(){
            return sum(n);
        }

        /**
         * add v to array[i] and update BIT.
         * @param i index of array (1-indexed)
         * @param v adding value
         */
        public void add(int i, int v){
            originalArray[i-1]+=v;
            for(;i<=n;i+=-i&i){
                bit[i]+=v;
            }
        }

        /**
         * update the value of array[i] to v and update BIT.
         * @param i index of array (1-indexed)
         * @param v adding value
         */
        public void update(int i, int v){
            add(i, v-originalArray[i-1]);
            originalArray[i]=v;
        }

        @Override
        public String toString(){
            int msb=0;
            for(int m=n;m>>1!=0;m>>=1, msb++);
            char[][] c=new char[msb+1][1<<(2*msb+1)];
            int[] indx=new int[msb+1];
            for(int i=1;i<=n;i++){
                int j=0;
                for(int l=-i&i;l>>1!=0;l>>=1, j++);
                char[] intc=Integer.toString(bit[i]).toCharArray();
                int intl=intc.length;
                c[j][indx[j]]='[';
                c[j][indx[j]+(1<<(j+2))-1]=']';
                int st=indx[j]+(1<<(j+1))-intl/2-1;
                for(int l=0;l<intl;l++){
                    c[j][st+l]=intc[l];
                }
                indx[j]+=1<<(j+3);
            }
            StringBuilder sb=new StringBuilder();
            for(int i=msb;i>=0;sb.append(String.valueOf(c[i--])).append("\n"));
            return sb.toString();
        }
    }

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;
        private boolean hasNextByte(){
            if(ptr<buflen) return true;
            else{
                ptr = 0;
                try{
                    buflen = in.read(buffer);
                }
                catch(IOException e){
                    e.printStackTrace();
                }
                if(buflen<=0) return false;
            }
        return true;
        }
        private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
        private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
        public boolean hasNext() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++; return hasNextByte();}
        public String next() {
            if (!hasNext()) throw new NoSuchElementException();
            StringBuilder sb = new StringBuilder();
            int b = readByte();
            while(isPrintableChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }
        public long nextLong() {
            if (!hasNext()) throw new NoSuchElementException();
            long n = 0;
            boolean minus = false;
            int b = readByte();
            if (b == '-') {
                minus = true;
                b = readByte();
            }
            if (b < '0' || '9' < b) throw new NumberFormatException();
            while(true){
                if ('0' <= b && b <= '9') {
                    n *= 10;
                    n += b - '0';
                }
                else if(b == -1 || !isPrintableChar(b)) return minus ? -n : n;
                else throw new NumberFormatException();
                b = readByte();
            }
        }
        public int nextInt() {
            long nl = nextLong();
            if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
            return (int) nl;
        }
        public double nextDouble() { return Double.parseDouble(next());}
        public void close(){
            try{in.close();}
            catch(IOException e){e.printStackTrace();}
        }
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.lang.reflect.Field;
import java.util.Arrays;
import java.util.NoSuchElementException;
import java.util.function.IntUnaryOperator;
import java.util.function.LongUnaryOperator;
import static java.lang.Math.max;
import static java.lang.Math.min;



public class Main {
    public static void main(String[] args) throws Exception {
        Field f = System.out.getClass().getDeclaredField("autoFlush");
        f.setAccessible(true);
        f.set(System.out, false);
        execute(System.in, System.out);
    }

    public static void execute(InputStream in, OutputStream out) {
        ExtendedScanner s = new ExtendedScanner(System.in);
        Out o = new Out(System.out);
        solve(s, o);
        o.flush();
        o.close();
    }

    public static void solve(ExtendedScanner sc, Out out) {
        int n = sc.nextInt();
        int[] a = sc.ints(n);
        int[] b = sc.ints(n);
        int[] x = new int[n];
        int inf = 1000000000;
        int min = inf;
        for (int i = 0; i < 1 << n; i++) {
            for (int j = 0; j < n; j++) {
                if ((i & (1 << j)) == 0) {
                    x[j] = a[j];
                } else {
                    x[j] = ~b[j];
                }
            }
            int c = 0;
            for (int p = 0; p < n - 1; p++) {
                for (int q = n - 1; q > p; q--) {
                    if (max(x[q - 1], ~x[q - 1]) > max(x[q], ~x[q])) {
                        int tmp = x[q - 1];
                        x[q - 1] = ~x[q];
                        x[q] = ~tmp;
                        c++;
                    }
                }
            }
            boolean ok = true;
            for (int j = 0; j < n - 1; j++) {
                if (x[j] < 0) {
                    if (x[j] != x[j + 1]) {
                        ok = false;
                    }
                    int tmp = x[j];
                    x[j] = ~x[j + 1];
                    x[j + 1] = ~tmp;
                    c++;
                }
            }
            for (int j = 0; j < n; j++) {
                if (x[j] < 0) {
                    ok = false;
                }
            }
            if (ok) {
                min = min(min, c);
            }
        }
        out.write(min == inf ? -1 : min).write('\n');
    }
}


class BasicScanner {
    private final InputStream in;
    private final byte[] buf = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;
    public BasicScanner(InputStream in) {this.in = in;}
    private boolean hasNextByte() {
        if (ptr < buflen) return true;
        ptr = 0;
        try {buflen = in.read(buf);}
        catch (final IOException e) {e.printStackTrace();}
        return buflen > 0;
    }
    private int readByte() {return hasNextByte() ? buf[ptr++] : -1;}
    public boolean hasNext() {
        while (hasNextByte() && !(33 <= buf[ptr] && buf[ptr] <= 126)) ptr++;
        return hasNextByte();
    }
    private StringBuilder nextSequence() {
        if (!hasNext()) throw new NoSuchElementException();
        final StringBuilder sb = new StringBuilder();
        int b = readByte();
        while (33 <= b && b <= 126) {sb.appendCodePoint(b); b = readByte();}
        return sb;
    }
    public char nextChar() {
        return (char) readByte();
    }
    public String next() {
        return nextSequence().toString();
    }
    public String next(int len) {
        return new String(nextChars(len));
    }
    public char[] nextChars() {
        final StringBuilder sb = nextSequence();
        int l = sb.length();
        char[] dst = new char[l];
        sb.getChars(0, l, dst, 0);
        return dst;
    }
    public char[] nextChars(int len) {
        if (!hasNext()) throw new NoSuchElementException();
        char[] s = new char[len];
        int i = 0;
        int b = readByte();
        while (33 <= b && b <= 126 && i < len) {s[i++] = (char) b; b = readByte();}
        if (i != len) throw new NoSuchElementException(String.format("length %d is longer than the sequence.", len));
        return s;
    }
    public long nextLong() {
        if (!hasNext()) throw new NoSuchElementException();
        long n = 0;
        boolean minus = false;
        int b = readByte();
        if (b == '-') {minus = true; b = readByte();}
        if (b < '0' || '9' < b) throw new NumberFormatException();
        while (true) {
            if ('0' <= b && b <= '9') n = n * 10 + b - '0';
            else if (b == -1 || !(33 <= b && b <= 126)) return minus ? -n : n;
            else throw new NumberFormatException();
            b = readByte();
        }
    }
    public int nextInt() {return Math.toIntExact(nextLong());}
    public double nextDouble() {return Double.parseDouble(next());}
}


class Out {
    private final OutputStream out;
    private byte[] buf = new byte[1024];
    private int ptr = 0;
    private static final int AUTO_FLUSH_THRETHOLD = 1 << 17;

    public Out(OutputStream out) {
        this.out = out;
    }

    public void flush() {
        try {
            out.write(buf, 0, ptr);
            out.flush();
            ptr = 0;
        } catch (IOException e) {e.printStackTrace();}
    }

    public void close() {
        try {out.close();} catch (IOException e) {e.printStackTrace();}
    }

    public Out write(Object o) {
        return write(o.toString());
    }

    public Out write(String s) {
        try {
            Field strValueField = s.getClass().getDeclaredField("value");
            strValueField.setAccessible(true);
            byte[] b = (byte[]) strValueField.get(s);
            int l = s.length();
            if (l > AUTO_FLUSH_THRETHOLD) {
                flush();
                int i = 0;
                while (i + AUTO_FLUSH_THRETHOLD < l) {
                    out.write(b, i, AUTO_FLUSH_THRETHOLD);
                    out.flush();
                    i += AUTO_FLUSH_THRETHOLD;
                }
                ensureCapacity(l - i);
                System.arraycopy(b, i, buf, 0, l - i);
                ptr = l - i;
            } else {
                ensureCapacity(ptr + l);
                System.arraycopy(b, 0, buf, ptr, l);
                ptr += l;
            }
        } catch (Exception e) {e.printStackTrace();}
        return this;
    }

    public Out write(char[] c) {
        int l = c.length;
        if (l > AUTO_FLUSH_THRETHOLD) {
            flush();
            ensureCapacity(AUTO_FLUSH_THRETHOLD);
            int i = 0;
            while (i + AUTO_FLUSH_THRETHOLD < l) {
                for (int j = 0; j < AUTO_FLUSH_THRETHOLD; j++) {
                    buf[ptr++] = (byte) c[i + j];
                }
                flush();
                i += AUTO_FLUSH_THRETHOLD;
            }
            for (; i < l; i++) {
                buf[ptr++] = (byte) c[i];
            }
        } else {
            ensureCapacity(ptr + l);
            for (char ch : c) buf[ptr++] = (byte) ch;
        }
        return this;
    }

    public Out write(char c) {
        ensureCapacity(ptr + 1);
        buf[ptr++] = (byte) c;
        return this;
    }

    public Out write(byte b) {
        ensureCapacity(ptr + 1);
        buf[ptr++] = b;
        return this;
    }

    public Out write(int x) {
        if (x == 0) {
            ensureCapacity(ptr + 1);
            buf[ptr++] = '0';
            return this;
        }
        int d = stringSize(x);
        ensureCapacity(ptr + d);
        if (x < 0) {
            buf[ptr++] = '-';
            x = -x;
            d--;
        }
        int j = ptr + d; 
        while (x > 0) {
            buf[--j] = (byte) ('0' + (x % 10));
            x /= 10;
        }
        ptr += d;
        return this;
    }

    public Out write(long x) {
        if (x == 0) {
            ensureCapacity(ptr + 1);
            buf[ptr++] = '0';
            return this;
        }
        int d = stringSize(x);
        ensureCapacity(ptr + d);
        if (x < 0) {
            buf[ptr++] = '-';
            x = -x;
            d--;
        }
        int j = ptr + d; 
        while (x > 0) {
            buf[--j] = (byte) ('0' + (x % 10));
            x /= 10;
        }
        ptr += d;
        return this;
    }

    public Out write(double d) {
        return write(Double.toString(d));
    }

    private void ensureCapacity(int cap) {
        if (cap > AUTO_FLUSH_THRETHOLD) {
            flush();
        }
        if (cap >= buf.length) {
            int newLength = buf.length;
            while (newLength < cap) newLength <<= 1;
            byte[] newBuf = new byte[newLength];
            System.arraycopy(buf, 0, newBuf, 0, buf.length);
            buf = newBuf;
        }
    }
    private static int stringSize(long x) {
        int d = 1;
        if (x >= 0) {d = 0; x = -x;}
        long p = -10;
        for (int i = 1; i < 19; i++, p *= 10) if (x > p) return i + d;
        return 19 + d;
    }
    private static int stringSize(int x) {
        int d = 1;
        if (x >= 0) {d = 0; x = -x;}
        int p = -10;
        for (int i = 1; i < 10; i++, p *= 10) if (x > p) return i + d;
        return 10 + d;
    }
}


