import java.util.function.IntUnaryOperator;
import java.util.function.LongUnaryOperator;

class Main {
    static In in = new In();
    static Out out = new Out();
    static long mod = 1000000007;
    static long inf = 0xfffffffffffffffL;

    int[] a, b;
    void solve() {
        int n = in.nextInt();
        a = in.nextIntArray(n);
        b = in.nextIntArray(n);
        long ans = inf;
        for (int i = 0; i < 1 << n; i++) {
            int[] c = new int[n];
            int[] d = new int[n];
            for (int j = 0; j < n; j++) {
                c[j] = ((i >> j) & 1);
                d[j] = get(i, j);
            }
            int count = 0;
            for (int j = 0; j < n; j++) {
                int last = j;
                for (int k = j - 1; k >= 0; k--) {
                    if (d[k] > d[j]) {
                        last = k;
                    }
                }
                for (int k = j; k > last; k--) {
                    count++;
                    c[k]++;
                    c[k - 1]++;
                    int tmp = c[k];
                    c[k] = c[k - 1];
                    c[k - 1] = tmp;
                    tmp = d[k];
                    d[k] = d[k - 1];
                    d[k - 1] = tmp;
                }
            }
            boolean can = true;
            int tmp = c[0] % 2, last = 0;
            for (int j = 1; j < n; j++) {
                if (d[j - 1] == d[j]) {
                    tmp += (1 << j) * (c[j] % 2);
                } else {
                    if (Integer.bitCount(tmp) % 2 == 1) {
                        can = false;
                    } else {
                        count += f(tmp);
                    }
                    tmp = c[j] % 2;
                    last = j;
                }
            }
            if (Integer.bitCount(tmp) % 2 == 1) {
                can = false;
            } else {
                count += f(tmp);
            }
            if (can) {
                ans = Math.min(ans, count);
            }
        }
        out.println(ans == inf ? -1 : ans);
    }

    int f(int i) {
        int res = 0;
        while (i > 0) {
            if ((i & 1) == 1) {
                i ^= 3;
                res++;
            }
            i >>= 1;
        }
        return res;
    }

    int get(int flags, int i) {
        return ((flags >> i) & 1) == 1 ? b[i] : a[i];
    }

    public static void main(String[]$) {
        new Main().solve();
        out.flush();
    }
}

