import java.util.function.Function;
import java.util.function.Predicate;
import java.util.stream.Collectors;
import java.util.stream.Stream;

public class Main {

  public static void main(String[] args) {
    solve(System.in, System.out);
  }

  static void solve(InputStream is, PrintStream os) {
    Scanner sc = new Scanner(is);

    /* read */
    int n = sc.nextInt();
    int[] a = new int[n];
    int[] b = new int[n];
    for (int i = 0; i < n; i++) {
      a[i] = sc.nextInt();
    }

    for (int i = 0; i < n; i++) {
      b[i] = sc.nextInt();
    }

    if (n == 1) {
      os.println(0);
      return;
    }

    int min = Integer.MAX_VALUE;
    for (long i = 0, bits = 1 << n; i < bits; i++) {
      boolean[] reversed = new boolean[n - 1];
      for (int bit = 0; bit < n - 1; bit++) {
        reversed[bit] = ((i >> bit) & 1) == 1;
      }
      if (check(a, b, reversed, n)) {
        min = Math.min(count(reversed), min);
      }
    }
    if (min == Integer.MAX_VALUE) {
      os.println(-1);
    } else {
      os.println(min);
    }
  }

  private static int count(boolean[] reversed) {
    int ans = 0;
    for (boolean b : reversed) {
      if (b)
        ans++;
    }
    return ans;
  }

  private static boolean check(int[] a, int[] b, boolean[] reversed, int n) {

    int[] c = new int[n];
    int[] d = new int[n];
    for (int i = 0; i < n; i++) {
      c[i] = a[i];
      d[i] = b[i];
    }
    for (int i = 0; i < n - 1; i++) {
      if (reversed[i]) {
        int lf = c[i];
        int lb = d[i];
        int rf = c[i + 1];
        int rb = d[i + 1];
        c[i] = rb;
        d[i] = rf;
        c[i + 1] = lb;
        d[i + 1] = lf;
      }
    }

    int last = 0;
    for (int i = 0; i < n; i++) {
      if (c[i] < last) {
        return false;
      }
      last = c[i];
    }
    return true;
  }

  private static class GridPointEncoder implements Encoder<GridPoint> {

    public GridPointEncoder(int h, int w) {
      this.h = h;
      this.w = w;
    }

    private final int h;
    private final int w;

    @Override
    public int num() {
      return w * h;
    }

    @Override
    public int encode(GridPoint from) {
      return w * from.r + from.c;
    }

    @Override
    public GridPoint decode(int from) {
