internal partial class Solver {
    public void Run() {
        var n = ni();
        var a = ni(n);
        var b = ni(n);
        int ans = int.MaxValue;

        var dp = new int[1 << n, n]; // used, last
        for (int i = 0; i < (1 << n); i++) {
            for (int j = 0; j < n; j++) {
                dp[i, j] = int.MaxValue;
            }
        }
        for (int i = 0; i < n; i++) {
            dp[1 << i, i] = i;
        }
        for (int bit = 1; bit < (1 << n); bit++) {
            var lastPlacePosition = PopCount((ulong)bit) - 1;
            for (int i = 0; i < n; i++) {
                if (dp[bit, i] == int.MaxValue) continue;
                var last = (i - lastPlacePosition) % 2 == 0 ? a[i] : b[i];
                int move = 0;
                for (int j = 0; j < n; j++) {
                    if ((bit & (1 << j)) != 0) continue;
                    var p = (j - (lastPlacePosition + 1)) % 2 == 0 ? a[j] : b[j];
                    if (last <= p) {
                        UpdateMin(ref dp[bit | (1 << j), j], dp[bit, i] + move);
                    }
                    move++;
                }
            }
        }
        for (int i = 0; i < n; i++) {
            ans = Math.Min(dp[(1 << n) - 1, i], ans);
        }
        if (ans == int.MaxValue) ans = -1;
        cout.WriteLine(ans);
    }

    public static bool UpdateMin<T>(ref T x, T newValue) where T : IComparable<T> {
        if (x.CompareTo(newValue) > 0) { x = newValue; return true; }
        return false;
    }


    private static int PopCount(ulong x) {
        x = (x & 0x5555555555555555UL) + ((x >> 1) & 0x5555555555555555UL);
        x = (x & 0x3333333333333333UL) + ((x >> 2) & 0x3333333333333333UL);
        x = (x + (x >> 4)) & 0x0f0f0f0f0f0f0f0fUL;
        x += x >> 8;
        x += x >> 16;
        x += x >> 32;
        return (int)(x & 0x7FLU);
    }
}

