public class Scanner {
    private readonly TextReader Reader;
    private readonly CultureInfo ci = CultureInfo.InvariantCulture;

    private readonly char[] buffer = new char[2 * 1024];
    private int cursor = 0, length = 0;
    private string Token;
    private readonly StringBuilder sb = new StringBuilder(1024);

    public Scanner()
        : this(Console.In) {
    }

    public Scanner(TextReader reader) {
        Reader = reader;
    }

    public int NextInt() { return (int)NextLong(); }
    public long NextLong() {
        var s = Next();
        long r = 0;
        int i = 0;
        bool negative = false;
        if (s[i] == '-') {
            negative = true;
            i++;
        }
        for (; i < s.Length; i++) {
            r = r * 10 + (s[i] - '0');
#if DEBUG
            if (!char.IsDigit(s[i])) throw new FormatException();
#endif
        }
        return negative ? -r : r;
    }
    public double NextDouble() { return double.Parse(Next(), ci); }
    public string[] NextArray(int size) {
        string[] array = new string[size];
        for (int i = 0; i < size; i++) {
            array[i] = Next();
        }

        return array;
    }
    public int[] NextIntArray(int size) {
        int[] array = new int[size];
        for (int i = 0; i < size; i++) {
            array[i] = NextInt();
        }

        return array;
    }

    public long[] NextLongArray(int size) {
        long[] array = new long[size];
        for (int i = 0; i < size; i++) {
            array[i] = NextLong();
        }

        return array;
    }

    public double[] NextDoubleArray(int size) {
        double[] array = new double[size];
        for (int i = 0; i < size; i++) {
            array[i] = NextDouble();
        }

        return array;
    }

    public string Next() {
        if (Token == null) {
            if (!StockToken()) {
                throw new InvalidOperationException();
            }
        }
        var token = Token;
        Token = null;
        return token;
    }

    public bool HasNext() {
        if (Token != null) {
            return true;
        }

        return StockToken();
    }

    private bool StockToken() {
        while (true) {
            sb.Clear();
            while (true) {
                if (cursor >= length) {
                    cursor = 0;
                    if ((length = Reader.Read(buffer, 0, buffer.Length)) <= 0) {
                        break;
                    }
                }
                var c = buffer[cursor++];
                if (33 <= c && c <= 126) {
                    sb.Append(c);
                } else {
                    if (sb.Length > 0) break;
                }
            }

            if (sb.Length > 0) {
                Token = sb.ToString();
                return true;
            }

            return false;
        }
    }
}

using System;

public class Program
{
    private int N;
    private int[] A, B;
    private const long Inf = int.MaxValue;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        A = sc.IntArray();
        B = sc.IntArray();

        int l = 1 << N;

        // mask,i 最後にiを追加 使用済みがmaskになった
        // 移動距離
        var dp = new long[l, N];

        for (int i = 0; i < l; i++)
        {
            for (int j = 0; j < N; j++)
            {
                dp[i, j] = Inf;
            }
        }

        for (int i = 0; i < l; i++)
        {
            int bitCount = 0;
            for (int j = 0; j < N; j++)
            {
                if ((i & (1 << j)) > 0)
                {
                    bitCount++;
                }
            }

            if (bitCount == 0) continue;
            if (bitCount == 1)
            {
                for (int j = 0; j < N; j++)
                {
                    if ((i & (1 << j)) > 0)
                    {
                        dp[i, j] = j;
                    }
                }
            }
            else
            {
                for (int j = 0; j < N; j++)
                {
                    if ((i & (1 << j)) > 0)
                    {
                        int jj = ((bitCount - 1) - j) % 2 == 0 ? A[j] : B[j];
                        for (int k = 0; k < N; k++)
                        {
                            if (j == k) continue;
                            if ((i & (1 << k)) > 0)
                            {
                                int kk = ((bitCount - 2) - k) % 2 == 0 ? A[k] : B[k];

                                if (kk <= jj)
                                {
                                    int p = i - (1 << j);
                                    dp[i, j] = Math.Min(dp[i, j], dp[p, k] + Math.Max(j - (bitCount - 1), 0));
                                }
                            }
                        }
                    }
                }
            }
        }

        long ans = Inf;
        for (int i = 0; i < N; i++)
        {
            if (dp[l - 1, i] == Inf)
            {
                continue;
            }

            ans = Math.Min(ans, dp[l - 1, i]);
        }

        Console.WriteLine(ans == Inf ? -1 : ans);
    }

    public static void Main(string[] args)
    {
        new Program().Solve();
    }
}

