using System;

public class Program
{
    private int N;
    private int[] A, B;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        A = sc.IntArray();
        B = sc.IntArray();

        int l = 1 << N;

        // i個目を最後に追加
        // 現在 l
        // これまでの転倒数
        var dp = new long[l, N];

        for (int i = 0; i < l; i++)
        {
            for (int j = 0; j < N; j++)
            {
                dp[i, j] = int.MaxValue;
            }
        }

        for (int i = 1; i < l; i++)
        {
            int bitCount = 0;
            for (int j = 0; j < N; j++)
            {
                if ((i & (1 << j)) > 0)
                    bitCount++;
            }

            for (int j = 0; j < N; j++)
            {
                if ((i & (1 << j)) == 0)
                    continue;

                if (bitCount == 1)
                {
                    dp[i, j] = j;
                }
                else
                {
                    int jIndex = bitCount - 1;
                    int jj = (jIndex - j) % 2 == 0 ? A[j] : B[j];
                    for (int k = 0; k < N; k++)
                    {
                        if ((j == k) || ((i & (1 << k)) == 0))
                            continue;

                        // 一個前 k番目 今 j番目

                        // 一個前の値
                        int kIndex = bitCount - 2;
                        int kk = (kIndex - k) % 2 == 0 ? A[k] : B[k];

                        if (kk <= jj)
                        {
                            int p = i - (1 << j);
                            if (dp[p, k] == int.MaxValue) continue;
                            dp[i, j] = Math.Min(dp[i, j], dp[p, k] + Math.Max(j - jIndex, 0));
                        }
                    }
                }
            }
        }

        long min = int.MaxValue;
        for (int i = 0; i < N; i++)
        {
            min = Math.Min(dp[l - 1, i], min);
        }

        Console.WriteLine(min == int.MaxValue ? -1 : min);
    }

    public static void Main(string[] args)
    {
        new Program().Solve();
    }
}

