using System;

public class Program
{
    private int N;
    private int[] A, B;
    private const long Inf = int.MaxValue;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        A = sc.IntArray();
        B = sc.IntArray();

        int l = 1 << N;

        // mask,i 最後にiを追加 使用済みがmaskになった
        // 移動距離
        var dp = new long[l, N];

        for (int i = 0; i < l; i++)
        {
            for (int j = 0; j < N; j++)

            {
                dp[i, j] = Inf;
            }
        }

        for (int i = 0; i < l; i++)
        {
            int bitCount = 0;
            for (int j = 0; j < N; j++)
            {
                if ((i & (1 << j)) > 0)
                {
                    bitCount++;
                }
            }

            if (bitCount == 0) continue;
            if (bitCount == 1)
            {
                for (int j = 0; j < N; j++)
                {
                    if ((i & (1 << j)) > 0)
                    {
                        dp[i, j] = j;
                    }
                }
            }
            else
            {
                for (int j = 0; j < N; j++)
                {
                    if ((i & (1 << j)) > 0)
                    {
                        int jj = ((bitCount - 1) - j) % 2 == 0 ? A[j] : B[j];
                        for (int k = 0; k < N; k++)
                        {
                            if (j == k) continue;
                            if ((i & (1 << k)) > 0)
                            {
                                int kk = ((bitCount - 2) - k) % 2 == 0 ? A[k] : B[k];

                                if (kk <= jj)
                                {
                                    int p = i - (1 << j);
                                    if (dp[p, k] != Inf)
                                    {
                                        dp[i, j] = Math.Min(dp[i, j], dp[p, k] + Math.Max(j - (bitCount - 1), 0));
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        long ans = Inf;
        for (int i = 0; i < N; i++)
        {
            if (dp[l - 1, i] == Inf)
            {
                continue;
            }

            ans = Math.Min(ans, dp[l - 1, i]);
        }

        Console.WriteLine(ans == Inf ? -1 : ans);
    }

    public static void Main(string[] args)
    {
        new Program().Solve();
    }
}

