public class Kyopuro
{

    int n;
    int[] x, y;

    public void AtCoder()
    {
        string[] input;
        input = Console.ReadLine().Split(' ');
        n = int.Parse(input[0]);
        x = new int[n];
        y = new int[n];
        input = Console.ReadLine().Split(' ');
        for(int i=0; i<n; i++) x[i] = int.Parse(input[i]);
        input = Console.ReadLine().Split(' ');
        for (int i = 0; i < n; i++) y[i] = int.Parse(input[i]);

        int z = (int)Math.Pow(2, n);

        int[] w1 = new int[n];
        int[] w2 = new int[n];
        int[] w3 = new int[n];
        int[] w4 = new int[n];

        int kotae = 99999999;
        int tento;

        for (int i=0; i<z; i++)
        {

            int zz = i;
            for(int j=0; j<n; j++)
            {
                if (zz % 2 == 0)
                {
                    w1[j] = x[j];
                    w3[j] = 0;
                    w4[j] = w1[j];
                }
                else
                {
                    w1[j] = y[j];
                    w3[j] = 1;
                    w4[j] = w1[j];
                }
                w2[j] = j + 1;
                zz = zz / 2;
            }
            Array.Sort(w1, w2);
            Array.Sort(w4, w3);
            bool f = true;
            for (int j = 0; j < n; j++)
            {
                if (j%2 == 0)
                {
                    if (w2[j] % 2 == w3[j]) f = false;
                } else
                {
                    if (w2[j] % 2 != w3[j]) f = false;
                }
            }
            if (!f) continue;

            tento = Tento(n, w2);
            DebugWL(tento);
            if (tento < kotae) kotae = tento;

        }
        if (kotae == 99999999) kotae = -1;
        Console.WriteLine(kotae);
    }


    int[] bit;

    int Tento(int n, int[] s)
    {
        bit = new int[n + 1];
        long ans = 0;
        for (int i = 0; i < n; i++)
        {
            ans += i - bitr(s[i]);
            bitp(s[i], 1);
        }

        return (int) ans;
    }

    void bitp(int a, int p)
    {

        while (a <= n)
        {
            bit[a] += p;
            a += a & -a;
        }
    }

    int bitr(int n)
    {

        int a = 0;
        while (n > 0)
        {
            a += bit[n];
            n -= n & -n;
        }
        return a;
    }

    public static void DebugWL(object x) { System.Diagnostics.Debug.WriteLine(x); }

}

