                            if ((i & (1 << k)) > 0)
                            {
                                int kk = ((bitCount - 2) - k) % 2 == 0 ? A[k] : B[k];

                                if (kk <= jj)
                                {
                                    int p = i - (1 << j);
                                    if (dp[p, k] != Inf)
                                    {
                                        // Console.WriteLine($"{bitCount-1} {j}");
                                        dp[i, j] = Math.Min(dp[i, j], dp[p, k] + Math.Max((bitCount - 1) - j, 0));
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        long ans = Inf;
        for (int i = 0; i < N; i++)
        {
            if (dp[l - 1, i] == Inf)
            {
                continue;
            }

            ans = Math.Min(ans, dp[l - 1, i]);
        }

        Console.WriteLine(ans == Inf ? -1 : ans);
    }

    public static void Main(string[] args)
    {
        new Program().Solve();
    }
}

