using System;
using System.Collections.Generic;
class Program
{
	static void Main(string[] args)
	{
		int N = int.Parse(Console.ReadLine());
		int[]A = new int[N];
		int[]B = new int[N];
		string[] str = Console.ReadLine().Split();
		string[] str2 = Console.ReadLine().Split();
		for(var i=0;i<N;i++){
			A[i] = int.Parse(str[i]);
			B[i] = int.Parse(str2[i]);
		}
		int NA = (int)Math.Pow(2,N);
		int[]P = new int[N];
		P[0] = 1;
		for(var i=1;i<N;i++){
			P[i] = P[i-1] * 2;
		}
		int ans = 99999;
		for(var i=0;i<NA;i++){
			int c1 = 0;
			int c2 = 0;
			int[]C = new int[N];
			int[]C2 = new int[N];
			int[]E = new int[N];
			for(var j=0;j<N;j++){
				int a1 = i/P[j]%2;
				if(a1==1){
					C[j] = B[j];
				} else {
					C[j] = A[j];
				}
				C2[j] = C[j];
				E[j] = a1;
				if(a1==1){
					if(j%2==0){
						c1++;
					} else {
						c2++;
					}
				}
			}
			if(c1!=c2){
				continue;
			}
			Array.Sort(C);
			int[]D = new int[N];
			int ad = 0;
			bool flag0 = true;
			for(var j=0;j<N;j++){
				bool flag = false;
				for(var k=0;k<N;k++){
					if(D[k]==0 && C[j] == C2[k]){
						if(Math.Abs(j-k)%2==E[k]){
							D[k]++;
							ad += Math.Abs(j-k);
							flag = true;
 							break;
						}
					}
				}
				if(!flag){
					flag0 = false;
					break;
				}
			}
			if(flag0){
				ans = Math.Min(ad,ans);
			}
		}
		if(ans==99999){
			Console.WriteLine("-1");
		} else {
			Console.WriteLine(ans/2);
		}
	}
}

