class D
{
	static int[] Read() => Console.ReadLine().Split().Select(int.Parse).ToArray();
	static void Main()
	{
		var n = int.Parse(Console.ReadLine());
		var a = Read();
		var b = Read();

		var rn = Enumerable.Range(0, n).ToArray();
		var m = Enumerable.Range(0, 1 << n)
			.Select(x => Array.ConvertAll(rn, i => (x & (1 << i)) == 0 ? (a[i], false) : (b[i], true)))
			.Select(Swap)
			.Min();
		Console.WriteLine(m == 1 << 30 ? -1 : m);

		int Swap((int v, bool rev)[] c)
		{
			var g = Array.ConvertAll(c, _ => _.v);
			Array.Sort(g);
			var u = new bool[n];

			var map = new int[n];
			for (int i = 0; i < n; i++)
			{
				map[i] = -1;
				for (int j = 0; j < n; j++)
				{
					if (u[j] || g[i] != c[j].v || (i - j) % 2 != 0 != c[j].rev) continue;
					u[j] = true;
					map[i] = j;
					break;
				}
				if (map[i] == -1) return 1 << 30;
			}

			var t = 0;
			for (int i = 0; i < n; i++)
				for (int j = i + 1; j < n; j++)
					if (map[i] > map[j]) t++;
			return t;
		}
	}
}

using System;

public class Program
{
    private int N;
    private int[] A, B;

    public void Solve()
    {
        checked
        {
            var sc = new Scanner();
            N = sc.NextInt();
            A = sc.IntArray();
            B = sc.IntArray();

            int l = 1 << N;

            var dp = new long[l, N];

            for (int i = 0; i < l; i++)
            {
                for (int j = 0; j < N; j++)
                {
                    dp[i, j] = int.MaxValue;
                }
            }

            for (int mask = 1; mask < l; mask++)
            {
                int bitCount = 0;
                for (int i = 0; i < N; i++)
                {
                    if (C(mask, i))
                    {
                        bitCount++;
                    }
                }

                if (bitCount == 1)
                {
                    for (int i = 0; i < N; i++)
                    {
                        if (C(mask, i))
                        {
                            dp[mask, i] = 0;
                            break;
                        }
                    }

                    continue;
                }


                for (int i = 0; i < N; i++)
                {
                    if (C(mask, i))
                    {
                        int prev = mask - (1 << i);

                        int ii = (bitCount - 1 - i) % 2 == 0 ? A[i] : B[i];
                        for (int j = 0; j < N; j++)
                        {
                            if (C(prev, j))
                            {
                                int jj = (bitCount - 2 - j) % 2 == 0 ? A[j] : B[j];
                                if (jj <= ii)
                                {
                                    dp[mask, i] = Math.Min(dp[mask, i], dp[prev, j] + Math.Max(0, (bitCount - 1) - i));
                                }
                            }
                        }
                    }
                }
            }

            long ans = int.MaxValue;
            for (int i = 0; i < N; i++)
            {
                ans = Math.Min(ans, dp[l - 1, i]);
            }

            Console.WriteLine(ans == int.MaxValue ? -1 : ans);
        }
    }

    bool C(int mask, int i)
    {
        return (mask & (1 << i)) > 0;
    }

    public static void Main(string[] args)
    {
        new Program().Solve();
    }
}

class Scanner
{
    public Scanner()
    {
        _pos = 0;
        _line = new string[0];
    }

    const char Separator = ' ';
    private int _pos;
    private string[] _line;

    #region スペース区切りで取得

    public string Next()
    {
        if (_pos >= _line.Length)
        {
            _line = Console.ReadLine().Split(Separator);
            _pos = 0;
        }

        return _line[_pos++];
    }

    public int NextInt()
    {
        return int.Parse(Next());
    }

    public long NextLong()
    {
        return long.Parse(Next());
    }

    public double NextDouble()
    {
        return double.Parse(Next());
    }

    #endregion

    #region 型変換

    private int[] ToIntArray(string[] array)
    {
        var result = new int[array.Length];
        for (int i = 0; i < array.Length; i++)
        {
            result[i] = int.Parse(array[i]);
        }

        return result;
    }

    private long[] ToLongArray(string[] array)
    {
        var result = new long[array.Length];
        for (int i = 0; i < array.Length; i++)
        {
            result[i] = long.Parse(array[i]);
        }

        return result;
    }

    private double[] ToDoubleArray(string[] array)
    {
        var result = new double[array.Length];
        for (int i = 0; i < array.Length; i++)
        {
            result[i] = double.Parse(array[i]);
        }

        return result;
    }

    #endregion

    #region 配列取得

    public string[] Array()
    {
        if (_pos >= _line.Length)
            _line = Console.ReadLine().Split(Separator);

        _pos = _line.Length;
        return _line;
    }

    public int[] IntArray()
    {
        return ToIntArray(Array());
    }

    public long[] LongArray()
    {
        return ToLongArray(Array());
    }

    public double[] DoubleArray()
    {
        return ToDoubleArray(Array());
    }

    #endregion
}

using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Runtime.CompilerServices;
using System.Text;

namespace AtCoder
{
	public class Program
	{
		static void Main()
		{
			var cin = new Scanner();
			int n = cin.Int();
			int[] a = cin.ArrayInt(n);
			int[] b = cin.ArrayInt(n);

			long ans = long.MaxValue;
			for (int k = 0; k < 1 << n; k++) {
				var q = new PriorityQueue<PriorityPair<int, Card>>(n, true);
				for (int i = 0; i < n; i++) {
					bool isBlue = (k & (1 << i)) != 0;
					q.Enqueue(new PriorityPair<int, Card>(
						(isBlue ? b[i] : a[i]) * 100 + i,
						new Card(i, isBlue)));
				}

				bool ok = true;
				var indexes = new List<int>(n);
				while (q.Count > 0) {
					int number = q.Top.Priority / 100;
					var first = new PriorityQueue<int>(n / 2, true);
					var second = new PriorityQueue<int>(n / 2, true);
					while (q.Count > 0 && q.Top.Priority / 100 == number) {
						var next = q.Dequeue();
						if (Math.Abs(indexes.Count - next.Item.Index) % 2 == 0) {
							if (next.Item.IsBlue) {
								second.Enqueue(next.Item.Index);
							} else {
								first.Enqueue(next.Item.Index);
							}
						} else {
							if (next.Item.IsBlue) {
								first.Enqueue(next.Item.Index);
							} else {
								second.Enqueue(next.Item.Index);
							}
						}
					}

					bool ok2 = true;
					while (first.Count > 0 || second.Count > 0) {
						if (first.Count == 0) {
							ok2 = false;
							break;
						}

						indexes.Add(first.Dequeue());

						if (second.Count == 0) {
							if (first.Count > 0) {
								ok2 = false;
							}

							break;
						}

						indexes.Add(second.Dequeue());
					}

					if (ok2 == false) {
						ok = false;
						break;
					}
				}

				if (ok == false) {
					continue;
				}

				int cnt = 0;
				for (int i = 0; i < n - 1; i++) {
					for (int j = i + 1; j < n; j++) {
						if (indexes[j] < indexes[i]) {
							++cnt;
						}
					}
				}

				ans = Math.Min(ans, cnt);
			}

			if (ans != long.MaxValue) {
				Console.WriteLine(ans);
			} else {
				Console.WriteLine(-1);
			}
		}
	}

	public struct Card
