            Out.Flush();
        }

        static void Method(string[] args)
        {
            int n = ReadInt();
            int[] arrayA = ReadInts();
            int[] arrayB = ReadInts();

            int all = 1 << n;
            int res = int.MaxValue;
            for(int i = 0; i < all; i++)
            {
                bool[] useBlue = new bool[n];
                int[][] vals = new int[n][];
                for (int j = 0; j < n; j++)
                {
                    if (((1 << j) & i) > 0)
                    {
                        useBlue[j] = true;
                    }
                    vals[j] = new int[2] { 0, j };
                    vals[j][0] = useBlue[j] ? arrayB[j] : arrayA[j];
                }
                vals = vals.OrderBy(a => a[0]).ToArray();
                Queue<int[]> que = new Queue<int[]>();
                for (int j = 0; j < n; j++) que.Enqueue(vals[j]);
                bool ok = true;
                int tmp = 0;
                int[][] inValues = new int[n][];
                for(int j = 0; j < n; j++)
                {
                    Queue<int[]> next = new Queue<int[]>();
                    while (que.Count > 0)
                    {
                        int[] val = que.Dequeue();
                        int index = val[1];
                        if (useBlue[index])
                        {
                            if (j % 2 == index % 2)
                            {
                                next.Enqueue(val);
                                continue;
                            }
                        }
                        else
                        {
                            if (j % 2 != index % 2)
                            {
                                next.Enqueue(val);
                                continue;
                            }
                        }
                        inValues[j] = val;
                        for (int k = 0; k < j; k++)
                        {
                            if (inValues[k][1] > index) tmp++;
                        }
                        break;
                    }
                    if (inValues[j] == null
                        || (next.Count > 0 && next.Peek()[0] < inValues[j][0]))
                    {
                        ok = false;
                        break;
                    }
                    while (que.Count > 0)
                    {
                        next.Enqueue(que.Dequeue());
                    }
                    que = next;
                }
                if (ok)
                {
                    res = Min(res, tmp);
                }
            }
            if (res == int.MaxValue) WriteLine(-1);
            else WriteLine(res);
        }

