using System;

public class Program
{
    private int N;
    private int[] A, B;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        A = sc.IntArray();
        B = sc.IntArray();

        int l = 1 << N;

        var dp = new long[l, N];

        for (int i = 0; i < l; i++)
        {
            for (int j = 0; j < N; j++)
            {
                dp[i, j] = int.MaxValue;
            }
        }

        for (int mask = 0; mask < l - 1; mask++)
        {
            int bitCount = 0;
            for (int i = 0; i < N; i++)
            {
                if (C(mask, i))
                {
                    bitCount++;
                }
            }

            if (bitCount == 0)
            {
                for (int i = 0; i < N; i++)
                {
                    dp[mask | (1 << i), i] = 0;
                }
            }
            else
            {
                for (int i = 0; i < N; i++)
                {
                    // iを追加
                    if (!C(mask, i))
                    {
                        int ii = (bitCount - i) % 2 == 0 ? A[i] : B[i];

                        // 一個前
                        long c = int.MaxValue;

                        // 前にある(iiより小さい)のにiより番号が大きいカード
                        int cnt = 0;

                        for (int j = 0; j < N; j++)
                        {
                            if (C(mask, j))
                            {
                                int jj = (bitCount - 1 - j) % 2 == 0 ? A[j] : B[j];
                                if (jj <= ii)
                                {
                                    c = Math.Min(c, dp[mask, j]);
                                }

                                if (i < j)
                                {
                                    cnt++;
                                }
                            }
                        }

                        int next = mask | (1 << i);
                        dp[next, i] = Math.Min(dp[next, i], c + cnt);
                    }
                }
            }
        }

        long ans = int.MaxValue;
        for (int i = 0; i < N; i++)
        {
            ans = Math.Min(ans, dp[l - 1, i]);
        }

        Console.WriteLine(ans == int.MaxValue ? -1 : ans);
    }

    bool C(int mask, int i)
    {
        return (mask & (1 << i)) > 0;
    }

    public static void Main(string[] args)
    {
        new Program().Solve();
    }
}

