namespace AtCoder
{
    class Program
    {
        private static string Read() { return Console.ReadLine(); }
        private static int ReadInt() { return int.Parse(Read()); }
        private static long ReadLong() { return long.Parse(Read()); }
        private static double ReadDouble() { return double.Parse(Read()); }
        private static int[] ReadInts() { return Array.ConvertAll(Read().Split(), int.Parse); }
        private static long[] ReadLongs() { return Array.ConvertAll(Read().Split(), long.Parse); }
        private static double[] ReadDoubles() { return Array.ConvertAll(Read().Split(), double.Parse); }

        static int Bubble(List<int> values)
        {
            int N = values.Count;
            int count = 0;
            for (int i = 0; i < N; ++i)
            {
                for (int j = N - 2; j >= 0; --j)
                {
                    if (values[j] > values[j + 1])
                    {
                        var tmp = values[j];
                        values[j] = values[j + 1];
                        values[j + 1] = tmp;
                        ++count;
                    }
                }
            }
            return count;
        }

        static int Search(List<Tuple<int, int, bool>> list, List<int> values, int max, int s, bool[] used)
        {
            int C = values.Count;
            if (C == list.Count / 2) { return Bubble(values); }
            int ans = int.MaxValue;
            for (int i = s; i < list.Count; ++i)
            {
                if (list[i].Item1 >= max && !used[list[i].Item2] && (values.Count % 2 != 0) == list[i].Item3)
                {
                    values.Add(list[i].Item2);
                    used[list[i].Item2] = true;
                    ans = Math.Min(Search(list, values, list[i].Item1, s + 1, used), ans);
                    used[list[i].Item2] = false;
                    values.RemoveAt(C);
                }
            }
            return ans;
        }

        static int Solve(int N, int[] A, int[] B)
        {
            var list = new List<Tuple<int, int, bool>>();
            for (int i = 0; i < N; ++i)
            {
                if (i % 2 == 0)
                {
                    list.Add(Tuple.Create(A[i], i, false));
                    list.Add(Tuple.Create(B[i], i, true));
                }
                else
                {
                    list.Add(Tuple.Create(B[i], i, false));
                    list.Add(Tuple.Create(A[i], i, true));
                }
            }
            list.Sort();
            var ans = Search(list, new List<int>(), 0, 0, new bool[N]);
            return (ans < int.MaxValue) ? ans : -1;
        }

        static void Main(string[] args)
        {
            int N = ReadInt();
            var A = ReadInts();
            var B = ReadInts();
            Console.WriteLine(Solve(N, A, B));
        }
    }
}

