                for (var j = 0; j < N; j++)
                {
                    var minNum = 1000000L;
                    var minIdx = -1;
                    for (var k2 = j; k2 < N; k2++)
                    {
                        if (minNum > ary[k2])
                        {
                            minNum = ary[k2];
                            minIdx = k2;
                        }
                    }
                    var k = minIdx - 1;
                    var flag = false;
                    for (; k >= 0; k--)
                    {
                        if (ary[k] > ary[k + 1])
                        {
                            var t = ary[k]; ary[k] = ary[k + 1]; ary[k + 1] = t;
                            var t2 = aryInvalid[k]; aryInvalid[k] = aryInvalid[k + 1]; aryInvalid[k + 1] = t2;
                            aryInvalid[k] = !aryInvalid[k];
                            aryInvalid[k + 1] = !aryInvalid[k + 1];
                            cnt++;
                        }
                        else if (ary[k] == ary[k + 1])
                        {
                            if (!aryInvalid[k + 1])
