using System;
using System.Collections.Generic;
using System.Linq;

public class Program
{
    private int N;
    private int[] A, B;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        A = sc.IntArray();
        B = sc.IntArray();

        /*
         * 偶数番目
         * 裏返すと奇数番目になる
         *
         * 奇数番目
         * 裏返すと偶数番目になる
         *
         * 2^18全探索
         * 距離が合ってるか
         *
         * 転倒数
         */

        int l = 1 << N;
        int ans = int.MaxValue;
        for (int i = 0; i < l; i++)
        {
            int o;
            if (C(i, out o))
            {
                ans = Math.Min(o, ans);
            }
        }

        Console.WriteLine(ans == int.MaxValue ? -1 : ans);
    }

    private bool C(int l, out int cnt)
    {
        // false A面 true B面
        var b = new bool[N];
        int c = 0;
        cnt = 0;
        for (int i = 0; i < N; i++)
        {
            b[i] = (l & (1 << i)) > 0;
            if (b[i])
            {
                c++;
            }
        }

        if (c % 2 != 0)
        {
            return false;
        }

        var ar = new int[N];
        for (int i = 0; i < N; i++)
        {
            if (b[i])
            {
                ar[i] = B[i];
            }
            else
            {
                ar[i] = A[i];
            }
        }

        Array.Sort(ar);
        //Console.WriteLine(string.Join(" ",ar));
        bool[] flag = new bool[N];
        for (int i = 0; i < N; i++)
        {
            bool f = false;
            for (int j = 0; j < N; j++)
            {
                int n = b[j] ? B[i] : A[i];
                if (n == ar[j] && i % 2 == (j + (b[j] ? 1 : 0)) % 2 && !flag[j])
                {
                    cnt += Math.Abs(j - i);

                    f = true;
                    flag[j] = true;
                    break;
                }
            }

            if (!f)
            {
                return false;
            }
        }

        cnt /= 2;
        return true;
    }

    public static void Main(string[] args)
    {
