	public class Program
	{
		static void Main()
		{
			var cin = new Scanner();
			int n = cin.Int();
			int[] a = cin.ArrayInt(n);
			int[] b = cin.ArrayInt(n);

			long ans = long.MaxValue;
			for (int k = 0; k < 1 << n; k++) {
				var q = new PriorityQueue<PriorityPair<int, Card>>(n, true);
				for (int i = 0; i < n; i++) {
					bool isBlue = (k & (1 << i)) != 0;
					q.Enqueue(new PriorityPair<int, Card>(
						(isBlue ? b[i] : a[i]) * 100 + i,
						new Card(i, isBlue)));
				}

				bool ok = true;
				var indexes = new List<int>(n);
				while (q.Count > 0) {
					int number = q.Top.Priority / 100;
					var first = new PriorityQueue<int>(n / 2, true);
					var second = new PriorityQueue<int>(n / 2, true);
					while (q.Count > 0 && q.Top.Priority / 100 == number) {
						var next = q.Dequeue();
						if (Math.Abs(indexes.Count - next.Item.Index) % 2 == 0) {
							if (next.Item.IsBlue) {
								second.Enqueue(next.Item.Index);
							} else {
								first.Enqueue(next.Item.Index);
							}
						} else {
							if (next.Item.IsBlue) {
								first.Enqueue(next.Item.Index);
							} else {
								second.Enqueue(next.Item.Index);
							}
						}
					}

					bool ok2 = true;
					while (first.Count > 0 || second.Count > 0) {
						if (first.Count == 0) {
							ok2 = false;
							break;
						}

						indexes.Add(first.Dequeue());

						if (second.Count == 0) {
							if (first.Count > 0) {
								ok2 = false;
							}

							break;
						}

						indexes.Add(second.Dequeue());
					}

					if (ok2 == false) {
						ok = false;
						break;
					}
				}

				if (ok == false) {
					continue;
				}

				int cnt = 0;
				for (int i = 0; i < n - 1; i++) {
					for (int j = i + 1; j < n; j++) {
						if (indexes[j] < indexes[i]) {
							++cnt;
						}
					}
				}

				ans = Math.Min(ans, cnt);
			}

