                if (i0Max <= t.a) i0Max = t.a;
                else {
                    i0Fail = true;
                    break;
                }
            }

            if (!i0Fail) {
                Console.WriteLine(0);
                return;
            }

            search.Add(cards);
            for (var i = 1; i < 6; i++) {
                var nextSearch = new List<List<Card>>();
                foreach (var s in search) {
                    for (var j = 0; j < s.Count - 1; j++) {
                        var list = new List<Card>(s);
                        var tmp = list[j];
                        list[j] = list[j + 1];
                        list[j + 1] = tmp;
                        list[j] = list[j].Flip();
                        list[j + 1] = list[j + 1].Flip();

                        var max = 0;
                        var fail = false;
                        foreach (var t in list) {
                            if (max <= t.a) max = t.a;
                            else {
                                fail = true;
                                break;
                            }
                        }

                        if (fail) {
                            nextSearch.Add(list);
                        } else {
                            Console.WriteLine(i);
                            return;
                        }
                    }
                }
                search.Clear();
                search.AddRange(nextSearch);
            }

            Console.WriteLine(-1);
        }

