class D
{
	static int[] Read() => Console.ReadLine().Split().Select(int.Parse).ToArray();
	static void Main()
	{
		var n = int.Parse(Console.ReadLine());
		var a = Read();
		var b = Read();

		var m = 1 << 30;
		for (int x = 0; x < (1 << n); x++)
		{
			var bx = new BitArray(new[] { x });
			var c = new (int, bool)[n];
			for (int i = 0; i < n; i++)
				c[i] = (bx[i] ? b[i] : a[i], bx[i]);
			m = Math.Min(m, Swap(c));
		}
		Console.WriteLine(m == 1 << 30 ? -1 : m);

		int Swap((int v, bool rev)[] c)
		{
			var g = Array.ConvertAll(c, _ => _.v);
			Array.Sort(g);
			var u = new bool[n];

			var map = new int[n];
			for (int i = 0; i < n; i++)
			{
				map[i] = -1;
				for (int j = 0; j < n; j++)
				{
					if (u[j] || g[i] != c[j].v || (i - j) % 2 != 0 != c[j].rev) continue;
					u[j] = true;
					map[i] = j;
					break;
				}
				if (map[i] == -1) return 1 << 30;
			}

			var t = 0;
			for (int i = 0; i < n; i++)
				for (int j = i + 1; j < n; j++)
					if (map[i] > map[j]) t++;
			return t;
		}
	}
}

using System;

public class Program
{
    private int N;
    private int[] A, B;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        A = sc.IntArray();
        B = sc.IntArray();

        int l = 1 << N;

        var dp = new long[l, N];

        for (int i = 0; i < l; i++)
        {
            for (int j = 0; j < N; j++)
            {
                dp[i, j] = int.MaxValue;
            }
        }

        for (int mask = 1; mask < l; mask++)
        {
            int bitCount = 0;
            for (int i = 0; i < N; i++)
            {
                if (C(mask, i))
                {
                    bitCount++;
                }
            }

            if (bitCount == 1)
            {
                for (int i = 0; i < N; i++)
                {
                    if (C(mask, i))
                    {
                        dp[mask, i] = 0;
                        break;
                    }
                }

                continue;
            }

            for (int i = 0; i < N; i++)
            {
                if (C(mask, i))
                {
                    int prev = mask - (1 << i);

                    int ii = (bitCount - 1 - i) % 2 == 0 ? A[i] : B[i];
                    for (int j = 0; j < N; j++)
                    {
                        if (C(prev, j))
                        {
                            int jj = (bitCount - 2 - j) % 2 == 0 ? A[j] : B[j];
                            if (jj <= ii)
                            {
                                dp[mask, i] = Math.Min(dp[mask, i], dp[prev, j] + Math.Max(0, (bitCount - 1) - i));
                            }
                        }
                    }
                }
            }
        }

        long ans = int.MaxValue;
        for (int i = 0; i < N; i++)
        {
            ans = Math.Min(ans, dp[l - 1, i]);
        }

        Console.WriteLine(ans == int.MaxValue ? -1 : ans);
    }

    bool C(int mask, int i)
    {
        return (mask & (1 << i)) > 0;
    }

    public static void Main(string[] args)
    {
        new Program().Solve();
    }
}

