	public class Scanner2
	{
		private readonly char[] delimiter_ = new char[] { ' ' };
		private readonly string filePath_;
		private string[] buf_;
		private int index_;
		Func<string> reader_;

		public Scanner2(string file = "")
		{
			if (string.IsNullOrWhiteSpace(file)) {
				reader_ = Console.ReadLine;
			} else {
				filePath_ = file;
				var fs = new StreamReader(file);
				reader_ = fs.ReadLine;
			}
			buf_ = new string[0];
			index_ = 0;
		}

		public string Next()
		{
			if (index_ < buf_.Length) {
				return buf_[index_++];
			}

			string st = reader_();
			while (st == "") {
				st = reader_();
			}

			buf_ = st.Split(delimiter_, StringSplitOptions.RemoveEmptyEntries);
			if (buf_.Length == 0) {
				return Next();
			}

			index_ = 0;
			return buf_[index_++];
		}

		public int Int() => int.Parse(Next());
		public long Long() => long.Parse(Next());
		public double Double() => double.Parse(Next());

		public int[] ArrayInt(int N, int add = 0)
		{
			int[] Array = new int[N];
			for (int i = 0; i < N; i++) {
				Array[i] = Int() + add;
			}
			return Array;
		}

		public long[] ArrayLong(int N, long add = 0)
		{
			long[] Array = new long[N];
			for (int i = 0; i < N; i++) {
				Array[i] = Long() + add;
			}
			return Array;
		}

		public double[] ArrayDouble(int N, double add = 0)
		{
			double[] Array = new double[N];
			for (int i = 0; i < N; i++) {
				Array[i] = Double() + add;
			}
			return Array;
		}

		public void Save(string text)
		{
			if (string.IsNullOrWhiteSpace(filePath_)) {
				return;
			}

			File.WriteAllText(filePath_ + "_output.txt", text);
		}
	}
}

using System;
using System.Linq;

static class D
{
    static void Main()
    {
        int n = Int32.Parse(Console.ReadLine());
        int[] a = Console.ReadLine().Split().Select(Int32.Parse).ToArray();
        int[] b = Console.ReadLine().Split().Select(Int32.Parse).ToArray();

        var x = new int[n];
        var y = new int[n];

        int ans = -1;

        for (int bits = 0; bits < (1 << n); bits++)
        {
            for (int i = 0; i < n; i++)
            {
                int bit = (bits >> i) & 1;
                int x_i = (bit == 0) ? a[i] : b[i];
                x[i] = x_i;
            }

            Array.Sort(x);

            for (int i = 0; i < n; i++)
            {
                int bit = (bits >> i) & 1;
                int x_i = (bit == 0) ? a[i] : b[i];

                y[i] = -1;

                for (int j = 0; j < n; j++)
                {
                    if (x[j] == x_i && Math.Abs(j - i) % 2 == bit)
                    {
                        x[j] = 0;
                        y[i] = j;
                        break;
                    }
                }
                if (y[i] == -1) goto fail;
            }

            int flips = 0;

            for (int i = 0; i < n; i++)
            for (int j = 0; j < i; j++)
            {
                if (y[j] > y[i]) ++flips;
            }

            if (ans == -1 || ans > flips)
                ans = flips;
        fail: ;
        }

        Console.WriteLine(ans);
    }
}

