public class Solver
{
	public void Solve()
	{
		long N = GetLong();
		var A = GetLongs(N);
		var B = GetLongs(N);

		long INF = long.MaxValue / 2;
		long MASK = leftShift(1, N);
		var dp = new long[MASK, 64];
		for(long i = 0; i < MASK; i++)
		{
			for(long j = 0; j < 64; j++)
				dp[i, j] = INF;
		}
		dp[0, 0] = 0;
		for(long s = 0; s < MASK; s++)
		{
			long popcnt = 0;
			for(long i = 0; i < N; i++)
			{
				if(contains(s, i))
					popcnt++;
			}

			var cand = new List<(long, long)>();
			long head = popcnt;
			for(long i = 0; i < N; i++)
			{
				if(!contains(s, i))
				{
					cand.Add((i, head));
					head++;
				}
			}

			for(long i = 0; i < 64; i++)
			{
				if(dp[s, i] == INF)
					continue;

				foreach(var p in cand)
				{
					long idx = p.Item1;
					long pos = p.Item2;
					long j = Abs(idx - popcnt) % 2 == 0 ? A[idx] : B[idx];
					if(j >= i)
						chmin(ref dp[s | leftShift(1, idx), j], dp[s, i] + Abs(pos - popcnt));
				}
			}
		}

		long ans = INF;
		for(long i = 0; i < 64; i++)
			chmin(ref ans, dp[MASK - 1, i]);

		WriteLine((ans == INF) ? -1 : ans);
	}
}

