        int[] A = Util.readintarr();
        int[] B = Util.readintarr();

        //BITじゃなーいよ。

        //1、ありえる完成形を全探索する
        //2、それになるまでバブルソートする
        //3、その中で最も手数が低いものを持ってくる

        //1。
        //BFS?
        Stack<state> states = new Stack<state>();
        state firststate = new state(N);

        states.Push(firststate);
        List<string> candidate = new List<string>();
        while (states.Count > 0)
        {
            state targetstate = states.Pop();
            if (targetstate.setCards == N)
            {
                //候補だよなあ
                candidate.Add(targetstate.cards);
                continue;
            }


            //setCards=決めた枚数がKなら、K+1番目を決める。K=0なら赤青赤青の順で。
            for (int i = 0; i < targetstate.isUsed.Length; i++)
            {
                if (targetstate.isUsed[i])
                    continue;
                //i番目のカードが使われていたら、パス。
                else
                {
                    int cardsValue = 0;
                    if ((targetstate.setCards % 2) == (i % 2))
                    {
                        //表
                        cardsValue = A[i];
                    }
                    else
                    {
                        //裏
                        cardsValue = B[i];
                    }

                    if (cardsValue < targetstate.maxvalue)
                        continue;
                    //数が小さすぎるときね


                    //ここまで来て初めて候補。
                    state pushState = new state(N);
                    for (int st = 0; st < N; st++)
                    {
                        pushState.isUsed[st] = targetstate.isUsed[st];
                    }
                    pushState.isUsed[i] = true;
                    pushState.maxvalue = cardsValue;
                    pushState.setCards = targetstate.setCards + 1;
                    pushState.cards = targetstate.cards + (i+" ");

                    states.Push(pushState);

                }

            }

        }


        if (candidate.Count == 0)
        {
            Console.WriteLine(-1);
        }
        else
        {
            long output = long.MaxValue;
            for (int i = 0; i < candidate.Count; i++)
            {
                List<int> vs = new List<int>();
                for (int youso = 0; youso < N; youso++)
                {
                    vs.Add(youso);
                }
                string target = candidate[i].Trim();
                int[] arr = target.Split().Select(int.Parse).ToArray();
                int output_candidate = 0;

                for (int ptr = N - 1; ptr >= 0; ptr--)
                {
                    int targetvalue = arr[ptr];//並び替え候補の中の一番最後の添字
                    //これと一緒になってほしいのは、vsの
                    for (int vsprt = 0; vsprt < vs.Count; vsprt++)
                    {
                        if (vs[vsprt] == targetvalue)
                        {
                            output_candidate += Math.Abs(vsprt - ptr);
                            vs.RemoveAt(vsprt);
                            continue;
                        }
                    }
                    if (output > output_candidate) break;
                }

                if (output > output_candidate)
                {
                    output = output_candidate;
                }

            }

            Console.WriteLine(output);

        }



    }


