using System;

public class Program
{
    private int N;
    private int[] A, B;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        A = sc.IntArray();
        B = sc.IntArray();

        int l = 1 << N;

        // i個目追加
        // 現在 l
        // これまでの転倒数
        var dp = new int[l, N];

        for (int i = 0; i < l; i++)
        {
            for (int j = 0; j < N; j++)
            {
                dp[i, j] = int.MaxValue;
            }
        }

        for (int i = 1; i < l; i++)
        {
            int bitCount = 0;
            for (int j = 0; j < N; j++)
            {
                if ((i & (1 << j)) > 0)
                    bitCount++;
            }

            for (int j = 0; j < N; j++)
            {
                if ((i & (1 << j)) == 0)
                    continue;

                if (bitCount == 1)
                {
                    dp[i, j] = j;
                }
                else
                {
                    int jIndex = bitCount - 1;
                    int jj = (jIndex - j) % 2 == 0 ? A[j] : B[j];
                    for (int k = 0; k < N; k++)
                    {
                        if (j == k || (i & (1 << k)) == 0)
                            continue;

                        // 一個前 k番目 今 j番目

                        // 一個前の値
                        int kIndex = bitCount - 2;
                        int kk = (kIndex - k) % 2 == 0 ? A[k] : B[k];

                        if (kk <= jj)
                        {
                            int p = i - (1 << j);
                            if (dp[p, k] == int.MaxValue) continue;
                            dp[i, j] = Math.Min(dp[i, j], dp[p, k] + Math.Abs(jIndex - j));
                        }
                    }
                }
            }
        }

        int min = int.MaxValue;
        for (int i = 0; i < N; i++)
        {
            min = Math.Min(dp[(1 << N) - 1, i], min);
        }

        Console.WriteLine(min == int.MaxValue ? -1 : min / 2);
    }

    public static void Main(string[] args)
    {
        new Program().Solve();
    }
}

class Scanner
{
    public Scanner()
    {
        _pos = 0;
        _line = new string[0];
    }

    const char Separator = ' ';
    private int _pos;
    private string[] _line;

    #region スペース区切りで取得

    public string Next()
    {
        if (_pos >= _line.Length)
        {
            _line = Console.ReadLine().Split(Separator);
            _pos = 0;
        }

        return _line[_pos++];
    }

    public int NextInt()
    {
        return int.Parse(Next());
    }

    public long NextLong()
    {
        return long.Parse(Next());
    }

    public double NextDouble()
    {
        return double.Parse(Next());
    }

    #endregion

    #region 型変換

    private int[] ToIntArray(string[] array)
    {
        var result = new int[array.Length];
        for (int i = 0; i < array.Length; i++)
        {
            result[i] = int.Parse(array[i]);
        }

        return result;
    }

    private long[] ToLongArray(string[] array)
    {
        var result = new long[array.Length];
        for (int i = 0; i < array.Length; i++)
        {
            result[i] = long.Parse(array[i]);
        }

        return result;
    }

    private double[] ToDoubleArray(string[] array)
    {
        var result = new double[array.Length];
        for (int i = 0; i < array.Length; i++)
        {
            result[i] = double.Parse(array[i]);
        }

        return result;
    }

    #endregion

    #region 配列取得

    public string[] Array()
    {
        if (_pos >= _line.Length)
            _line = Console.ReadLine().Split(Separator);

        _pos = _line.Length;
        return _line;
    }

    public int[] IntArray()
    {
        return ToIntArray(Array());
    }

    public long[] LongArray()
    {
        return ToLongArray(Array());
    }

    public double[] DoubleArray()
    {
        return ToDoubleArray(Array());
    }

    #endregion
}

using System;
using System.Linq;//リストの使用
using System.Collections.Generic;
using System.Text;//テキストの高速出力に必要
class Program
{
	static void Main()
	{
		int n = int.Parse(Console.ReadLine());
		int[] numsA = Array.ConvertAll(Console.ReadLine().Split(' '),int.Parse);
    int[] numsB = Array.ConvertAll(Console.ReadLine().Split(' '),int.Parse);
    int[,] numsSortBefore = new int[n,3];//数値と表裏必要と現在
    int changeCount = 0;
    int answer = 99999;
    bool canChange = true;

    for(long i = 0; i < (1<<n); i++)//２進数で全通り試す
    {
      changeCount = 0;
      canChange = true;
      for(int j = 0; j < n; j++)//00001などに1があるか右側から見る
      {
        if((i&(1<<j)) != 0)
        {
          numsSortBefore[j,0] = numsA[j];
          numsSortBefore[j,1] = 0;
          numsSortBefore[j,2] = 0;
        }
        else//0の場合の処理
        {
          numsSortBefore[j,0] = numsB[j];
          numsSortBefore[j,1] = 1;
          numsSortBefore[j,2] = 0;
        }
        //Console.WriteLine(i+"a"+j+" "+numsSortBefore[j,0]);
      }

      for(int j = n-1; j > 0; j--)
      {
        for(int k = j; k > 0; k--)
        {
          if(numsSortBefore[k-1,0] > numsSortBefore[k,0])
          {
            int swapMemo = numsSortBefore[k-1,0];
            numsSortBefore[k-1,0] = numsSortBefore[k,0];
            numsSortBefore[k,0] = swapMemo;

            numsSortBefore[k-1,2] = 1-numsSortBefore[k-1,2];
            numsSortBefore[k,2] = 1-numsSortBefore[k,2];

            changeCount++;
          }
        }
      }

      for(int j = 0; j < n; j++)
      {
        //Console.WriteLine(i+" "+numsSortBefore[j,1]+" "+numsSortBefore[j,2]);
        if(numsSortBefore[j,1] != numsSortBefore[j,2])
        {
          if(j == n-1)
          {
            canChange = false;
            break;
          }else if((numsSortBefore[j+1,1] != numsSortBefore[j+1,2]) && (numsSortBefore[j,0] == numsSortBefore[j+1,0]))
          {
            changeCount++;
            j++;
          }else
          {
            canChange = false;
            break;
          }
        }
      }

      //Console.WriteLine(i+" "+changeCount+" "+canChange);
      if(canChange) answer = Math.Min(answer,changeCount);

    }

    if(answer == 99999) answer = -1;
		Console.WriteLine(answer);
	}
}

