public class Solver
{
	public void Solve()
	{
		int N = GetInt();
		int[] A = GetInts(N);
		int[] B = GetInts(N);

		int ans = int.MaxValue;
		int comb = (1 << (N / 2)) - 1;
		int end = (1 << N);
		while(comb < end)
		{
			var total = new List<int>();
			var even = new List<int>();
			var odd = new List<int>();
			for(int i = 0; i < N; i++)
			{
				if(contains(comb, i))
				{
					odd.Add((i % 2 == 1) ? A[i] : B[i]);
					total.Add((i % 2 == 1) ? A[i] : B[i]);
				}
				else
				{
					even.Add((i % 2 == 0) ? A[i] : B[i]);
					total.Add((i % 2 == 0) ? A[i] : B[i]);
				}
			}
			odd.Sort();
			even.Sort();

			var merge = new int[N];
			for(int i = 0; i < even.Count; i++)
				merge[i * 2] = even[i];

			for(int i = 0; i < odd.Count; i++)
				merge[i * 2 + 1] = odd[i];

			bool valid = true;
			for(int i = 0; i < N - 1; i++)
			{
				if(A[i] > A[i + 1])
				{
					valid = false;
					break;
				}
			}

			if(valid)
				ans = Min(ans, calc(N, total));

			comb = nextCombination(comb);
		}

		WriteLine((ans == int.MaxValue) ? -1 : ans);
	}

	private bool contains(int s, int x) => ((s >> x) & 1) == 1;

	private int calc(int N, List<int> a)
	{
		int res = 0;
		var bit = new BinaryIndexedTree<int>(51, 0, (x, y) => x + y);
		for(int j = 0; j < N; j++)
		{
			res += j - bit.Query(a[j]);
			bit.Update(a[j], 1);
		}
		return res;
	}
}

public static class BinaryRepresentation
{
	/*
	* initialize: array = { 0, 1, 2, ..., N - 1 } 
	* do { ... } while(nextPermutaion(ref array));
	*/
	private static bool nextPermutation(ref int[] array)
	{
		int len = array.Length;
		int i = len - 2;
		while((i >= 0) && (array[i] > array[i + 1]))
			i--;
		if(i < 0)
			return false;

		int pivot = array[i];
		int j = i + 1;
		while((j < len - 1) && (array[j + 1] > pivot))
			j++;

		int tmp = array[i];
		array[i] = array[j];
		array[j] = tmp;

		Array.Reverse(array, i + 1, len - i - 1);

		return true;
	}

	/* 
	* nCk
	* initialize: comb = (1 << k) - 1
	* while(comb < (1 << n)) { ...; comb = nextCombination(comb); };
	*/
	public static int nextCombination(int comb)
	{
		int x = comb & -comb;
		int y = comb + x;
		return (((comb & ~y) /x) >> 1) | y;
	}

	public static int popcnt(int v) {
		v = v - ((v >> 1) & 0x55555555);
		v = (v & 0x33333333) + ((v >> 2) & 0x33333333);
		return ((v + (v >> 4) & 0xF0F0F0F) * 0x1010101) >> 24;
	}

	public static long popcnt(long v) {
		v = v - ((v >> 1) & 0x5555555555555555);
		v = (v & 0x3333333333333333) + ((v >> 2) & 0x3333333333333333);
		return ((v + (v >> 4) & 0xF0F0F0F0F0F0F0F) * 0x101010101010101) >> 56;
	}
}

public class BinaryIndexedTree<T>
{
	private int N;
	private T Identity;
	private Func<T, T, T> Func;
	private T[] bit;

	public BinaryIndexedTree(int n, T identity, Func<T, T, T> func)
	{
		N = n;
		Identity = identity;
		Func = func;

		bit = new T[N + 1];  // 1-index
		for(int i = 0; i <= N; i++)
			bit[i] = Identity;
	}

	public void Update(int i, T x)
	{
		while(i <= N)
		{
			bit[i] = Func(bit[i], x);
			i += i & -i;
		}
	}

	public T Query(int i)
	{
		T s = Identity;
		while(i > 0)
		{
			s = Func(s, bit[i]);
			i -= i & -i;
		}
		return s;
	}

	/* bit must be monotonically increasing */
	public int LowerBound(T key, Comparison<T> comp, Func<T, T, T> inv)
	{
		if(comp(key, Identity) <= 0)
			return 0;

		int pow = 1;
		while(pow <= N)
			pow <<= 1;
		pow >>= 1;

		int x = 0;
		for(int k = pow; k > 0; k >>= 1)
		{
			if((x + k <= N) && (comp(bit[x + k], key) < 0))
			{
				key = inv(key, bit[x + k]);
				x += k;
			}
		}

		return x + 1;
	}
}

