using System.Linq;

public class Program
{
    private int N;
    private int[] A, B;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        A = sc.IntArray();
        B = sc.IntArray();

        /*
         * 偶数番目
         * 裏返すと奇数番目になる
         *
         * 奇数番目
         * 裏返すと偶数番目になる
         *
         * 2^18全探索
         * 距離が合ってるか
         *
         * 転倒数
         */

        int l = 1 << N;
        int ans = int.MaxValue;
        for (int i = 0; i < l; i++)
        {
            int o;
            if (C(i, out o))
            {
                ans = Math.Min(o, ans);
            }
        }

        Console.WriteLine(ans == int.MaxValue ? -1 : ans);
    }

    private bool C(int l, out int cnt)
    {
        // false A面 true B面
        var b = new bool[N];
        int c = 0;
        cnt = 0;
        for (int i = 0; i < N; i++)
        {
            b[i] = (l & (1 << i)) > 0;
            if (b[i])
            {
                c++;
            }
        }

        if (c % 2 != 0)
        {
            return false;
        }

        var ar = new int[N];
        for (int i = 0; i < N; i++)
        {
            if (b[i])
            {
                ar[i] = B[i];
            }
            else
            {
                ar[i] = A[i];
            }
        }

        Array.Sort(ar);
        // 距離が合ってるか

        var odd = new HashMap();
        var even = new HashMap();
        for (int i = 0; i < N; i++)
        {
            if (i % 2 == 0)
            {
                even[ar[i]].Add(i);
            }
            else
            {
                odd[ar[i]].Add(i);
            }
        }


        // 一番近いやつ
        for (int i = 0; i < N; i++)
        {
            // 奇数番目
            bool od = b[i] ^ (i % 2 == 1);
            int n = b[i] ? B[i] : A[i];

            if (od)
            {
                var arr = odd[n].ToArray();
                if (arr.Length == 0) return false;
                int dist = int.MaxValue;
                int index = -1;
                foreach (int j in arr)
                {
                    if (Math.Abs(i - j) < dist)
                    {
                        dist = Math.Abs(i - j);
                        index = j;
                    }

                    if (Math.Abs(i - j) == dist)
                    {
                        index = Math.Max(index, j);
                    }
                }

                cnt += dist;
                odd[n].Remove(index);
            }
            else
            {
                var arr = even[n].ToArray();
                if (arr.Length == 0) return false;
                int dist = int.MaxValue;
                int index = -1;
                foreach (int j in arr)
                {
                    if (Math.Abs(i - j) < dist)
                    {
                        dist = Math.Abs(i - j);
                        index = j;
                    }

                    if (Math.Abs(i - j) == dist)
                    {
                        index = Math.Max(index, j);
                    }
                }

                cnt += dist;
                even[n].Remove(index);
            }
        }

        cnt /= 2;
        return true;
    }

    public static void Main(string[] args)
    {
        new Program().Solve();
    }
}

