using System;
using System.Linq;

class D
{
	static int[] Read() => Console.ReadLine().Split().Select(int.Parse).ToArray();
	static void Main()
	{
		var n = int.Parse(Console.ReadLine());
		var a = Read();
		var b = Read();

		var p2 = Enumerable.Range(0, n + 1).Select(i => 1 << i).ToArray();
		var m = 1 << 30;

		for (int x = 0; x < p2[n]; x++)
		{
			var c = new (int i, int v, bool rev)[n];
			for (int i = 0; i < n; i++)
				c[i] = (x & p2[i]) == 0 ? (i, a[i], false) : (i, b[i], true);

			var t = 0;
			for (int i = 0; i < n; i++)
				for (int j = i + 1; j < n; j++)
				{
					if (c[j - 1].v <= c[j].v) continue;
					(c[j], c[j - 1]) = (c[j - 1], c[j]);
					t++;
				}

			var ok = true;
			for (int i = 0; i < n; i++)
			{
				if ((i - c[i].i) % 2 != 0 == c[i].rev) continue;
				if (i + 1 == n || c[i].v < c[i + 1].v) { ok = false; break; }

				// 同じ数が続く場合
				for (int j = i + 1; j < n; j++)
				{
					if (c[i].v < c[j].v) break;
					if ((i - c[j].i) % 2 != 0 != c[i].rev) continue;

					// c[j] を c[i] に移動
					for (int k = j; k > i; k--)
					{
						(c[k], c[k - 1]) = (c[k - 1], c[k]);
						t++;
					}
					break;
				}
				if ((i - c[i].i) % 2 != 0 != c[i].rev) { ok = false; break; }
			}
			if (ok) m = Math.Min(m, t);
		}
		Console.WriteLine(m == 1 << 30 ? -1 : m);
	}
}

