using System;
using System.Collections.Generic;
using System.Linq;

public class Solution
{
    public static int PopCount(int bits)
    {
        bits = (bits & 0x55555555) + (bits >> 1 & 0x55555555);
        bits = (bits & 0x33333333) + (bits >> 2 & 0x33333333);
        bits = (bits & 0x0f0f0f0f) + (bits >> 4 & 0x0f0f0f0f);
        bits = (bits & 0x00ff00ff) + (bits >> 8 & 0x00ff00ff);
        return (bits & 0x0000ffff) + (bits >> 16 & 0x0000ffff);
    }

    public static void Main()
    {
        var N = int.Parse(Console.ReadLine());
        var A = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
        var B = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();

        int getCard(int i, int j)
        {
            if ((i - j) % 2 == 0)
            {
                return A[i];
            }
            return B[i];
        }

        var maxMask = 1 << N;
        var step = new int[maxMask, N]; // [used, last]
        for (var mask = 1; mask < maxMask; mask++)
        {
            for (int i = 0; i < N; i++)
            {
                step[mask, i] = int.MaxValue;
            }
        }
        for (int i = 0; i < N; i++)
        {
            step[1 << i, i] = i;
        }

        for (var mask = 1; mask < maxMask; mask++)
        {
            var used = new List<int>();
            var nexts = new List<int>();
            for (int i = 0; i < N; i++)
            {
                if ((mask & (1 << i)) == 0)
                {
                    nexts.Add(i);
                }
                else
                {
                    used.Add(i);
                }
            }

            foreach (var last in used)
            {
                if (step[mask, last] == int.MaxValue)
                {
                    continue;
                }

                var curStep = step[mask, last];
                var lastCard = getCard(last, used.Count - 1);
                for (int move = 0; move < nexts.Count; move++)
                {
                    var next = nexts[move];
                    var nextCard = getCard(next, used.Count);
                    if (lastCard <= nextCard)
                    {
                        var nextMask = mask | (1 << next);
                        step[nextMask, next] = Math.Min(step[nextMask, next], curStep + move);
                    }
                }
            }
        }

        var best = int.MaxValue;
        for (int i = 0; i < N; i++)
        {
            best = Math.Min(best, step[maxMask - 1, i]);
        }
        if (best == int.MaxValue)
        {
            best = -1;
        }

        Console.WriteLine(best);
    }
}

