    public int Number;
    public bool IsFront;
}

internal partial class Solver {
    int[] best;
    public void Run() {
        var n = ni();
        var a = ni(n);
        var b = ni(n);
        var isFront = new bool[n];
        var cards = E.Range(0, n).Select(_ => new Card()).ToArray();
        best = new int[n];
        int ans = int.MaxValue;
        for (int bit = 0; bit < (1 << n); bit++) {
            for (int j = 0; j < n; j++) {
                isFront[j] = (bit & (1 << j)) != 0;
                cards[j].IsFront = isFront[j];
                cards[j].Number = isFront[j] ? a[j] : b[j];
            }
            var result = Try(cards);
            ans = Math.Min(ans, result);
        }
        if (ans == int.MaxValue) ans = -1;
        cout.WriteLine(ans);
    }

    private int Try(Card[] cards) {
        var n = cards.Length;
        int swap = 0;
        for (int i = 0; i < n; i++) {
            best[i] = cards[i].Number;
        }
        Array.Sort(best);
        for (int i = 0; i < n; i++) {
            var target = -1;
            for (int j = i; j < n; j++) {
                if (cards[j].Number == best[i]) {
                    var needFlip = j - i;
                    if ((needFlip % 2 == 0 && cards[j].IsFront) ||
                        (needFlip % 2 == 1 && !cards[j].IsFront)
                        ) {
                        target = j; break;
                    }
                }
            }
            if (target == -1) return int.MaxValue;
            for (int j = target; j > i; j--) {
                var t = cards[j];
                cards[j] = cards[j - 1];
                cards[j - 1] = t;
                cards[j - 1].IsFront ^= true;
                cards[j].IsFront ^= true;
                swap++;
            }
        }
        return swap;
    }
}

