class Solver {
    StreamWriter sw;
    Scan sc;
    void Prt(string a) => sw.WriteLine(a);
    void Prt<T>(IEnumerable<T> a) => Prt(string.Join(" ", a));
    void Prt(params object[] a) => Prt(string.Join(" ", a));
    public Solver(StreamWriter sw) {
        this.sw = sw;
        this.sc = new Scan();
    }

    public void solve() {
        int n = sc.Int;
        var a = sc.IntArr;
        var b = sc.IntArr;
        var dp = new int[1 << n][];
        for (int i = 0; i < (1 << n); i++)
        {
            dp[i] = new int[n];
            for (int j = 0; j < n; j++)
            {
                dp[i][j] = M;
            }
        }
        for (int i = 0; i < n; i++)
        {
            dp[1 << i][i] = i;
        }
        for (int i = 0; i < (1 << n); i++)
        {
            int c = 0;
            for (int j = 0; j < n; j++)
            {
                if (((i >> j) & 1) == 1) {
                    ++c;
                }
            }
            for (int j = 0; j < n; j++)
            {
                if (dp[i][j] == M) continue;
                int cc = 0;
                for (int k = 0; k < n; k++)
                {
                    if (((i >> k) & 1) == 0) {
                        int pp = (c + 1) % 2 == j % 2 ? a[j] : b[j];
                        int p = c % 2 == k % 2 ? a[k] : b[k];
                        if (pp <= p) {
                            dp[i ^ (1 << k)][k] = Math.Min(dp[i ^ (1 << k)][k], dp[i][j] + cc);
                        }
                        ++cc;
                    }
                }
            }
        }
        int ans = dp.Last().Min();
        Prt(ans == M ? -1 : ans);

    }
}

