func solve(scanner *bufio.Scanner, writer *bufio.Writer) {
	n := getNextInt(scanner)
	cc := make([][2]int, n)
	for i := 0; i < n; i++ {
		cc[i][0] = getNextInt(scanner)
	}
	for i := 0; i < n; i++ {
		cc[i][1] = getNextInt(scanner)
	}

	// dp[すでに使った集合][すでに使った中で最後に使ったindex] = 転倒数の和
	dp := make([][]int, 1<<uint(n))
	for i := 0; i < 1<<uint(n); i++ {
		dp[i] = make([]int, n)
		for j := 0; j < n && i > 0; j++ {
			dp[i][j] = math.MaxInt32
		}
	}
	for b := 0; b < 1<<uint(n); b++ {
		for i := 0; i < n; i++ {
			if dp[b][i] == math.MaxInt32 {
				continue
			}
			used := 0
			for j := 0; j < n; j++ {
				if b>>uint(j)&1 == 0 {
					continue
				}
				used++
			}
			for j := 0; j < n; j++ {
