func solve(scanner *bufio.Scanner, writer *bufio.Writer) {
	n := getNextInt(scanner)
	cc := make([][2]int, n)
	for i := 0; i < n; i++ {
		cc[i][0] = getNextInt(scanner)
	}
	for i := 0; i < n; i++ {
		cc[i][1] = getNextInt(scanner)
	}

	dp := make([][]int, 1<<uint(n))
	for i := 0; i < 1<<uint(n); i++ {
		dp[i] = make([]int, n)
		for j := 0; j < n && i > 0; j++ {
			dp[i][j] = math.MaxInt32
		}
	}
	for b := 0; b < 1<<uint(n); b++ {
		sum := 0
		for i := 0; i < n; i++ {
			sum += (b >> uint(i)) & 1
		}
		for i := 0; i < n; i++ {
			if b == 0 {
				dp[b|1<<uint(i)][i] = i
				continue
			}
			if (b>>uint(i))&1 == 1 {
				continue
			}
			for j := 0; j < n; j++ {
				if (b>>uint(j))&1 != 1 {
					continue
				}
				if cc[j][absint(j-sum+1)%2] > cc[i][absint(i-sum)%2] {
					continue
				}
				if dp[b|1<<uint(i)][i] > dp[b][j]+absint(i-sum) {
					dp[b|1<<uint(i)][i] = dp[b][j] + absint(i-sum)
				}
			}
		}
	}

	ans := math.MaxInt32
	for i := 0; i < n; i++ {
		if dp[1<<uint(n)-1][i]%2 != 0 {
			continue
		}
		if ans > dp[1<<uint(n)-1][i] {
			ans = dp[1<<uint(n)-1][i]
		}
	}

	if ans == math.MaxInt32 {
		ans = -2
	}

	fmt.Fprintln(writer, ans/2)
}

