	INF_BIT60    = 1 << 60
	INF_INT32    = math.MaxInt32
	INF_BIT30    = 1 << 30
	NIL          = -1

	// for dijkstra, prim, and so on
	WHITE = 0
	GRAY  = 1
	BLACK = 2
)

var (
	n    int
	A, B []int

	dp [1<<20 + 5][50 + 5]int
)

func main() {
	n = ReadInt()
	A = ReadIntSlice(n)
	B = ReadIntSlice(n)

	for i := 0; i < 1<<uint(n); i++ {
		for j := 0; j <= 50; j++ {
			dp[i][j] = INF_BIT30
		}
	}
	dp[0][0] = 0

	for S := 0; S < 1<<uint(n); S++ {
		pc := PopCount(S)

		// iは最後尾の値
		for i := 0; i <= 50; i++ {

			// jは次に並べるカード
			add := 0
			for j := 0; j < n; j++ {
				// すでに並んでいたらcontinue
				if NthBit(S, j) == 1 {
					add++
					continue
				}

				posj := pc
				var vj int
				if AbsInt(posj-j)%2 == 0 {
					vj = A[j]
				} else {
					vj = B[j]
				}

				if vj >= i {
					ChMin(&dp[S|(1<<uint(j))][vj], dp[S][i]+(j-add))
				}
			}
		}
	}

	ans := INF_BIT30
	for i := 0; i <= 50; i++ {
		ChMin(&ans, dp[1<<uint(n)-1][i])
	}

	if ans >= INF_BIT30 {
		fmt.Println(-1)
	} else {
		fmt.Println(ans)
	}
}

// ChMin accepts a pointer of integer and a target value.
// If target value is SMALLER than the first argument,
//	then the first argument will be updated by the second argument.
func ChMin(updatedValue *int, target int) bool {
	if *updatedValue > target {
		*updatedValue = target
		return true
	}
	return false
}

// AbsInt is integer version of math.Abs
func AbsInt(a int) int {
	if a < 0 {
		return -a
	}
	return a
}

// NthBit returns nth bit value of an argument.
// n starts from 0.
func NthBit(num int, nth int) int {
	return num >> uint(nth) & 1
}

// OnBit returns the integer that has nth ON bit.
// If an argument has nth ON bit, OnBit returns the argument.
func OnBit(num int, nth int) int {
	return num | (1 << uint(nth))
}

// OffBit returns the integer that has nth OFF bit.
// If an argument has nth OFF bit, OffBit returns the argument.
func OffBit(num int, nth int) int {
	return num & ^(1 << uint(nth))
}

// PopCount returns the number of ON bit of an argument.
func PopCount(num int) int {
	res := 0

	for i := 0; i < 70; i++ {
		if ((num >> uint(i)) & 1) == 1 {
			res++
		}
	}

	return res
}

