func solve(scanner *bufio.Scanner, writer *bufio.Writer) {
	n := getNextInt(scanner)
	cc := make([]Card, n)
	cm := make(CC, n)
	for i := 0; i < n; i++ {
		cc[i].a = getNextInt(scanner)
	}
	for i := 0; i < n; i++ {
		cc[i].b = getNextInt(scanner)
	}

	ans := math.MaxInt32
	for b := 0; b < 1<<uint(n); b++ {
		for i := 0; i < n; i++ {
			cm[i].i = i
			if b>>uint(i)&1 == 0 {
				cm[i].v = cc[i].a
				cm[i].r = 0
			} else {
				cm[i].v = cc[i].b
				cm[i].r = 1
			}
		}
		sort.Sort(cm)
		valid := true
		sum := 0
		for i := 0; i < n && valid; i++ {
			if absint(cm[i].i-i)%2 != cm[i].r {
				valid = false
				if i > 0 && cm[i-1].v == cm[i].v && absint(cm[i-1].i-i+1)%2 != cm[i-1].r {
					cm[i-1].i, cm[i].i = cm[i].i, cm[i-1].i
					valid = true
				}
				if i < n-1 && cm[i+1].v == cm[i].v && absint(cm[i+1].i-i-1)%2 != cm[i+1].r {
					cm[i+1].i, cm[i].i = cm[i].i, cm[i+1].i
					valid = true
				}
			}
			sum += absint(cm[i].i - i)
		}
		if valid && ans > sum {
			ans = sum
		}
	}

	if ans == math.MaxInt32 {
		ans = -2
	}

	fmt.Fprintln(writer, ans/2)
}

