	var idx int
	ans := l[idx]
	for i, n := range l {
		if n < ans {
			ans = n
			idx = i
		}
	}
	return idx, ans
}

func run(a []int, b []int, i int) ([]int, []int) {
	a[i], a[i+1], b[i], b[i+1] = b[i+1], b[i], a[i+1], a[i]

	return a, b
}

func check(a []int) bool {
	for i := 0; i < len(a)-1; i++ {
		if a[i] > a[i+1] {
			return false
		}
	}
	return true
}

var (
	mem map[string]bool
)

func loopCheck(a []int, b []int) bool {
	c := make([]string, len(a)+len(b))

	for i, x := range append(a, b...) {
		c[i] = string(x)
	}
	key := strings.Join(c, ",")
	if mem[key] {
		return true
	}
	mem[key] = true
	return false
}

type Param struct {
	A     []int
	B     []int
	idx   int
	count int
}

func bfs(p Param) ([]Param, bool) {
	var q []Param
	i := p.idx
	a := make([]int, len(p.A))
	b := make([]int, len(p.B))
	copy(a, p.A)
	copy(b, p.B)
	a[i], a[i+1], b[i], b[i+1] = b[i+1], b[i], a[i+1], a[i]
	if check(a) {
		return nil, true
	}
	if loopCheck(a, b) {
		return nil, false
	}
	for j := 0; j < len(p.A)-1; j++ {
		if j != i {
			q = append(q, Param{A: a, B: b, idx: j, count: p.count + 1})
		}
	}
	return q, false
}

