		return
	}
	var que []Param
	for i := 0; i < n-1; i++ {
		que = append(que, Param{A: a, B: b, idx: i, count: 0})
	}
	for i := 0; i < len(que); i++ {
		q, fin := bfs(que[i])
		if fin {
			ans = que[i].count + 1
			break
		}
		que = append(que, q...)
	}
