func solve(scanner *bufio.Scanner, writer *bufio.Writer) {
	n := getNextInt(scanner)
	cc := make([][2]int, n)
	for i := 0; i < n; i++ {
		cc[i][0] = getNextInt(scanner)
	}
	for i := 0; i < n; i++ {
		cc[i][1] = getNextInt(scanner)
	}

	ans := math.MaxInt32
	ss := make([]int, n)
	for b := 0; b < 1<<uint(n); b++ {
		for i := 0; i < n; i++ {
			ss[i] = cc[i][b>>uint(i)&1]
		}
		sort.Ints(ss)
		used := make([]bool, n)

		sum := 0
		for i := 0; i < n; i++ {
			for j := 0; j < n; j++ {
				if used[j] {
					continue
				}
				if absint(i-j)%2 != b>>uint(j)&1 {
					continue
				}
				if ss[i] != cc[j][b>>uint(j)&1] {
					continue
				}
				used[j] = true
				sum += absint(i - j)
				break
			}
		}
		valid := true
		for i := 0; i < n && valid; i++ {
			valid = used[i]
		}
		if valid == false {
			continue
		}
		if ans > sum {
			ans = sum
		}

	}

	if ans == math.MaxInt32 {
		ans = -2
	}

	fmt.Fprintln(writer, ans/2)
}

