        if (i == N) {
            if (res == -1) res = int.max;
            bit.do_init();
            int rr;
            foreach (j, d; ds) {
                bit.put(d+1, 1);
                rr += (j+1) - bit.query((d+1).to!size_t);
            }
            res = min(res, rr);
        } else {
            if (DP[i][p][s]) return;
            DP[i][p][s] = true;
