        foreach (i; 0..N) {
            if ((1<<i) & s) {
                cs ~= Card(i, BS[i], true);
            } else {
                cs ~= Card(i, AS[i], false);
            }
        }
        sort!"a.n == b.n ? a.i < b.i : a.n < b.n"(cs);

        bool is_diff(int i) {
            if (cs[i].is_red) {
                return i%2 == cs[i].i%2;
            } else {
                return i%2 != cs[i].i%2;
            }
        }

        foreach (i; 0..N) {
            auto j = i+1;
            while (j < N && is_diff(i) && cs[i].n == cs[j].n) {
                if (is_diff(j)) {
                    swap(cs[i], cs[j]);
                    if (is_diff(i))
                        swap(cs[i], cs[j]);
                }
                ++j;
            }

            if (is_diff(i)) goto ng;
        }

        {
            if (res == -1) res = int.max;
            auto bit = bitree!("a + b", 0L, long)(N+1);
            long rr;
            foreach (j, c; cs) {
                bit.put(c.i+1, 1);
                rr += (j+1) - bit.query((c.i+1).to!size_t);
            }
            res = min(res, rr);
        }
        ng:
    }

