    auto b = readln.split.to!(int[]);

    if (N == 1) {
        writeln(0);
        return;
    }

    auto ans = inf;

    foreach (set ; 0 .. 1 << N) {
        Card[] cs;

        foreach (i ; 0 .. N) {
            if (set & 1 << i) {
                cs ~= Card(a[i], 1);
            }
