int solve(int N, Card[] cs) {
    int res;

    foreach (i ; 0 .. N) {
        foreach_reverse (j ; i + 1 .. N) {
            if (cs[j - 1].x > cs[j].x) {
                swap(cs[j - 1], cs[j]);
                cs[j - 1].h ^= 1;
                cs[j].h ^= 1;
                res++;
            }
        }
    }

    foreach (i ; 0 .. N - 2) {
        assert(cs[i].x <= cs[i + 1].x);

        if (!cs[i].h) {
            if (cs[i].x != cs[i + 1].x) {
                return inf;
            }
            if (!cs[i + 1].h) {
                res++;
                cs[i + 1].h ^= 1;
            }
            else if (cs[i + 2].x == cs[i].x && cs[i + 2].h) {
                res += 2;
                cs[i + 2].h ^= 1;
            }
            else {
                return inf;
            }
        }
    }

    if (cs[N - 2].h && cs[N - 1].h) {
        return res;
    }
    else if (cs[N - 2].x == cs[N - 1].x && !cs[N - 2].h && !cs[N - 1].h) {
        res++;
    }
    else {
        return inf;
    }

    return res;
}



