    foreach (i ; 0 .. N) {
        foreach_reverse (j ; i + 1 .. N) {
            if (cs[j - 1].x > cs[j].x) {
                swap(cs[j - 1], cs[j]);
                cs[j - 1] = Card(cs[j - 1].x, cs[j - 1].h ^ 1);
                cs[j] = Card(cs[j].x, cs[j].h ^ 1);
