void main() {
  long N;
  scanln(N);

  long[] as = readln.split.to!(long[]);
  long[] bs = readln.split.to!(long[]);

  long[] xs = new long[N];
  long[] ys = new long[N];
  foreach(i; 0..N) {
    if (i%2==0) {
      xs[i] = as[i];
      ys[i] = bs[i];
    } else {
      ys[i] = as[i];
      xs[i] = bs[i];
    }
  }

  long ans = INF;
  long[] ps = new long[N];
  long[] qs = new long[N];
  long[] rs = new long[N];
  long[] us = new long[N];
  foreach(bits; 0L..1L<<N) {
    long s = 0;
    foreach(i; 0..N) {
      if (bits>>i&1) {
        ps[s] = xs[i];
        s++;
      } else {
        qs[i-s] = ys[i];
      }
    }
    if (s != N.ceil(2)) {
      continue;
    }
    {
      bool ok = true;
      long[] ps2 = ps[0..s].dup.sort!"a<b".array;
      long[] qs2 = qs[0..N-s].dup.sort!"a<b".array;
      long t1 = -INF;
      long t2 = -INF;
      foreach(i; 0..ps2.length) {
        t2 = ps2[i];
        ok &= t1 <= t2;
        t1 = t2;
        if (i < qs2.length) {
          t2 = qs2[i];
          ok &= t1 <= t2;
          t1 = t2;
        }
      }
      if (!ok) continue;

      foreach(i; 0..s) {
        {
          long t = INF;
          long k = -1;
          foreach(j, p; ps[0..s]) {
            if (p < t) {
              t = p;
              k = j;
            }
          }
          ps2[k] = 2*i;
          ps[k] = INF;
        }
        if (i < N-s) {
          long t = INF;
          long k = -1;
          foreach(j, q; qs[0..N-s]) {
            if (q < t) {
              t = q;
              k = j;
            }
          }
          qs2[k] = 2*i+1;
          qs[k] = INF;
        }
      }

      s = 0;
      foreach(i; 0..N) {
        if (bits>>i&1) {
          us[i] = ps2[s];
          s++;
        } else {
          us[i] = qs2[i-s];
        }
      }
    }
    ans.ch!min(
      us.inversion
    );
  }
  if (ans == INF) {
    writeln(-1);
  } else {
    ans.writeln;
  }
}

long inversion(long[] xs) {
  long N = xs.length;

  long[long] aa;
  xs.dup.sort!"a<b".uniq.enumerate.each!(a => aa[a.value] = a.index);

  long[] ys = xs.map!(x => aa[x]).array;

  auto seg = SegTree!(long, (a, b) => a+b, 0L)(N+1);
  long res = 0;
  foreach(i; 0..N) {
    res += seg.query(ys[i], N);
    seg.update(ys[i], seg.get(ys[i]) + 1);
  }
  return res;
}

