enum long INF = long.max/5;
enum long MOD = 10L^^9+7;

void main() {
  long N;
  scanln(N);

  long[] as = readln.split.to!(long[]);
  long[] bs = readln.split.to!(long[]);

  long[][] dp = new long[][](1<<N, N);
  foreach(bits; 0..1<<N) dp[bits][] = INF;
  foreach(i; 0..N) {
    dp[1<<i][i] = i;
  }

  foreach(bits; 0..1<<N) {
    foreach(i; 0..N) {
      if (!(bits>>i&1)) continue;
      foreach(j; 0..N) {
        if (bits>>j&1) continue;
        long k = bits.popcnt;
        long x = abs(i-(k-1))%2==0 ? as[i] : bs[i];
        long y = abs(j-k)%2==0 ? as[j] : bs[j];
        if (y < x) continue;
        long l = j;
        foreach(m; j+1..N) {
          if (bits>>m&1) {
            l++;
          }
        }
        assert(l >= k);
        dp[bits|(1<<j)][j].ch!min(dp[bits][i] + abs(l-k));
      }
    }
  }

  long ans = dp[(1<<N)-1].reduce!min;
  if (ans == INF) {
    writeln(-1);
  } else {
    ans.writeln;
  }
}

