            auto bit = bitree!("a + b", 0, int)(N+1);
            int rr;
            foreach (j, d; ds) {
                bit.put(d+1, 1);
                rr += (j+1) - bit.query((d+1).to!size_t);
            }
            res = min(res, rr);
        } else {
            foreach (j, c; cs) if (!((1<<j) & s)) {
                auto x = i%2 == j%2 ? c.a : c.b;
                if (x >= p) {
                    ds[i] = j.to!int;
                    solve(i+1, x, s | (1<<j));
                }
            }
        }
    }
