int solve(int N, Card[] cs) {
    int res;

    foreach (i ; 0 .. N) {
        foreach_reverse (j ; i + 1 .. N) {
            if (cs[j - 1].x > cs[j].x) {
                swap(cs[j - 1], cs[j]);
                cs[j - 1].h ^= 1;
                cs[j].h ^= 1;
                res++;
            }
        }
    }

    foreach (i ; 0 .. N - 1) {
        assert(cs[i].x <= cs[i + 1].x);

        if (!cs[i].h) {
            if (cs[i].x != cs[i + 1].x || cs[i + 1].h) {
                return inf;
            }
            cs[i + 1].h ^= 1;
            res++;
        }
    }

    if (!cs[N - 1].h) {
        return inf;
    }

    return res;
}



