proc ceilPowerOfTwoMinusOne*(x: Natural): Natural {.noSideEffect.} =
  result = x
  when defined(cpu64):
    result = result or (result shr 32)
  when sizeof(int) > 2:
    result = result or (result shr 16)
  when sizeof(int) > 1:
    result = result or (result shr 8)
  result = result or (result shr 4)
  result = result or (result shr 2)
  result = result or (result shr 1)

proc ceilPowerOfTwo*(x: Natural): Natural {.noSideEffect.} = ceilPowerOfTwoMinusOne(x-1) + 1

proc floorPowerOfTwo*(x: Natural): Natural {.noSideEffect.} = ceilPowerOfTwo(x+1) shr 1

proc msbthPowerOfTwo*(x:Natural): Natural {.noSideEffect.} = floorPowerOfTwo(x)

proc msb(n:int):int {.noSideEffect.} =
  if n <= 0:
    return -1
  result = 0
  var n = n
  when defined(cpu64):
    if n shr 32 != 0:
      result += 32
      n = n shr 32
  when sizeof(int) > 2:
    if n shr 16 != 0:
      result += 16
      n = n shr 16
  when sizeof(int) > 1:
    if n shr 8 > 0:
      result += 8
      n = n shr 8
  if n shr 4 > 0:
      result += 4
      n = n shr 4
  if n shr 2 > 0:
      result += 2
      n = n shr 2
  if n shr 1 > 0:
      result += 1
      n = n shr 1

proc floorLogTwo(n:int):int {.noSideEffect.} = msb(n)

proc ceilLogTwo(n:int):int {.noSideEffect.} = floorLogTwo(n-1)+1

proc sum(n:int):int {.noSideEffect.}=
  result = 0
  for i in 0..<64:
    result += n[i]

