proc invertion(xs: var seq[(int, int)]; flipped: var seq[bool]; l = 0; r = N): int =
  if r-l == 1: return 0
  let
    mid = (r+l) div 2
  result += xs.invertion(flipped, l, mid)
  result += xs.invertion(flipped, mid, r)
  var
    i = l
    k = mid
    tmp = newSeq[(int, int)](0)
  while i < mid or k < r:
    if i == mid:
      tmp.add(xs[k])
      k.inc
    elif k == r:
      tmp.add(xs[i])
      result += k-mid
      flipped[xs[i][1]] = flipped[xs[i][1]] xor ((k-mid) mod 2 == 1)
      i.inc
    else:
      if xs[i][0] > xs[k][0]:
        tmp.add(xs[k])
        flipped[xs[k][1]] = flipped[xs[k][1]] xor ((mid-i) mod 2 == 1)
        k.inc
      else:
        tmp.add(xs[i])
        flipped[xs[i][1]] = flipped[xs[i][1]] xor ((k-mid) mod 2 == 1)
        result += k-mid
        i.inc
  for i in range(l, r):
    xs[i] = tmp[i-l]

