def solve():
    N = int(input())
    A = [int(a) for a in input().split()]
    B = [int(b) for b in input().split()]

    minmove = 1000000000
    for i in range(2 ** N):
        b = i
        back = 0
        Num = [None] * N
        original = dict()
        for j in range(N):
            if b % 2 == 0:
                Num[j] = A[j]
            else:
                Num[j] = B[j]
                back += 1
            if Num[j] not in original: original[Num[j]] = {j}
            else: original[Num[j]] |= {j}
            b //= 2
        if back % 2 > 0: continue
        Num.sort() #実現したい数列

        appeared = set()
        move = 0
        for j, n in enumerate(Num): #このソートが実現できるか
            for o in original[n]:
                if abs(j - o) % 2 == 0 and A[o] == n:
                    original[n] -= {o}
                    for key in appeared:
                        if key > o: move += 1
                    appeared |= {o}
                    break
                elif abs(j - o) % 2 == 1 and B[o] == n:
                    original[n] -= {o}
                    for key in appeared:
                        if key > o: move += 1
                    appeared |= {o}
                    break
            else: #実現できない
                break
        else: #実現できるため、操作回数を求める
            minmove = min(minmove, move)

    if minmove == 1000000000: print(-1)
    else: print(minmove)

    return 0

