from collections import defaultdict


def solve(n, cards):
    dp = {(1 << n) - 1: {0: 0}}
    for d in range(n):
        ndp = defaultdict(lambda: defaultdict(lambda: 1000000))
        for state, scores in dp.items():
            k = state
            curr = 0
            while k:
                b = k & -k
                i = b.bit_length() - 1
                num = cards[i][(d - i) % 2]
                curr_dp = ndp[state ^ b]
                prev_num = 1000000
                for score, left_num in sorted(scores.items()):
                    if left_num > num:
                        continue
                    if prev_num <= left_num:
                        continue
                    curr_dp[score + curr] = min(curr_dp[score + curr], num)
                    prev_num = left_num
                k ^= b
                curr += 1

        if len(ndp) == 0:
            return -1
        dp = ndp
    if 0 in dp and len(dp[0]) > 0:
        return min(dp[0].keys())
    else:
        return -1


