import sys


class Solution:
    def __init__(self):
        self.minimum = sys.maxsize

    def check(self, cards):
        for i in range(len(cards) - 1):
            if cards[i][0] > cards[i + 1][0]:
                return False
        return True

    def swapAndFlip(self, i, j, cards):
        cards[i], cards[j] = cards[j], cards[i]
        cards[i][0], cards[i][1] = cards[i][1], cards[i][0]
        cards[j][0], cards[j][1] = cards[j][1], cards[j][0]

    def dfs(self, start, ops, cards):
        if start == len(cards):
            if self.check(cards):
                self.minimum = min(self.minimum, ops)
            return
        self.dfs(start + 1, ops, cards)
        for i in range(start + 1, len(cards)):
            self.swapAndFlip(start, i, cards)
            ops += 1
            self.dfs(start + 1, ops, cards)
            self.swapAndFlip(start, i, cards)
            ops -= 1

    def minNumOperations(self, upSides, downSides):
        self.minimum = sys.maxsize
        self.dfs(0, 0, [[upSides[x], downSides[x]] for x in range(len(upSides))])
        return self.minimum if self.minimum < sys.maxsize else -1


