def solve(n, a_list, b_list):

    res = 10 ** 9 + 7

    for p in product([0, 1], repeat=n):
        if sum(p) % 2 == 1:
            continue

        r = 0
        q = [0] * n

        c_list = [a for a in a_list]
        for i in range(n):
            if p[i] == 1:
                c_list[i] = b_list[i]
        c_list_s = list(sorted(c_list))

        # r
        for i in range(n - 1):
            for j in range(i + 1, n):
                if c_list[i] > c_list[j]:
                    r += 1
                    q[i] += 1
                    q[j] += 1

        used = [0] * n
        d = []
        for k in range(n):
            for i in range(n):
                if c_list[i] == c_list_s[k] and not used[i]:
                    used[i] = 1
                    j = i
                    break
            d.append((p[j] + q[j]) % 2)
            if k == n - 1:
                if sum(d) % 2 == 0:
                    for i in range(len(d)):
                        if d[i] == 1:
                            r += 1
                            d[i + 1] = 1 - d[i + 1]
                else:
                    r += 10 ** 9 + 7
                d = []
            elif c_list_s[k] != c_list_s[k + 1]:
                if sum(d) % 2 == 0:
                    for i in range(len(d)):
                        if d[i] == 1:
                            r += 1
                            d[i + 1] = 1 - d[i + 1]
                else:
                    r += 10 ** 9 + 7
                d = []

        res = min(res, r)
    # print(res)
    if res < 10 ** 9 + 7:
        return res
    else:
        return -1


