        for j in range(N):
            if l&(1<<j)>0:
                if j%2==0:
                    E[B[j]] += 1
                    L.append(B[j])
                else:
                    O[B[j]] += 1
                    L.append(B[j])
            else:
                if j%2==0:
                    O[A[j]] += 1
                    L.append(A[j])
                else:
                    E[A[j]] += 1
                    L.append(A[j])
        if (len(O)-len(E))!=N%2:
            continue
        C = deepcopy(L)
        L.sort()
        for i,l in enumerate(L):
            if i%2==0:
                O[l] -= 1
            else:
                E[l] -= 1
        flag = True
        for o in O.values():
            if o!=0:
                flag = False
                break
        for e in E.values():
