def solve(N: int, A: "List[int]", B: "List[int]"):

    AB = list(zip(A,B))
    answer = 10**18

    #0が表,1が裏返す
    for bit in product([0,1],repeat=N):
        one_count = bit.count(1)
        if one_count%2 == 1:
            continue

        num_list = []
        #(数字,表か裏か,元々のindex)
        for i in range(N):
            num_list.append((AB[i][bit[i]],bit[i],i))

        num_list.sort(key= lambda x: (x[0],x[1]))

        move_dist = 0
        for i in range(N):
            for j in range(i+1,N):
                if num_list[i][2] > num_list[j][2]:
                    move_dist+=1

        else: ## 可能な移動である
            answer = min(answer,move_dist)

    if answer == 10**18:
        print(-1)
    else:
        print(answer)
    return


