        res = 0
        for i in range(N):
            idx = bisect_left(B,A[i])
            inverse = i - BIT.sum(idx+1)
            res += inverse
            BIT.add(idx+1,1)
        return res


    def check(mask): 
        """
        ビットが立ってるところは裏
        裏になるものは元いる位置から奇数移動
        表になるものは元いる位置から偶数移動
        """
        C=[0]*N
        for i in range(N):
            if (mask>>i&1):
                C[i] = (B[i],i)
            else:
                C[i] = (A[i],i)

        C.sort()
        dic = defaultdict(lambda : deque())
        for j,(c,i) in enumerate(C):
            dic[c,j&1].append(j)

        indexes = []
        for i in range(N):
            if (mask>>i&1):
                num,is_odd_idx = (B[i],i&1)
                if dic[num,is_odd_idx^1]:
                    idx = dic[num,is_odd_idx^1].popleft()
