def sortable(m, A, B):
    if len(A) == 1:
        return 0 if m <= A[0] else -1
    t = INF
    for i in range(len(A)):
        n = A[i] if i % 2 == 0 else B[i]
        if n < m:
            continue
        x = sortable(n, B[0:i] + A[i + 1:], A[0:i] + B[i + 1:])
        if x >= 0:
            t = min(t, x + i)
    if t != INF:
        return t
    return -1


