def is_non_decreasing(data):
    for i in range(len(data)-1):
        if data[i+1] < data[i]:
            return False
    return True



def search(a,b,depth):
    if is_non_decreasing(a):
        return True
    if depth == 0:
        return False

    for i in range(len(a)-1):
        a[i], b[i], a[i+1], b[i+1] = b[i+1], a[i+1], b[i], a[i]

        result = search(a,b,depth-1)

        a[i], b[i], a[i+1], b[i+1] = b[i+1], a[i+1], b[i], a[i]

        if result:
            return True

    return False

