                if b[i] <= a[j]:
                    v[i+n].append(j)
    B = 1<<n
    dp = [[float("inf")]*N for i in range(B)]
    for i in range(N):
        if i < n and i&1:
            continue
        if i >= n and not (i+n)&1:
            continue
        j = i if i < n else i-n
        dp[1<<j][i] = 0
    bitcount = [bin(i).count("1") for i in range(B)]
