    def check(mask): 
        """
        ビットが立ってるところは裏
        裏になるものは元いる位置から奇数移動
        表になるものは元いる位置から偶数移動
        """
        C=[0]*N
        for i in range(N):
            if (mask>>i&1):
                C[i] = (B[i],i)
            else:
                C[i] = (A[i],i)

        C.sort()
        dic = defaultdict(lambda : deque())
        for j,(c,i) in enumerate(C):
