def solve(N: int, A: "List[int]", B: "List[int]"):

    AB = list(zip(A,B))
    answer = 10**18

    #0が表,1が裏返す
    for bit in product([0,1],repeat=N):
        one_count = bit.count(1)
        if one_count%2 == 1:
            continue

        num_list = []
        #(数字,表か裏か,元々のindex)
        for i in range(N):
            num_list.append((AB[i][bit[i]],bit[i],i))

        num_list.sort(key= lambda x: (x[0],x[2]))

        move_dist = 0
        for i in range(N):
            _, flag, index = num_list[i]

            if abs(i-index)%2 != flag:
                break
            move_dist += abs(i-index)
        else: ## 可能な移動である
            if move_dist%2 == 0:
                answer = min(answer,move_dist//2)

    if answer == 10**18:
        print(-1)
    else:
        print(answer)
    return


