    for i in not_used:
        if (index - i) % 2 == 0:
            if A[i] >= cur_elem:
                cost_delta = 0
                for j in range(i, N):
                    if j not in not_used:
                        cost_delta += 1
                new_cost = cost + cost_delta
                if new_cost < cur_min:
                    if index + 1 == N:
                        cur_min = min(cur_min, new_cost)
                    else:
                        not_used.discard(i)
                        cur_min = min(cur_min, solve(index + 1, A[i], new_cost, cur_min))
                        not_used.add(i)
