import numpy as np

def select(d, index_list, list_min):
    while True:
        uo = len(index_list)%2
        index = np.argmin(d[uo])
        if d[uo][index] == 100:
            if len(d[0]) == len(index_list):
                return index_list
            else:
                return -1
        if list_min > d[uo][index]:
            d[uo][index] = 100
            continue
        tmp = d[-uo-1][index]
        d[0][index], d[1][index] = 100, 100
        ret = select(d, index_list + [index], d[uo][index])

        if ret != -1:
            break
        else:
            d[-uo-1][index] = tmp
    return ret


