def solve(not_used, index, cur_elem, cost, cur_min):
    #print("\t" * index, cur_elem, cost)
    if index == N:
        return cost
    for i in not_used:
        if (index - i) % 2 == 0:
            if A[i] >= cur_elem:
                cost_delta = 0
                for j in range(i, N):
                    if j not in not_used:
                        cost_delta += 1
                new_cost = cost + cost_delta
                if new_cost < cur_min:
                    cur_min = min(cur_min, solve(not_used - {i}, index + 1, A[i], new_cost, cur_min))
        else:
            if B[i] >= cur_elem:
                cost_delta = 0
                for j in range(i, N):
                    if j not in not_used:
                        cost_delta += 1
                new_cost = cost + cost_delta
                if new_cost < cur_min:
                    cur_min = min(cur_min, solve(not_used - {i}, index + 1, B[i], new_cost, cur_min))
    return cur_min

