fn solve<R: BufRead, W: Write>(reader: R, mut writer: W) {
  let mut _scanner = spella::io::Scanner::new(reader);

  #[allow(unused_macros)]
  macro_rules! scan {
    ($T:ty) => {
      _scanner.next::<$T>().unwrap().unwrap()
    };
    ($($T:ty),+) => {
      ($(scan!($T)),+)
    };
    ($($T:ty),+; $n:expr $(; $m:expr)*) => {{
      (0..$n).map(|_| scan!($($T),+ $(; $m)*)).collect::<Vec<_>>()
    }};
  }

  #[allow(unused_macros)]
  macro_rules! scan_iter {
    ($($T:ty),+; $n:expr) => {
      (0..$n).map(|_| scan!($($T),+))
    };
  }

  #[allow(unused_macros)]
  macro_rules! print {
    ($fmt:expr) => {
      write!(writer, $fmt).unwrap()
    };
    ($fmt:expr, $($arg:tt)*) => {
      write!(writer, $fmt, $($arg)*).unwrap()
    };
  }

  #[allow(unused_macros)]
  macro_rules! println {
    ($fmt:expr) => {
      writeln!(writer, $fmt).unwrap()
    };
    ($fmt:expr, $($arg:tt)*) => {
      writeln!(writer, $fmt, $($arg)*).unwrap()
    };
  }

  #[allow(unused_macros)]
  macro_rules! eprint {
    ($fmt:expr) => {
      #[cfg(debug_assertions)]
      write!(std::io::stderr(), $fmt).unwrap()
    };
    ($fmt:expr, $($arg:tt)*) => {
      #[cfg(debug_assertions)]
      write!(std::io::stderr(), $fmt, $($arg)*).unwrap()
    };
  }

  #[allow(unused_macros)]
  macro_rules! eprintln {
    ($fmt:expr) => {
      #[cfg(debug_assertions)]
      writeln!(std::io::stderr(), $fmt).unwrap()
    };
    ($fmt:expr, $($arg:tt)*) => {
      #[cfg(debug_assertions)]
      writeln!(std::io::stderr(), $fmt, $($arg)*).unwrap()
    };
  }

  #[allow(unused_macros)]
  macro_rules! dbg {
    ($($x:expr),+) => {{
      eprintln!(concat!("[{}:{}] ", $(stringify!($x), " = {:?}; "),+), file!(), line!(), $($x),+);
    }};
  }

  fn inversion_number<T: Ord>(s: &[T]) -> usize {
    let mut cnt = 0;
    for i in 0..s.len() {
      for j in i..s.len() {
        if s[i] > s[j] {
          cnt += 1;
        }
      }
    }
    cnt
  }

  let n = scan!(usize);
  let a = scan!(u8; n);
  let b = scan!(u8; n);

  let mut ans = None;

  'outer: for v in 0u32..1 << n {
    {
      let mut cnt = 0;
      for i in 0..n {
        let bit = v & (1 << i);
        if cnt % 2 != 0 && bit == 0 {
          continue 'outer;
        }
        if bit != 0 {
          cnt += 1;
        } else {
          cnt = 0;
        }
      }
      if cnt % 2 != 0 {
        continue 'outer;
      }
    }

    let mut x = Vec::with_capacity(n);
    let mut y = Vec::with_capacity(n);
    let mut z = Vec::with_capacity(n);
    {
      let mut x_i = 0;
      let mut y_i = 0;
      for i in 0..n {
        let bit = v & (1 << i);
        dbg!(i, bit != 0, x, y, z);
        if (bit == 0) ^ (i % 2 == 0) {
          if bit == 0 {
            y.push(a[y_i * 2 + 1]);
          } else {
            y.push(b[y_i * 2 + 1]);
          }
          z.push(true);
          y_i += 1;
        } else {
          if bit == 0 {
            x.push(a[x_i * 2]);
          } else {
            x.push(b[x_i * 2]);
          }
          z.push(false);
          x_i += 1;
        }
      }
    }
    dbg!(x);
    dbg!(y);
    dbg!(z);

    let mut w = Vec::with_capacity(n);
    for i in 0..n {
      if i % 2 == 0 {
        w.push(x[i / 2]);
      } else {
        w.push(y[i / 2]);
      }
    }
    dbg!(w);

    x.sort();
    y.sort();
    let mut sorted = true;
    {
      let mut prev = 0;
      let mut x_i = 0;
      let mut y_i = 0;
      for i in 0..n {
        if z[i] == false {
          sorted &= x[x_i] >= prev;
          prev = x[x_i];
          x_i += 1;
        } else {
          sorted &= y[y_i] >= prev;
          prev = y[y_i];
          y_i += 1;
        }
      }
    }
    dbg!(sorted);
    if sorted {
      let t = inversion_number(&w);
      ans = Some(ans.map_or(t, |ans| cmp::min(ans, t)));
    }
  }

  match ans {
    Some(ans) => println!("{}", ans),
    None => println!("-1"),
  }
}

