const INF: usize = 1_000_000_000_000_000;

fn solve() {
    let n = get!(usize);
    let a = get!([usize]);
    let b = get!([usize]);

    let mut dp = vec![vec![INF; n];1<<n];
    for i in 0..n {
        dp[1<<i][i] = i;
    }
    for mask in 1..1usize<<n {
        let last_pos = mask.count_ones() as usize-1;
        for last in 0..n {
            if dp[mask][last] == INF {
                continue;
            }
            let last_val = if last % 2 == last_pos % 2 {
                a[last]
            } else {
                b[last]
            };
            let mut current = Vec::new();
            for i in 0..n {
                let is_set = (mask>>i)%2 == 1;
                if !is_set {
                    current.push(i);
                }
            }
            for (pos, i) in current.into_iter().enumerate() {
                let new_val = if i % 2 == last_pos % 2 {
                    b[i]
                } else {
                    a[i]
                };
                if new_val >= last_val {
                    dp[mask|1<<i][i] = min!(dp[mask|1<<i][i], dp[mask][last]+pos);
                }
            }
        }
    }
    // debug!(dp);
    let mn = dp[(1<<n)-1].iter().min().unwrap();
    if *mn == INF {
        println!("-1");
    } else {
        println!("{}", mn);
    }
}

