fn solve() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }
    input! {
        n: usize,
        a: [usize; n],
        b: [usize; n],
    }
    const INF: i64 = 1 << 50;
    const W: usize = 51;
    // dp[last value][used]
    let mut mi = INF;
    for bits in 0..1usize << n {
        if bits.count_ones() as usize != n / 2 {
            continue;
        }
        let mut even = vec![];
        let mut odd = vec![];
        for i in 0..n {
            if (bits & 1 << i) != 0 {
                odd.push((if (i + 1) % 2 == 0 { a[i] } else { b[i] }, i));
            } else {
                even.push((if i % 2 == 0 { a[i] } else { b[i] }, i));
            }
        }
        even.sort();
        odd.sort();
        let mut ok = true;
        for i in 0..n - 1 {
            if i % 2 == 0 {
                if even[i / 2].0 > odd[i / 2].0 {
                    ok = false;
                    break;
                }
            } else {
                if odd[i / 2].0 > even[i / 2 + 1].0 {
                    ok = false;
                    break;
                }
            }
        }
        if !ok { continue; }
        let mut ind = vec![0; n];
        for i in 0..n {
            if i % 2 == 0 {
                ind[i] = even[i / 2].1;
            } else {
                ind[i] = odd[i / 2].1;
            }
        }
        let mut c = 0;
        for i in 0..n {
            for j in 0..i {
                if ind[j] > ind[i] {
                    c += 1;
                }
            }
        }
        mi = min(mi, c);
    }
    puts!("{}\n", if mi >= INF { -1 } else { mi });
}

