macro_rules! parse {
    ($it: ident) => {
        $it.next().unwrap().parse().unwrap()
    };
    ($it: ident,2) => {
        (parse!($it), parse!($it))
    };
    ($it: ident,3) => {
        (parse!($it), parse!($it), parse!($it))
    };
    ($it: ident,4) => {
        (parse!($it), parse!($it), parse!($it), parse!($it))
    };
    ($it: ident, $n: expr) => {
        (&mut $it).take($n).map(|e| e.parse().unwrap()).collect();
    };
}
fn binary_search_left<T: Ord>(v: &Vec<T>, x: T) -> usize {
    let mut l: isize = -1;
    let mut r: isize = v.len() as isize;
    while r - l > 1 {
        let m = (r + l) / 2;
        if v[m as usize] < x {
            l = m;
        } else {
            r = m;
        }
    }
    r as usize
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    let n: usize = parse!(it);
    let a: Vec<usize> = parse!(it, n);
    let b: Vec<usize> = parse!(it, n);
    let mut ret = std::usize::MAX;
    'outer: for i in 0..(1 << n) {
        let flags: Vec<bool> = (0..n).map(|j| (i >> j) & 1 == 1).collect();
        let c: Vec<usize> = (0..n).map(|j| if flags[j] { b[j] } else { a[j] }).collect();
        let mut d = c.clone();
        d.sort();
        let mut arg = vec![None; n];
        let mut used = vec![false; n];
        for i in 0..n {
            let l = binary_search_left(&d, c[i]);
            let r = binary_search_left(&d, c[i] + 1);
            for j in l..r {
                if !used[j] && if i < j { j - i } else { i - j } % 2 == flags[i] as usize {
                    arg[i] = Some(j);
                    used[j] = true;
                    break;
                }
            }
            if arg[i] == None {
                continue 'outer;
            }
        }
        let mut p = 0usize;
        for i in 0..n {
            for j in (i + 1)..n {
                p += (arg[i] > arg[j]) as usize;
            }
        }
        ret = std::cmp::min(ret, p)
    }
    println!(
        "{}",
        if ret == std::usize::MAX {
            -1
        } else {
            ret as i64
        }
    );
}

