fn solve() {
	let n = read!(usize);
	let a = read!([usize]);
	let b = read!([usize]);
	let mut ans = INF;
	for i in 0..(1<<n){
		let mut red = vec![true;n];
		let mut sum = 0;
		for j in 0..n {
			if ((i>>j)%2)==1 {
				red[j] = false;
				sum += 1;
			}
		}
		if sum%2!=0 {
			continue;
		}
		let mut v = vec![];
		for j in 0..n {
			if red[j]{
				v.push(a[j]);
			}
			else{
				v.push(b[j]);
			}
		}
		let mut vs = v.clone();
		vs.sort();
		let mut seen = vec![false;n];
		let mut t = vec![0;n];
		for j in 0..n {
			for k in 0..n {
				if red[j] && ((k+j)%2)==0 && !seen[k] && vs[k]==a[j]{
					seen[k] = true;
					t[k] = j;
					break;
				}
				if !red[j] && ((k+j)%2)==1 && !seen[k] && vs[k]==b[j]{
					seen[k] = true;
					t[k] = j;
					break;
				}
			}
		}
		let mut flag = true;
		for j in 0..n {
			if !seen[j] {
				flag = false;
			}
		}
		if !flag {
			continue;
		}
		let mut num = vec![0;n];
		let mut sum = 0;
		for j in 0..n {
			let target = t[j];
			for k in target+1..n {
				sum += num[k];
			}
			num[target] += 1;
		}
		ans = min(ans, sum);
		// for j in 0..n {
