        std::io::stdin().read_line(&mut line).unwrap();
        line.split_whitespace()
            .map(|x| x.parse().unwrap())
            .collect()
    };

    const INF: usize = 1_000_000_000;
    let res = (0..(1 << N))
        .map(|p| {
            let mut a = vec![];
            let mut b = vec![];
            for i in 0..N {
                if (p >> i) & 1 == 1 {
                    a.push((A[i], i));
                } else {
                    b.push((B[i], i));
                }
            }
            a.sort();
            b.sort();
            // println!("a={:?}", a);
            // println!("b={:?}", b);
            let mut X = vec![];
            for i in 0..N {
                X.push(i);
            }
            let mut x = 0;
            let mut cost = 0;
            for i in 0..N {
                // println!("{:?}", X);
                let j = (0..a.len()).find(|&j| a[j].1 % 2 == i % 2).unwrap_or(INF);
                let k = (0..b.len()).find(|&k| b[k].1 % 2 != i % 2).unwrap_or(INF);
                if j < INF && x <= a[j].0 && (k == INF || a[j].0 < b[k].0) {
                    x = a[j].0;
                    let l = (0..N).find(|&l| X[l] == a[j].1).unwrap();
                    // println!("{}", l);
                    cost += l - i;
                    for r in (i..l).rev() {
                        let tmp = X[r + 1];
                        X[r + 1] = X[r];
                        X[r] = tmp;
                    }
                    a.remove(j);
                } else if k < INF && x <= b[k].0 && (j == INF || b[k].0 <= a[j].0) {
                    x = b[k].0;
                    let l = (0..N).find(|&l| X[l] == b[k].1).unwrap();
                    cost += l - i;
                    for r in (i..l).rev() {
                        let tmp = X[r + 1];
                        X[r + 1] = X[r];
                        X[r] = tmp;
                    }
                    b.remove(k);
                } else {
                    cost = INF;
                    break;
                }
            }
            cost
        })
        .min()
        .unwrap();
    let ans = if res == INF { -1 } else { res as i64 };

    println!("{}", ans);
}

