fn dist(i: usize, k: usize) -> usize {
    if i > k {
        i - k
    } else {
        k - i
    }
}

fn main() {
    input! {
        n: usize,
        xs: [usize; n],
        ys: [usize; n],
    }
    let inf = 1usize << 50;
    // dp[i][used][last] = min times
    let mut dp = vec![vec![vec![inf; 64]; 1 << n]; n + 1];
    dp[0][0][0] = 0;
    for i in 0..n {
        for used in 0..1 << n {
            for last in 0..51 {
                let mut count = 0;
                for k in 0..n {
                    if used & (1 << k) != 0 {
                        continue;
                    }
                    // ?
                    let pality = dist(i, k) % 2;
                    let v = if pality == 0 { xs[k] } else { ys[k] };
                    if last <= v {
                        dp[i + 1][used | (1 << k)][v] =
                            min(dp[i + 1][used | (1 << k)][v], dp[i][used][last] + count);
                    }
                    count += 1;
                }
            }
        }
    }
    let mut res = inf;
    for last in 0..51 {
        res = min(res, dp[n][(1 << n) - 1][last]);
    }
    if res == inf {
        println!("-1");
    } else {
        println!("{}", res);
    }
}

