const INF: usize = 100000000;

fn main() {
    input! {
        n: usize,
        a: [i32; n],
        b: [i32; n]
    };

    let mut eo = dvec!(0; n, 2);
    for i in 0..n {
        eo[i][i%2] = a[i];
        eo[i][(i%2)^1] = b[i];
    }


    let mut dp = dvec!(INF; 1<<n, n);
    dp[0][0] = 0;
    for p in 0..1<<n {
        let mut next = 0;
        for i in 0..n {
            if p & (1<<i) >= 1 {
                next ^= 1;
            }
        }

        for last in 0..n {
            let left = ifv!(p == 0, 0, eo[last][next^1]);
            let base = dp[p][last];
            if base == INF {
                continue;
            }

            let mut lower = 0;
            for k in 0..n {
                if p & (1<<k) >= 1 {
                    lower += 1;
                    continue;
                }
                if left <= eo[k][next] {
                    dp[p|(1<<k)][k] = min(dp[p|(1<<k)][k], base+k-lower);
                }
            }
        }
    }

    let mut best = INF;
    for i in 0..n {
        best = min(best, dp[(1<<n)-1][i]);
    }
    if best == INF {
        println!("-1");
    } else {
        println!("{}", best);
    }
}

