}

// -----------------------------------------------
// Solution
// -----------------------------------------------

fn main() {
    let N = read!(usize);
    let A = read![[i64]];
    let B = read![[i64]];

    let mut numbers = vec![Default::default(); N];
    let mut cards = vec![Default::default(); N];
    let mut parity = vec![Default::default(); N];
    let mut min_cost = std::i64::MAX;

    for s in 0..1 << N {
        let flip = |i: usize| (s & (1 << i)) != 0;

        for i in 0..N {
            let c = if flip(i) { B[i] } else { A[i] };
            cards[i] = (c, i);
            numbers[i] = c;
            parity[i] = false;
        }

        numbers.sort();

        let mut l = 0;
        let mut cost = 0;
        let mut ok = true;

        while l < N {
            let i = (l..N).filter(|&i| cards[i].0 == numbers[l]).next().unwrap();

            for j in (l..i).rev() {
                cards.swap(j, j + 1);
                parity[j] = !parity[j];
                parity[j + 1] = !parity[j + 1];
                cost += 1;
            }

            debug_assert_eq!(cards[l].0, numbers[l]);
            if parity[l] != flip(l) || cost > min_cost {
                ok = false;
                break;
            }
            l += 1;
        }

        if ok {
            min_cost = min(min_cost, cost);
        }
    }

    if min_cost == std::i64::MAX {
        println!("-1")
    } else {
        println!("{}", min_cost)
    }
}

