        for j in 0..n - 1 {
            if (i >> j) & 1 == 1 {
                cost += 1;
                let buf = aa[j];
                aa[j] = bb[j + 1];
                bb[j + 1] = buf;
                let buf = bb[j];
                bb[j] = aa[j + 1];
                aa[j + 1] = buf;
            }
        }
