            }
        }

        let mut cost2 = 0;

        for i in 0..aa1.len() {
            for j in i + 1..aa1.len() {
                if aa1[i] > aa1[j] {
                    cost2 += 3;
                }
            }
        }

        for i in 0..aa2.len() {
            for j in i + 1..aa2.len() {
