fn main() {
    input! {
        n: usize,
        aa: [usize; n],
        bb: [usize; n],
    }

    let mut ans = -1;
    // 0b0000 A3, A2, A1, A0
    // 0b0101 A3, B2, A1, B0
    for bit in 0b0 .. 0b1 << n {
        let mut even_pos = vec![];
        let mut odd_pos = vec![];

        // use cards
        for i in 0..n {
            let i_is_even = i % 2 == 0;
            if bit & (0b1 << i) == 0 {
                // use A
                if i_is_even {
                    even_pos.push((aa[i], i));
                } else {
                    odd_pos.push((aa[i], i));
                }
            } else {
                // use B
                if i_is_even {
                    odd_pos.push((bb[i], i));
                } else {
                    even_pos.push((bb[i], i));
                }
            }
        }

        // cannot create
        if even_pos.len() != odd_pos.len() && even_pos.len() != odd_pos.len() + 1 {
            continue;
        }

        even_pos.sort();
        odd_pos.sort();

        let result = {
            let mut v = vec![];
            let mut ei = even_pos.into_iter();
            let mut oi = odd_pos.into_iter();
            loop {
                match (ei.next(), oi.next()) {
                    (Some(e), Some(o)) => {
                        v.push(e);
                        v.push(o);
                    },
                    (Some(e), None) => {
                        v.push(e);
                    },
                    (None, Some(o)) => {
                        v.push(o);
                    },
                    (None, None) => break
                }
            }
            v
        };
        if !sorted(&result) {
            continue;
        }

        let n = bubble_cnt(&result, &|&(_, index)| index) as isize;
        if ans == -1 || ans > n {
            ans = n;
        }
    }

    println!("{}", ans);
}

fn sorted<T>(v: &[T]) -> bool
where
    T: Ord
{
    v.windows(2).all(|w| w[0] <= w[1])
}

fn bubble_cnt<T, F>(v: &Vec<T>, f: &F) -> usize
where
    F: Fn(&T) -> usize
{
    let mut indices = v.iter().map(f).collect::<Vec<_>>();
    let mut cnt = 0;
    let mut last_change = indices.len() - 1;
    while last_change > 1 {
        let mut tmp = 0;
        for i in 0..last_change {
            if indices[i] > indices[i + 1] {
                cnt += 1;
                indices.swap(i, i + 1);
                tmp = i + 1;
            }
        }
        last_change = tmp;
    }
    cnt
}

