    for used in 0..1 << n {
        let used = used as usize;
        let i = used.count_ones() as usize;
        for last in 0..51 {
            let mut count = 0;
            for k in 0..n {
                if used & (1 << k) != 0 {
                    continue;
                }
                // ?
                let pality = dist(i, k) % 2;
                let v = if pality == 0 { xs[k] } else { ys[k] };
                if last <= v {
                    dp[used | (1 << k)][v] = min(dp[used | (1 << k)][v], dp[used][last] + count);
                }
                count += 1;
            }
        }
    }
    let mut res = inf;
    for last in 0..51 {
        res = min(res, dp[(1 << n) - 1][last]);
    }
    if res == inf {
        println!("-1");
    } else {
        println!("{}", res);
    }
}

