macro_rules! parse {
    ($it: ident) => {
        $it.next().unwrap().parse().unwrap()
    };
    ($it: ident,2) => {
        (parse!($it), parse!($it))
    };
    ($it: ident,3) => {
        (parse!($it), parse!($it), parse!($it))
    };
    ($it: ident,4) => {
        (parse!($it), parse!($it), parse!($it), parse!($it))
    };
    ($it: ident, $n: expr) => {
        (&mut $it).take($n).map(|e| e.parse().unwrap()).collect();
    };
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    let n: usize = parse!(it);
    let a: Vec<usize> = parse!(it, n);
    let b: Vec<usize> = parse!(it, n);
    let mut ret = std::usize::MAX;
    'outer: for i in 0..(1 << n) {
        let flags: Vec<bool> = (0..n).map(|j| (i >> j) & 1 == 1).collect();
        let mut c: Vec<usize> = (0..n).map(|j| if flags[j] { b[j] } else { a[j] }).collect();
        let mut arg: Vec<_> = c.iter().enumerate().collect::<Vec<_>>();
        arg.sort_by_key(|&(_, &x)| x);
        let arg: Vec<usize> = arg.iter().map(|&(i, _)| i).collect();
        for i in 0..n {
            let a = flags[arg[i]];
            let b = (if arg[i] > i { arg[i] - i } else { i - arg[i] }) % 2 == 1;
            if a ^ b {
                continue 'outer;
            }
        }
        let mut p = 0usize;
        for i in 0..n {
            for j in (i + 1)..n {
                p += (c[i] > c[j]) as usize;
            }
        }
        ret = std::cmp::min(ret, p)
    }
    println!(
        "{}",
        if ret == std::usize::MAX {
            -1
        } else {
            ret as i64
        }
    );
}

