// 裏の数は偶数
// 3回のコストでi, i + 2 swap
// AaBb と書くとリバース
// 裏表決め打ちしたときにソートできるか、最小値達成できるか
// コストの計算わからん
// 値が小さいのはなんか役に立たないか
// 対角線のswap

fn run() {
    input! {
        n: usize,
        a: [usize1; n],
        b: [usize1; n],
    }
    let inf = std::u16::MAX;
    let mut dp = vec![vec![inf; 1 << n]; 50];
    dp[0][0] = 0;
    for s in 0..50 {
        for i in 0..(1usize << n) {
            if dp[s][i] == inf {
                continue;
            }
            let v = dp[s][i];
            let c = i.count_ones() as usize & 1;
            let mut cost = 0;
            for j in 0..n {
                if (i >> j) & 1 == 1 {
                    continue;
                }
                cost += 1;
                let x = if c ^ (j & 1) == 0 {a[j]} else {b[j]};
                if x < s {
                    continue;
                }
                dp[x][i | (1 << j)] = std::cmp::min(dp[x][i | (1 << j)], v + cost - 1);
            }
        }
    }
    let mut ans = inf;
    for i in 0..n {
        ans = std::cmp::min(ans, dp[i][(1 << n) - 1]);
    }
    if ans == inf {
        println!("-1");
    } else {
        println!("{}", ans);
    }
}

