const INF: usize = 1_000_000_000_000_000;

fn solve() {
    let n = get!(usize);
    let a = get!([usize]);
    let b = get!([usize]);

    let mut dp = vec![vec![INF; n];1<<n];
    for i in 0..n {
        dp[1<<i][i] = i;
    }
    for mask in 1..1usize<<n {
        let last_pos = mask.count_ones() as usize-1;
        for last in 0..n {
            if dp[mask][last] == INF {
                continue;
            }
            let last_val = if last % 2 == last_pos % 2 {
                a[last]
            } else {
                b[last]
            };
            for i in 0..n {
                let is_set = (mask>>i)%2 == 1;
                if is_set {
                    continue;
                }
                let new_val = if i % 2 == last_pos % 2 {
                    b[i]
                } else {
                    a[i]
                };
                if new_val >= last_val {
                    let diff = (last_pos as isize - i as isize + 1).abs() as usize;
                    dp[mask|1<<i][i] = min!(dp[mask|1<<i][i], dp[mask][last]+diff);
                }
            }
        }
    }
    // debug!(dp);
    let mn = dp[(1<<n)-1].iter().min().unwrap();
    if *mn == INF {
        println!("-1");
    } else {
        println!("{}", mn/2);
    }
}

fn main() {
	let mut s = String::new();
	use std::io::Read;
	std::io::stdin().read_to_string(&mut s).unwrap();
	let mut s = s.split_whitespace();
	let n: usize = s.next().unwrap().parse().unwrap();
	let a: Vec<i16> = s.by_ref().take(n).map(|a| a.parse().unwrap()).collect();
	let b: Vec<i16> = s.map(|a| a.parse().unwrap()).collect();
	let mut ans = std::usize::MAX;
	'pat: for pattern in 0..1 << n {
		let mut target: Vec<_> = a.iter().zip(b.iter()).enumerate().map(|(i, (a, b))| if (pattern >> i) & 1 == 0 { (*a, (i, false)) } else { (*b, (i, true)) }).collect();
		target.sort();
		let mut dummy = vec![0; n];
		let mut l = 0;
		while l < target.len() {
			let mut r = l;
			while r < target.len() && target[l].0 == target[r].0 { r += 1; }
			let mut unused: usize = ((1 << r) - 1) ^ ((1 << l) - 1);
			for i in l..r {
				for j in unused.trailing_zeros() as usize..r {
					if (unused >> j) & 1 == 0 { continue; }
					if ((target[i].1 .0 as i8 - j as i8) & 1 == 1) == target[i].1 .1 {
						dummy[target[i].1 .0] = j;
						unused ^= 1 << j;
					}
				}
			}
			if unused != 0 { continue 'pat; }
			l = r;
		}
		let cnt = count(&dummy);
		if cnt < ans { ans = cnt; }
	}
	println!("{}", if ans == std::usize::MAX { -1 } else { ans as i16 });
}

fn count(a: &[usize]) -> usize {
	let mut bit = BIT::new(a.len());
	a.iter().enumerate().fold(0, |r, (i, &a)|{
		bit.add(a, 1);
		r + (i + 1) - bit.sum(a + 1) as usize
	})
}

struct BIT<T> {
	data: Vec<T>
}

impl<T> BIT<T>
where
	T: Clone + Default + std::ops::AddAssign
{
	fn new(n: usize) -> BIT<T> {
		BIT { data: vec![T::default(); n + 1] }
	}
	fn sum(&self, i: usize) -> T {
		let mut r = T::default();
		let mut i = i;
		while i > 0 {
			r += self.data[i].clone();
			i &= i - 1;
		}
		r
	}
	fn add(&mut self, i: usize, value: T) {
		let mut i = i + 1;
		while i < self.data.len() {
			self.data[i] += value.clone();
			i += i & (!i + 1);
		}
	}
}

