#[derive(Eq, PartialEq, Clone, Debug)]
pub struct Rev<T>(pub T);
impl<T: PartialOrd> PartialOrd for Rev<T> {
    fn partial_cmp(&self, other: &Rev<T>) -> Option<Ordering> {
        other.0.partial_cmp(&self.0)
    }
}
impl<T: Ord> Ord for Rev<T> {
    fn cmp(&self, other: &Rev<T>) -> Ordering {
        other.0.cmp(&self.0)
    }
}

fn solve() {
    let n = get!(usize);
    let a = get!([usize]);
    let b = get!([usize]);

    let mut dp = vec![vec![None; n]; 1<<n];
    for i in 0..n {
        dp[1<<i][i] = Some(i);
    }
    for mask in 0..1usize<<n {
        let count = mask.count_ones() as usize;
        for i in 0..n {
            if dp[mask][i].is_none() {
                continue;
            }
            let cost = dp[mask][i].unwrap();
            let val = if count % 2 == i % 2 {
                b[i]
            } else {
                a[i]
            };
            for j in 0..n {
                if mask & (1<<j) > 0 {
                    continue;
                }
                let new_val = if count % 2 == j % 2 {
                    a[j]
                } else {
                    b[j]
                };
                let ncost = cost + (count as isize - j as isize).abs() as usize;
                if val <= new_val {
                    dp[mask|1<<j][j] = if let Some(cost) = dp[mask|1<<j][j] {
                        Some(min!(ncost, cost))
                    } else {
                        Some(ncost)
                    };
                }
            }
        }
    }
    let mut mn = std::usize::MAX;
    for i in 0..n {
        if let Some(cost) = dp[(1<<n)-1][i] {
            mn = min!(mn, cost);
        }
    }
    if mn == std::usize::MAX {
        println!("-1");
    } else {
        println!("{}", mn/2);
    }
}

use std::io::{stdin, Read};

macro_rules! parse {
    ($it: ident) => {
        $it.next().unwrap().parse().unwrap()
    };
    ($it: ident,2) => {
        (parse!($it), parse!($it))
    };
    ($it: ident,3) => {
        (parse!($it), parse!($it), parse!($it))
    };
    ($it: ident,4) => {
        (parse!($it), parse!($it), parse!($it), parse!($it))
    };
    ($it: ident, $n: expr) => {
        (&mut $it).take($n).map(|e| e.parse().unwrap()).collect();
    };
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    let n: usize = parse!(it);
    let a: Vec<usize> = parse!(it, n);
    let b: Vec<usize> = parse!(it, n);
    let mut dp = vec![vec![None; n]; 1 << n];
    let diff = |x, y| if x > y { x - y } else { y - x };
    let v = |i: usize, to: usize| {
        if diff(i, to) % 2 == 1 {
            b[i]
        } else {
            a[i]
        }
    };
    for i in 0..n {
        dp[1 << i][i] = Some(0);
    }
    for i in 1usize..(1 << n) {
        let r = i.count_ones() as usize;
        for j in 0..n {
            if let Some(x) = dp[i][j] {
                for k in 0..n {
                    if (i >> k) & 1 == 1 || j == k || v(j, r - 1) > v(k, r) {
                        continue;
                    }
                    let largerk = (i & (!((1 << k) - 1))).count_ones() as usize;
                    dp[i | (1 << k)][k] = match dp[i | 1 << k][k] {
                        Some(y) => Some(std::cmp::min(y, x + largerk)),
                        None => Some(x + largerk),
                    }
                }
            }
        }
    }
    let mut ret = None;
    for i in 0..n {
        ret = match dp[(1 << n) - 1][i] {
            None => ret,
            Some(x) => match ret {
                None => Some(x),
                Some(ret) => Some(std::cmp::min(x, ret)),
            },
        }
    }
    match ret {
        None => println!("{}", -1),
        Some(x) => println!("{}", x),
    }
}

fn main() {
    let mut s = String::new();
    stdin().read_to_string(&mut s).unwrap();
    solve(&s);
}

