fn solve() {
    let out = stdout();
    let mut out = BufWriter::new(out.lock());
    input!{
        n:usize,
        a:[i64;n],
        b:[i64;n],
    }
    let mut A = vec![0];
    for x in a {
        A.push(x)
    }
    A.sort();
    let mut B = vec![0];
    for x in b {
        B.push(x)
    }
    B.sort();
    let N = n+1;

    let mut dp = dvec![1<<60; 1<<N,N];
    dp[1][0] = 0;

    for mask in 1..(1<<N) {
        let mut cur = vec![];
        let mut new = vec![];
        for i in 0..N {
            if mask & (1<<i) > 0 {
                cur.push(i);
            } else {
                new.push(i);
            }
        }
        // マスクに入ってるやつの長さ
        let m = cur.len();
        for l in cur {
            let L = max(l,m-1) - min(l,m-1);
            let x = if L%2 == 0 {
                A[l]
            } else {
                B[l]
            };
            for r in new.clone() {
                let R = max(r,m) - min(r,m);
                let y = if R%2 == 0 {
                    A[r]
                } else {
                    B[r]
                };
                // 広義単調増加になってる
                if x <= y {
                    let newmask = mask | (1<<r);
                    chmin!(dp[newmask][r], dp[mask][l] + R);
                }
            }
        }
    }

    let mut minv = 1<<60;
    for i in 1..N {
        chmin!(minv, dp[(1<<N)-1][i]);
    }

    if minv == 1<<60 {
        println!("-1");
    } else {
        println!("{}", minv / 2);
    }
}

