fn main() {
    let n = read::<usize>();
    let a = read_vec::<usize>();
    let b = read_vec::<usize>();

    let mut ans = std::i64::MAX;
    'outer: for i in 0..1 << n {
        let mut evens = vec![];
        let mut odds = vec![];
        for j in 0..n {
            let mut oe = j % 2;
            let mut num;
            if i >> j & 1 == 1 {
                oe = 1 - oe;
                num = b[j];
            } else {
                num = a[j];
            }
            if oe == 0 {
                evens.push((num, j));
            } else {
                odds.push((num, j));
            }
        }

        if odds.len() != n / 2 {
            continue 'outer;
        }

        evens.sort();
        odds.sort();
        let mut numbers = vec![];
        for i in 0..n / 2 {
            numbers.push(evens[i].0);
            numbers.push(odds[i].0);
        }
        if n % 2 == 1 {
            numbers.push(evens[n / 2].0);
        }
        for i in 0..n - 1 {
            if numbers[i] > numbers[i + 1] {
                continue 'outer;
            }
        }

        let mut temp = 0;
        for j in 0..evens.len() {
            temp += (evens[j].1 as i64 - 2 * j as i64).abs();
        }
        for j in 0..odds.len() {
            temp += (odds[j].1 as i64 - 2 * j as i64 - 1).abs();
        }
        ans = min(ans, temp);
    }
    if ans == std::i64::MAX {
        println!("-1");
    } else {
        unreachable!();
        // println!("0000");
        //println!("{}", ans / 2);
    }
}

fn read<T: std::str::FromStr>() -> T {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).ok();
    s.trim().parse().ok().unwrap()
}

fn read_vec<T: std::str::FromStr>() -> Vec<T> {
    read::<String>()
        .split_whitespace()
        .map(|e| e.parse().ok().unwrap())
        .collect()
}

