            Parser {
                reader: io::empty(),
                buf: s.as_bytes().to_vec(),
                pos: 0,
            }
        }
    }

    impl<R: BufRead> Parser<R> {
        pub fn new(reader: R) -> Parser<R> {
            Parser {
                reader: reader,
                buf: vec![],
                pos: 0,
            }
        }
        pub fn update_buf(&mut self) {
            self.buf.clear();
            self.pos = 0;
            loop {
                let (len, complete) = {
                    let buf2 = self.reader.fill_buf().unwrap();
                    self.buf.extend_from_slice(buf2);
                    let len = buf2.len();
                    (len, buf2[len - 1] <= 0x20)
                };
                self.reader.consume(len);
                if complete {
                    break;
                }
            }
        }
        pub fn next<T: str::FromStr>(&mut self) -> Result<T, T::Err> {
            loop {
                let mut begin = self.pos;
                while begin < self.buf.len() && (self.buf[begin] <= 0x20) {
                    begin += 1;
                }
                let mut end = begin;
                while end < self.buf.len() && (self.buf[end] > 0x20) {
                    end += 1;
                }
                if begin != self.buf.len() {
                    self.pos = end;
                    return unsafe { str::from_utf8_unchecked(&self.buf[begin..end]) }.parse::<T>();
                } else {
                    self.update_buf();
                }
            }
        }
        pub fn fast_i64(&mut self) -> i64 {
            loop {
                let mut begin = self.pos;
                while begin < self.buf.len() && (self.buf[begin] <= 0x20) {
                    begin += 1;
                }
                if begin == self.buf.len() {
                    self.update_buf();
                    continue;
                }
                let mut res = 0;
                let (is_positive, mut end) = match self.buf[begin] {
                    b'+' => (true, begin + 1),
                    b'-' => (false, begin + 1),
                    _ => (true, begin),
                };
                while end < self.buf.len() && (self.buf[end] > 0x20) {
                    res = res * 10 + (self.buf[end] as i64 - '0' as i64);
                    end += 1;
                }
                if begin != self.buf.len() {
                    self.pos = end;
                    return if is_positive { res } else { -res };
                } else {
                    self.update_buf();
                }
            }
        }
    }
}

use input_mcr::*;
use std::cmp::*;

fn dist(i: usize, k: usize) -> usize {
    if i > k {
        i - k
    } else {
        k - i
    }
}

fn main() {
    input! {
        n: usize,
        xs: [usize; n],
        ys: [usize; n],
    }
    let inf = 1usize << 50;
    // dp[used][last] = min times
    let mut dp = vec![vec![inf; 1 << n]; 64];
    dp[0][0] = 0;
    for used in 0..1 << n {
        let used = used as usize;
        let i = used.count_ones() as usize;
        for last in 0..51 {
            let mut count = 0;
            for k in 0..n {
                if used & (1 << k) != 0 {
                    continue;
                }
                // ?
                let pality = dist(i, k) % 2;
                let v = if pality == 0 { xs[k] } else { ys[k] };
                if last <= v {
                    dp[v][used | (1 << k)] = min(dp[v][used | (1 << k)], dp[last][used] + count);
                }
                count += 1;
            }
        }
    }
    let mut res = inf;
    for last in 0..51 {
        res = min(res, dp[last][(1 << n) - 1]);
    }
    if res == inf {
        println!("-1");
    } else {
        println!("{}", res);
    }
}

use std::cmp::*;
use std::io::*;

fn main() {
    let mut s: String = String::new();
    std::io::stdin().read_to_string(&mut s).ok();
    let mut itr = s.trim().split_whitespace();
    let n: usize = itr.next().unwrap().parse().unwrap();
    let a: Vec<usize> = (0..n)
        .map(|_| itr.next().unwrap().parse().unwrap())
        .collect();
    let b: Vec<usize> = (0..n)
        .map(|_| itr.next().unwrap().parse().unwrap())
        .collect();

    // a ... 偶数回スワップして表
    // b ... 奇数回スワップして表
    const INF: i32 = 1 << 30;
    let mut ans = INF;
    for bit in 0..1 << n {
        let mut tmp = Vec::new();
        for i in 0..n {
            if bit >> i & 1 == 0 {
                tmp.push((a[i], i, 0));
            } else {
                tmp.push((b[i], i, 1));
            }
        }
        tmp.sort();

        let mut ok = true;
        let mut cnt = 0;
        for i in 0..n {
            let v = tmp[i].0;
            let j = tmp[i].1;
            let k = tmp[i].2;
            let diff = (i as i32 - j as i32).abs();
            if diff % 2 != k {
                ok = false;
                for l in i + 1..n {
                    if tmp[l].0 == v
                        && tmp[l].2 != k
                        && (tmp[l].1 as i32 - i as i32).abs() % 2 == tmp[l].2
                    {
                        tmp.swap(i, l);
                        cnt += 1;
                        ok = true;
                        break;
                    }
                }
                if !ok {
                    break;
                }
            }
            cnt += diff;
        }
        if ok {
            ans = min(ans, cnt / 2);
        }
    }
    if ans == INF {
        println!("-1")
    } else {
        println!("{}", ans);
    }
}

