fn main() {
    read!(n = usize);
    read!(aa = Vec<u8>);
    read!(bs = Vec<u8>);

    let mut dp = vec![vec![None; n]; 1<<n];
    for set in 1usize..1<<n {
        if set.count_ones() == 1 {
            let i = set.trailing_zeros() as usize;
            dp[set][i] = Some(0);
            continue;
        }

        for i in 0..n {
            if set & (1<<i) == 0 {
                continue;
            }
            let subset = set ^ 1<<i;
            let di = (subset.count_ones() as usize).abs_diff(i);
            let xi = if di % 2 == 0 { aa[i] } else { bs[i] };
            let inv_mask = ((1<<n) - 1) ^ dbg!((1 << i+1) - 1);
            dbg!((set, i, subset, inv_mask));
            let inv_count = (subset & inv_mask).count_ones() as usize;
            dbg!((set, i, subset, inv_mask));
            dp[set][i] = (0..n).flat_map(|j| {
                dp[subset][j].and_then(|prev| {
                    let dj = (subset.count_ones() as usize - 1).abs_diff(j);
                    let xj = if dj % 2 == 0 { aa[j] } else { bs[j] };
                    (xj <= xi).then(prev + inv_count)
                })
            }).min();
            dbg!((set, i, dp[set][i]));
        }
    }

    let ans = dp[(1<<n) - 1].iter().cloned().flatten().min();
    println!("{}", ans.map(|x| x.to_string()).unwrap_or("-1".to_string()));
}

