use std::cmp::*;
use std::io::*;

fn main() {
    let mut s: String = String::new();
    std::io::stdin().read_to_string(&mut s).ok();
    let mut itr = s.trim().split_whitespace();
    let n: usize = itr.next().unwrap().parse().unwrap();
    let a: Vec<usize> = (0..n)
        .map(|_| itr.next().unwrap().parse().unwrap())
        .collect();
    let b: Vec<usize> = (0..n)
        .map(|_| itr.next().unwrap().parse().unwrap())
        .collect();

    // a ... 偶数回スワップして表
    // b ... 奇数回スワップして表
    const INF: i32 = 1 << 30;
    let mut ans = INF;
    for bit in 0..1 << n {
        let mut tmp = Vec::new();
        for i in 0..n {
            if bit >> i & 1 == 0 {
                tmp.push((a[i], i, 0));
            } else {
                tmp.push((b[i], i, 1));
            }
        }
        tmp.sort();

        let mut ok = true;
        let mut cnt = 0;
        for i in 0..n {
            let v = tmp[i].0;
            let j = tmp[i].1;
            let k = tmp[i].2;
            let diff = (i as i32 - j as i32).abs();
            if diff % 2 != k {
                ok = false;
            }
            cnt += diff;
        }
        if ok {
            ans = min(ans, cnt / 2);
        }
    }
    if ans == INF {
        println!("-1")
    } else {
        println!("{}", ans);
    }
}

