macro_rules! order_by {
    ($($x:tt)*) => {
        |l, r| {
            order_by_inner!(l, r, $($x)*)
        }
    }
}
macro_rules! order_by_inner {
    () => {};
    ($l:ident) => {std::cmp::Ordering::Equal};
    ($l:ident , ) => {std::cmp::Ordering::Equal};
    ($l:ident , $r:ident) => {std::cmp::Ordering::Equal};
    ($l:ident , $r:ident , ) => {std::cmp::Ordering::Equal};

    // last
    ($l:ident , $r:ident , $x:tt asc) => {
        $l.$x.cmp(&$r.$x)
    };
    ($l:ident , $r:ident , $x:tt desc) => {
        $l.$x.cmp(&$r.$x).reverse()
    };
    ($l:ident , $r:ident , $x:tt) => {
        order_by_inner!($l, $r, $x asc)
    };

    // mid
    ($l:ident , $r:ident , $x:tt asc , $($p:tt)+) => {
        match $l.$x.cmp(&$r.$x) {
            std::cmp::Ordering::Equal => {
                order_by_inner!($l, $r, $($p)+)
            },
            other => other
        }
    };
    ($l:ident , $r:ident , $x:tt desc , $($p:tt)+) => {
        match $l.$x.cmp(&$r.$x).reverse() {
            std::cmp::Ordering::Equal => {
                order_by_inner!($l, $r, $($p)+)
            },
            other => other
        }
    };
    ($l:ident , $r:ident , $x:tt , $($p:tt)+) => {
        order_by_inner!($l, $r, $x asc, $($p)+)
    };
}

fn main() {
    input! {
        n: usize,
        aa: [usize; n],
        bb: [usize; n],
    }
    // n <= 18

    let mut ll = aa.into_iter().enumerate().map(|(i, v)| (i + 1, 0 as usize, v)).collect::<Vec<_>>();
    ll.append(&mut {
        bb.into_iter().enumerate().map(|(i, v)| (i + 1, 1 as usize, v)).collect::<Vec<_>>()
    });

    let ans = get(&ll);
    if ans.len() > 0 {
        let k = ans.into_iter().map(|ans_i| {
            let mut indices = ans_i.iter().map(|a| a.0).collect::<Vec<_>>();
            let mut cnt = 0;
            let mut last_change = indices.len() - 1;
            while last_change > 1 {
                let mut tmp = 0;
                for i in 0..last_change {
                    if indices[i] > indices[i + 1] {
                        cnt += 1;
                        indices.swap(i, i + 1);
                        tmp = i + 1;
                    }
                }
                last_change = tmp;
            }
            cnt
        }).min().unwrap();
        println!("{}", k);
    } else {
        println!("-1");
    }
}

fn get(v: &Vec<(usize, usize, usize)>) -> Vec<Vec<(usize, usize, usize)>> {
    let mut v = v.clone();
    v.sort_by(order_by!(2, 0, 1));
    // println!("{:?}", v);
    let mut r = vec![(0,0, 0)];
    let mut result = vec![];
    let mut used = vec![];
    get_i(&v, &mut r, &mut used, 0, &mut result);
    result
}

fn get_i(v: &Vec<(usize, usize, usize)>, result: &mut Vec<(usize, usize, usize)>, used: &mut Vec<usize>, i: usize, final_result: &mut Vec<Vec<(usize, usize, usize)>>) {
    // println!("then get_i[{}], result: {:?}, used: {:?}", i, result, used);
    if i >= v.len() / 2 {
        if result.iter().filter(|a| a.1 == 1).count() % 2 == 0 {
            final_result.push(result.clone());
        }
        return;
    }
    let last = result[result.len() - 1].2;
    for &(index, ab, value) in v {
        if used.contains(&index) {
            // println!("  value: ({}, {}, {})", index, ab, value);
            // println!("        contains");
            continue;
        }
        if value < last {
            // println!("  value: ({}, {}, {})", index, ab, value);
            // println!("        small");
            continue;
        }
        if (i % 2 == 0 && odd(index, ab)) || (i % 2 != 0 && !odd(index, ab))  {
            // println!("  value: ({}, {}, {})", index, ab, value);
            // println!("        use");
            result.push((index, ab, value));
            used.push(index);
            get_i(v, result, used, i + 1, final_result);
            used.pop();
            result.pop();
        }
    }
}


fn odd(index: usize, ab: usize) -> bool {
    match index % 2 == 0 {
        true => ab == 1,
        false => ab == 0
    }
}

