fn get(v: &Vec<(usize, usize, usize)>) -> Option<Vec<(usize, usize, usize)>> {
    let mut v = v.clone();
    v.sort_by(order_by!(2, 0, 1));
    // println!("{:?}", v);
    let mut result = vec![(0,0, 0)];
    let mut used = vec![];
    get_i(&v, &mut result, &mut used, 0)
}

fn get_i(v: &Vec<(usize, usize, usize)>, result: &mut Vec<(usize, usize, usize)>, used: &mut Vec<usize>, i: usize) -> Option<Vec<(usize, usize, usize)>> {
    // println!("then get_i[{}], result: {:?}, used: {:?}", i, result, used);
    if i >= v.len() / 2 {
        return if result.iter().filter(|a| a.1 == 1).count() % 2 == 0 {
            Some(result.clone())
        } else {
            None
        }
    }
    let last = result[result.len() - 1].2;
    for &(index, ab, value) in v {
        if used.contains(&index) {
            // println!("  value: ({}, {}, {})", index, ab, value);
            // println!("        contains");
            continue;
        }
        if value < last {
            // println!("  value: ({}, {}, {})", index, ab, value);
            // println!("        small");
            continue;
        }
        if (i % 2 == 0 && odd(index, ab)) || (i % 2 != 0 && !odd(index, ab))  {
            // println!("  value: ({}, {}, {})", index, ab, value);
            // println!("        use");
            result.push((index, ab, value));
            used.push(index);
            if let Some(r) = get_i(v, result, used, i + 1) {
                return Some(r);
            } else {
                result.pop();
                used.pop();
            }
        }

    }
    None
}


fn odd(index: usize, ab: usize) -> bool {
    match index % 2 == 0 {
        true => ab == 1,
        false => ab == 0
    }
}

