    }

    let mut ans = -1;

    use std::io::Write;

    for bp in 0..1 << n {
        let mut e = vec![];
        let mut o = vec![];

        for i in 0..n {
            if bp & (1 << i) != 0 {
                if (i + 1) % 2 == 0 {
                    e.push((b[i], i));
                } else {
                    o.push((b[i], i));
                }
            } else {
                if i % 2 == 0 {
                    e.push((a[i], i));
                } else {
                    o.push((a[i], i));
                }
            }
        }

        let ok = if n % 2 == 0 { e.len() == o.len() } else { e.len() == o.len() + 1 };
        if !ok {
            continue;
        }

        e.sort();
        o.sort();

        let mut ok = true;

        for i in 0..n-1 {
            ok &= if i % 2 == 0 {
                e[i/2].0 <= o[i/2].0
            } else {
                o[i/2].0 <= e[i/2+1].0
            };

            if !ok {
                break;
            }
        }

        if !ok {
            continue;
        }

        let mut sum = 0;

        for i in 0..n {
            if i % 2 == 0 {
                sum += (e[i/2].1 as i64 - i as i64).abs();
            } else {
