// n^m
struct PowerPermutation { n: usize, m: usize, ar: Vec<usize> }
impl PowerPermutation {
    fn new(n: usize, m: usize) -> PowerPermutation {
        let ar = vec![0; m];
        PowerPermutation { n: n, m: m, ar: ar }
    }
}
impl Iterator for PowerPermutation {
    type Item = Vec<usize>;
    fn next(&mut self) -> Option<Vec<usize>> {
        if self.ar[self.m-1] >= self.n { return None }
        let r = self.ar.clone();
        self.ar[0] += 1;
        for i in 0..self.m-1 {
            if self.ar[i] == self.n {
                self.ar[i] = 0;
                self.ar[i + 1] += 1;
            } else {
                break;
            }
        }
        return Some(r);
    }
}

fn main() {
    let mut sc = Scanner::new();
    let n: usize = sc.cin();
    let xs: Vec<usize> = sc.vec(n);
    let ys: Vec<usize> = sc.vec(n);

    let mut ans = n + 1;
    for p in PowerPermutation::new(2, n - 1) {
        let mut xs = xs.clone();
        let mut ys = ys.clone();
        let mut flip = 0;
        for i in 0..n-1 {
            if p[i] == 1 {
                flip += 1;
                let tmp = xs[i];
                let tmp2 = ys[i];
                xs[i] = ys[i+1];
                ys[i] = xs[i+1];
                xs[i+1] = tmp2;
                ys[i+1] = tmp;
            }
        }
        let mut ok = true;
        for i in 0..n-1 {
            if xs[i] > xs[i+1] {
                ok = false;
            }
        }
        if (ok) {
            ans = min!(ans, flip);
        }
    }

    if ans == n + 1 {
        put!(-1);
    } else {
        put!(ans);
    }


}

