    for k in 0..2_usize.pow(n as u32 - 1) {
        for i in 0..2_usize.pow(n as u32 - 1) {
            let mut aa = a.clone();
            let mut bb = b.clone();
            let mut cost = 0;
            for j in 0..n {
                if (i >> j) & 1 == 1 {
                    cost += 1;
                    let buf = aa[j];
                    aa[j] = bb[j + 1];
                    bb[j + 1] = buf;
                    let buf = bb[j];
                    bb[j] = aa[j + 1];
                    aa[j + 1] = buf;
                }
            }
            for j in 0..n {
                if (k >> j) & 1 == 1 {
                    cost += 1;
                    let buf = aa[j];
                    aa[j] = bb[j + 1];
                    bb[j + 1] = buf;
                    let buf = bb[j];
                    bb[j] = aa[j + 1];
                    aa[j + 1] = buf;
                }
            }
            let mut aa1 = vec![];
            let mut aa2 = vec![];

            for i in 0..n {
                if i % 2 == 0 {
                    aa1.push(aa[i]);
                } else {
                    aa2.push(aa[i]);
                }
            }

            let mut cost2 = 0;

