                        cost2 += 3;
                    }
                }
            }

            for i in 0..aa2.len() {
                for j in i + 1..aa2.len() {
                    if aa2[i] > aa2[j] {
                        cost2 += 3;
                    }
                }
            }

            aa1.sort();
            aa2.sort();

            let mut ax = vec![];

            for i in 0..aa1.len() {
                ax.push(aa1[i]);
                if aa2.len() > i {
                    ax.push(aa2[i]);
                }
