    use std::io;
    use std::io::BufRead;
    use std::str;

    // ref: tatsuya6502 <https://qiita.com/tatsuya6502/items/cd448486f7ef7b5b8c7e>
    // ref: wariuni <https://qiita.com/tatsuya6502/items/cd448486f7ef7b5b8c7e#comment-7040a5ae96305e884eb9>
    // diff: using std::io::BufRead::fill_buf()
    pub struct Parser<R> {
        pub reader: R,
        buf: Vec<u8>,
        pos: usize,
    }

    impl Parser<io::Empty> {
        pub fn from_str(s: &str) -> Parser<io::Empty> {
            Parser {
                reader: io::empty(),
                buf: s.as_bytes().to_vec(),
                pos: 0,
            }
        }
    }

    impl<R: BufRead> Parser<R> {
        pub fn new(reader: R) -> Parser<R> {
            Parser {
                reader: reader,
                buf: vec![],
                pos: 0,
            }
        }
        pub fn update_buf(&mut self) {
            self.buf.clear();
            self.pos = 0;
            loop {
                let (len, complete) = {
                    let buf2 = self.reader.fill_buf().unwrap();
                    self.buf.extend_from_slice(buf2);
                    let len = buf2.len();
                    (len, buf2[len - 1] <= 0x20)
                };
                self.reader.consume(len);
                if complete {
                    break;
                }
            }
        }
        pub fn next<T: str::FromStr>(&mut self) -> Result<T, T::Err> {
            loop {
                let mut begin = self.pos;
                while begin < self.buf.len() && (self.buf[begin] <= 0x20) {
                    begin += 1;
                }
                let mut end = begin;
                while end < self.buf.len() && (self.buf[end] > 0x20) {
                    end += 1;
                }
                if begin != self.buf.len() {
                    self.pos = end;
                    return unsafe { str::from_utf8_unchecked(&self.buf[begin..end]) }.parse::<T>();
                } else {
                    self.update_buf();
                }
            }
        }
        pub fn fast_i64(&mut self) -> i64 {
            loop {
                let mut begin = self.pos;
                while begin < self.buf.len() && (self.buf[begin] <= 0x20) {
                    begin += 1;
                }
                if begin == self.buf.len() {
                    self.update_buf();
                    continue;
                }
                let mut res = 0;
                let (is_positive, mut end) = match self.buf[begin] {
                    b'+' => (true, begin + 1),
                    b'-' => (false, begin + 1),
                    _ => (true, begin),
                };
                while end < self.buf.len() && (self.buf[end] > 0x20) {
                    res = res * 10 + (self.buf[end] as i64 - '0' as i64);
                    end += 1;
                }
                if begin != self.buf.len() {
                    self.pos = end;
                    return if is_positive { res } else { -res };
                } else {
                    self.update_buf();
                }
            }
        }
    }
}

use input_mcr::*;
use std::cmp::*;

fn dist(i: usize, k: usize) -> usize {
    if i > k {
        i - k
    } else {
        k - i
    }
}

fn main() {
    input! {
        n: usize,
        xs: [usize; n],
        ys: [usize; n],
    }
    let inf = 1usize << 50;
    // dp[i][used][last] = min times
    let mut dp = vec![vec![vec![inf; 64]; 1 << n]; n + 1];
    dp[0][0][0] = 0;
    for i in 0..n {
        for used in 0..1 << n {
            let mut best = inf;
            for last in 0..51 {
                if dp[i][used][last] >= best {
                    continue;
                }
                best = dp[i][used][last];
                let mut count = 0;
                for k in 0..n {
                    if used & (1 << k) != 0 {
                        continue;
                    }
                    // ?
                    let pality = dist(i, k) % 2;
                    let v = if pality == 0 { xs[k] } else { ys[k] };
                    if last <= v {
                        dp[i + 1][used | (1 << k)][v] =
                            min(dp[i + 1][used | (1 << k)][v], dp[i][used][last] + count);
                    }
                    count += 1;
                }
            }
        }
    }
    let mut res = inf;
    for last in 0..51 {
        res = min(res, dp[n][(1 << n) - 1][last]);
    }
    if res == inf {
        println!("-1");
    } else {
        println!("{}", res);
    }
}

