fn main() {
    let n = read::<usize>();
    let a = read_vec::<usize>();
    let b = read_vec::<usize>();

    let mut ans = std::i64::MAX;
    'outer: for i in 0..1 << n {
        if (i as u64).count_ones() % 2 == 1 {
            continue;
        }
        let mut array = vec![];
        let mut max_dict = HashMap::new();
        for j in 0..n {
            if (i >> j) & 1 == 1 {
                array.push((b[j], j));
                *max_dict.entry((b[j], 1)).or_insert(0) += 1;
            } else {
                array.push((a[j], j));
                *max_dict.entry((a[j], 0)).or_insert(0) += 1;
            }
        }
        array.sort();
        let mut temp = 0;
        for j in 0..n {
            let diff = (array[j].1 as i64 - j as i64).abs();
            if !max_dict.contains_key(&(array[j].0, diff % 2))
                || max_dict[&(array[j].0, diff % 2)] == 0
            {
                continue 'outer;
            }

            *max_dict.get_mut(&(array[j].0, diff % 2)).unwrap() -= 1;
            temp += diff;
        }
        ans = min(temp, ans);
    }
    if ans == std::i64::MAX {
        println!("-1");
    } else {
        println!("{}", ans / 2);
    }
}

