fn main() {
    input! {
        n: usize,
        a: [usize; n],
        b: [usize; n],
    }

    let mut dp = vec![vec![1 << 20; 51]; 1 << n];
    dp[0][0] = 0;

    for i in 0..1 << n {
        let bits = (i as u32).count_ones();
        let mut cand = vec![];
        let mut now = bits;
        for j in 0..n {
            if (i >> j) & 1 == 0 {
                cand.push((j, now));
                now += 1;
            }
        }
        for j in 0..51 {
            if dp[i][j] == 1 << 20 {
                continue;
            }
            for &(ini, now) in &cand {
                let next = i | (1 << ini);
                let mv = (now as isize - bits as isize).abs() as usize;
                let flip = (ini as isize - bits as isize).abs() as usize;
                let nextv = dp[i][j] + mv as usize;
                // println!("{} {} {} {} {}", i, j, ini, next, nextv);
                if flip & 1 == 1 && j <= b[ini] {
                    dp[next][b[ini]] = min(dp[next][b[ini]], nextv);
                } else if flip & 1 == 0 && j <= a[ini] {
                    dp[next][a[ini]] = min(dp[next][a[ini]], nextv);
                }
            }
        }
    }
    let a = *dp[(1 << n) - 1].iter().min().unwrap();
    if a == 1 << 20 {
        println!("{}", -1);
    } else {
        println!("{}", a);
    }
}

