fn check(v: &Vec<usize>, n: usize) -> bool {
  for i in 1..n {
    if v[i-1] > v[i] {
       return false
    }
  }
  return true
}

fn swap1(v: &mut Vec<usize>, w: &mut Vec<usize>, i: usize) {
  let tmp = v[i];
  v[i] = w[i];
  w[i] = tmp;
} 

fn swap2(v: &mut Vec<usize> ,i: usize) {
  let tmp = v[i];
  v[i] = v[i+1];
  v[i+1] = tmp;
}

