    }
    let inf = usize::max_value() >> 1;
    let mut dp = vec![vec![inf; 51]; 1 << n];
    dp[(1 << n) - 1][0] = 0;
    let mut q = VecDeque::new();
    q.push_back((0, (1 << n) - 1));
    let mut set = HashSet::new();
    while let Some((next, s)) = q.pop_front() {
        if !set.insert(s) {
            continue;
        }
        for i in 0..50 {
            dp[s][i + 1] = min(dp[s][i], dp[s][i + 1]);
        }
        let mut c = 0;
        for i in 0..n {
            let bit = 1 << i;
            if s & bit == 0 {
                continue;
            }
            let y = if (i + next) % 2 == 0 {a[i]} else {b[i]};
            dp[s ^ bit][y] = min(dp[s ^ bit][y], dp[s][y] + c);
            q.push_back((next + 1, s ^ bit));
            c += 1;
        }
    }
    let ans = dp[0].iter().cloned().min().unwrap();
    if ans == inf {
        println!("-1");
    } else {
        println!("{}", ans);
    }
