fn main() {
    let N: usize = {
        let mut line: String = String::new();
        std::io::stdin().read_line(&mut line).unwrap();
        line.trim().parse().unwrap()
    };
    let A: Vec<usize> = {
        let mut line: String = String::new();
        std::io::stdin().read_line(&mut line).unwrap();
        line.split_whitespace()
            .map(|x| x.parse().unwrap())
            .collect()
    };
    let B: Vec<usize> = {
        let mut line: String = String::new();
        std::io::stdin().read_line(&mut line).unwrap();
        line.split_whitespace()
            .map(|x| x.parse().unwrap())
            .collect()
    };

    const INF: usize = 1_000_000_000;
    let res = (0..(1 << N))
        .map(|p| {
            let mut X = vec![];
            for i in 0..N {
                X.push((i, 1));
            }
            let mut Y = vec![];
            for i in 0..N {
                if (p >> i) & 1 == 1 {
                    Y.push(A[i]);
                } else {
                    Y.push(B[i]);
                }
            }
            let mut cost = 0;
            // println!("p={}", p);
            for i in 0..N {
                // println!("{:?}", X);
                // println!("{:?}", Y);
                let l = (i..N)
                    .find(|&l| ((l - i) + X[l].1) % 2 == (p >> X[l].0) & 1)
                    .unwrap_or(INF);
                if l == INF {
                    cost = INF;
                    break;
                }
                let mut k = l;
                for j in l..N {
                    if Y[j] < Y[k] && ((j - i) + X[j].1) % 2 == (p >> X[j].0) & 1 {
                        k = j;
                    }
                }
                // println!("l={}, k={}", l, k);
                for r in (i..k).rev() {
                    let tmp = X[r + 1];
                    X[r + 1] = (X[r].0, 1 - X[r].1);
                    X[r] = (tmp.0, 1 - tmp.1);
                    let tmp2 = Y[r + 1];
                    Y[r + 1] = Y[r];
                    Y[r] = tmp2;
                    cost += 1;
                }
            }
            if (1..N).any(|i| Y[i - 1] > Y[i]) {
                cost = INF;
            }
            // println!("{}", cost);
            cost
        })
        .min()
        .unwrap();
    let ans = if res >= INF { -1 } else { res as i64 };

    println!("{}", ans);
}

