// example: Bit::new(n, |x, y| *x += *y, 0)
struct Bit<T, F> {
  n: usize,
  dat: Vec<T>,
  op: F,
  unit: T,
}

impl<T: Clone, F: Fn(&mut T, &T)> Bit<T, F> {
  #[allow(dead_code)]
  fn new(n: usize, op: F, unit: T) -> Self {
      Bit {
          n: n,
          dat: vec![unit.clone(); n + 1],
          op: op,
          unit: unit,
      }
  }
  #[allow(dead_code)]
  fn from_vec(mut v: Vec<T>, op: F, unit: T) -> Self {
      let n = v.len();
      let mut dat = vec![unit.clone()];
      dat.append(&mut v);
      for i in 1..n {
          let j = i as i32;
          let b = (j & -j) as usize;
          let x = dat[i].clone();
          op(&mut dat[i + b], &x);
      }
      Bit {
          n: n,
          dat: dat,
          op: op,
          unit: unit,
      }
  }
  fn operate(&mut self, k: usize, a: &T) {
      let mut k = k;
      while k <= self.n {
          (self.op)(&mut self.dat[k], &a);
          let l = k as i32;
          k += (l & -l) as usize;
      }
  }
  fn accum(&self, k: usize) -> T {
      let mut k = k;
      let mut sum = self.unit.clone();
      while k > 0 {
          (self.op)(&mut sum, &self.dat[k]);
          let l = k as i32;
          k -= (l & -l) as usize;
      }
      sum
  }
}

const INF: i64 = 1 << 60;

fn main() {
  let out = std::io::stdout();
  let mut out = std::io::BufWriter::new(out.lock());
  macro_rules! puts {
    ($($format:tt)*) => (write!(out,$($format)*).unwrap());
  }
  input! {
    n: usize,
    a: [i32; n],
    b: [i32; n],
  }
  let mut ans = INF;
  for pat in 0 .. (1 << n) {
    let mut flip = [0, 0];
    for i in 0 .. n {
      if (pat >> i) & 1 != 0 {
        flip[i % 2] += 1;
      }
    }
    if flip[0] != flip[1] {
      continue;
    }
    let mut nums = vec![vec![]; 2];
    for i in 0 .. n {
      let flipped = (pat >> i) & 1 != 0;
      let v = if flipped {
        b[i]
      } else {
        a[i]
      };
      if flipped {
        nums[(i + 1) % 2].push((v, i));
      } else {
        nums[i % 2].push((v, i));
      }
    }
    nums[0].sort();
    nums[1].sort();
    let mut sorted = true;
    for i in 0 .. nums[1].len() {
      if nums[0][i].0 > nums[1][i].0 {
        sorted = false;
        break;
      }
    }
    for i in 1 .. nums[0].len() {
      if nums[1][i-1].0 > nums[0][i].0 {
        sorted = false;
        break;
      }
    }
    if ! sorted {
      continue;
    }
    let mut bit = Bit::new(n, |x, y| *x += *y, 0);
    let mut swap = 0;
    for i in (0 .. n).rev() {
      let index = nums[i % 2][i / 2].1 + 1;
      swap += bit.accum(index);
      bit.operate(index, &1);
    }
    ans = cmp::min(ans, swap);
  }

  puts!("{}\n", if ans == INF { -1 } else { ans });
}

use std::cmp;

const INF: usize = 1 << 50;
const V: usize = 51;

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());
    let n: usize = sc.read();
    let a: Vec<usize> = sc.vec(n);
    let b: Vec<usize> = sc.vec(n);
    let mut dp = vec![vec![INF; V]; 1 << n];
    dp[0][0] = 0;

    let mut masks = (0..(1 << n))
        .map(|mask: usize| (mask.count_ones() as usize, mask))
        .collect::<Vec<_>>();
    masks.sort();

    for (pos, cur_mask) in masks.into_iter() {
        for next_add in 0..n {
            if cur_mask & (1 << next_add) != 0 {
                continue;
            }
            let next_mask = cur_mask | (1 << next_add);

            let mut back_used = 0;
            for i in (next_add + 1)..n {
                if cur_mask & (1 << i) != 0 {
                    back_used += 1;
                }
            }
            let cur_pos = next_add + back_used;
            let distance = cur_pos - pos;

            let d = if pos > next_add {
                pos - next_add
            } else {
                next_add - pos
            };
            let card = if d % 2 == 0 { a[next_add] } else { b[next_add] };

            for cur_v in 0..V {
                let c = dp[cur_mask][cur_v];
                if c == INF {
                    continue;
                }
                if card >= cur_v {
                    dp[next_mask][card] = cmp::min(dp[next_mask][card], c + distance);
                }
            }
        }
    }
    let mut ans = INF;
    for i in 0..V {
        ans = cmp::min(ans, dp[(1 << n) - 1][i]);
    }

    if ans >= INF {
        println!("-1");
    } else {
        println!("{}", ans);
    }
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> IO<R, W> {
        IO(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: std::ops::Deref<Target = str>>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

