pub trait SetMinMax {
	fn setmin(&mut self, v: Self) -> bool;
	fn setmax(&mut self, v: Self) -> bool;
}
impl<T> SetMinMax for T where T: PartialOrd {
	fn setmin(&mut self, v: T) -> bool {
		*self > v && { *self = v; true }
	}
	fn setmax(&mut self, v: T) -> bool {
		*self < v && { *self = v; true }
	}
}

fn solve() {
	let n = read!(usize);
	let a = read!([usize]);
	let b = read!([usize]);
	let mut ans = INF;
	for i in 0..(1<<n){
		let mut red = vec![true;n];
		let mut sum = 0;
		for j in 0..n {
			if ((i>>j)%2)==1 {
				red[j] = false;
				sum += 1;
			}
		}
		if sum%2!=0 {
			continue;
		}
		let mut v = vec![];
		for j in 0..n {
			if red[j]{
				v.push(a[j]);
			}
			else{
				v.push(b[j]);
			}
		}
		let mut vs = v.clone();
		vs.sort();
		let mut seen = vec![false;n];
		let mut t = vec![0;n];
		for j in 0..n {
			for k in 0..n {
				if k<=j{
					let lidx = j - k;
					if red[j] && (k%2)==0 && !seen[lidx] && vs[lidx]==a[j]{
						seen[lidx] = true;
						t[lidx] = j;
						break;
					}
					if !red[j] && (k%2)==1 && !seen[lidx] && vs[lidx]==b[j]{
						seen[lidx] = true;
						t[lidx] = j;
						break;
					}
				}
				let ridx = j + k;
				if ridx<n && red[j] && (k%2)==0 && !seen[ridx] && vs[ridx]==a[j]{
					seen[ridx] = true;
					t[ridx] = j;
					break;
				}
				if ridx<n && !red[j] && (k%2)==1 && !seen[ridx] && vs[ridx]==b[j]{
					seen[ridx] = true;
					t[ridx] = j;
					break;
				}

			}
		}
		let mut flag = true;
		for j in 0..n {
			if !seen[j] {
				flag = false;
			}
		}
		if !flag {
			continue;
		}
		let mut num = vec![0;n];
		let mut sum = 0;
		for j in 0..n {
			let target = t[j];
			for k in target+1..n {
				sum += num[k];
			}
			num[target] += 1;
		}
		ans = min(ans, sum);
		// for j in 0..n {
		// 	print!("{} ", t[j]);
		// }
		// println!();
		// println!("{} {}", i, sum);
	}
	println!("{}", if ans==INF {-1} else {ans});
}

fn run() {
    solve();
}

