fn run() {
    let n: usize = scan();
    let a: Vec<i32> = scan_iter().take(n).collect();
    let b: Vec<i32> = scan_iter().take(n).collect();
    let mut ans = i32::max_value();
    for s in 0..(1 << n) {
        let mut v1 = Vec::new();
        let mut v2 = Vec::new();
        for i in 0..n {
            let f1 = i % 2 == 0;
            let f2 = (s >> i & 1) == 0;
            let val = if f2 { a[i] } else { b[i] };
            if f1 == f2 {
                v1.push((val, i));
            } else {
                v2.push((val, i));
            }
        }
        if !(v1.len() >= v2.len() && v1.len() <= v2.len() + 1) {
            continue;
        }
        v1.sort();
        v2.sort();
        let mut v = Vec::new();
        for i in 0..v1.len() {
            v.push(v1[i]);
            if i < v2.len() {
                v.push(v2[i]);
            }
        }
        let mut is_sorted = true;
        for i in 0..v.len() {
            if i + 1 < v.len() && v[i].0 > v[i + 1].0 {
                is_sorted = false;
            }
        }
        if is_sorted {
            let mut cost = 0;
            for i in 0..n {
                for j in i + 1..n {
                    if v[i].1 > v[j].1 {
                        cost += 1;
                    }
                }
            }
            ans.set_min(cost);
        }
    }
    if ans != i32::max_value() {
        println!("{}", ans);
    } else {
        println!("-1");
    }
}

