fn main() {
    let n = read::<usize>();
    let a = read_vec::<usize>();
    let b = read_vec::<usize>();

    let mut ans = std::i64::MAX;
    'outer: for i in 0..1 << n {
        let mut evens = vec![];
        let mut odds = vec![];
        for j in 0..n {
            let mut oe = j % 2;
            let mut num;
            if i >> j & 1 == 1 {
                oe = 1 - oe;
                num = b[j];
            } else {
                num = a[j];
            }
            if oe == 0 {
                evens.push((num, j));
            } else {
                odds.push((num, j));
            }
        }

        if odds.len() != n / 2 {
            continue 'outer;
        }

        evens.sort();
        odds.sort();
        let mut numbers = vec![];
        for i in 0..n / 2 {
            numbers.push(evens[i].0);
            numbers.push(odds[i].0);
        }
        if n % 2 == 1 {
            numbers.push(evens[n / 2].0);
        }
        for i in 0..n - 1 {
            if numbers[i] > numbers[i + 1] {
                continue 'outer;
            }
        }

        let mut indexes = vec![];
        for i in 0..n / 2 {
            indexes.push(evens[i].1);
            indexes.push(odds[i].1);
        }
        if n % 2 == 1 {
            indexes.push(evens[n / 2].1);
        }
        let temp = count_inversion(&indexes);
